globalThis.ANDE_CHUNKS["2a3d456aadb1ceb5276cf996abd58ba66c8990eca0849bc50506973f480ecc65"] = [{"id":"meituan_social:4096971848","sourceKey":"meituan_social","company":"美团","title":"小象超市-商品财务BP","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4096971848&jobShareType=1","duty":"1、财务分析：参与产品和项目的整体评估，包括商业定价、健康度评估，并建立规范的通用模型；按期出具多维度的经营分析数据及业务运营情况、行业同类产品分析报告，结合业务特点制定关键业务指标及分析体系，与业务建立双向反馈机制；\n2、财务支持：深入了解业务，与业务伙伴密切合作，建立合理有效的分析体系，给予有效建议并推进解决方案，深度支持业务决策和过程管理；\n3、财务管理：对业务方案进行风险评估，建立定期的业务和财务数据跟踪体系，对重点业务和项目进行随时跟进，定期反馈。\n4.AI智能分析赋能：推动AI工具在商品财务分析、经营洞察及业务决策支持中的落地应用，提升数据分析的广度和深度。","requirements":"1、5年及以上数据分析、经营分析、策略分析等相关工作经验；\n2、具备较强的商业洞察力，逻辑性强，能够框架性拆解并分析问题、推动问题解决；\n3、具备高阶经营分析/数据分析能力，善于从数据背后抽丝剥茧、层层下探，识别业务信号；\n4、强逻辑思维，强深潜能力，强沟通能力，有很好的提炼总结表达能力。\n5、具备AI工具应用能力，能利用大语言模型、智能BI等工具提升数据分析效率和洞察质量，有AI+零售财务实践经验者优先。","description":"部门介绍\n财务平台负责公司整体和各业务层面的财务管理工作，通过建设专业、全面、复合的财务管理能力和与业务经营的紧密结合来支持公司健康发展。目前财务平台拥有财务会计、财务报告、资金管理、税务管理、财务共享、财务系统、规划分析、财务BP和内控内审等主要工作方向。我们的目标是建设业界一流的财务管理能力和经营支持体系，为公司战略的正确落地、投入效率的持续提升、业务价值的不断增长保驾护航。欢迎加入财务平台，携手一起向未来！\n\n岗位职责\n1、财务分析：参与产品和项目的整体评估，包括商业定价、健康度评估，并建立规范的通用模型；按期出具多维度的经营分析数据及业务运营情况、行业同类产品分析报告，结合业务特点制定关键业务指标及分析体系，与业务建立双向反馈机制；\n2、财务支持：深入了解业务，与业务伙伴密切合作，建立合理有效的分析体系，给予有效建议并推进解决方案，深度支持业务决策和过程管理；\n3、财务管理：对业务方案进行风险评估，建立定期的业务和财务数据跟踪体系，对重点业务和项目进行随时跟进，定期反馈。\n4.AI智能分析赋能：推动AI工具在商品财务分析、经营洞察及业务决策支持中的落地应用，提升数据分析的广度和深度。\n\n岗位基本要求\n1、5年及以上数据分析、经营分析、策略分析等相关工作经验；\n2、具备较强的商业洞察力，逻辑性强，能够框架性拆解并分析问题、推动问题解决；\n3、具备高阶经营分析/数据分析能力，善于从数据背后抽丝剥茧、层层下探，识别业务信号；\n4、强逻辑思维，强深潜能力，强沟通能力，有很好的提炼总结表达能力。\n5、具备AI工具应用能力，能利用大语言模型、智能BI等工具提升数据分析效率和洞察质量，有AI+零售财务实践经验者优先。\n\n具备以下条件优先\n1、有制造业、零售业成本管理经验优先；\n2、参与过加工品成本归集、成本精益化管控、成本考核体系、成本线上化体系搭建项目优先。\n\n岗位亮点\n1、业务增长速度快，个人成长机会多，发挥空间大；\n2、业务核心岗位，团队氛围好，可与多部门合作，职业发展空间广阔。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4659765027","sourceKey":"meituan_social","company":"美团","title":"站外产品运营（微信生态方向）","city":"北京市/广州市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4659765027&jobShareType=1","duty":"1、负责美团在微信生态及站外核心平台的产品运营策略制定与落地，覆盖从内容触达、供给运营到用户转化的全链路，为站外增长目标负责。\n2、深入研究目标平台（微信图文/视频号/公众号、小红书等）的生态规则、流量机制与用户行为，构建适配美团业务的站外运营方法论，持续优化内容与供给的匹配效率和转化效果。\n3、主导站外运营的产品化与AI化建设——推动AIGC内容工具、供给诊断与提权系统、AI Agent等产品能力落地，实现运营全链路从人力驱动向系统化、智能化转型。\n4、基于站外高热供给信号，优化和改善美团供给组织，设计覆盖\"AI供给识别与挖掘→供给诊断分析→AI动态化提权\"的端到端产品能力。\n5、建立效果评估与数据驱动体系（转化漏斗、ROI分析、AB实验等），持续优化策略，确保站外运营有效反哺核心业务指标。","requirements":"1、本科及以上学历，3年以上产品运营/策略运营/内容运营经验，有站外增长、内容平台运营或供给策略相关经验者优先。\n2、熟悉微信生态或主流内容平台的运营逻辑，对平台规则、流量分发、用户转化有深刻理解，有操盘过规模化项目的实战案例。\n3、懂运营也懂产品。能将业务需求清晰转化为产品方案；对AI技术（LLM、AIGC）在运营场景的应用有强烈兴趣和实操经验，有从0到1搭建运营工具或AI产品经历者优先。\n4、较强的数据分析能力和跨部门协调能力，具备创业精神，结果导向。","description":"部门介绍\n美团平台为用户的基础产品体验负责，还承担了美团的用户增长、市场和品牌营销以及多条业务线的产品设计职责，建立了融合文字、图片、视频和直播等不同形式的內容生态系统，同时整合地图服务部、客户服务和体验部、企业业务部、网约车业务部等部门，致力于用科技提升美团数亿消费者、近千万商家、骑手、司机和团长的服务体验。美团平台拥有高并发、多业务的复杂场景，为技术深度优化提供了最佳实践可能。这里有简单、讲逻辑、有爱的团队，更是一块理想的实战场地，舞台广阔，欢迎你来尽情施展。\n\n岗位职责\n1、负责美团在微信生态及站外核心平台的产品运营策略制定与落地，覆盖从内容触达、供给运营到用户转化的全链路，为站外增长目标负责。\n2、深入研究目标平台（微信图文/视频号/公众号、小红书等）的生态规则、流量机制与用户行为，构建适配美团业务的站外运营方法论，持续优化内容与供给的匹配效率和转化效果。\n3、主导站外运营的产品化与AI化建设——推动AIGC内容工具、供给诊断与提权系统、AI Agent等产品能力落地，实现运营全链路从人力驱动向系统化、智能化转型。\n4、基于站外高热供给信号，优化和改善美团供给组织，设计覆盖\"AI供给识别与挖掘→供给诊断分析→AI动态化提权\"的端到端产品能力。\n5、建立效果评估与数据驱动体系（转化漏斗、ROI分析、AB实验等），持续优化策略，确保站外运营有效反哺核心业务指标。\n\n岗位基本要求\n1、本科及以上学历，3年以上产品运营/策略运营/内容运营经验，有站外增长、内容平台运营或供给策略相关经验者优先。\n2、熟悉微信生态或主流内容平台的运营逻辑，对平台规则、流量分发、用户转化有深刻理解，有操盘过规模化项目的实战案例。\n3、懂运营也懂产品。能将业务需求清晰转化为产品方案；对AI技术（LLM、AIGC）在运营场景的应用有强烈兴趣和实操经验，有从0到1搭建运营工具或AI产品经历者优先。\n4、较强的数据分析能力和跨部门协调能力，具备创业精神，结果导向。\n\n岗位亮点\n1、从0到1的建设型岗位，拥有极大自主权，拒绝\"螺丝钉\"。\n2、深度拥抱AI——用AI重构运营全链路，提升未来职业护城河。\n3、离\"交易\"最近的运营角色，直接驱动真实商业转化。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4646465341","sourceKey":"meituan_social","company":"美团","title":"营销产品经理（招商方向）","city":"北京市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4646465341&jobShareType=1","duty":"1. 负责营销招商方向AI产品的规划与设计，结合业务需求与用户场景，建设相关产品能力，最终实现招商一体化。 \n2. 协同算法、工程、运营等团队，推动AI营销产品的落地与迭代，确保产品目标达成。  \n3. 深入分析行业趋势与动态，站在业务经营视角思考问题，持续优化产品功能与用户体验。 \n4. 监控产品核心指标，基于行业洞察+数据驱动决策，提升营销能力的人效与效果。","requirements":"1. 3年以上产品经理工作经验，有AI产品或营销产品背景者优先。  \n2. 具备AI产品实践经验，熟悉AI技术体系，或主导/参与过AI驱动的营销产品创新。\n3. 优秀的沟通协调能力，能够跨团队协作并推动项目高效执行。 \n4.强目标导向与自驱力，具备优秀的韧性和团队协作精神，对业务有热情，能适应快节奏迭代。","description":"部门介绍\n美团平台为用户的基础产品体验负责，还承担了美团的用户增长、市场和品牌营销以及多条业务线的产品设计职责，建立了融合文字、图片、视频和直播等不同形式的內容生态系统，同时整合地图服务部、客户服务和体验部、企业业务部、网约车业务部等部门，致力于用科技提升美团数亿消费者、近千万商家、骑手、司机和团长的服务体验。美团平台拥有高并发、多业务的复杂场景，为技术深度优化提供了最佳实践可能。这里有简单、讲逻辑、有爱的团队，更是一块理想的实战场地，舞台广阔，欢迎你来尽情施展。\n\n岗位职责\n1. 负责营销招商方向AI产品的规划与设计，结合业务需求与用户场景，建设相关产品能力，最终实现招商一体化。 \n2. 协同算法、工程、运营等团队，推动AI营销产品的落地与迭代，确保产品目标达成。  \n3. 深入分析行业趋势与动态，站在业务经营视角思考问题，持续优化产品功能与用户体验。 \n4. 监控产品核心指标，基于行业洞察+数据驱动决策，提升营销能力的人效与效果。\n\n岗位基本要求\n1. 3年以上产品经理工作经验，有AI产品或营销产品背景者优先。  \n2. 具备AI产品实践经验，熟悉AI技术体系，或主导/参与过AI驱动的营销产品创新。\n3. 优秀的沟通协调能力，能够跨团队协作并推动项目高效执行。 \n4.强目标导向与自驱力，具备优秀的韧性和团队协作精神，对业务有热情，能适应快节奏迭代。\n\n岗位亮点\n1. 参与前沿AI技术在营销领域的创新应用，推动行业变革。  \n2. 与优秀技术团队深度合作，快速提升AI产品化能力。  \n3. 产品复杂度高，业务价值大。\n4. 团队氛围好，学习型组织，能够持续有成长。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4145786874","sourceKey":"meituan_social","company":"美团","title":"外卖柜广告销售经理（品牌客户方向）","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4145786874&jobShareType=1","duty":"通过直客或渠道合作的形式，销售美团履约设施标准媒体资源，并透过整合营销形式扩大自有媒体销售规模。\n\n1、负责开发品牌客户（快消、医药行业服务经验优先），通过挖掘客户需求并利用外部资源和营销手段提供解决方案，与客户建立长期合作关系；\n\n2、负责外部推广渠道拓展，建立销售资源池；\n\n3、负责客户账款应收管理，保障项目执行、验收与交付；\n\n4、根据业绩指标，建立销售计划并达成考核，交付结果。","requirements":"1、对行业市场现状较为了解，有品牌资源优先，能有效锁定目标客户，进行需求深挖；\n\n2 、有3-5年整合营销、品牌推广等品牌广告销售经验，能够策划或执行相关大型线上线下活动；\n\n3、对于时下事件营销和品牌热点具备较高的敏锐度，能够将创新营销思维应用到实际客户开发和项目策划当中；营销认知度强，根据自有资源可定制组合资源包（资源整合推介）；\n\n4、熟练掌握办公工具使用，具备广告营销项目基础方案撰写和策划引导能力；\n\n5、良好的沟通能力，准确获取目标客户需求商机并具备一定解决方案的制定能力；\n\n6、强烈的业绩导向，能高效推进销售全流程，具备出色的谈判和闭环能力。","description":"部门介绍\n美团配送是以科技为内核的即时物流品牌，利用高效、稳定、广阔的配送网络和前沿科技能力为各行业客户提供涵盖商流物流一体化、流量赋能、行业定制化即时配送、末端配送、前置仓等服务在内的全方位同城物流综合解决方案。\n作为科技创新和智慧物流的实践者，美团配送在人工智能（AI）、5G应用、物联网（IoT）、云计算等多维度不断探索科创蓝海，让同城物流进入数智化时代。美团配送在IoT智能设备、外卖柜、换电网络、无人配送体系等硬件设施与服务上不断推陈出新，持续优化骑手、消费者、商家体验；自研同城物流系统，通过智能分析为用户提供更便捷的生活方式，为商家提供更高效的履约服务。\n加入我们，一起把世界送到消费者手中！\n\n岗位职责\n通过直客或渠道合作的形式，销售美团履约设施标准媒体资源，并透过整合营销形式扩大自有媒体销售规模。\n\n1、负责开发品牌客户（快消、医药行业服务经验优先），通过挖掘客户需求并利用外部资源和营销手段提供解决方案，与客户建立长期合作关系；\n\n2、负责外部推广渠道拓展，建立销售资源池；\n\n3、负责客户账款应收管理，保障项目执行、验收与交付；\n\n4、根据业绩指标，建立销售计划并达成考核，交付结果。\n\n岗位基本要求\n1、对行业市场现状较为了解，有品牌资源优先，能有效锁定目标客户，进行需求深挖；\n\n2 、有3-5年整合营销、品牌推广等品牌广告销售经验，能够策划或执行相关大型线上线下活动；\n\n3、对于时下事件营销和品牌热点具备较高的敏锐度，能够将创新营销思维应用到实际客户开发和项目策划当中；营销认知度强，根据自有资源可定制组合资源包（资源整合推介）；\n\n4、熟练掌握办公工具使用，具备广告营销项目基础方案撰写和策划引导能力；\n\n5、良好的沟通能力，准确获取目标客户需求商机并具备一定解决方案的制定能力；\n\n6、强烈的业绩导向，能高效推进销售全流程，具备出色的谈判和闭环能力。\n\n具备以下条件优先\n有快消、医药等资源优先\n\n岗位亮点\n内部渠道及媒体资源丰富，整合营销机会多，可快速提升多元媒体营销视野；\n\n业务处于高速发展期，提供职业晋升和能力拓展的双重空间。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:2993924789","sourceKey":"meituan_social","company":"美团","title":"酒店选址开发经理 - 广州/深圳","city":"广州市/深圳市/南宁市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=2993924789&jobShareType=1","duty":"岗位职责\n美团酒店2023年成立“酒店品牌加盟项目”，通过存量酒店整店/整层翻新改造、毛坯改造、流量/运营扶持，提升酒店产品竞争力和收益增长。 感兴趣的话，可以聊下～\n全国均招聘（酒店开发总监、酒店开发KA）。 公司内部的新项目、未来潜力大，机会多、薪资和挑战空间大！\n职级发展空间：L6-L7\n薪资结构：底薪+绩效+项目提成\n1.主动挖掘客户需求，制定合理的开发签约方案；\n2.负责所辖区域酒店的考察评估、筛选、洽谈、签约；\n3.完成分区内工作安排，总结分享经验，完成个人计划目标；\n4.记录核心KP信息，建立客户档案，长期维护；\n5.所辖区域的行业政策，以及竞争品牌的市场政策、市场现状、销售情况的调查收集和信息的反馈;","requirements":"1.本科及以上学历；有相关经验可放宽到大专\n2.有酒店开发经验、OTA工作经验、连锁酒店加盟经验者优先；\n3.有目标感强，逻辑表达能力及思路清晰；\n4.价值观正，做正确的事而不是容易的事；\n5.能适应长期出差。","description":"部门介绍\n美团酒店旅行业务涵盖酒店、民宿、机票、火车票、旅游度假、景点门票等各类住行游品类，通过与产业上下游的深度合作，为用户提供美好的旅游旅行体验。我们积极打造AI友好型组织，使用AI等新技术提升旅游服务的供需匹配效率，更好满足用户个性化、多样化的出游需求。我们持续深耕产业链，用数字化服务助力实体商家高质量经营，探索自有品牌等供给新模式，打造健康的商家生态，保障用户服务体验。为满足用户日益增长的跨境旅行需求，我们将聚焦亚太区域，打造高品质的住宿、交通、游玩等服务矩阵。\n这里有多元的业务布局、持续的成长空间，无论是向往的远方还是眼前的工作，一路都是风景相伴。加入我们，共同为用户创造旅游旅行中的高光时刻！\n\n岗位职责\n岗位职责\n美团酒店2023年成立“酒店品牌加盟项目”，通过存量酒店整店/整层翻新改造、毛坯改造、流量/运营扶持，提升酒店产品竞争力和收益增长。 感兴趣的话，可以聊下～\n全国均招聘（酒店开发总监、酒店开发KA）。 公司内部的新项目、未来潜力大，机会多、薪资和挑战空间大！\n职级发展空间：L6-L7\n薪资结构：底薪+绩效+项目提成\n1.主动挖掘客户需求，制定合理的开发签约方案；\n2.负责所辖区域酒店的考察评估、筛选、洽谈、签约；\n3.完成分区内工作安排，总结分享经验，完成个人计划目标；\n4.记录核心KP信息，建立客户档案，长期维护；\n5.所辖区域的行业政策，以及竞争品牌的市场政策、市场现状、销售情况的调查收集和信息的反馈;\n\n岗位基本要求\n1.本科及以上学历；有相关经验可放宽到大专\n2.有酒店开发经验、OTA工作经验、连锁酒店加盟经验者优先；\n3.有目标感强，逻辑表达能力及思路清晰；\n4.价值观正，做正确的事而不是容易的事；\n5.能适应长期出差。\n\n岗位亮点\n可持续发展的新项目、志在为客户创造更多价值，空间大、机会多，欢迎自荐&推荐[庆祝][庆祝][庆祝]\n销售KA岗：主要base广州、深圳、厦门，负责省内客户开发。要求：销售经验丰富；目标感强；能高频出差；有连锁酒店开发经验优先。\n25年公司重点投入的新项目，大好机会，有换工作的抓紧时间啦！公司有成熟的培训体系和人性化的团队管理，既能赚钱，也能给你成长。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:2842443738","sourceKey":"meituan_social","company":"美团","title":"医药健康-城市直营中心-SMB","city":"北京市/呼和浩特市/沈阳市/大连市/哈尔滨市/南京市/扬州市/杭州市/宁波市/温州市/嘉兴市/绍兴市/金华市/芜湖市/福州市/潍坊市/烟台市/洛阳市/长沙市/深圳市/珠海市/汕头市/东莞市/中山市/南宁市/重庆市/贵阳市/石家庄市/上海市/武汉市/广州市/成都市/西安市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=2842443738&jobShareType=1","duty":"1）通过销售拜访，了解商户的业务现状与实际需求并结合消费者的消费动向，制定个性化营销方案，与商户谈判并达成合作；\n2）执行公司的销售策略及政策，达成业绩目标；\n3）与公司各部门配合，及时处理用户的反馈、投诉和建议，提高用户满意度；\n4）归档和更新所有目标商户拜访、协议、服务条款等有关的文件和数据，确保信息在数据库中得到正确的维护。","requirements":"1）通过销售拜访，了解商户的业务现状与实际需求并结合消费者的消费动向，制定个性化营销方案，与商户谈判并达成合作；\n2）执行公司的销售策略及政策，达成业绩目标；\n3）与公司各部门配合，及时处理用户的反馈、投诉和建议，提高用户满意度；\n4）归档和更新所有目标商户拜访、协议、服务条款等有关的文件和数据，确保信息在数据库中得到正确的维护。","description":"部门介绍\n美团医药健康事业部是美团核心本地商业板块下专注健康领域的业务部门，涵盖美团买药、美团医美和美团医疗三大业务。自创立以来，美团医药健康致力于为用户提供全健康周期产品及服务，满足人民群众多层次多元化医疗健康需求，现已覆盖购药到家、居家检测、问诊挂号、医保支付、求医寻院、医疗美容等核心场景。此外，美团医药健康还为商户提供数字化转型创新解决方案，打造贯穿上游的联动机制，长期参与共建更透明、更可持续的医药健康产业生态圈，目前业务已覆盖25万家药店，收录27万家医疗机构。未来，美团医药康将协同更多行业伙伴，帮助大家变得更健康、更美丽、更养生。\n\n岗位职责\n1）通过销售拜访，了解商户的业务现状与实际需求并结合消费者的消费动向，制定个性化营销方案，与商户谈判并达成合作；\n2）执行公司的销售策略及政策，达成业绩目标；\n3）与公司各部门配合，及时处理用户的反馈、投诉和建议，提高用户满意度；\n4）归档和更新所有目标商户拜访、协议、服务条款等有关的文件和数据，确保信息在数据库中得到正确的维护。\n\n岗位基本要求\n1）通过销售拜访，了解商户的业务现状与实际需求并结合消费者的消费动向，制定个性化营销方案，与商户谈判并达成合作；\n2）执行公司的销售策略及政策，达成业绩目标；\n3）与公司各部门配合，及时处理用户的反馈、投诉和建议，提高用户满意度；\n4）归档和更新所有目标商户拜访、协议、服务条款等有关的文件和数据，确保信息在数据库中得到正确的维护。\n\n岗位亮点\n岗位对人整体综合发展帮助大，行业发展潜力大，未来发展空间大，成长机会多","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4486395891","sourceKey":"meituan_social","company":"美团","title":"长沙生鲜仓收退库维主管","city":"长沙市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4486395891&jobShareType=1","duty":"1. 负责长沙生鲜仓的收退库日常运营管理工作，确保流程高效、准确。  \n2. 管理并指导20人团队，包括排班、培训、绩效考核及现场协调。  \n3. 监控库存数据，及时处理异常情况，保障库存准确性与商品质量。  \n4. 优化收退库操作流程，提升作业效率，降低损耗率。  \n5. 与采购、配送、质检等部门协作，确保生鲜商品流转顺畅。","requirements":"1. 大学专科及以上学历，物流、仓储管理或相关专业优先。  \n2. 具备1年以上仓储或物流相关工作经验，有生鲜行业经验者更佳。  \n3. 具备基础团队管理经验，能有效沟通并协调现场工作。  \n4. 熟悉仓储管理系统操作，具备较强的数据敏感度和问题解决能力。  \n5. 能适应生鲜仓储环境，具备较强的责任心和心里承受能力。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1. 负责长沙生鲜仓的收退库日常运营管理工作，确保流程高效、准确。  \n2. 管理并指导20人团队，包括排班、培训、绩效考核及现场协调。  \n3. 监控库存数据，及时处理异常情况，保障库存准确性与商品质量。  \n4. 优化收退库操作流程，提升作业效率，降低损耗率。  \n5. 与采购、配送、质检等部门协作，确保生鲜商品流转顺畅。\n\n岗位基本要求\n1. 大学专科及以上学历，物流、仓储管理或相关专业优先。  \n2. 具备1年以上仓储或物流相关工作经验，有生鲜行业经验者更佳。  \n3. 具备基础团队管理经验，能有效沟通并协调现场工作。  \n4. 熟悉仓储管理系统操作，具备较强的数据敏感度和问题解决能力。  \n5. 能适应生鲜仓储环境，具备较强的责任心和心里承受能力。\n\n岗位亮点\n1. 提供完善的培训体系和职业发展通道。  \n2. 团队氛围积极，注重员工成长与关怀。  \n3. 工作地点位于长沙，交通便利，生活配套齐全。  \n4. 生鲜行业快速发展，岗位成长空间大。  \n5. 享有竞争力的薪酬福利及绩效奖励机制。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4258187656","sourceKey":"meituan_social","company":"美团","title":"多模态测试开发工程师","city":"北京市/成都市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4258187656&jobShareType=1","duty":"1. 参与多模态相关产品（语音、视觉方向）的功能测试与质量保障，包括 Web 页面与客户端（移动端 / PC 端）等。\n2. 根据产品需求与设计文档，设计测试用例，执行功能测试、兼容性测试、接口测试等，及时发现并定位问题。\n3. 参与语音识别、语音交互、图像识别、图像生成等多模态场景的专项测试，关注模型效果及用户体验。\n4. 跟踪缺陷生命周期，推动问题及时修复并回归验证，输出测试报告。\n5. 能够使用简单脚本或工具进行部分测试场景的自动化或半自动化，提高测试效率。\n6. 与产品、研发、算法等多团队协作，参与需求评审和版本评审，对产品质量和可测试性提出合理建议。","requirements":"1. 本科及以上学历，计算机、软件工程、信息技术等相关专业优先。\n2. 熟悉基本的软件测试流程和方法，能够编写测试用例并执行测试，掌握常见缺陷管理工具。\n3. 对语音识别、语音交互、图像处理、视觉识别等多模态产品有一定了解或浓厚兴趣，有相关测试经验者优先。\n4. 具备一定编码能力，至少熟悉一种编程或脚本语言（如 Python / JavaScript / Java 等），能编写简单脚本或小工具辅助测试。\n5. 了解 AI 技术，具备测试 AI Agent 的实践经验。\n6. 具备多模态工程链路可靠性、性能测试的经验优先。\n7. 具备多模态大模型评测经验优先。\n7. 具备良好的问题定位与分析能力，逻辑清晰，责任心强，细致认真，能承受一定工作压力。","description":"部门介绍\n基础研发平台是美团的核心技术平台，立足于“零售+科技”的战略定位，通过打造人工智能、大数据、云计算、安全等核心技术能力，以及研发效能平台、企业应用平台等公共服务，为业务提供稳定安全、扩展易用、技术领先的平台技术和产品服务。\n在这里，我们会参与到最前沿的技术研发和探索；能够接触超规模集群、海量数据，挑战高复杂业务场景，有机会与业界一流的工程师一起并肩前行。\n在这里，我们有超强的技术氛围，持续向社区贡献业界实践，加速行业技术发展；我们有完善的互联网学习生态圈，重视底层逻辑和方法论，助力职业生涯的非线性成长。\n真诚地邀请你，和我们一起驱动技术发展，创造行业价值。\n\n岗位职责\n1. 参与多模态相关产品（语音、视觉方向）的功能测试与质量保障，包括 Web 页面与客户端（移动端 / PC 端）等。\n2. 根据产品需求与设计文档，设计测试用例，执行功能测试、兼容性测试、接口测试等，及时发现并定位问题。\n3. 参与语音识别、语音交互、图像识别、图像生成等多模态场景的专项测试，关注模型效果及用户体验。\n4. 跟踪缺陷生命周期，推动问题及时修复并回归验证，输出测试报告。\n5. 能够使用简单脚本或工具进行部分测试场景的自动化或半自动化，提高测试效率。\n6. 与产品、研发、算法等多团队协作，参与需求评审和版本评审，对产品质量和可测试性提出合理建议。\n\n岗位基本要求\n1. 本科及以上学历，计算机、软件工程、信息技术等相关专业优先。\n2. 熟悉基本的软件测试流程和方法，能够编写测试用例并执行测试，掌握常见缺陷管理工具。\n3. 对语音识别、语音交互、图像处理、视觉识别等多模态产品有一定了解或浓厚兴趣，有相关测试经验者优先。\n4. 具备一定编码能力，至少熟悉一种编程或脚本语言（如 Python / JavaScript / Java 等），能编写简单脚本或小工具辅助测试。\n5. 了解 AI 技术，具备测试 AI Agent 的实践经验。\n6. 具备多模态工程链路可靠性、性能测试的经验优先。\n7. 具备多模态大模型评测经验优先。\n7. 具备良好的问题定位与分析能力，逻辑清晰，责任心强，细致认真，能承受一定工作压力。\n\n岗位亮点\n接触前沿的多模态大模型技术、使用前沿的大模型及工具，一起探索多模态大模型场景下的Agent质量保障新范式","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4654497616","sourceKey":"meituan_social","company":"美团","title":"城市经理","city":"广州市/深圳市/惠州市/东莞市/中山市/佛山市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4654497616&jobShareType=1","duty":"1. 负责组建高质量的销售、采购团队，对团队梯队搭建、人才培养、人员管理负责；\n2. 负责城市目标、策略制定及分解、落地负责，确保在正确的策略下完成业务目标，同时沉淀方法论；\n3. 带领团队帮助客户更好进行服务规划、完成服务目标、提升服务满意度，从而提升公司品牌影响力；\n4. 协调总部相关部门带领采销仓配出色完成业务目标；\n5.从运营的各个环的运营中发现问题、提出建议、建立流程持续提高城市团队运营效率。","requirements":"1.大专以上毕业，5年以上工作经验；\n2.有大规模直销管理经验则优先考虑；\n3.有食材经验值优先考虑；\n4.超强的使命感和执行力、不屈不挠的斗志、能吃苦；","description":"部门介绍\n快驴进货是美团旗下的餐饮供应链平台，帮助餐饮商户以更低成本、更高效率来获取安全可靠的食材供应，让餐饮采购更简单。快驴进货同步发展“自营+平台”的业务模式，在采购环节一方面向上游供应商直采大宗商品，另一方面引入各地批发商，助力平台伙伴共同发展；在销售环节既有自建团队进行市场、客户拓展，又帮助各地批发商拓展业务；同时自建仓储管理系统、配送网络与团队，为客户提供优质履约服务。\n截至2022年，快驴进货布局了全国41个城市，为百万家商户提供“全、省、稳、好”的餐饮供应链服务。我们拥有3000+品牌食材、超5万SKU商品、超28万商品资质，并提供源头严审核、食品安全严把关、24小时无忧售后的全面保障，实现手机下单、送货上门的高效采购模式，帮百万商家节省了采购时间与成本，助力平台伙伴共同发展，在万亿市场共享机遇。\n在这里，你将收获完善的员工发展机制及学习体系，与各界专家一起深度参与餐饮供应链业务的发展。欢迎优秀的你加入美团快驴进货，与我们一起成长，一起更好！\n\n岗位职责\n1. 负责组建高质量的销售、采购团队，对团队梯队搭建、人才培养、人员管理负责；\n2. 负责城市目标、策略制定及分解、落地负责，确保在正确的策略下完成业务目标，同时沉淀方法论；\n3. 带领团队帮助客户更好进行服务规划、完成服务目标、提升服务满意度，从而提升公司品牌影响力；\n4. 协调总部相关部门带领采销仓配出色完成业务目标；\n5.从运营的各个环的运营中发现问题、提出建议、建立流程持续提高城市团队运营效率。\n\n岗位基本要求\n1.大专以上毕业，5年以上工作经验；\n2.有大规模直销管理经验则优先考虑；\n3.有食材经验值优先考虑；\n4.超强的使命感和执行力、不屈不挠的斗志、能吃苦；\n\n具备以下条件优先\n有零售行业优先\n\n岗位亮点\n行业发展增长潜力大，发展空间大；\n有机会不断提升个人职业素养和管理能力；","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4375681827","sourceKey":"meituan_social","company":"美团","title":"KSA-达曼运输调度主管","city":"达曼","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4375681827&jobShareType=1","duty":"1. 负责日常运输任务的调度安排，确保车辆和司机资源合理配置。  \n2. 跟踪运输进度，及时处理运输过程中的异常情况，保障货物准时送达。  \n3. 与仓库、客户及承运方保持沟通，协调装货、卸货及交接事宜。  \n4. 优化运输路线和配送计划，提升运输效率并控制成本。  \n5. 记录并分析运输数据，定期提交运营报告。","requirements":"1. 大学本科及以上学历，物流、运输管理或相关专业优先。  \n2. 具备5年以上运输调度或相关岗位工作经验。  \n3. 熟悉物流运输流程及调度系统操作。  \n4. 具备良好的沟通协调能力和应急处理能力。  \n5. 能适应一定的工作压力，具备较强的责任心和执行力。","description":"部门介绍\n美团的使命是“帮大家吃得更好，生活更好”，公司聚焦“零售 + 科技”战略，和广大商户与各类合作伙伴一起，努力为消费者提供品质生活，推动商品零售和服务零售在需求侧和供给侧的数字化转型。\n2018年9月20日，美团正式在港交所挂牌上市。美团将始终坚持以客户为中心，不断加大在科技研发方面的投入，更好承担社会责任，更多创造社会价值，与广大合作伙伴一起发展共赢。\n\n岗位职责\n1. 负责日常运输任务的调度安排，确保车辆和司机资源合理配置。  \n2. 跟踪运输进度，及时处理运输过程中的异常情况，保障货物准时送达。  \n3. 与仓库、客户及承运方保持沟通，协调装货、卸货及交接事宜。  \n4. 优化运输路线和配送计划，提升运输效率并控制成本。  \n5. 记录并分析运输数据，定期提交运营报告。\n\n岗位基本要求\n1. 大学本科及以上学历，物流、运输管理或相关专业优先。  \n2. 具备5年以上运输调度或相关岗位工作经验。  \n3. 熟悉物流运输流程及调度系统操作。  \n4. 具备良好的沟通协调能力和应急处理能力。  \n5. 能适应一定的工作压力，具备较强的责任心和执行力。\n\n岗位亮点\n1. 在快速发展的物流行业中积累核心运营经验。  \n2. 提供完善的培训体系和职业发展通道。  \n3. 工作地点位于达曼，享受具有竞争力的薪酬福利。  \n4. 团队协作氛围良好，支持员工成长与创新。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4616097894","sourceKey":"meituan_social","company":"美团","title":"私域用户运营","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4616097894&jobShareType=1","duty":"负责美团私域流量增长，通过精细化的用户运营策略，实现核心增长目标的达成，负责私域增长AI工作流建设。\n1、主导私域增长与用户运营的AI工作流建设，将AI能力嵌入运营全链路，包括但不限于AI驱动的用户分层经营策略、私域资产管理、私域用户运营链路，打造可规模化运行的AI增长工作流体系；持续探索ai生态下的增长机会。\n2、设计并验证高质量的私域用户增长路径，围绕用户新增、召回激活、活跃提升等关键场景，通过精细化用户分层与需求匹配策略，实现高价值用户的精准获取与高效转化，持续优化增长质量与单位获客效率；\n3、联合业务挖掘生活服务场景下的私域增长机会，设计跨业务线的联合增长方案，推动私域流量与业务场景的深度融合，实现共同增长\n4、协同算法、AI平台等团队，推动私域AI运营工具与系统能力的迭代升级，沉淀\"AI+私域增长\"的方法论与运营SOP，形成可复用、可推广的增长基建。","requirements":"1、本科及以上学历，3年以上互联网用户增长、私域运营或用户运营经验，有生活服务行业经验者优先；\n2、对私域流量经营有系统认知，熟悉微信生态（企微、社群、公众号、小程序）的运营逻辑与增长玩法，有私域流量池从0到1搭建或从1到N增长的实际操盘经验；\n3、对高质量用户增长有清晰方法论，能从用户价值视角定义增长质量，有高价值用户获取、流失用户激活、用户生命周期价值提升等实战经验，做过渠道增长与增长策略者优先；\n4、对AI赋能运营有强烈兴趣和实践认知，了解大模型（LLM）、智能体（Agent）、自动化工作流等AI技术在运营场景中的应用方向，有AI工具落地运营场景经验者优先；\n5、具备较强的数据分析能力，能熟练运用AB测试、漏斗分析、归因分析等方法指导策略优化，有SQL基础者优先；\n6、逻辑严谨，数据驱动，有较强的提出问题、分析问题、解决问题的能力，对增长和AI同时充满热情，能在复杂业务场景中找到增长破局点。","description":"部门介绍\n美团平台为用户的基础产品体验负责，还承担了美团的用户增长、市场和品牌营销以及多条业务线的产品设计职责，建立了融合文字、图片、视频和直播等不同形式的內容生态系统，同时整合地图服务部、客户服务和体验部、企业业务部、网约车业务部等部门，致力于用科技提升美团数亿消费者、近千万商家、骑手、司机和团长的服务体验。美团平台拥有高并发、多业务的复杂场景，为技术深度优化提供了最佳实践可能。这里有简单、讲逻辑、有爱的团队，更是一块理想的实战场地，舞台广阔，欢迎你来尽情施展。\n\n岗位职责\n负责美团私域流量增长，通过精细化的用户运营策略，实现核心增长目标的达成，负责私域增长AI工作流建设。\n1、主导私域增长与用户运营的AI工作流建设，将AI能力嵌入运营全链路，包括但不限于AI驱动的用户分层经营策略、私域资产管理、私域用户运营链路，打造可规模化运行的AI增长工作流体系；持续探索ai生态下的增长机会。\n2、设计并验证高质量的私域用户增长路径，围绕用户新增、召回激活、活跃提升等关键场景，通过精细化用户分层与需求匹配策略，实现高价值用户的精准获取与高效转化，持续优化增长质量与单位获客效率；\n3、联合业务挖掘生活服务场景下的私域增长机会，设计跨业务线的联合增长方案，推动私域流量与业务场景的深度融合，实现共同增长\n4、协同算法、AI平台等团队，推动私域AI运营工具与系统能力的迭代升级，沉淀\"AI+私域增长\"的方法论与运营SOP，形成可复用、可推广的增长基建。\n\n岗位基本要求\n1、本科及以上学历，3年以上互联网用户增长、私域运营或用户运营经验，有生活服务行业经验者优先；\n2、对私域流量经营有系统认知，熟悉微信生态（企微、社群、公众号、小程序）的运营逻辑与增长玩法，有私域流量池从0到1搭建或从1到N增长的实际操盘经验；\n3、对高质量用户增长有清晰方法论，能从用户价值视角定义增长质量，有高价值用户获取、流失用户激活、用户生命周期价值提升等实战经验，做过渠道增长与增长策略者优先；\n4、对AI赋能运营有强烈兴趣和实践认知，了解大模型（LLM）、智能体（Agent）、自动化工作流等AI技术在运营场景中的应用方向，有AI工具落地运营场景经验者优先；\n5、具备较强的数据分析能力，能熟练运用AB测试、漏斗分析、归因分析等方法指导策略优化，有SQL基础者优先；\n6、逻辑严谨，数据驱动，有较强的提出问题、分析问题、解决问题的能力，对增长和AI同时充满热情，能在复杂业务场景中找到增长破局点。\n\n具备以下条件优先\n1、有大型互联网平台私域增长操盘经验，操盘私域用户规模百万级以上，且有可量化的高质量用户增长成果者优先；\n2、有AI工作流搭建经验，使用过主流AI工具（如Coze、Dify、FastGPT等Agent平台）落地场景者优先；\n\n岗位亮点\n1、参与行业大规模私域经营转型，沉淀高质量增长经验\n2、验证AI能力在私域全链路中应用与提效，同时具备增长与AI实践经验\n3、在渠道视角理解各业务增长逻辑，与外部AI平台交流增长合作机会","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4664804077","sourceKey":"meituan_social","company":"美团","title":"产品经理（非餐特色POI方向）","city":"上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4664804077&jobShareType=1","duty":"1、负责点评非餐特色POI的点位建设策略，推动优质点位的发现、挖掘与结构化覆盖，提升平台POI供给质量与丰富度\n2、制定UGC内容供给策略，通过激励体系设计驱动用户产出优质图文/打卡内容，提升内容生态的活跃度与可分发规模\n3、与算法团队深度协作，推进内容理解与挖掘能力建设，实现从非结构化内容中自动提取POI信息、标签及质量信号\n4、负责POI消费侧产品优化，结合用户场景提升POI详情页、推荐分发等环节的消费体验与转化效率，，理解内容分发机制与排序策略，能从供给视角反向优化分发效果","requirements":"1、本科及以上学历，3年以上互联网产品经理经验，有C端产品背景者优先\n2、具备较强的策略思维和数据分析能力，能独立完成从问题定义到方案落地的完整闭环\n3、有与算法/NLP/CV团队协作经验者优先，能理解技术方案并转化为产品需求","description":"部门介绍\n大众点评作为国内重要的本地生活消费决策参考平台，多年来深耕本地生活消费领域，深受广大用户的信任和喜爱。我们的业务覆盖了吃喝玩乐游购娱等生活场景，通过极具辨识度和公信力的”星级“和”评价“产品，为数亿用户提供了全面、可信的消费决策依据。为更好满足用户探索城市的需求，大众点评在原有星级和评价的基础上，以信息流产品形式，助力用户发现更多好去处。大量优秀年轻同学的加入，为我们的团队注入了澎湃活力。我们相信，真实的生活是不可替代的，真实的感受是值得记录的，真实的美好是要被看到的。希望优秀的你能和我们一起，帮助广大用户在大众点评上发现更多好去处，找到属于自己的人间烟火气，共创美好生活。\n\n岗位职责\n1、负责点评非餐特色POI的点位建设策略，推动优质点位的发现、挖掘与结构化覆盖，提升平台POI供给质量与丰富度\n2、制定UGC内容供给策略，通过激励体系设计驱动用户产出优质图文/打卡内容，提升内容生态的活跃度与可分发规模\n3、与算法团队深度协作，推进内容理解与挖掘能力建设，实现从非结构化内容中自动提取POI信息、标签及质量信号\n4、负责POI消费侧产品优化，结合用户场景提升POI详情页、推荐分发等环节的消费体验与转化效率，，理解内容分发机制与排序策略，能从供给视角反向优化分发效果\n\n岗位基本要求\n1、本科及以上学历，3年以上互联网产品经理经验，有C端产品背景者优先\n2、具备较强的策略思维和数据分析能力，能独立完成从问题定义到方案落地的完整闭环\n3、有与算法/NLP/CV团队协作经验者优先，能理解技术方案并转化为产品需求\n\n具备以下条件优先\n1、有UGC/内容社区/激励体系相关经验者优先，熟悉用户行为驱动和增长方法论\n2、对本地生活、POI、LBS等领域有认知或兴趣者加分\n3、善于利用AI工具提升个人和团队工作效率，能主动探索新技术在业务场景中的应用可能性\n\n岗位亮点\n1、深度参与点评核心供给体系建设，参与业务早期探索与建设\n2、团队氛围务实高效，重视个人成长与发挥空间","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4668871132","sourceKey":"meituan_social","company":"美团","title":"产品运营（非餐特色POI方向）","city":"上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4668871132&jobShareType=1","duty":"1、负责非餐特色POI的点位建设运营，制定供给策略对供给规模与质量负责\n2、设计UGC/PUGC内容激励体系，运营核心创作者群体，驱动优质POI与内容持续产出与规模化供给\n3、制定站内外心智传播策略，操盘主题活动与IP项目，对POI的WAU、DAU等消费目标负责\n4、关注内容在搜索与信息流场景中的分发效果，结合供给与用户场景推动POI在各渠道的消费增长","requirements":"1、本科及以上学历，有C端内容社区或本地生活平台经验者优先\n2、有较强的数据能力，熟练SQL，能基于熟练基于数据做业务决策\n3、跨团队协调能力强，能推动产品、算法、市场等多方协同","description":"部门介绍\n大众点评作为国内重要的本地生活消费决策参考平台，多年来深耕本地生活消费领域，深受广大用户的信任和喜爱。我们的业务覆盖了吃喝玩乐游购娱等生活场景，通过极具辨识度和公信力的”星级“和”评价“产品，为数亿用户提供了全面、可信的消费决策依据。为更好满足用户探索城市的需求，大众点评在原有星级和评价的基础上，以信息流产品形式，助力用户发现更多好去处。大量优秀年轻同学的加入，为我们的团队注入了澎湃活力。我们相信，真实的生活是不可替代的，真实的感受是值得记录的，真实的美好是要被看到的。希望优秀的你能和我们一起，帮助广大用户在大众点评上发现更多好去处，找到属于自己的人间烟火气，共创美好生活。\n\n岗位职责\n1、负责非餐特色POI的点位建设运营，制定供给策略对供给规模与质量负责\n2、设计UGC/PUGC内容激励体系，运营核心创作者群体，驱动优质POI与内容持续产出与规模化供给\n3、制定站内外心智传播策略，操盘主题活动与IP项目，对POI的WAU、DAU等消费目标负责\n4、关注内容在搜索与信息流场景中的分发效果，结合供给与用户场景推动POI在各渠道的消费增长\n\n岗位基本要求\n1、本科及以上学历，有C端内容社区或本地生活平台经验者优先\n2、有较强的数据能力，熟练SQL，能基于熟练基于数据做业务决策\n3、跨团队协调能力强，能推动产品、算法、市场等多方协同\n\n具备以下条件优先\n1、对AI/大模型有应用意识，探索AI能力在运营链路中的规模化应用，推动内容生成、数据分析、运营流程的智能化提效\n2、有活动操盘与品牌传播经验，具备站内外资源整合能力\n3、有内容供给或运营体系从0到1搭建经验，能独立闭环并对结果负责\n4、深度理解UGC生态与创作者运营，有激励体系设计与规模化落地经验\n\n岗位亮点\n1、深度参与点评核心供给体系建设，参与业务早期探索与建设\n2、团队氛围务实高效，重视个人成长与发挥空间","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4669893319","sourceKey":"meituan_social","company":"美团","title":"商业分析师","city":"北京市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4669893319&jobShareType=1","duty":"1. 负责医美和美容行业的市场研究与商业分析，识别行业趋势、竞争格局及用户行为变化。  \n2. 支持业务部门制定战略决策，通过数据分析提供可落地的业务优化建议。  \n3. 搭建并维护关键业务指标体系，监控核心数据表现，及时发现异常并推动问题解决。  \n4. 协同运营、销售团队，开展专项分析项目，提升业务增长效率与用户体验。","requirements":"1. 大学本科及以上学历，统计学、经济学、工商管理或相关专业优先。  \n2. 具备4年以上商业分析或行业研究经验，有医美、美容或消费服务行业背景者优先。  \n3. 熟练使用SQL，熟悉Python或R等分析工具者优先。  \n4. 具备较强的逻辑思维、数据敏感度和跨团队沟通能力。","description":"部门介绍\n美团医药健康事业部是美团核心本地商业板块下专注健康领域的业务部门，涵盖美团买药、美团医美和美团医疗三大业务。自创立以来，美团医药健康致力于为用户提供全健康周期产品及服务，满足人民群众多层次多元化医疗健康需求，现已覆盖购药到家、居家检测、问诊挂号、医保支付、求医寻院、医疗美容等核心场景。此外，美团医药健康还为商户提供数字化转型创新解决方案，打造贯穿上游的联动机制，长期参与共建更透明、更可持续的医药健康产业生态圈，目前业务已覆盖25万家药店，收录27万家医疗机构。未来，美团医药康将协同更多行业伙伴，帮助大家变得更健康、更美丽、更养生。\n\n岗位职责\n1. 负责医美和美容行业的市场研究与商业分析，识别行业趋势、竞争格局及用户行为变化。  \n2. 支持业务部门制定战略决策，通过数据分析提供可落地的业务优化建议。  \n3. 搭建并维护关键业务指标体系，监控核心数据表现，及时发现异常并推动问题解决。  \n4. 协同运营、销售团队，开展专项分析项目，提升业务增长效率与用户体验。\n\n岗位基本要求\n1. 大学本科及以上学历，统计学、经济学、工商管理或相关专业优先。  \n2. 具备4年以上商业分析或行业研究经验，有医美、美容或消费服务行业背景者优先。  \n3. 熟练使用SQL，熟悉Python或R等分析工具者优先。  \n4. 具备较强的逻辑思维、数据敏感度和跨团队沟通能力。\n\n岗位亮点\n1. 深入参与高增长潜力的医美与美容行业，接触前沿业务模式。  \n2. 与资深团队共事，获得专业成长与职业发展支持。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4651725225","sourceKey":"meituan_social","company":"美团","title":"无人车业务部-车身结构SQE","city":"上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4651725225&jobShareType=1","duty":"1、前期供应商定点评估​\n\n参与新供应商的开发与准入审核，从质量体系、设备和工艺能力、过程质量保证能力等方面综合评估，输出定点建议\n\n2、研发阶段DV/PV评审与推进​\n\n在产品设计和生产验证阶段，参与样件评审，识别设计风险与工艺可行性；跟踪 DV/PV 测试进度，推动问题整改\n\n3、工/模/夹/检具开发管控及验收​\n\n监督供应商工/模/夹/检具开发计划，定期跟进里程碑节点；参与工/模/夹/检具的验收，确认符合产品图纸及工艺要求\n\n4、供应商产线开发与生产达成​\n\n协助供应商优化产线布局、工艺流程及质量控制点，确保良率达标；监控供应商产能计划，协调资源解决生产瓶颈\n\n5、量产阶段质量管控​\n\n制定并更新来料检验标准，开展量产审核及签批；定期对供应商进行过程审核，推动过程质量持续改善\n\n6、生产零部件质量问题处置​\n\n处理生产线反馈的来料异常，主导问题分析，督促供应商完成整改，对重大质量问题实施驻厂辅导或升级管理\n\n7、零件售后质量问题推进​\n\n处置售后市场反馈的零部件不良，联合供应商开展失效分析，跟踪改进措施的落地效果，降低 PPM 及保修成本\n\n8、借助AI工具提升质量管理效率\n\n有意愿学习并推广AI工具以提升个人及团队工作效率，如运用AI工具辅助FMEA评审、控制计划优化，缩短文档编制时间；如利用AI进行质量数据的自动清洗与分析，快速识别异常趋势，为决策提供数据支撑。","requirements":"1、学历与专业​\n\n本科及以上学历，车辆工程、机械设计制造及自动化、材料成型与控制工程、焊接技术与工程等相关理工科专业优先\n\n2、工作经验​\n\n①5年以上​SQE或相关质量工作经验，其中至少 3 年涉及车身结构件、货箱、外饰件的质量管理或供应商开发经验\n\n②有商用车/乘用车主机厂或一级供应商（车身/外饰方向）工作经验优先，熟悉冲压、焊接、注塑、涂胶等工艺更佳\n\n3、专业技能​\n\n熟练掌握 APQP、PPAP、FMEA、MSA、SPC 五大工具；精通 8D、QC七大手法、PDCA 等质量问题解决工具。\n\n4、车身结构能力要求：\n\n①熟悉车身货箱及外饰常见制造工艺：钣金冲压、焊接(CO₂气体保护焊/电阻点焊/激光焊)、铆接（拉铆/压铆）、拼板涂胶、涂装（阴极电泳+喷粉/喷漆）、注塑成型等工艺\n\n②识别并管控车身货箱/外饰关键特性：如货箱底板/侧板的平面度、门框对角线公差、骨架焊缝熔深与强度、密封条压缩负荷与回弹性、涂胶尺寸及开放和固化时间、涂层厚度与附着力、塑料件冲击强度/热变形温度\n\n③了解底车身货箱/外饰常用的试验标准：如 QC/T 566《货车货箱技术条件》、GB/T 17350《专用汽车和专用半挂车术语》、淋雨试验（IPX3/IPX4）、盐雾试验（≥480h）、氙灯老化试验（≥1000h）、碎石冲击试验、扭转疲劳试验\n\n④能看懂机械图纸及公差标注，熟悉三坐标/投影仪/激光扫描仪/金相实验仪/涂层测厚仪/附着力测试仪等设备检测过程\n\n5、AI技能要求\n\n具备基本的AI工具应用能力：能够使用主流AI助手辅助完成质量文档撰写、数据汇总与初步分析；了解AI在质量管理中的典型场景（如指标统计、预测性质量分析）；有意愿主动学习和推广新的AI工具\n\n6、软性素质​\n\n①逻辑清晰，善于数据分析与报告呈现；\n\n②较强的结果导向意识，适应短期出差（供应商现场）\n\n③优秀的沟通协调能力，能独立推动供应商及内部跨部门协作。","description":"部门介绍\n无人车业务部成立于2016年，旨在用无人驾驶技术提升物流配送的效率和体验。美团无人车以自研L4级自动驾驶软硬件技术为核心，与美团即时零售业务结合，形成满足公开道路、社区、工业园区等室外全场景下的无人配送整体解决方案。自2020年起，无人车已在北京、深圳等多地进入常态化试运营阶段，在城市复杂场景下提供针对餐饮外卖、生鲜食杂等货物的即时配送服务。2025年，美团无人车又踏上了同城货运的新探索，并在2026年持续扩大运营范围和车队数量，为更多城市带来智能配送服务。\n欢迎加入美团无人车团队，与我们一起用科技推动即时零售再升级！\n\n岗位职责\n1、前期供应商定点评估​\n\n参与新供应商的开发与准入审核，从质量体系、设备和工艺能力、过程质量保证能力等方面综合评估，输出定点建议\n\n2、研发阶段DV/PV评审与推进​\n\n在产品设计和生产验证阶段，参与样件评审，识别设计风险与工艺可行性；跟踪 DV/PV 测试进度，推动问题整改\n\n3、工/模/夹/检具开发管控及验收​\n\n监督供应商工/模/夹/检具开发计划，定期跟进里程碑节点；参与工/模/夹/检具的验收，确认符合产品图纸及工艺要求\n\n4、供应商产线开发与生产达成​\n\n协助供应商优化产线布局、工艺流程及质量控制点，确保良率达标；监控供应商产能计划，协调资源解决生产瓶颈\n\n5、量产阶段质量管控​\n\n制定并更新来料检验标准，开展量产审核及签批；定期对供应商进行过程审核，推动过程质量持续改善\n\n6、生产零部件质量问题处置​\n\n处理生产线反馈的来料异常，主导问题分析，督促供应商完成整改，对重大质量问题实施驻厂辅导或升级管理\n\n7、零件售后质量问题推进​\n\n处置售后市场反馈的零部件不良，联合供应商开展失效分析，跟踪改进措施的落地效果，降低 PPM 及保修成本\n\n8、借助AI工具提升质量管理效率\n\n有意愿学习并推广AI工具以提升个人及团队工作效率，如运用AI工具辅助FMEA评审、控制计划优化，缩短文档编制时间；如利用AI进行质量数据的自动清洗与分析，快速识别异常趋势，为决策提供数据支撑。\n\n岗位基本要求\n1、学历与专业​\n\n本科及以上学历，车辆工程、机械设计制造及自动化、材料成型与控制工程、焊接技术与工程等相关理工科专业优先\n\n2、工作经验​\n\n①5年以上​SQE或相关质量工作经验，其中至少 3 年涉及车身结构件、货箱、外饰件的质量管理或供应商开发经验\n\n②有商用车/乘用车主机厂或一级供应商（车身/外饰方向）工作经验优先，熟悉冲压、焊接、注塑、涂胶等工艺更佳\n\n3、专业技能​\n\n熟练掌握 APQP、PPAP、FMEA、MSA、SPC 五大工具；精通 8D、QC七大手法、PDCA 等质量问题解决工具。\n\n4、车身结构能力要求：\n\n①熟悉车身货箱及外饰常见制造工艺：钣金冲压、焊接(CO₂气体保护焊/电阻点焊/激光焊)、铆接（拉铆/压铆）、拼板涂胶、涂装（阴极电泳+喷粉/喷漆）、注塑成型等工艺\n\n②识别并管控车身货箱/外饰关键特性：如货箱底板/侧板的平面度、门框对角线公差、骨架焊缝熔深与强度、密封条压缩负荷与回弹性、涂胶尺寸及开放和固化时间、涂层厚度与附着力、塑料件冲击强度/热变形温度\n\n③了解底车身货箱/外饰常用的试验标准：如 QC/T 566《货车货箱技术条件》、GB/T 17350《专用汽车和专用半挂车术语》、淋雨试验（IPX3/IPX4）、盐雾试验（≥480h）、氙灯老化试验（≥1000h）、碎石冲击试验、扭转疲劳试验\n\n④能看懂机械图纸及公差标注，熟悉三坐标/投影仪/激光扫描仪/金相实验仪/涂层测厚仪/附着力测试仪等设备检测过程\n\n5、AI技能要求\n\n具备基本的AI工具应用能力：能够使用主流AI助手辅助完成质量文档撰写、数据汇总与初步分析；了解AI在质量管理中的典型场景（如指标统计、预测性质量分析）；有意愿主动学习和推广新的AI工具\n\n6、软性素质​\n\n①逻辑清晰，善于数据分析与报告呈现；\n\n②较强的结果导向意识，适应短期出差（供应商现场）\n\n③优秀的沟通协调能力，能独立推动供应商及内部跨部门协作。\n\n具备以下条件优先\n1、持有六西格玛绿带/黑带证书；\n\n2、熟悉 IATF 16949质量管理体系，具备内审员资质；\n\n3、有将AI工具落地于质量管理的实战经验\n\n4、有主导或深度参与车身/货箱/外饰零件供应商开发、新项目导入的成功案例；\n\n岗位亮点\n1、站在智能驾驶风口，参与下一代出行变革\n\n参与无人车研发，直接负责车身结构（货箱/钣金骨架）及外饰件（保险杠/格栅/装饰件）​ 的供应商质量管控，你的工作成果将直接影响无人车的耐用性、外观品质与用户感知\n\n2、开放包容的技术氛围 + 扁平化管理\n\n研发文化浓厚，鼓励技术创新与跨部门协作，你的专业意见会被认真倾听。团队年轻有活力，定期举办技术分享会\n\n3、见证产品从0到1的全过程\n\n无人车从原型到量产，每一个零部件的质量突破都凝聚着你的贡献。当你看到自己把关的车身与外饰系统在路上安全行驶，成就感无可替代","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4491482184","sourceKey":"meituan_social","company":"美团","title":"美团月付AI产品专家","city":"上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4491482184&jobShareType=1","duty":"1、独立负责AI产品端到端的从0-1，从场景挖掘与需求定义、AI技术方案选型、产品设计与原型验证，到上线推广与效果迭代；\n2、具备AI驱动的C端增长能力或赋能信贷交易与合规链路的能力。能够结合LLM、推荐模型、生成式UI等AI能力，设计智能化的用户获客、转化、促活功能；将AI能力应用于信贷交易全链路（授信、放款、还款、对账、合规），推动复杂流程的智能化理解与自动化处理，构建智能交易中枢；\n3、建立AI产品评估体系。定义AI产品的效果评测标准与方法（如准确率、转化率提升、用户满意度等），建立数据驱动的闭环迭代机制，持续跟踪关键指标，驱动算法与产品的协同改进；\n4、跨团队协同与资源整合。协同算法、研发、运营、风控等团队，整合美团生态资源，实现AI产品在业务效率、用户体验、场景效果取得多方共赢的结果。","requirements":"1、有独立负责AI产品从0到1落地的完整经历，有参与场景定义、模型能力需求设计、Prompt/Workflow/Agent搭建、效果评估全链路，最终交付用户可使用的AI功能并验证了业务效果；\n2、能熟练使用AI工具（Prompt Engineering、Agent框架、AI编程工具等）把想法快速变成可验证的原型；了解LLM/多模态/Agent等AI技术的原理、能力边界与最新进展；\n3、能清晰定义\"模型需要预测什么、输出什么、如何与用户或系统交互\"，将AI能力封装为用户可理解、可感知的C端功能或系统可执行的B端方案；\n4、5年+互联网产品经验，有C端增长或金融/交易系统产品经验优先，扎实的用户洞察力、交互设计能力、数据分析能力。","description":"部门介绍\n美团金融服务平台成立于2016年，以“场景+金融”模式，携手合作伙伴构建开放生态，为美团平台用户和商户提供底层账户、支付通道、信贷、保险和理财等金融解决方案。我们致力于以科技为核心，助力金融机构打通金融普惠“最后一公里”。我们期待与大家共同完成每一件平凡而卓越的事情，一起为用户提供优质的产品体验，守护用户的资金安全，让生活变得更美好。\n\n岗位职责\n1、独立负责AI产品端到端的从0-1，从场景挖掘与需求定义、AI技术方案选型、产品设计与原型验证，到上线推广与效果迭代；\n2、具备AI驱动的C端增长能力或赋能信贷交易与合规链路的能力。能够结合LLM、推荐模型、生成式UI等AI能力，设计智能化的用户获客、转化、促活功能；将AI能力应用于信贷交易全链路（授信、放款、还款、对账、合规），推动复杂流程的智能化理解与自动化处理，构建智能交易中枢；\n3、建立AI产品评估体系。定义AI产品的效果评测标准与方法（如准确率、转化率提升、用户满意度等），建立数据驱动的闭环迭代机制，持续跟踪关键指标，驱动算法与产品的协同改进；\n4、跨团队协同与资源整合。协同算法、研发、运营、风控等团队，整合美团生态资源，实现AI产品在业务效率、用户体验、场景效果取得多方共赢的结果。\n\n岗位基本要求\n1、有独立负责AI产品从0到1落地的完整经历，有参与场景定义、模型能力需求设计、Prompt/Workflow/Agent搭建、效果评估全链路，最终交付用户可使用的AI功能并验证了业务效果；\n2、能熟练使用AI工具（Prompt Engineering、Agent框架、AI编程工具等）把想法快速变成可验证的原型；了解LLM/多模态/Agent等AI技术的原理、能力边界与最新进展；\n3、能清晰定义\"模型需要预测什么、输出什么、如何与用户或系统交互\"，将AI能力封装为用户可理解、可感知的C端功能或系统可执行的B端方案；\n4、5年+互联网产品经验，有C端增长或金融/交易系统产品经验优先，扎实的用户洞察力、交互设计能力、数据分析能力。\n\n岗位亮点\n主导AI能力在亿级用户信用付产品中的端到端落地","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4306392038","sourceKey":"meituan_social","company":"美团","title":"小象超市天津/石家庄BDM","city":"天津市/沈阳市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4306392038&jobShareType=1","duty":"1.快速搭建BD团队：负责招聘、培养和管理销售团队，建立高绩效团队，并制定并执行相关策略、资源分配等，以实现团队的快速成长；\n2.执行公司的销售策略及政策：负责执行公司的销售策略和政策，通过日常闭环管理跟踪业务进展，带领团队达成业绩目标；\n3.与内外部部门协作：与横向协同部门紧密配合，及时解决销售工作中的各类问题，并持续改进和优化销售流程。","requirements":"1.学历要求：大专及以上学历；\n2.销售管理经验：至少有3年以上销售管理经验，有C端销售管理经验者优先考虑；\n3.学习能力和执行力：具备强烈的学习能力，能承受压力，精力充沛，具备在压力下出色完成任务的能力；\n4.良好的沟通协调能力：具备出色的沟通与协调能力，能够与团队成员和其他部门有效合作，达成共同目标","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1.快速搭建BD团队：负责招聘、培养和管理销售团队，建立高绩效团队，并制定并执行相关策略、资源分配等，以实现团队的快速成长；\n2.执行公司的销售策略及政策：负责执行公司的销售策略和政策，通过日常闭环管理跟踪业务进展，带领团队达成业绩目标；\n3.与内外部部门协作：与横向协同部门紧密配合，及时解决销售工作中的各类问题，并持续改进和优化销售流程。\n\n岗位基本要求\n1.学历要求：大专及以上学历；\n2.销售管理经验：至少有3年以上销售管理经验，有C端销售管理经验者优先考虑；\n3.学习能力和执行力：具备强烈的学习能力，能承受压力，精力充沛，具备在压力下出色完成任务的能力；\n4.良好的沟通协调能力：具备出色的沟通与协调能力，能够与团队成员和其他部门有效合作，达成共同目标\n\n岗位亮点\n大平台、发展稳定。六险一金及年假，福利保障完善。明确的晋升和培训体系。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4249340062","sourceKey":"meituan_social","company":"美团","title":"充电宝-KA客户实施","city":"上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4249340062&jobShareType=1","duty":"1. 负责共享充电宝项目的远程运维工作，对断电率、空仓率、僵尸宝率等核心运维指标负责，通过数据分析发现问题并推动解决。  \n2. 协助销售团队，提升运维数据，用数据驱动运维优化。  \n3. 合作商帮扶与管理，协助梳理运维流程并提供优化建议，帮助合作商降本提效，同时建立并维护良好的合作关系。\n4. 结合充电宝行业经验，对负责区域定期进行全面盘点与问题诊断，输出有效解决方案，取得结果，提升设备产能与门店收益，保障用户体验。","requirements":"1. 熟练使用办公软件、会使用基础函数。\n2. 对数据敏感，具备基础数据分析能力，能通过数据发现异常并结合实际工作进行推动改进。  \n3. 具备责任心和主人翁意识，吃苦耐劳，工作细致，能承受一定压力。  \n4. 有较强的沟通能力，善于主动思考且思路清晰，具备问题分层与解决能力，执行力强。","description":"部门介绍\n美团充电宝是服务零售中的共享租赁业务，承接美团使命，致力让大家充电更简单。美团充电宝业务以应急充电功能为服务核心，覆盖吃喝玩乐生活全场景。目前，已在全国超过2000多个城市的餐饮、娱乐、机场、地铁、火车站、医院、学校、景区等公共区域及场所提供充电服务，铺设机柜超过百万，有KA、直营、渠道合作商多种业务模式，随时随地保障和满足消费者的充电需求。我们的业务资产数量多、场景多元化，追求精益管理。我们的团队大咖云集，崇尚自主驱动，求真务实。我们正处在快速发展期，规模持续增长，目标是市场规模和利润水平双第一。我们的管理者关注团队每个成员的成长，为每个人提供适合自身发展的机会。广阔天地、大有作为，美团充电宝期待你的加入！\n\n岗位职责\n1. 负责共享充电宝项目的远程运维工作，对断电率、空仓率、僵尸宝率等核心运维指标负责，通过数据分析发现问题并推动解决。  \n2. 协助销售团队，提升运维数据，用数据驱动运维优化。  \n3. 合作商帮扶与管理，协助梳理运维流程并提供优化建议，帮助合作商降本提效，同时建立并维护良好的合作关系。\n4. 结合充电宝行业经验，对负责区域定期进行全面盘点与问题诊断，输出有效解决方案，取得结果，提升设备产能与门店收益，保障用户体验。\n\n岗位基本要求\n1. 熟练使用办公软件、会使用基础函数。\n2. 对数据敏感，具备基础数据分析能力，能通过数据发现异常并结合实际工作进行推动改进。  \n3. 具备责任心和主人翁意识，吃苦耐劳，工作细致，能承受一定压力。  \n4. 有较强的沟通能力，善于主动思考且思路清晰，具备问题分层与解决能力，执行力强。\n\n具备以下条件优先\n充电宝行业、共享行业、客户成功、客户实施、相关行业或岗位经验优先！\n\n岗位亮点\n做五休二，基本无外出、无出差，团队氛围好！","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4097722793","sourceKey":"meituan_social","company":"美团","title":"闪购-店铺运营专家-西安","city":"西安市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4097722793&jobShareType=1","duty":"1.根据区域消费特征及市场行情变化，组织制定差异化店铺运营策略\n2.协调营销资源并完成落地执行，或指导并监督合作商落地执行，实现品牌销售增长目标\n3.对合作商及门店日常运营进行监控，对运营数据进行分析，及时发现异常并探寻可增长点\n4.负责建立日常运营管理工具，为运营监控提效，为合作商赋能\n5.负责与协同部门及合作商密切沟通，促进品牌整体运营结果达成和策略落地","requirements":"1.有连锁品牌线上运营经验，熟悉即时零售运营规则\n2.有较强的数据分析能力，熟练使用SQL\n3.有较强的多方协同能力、沟通能力\n4.能适应快速变化及快节奏工作","description":"部门介绍\n美团闪购是美团旗下的即时零售平台，依托即时配送能力，连接本地零售供给，满足消费者30分钟万物到家的即时需求。美团闪购涵盖超市便利、食材、水果、鲜花绿植、休闲零食、酒水饮料、数码家电、美妆个护、母婴玩具、日用百货、服饰鞋帽、宠物等诸多品类，业务覆盖全国近3,000个县市区旗，每日百万级在岗骑手，以高效的配送、丰富的品类和广泛的覆盖，为美团数亿用户带来便捷的生活体验，积极助力实体零售线上化转型，提升本地商业活力。\n\n岗位职责\n1.根据区域消费特征及市场行情变化，组织制定差异化店铺运营策略\n2.协调营销资源并完成落地执行，或指导并监督合作商落地执行，实现品牌销售增长目标\n3.对合作商及门店日常运营进行监控，对运营数据进行分析，及时发现异常并探寻可增长点\n4.负责建立日常运营管理工具，为运营监控提效，为合作商赋能\n5.负责与协同部门及合作商密切沟通，促进品牌整体运营结果达成和策略落地\n\n岗位基本要求\n1.有连锁品牌线上运营经验，熟悉即时零售运营规则\n2.有较强的数据分析能力，熟练使用SQL\n3.有较强的多方协同能力、沟通能力\n4.能适应快速变化及快节奏工作\n\n岗位亮点\n1.部门创新岗位，闪购新供给发展空间大，个人成长快\n2.参与业务0-1发展，能够接触行业大牛","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4669807551","sourceKey":"meituan_social","company":"美团","title":"履约技术-运营系统方向-软件开发工程师","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4669807551&jobShareType=1","duty":"1、深入理解履约运营和等级、权益等配送核心业务，对业务流程进行合理抽象和建模，构建易扩展、低成本、高可用系统，支持复杂多变业务场景 \n\n2、积极实践AI Coding辅助软件开发全流程，作为AI Builder输出影响力，保证资金安全和稳定性，提高业务支撑效率，跨团队有效沟通，解决关键业务问题和技术难题 \n\n3、充分进行业界对标调研，结合业务和系统现状，规划系统架构，并落地系统建设","requirements":"1.本科及以上学历，计算机相关专业， 3年以上开发经验\n\n2.具有扎实的AI Coding基础知识和实践经验，良好的架构设计能力、问题定义及解决能力、技术判断力\n\n3.熟练掌握Java Web前后端全栈开发，熟悉MySQL/Redis/Kafka/流程引擎/Spark离线计算等中间件\n\n4.沟通交流顺畅，逻辑清晰，有良好的跨团队协作的经验和意识，良好的学习态度和投入度","description":"部门介绍\n美团核心本地商业下业务研发平台，基于公司“零售+科技”的战略导向，通过从底层架构到应用系统、从软件到硬件、从传统算法到GenAI的全方位技术研究，以及开发、运维、安全等全流程能力建设，致力于推动美团核心本地商业下需求侧与供给侧的数字化和智能化升级，助力业务实现高质量增长，优化用户使用体验，提升商户经营水平，促进行业生态伙伴关系的持续健康发展。团队秉持务实、自驱、开放以及追求卓越的工程师文化，一方面通过系统和技术体系的持续迭代升级，帮助业务高质量增长；另一方面，密切关注前沿技术趋势变化，积极创新技术能力，为业务未来发展创造新的可能性。期待优秀的你加入我们，在夯实专业、深耕平台的基础上与业务携手同行，一起用技术 “帮大家吃得更好，生活更好”。\n\n岗位职责\n1、深入理解履约运营和等级、权益等配送核心业务，对业务流程进行合理抽象和建模，构建易扩展、低成本、高可用系统，支持复杂多变业务场景 \n\n2、积极实践AI Coding辅助软件开发全流程，作为AI Builder输出影响力，保证资金安全和稳定性，提高业务支撑效率，跨团队有效沟通，解决关键业务问题和技术难题 \n\n3、充分进行业界对标调研，结合业务和系统现状，规划系统架构，并落地系统建设\n\n岗位基本要求\n1.本科及以上学历，计算机相关专业， 3年以上开发经验\n\n2.具有扎实的AI Coding基础知识和实践经验，良好的架构设计能力、问题定义及解决能力、技术判断力\n\n3.熟练掌握Java Web前后端全栈开发，熟悉MySQL/Redis/Kafka/流程引擎/Spark离线计算等中间件\n\n4.沟通交流顺畅，逻辑清晰，有良好的跨团队协作的经验和意识，良好的学习态度和投入度\n\n岗位亮点\n1.核心领域、高性能挑战：深度参与配送履约运营核心业务，系统具备多业务线、差异化场景，海量数据、计算复杂等特点，适合期望在核心业务领域平台化系统建设提升架构能力的同学\n\n2.业务复杂，能力提升快：可以与产品、业务团队紧密合作，深入了解业务和产品需求，在工作中能够遇到各种业务难题，沉淀通过平台化系统解决高复杂度业务问题经验，锻炼自己的问题分析解决能力和团队协作能力\n\n3.成为AI Builder，拓宽视野：有机会遇到核心技术问题，深度应用AI Coding，不断提升技术水平和创新能力","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4664757646","sourceKey":"meituan_social","company":"美团","title":"供给产品工具系统运营","city":"北京市/深圳市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4664757646&jobShareType=1","duty":"本岗位面向Keeta各区域B端运营及BD，负责供给产品工具系统的体验优化、版本管理、运营赋能及AI效率落地。\n1. 常态化调研多区域用户真实使用痛点，持续优化工具系统操作链路与功能适配，提升用户使用体验。\n2. 产品版本全流程管理，从需求跟进、上线落地到复盘迭代的全生命周期管理，保障版本平稳落地、贴合业务需求\n3. 运营机制搭建迭代，搭建用户反馈、问题跟进、培训赋能、数据复盘等标准化运营机制，沉淀可复用的工具运营方法。\n4. AI工具落地赋能：运用各类AI工具提升日常工作效率，主动探索AI在工具运营场景的创新应用，推动团队效率升级。","requirements":"1. 具备优秀的B端用户调研与需求洞察能力，可精准挖掘用户真实业务痛点与核心诉求。\n2. 具备运营流程与机制搭建落地经验，可通过体系化运营解决业务问题、落地运营结果。\n3. 具备良好的跨部门沟通协同能力，可高效联动多方推进工作，英语可做为工作语言。\n4. 熟练使用各类AI工具辅助办公，可借助AI完成数据分析、文档梳理等工作，提升工作效率。\n5. 加分项：具备供给/交易类B端平台、BD业务、工具系统版本运营及体验优化相关经验。","description":"部门介绍\nKeeta是全球领先外卖平台美团旗下的独立品牌，肩负着“帮大家吃得更好，生活更好”的使命。依托美团深耕中国市场15年的技术与运营积淀，我们正引领全球餐饮与商品即时配送服务的创新与发展。\n\n自2023年成立以来，Keeta始终扎根社区并创造价值。我们为用户提供可靠的外卖体验，以智慧技术助餐厅提升经营效率，在为骑手拓宽收入来源的同时，也充分提供安全保障措施。基于这份多方共赢、共同成长的理念，我们的业务已从中国香港稳步拓展至中东及巴西，并持续向世界迈进。\n\n岗位职责\n本岗位面向Keeta各区域B端运营及BD，负责供给产品工具系统的体验优化、版本管理、运营赋能及AI效率落地。\n1. 常态化调研多区域用户真实使用痛点，持续优化工具系统操作链路与功能适配，提升用户使用体验。\n2. 产品版本全流程管理，从需求跟进、上线落地到复盘迭代的全生命周期管理，保障版本平稳落地、贴合业务需求\n3. 运营机制搭建迭代，搭建用户反馈、问题跟进、培训赋能、数据复盘等标准化运营机制，沉淀可复用的工具运营方法。\n4. AI工具落地赋能：运用各类AI工具提升日常工作效率，主动探索AI在工具运营场景的创新应用，推动团队效率升级。\n\n岗位基本要求\n1. 具备优秀的B端用户调研与需求洞察能力，可精准挖掘用户真实业务痛点与核心诉求。\n2. 具备运营流程与机制搭建落地经验，可通过体系化运营解决业务问题、落地运营结果。\n3. 具备良好的跨部门沟通协同能力，可高效联动多方推进工作，英语可做为工作语言。\n4. 熟练使用各类AI工具辅助办公，可借助AI完成数据分析、文档梳理等工作，提升工作效率。\n5. 加分项：具备供给/交易类B端平台、BD业务、工具系统版本运营及体验优化相关经验。\n\n岗位亮点\n1.国际化业务，初创团队，从0-1的经验，成长空间\n2.外卖业务，长链路业务属性具备诸多挑战，可建立复杂业务产品的认知\n3.发展空间大，团队氛围好，自我成长快。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4661479149","sourceKey":"meituan_social","company":"美团","title":"AI数据产品专家","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4661479149&jobShareType=1","duty":"1、负责AI数据产品方向的整体规划与路线图制定，定义各阶段的核心场景与验收标准，明确半年及年度产品里程碑。\n2、深入业务团队，通过用户调研、场景跟踪和数据回访，提炼高频且高价值的数据消费痛点，将其转化为可落地的产品需求；持续跟踪行业内Data Agent / AI BI / Copilot类产品动态，输出有判断力的产品分析而非功能罗列，持续校准自身产品定位。\n3、主导AI数据产品的体验设计与交互定义，协调研发、算法、数据架构等多个技术团队，拉齐技术可行性与产品目标，确保产品在准确率、响应速度、交互流畅度上实现高质量交付。\n4、建立AI数据产品的效果度量体系（覆盖DAU、查询成功率、用户留存、人效提升等关键指标），以数据驱动产品迭代，定期输出产品复盘与方向调整建议。\n5、负责团队梯队建设，明确能力模型与成长路径，推动团队在AI数据产品领域的专业深度和协作效率持续提升。\n6、制定AI数据产品的推广与运营策略，从种子用户验证到公司内外部规模化推广，分阶段设计用户增长路径与培训体系。","requirements":"1、本科及以上学历，计算机、数据科学、信息管理等相关专业背景。\n2、7年以上互联网产品经验，其中至少3年数据产品（BI/数据平台/数据中台）方向的深度经验。\n3、对数据消费全链路有体感：理解数仓分层、指标体系、数据权限等基础概念。\n4、对LLM/Agent领域有深入理解，能独立判断技术可行性与产品价值的边界。\n5、3年以上产品团队管理经验，能独立负责跨职能团队的目标对齐、优先级决策和资源协调。","description":"部门介绍\n基础研发平台是美团的核心技术平台，立足于“零售+科技”的战略定位，通过打造人工智能、大数据、云计算、安全等核心技术能力，以及研发效能平台、企业应用平台等公共服务，为业务提供稳定安全、扩展易用、技术领先的平台技术和产品服务。\n在这里，我们会参与到最前沿的技术研发和探索；能够接触超规模集群、海量数据，挑战高复杂业务场景，有机会与业界一流的工程师一起并肩前行。\n在这里，我们有超强的技术氛围，持续向社区贡献业界实践，加速行业技术发展；我们有完善的互联网学习生态圈，重视底层逻辑和方法论，助力职业生涯的非线性成长。\n真诚地邀请你，和我们一起驱动技术发展，创造行业价值。\n\n岗位职责\n1、负责AI数据产品方向的整体规划与路线图制定，定义各阶段的核心场景与验收标准，明确半年及年度产品里程碑。\n2、深入业务团队，通过用户调研、场景跟踪和数据回访，提炼高频且高价值的数据消费痛点，将其转化为可落地的产品需求；持续跟踪行业内Data Agent / AI BI / Copilot类产品动态，输出有判断力的产品分析而非功能罗列，持续校准自身产品定位。\n3、主导AI数据产品的体验设计与交互定义，协调研发、算法、数据架构等多个技术团队，拉齐技术可行性与产品目标，确保产品在准确率、响应速度、交互流畅度上实现高质量交付。\n4、建立AI数据产品的效果度量体系（覆盖DAU、查询成功率、用户留存、人效提升等关键指标），以数据驱动产品迭代，定期输出产品复盘与方向调整建议。\n5、负责团队梯队建设，明确能力模型与成长路径，推动团队在AI数据产品领域的专业深度和协作效率持续提升。\n6、制定AI数据产品的推广与运营策略，从种子用户验证到公司内外部规模化推广，分阶段设计用户增长路径与培训体系。\n\n岗位基本要求\n1、本科及以上学历，计算机、数据科学、信息管理等相关专业背景。\n2、7年以上互联网产品经验，其中至少3年数据产品（BI/数据平台/数据中台）方向的深度经验。\n3、对数据消费全链路有体感：理解数仓分层、指标体系、数据权限等基础概念。\n4、对LLM/Agent领域有深入理解，能独立判断技术可行性与产品价值的边界。\n5、3年以上产品团队管理经验，能独立负责跨职能团队的目标对齐、优先级决策和资源协调。\n\n具备以下条件优先\n1、有AI Agent或智能助手类产品的设计与落地经验。\n2、有企业内部效率工具、协同办公、知识管理类产品经验。\n3、有从0到1的产品经验，或主导过百万级用户量产品的核心模块。\n4、熟悉 AI 工具生态及Agent 评测体系设计经验。\n5、有推动组织级 AI 转型或 AI 工具落地推广的成功案例。\n\n岗位亮点\n1、产品负责人定位，端到端负责AI数据产品方向，从定义到推广全权负责，在公司级数据智能化战略中有直接话语权。\n2、数据平台服务全公司数据使用者，AI数据产品的每一个决策都直接影响这些人的日常工作方式。同时产品也面向外部建设具备商业化价值的AI产品能力，影响力覆盖公司内外。\n3、站在AI重塑数据消费的行业拐点上，不是在成熟产品上做微调，而是定义一个新品类的产品形态。\n4、与数据工程和算法团队协同，快速建立\"AI × 数据产品\"的稀缺复合能力。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4176488439","sourceKey":"meituan_social","company":"美团","title":"小象超市-水果采购专家（华北区域）","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4176488439&jobShareType=1","duty":"1.负责水果类商品的招商采购工作，包括市场调研、供应商筛选、谈判合作及合同签订等；\n2.负责建立和维护供应商关系，保证供应商的稳定供货，并不断优化供应商体系，提升供应链效率；\n3.负责采购成本的控制，制定合理的采购价格，确保公司的采购成本在合理范围内；\n4.协助解决采购过程中的问题和纠纷，保证采购工作的顺利进行。","requirements":"1.大学专科及以上学历，专业不限，有供应链管理或相关领域背景优先；\n2.具备3年以上水果类商品的招商采购经验，熟悉水果市场和供应链管理流程；\n3.具备较强的市场分析和数据处理能力，能够准确把握市场需求和价格趋势；\n4.具备良好的供应商管理和谈判能力，能够与供应商建立互信合作的关系；\n5.具备良好的团队合作精神和沟通能力，能够与内外部团队有效协作，推动项目的顺利进行；\n6.具备较强的问题解决能力，能够应对采购过程中的各种挑战；\n7.掌握基本的AI工具，使用工具提升工作流程效率","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1.负责水果类商品的招商采购工作，包括市场调研、供应商筛选、谈判合作及合同签订等；\n2.负责建立和维护供应商关系，保证供应商的稳定供货，并不断优化供应商体系，提升供应链效率；\n3.负责采购成本的控制，制定合理的采购价格，确保公司的采购成本在合理范围内；\n4.协助解决采购过程中的问题和纠纷，保证采购工作的顺利进行。\n\n岗位基本要求\n1.大学专科及以上学历，专业不限，有供应链管理或相关领域背景优先；\n2.具备3年以上水果类商品的招商采购经验，熟悉水果市场和供应链管理流程；\n3.具备较强的市场分析和数据处理能力，能够准确把握市场需求和价格趋势；\n4.具备良好的供应商管理和谈判能力，能够与供应商建立互信合作的关系；\n5.具备良好的团队合作精神和沟通能力，能够与内外部团队有效协作，推动项目的顺利进行；\n6.具备较强的问题解决能力，能够应对采购过程中的各种挑战；\n7.掌握基本的AI工具，使用工具提升工作流程效率\n\n具备以下条件优先\n1、有大型供应商资源\n2、有生鲜零售，线上，线下及大型超市采购经验\n\n岗位亮点\n1.上市公司，平台大，行业整合能力强\n2.自营重点项目，清晰的晋升路径，发展空间大\n3.与各类供应商建立广泛的合作关系，拓展行业视角与资源积累","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4655537563","sourceKey":"meituan_social","company":"美团","title":"Keeta-履约策略产品","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4655537563&jobShareType=1","duty":"1. 角色定位： 参与履约策略方向的工作，负责供需调节/配送范围/配送费定价，平衡配送体验和规模转化\n2. 发现问题：充分理解外卖业务，厘清关键变量和影响关系，通过 数据分析/行研用研/实际体验 建设健壮的分析诊断能力，持续发现关键问题和背后的原因\n3. 规划执行：基于上游业务目标，协同运营和研发确定阶段性目标，设定milestone并抽象核心解法，推动方案上线并评估迭代","requirements":"1. 从需求出发从问题出发，对场景思考全面，有平衡多目标的能力和意识，避免顾此失彼\n2. 能站在用户视角、骑手视角、竞争视角思考问题，理解数据背后的意义，避免纯数字驱动\n3. 独立思考，避免路径依赖，同时敬畏对手敬畏用户\n4. 有责任心，做正确的事\n5. 协作意识，合作共赢","description":"部门介绍\nKeeta是全球领先外卖平台美团旗下的独立品牌，肩负着“帮大家吃得更好，生活更好”的使命。依托美团深耕中国市场15年的技术与运营积淀，我们正引领全球餐饮与商品即时配送服务的创新与发展。\n\n自2023年成立以来，Keeta始终扎根社区并创造价值。我们为用户提供可靠的外卖体验，以智慧技术助餐厅提升经营效率，在为骑手拓宽收入来源的同时，也充分提供安全保障措施。基于这份多方共赢、共同成长的理念，我们的业务已从中国香港稳步拓展至中东及巴西，并持续向世界迈进。\n\n岗位职责\n1. 角色定位： 参与履约策略方向的工作，负责供需调节/配送范围/配送费定价，平衡配送体验和规模转化\n2. 发现问题：充分理解外卖业务，厘清关键变量和影响关系，通过 数据分析/行研用研/实际体验 建设健壮的分析诊断能力，持续发现关键问题和背后的原因\n3. 规划执行：基于上游业务目标，协同运营和研发确定阶段性目标，设定milestone并抽象核心解法，推动方案上线并评估迭代\n\n岗位基本要求\n1. 从需求出发从问题出发，对场景思考全面，有平衡多目标的能力和意识，避免顾此失彼\n2. 能站在用户视角、骑手视角、竞争视角思考问题，理解数据背后的意义，避免纯数字驱动\n3. 独立思考，避免路径依赖，同时敬畏对手敬畏用户\n4. 有责任心，做正确的事\n5. 协作意识，合作共赢\n\n具备以下条件优先\n具备以下优先\n1. 4年以上策略类产品工作经验，包括但不限于履约策略、智能定价补贴 、量分发\n2. 英语可作为工作语言者优先\n\n岗位亮点\n1. 国际化业务，初创团队，从0-1的经验，成长空间；\n2. 外卖业务复杂，长链路业务属性具备诸多挑战，可建立复杂业务产品的认知；\n3. 发展空间大，团队氛围好，自我成长快。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4657620585","sourceKey":"meituan_social","company":"美团","title":"厦门冷链主管","city":"厦门市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4657620585&jobShareType=1","duty":"1. 负责冷链仓储的日常运营管理，确保货物存储、出入库流程符合温控标准。  \n2. 制定并优化冷链仓储作业流程，提升仓储效率与安全性。  \n3. 监督冷链设备的运行状态，协调维护与故障处理，保障冷链不断链。  \n4. 管理仓储团队，安排人员排班与培训，确保操作规范执行到位。  \n5. 配合质量部门完成冷链相关记录与数据整理，支持审计与合规检查。","requirements":"1. 大学专科及以上学历，物流、供应链管理或相关专业优先。  \n2. 具备5年以上仓储管理经验，其中至少2年冷链仓储相关工作经验。  \n3. 熟悉冷链物流操作规范及温控管理要求，了解GSP等相关法规。  \n4. 具备良好的沟通协调能力与团队管理能力，责任心强。  \n5. 能适应倒班工作，工作地点为宁波市。","description":"部门介绍\n快驴进货是美团旗下的餐饮供应链平台，帮助餐饮商户以更低成本、更高效率来获取安全可靠的食材供应，让餐饮采购更简单。快驴进货同步发展“自营+平台”的业务模式，在采购环节一方面向上游供应商直采大宗商品，另一方面引入各地批发商，助力平台伙伴共同发展；在销售环节既有自建团队进行市场、客户拓展，又帮助各地批发商拓展业务；同时自建仓储管理系统、配送网络与团队，为客户提供优质履约服务。\n截至2022年，快驴进货布局了全国41个城市，为百万家商户提供“全、省、稳、好”的餐饮供应链服务。我们拥有3000+品牌食材、超5万SKU商品、超28万商品资质，并提供源头严审核、食品安全严把关、24小时无忧售后的全面保障，实现手机下单、送货上门的高效采购模式，帮百万商家节省了采购时间与成本，助力平台伙伴共同发展，在万亿市场共享机遇。\n在这里，你将收获完善的员工发展机制及学习体系，与各界专家一起深度参与餐饮供应链业务的发展。欢迎优秀的你加入美团快驴进货，与我们一起成长，一起更好！\n\n岗位职责\n1. 负责冷链仓储的日常运营管理，确保货物存储、出入库流程符合温控标准。  \n2. 制定并优化冷链仓储作业流程，提升仓储效率与安全性。  \n3. 监督冷链设备的运行状态，协调维护与故障处理，保障冷链不断链。  \n4. 管理仓储团队，安排人员排班与培训，确保操作规范执行到位。  \n5. 配合质量部门完成冷链相关记录与数据整理，支持审计与合规检查。\n\n岗位基本要求\n1. 大学专科及以上学历，物流、供应链管理或相关专业优先。  \n2. 具备5年以上仓储管理经验，其中至少2年冷链仓储相关工作经验。  \n3. 熟悉冷链物流操作规范及温控管理要求，了解GSP等相关法规。  \n4. 具备良好的沟通协调能力与团队管理能力，责任心强。  \n5. 能适应倒班工作，工作地点为宁波市。\n\n岗位亮点\n1. 提供完善的冷链专业培训与职业发展通道。  \n2. 工作环境规范，配备先进的冷链仓储设备。  \n3. 团队氛围积极，注重员工成长与工作生活平衡。  \n4. 享受具有竞争力的薪酬福利与绩效奖金。  \n5. 地处宁波物流枢纽，行业资源丰富，发展机会广阔。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3687048019","sourceKey":"meituan_social","company":"美团","title":"商家策略负责人","city":"圣保罗","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3687048019&jobShareType=1","duty":"1.负责商家运营团队的日常管理和指导，建设懂策略、能本地化落地、能横向协同的高效组织；\n2.负责品牌的调研、分析和完整解决方案输出，建立机制和标准，打磨业务精益模型，确保业务快速扩张；\n3.负责线上门店运营管理，建设工具产品实现业务的快速扩张，对品牌的门店经营结果负责；\n4.负责商家数据分析和业绩评估，基于数据表现、品牌反馈和市场动态，及时调整运营策略和方案；\n5.负责线下和KA/SMB、客户增长、配送等多端的协作，统筹商户品牌的规模、体验、损益最优平衡。\n6.负责基于市场和竞争动态，不断创新迭代业务模式，寻求品牌、用户、平台三方利益最优的解决方案；","requirements":"1.大学本科及以上学历，专业不限；\n2.8年以上产品运营或商家运营相关工作经验，具备一定的团队管理经验；\n3.熟悉本地生活服务行业的商家运营流程和规则，具备较强的数据分析能力和解决问题的能力；\n4.具备良好的沟通能力和团队协作能力，能够有效管理团队并推动工作落地；\n5.思维敏捷，逻辑清晰，能够承受工作压力。","description":"部门介绍\nKeeta是全球领先外卖平台美团旗下的独立品牌，肩负着“帮大家吃得更好，生活更好”的使命。依托美团深耕中国市场15年的技术与运营积淀，我们正引领全球餐饮与商品即时配送服务的创新与发展。\n\n自2023年成立以来，Keeta始终扎根社区并创造价值。我们为用户提供可靠的外卖体验，以智慧技术助餐厅提升经营效率，在为骑手拓宽收入来源的同时，也充分提供安全保障措施。基于这份多方共赢、共同成长的理念，我们的业务已从中国香港稳步拓展至中东及巴西，并持续向世界迈进。\n\n岗位职责\n1.负责商家运营团队的日常管理和指导，建设懂策略、能本地化落地、能横向协同的高效组织；\n2.负责品牌的调研、分析和完整解决方案输出，建立机制和标准，打磨业务精益模型，确保业务快速扩张；\n3.负责线上门店运营管理，建设工具产品实现业务的快速扩张，对品牌的门店经营结果负责；\n4.负责商家数据分析和业绩评估，基于数据表现、品牌反馈和市场动态，及时调整运营策略和方案；\n5.负责线下和KA/SMB、客户增长、配送等多端的协作，统筹商户品牌的规模、体验、损益最优平衡。\n6.负责基于市场和竞争动态，不断创新迭代业务模式，寻求品牌、用户、平台三方利益最优的解决方案；\n\n岗位基本要求\n1.大学本科及以上学历，专业不限；\n2.8年以上产品运营或商家运营相关工作经验，具备一定的团队管理经验；\n3.熟悉本地生活服务行业的商家运营流程和规则，具备较强的数据分析能力和解决问题的能力；\n4.具备良好的沟通能力和团队协作能力，能够有效管理团队并推动工作落地；\n5.思维敏捷，逻辑清晰，能够承受工作压力。\n\n岗位亮点\n1.国际化大舞台，与全球人才为伴，与全球高手同台竞技；\n2.能够全方位了解海外外卖业务模式，有足够的空间和灵活度全面发挥你的才能；\n3.创新业务的核心部门，0-1阶段的高速增长和无限空间。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4570708137","sourceKey":"meituan_social","company":"美团","title":"城市运营主管（佛山市）","city":"佛山市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4570708137&jobShareType=1","duty":"1. 负责佛山市市区域内车辆的日常运营调度与维护管理，确保车辆高效运转。\n2. 协助制定并执行城市运营策略，提升车辆使用率和用户满意度。\n3. 对接维修、调度、仓储等团队，协调资源解决运营中的突发问题。\n4. 收集并分析运营数据，定期输出运营报告，提出优化建议。","requirements":"1. 大学本科及以上学历，专业不限。\n2. 具备1年以上运营或运维相关工作经验，有车辆管理或共享出行行业经验优先。\n3. 具备良好的沟通协调能力和团队协作意识。\n4. 熟练使用办公软件，具备基础数据分析能力。","description":"部门介绍\n美团骑行事业部在全国各个城市开展美团单车、电单车业务，提供绿色、便捷的共享出行服务，是美团出行板块重要的组成部分。我们力求为城市可持续发展提供低碳智能的解决方案，通过技术创新和硬件升级，不断优化全流程骑行体验，为低碳出行提供更好的服务。其中，美团单车旨在为城市居民提供通勤接驳服务，满足用户短途接驳出行需求；美团电单车则满足用户中短途多场景低碳出行需求。\n我们有开放的工作氛围，也有充满韧劲和创造力，心系低碳出行的伙伴。加入我们，一起为用户创造更好的出行体验。\n\n岗位职责\n1. 负责佛山市市区域内车辆的日常运营调度与维护管理，确保车辆高效运转。\n2. 协助制定并执行城市运营策略，提升车辆使用率和用户满意度。\n3. 对接维修、调度、仓储等团队，协调资源解决运营中的突发问题。\n4. 收集并分析运营数据，定期输出运营报告，提出优化建议。\n\n岗位基本要求\n1. 大学本科及以上学历，专业不限。\n2. 具备1年以上运营或运维相关工作经验，有车辆管理或共享出行行业经验优先。\n3. 具备良好的沟通协调能力和团队协作意识。\n4. 熟练使用办公软件，具备基础数据分析能力。\n\n岗位亮点\n1. 参与城市级运营项目，积累一线实战经验。\n2. 扁平化管理，快速成长通道。\n3. 工作地点稳定，团队氛围积极。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4557950931","sourceKey":"meituan_social","company":"美团","title":"景点游玩业务部-交易产品经理","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4557950931&jobShareType=1","duty":"1.负责境内门票业务的C端交易路径产品设计和优化，通过改善用户交易流程体验，提高交易转化效率。\n2.建设交易路径的用户指标体系，结合数据驱动产品体验和转化效率提升。\n3.深入理解用户在购买门票的需求的决策流程，协同业务及研发团队，进行产品方案规划、设计和迭代。\n4.关注旅游行业动态，结合业务阶段、业务需求，推进项目落地并达成目标。","requirements":"1.大学本科及以上学历，5年以上C端产品工作经验，OTA行业或知名电商产品相关经验优先。\n2.以用户为中心，对用户场景和需求有深入理解和洞察，对市场动态和新功能有敏锐的洞察力，具备较强的创新意识。\n3.具备出色的沟通表达能力，较强的owner意识，擅长跨部门协作沟通。\n4.逻辑思维严密，良好的数据sense，具备较强的数据分析能力，具备sql能力，有使用AI工具的经验。\n5.韧性强，有较强的成就动机，热爱旅游者优先。\n6.有AI在日常工作中应用的经验者优先。","description":"部门介绍\n美团酒店旅行业务涵盖酒店、民宿、机票、火车票、旅游度假、景点门票等各类住行游品类，通过与产业上下游的深度合作，为用户提供美好的旅游旅行体验。我们积极打造AI友好型组织，使用AI等新技术提升旅游服务的供需匹配效率，更好满足用户个性化、多样化的出游需求。我们持续深耕产业链，用数字化服务助力实体商家高质量经营，探索自有品牌等供给新模式，打造健康的商家生态，保障用户服务体验。为满足用户日益增长的跨境旅行需求，我们将聚焦亚太区域，打造高品质的住宿、交通、游玩等服务矩阵。\n这里有多元的业务布局、持续的成长空间，无论是向往的远方还是眼前的工作，一路都是风景相伴。加入我们，共同为用户创造旅游旅行中的高光时刻！\n\n岗位职责\n1.负责境内门票业务的C端交易路径产品设计和优化，通过改善用户交易流程体验，提高交易转化效率。\n2.建设交易路径的用户指标体系，结合数据驱动产品体验和转化效率提升。\n3.深入理解用户在购买门票的需求的决策流程，协同业务及研发团队，进行产品方案规划、设计和迭代。\n4.关注旅游行业动态，结合业务阶段、业务需求，推进项目落地并达成目标。\n\n岗位基本要求\n1.大学本科及以上学历，5年以上C端产品工作经验，OTA行业或知名电商产品相关经验优先。\n2.以用户为中心，对用户场景和需求有深入理解和洞察，对市场动态和新功能有敏锐的洞察力，具备较强的创新意识。\n3.具备出色的沟通表达能力，较强的owner意识，擅长跨部门协作沟通。\n4.逻辑思维严密，良好的数据sense，具备较强的数据分析能力，具备sql能力，有使用AI工具的经验。\n5.韧性强，有较强的成就动机，热爱旅游者优先。\n6.有AI在日常工作中应用的经验者优先。\n\n岗位亮点\n1.在行业头部规模团队参与业务重点战略方向，有机会把你的想法付之行动，为行业和用户创造价值。\n2.作为核心岗位人员，参与定义复杂业务场景的策略体系建设，获得驱动业务增长的成就感和从思考到执行的全方位提升，快速提升个人能力和经验视野。\n3.团队氛围开放，团队求真务实，目标导向强，和各业务职能团队的无缝紧密合作，更丰富的信息输入、更聚焦的工作领域、更高效的沟通协作。\n4.所在团队先后获得：北京信息通信行业适老化及无障碍服务优秀案例、文旅部首批适老化示范案例、公司首届增长比赛第1名、到店“以客户为中心奖”、总经理特别奖等诸多奖项。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4657304903","sourceKey":"meituan_social","company":"美团","title":"无人车业务部-仿真性能优化工程师","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4657304903&jobShareType=1","duty":"1. 负责大规模仿真和数据计算性能优化；\n2. 负责云计算平台性能指标和稳定性建设工作；","requirements":"1. 有扎实的 C++ / Python 语言基础与 Linux 系统基础，热爱技术，愿意学习；\n2. 精通 Linux 下性能分析工具，具有 CPU、GPU、内存、网络性能调优经验；\n3. 良好的沟通表达和团队协作能力；","description":"部门介绍\n无人车业务部成立于2016年，旨在用无人驾驶技术提升物流配送的效率和体验。美团无人车以自研L4级自动驾驶软硬件技术为核心，与美团即时零售业务结合，形成满足公开道路、社区、工业园区等室外全场景下的无人配送整体解决方案。自2020年起，无人车已在北京、深圳等多地进入常态化试运营阶段，在城市复杂场景下提供针对餐饮外卖、生鲜食杂等货物的即时配送服务。2025年，美团无人车又踏上了同城货运的新探索，并在2026年持续扩大运营范围和车队数量，为更多城市带来智能配送服务。\n欢迎加入美团无人车团队，与我们一起用科技推动即时零售再升级！\n\n岗位职责\n1. 负责大规模仿真和数据计算性能优化；\n2. 负责云计算平台性能指标和稳定性建设工作；\n\n岗位基本要求\n1. 有扎实的 C++ / Python 语言基础与 Linux 系统基础，热爱技术，愿意学习；\n2. 精通 Linux 下性能分析工具，具有 CPU、GPU、内存、网络性能调优经验；\n3. 良好的沟通表达和团队协作能力；\n\n具备以下条件优先\n1. 有大规模分布式系统性能优化经验者优先；\n2. 有自动驾驶相关工作经验者优先；\n\n岗位亮点\n1. 通过云计算平台的建设，促进自动驾驶大规模落地应用；\n2. 挑战在自动驾驶计算业务下的任务调度，数据调度等系统设计难题；\n3. 有机会了解自动驾驶计算特点和自动驾驶算法相关知识；","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4664694506","sourceKey":"meituan_social","company":"美团","title":"财务运营-金服财务运营-保险财务运营","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4664694506&jobShareType=1","duty":"1. 对接保险经纪业务，结合会计准则、结算规则和合规要求等，识别和判断业务活动对财务的影响，出具相应的财务方案，为业务部门的发展及商业决策提供积极的财务支持；\n2. 负责险经纪业务日常运营工作，包括保费/理赔代收代付和经纪费等业务的账务处理、结算和核对。  \n2. 协助完成保险业务财务数据的统计、分析与报告，支持业务部门决策。  \n3. 对接保险公司及内部主业，确保财务数据准确性和流程合规性。  \n4. 负责优化保险财务流程，提升系统信息化水平，增强运营效率与合规性。\n5. 配合内外部审计及行业检查，提供财务数据及相关材料。","requirements":"1. 大学本科及以上学历，财务、会计、金融等相关专业。  \n2. 具备3年以上财务相关工作经验。  \n3. 熟悉行业财务流程及会计准则，具备基础的数据分析能力。  \n4. 工作细致、责任心强，具备良好的沟通能力和团队协作精神，能有效协调财务、产研、业务等多方资源；\n5. 有大型会计师事务所从业经验者、保险财务或互联网公司财务经验者优先。","description":"部门介绍\n财务平台负责公司整体和各业务层面的财务管理工作，通过建设专业、全面、复合的财务管理能力和与业务经营的紧密结合来支持公司健康发展。目前财务平台拥有财务会计、财务报告、资金管理、税务管理、财务共享、财务系统、规划分析、财务BP和内控内审等主要工作方向。我们的目标是建设业界一流的财务管理能力和经营支持体系，为公司战略的正确落地、投入效率的持续提升、业务价值的不断增长保驾护航。欢迎加入财务平台，携手一起向未来！\n\n岗位职责\n1. 对接保险经纪业务，结合会计准则、结算规则和合规要求等，识别和判断业务活动对财务的影响，出具相应的财务方案，为业务部门的发展及商业决策提供积极的财务支持；\n2. 负责险经纪业务日常运营工作，包括保费/理赔代收代付和经纪费等业务的账务处理、结算和核对。  \n2. 协助完成保险业务财务数据的统计、分析与报告，支持业务部门决策。  \n3. 对接保险公司及内部主业，确保财务数据准确性和流程合规性。  \n4. 负责优化保险财务流程，提升系统信息化水平，增强运营效率与合规性。\n5. 配合内外部审计及行业检查，提供财务数据及相关材料。\n\n岗位基本要求\n1. 大学本科及以上学历，财务、会计、金融等相关专业。  \n2. 具备3年以上财务相关工作经验。  \n3. 熟悉行业财务流程及会计准则，具备基础的数据分析能力。  \n4. 工作细致、责任心强，具备良好的沟通能力和团队协作精神，能有效协调财务、产研、业务等多方资源；\n5. 有大型会计师事务所从业经验者、保险财务或互联网公司财务经验者优先。\n\n具备以下条件优先\n事务所背景、互联网公司财务背景优先\n\n岗位亮点\n1. 加入快速发展的金融科技团队，接触前沿保险业务模式，深度参与保险财务核心业务，积累行业专业经验。  \n2. 提供完善的培训体系与职业发展通道。\n3. 与业务、技术团队紧密协作，提升综合能力。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4654075979","sourceKey":"meituan_social","company":"美团","title":"酒店agent收益产品","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4654075979&jobShareType=1","duty":"1. 负责收益产品的规划与设计，结合业务目标制定产品策略和 roadmap。  \n2. 熟练掌握商家 OTA 运营的方法、策略、工具，并抽象为 agent 可用的 skill，同时优化 token 消耗持续迭代；\n3. 深入分析商户行为与业务数据，挖掘收益增长机会并推动产品优化。  \n4. 监控产品核心指标，建立收益评估体系并输出分析报告。","requirements":"1. 具备2年以上电商/OTA商户后台相关工作经验，有收益管理或商业化产品背景者优先。  \n2. 熟悉数据分析工具，具备较强的逻辑思维和用户洞察能力。  \n3. 具备良好的沟通能力和跨团队协作能力，能独立推动项目进展。","description":"部门介绍\n美团的使命是“帮大家吃得更好，生活更好”，公司聚焦“零售 + 科技”战略，和广大商户与各类合作伙伴一起，努力为消费者提供品质生活，推动商品零售和服务零售在需求侧和供给侧的数字化转型。\n2018年9月20日，美团正式在港交所挂牌上市。美团将始终坚持以客户为中心，不断加大在科技研发方面的投入，更好承担社会责任，更多创造社会价值，与广大合作伙伴一起发展共赢。\n\n岗位职责\n1. 负责收益产品的规划与设计，结合业务目标制定产品策略和 roadmap。  \n2. 熟练掌握商家 OTA 运营的方法、策略、工具，并抽象为 agent 可用的 skill，同时优化 token 消耗持续迭代；\n3. 深入分析商户行为与业务数据，挖掘收益增长机会并推动产品优化。  \n4. 监控产品核心指标，建立收益评估体系并输出分析报告。\n\n岗位基本要求\n1. 具备2年以上电商/OTA商户后台相关工作经验，有收益管理或商业化产品背景者优先。  \n2. 熟悉数据分析工具，具备较强的逻辑思维和用户洞察能力。  \n3. 具备良好的沟通能力和跨团队协作能力，能独立推动项目进展。\n\n岗位亮点\n1. 参与核心收益产品建设，直接影响公司营收增长。  \n2. 与行业资深团队共事，快速提升产品专业能力。  \n3. 扁平化管理，拥有充分的自主决策空间。  \n4. 工作地点位于北京核心区域，交通便利，办公环境优越。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4643473277","sourceKey":"meituan_social","company":"美团","title":"景点度假业务-销售和供给运营专家","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4643473277&jobShareType=1","duty":"1. 负责景点度假业务的整体销售运营策略制定与执行，提升业务增长和市场份额。  \n2. 管理并优化供给端资源，包括供应商合作、产品上架及库存管理，确保供给质量与效率。  \n3. 带领团队，推动跨部门协作，提升运营流程标准化与数据驱动决策能力。  \n4. 监控关键业务指标，分析销售与供给数据，输出运营洞察并推动优化方案落地。  \n5. 探索创新运营模式，提升用户体验与商家满意度，支持业务长期可持续发展。","requirements":"1. 大学本科及以上学历，具备5年以上业务运营、销售运营或供给管理经验。  \n2. 熟悉景点度假行业，具备行业供给运营背景者优先。  \n3. 具备较强的数据分析能力，熟练使用SQL等基础数据分析工具。  \n4. 具备优秀的团队管理能力，有带领6人以上团队的经验。  \n5. 工作地点为北京市，能适应跨城市协作与阶段性出差。","description":"部门介绍\n美团酒店旅行业务涵盖酒店、民宿、机票、火车票、旅游度假、景点门票等各类住行游品类，通过与产业上下游的深度合作，为用户提供美好的旅游旅行体验。我们积极打造AI友好型组织，使用AI等新技术提升旅游服务的供需匹配效率，更好满足用户个性化、多样化的出游需求。我们持续深耕产业链，用数字化服务助力实体商家高质量经营，探索自有品牌等供给新模式，打造健康的商家生态，保障用户服务体验。为满足用户日益增长的跨境旅行需求，我们将聚焦亚太区域，打造高品质的住宿、交通、游玩等服务矩阵。\n这里有多元的业务布局、持续的成长空间，无论是向往的远方还是眼前的工作，一路都是风景相伴。加入我们，共同为用户创造旅游旅行中的高光时刻！\n\n岗位职责\n1. 负责景点度假业务的整体销售运营策略制定与执行，提升业务增长和市场份额。  \n2. 管理并优化供给端资源，包括供应商合作、产品上架及库存管理，确保供给质量与效率。  \n3. 带领团队，推动跨部门协作，提升运营流程标准化与数据驱动决策能力。  \n4. 监控关键业务指标，分析销售与供给数据，输出运营洞察并推动优化方案落地。  \n5. 探索创新运营模式，提升用户体验与商家满意度，支持业务长期可持续发展。\n\n岗位基本要求\n1. 大学本科及以上学历，具备5年以上业务运营、销售运营或供给管理经验。  \n2. 熟悉景点度假行业，具备行业供给运营背景者优先。  \n3. 具备较强的数据分析能力，熟练使用SQL等基础数据分析工具。  \n4. 具备优秀的团队管理能力，有带领6人以上团队的经验。  \n5. 工作地点为北京市，能适应跨城市协作与阶段性出差。\n\n岗位亮点\n1. 参与核心业务运营，直接影响业务战略与增长方向。  \n2. 团队规模适中，管理职责明确，具备充分的成长与晋升空间。  \n3. 与行业优质供应商深度合作，积累丰富的资源与行业洞察。  \n4. 扁平化管理氛围，鼓励创新与数据驱动的工作方式。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4100062696","sourceKey":"meituan_social","company":"美团","title":"小象超市-线下门店财务BP","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4100062696&jobShareType=1","duty":"1、财务支持：深入了解业务，与业务伙伴密切合作，建立门店费用管理机制，费用管理分析标准化能力建设。\n2、财务分析：深度参与门店业态的财务健康度评估，包括门店业态的人力成本模型、费用管理模型建设。按期出具多维度的经营分析和财务分析数据，分析和挖掘业务机会点，结合业务特点制定关键业务指标及分析体系，与业务建立双向反馈机制；\n3、财务管理：对业务方案进行风险评估，建立定期的业务和财务数据跟踪体系，做好事前评估、事中跟踪、事后复盘，掌握业务的各环节对成本模型的影响因子；\n4、财务预算：准确编制对应业务的财务预测及年度预算，并协助业务进行预算管理，监督和评估业务的业绩达成；\n5、财务日常工作：与账务、税务和报表团队积极协调，完成其他指定任务；\n6、负责流程优化及财务风险管控。\n7、AI工具应用：积极探索并应用AI工具（如大语言模型、智能分析平台等）提升财务分析效率，推动财务报表、费用分析等工作的智能化升级。","requirements":"1. 本科及以上学历，财务、金融、会计等相关专业\n2. 5年以上财务分析或财务BP经验，有线下零售门店财务经验者优先（连锁零售/生鲜超市/便利店/餐饮等均可）\n3. 熟悉门店P&L结构，有单店盈利模型或开店收益测算实操经验\n4. 具备AI工具使用意识和能力，能熟练使用AI辅助工具（如ChatGPT、Copilot等）提升工作效率。\n5. 具备较强的业务理解力和跨团队沟通能力，能在业务高速变化环境中快速响应\n\n具备以下优先：来自盒马、山姆、沃尔玛、叮咚买菜、朴朴超市、永辉、胖东来等线下零售企业财务团队","description":"部门介绍\n财务平台负责公司整体和各业务层面的财务管理工作，通过建设专业、全面、复合的财务管理能力和与业务经营的紧密结合来支持公司健康发展。目前财务平台拥有财务会计、财务报告、资金管理、税务管理、财务共享、财务系统、规划分析、财务BP和内控内审等主要工作方向。我们的目标是建设业界一流的财务管理能力和经营支持体系，为公司战略的正确落地、投入效率的持续提升、业务价值的不断增长保驾护航。欢迎加入财务平台，携手一起向未来！\n\n岗位职责\n1、财务支持：深入了解业务，与业务伙伴密切合作，建立门店费用管理机制，费用管理分析标准化能力建设。\n2、财务分析：深度参与门店业态的财务健康度评估，包括门店业态的人力成本模型、费用管理模型建设。按期出具多维度的经营分析和财务分析数据，分析和挖掘业务机会点，结合业务特点制定关键业务指标及分析体系，与业务建立双向反馈机制；\n3、财务管理：对业务方案进行风险评估，建立定期的业务和财务数据跟踪体系，做好事前评估、事中跟踪、事后复盘，掌握业务的各环节对成本模型的影响因子；\n4、财务预算：准确编制对应业务的财务预测及年度预算，并协助业务进行预算管理，监督和评估业务的业绩达成；\n5、财务日常工作：与账务、税务和报表团队积极协调，完成其他指定任务；\n6、负责流程优化及财务风险管控。\n7、AI工具应用：积极探索并应用AI工具（如大语言模型、智能分析平台等）提升财务分析效率，推动财务报表、费用分析等工作的智能化升级。\n\n岗位基本要求\n1. 本科及以上学历，财务、金融、会计等相关专业\n2. 5年以上财务分析或财务BP经验，有线下零售门店财务经验者优先（连锁零售/生鲜超市/便利店/餐饮等均可）\n3. 熟悉门店P&L结构，有单店盈利模型或开店收益测算实操经验\n4. 具备AI工具使用意识和能力，能熟练使用AI辅助工具（如ChatGPT、Copilot等）提升工作效率。\n5. 具备较强的业务理解力和跨团队沟通能力，能在业务高速变化环境中快速响应\n\n具备以下优先：来自盒马、山姆、沃尔玛、叮咚买菜、朴朴超市、永辉、胖东来等线下零售企业财务团队\n\n具备以下条件优先\n有线下业态零售工作经验，探索创新能力强\n\n岗位亮点\n1. 深度参与美团小象超市战略级新业态从0到1的财务体系建设，成长空间大\n2. 与门店运营团队高度协同，快速积累零售线下业态的完整财务视角\n3. 开放包容的团队氛围，鼓励数据驱动和创新探索","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4306730933","sourceKey":"meituan_social","company":"美团","title":"内容安全AI产品专家","city":"北京市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4306730933&jobShareType=1","duty":"1.负责设计、推动和执行落地领域垂类人+AI协作工作流落地，提高低水平重复工作端到端自动达成比例。\n2.制定AI for Sercurity的安全策略、标准和流程，跨职能团队合作，将安全能力默认集成到业务运营流程中。\n3.设计量化指标体系和负反馈信号，持续驱动内容安全防控质量良性循环。","requirements":"1.极强的好奇心和动手改变局面的欲望，思维逻辑性较强。\n2.工科，对机器学习/深度学习有基础理解，能与工程师进行高效对话。\n3.对于Agent/Workflow有动手经验和个人见解，善用SOP、Benchmark牵引进展。\n4.具备数据敏感度和分析能力，熟练使用数据分析工具。\n5.有在大型内容平台工作经验者优先。\n6.具备强烈的风险预判和管控意识。\n7.有项目管理经验，具备较强的沟通、协调能力，推动跨部门协作达成共识。","description":"部门介绍\n基础研发平台是美团的核心技术平台，立足于“零售+科技”的战略定位，通过打造人工智能、大数据、云计算、安全等核心技术能力，以及研发效能平台、企业应用平台等公共服务，为业务提供稳定安全、扩展易用、技术领先的平台技术和产品服务。\n在这里，我们会参与到最前沿的技术研发和探索；能够接触超规模集群、海量数据，挑战高复杂业务场景，有机会与业界一流的工程师一起并肩前行。\n在这里，我们有超强的技术氛围，持续向社区贡献业界实践，加速行业技术发展；我们有完善的互联网学习生态圈，重视底层逻辑和方法论，助力职业生涯的非线性成长。\n真诚地邀请你，和我们一起驱动技术发展，创造行业价值。\n\n岗位职责\n1.负责设计、推动和执行落地领域垂类人+AI协作工作流落地，提高低水平重复工作端到端自动达成比例。\n2.制定AI for Sercurity的安全策略、标准和流程，跨职能团队合作，将安全能力默认集成到业务运营流程中。\n3.设计量化指标体系和负反馈信号，持续驱动内容安全防控质量良性循环。\n\n岗位基本要求\n1.极强的好奇心和动手改变局面的欲望，思维逻辑性较强。\n2.工科，对机器学习/深度学习有基础理解，能与工程师进行高效对话。\n3.对于Agent/Workflow有动手经验和个人见解，善用SOP、Benchmark牵引进展。\n4.具备数据敏感度和分析能力，熟练使用数据分析工具。\n5.有在大型内容平台工作经验者优先。\n6.具备强烈的风险预判和管控意识。\n7.有项目管理经验，具备较强的沟通、协调能力，推动跨部门协作达成共识。\n\n具备以下条件优先\n垂直场景AI落地经验\n大模型安全防护经验\n境外内容安全经验\n\n岗位亮点\n1.我们有开放、直接的工作氛围，以逻辑和事实说话，而不是岗位级别和层级，我们尊重知识和常识。\n2.我们有核心的业务场景，你可以全身心地投入安全+人工智能的时代浪潮中，建设业界卓越的内容安全解决方案。\n3.内容安全识别是复杂的认知理解问题，涉及模式识别、逻辑推理、认知决策等具体任务。内容安全业务仍将长期处于机器智能与领域专家伴生的阶段，如何处理场景内人机协同问题，需要结合具体场景归纳/演绎并试错。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3852641829","sourceKey":"meituan_social","company":"美团","title":"大模型应用算法工程师 - 商业分析智能体 (BA Agent)","city":"北京市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3852641829&jobShareType=1","duty":"主导BA Agent 核心能力构建：作为核心成员，你将定义并主导包括自助取数、多维分析、归因洞察、智能可视化等关键模块的技术路径。你不仅是算法的实现者，更是产品能力的塑造者。\n\n驱动前沿技术探索与落地：针对商业分析中的复杂推理、自主规划和工具使用等挑战，你将主导在多智能体协作（Multi-Agent）、强化学习（AgentRL）、代码生成（AI Coding）等方向上的探索和应用，构建技术壁垒。\n\n定义并刷新业界SoTA：你将负责设计并执行严谨的算法实验，不仅要量化地超越现有解决方案，更要与团队一起，持续刷新商业分析领域的人工智能技术边界。\n\n构建高效能分析系统：你将深入理解业务，与产品、业务分析师紧密合作，将前沿算法沉淀为稳定、高效的系统级解决方案，真正实现“AI赋能业务，降低决策门槛”的目标。","requirements":"计算机、人工智能、数学等相关专业硕士及以上学历，3年以上相关领域研发经验。\n\n深厚的商业数据理解力：对商业分析、数据仓库、BI等领域有深刻理解或浓厚兴趣，能够快速将模糊的业务问题转化为清晰的、可量化的技术任务。\n\n扎实的大模型与AI算法功底：熟悉主流大语言模型的原理与应用，具备丰富的Prompt Engineering、Post-Traning经验；在以下至少一个领域有深入的实践和落地经验：NL2SQL、RAG、Function Calling、Code Generation、Agent模型（规划、推理、工具使用）。\n\n卓越的工程与问题解决能力：具备优秀的算法设计和端到端实现能力，能owner从需求分析到模型上线评估的全链路。有顶会（NeurIPS/ICML/ICLR/ACL等）发表者是加分项。\n\n优秀的合作与沟通能力：你将是连接业务、产品和工程的桥梁，需要清晰地沟通技术方案，并高效协作。","description":"部门介绍\n基础研发平台是美团的核心技术平台，立足于“零售+科技”的战略定位，通过打造人工智能、大数据、云计算、安全等核心技术能力，以及研发效能平台、企业应用平台等公共服务，为业务提供稳定安全、扩展易用、技术领先的平台技术和产品服务。\n在这里，我们会参与到最前沿的技术研发和探索；能够接触超规模集群、海量数据，挑战高复杂业务场景，有机会与业界一流的工程师一起并肩前行。\n在这里，我们有超强的技术氛围，持续向社区贡献业界实践，加速行业技术发展；我们有完善的互联网学习生态圈，重视底层逻辑和方法论，助力职业生涯的非线性成长。\n真诚地邀请你，和我们一起驱动技术发展，创造行业价值。\n\n岗位职责\n主导BA Agent 核心能力构建：作为核心成员，你将定义并主导包括自助取数、多维分析、归因洞察、智能可视化等关键模块的技术路径。你不仅是算法的实现者，更是产品能力的塑造者。\n\n驱动前沿技术探索与落地：针对商业分析中的复杂推理、自主规划和工具使用等挑战，你将主导在多智能体协作（Multi-Agent）、强化学习（AgentRL）、代码生成（AI Coding）等方向上的探索和应用，构建技术壁垒。\n\n定义并刷新业界SoTA：你将负责设计并执行严谨的算法实验，不仅要量化地超越现有解决方案，更要与团队一起，持续刷新商业分析领域的人工智能技术边界。\n\n构建高效能分析系统：你将深入理解业务，与产品、业务分析师紧密合作，将前沿算法沉淀为稳定、高效的系统级解决方案，真正实现“AI赋能业务，降低决策门槛”的目标。\n\n岗位基本要求\n计算机、人工智能、数学等相关专业硕士及以上学历，3年以上相关领域研发经验。\n\n深厚的商业数据理解力：对商业分析、数据仓库、BI等领域有深刻理解或浓厚兴趣，能够快速将模糊的业务问题转化为清晰的、可量化的技术任务。\n\n扎实的大模型与AI算法功底：熟悉主流大语言模型的原理与应用，具备丰富的Prompt Engineering、Post-Traning经验；在以下至少一个领域有深入的实践和落地经验：NL2SQL、RAG、Function Calling、Code Generation、Agent模型（规划、推理、工具使用）。\n\n卓越的工程与问题解决能力：具备优秀的算法设计和端到端实现能力，能owner从需求分析到模型上线评估的全链路。有顶会（NeurIPS/ICML/ICLR/ACL等）发表者是加分项。\n\n优秀的合作与沟通能力：你将是连接业务、产品和工程的桥梁，需要清晰地沟通技术方案，并高效协作。\n\n岗位亮点\n一流业务场景驱动：你将直接面对国内最复杂、最前沿的商业分析挑战，处理海量、高维的真实商业数据，你的工作成果将直接影响核心业务决策，创造巨大的商业价值。\n\n开创性技术探索：我们鼓励在Agent领域的探索和创新，挑战技术无人区。我们不仅提供充足的GPU算力，更提供开放、敢于试错的创新文化。\n\n清晰的成长路径与影响力：你将作为早期核心成员，深度参与产品的从1到N，有机会成长为该方向的技术负责人。你的工作不仅是写代码，更是定义未来商业智能的形态。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4629344712","sourceKey":"meituan_social","company":"美团","title":"Fulfillment Capacity Strategy Expert运力运营专家","city":"圣保罗","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4629344712&jobShareType=1","duty":"1. Be responsible for fulfillment capacity levels; design capacity models tailored to different stages of business development; set capacity targets based on order volume forecasts; and develop capacity growth and retention strategies;\n2. Be responsible for the quality of fulfillment capacity; design capacity management rules in line with business development needs; develop solutions for issues such as rider attendance, equipment, order refusals, handling of delivery anomalies, and management of rider-initiated cancellation reasons; collaborate with relevant stakeholders to drive implementation of these solutions and establish a competitive advantage in capacity quality;\n3. Be responsible for fulfillment costs; within the constraints of user experience, leverage strategies such as scheduling, pricing, and ETA coordination in conjunction with capacity models to improve delivery labor efficiency and optimize fulfillment costs;\n4. Oversee operational activities supporting strategy implementation, such as market research, frontline engagement, and information coordination.","requirements":"Basic Requirements: Bachelor’s degree or higher.\n\nExperience: 3+ years of relevant experience in internet platform operations, strategy analysis, or the logistics and delivery industry. Candidates with experience in strategy operations or workforce management for O2O, on-demand delivery, e-commerce logistics, or ride-hailing platforms are preferred.\n\nCore Competencies:\n1. Data-Driven: Excellent data analysis skills and data sensitivity; proficient in using tools such as SQL to identify issues and validate strategies through data;\n2. Logical and Systematic Thinking: Clear logical thinking and systematic problem-solving abilities; capable of breaking down complex business problems and designing actionable solutions;\n3. Project Management and Collaboration: Outstanding cross-departmental communication and collaboration skills; able to effectively coordinate resources across product, technology, marketing, and other teams to ensure project goals are met;\n4. Ownership Mindset and Resilience: Takes ownership of business outcomes, possesses strong self-motivation, and is capable of solving problems in fast-paced, uncertain environments.","description":"部门介绍\nKeeta是全球领先外卖平台美团旗下的独立品牌，肩负着“帮大家吃得更好，生活更好”的使命。依托美团深耕中国市场15年的技术与运营积淀，我们正引领全球餐饮与商品即时配送服务的创新与发展。\n\n自2023年成立以来，Keeta始终扎根社区并创造价值。我们为用户提供可靠的外卖体验，以智慧技术助餐厅提升经营效率，在为骑手拓宽收入来源的同时，也充分提供安全保障措施。基于这份多方共赢、共同成长的理念，我们的业务已从中国香港稳步拓展至中东及巴西，并持续向世界迈进。\n\n岗位职责\n1. Be responsible for fulfillment capacity levels; design capacity models tailored to different stages of business development; set capacity targets based on order volume forecasts; and develop capacity growth and retention strategies;\n2. Be responsible for the quality of fulfillment capacity; design capacity management rules in line with business development needs; develop solutions for issues such as rider attendance, equipment, order refusals, handling of delivery anomalies, and management of rider-initiated cancellation reasons; collaborate with relevant stakeholders to drive implementation of these solutions and establish a competitive advantage in capacity quality;\n3. Be responsible for fulfillment costs; within the constraints of user experience, leverage strategies such as scheduling, pricing, and ETA coordination in conjunction with capacity models to improve delivery labor efficiency and optimize fulfillment costs;\n4. Oversee operational activities supporting strategy implementation, such as market research, frontline engagement, and information coordination.\n\n岗位基本要求\nBasic Requirements: Bachelor’s degree or higher.\n\nExperience: 3+ years of relevant experience in internet platform operations, strategy analysis, or the logistics and delivery industry. Candidates with experience in strategy operations or workforce management for O2O, on-demand delivery, e-commerce logistics, or ride-hailing platforms are preferred.\n\nCore Competencies:\n1. Data-Driven: Excellent data analysis skills and data sensitivity; proficient in using tools such as SQL to identify issues and validate strategies through data;\n2. Logical and Systematic Thinking: Clear logical thinking and systematic problem-solving abilities; capable of breaking down complex business problems and designing actionable solutions;\n3. Project Management and Collaboration: Outstanding cross-departmental communication and collaboration skills; able to effectively coordinate resources across product, technology, marketing, and other teams to ensure project goals are met;\n4. Ownership Mindset and Resilience: Takes ownership of business outcomes, possesses strong self-motivation, and is capable of solving problems in fast-paced, uncertain environments.\n\n岗位亮点\n1. Participate in core product operations and directly influence the product development direction.\n2. Flat management structure with ample autonomy in decision-making.\n3. International work environment, growing alongside a multicultural team.\n4. Comprehensive career development paths and training resources provided.","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4663352268","sourceKey":"meituan_social","company":"美团","title":"库存优化专家","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4663352268&jobShareType=1","duty":"1、基于自营库存供应链视角，制定订货和库存解决方案，优化周转和缺货率指标、提升供应链运营效率；包含但不限于多级仓网订货模型设计、采购合理性优化等；\n2、基于商和仓结构，制定进向成本优化方案，从成本视角建模库存品周转和链路优化模型；\n3、与物流/产研协同，提升调拨、清滞、退供、采购的自动化效率及合理性，不断提升供应链效率；\n4、上级安排的其他工作。","requirements":"1、本科学历及以上，供应链、物流、工业工程等相关专业优先；\n2、5年以上供应链规划和解决方案相关经验，对零售全链条有深刻认知，了解商品周转及流通业态；\n3、有良好的思维逻辑和策略规划能力，能有效提炼供应链的核心痛点并提供解决方案，良好的沟通协作能力，能将解决方案协同各方快速落地；\n4、具备数据处理能力，如熟练应用SQL、AI等工具。","description":"部门介绍\n快驴进货是美团旗下的餐饮供应链平台，帮助餐饮商户以更低成本、更高效率来获取安全可靠的食材供应，让餐饮采购更简单。快驴进货同步发展“自营+平台”的业务模式，在采购环节一方面向上游供应商直采大宗商品，另一方面引入各地批发商，助力平台伙伴共同发展；在销售环节既有自建团队进行市场、客户拓展，又帮助各地批发商拓展业务；同时自建仓储管理系统、配送网络与团队，为客户提供优质履约服务。\n截至2022年，快驴进货布局了全国41个城市，为百万家商户提供“全、省、稳、好”的餐饮供应链服务。我们拥有3000+品牌食材、超5万SKU商品、超28万商品资质，并提供源头严审核、食品安全严把关、24小时无忧售后的全面保障，实现手机下单、送货上门的高效采购模式，帮百万商家节省了采购时间与成本，助力平台伙伴共同发展，在万亿市场共享机遇。\n在这里，你将收获完善的员工发展机制及学习体系，与各界专家一起深度参与餐饮供应链业务的发展。欢迎优秀的你加入美团快驴进货，与我们一起成长，一起更好！\n\n岗位职责\n1、基于自营库存供应链视角，制定订货和库存解决方案，优化周转和缺货率指标、提升供应链运营效率；包含但不限于多级仓网订货模型设计、采购合理性优化等；\n2、基于商和仓结构，制定进向成本优化方案，从成本视角建模库存品周转和链路优化模型；\n3、与物流/产研协同，提升调拨、清滞、退供、采购的自动化效率及合理性，不断提升供应链效率；\n4、上级安排的其他工作。\n\n岗位基本要求\n1、本科学历及以上，供应链、物流、工业工程等相关专业优先；\n2、5年以上供应链规划和解决方案相关经验，对零售全链条有深刻认知，了解商品周转及流通业态；\n3、有良好的思维逻辑和策略规划能力，能有效提炼供应链的核心痛点并提供解决方案，良好的沟通协作能力，能将解决方案协同各方快速落地；\n4、具备数据处理能力，如熟练应用SQL、AI等工具。\n\n岗位亮点\n1.全面供应链视角，业务发挥空间大，团队氛围好；\n2.BU级重点项目，能从全链路视角看业务发展。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4640348001","sourceKey":"meituan_social","company":"美团","title":"预测算法工程师","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4640348001&jobShareType=1","duty":"1. 负责美团骑行换电&资产管理核心业务中的预测算法设计与落地，包括但不限于骑行耗电量预测、换电价值预测、基于多模态大模型与计算机视觉的车辆故障识别等\n\n2. 参与换电&资产预测算法体系搭建，抽象并定义算法问题、算法技术选型、模型搭建、落地推广应用，实现业务效果提升\n\n3. 深入了解业务，与产品、工程、数据、业务团队密切合作，持续推动从算法技术到业务价值的转化，驱动业务变革\n\n4. 构建骑行换电&资产智能感知与预测算法体系，综合运用机器学习、深度学习、时序预测、多模态大模型等技术，提升资产状态预测精度与故障识别准确率，驱动资产利用率提升与资产成本优化","requirements":"岗位基本需求\n\n1. 计算机、数学、自动化等相关专业，在机器学习、深度学习、时序预测、计算机视觉、多模态大模型等至少一个领域有深入积累\n\n2. 熟悉常用的预测模型算法，具备良好的编码习惯和工程能力\n\n3. 具备良好的业务理解、问题定义、沟通和合作能力，能够与各个团队紧密合作，解决问题 \n\n4. 善于分析和发现问题，具备较强的自驱力，有强烈的学习意愿和创新精神，对算法技术有浓厚的兴趣和热情\n\n5. 具备较强的自我驱动力和学习能力，了解常用 AI Coding 工作范式、方法论等","description":"部门介绍\n美团的使命是“帮大家吃得更好，生活更好”，公司聚焦“零售 + 科技”战略，和广大商户与各类合作伙伴一起，努力为消费者提供品质生活，推动商品零售和服务零售在需求侧和供给侧的数字化转型。\n2018年9月20日，美团正式在港交所挂牌上市。美团将始终坚持以客户为中心，不断加大在科技研发方面的投入，更好承担社会责任，更多创造社会价值，与广大合作伙伴一起发展共赢。\n\n岗位职责\n1. 负责美团骑行换电&资产管理核心业务中的预测算法设计与落地，包括但不限于骑行耗电量预测、换电价值预测、基于多模态大模型与计算机视觉的车辆故障识别等\n\n2. 参与换电&资产预测算法体系搭建，抽象并定义算法问题、算法技术选型、模型搭建、落地推广应用，实现业务效果提升\n\n3. 深入了解业务，与产品、工程、数据、业务团队密切合作，持续推动从算法技术到业务价值的转化，驱动业务变革\n\n4. 构建骑行换电&资产智能感知与预测算法体系，综合运用机器学习、深度学习、时序预测、多模态大模型等技术，提升资产状态预测精度与故障识别准确率，驱动资产利用率提升与资产成本优化\n\n岗位基本要求\n岗位基本需求\n\n1. 计算机、数学、自动化等相关专业，在机器学习、深度学习、时序预测、计算机视觉、多模态大模型等至少一个领域有深入积累\n\n2. 熟悉常用的预测模型算法，具备良好的编码习惯和工程能力\n\n3. 具备良好的业务理解、问题定义、沟通和合作能力，能够与各个团队紧密合作，解决问题 \n\n4. 善于分析和发现问题，具备较强的自驱力，有强烈的学习意愿和创新精神，对算法技术有浓厚的兴趣和热情\n\n5. 具备较强的自我驱动力和学习能力，了解常用 AI Coding 工作范式、方法论等\n\n具备以下条件优先\n有多模态大模型、图像识别相关项目经验者优先\n\n岗位亮点\n1.业务规模大：百万级骑行资产、日均千万级运维数据，覆盖故障感知、健康预测、智能派单的全过程算法触点场景，技术落地与业务闭环紧密。 \n\n2.技术纵深广：融合机器学习、深度学习、计算机视觉、多模态大模型等多技术栈，技术挑战丰富，从感知识别到决策优化的完整算法链路均有深入探索空间。 \n\n3.战略级定位：深度参与公司核心资产运营效率提升的关键方向，目标空间大，协同资源丰富，个人业务与技术成长路径清晰。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4616193691","sourceKey":"meituan_social","company":"美团","title":"Keemart 供应链全栈研发工程师","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4616193691&jobShareType=1","duty":"1、负责食杂零售海外供应链相关产品的全栈研发工作，覆盖前后端的需求评审、系统设计、开发与技术运维。\n2、负责供应链业务的需求分析与评审，识别潜在业务问题，提出建设性解决方案，助力业务达成业绩目标。\n3、负责供应链系统的持续优化，能够识别系统问题、持续简化，保持系统简洁有序。\n4、负责新兴技术的调研与实践，基于业务场景建设相关 Agent（如业务运营 Agent、研发运维 Agent），提升业务运营与研发效率。","requirements":"1、扎实的前后端基本功，熟练掌握后端开发语言（如 Java）和前端开发语言（如 JavaScript）；熟悉 MySQL、Redis、RPC、消息队列、React等常用中间件与技术栈。\n2、理解大模型原理及常见模型特性，熟悉 RAG、Agent、Skills 等技术组件，熟悉主流 AI Coding 工具链（如 Cursor、Claude Code 等）。\n3、精通 AI Coding，具备 Spec Coding、Harness Engineering、构建知识库等实践经验。\n4、熟悉常用业务架构设计，具备良好的编程能力与代码风格，对模块化编程有较深理解。\n5、具备复杂领域的系统设计经验，深度参与系统架构设计、开发、维护、升级等全过程。\n6、具备良好的业务理解与逻辑思维能力，能够发现业务问题并积极推动解决。\n7、具备良好的沟通协调能力，能够协同上下游快速达成目标。","description":"部门介绍\n美团的使命是“帮大家吃得更好，生活更好”，公司聚焦“零售 + 科技”战略，和广大商户与各类合作伙伴一起，努力为消费者提供品质生活，推动商品零售和服务零售在需求侧和供给侧的数字化转型。\n2018年9月20日，美团正式在港交所挂牌上市。美团将始终坚持以客户为中心，不断加大在科技研发方面的投入，更好承担社会责任，更多创造社会价值，与广大合作伙伴一起发展共赢。\n\n岗位职责\n1、负责食杂零售海外供应链相关产品的全栈研发工作，覆盖前后端的需求评审、系统设计、开发与技术运维。\n2、负责供应链业务的需求分析与评审，识别潜在业务问题，提出建设性解决方案，助力业务达成业绩目标。\n3、负责供应链系统的持续优化，能够识别系统问题、持续简化，保持系统简洁有序。\n4、负责新兴技术的调研与实践，基于业务场景建设相关 Agent（如业务运营 Agent、研发运维 Agent），提升业务运营与研发效率。\n\n岗位基本要求\n1、扎实的前后端基本功，熟练掌握后端开发语言（如 Java）和前端开发语言（如 JavaScript）；熟悉 MySQL、Redis、RPC、消息队列、React等常用中间件与技术栈。\n2、理解大模型原理及常见模型特性，熟悉 RAG、Agent、Skills 等技术组件，熟悉主流 AI Coding 工具链（如 Cursor、Claude Code 等）。\n3、精通 AI Coding，具备 Spec Coding、Harness Engineering、构建知识库等实践经验。\n4、熟悉常用业务架构设计，具备良好的编程能力与代码风格，对模块化编程有较深理解。\n5、具备复杂领域的系统设计经验，深度参与系统架构设计、开发、维护、升级等全过程。\n6、具备良好的业务理解与逻辑思维能力，能够发现业务问题并积极推动解决。\n7、具备良好的沟通协调能力，能够协同上下游快速达成目标。\n\n具备以下条件优先\n1、有 Agent/ CLI/浏览器自动化技术（如 Playwright、CDP）工具链开发经验者优先。\n2、有 Prompt Engineering、RAG 系统设计深度实践经验者优先。\n3、有供应商、供应链计划、单据管理、库存管理等相关领域研发经验者优先。\n\n岗位亮点\n1、能和物流、数仓、算法、库存、商品等多元化背景的技术团队一起，共同学习、共同进步。\n2、有机会全身心的参与境外即时零售业态，能在急速发展的业务当中，提升对即时零售供应链的理解，构建完整的供应链图景。\n3、有机会搭建适配海外供应链业务的相关 Agent，通过 AI 重塑供应链业务流程。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4634851776","sourceKey":"meituan_social","company":"美团","title":"食杂零售出海-物流全栈研发工程师","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4634851776&jobShareType=1","duty":"1.负责食杂零售出海业务物流系统的全栈设计与开发，涵盖前端、后端及数据库架构。  \n2.参与物流核心模块的需求分析、技术方案设计与系统优化，保障高可用与可扩展性。\n3.与产品、运营及海外团队协作，推动物流系统在全球多区域的落地与迭代。  \n4.编写高质量、可维护的代码，完成单元测试与系统集成，确保交付质量。\n5.持续关注技术发展趋势，探索并引入适合业务场景的新技术与工具。","requirements":"1.大学本科及以上学历，计算机相关专业优先。\n2.有2年以上系统研发经验，有1年以上AI相关开发经验，熟悉物流业务流程。\n3.具备良好的团队协作能力，能够有效协同团队成员合作完成项目。\n4.理解大模型原理及常见模型特性，深入理解RAG、Agent、Skills 等技术组件，熟练使用主流 AI Coding 工具链（如 Cursor、Claude Code 等）。\n5.精通 AI Coding，具备 Spec Coding、Harness Engineering、知识库构建等实践经验。\n6.具备全栈开发能力，前后端基本功扎实，熟练掌握java、android、JavaScript等前后端开发语言。\n7.熟悉分布式系统、微服务架构及常见中间件（如Redis、Kafka、MySQL等）。\n8.具备良好的沟通能力和团队协作精神，能独立承担模块开发与问题排查。","description":"部门介绍\n美团的使命是“帮大家吃得更好，生活更好”，公司聚焦“零售 + 科技”战略，和广大商户与各类合作伙伴一起，努力为消费者提供品质生活，推动商品零售和服务零售在需求侧和供给侧的数字化转型。\n2018年9月20日，美团正式在港交所挂牌上市。美团将始终坚持以客户为中心，不断加大在科技研发方面的投入，更好承担社会责任，更多创造社会价值，与广大合作伙伴一起发展共赢。\n\n岗位职责\n1.负责食杂零售出海业务物流系统的全栈设计与开发，涵盖前端、后端及数据库架构。  \n2.参与物流核心模块的需求分析、技术方案设计与系统优化，保障高可用与可扩展性。\n3.与产品、运营及海外团队协作，推动物流系统在全球多区域的落地与迭代。  \n4.编写高质量、可维护的代码，完成单元测试与系统集成，确保交付质量。\n5.持续关注技术发展趋势，探索并引入适合业务场景的新技术与工具。\n\n岗位基本要求\n1.大学本科及以上学历，计算机相关专业优先。\n2.有2年以上系统研发经验，有1年以上AI相关开发经验，熟悉物流业务流程。\n3.具备良好的团队协作能力，能够有效协同团队成员合作完成项目。\n4.理解大模型原理及常见模型特性，深入理解RAG、Agent、Skills 等技术组件，熟练使用主流 AI Coding 工具链（如 Cursor、Claude Code 等）。\n5.精通 AI Coding，具备 Spec Coding、Harness Engineering、知识库构建等实践经验。\n6.具备全栈开发能力，前后端基本功扎实，熟练掌握java、android、JavaScript等前后端开发语言。\n7.熟悉分布式系统、微服务架构及常见中间件（如Redis、Kafka、MySQL等）。\n8.具备良好的沟通能力和团队协作精神，能独立承担模块开发与问题排查。\n\n具备以下条件优先\n1.有AI项目背景优先;\n2.有物流相关领域研发经验者优先。\n\n岗位亮点\n1.参与全球化业务，深入理解海外物流场景，拓展国际视野。  \n2. 技术挑战性强，涉及高并发、多时区、多语言等复杂系统设计。  \n3. 扁平化管理，快速成长通道，与资深技术团队共同攻坚业务难题。  \n4.有机会全身心的参与新零售业态，能在急速发展的B端业务当中，从0到1的建立对B端业务的认知，构建完整的宏观图景。和团队一起对供应链、采销、仓配等行业技能进行全新的升级、再造。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4348546620","sourceKey":"meituan_social","company":"美团","title":"AI算法工程师-大模型搜推应用","city":"北京市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4348546620&jobShareType=1","duty":"1. 负责食杂零售搜推算法策略迭代，优化用户搜推体验，提升点击率、转化率等核心指标\n2. 应用先进技术手段，优化意图理解、召回、搜索相关性、排序、流量调控等算法模块效果，显著提升用户体验和转化效率\n3. 紧跟业界大模型、agent 前沿进展，积极学习新的模型结构和 agent 认知，探索在食杂业务落地的可能性\n4. 与其他团队密切合作，实现高质量的产品和解决方案。","requirements":"1、拥有计算机、电子、通信、数学、统计学或相关专业的本科及以上学历，具备3年及以上工作经验\n2、具备大规模深度学习、生成式模型训练开发实际经验，搜推及大模型算法专业能力扎实，善于将技术能力应用于用户需求解决\n3、具有较强的团队协作能力和沟通能力，有较好的责任意识，能独立负责单一模块能力建设与升级，同各模块各职能方向负责人协同共建。","description":"部门介绍\n美团的使命是“帮大家吃得更好，生活更好”，公司聚焦“零售 + 科技”战略，和广大商户与各类合作伙伴一起，努力为消费者提供品质生活，推动商品零售和服务零售在需求侧和供给侧的数字化转型。\n2018年9月20日，美团正式在港交所挂牌上市。美团将始终坚持以客户为中心，不断加大在科技研发方面的投入，更好承担社会责任，更多创造社会价值，与广大合作伙伴一起发展共赢。\n\n岗位职责\n1. 负责食杂零售搜推算法策略迭代，优化用户搜推体验，提升点击率、转化率等核心指标\n2. 应用先进技术手段，优化意图理解、召回、搜索相关性、排序、流量调控等算法模块效果，显著提升用户体验和转化效率\n3. 紧跟业界大模型、agent 前沿进展，积极学习新的模型结构和 agent 认知，探索在食杂业务落地的可能性\n4. 与其他团队密切合作，实现高质量的产品和解决方案。\n\n岗位基本要求\n1、拥有计算机、电子、通信、数学、统计学或相关专业的本科及以上学历，具备3年及以上工作经验\n2、具备大规模深度学习、生成式模型训练开发实际经验，搜推及大模型算法专业能力扎实，善于将技术能力应用于用户需求解决\n3、具有较强的团队协作能力和沟通能力，有较好的责任意识，能独立负责单一模块能力建设与升级，同各模块各职能方向负责人协同共建。\n\n具备以下条件优先\n1、有过大模型应用经验，Agent落地，大模型预训练等经验，尤其生成式搜索、生成式推荐等相关项目经验者的优先；\n2、在国际顶会或核心期刊上发表过学术论文。\n\n岗位亮点\n1.团队业务紧跟公司的业务目标，每一次策略迭代都能给公司的业务目标带来具体的价值，实现自我价值和个人成就感。\n2.团队成员大多来自于名校和名企，在这里有机会学习、尝试和落地业界先进技术。\n3.业务处于快速发展阶段，能够为个人提供了快速成长的空间，拥有自主迭代的决策权，更好地实现创新。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4092225251","sourceKey":"meituan_social","company":"美团","title":"AI算法专家-供应链物流方向","city":"北京市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4092225251&jobShareType=1","duty":"1、负责美团食杂零售预测、供应链算法研发与建设，支持小象超市、快乐猴超市、快驴进货、Keemart等多个业态的供应链智能化运营。\n2、综合运用深度学习、运筹优化、大模型等前沿技术，针对供应链全链路复杂场景（包括但不限于需求预测、库存优化、履约调度、时效预测等）构建算法方案，持续提升供应链的智能化和自动化水平，提升效率、降低成本、优化用户体验。\n3、在运筹优化、机器学习/深度学习、大模型应用等算法领域持续探索与创新，沉淀通用算法能力，推进算法平台化建设，提升研发效率。\n4、深入理解零售、供应链业务逻辑和运营模式，与业务、产品、工程、数据等团队紧密协同，完成从业务问题到算法问题的抽象与定义，设计指标体系，进行算法技术选型和方案设计实现，推动落地应用。\n5、参与项目管理、团队建设，通过Code Review、技术分享、技术方案评审等方式，提升团队整体算法与工程能力，营造良好的技术氛围。","requirements":"1、硕士及以上学历，运筹优化、人工智能、计算机、自动化等相关专业；熟练掌握运筹优化、机器学习/深度学习、大模型应用中至少一个方向的算法知识体系；具有2年以上电商、零售、互联网相关领域算法研发落地经验。\n2、编程基础扎实，具备良好的程序设计能力与代码规范意识，熟练掌握Python，熟悉常用机器学习/深度学习框架（例如TensorFlow/PyTorch/XGBoost等），运筹优化建模框架（例如ortools）。\n3、熟练使用Spark等大数据处理框架，具备在大规模数据场景下进行数据处理、特征构建、模型训练与调优的能力。\n4、对零售、电商及供应链领域有热情，持续关注行业发展趋势，能主动思考业务模式与技术结合的创新点，具备良好的业务洞察力和数据分析能力。\n5、具备良好的沟通表达、跨团队协作能力和结果导向意识，能够在复杂多方协同的环境下推动项目落地。","description":"部门介绍\n美团的使命是“帮大家吃得更好，生活更好”，公司聚焦“零售 + 科技”战略，和广大商户与各类合作伙伴一起，努力为消费者提供品质生活，推动商品零售和服务零售在需求侧和供给侧的数字化转型。\n2018年9月20日，美团正式在港交所挂牌上市。美团将始终坚持以客户为中心，不断加大在科技研发方面的投入，更好承担社会责任，更多创造社会价值，与广大合作伙伴一起发展共赢。\n\n岗位职责\n1、负责美团食杂零售预测、供应链算法研发与建设，支持小象超市、快乐猴超市、快驴进货、Keemart等多个业态的供应链智能化运营。\n2、综合运用深度学习、运筹优化、大模型等前沿技术，针对供应链全链路复杂场景（包括但不限于需求预测、库存优化、履约调度、时效预测等）构建算法方案，持续提升供应链的智能化和自动化水平，提升效率、降低成本、优化用户体验。\n3、在运筹优化、机器学习/深度学习、大模型应用等算法领域持续探索与创新，沉淀通用算法能力，推进算法平台化建设，提升研发效率。\n4、深入理解零售、供应链业务逻辑和运营模式，与业务、产品、工程、数据等团队紧密协同，完成从业务问题到算法问题的抽象与定义，设计指标体系，进行算法技术选型和方案设计实现，推动落地应用。\n5、参与项目管理、团队建设，通过Code Review、技术分享、技术方案评审等方式，提升团队整体算法与工程能力，营造良好的技术氛围。\n\n岗位基本要求\n1、硕士及以上学历，运筹优化、人工智能、计算机、自动化等相关专业；熟练掌握运筹优化、机器学习/深度学习、大模型应用中至少一个方向的算法知识体系；具有2年以上电商、零售、互联网相关领域算法研发落地经验。\n2、编程基础扎实，具备良好的程序设计能力与代码规范意识，熟练掌握Python，熟悉常用机器学习/深度学习框架（例如TensorFlow/PyTorch/XGBoost等），运筹优化建模框架（例如ortools）。\n3、熟练使用Spark等大数据处理框架，具备在大规模数据场景下进行数据处理、特征构建、模型训练与调优的能力。\n4、对零售、电商及供应链领域有热情，持续关注行业发展趋势，能主动思考业务模式与技术结合的创新点，具备良好的业务洞察力和数据分析能力。\n5、具备良好的沟通表达、跨团队协作能力和结果导向意识，能够在复杂多方协同的环境下推动项目落地。\n\n具备以下条件优先\n1、有零售供应链算法研发经验，在需求预测、库存优化、履约调度、时效预测等方向具备一定的行业经验。\n2、在深度学习、运筹优化等领域有深入研究，作为核心作者在国际一流会议或期刊发表过相关论文者优先。\n3、有带领或指导小团队完成复杂算法项目的经验，具备一定的技术领导力。\n\n岗位亮点\n1、美团坚持“零售+科技”的长期战略定位，零售业务高速发展，目前正处于供应链智能化升级的关键时期，为算法创新和价值落地提供了广阔空间。\n2、团队氛围简单、纯粹、务实，有激情，团队成员来自海内外一流高校及科研院所，鼓励技术交流，学习成长机会丰富。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4629397876","sourceKey":"meituan_social","company":"美团","title":"资源收益管理分析师","city":"上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4629397876&jobShareType=1","duty":"1、基于业务目标要求，制定长短期补贴/渠道市场预算投入规划，统筹各类资源策略保障规划落地；\n2、剖析用户交易行为，洞察不同补贴工具/补贴项目对交易增长的驱动作用，调优补贴分配，牵引业务策略迭代；\n3、负责各类资源项目的效率评估，关注新工具的潜力，找到高效投入的机会点；\n4、参与重要补贴及营销项目的目标制定、效率及效果评估，推动项目落地和策略调优；\n5、积极探索利用AI工具进行日常各项分析工作。","requirements":"1. 本科及以上学历；\n2. 商业和业务逻辑敏感，具备良好的逻辑分析能力和系统性思维能力，良好的跨团队沟通能力；\n3. 擅长sql或python，有良好的AI运用能力优先。\n4. 2年及以上相关工作经验，有补贴/渠道/用户策略、本地生活行业相关经验优先","description":"部门介绍\n美团服务零售事业部下设乐生活业务部、易生活业务部、进场零售业务部以及中小城市发展部四大业务部门，旨在通过提供丰富、可靠、实惠的服务与商品满足用户各类生活需求。我们所处的服务零售行业是一个具有万亿规模的市场，覆盖足疗洗浴、酒吧KTV、运动健身、美发美甲、教育培训、亲子游乐、家政洗涤维修、摄影写真等数十个服务消费细分领域，同时延伸至超市便利、美妆个护、3C数码、服饰珠宝、运动户外、商场购物中心等实体零售到店消费场景，连接数十万品牌商户与线下门店。作为商家和行业的小帮手，我们持续深入服务零售与实体零售产业链，用AI等技术推动行业变革，帮助商家提升经营效率、实现高效的线上化经营与到店转化，优化消费者服务体验，提供安心、放心的履约保障。这里有着多元的业务布局，有着富有挑战和影响力的工作内容，为你提供丰富的视野、持续的成长和发展机会，引领你发现更多可能。期待和你在“随时随地，美好生活”的愿景指引下，共建美好的生活服务体验、健康的商家生态与高质量的经营结果。\n\n岗位职责\n1、基于业务目标要求，制定长短期补贴/渠道市场预算投入规划，统筹各类资源策略保障规划落地；\n2、剖析用户交易行为，洞察不同补贴工具/补贴项目对交易增长的驱动作用，调优补贴分配，牵引业务策略迭代；\n3、负责各类资源项目的效率评估，关注新工具的潜力，找到高效投入的机会点；\n4、参与重要补贴及营销项目的目标制定、效率及效果评估，推动项目落地和策略调优；\n5、积极探索利用AI工具进行日常各项分析工作。\n\n岗位基本要求\n1. 本科及以上学历；\n2. 商业和业务逻辑敏感，具备良好的逻辑分析能力和系统性思维能力，良好的跨团队沟通能力；\n3. 擅长sql或python，有良好的AI运用能力优先。\n4. 2年及以上相关工作经验，有补贴/渠道/用户策略、本地生活行业相关经验优先\n\n岗位亮点\n岗位业务接触面较宽，有机会参与业务战略决策，综合能力锻炼机会多；\n工作环境积极向上，团队氛围融洽，成长空间广阔。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4564894591","sourceKey":"meituan_social","company":"美团","title":"AI Agent 产品经理（微信生态方向）","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4564894591&jobShareType=1","duty":"1、深度理解用户在餐饮、出行、酒旅等场景下的需求，定义站外AI产品的核心方向与用户体验，覆盖AI助手、AIGC内容等场景，在用户需求、商业目标与技术边界之间找到最优解，主导关键产品决策，对核心业务指标负责；\n\n2、将前沿AI技术转化为规模化产品价值，深度参与Agent系统从工具调用、长程规划到自我纠错的全链路产品设计，推动AI能力从技术验证走向亿级用户的真实应用；\n\n3、驱动产品在复杂环境中持续演进，协调跨组织资源高效对齐，建立数据与用户洞察体系，基于行业趋势输出前瞻性产品规划，并有能力推动落地。","requirements":"1、本科及以上学历，计算机、人机交互等相关专业背景优先；具备3-5年互联网产品经验，有主导过大体量产品或复杂平台型产品完整经历者优先；\n\n2、具备AI产品的深度认知与实战经验，对大语言模型产品化、Agent系统设计、对话体验、AIGC等有系统性理解，能够与算法和工程团队在技术方案层面进行实质性讨论，而非停留在需求传递；\n\n3、全局视野与落地能力兼备，既能从业务全局定义方向和优先级，也能深入细节把控关键体验；具备较强的跨团队协作与推动能力，能够通过专业判断和沟通能力驱动多方资源对齐，在模糊和复杂环境中找到推进路径；有本地生活、搜索推荐或对话式产品背景者优先。","description":"部门介绍\n美团平台为用户的基础产品体验负责，还承担了美团的用户增长、市场和品牌营销以及多条业务线的产品设计职责，建立了融合文字、图片、视频和直播等不同形式的內容生态系统，同时整合地图服务部、客户服务和体验部、企业业务部、网约车业务部等部门，致力于用科技提升美团数亿消费者、近千万商家、骑手、司机和团长的服务体验。美团平台拥有高并发、多业务的复杂场景，为技术深度优化提供了最佳实践可能。这里有简单、讲逻辑、有爱的团队，更是一块理想的实战场地，舞台广阔，欢迎你来尽情施展。\n\n岗位职责\n1、深度理解用户在餐饮、出行、酒旅等场景下的需求，定义站外AI产品的核心方向与用户体验，覆盖AI助手、AIGC内容等场景，在用户需求、商业目标与技术边界之间找到最优解，主导关键产品决策，对核心业务指标负责；\n\n2、将前沿AI技术转化为规模化产品价值，深度参与Agent系统从工具调用、长程规划到自我纠错的全链路产品设计，推动AI能力从技术验证走向亿级用户的真实应用；\n\n3、驱动产品在复杂环境中持续演进，协调跨组织资源高效对齐，建立数据与用户洞察体系，基于行业趋势输出前瞻性产品规划，并有能力推动落地。\n\n岗位基本要求\n1、本科及以上学历，计算机、人机交互等相关专业背景优先；具备3-5年互联网产品经验，有主导过大体量产品或复杂平台型产品完整经历者优先；\n\n2、具备AI产品的深度认知与实战经验，对大语言模型产品化、Agent系统设计、对话体验、AIGC等有系统性理解，能够与算法和工程团队在技术方案层面进行实质性讨论，而非停留在需求传递；\n\n3、全局视野与落地能力兼备，既能从业务全局定义方向和优先级，也能深入细节把控关键体验；具备较强的跨团队协作与推动能力，能够通过专业判断和沟通能力驱动多方资源对齐，在模糊和复杂环境中找到推进路径；有本地生活、搜索推荐或对话式产品背景者优先。\n\n岗位亮点\n连接微信智能体亿万用户、连接小红书海量内容生态，在本地生活高频场景中打造下一代用户入口，是真正有挑战、有影响力的机会。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4630974320","sourceKey":"meituan_social","company":"美团","title":"内容增长运营","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4630974320&jobShareType=1","duty":"负责美团大模型业务创新产品的内容增长运营工作，围绕用户增长目标，制定并落地内容策略、传播方案及增长项目，持续提升产品的用户规模、活跃度、留存率与品牌影响力","requirements":"1、具备完整的 C 端用户增长全链路操盘经验，熟悉拉新、激活、留存、转化等关键环节，能够独立制定并落地增长策略，对业务结果负责；有 AI Native 产品成功增长案例者优先。\n2、热爱 AI，对国内外主流大模型、AIGC 产品及相关工具有深入理解，具备持续跟踪行业动态、学习新模型与新工具的习惯，并能够熟练运用 AI 提升内容生产、用户运营及项目协同效率。\n3、熟悉主流媒体平台的投放逻辑、内容生态及传播渠道特性，具备优秀的内容判断力，对互联网热点、内容趋势、用户审美及传播规律保持敏锐，能够快速识别并策划具有传播潜力的内容选题。\n4、对市场趋势、用户需求及行业动态保持高度敏感，具备较强的消费者洞察能力，能够将创意构想转化为可执行、可衡量的营销及增长方案；具备优秀的文案表达、方案策划与提案呈现能力。\n5、具备较强的策略思维、数据分析能力和跨团队协作能力，能够通过数据发现问题、验证策略并持续优化，独立推进复杂项目，协调产品、研发、市场等相关团队，推动业务目标高质量落地。","description":"部门介绍\n基础研发平台是美团的核心技术平台，立足于“零售+科技”的战略定位，通过打造人工智能、大数据、云计算、安全等核心技术能力，以及研发效能平台、企业应用平台等公共服务，为业务提供稳定安全、扩展易用、技术领先的平台技术和产品服务。\n在这里，我们会参与到最前沿的技术研发和探索；能够接触超规模集群、海量数据，挑战高复杂业务场景，有机会与业界一流的工程师一起并肩前行。\n在这里，我们有超强的技术氛围，持续向社区贡献业界实践，加速行业技术发展；我们有完善的互联网学习生态圈，重视底层逻辑和方法论，助力职业生涯的非线性成长。\n真诚地邀请你，和我们一起驱动技术发展，创造行业价值。\n\n岗位职责\n负责美团大模型业务创新产品的内容增长运营工作，围绕用户增长目标，制定并落地内容策略、传播方案及增长项目，持续提升产品的用户规模、活跃度、留存率与品牌影响力\n\n岗位基本要求\n1、具备完整的 C 端用户增长全链路操盘经验，熟悉拉新、激活、留存、转化等关键环节，能够独立制定并落地增长策略，对业务结果负责；有 AI Native 产品成功增长案例者优先。\n2、热爱 AI，对国内外主流大模型、AIGC 产品及相关工具有深入理解，具备持续跟踪行业动态、学习新模型与新工具的习惯，并能够熟练运用 AI 提升内容生产、用户运营及项目协同效率。\n3、熟悉主流媒体平台的投放逻辑、内容生态及传播渠道特性，具备优秀的内容判断力，对互联网热点、内容趋势、用户审美及传播规律保持敏锐，能够快速识别并策划具有传播潜力的内容选题。\n4、对市场趋势、用户需求及行业动态保持高度敏感，具备较强的消费者洞察能力，能够将创意构想转化为可执行、可衡量的营销及增长方案；具备优秀的文案表达、方案策划与提案呈现能力。\n5、具备较强的策略思维、数据分析能力和跨团队协作能力，能够通过数据发现问题、验证策略并持续优化，独立推进复杂项目，协调产品、研发、市场等相关团队，推动业务目标高质量落地。\n\n岗位亮点\n全面负责和牵引前沿AI原生产品的内容运营工作","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4609689022","sourceKey":"meituan_social","company":"美团","title":"Keeta科威特零售业务负责人","city":"科威特城","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4609689022&jobShareType=1","duty":"供给上线管理：负责海外零售业务，包括商品/服务供给的招商、上线、选品、定价及日常运营，确保供给充足、品类丰富、价格有竞争力。\n\n跨部门协同：与用户端、履约端、市场、产品、研发等相关部门紧密协作，推动供给策略与用户增长、履约效率、产品体验的一致性，确保业务目标落地。\n\n业务策略与规划：基于当地市场特点制定供给策略，拆解业务目标，推动执行并监控关键指标，持续优化供给结构和运营效率。\n\n团队管理：带领业务团队，搭建并培养高效执行的组织能力，推动团队在供给运营、数据分析、供应商管理等方面的专业成长。","requirements":"8年以上互联网或零售经营从业经验，3年以上团队管理经验；\n\n在商家管理/线上运营/商品运营等方面至少精通一项；\n\n具备较强的经营分析和诊断能力，有较强的商业意识和业务意识；\n\n具备商务英语能力，即时零售从业经验，有海外业务背景优先","description":"部门介绍\nKeeta是全球领先外卖平台美团旗下的独立品牌，肩负着“帮大家吃得更好，生活更好”的使命。依托美团深耕中国市场15年的技术与运营积淀，我们正引领全球餐饮与商品即时配送服务的创新与发展。\n\n自2023年成立以来，Keeta始终扎根社区并创造价值。我们为用户提供可靠的外卖体验，以智慧技术助餐厅提升经营效率，在为骑手拓宽收入来源的同时，也充分提供安全保障措施。基于这份多方共赢、共同成长的理念，我们的业务已从中国香港稳步拓展至中东及巴西，并持续向世界迈进。\n\n岗位职责\n供给上线管理：负责海外零售业务，包括商品/服务供给的招商、上线、选品、定价及日常运营，确保供给充足、品类丰富、价格有竞争力。\n\n跨部门协同：与用户端、履约端、市场、产品、研发等相关部门紧密协作，推动供给策略与用户增长、履约效率、产品体验的一致性，确保业务目标落地。\n\n业务策略与规划：基于当地市场特点制定供给策略，拆解业务目标，推动执行并监控关键指标，持续优化供给结构和运营效率。\n\n团队管理：带领业务团队，搭建并培养高效执行的组织能力，推动团队在供给运营、数据分析、供应商管理等方面的专业成长。\n\n岗位基本要求\n8年以上互联网或零售经营从业经验，3年以上团队管理经验；\n\n在商家管理/线上运营/商品运营等方面至少精通一项；\n\n具备较强的经营分析和诊断能力，有较强的商业意识和业务意识；\n\n具备商务英语能力，即时零售从业经验，有海外业务背景优先\n\n岗位亮点\n国际化业务快速发展且天花板高，个人成长性高，团队氛围好","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3976346781","sourceKey":"meituan_social","company":"美团","title":"服务风险客服主管","city":"石家庄市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3976346781&jobShareType=1","duty":"1.负责15人左右的组维度管理工作，包括员工日常管理、辅导改善、答疑、复盘等工作。\n2.负责组内运营数据改善和提升，包括数据达成分析、问题归因、制定解决方案。\n3.负责高风险疑难case的协助和推动，协助员工进行跨部门沟通，推动快速妥善解决。\n4.负责组内员工的成长培养，帮助员工提升业务能力、专业技巧，助力员工发展。\n5.能发现流程及产品不足，有效解决，并做到持续改善；探索AI工具在客服场景的应用，推动智能客服、智能质检等AI能力落地，提升团队运营效率。","requirements":"1.3年以上客服从业经历，1年以上客服团队管理经验，有风险服务业务经验优先；\n2.具备优秀的数据分析与判断能力、优秀的问题分析和解决能力、卓越的沟通协调能力；\n3.良好的团队合作精神，优秀的团队建设和管理能力；\n4.具有优良的服务洞察力和敬业精神；","description":"部门介绍\n美团平台为用户的基础产品体验负责，还承担了美团的用户增长、市场和品牌营销以及多条业务线的产品设计职责，建立了融合文字、图片、视频和直播等不同形式的內容生态系统，同时整合地图服务部、客户服务和体验部、企业业务部、网约车业务部等部门，致力于用科技提升美团数亿消费者、近千万商家、骑手、司机和团长的服务体验。美团平台拥有高并发、多业务的复杂场景，为技术深度优化提供了最佳实践可能。这里有简单、讲逻辑、有爱的团队，更是一块理想的实战场地，舞台广阔，欢迎你来尽情施展。\n\n岗位职责\n1.负责15人左右的组维度管理工作，包括员工日常管理、辅导改善、答疑、复盘等工作。\n2.负责组内运营数据改善和提升，包括数据达成分析、问题归因、制定解决方案。\n3.负责高风险疑难case的协助和推动，协助员工进行跨部门沟通，推动快速妥善解决。\n4.负责组内员工的成长培养，帮助员工提升业务能力、专业技巧，助力员工发展。\n5.能发现流程及产品不足，有效解决，并做到持续改善；探索AI工具在客服场景的应用，推动智能客服、智能质检等AI能力落地，提升团队运营效率。\n\n岗位基本要求\n1.3年以上客服从业经历，1年以上客服团队管理经验，有风险服务业务经验优先；\n2.具备优秀的数据分析与判断能力、优秀的问题分析和解决能力、卓越的沟通协调能力；\n3.良好的团队合作精神，优秀的团队建设和管理能力；\n4.具有优良的服务洞察力和敬业精神；\n\n岗位亮点\n1、发展方向多元：从消费者和商家服务体验出发，深入到业务中通过产品能力解决问题；\n2、有挑战成长快：复杂业务中学习和实践美团丰富方法论，建立自己思维框架。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4646716287","sourceKey":"meituan_social","company":"美团","title":"小象超市工程经理-川渝","city":"重庆市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4646716287&jobShareType=1","duty":"1. 制度与体系：结合业务模式拟定工程管理制度并严格落实，建立符合小象超市业态特点的项目管理标准化流程，保障项目安全高效推进；\n2. 全面管控：对工程项目的进度、质量、成本、安全进行全面把控，持续优化项目管理模式，做好指导、监督与考核，确保批量开店目标达成；\n3. 多方协同：组织设计、施工、供应商等多方会审，主导重要物料及工程验收备案；实时监督总包/分包履约状况，敏锐捕捉工程问题并迅速给出整改方案；\n4. 选址与交接：实地勘察场地，协同拓展部明确技术条件，助力完成选址、签约与场地交接，对门店的工程可行性提供专业判断；\n5. 结算与审计：严谨审查竣工图纸与结算资料，推动审计结算进程，配合完成结算闭环，有效控制工程超支风险；\n6. 报批报建：牵头负责施工及消防报批报建工作，获取开工许可等审批文件，熟练应对各地政策差异；\n7. 供应商管理：以设计标准为指引管理供应商体系，驱动培训考核，持续提升施工执行能力和材料品控水平；\n8. 数字化工程管控：推动工程管理数字化落地——运用BIM/数字孪生进行施工前预演和图纸审查；\n9. 借助AI辅助工具（如AI图纸合规检查、AI工期/成本预警）提升工程决策效率；\n10. 借助智能工单系统实现多项目并行的进度追踪和问题闭环；配合门店智能化改造，完成IoT设备（冷链监控、能耗管理、智能安防）调试与验收交付。","requirements":"1. 5年以上连锁商超或餐饮工程管理实践经验；\n2. 工程、土木、机电专业出身优先熟悉商超/餐饮工程各类标准、规范、技术方案及常用设备（制冷/强弱电/消防等）\n3. 精通工程管理、招投标、成本管控流程，具备独立管理多项目并行能力拥有施工报建、消防报审全流程实操经验具备良好的跨部门沟通协调能力，能有效推动多方资源协同\n4. 具备BIM基础操作能力，或使用过工程数字化工具\n5. 有使用AI工具辅助工程工作的经验（如AI图纸审查、AI工程文档生成、AI成本测算等工具）","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1. 制度与体系：结合业务模式拟定工程管理制度并严格落实，建立符合小象超市业态特点的项目管理标准化流程，保障项目安全高效推进；\n2. 全面管控：对工程项目的进度、质量、成本、安全进行全面把控，持续优化项目管理模式，做好指导、监督与考核，确保批量开店目标达成；\n3. 多方协同：组织设计、施工、供应商等多方会审，主导重要物料及工程验收备案；实时监督总包/分包履约状况，敏锐捕捉工程问题并迅速给出整改方案；\n4. 选址与交接：实地勘察场地，协同拓展部明确技术条件，助力完成选址、签约与场地交接，对门店的工程可行性提供专业判断；\n5. 结算与审计：严谨审查竣工图纸与结算资料，推动审计结算进程，配合完成结算闭环，有效控制工程超支风险；\n6. 报批报建：牵头负责施工及消防报批报建工作，获取开工许可等审批文件，熟练应对各地政策差异；\n7. 供应商管理：以设计标准为指引管理供应商体系，驱动培训考核，持续提升施工执行能力和材料品控水平；\n8. 数字化工程管控：推动工程管理数字化落地——运用BIM/数字孪生进行施工前预演和图纸审查；\n9. 借助AI辅助工具（如AI图纸合规检查、AI工期/成本预警）提升工程决策效率；\n10. 借助智能工单系统实现多项目并行的进度追踪和问题闭环；配合门店智能化改造，完成IoT设备（冷链监控、能耗管理、智能安防）调试与验收交付。\n\n岗位基本要求\n1. 5年以上连锁商超或餐饮工程管理实践经验；\n2. 工程、土木、机电专业出身优先熟悉商超/餐饮工程各类标准、规范、技术方案及常用设备（制冷/强弱电/消防等）\n3. 精通工程管理、招投标、成本管控流程，具备独立管理多项目并行能力拥有施工报建、消防报审全流程实操经验具备良好的跨部门沟通协调能力，能有效推动多方资源协同\n4. 具备BIM基础操作能力，或使用过工程数字化工具\n5. 有使用AI工具辅助工程工作的经验（如AI图纸审查、AI工程文档生成、AI成本测算等工具）\n\n具备以下条件优先\n具备电气，暖通，排烟等机电施工和设计经验优先\n\n岗位亮点\n有机会全身心地参与新零售业态，和团队一起更快速、更有效的完成工程筹建，提升个人能力； 能和电商、物流、零售、人工智能等多元化背景的团队技术大牛一起，综合学习，共同进步；工程团队的图纸审查、进度预警、成本分析都在探索AI辅助，你将有机会成为\"AI+工程管理\"这个新方向的先行者","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4659686163","sourceKey":"meituan_social","company":"美团","title":"项目管理部-资深项目经理","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4659686163&jobShareType=1","duty":"1. 管理业务及平台侧重点项目，明确项目目标，制定核心策略，整合项目管理计划，管控进度跟踪风险，对结果负责。\n2. 参与项目管理体系的建设和优化，结合业务特点为其提供项目管理解决方案或优化建议，包括但不限于项目管理体系化流程、规范、模版以及运营策略。\n3. 推动项目管理体系在业务组织的落地和运营，跟进体系运营的结果，包括但不限于流程体系在组织内的宣导培训、答疑咨询和反馈跟进。\n4. 积极沉淀案例库，SOP和方法论，为组织提供项目管理培训，用赋能的方式帮助业务团队提升项目管理的能力。","requirements":"1. 具有本科以上学历，持有PMP、PgMP认证者优先。\n2. 具备至少5年及以上重点业务项目集管理经验，负责过多个中大型软件项目管理，互联网行业背景优先。\n3. 具备出色的沟通协调能力、执行力、高效对接多方资源并推进问题闭环。 \n4. 思路清晰、积极主动，以结果为导向；具备较强的逻辑分析能力及语言和书面表达能力。\n5. 勤于思考，能够不断抽象问题、归纳总结，找到核心本质，推动相关工作效率不断提升。","description":"部门介绍\n核心本地商业（Core Local Commerce）是美团“零售+科技”战略的重要载体，涵盖了到店餐饮、服务零售、酒店旅行、外卖、履约配送、闪购、医药健康等多个业务，覆盖了超过200个消费场景，致力于通过“随时随地”的商品和服务，满足消费者的多样性需求，帮大家吃得更好，生活更好。核心本地商业扎根本地消费，围绕消费者的“吃、住、行、游、购、娱”进行深度创新，引领发展了即时零售、团购等多种消费业态，并在全国范围内广泛投资发展本地供给、履约平台等设施，助力创造产业、带动就业。基于多年的持续投入，核心本地商业打造了连接全国超过一千万中小微企业的服务体系，以及全球最大的即时配送网络。由核心本地商业所推行的30分钟“万物到家”体系，已覆盖全国2800多个城镇，为数亿用户提供优质的商品与服务。发展过程中，核心本地商业有效助力商超、连锁、本地小店等各类实体经济主体扩大交易规模、降低交易成本。截至目前，核心本地商业日均创造订单量数千万笔，助力千万商户实现了高质量发展。未来，核心本地商业将继续践行美团“零售+科技”战略，通过更大的投资，更多的技术创新，支持、培育消费新业态，为促进消费、服务民生、带动就业作出力所能及的贡献。欢迎优秀的你加入核心本地商业，我们携手助力市场繁荣，为用户创造更好的消费体验。\n\n岗位职责\n1. 管理业务及平台侧重点项目，明确项目目标，制定核心策略，整合项目管理计划，管控进度跟踪风险，对结果负责。\n2. 参与项目管理体系的建设和优化，结合业务特点为其提供项目管理解决方案或优化建议，包括但不限于项目管理体系化流程、规范、模版以及运营策略。\n3. 推动项目管理体系在业务组织的落地和运营，跟进体系运营的结果，包括但不限于流程体系在组织内的宣导培训、答疑咨询和反馈跟进。\n4. 积极沉淀案例库，SOP和方法论，为组织提供项目管理培训，用赋能的方式帮助业务团队提升项目管理的能力。\n\n岗位基本要求\n1. 具有本科以上学历，持有PMP、PgMP认证者优先。\n2. 具备至少5年及以上重点业务项目集管理经验，负责过多个中大型软件项目管理，互联网行业背景优先。\n3. 具备出色的沟通协调能力、执行力、高效对接多方资源并推进问题闭环。 \n4. 思路清晰、积极主动，以结果为导向；具备较强的逻辑分析能力及语言和书面表达能力。\n5. 勤于思考，能够不断抽象问题、归纳总结，找到核心本质，推动相关工作效率不断提升。\n\n具备以下条件优先\n1. 有互联网行业经验者优先；\n2. 具有项目管理体系建设、产研过程改进、工具优化相关经验者优先。\n\n岗位亮点\n平台发展空间大，深入业务领域，可参与项目全生命周期管理。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4631791354","sourceKey":"meituan_social","company":"美团","title":"Keeta技术-商城导购Java工程师","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4631791354&jobShareType=1","duty":"1.负责境外用户端导购核心系统的研发工作，包括餐饮外卖商城首页、Grocery商城首页以及商城底层平台化能力建设，致力于帮助业务提升用户产品体验，实现快速用户增长;\n2.参与全球多业务下用户端核心系统的架构规划、性能优化、稳定性、安全性等工作;\n3.保证高流量系统的性能和稳定性；\n4.参与技术决策，制定研发规范，完成技术选型，流程设计和技术风险评估等相关工作;\n5.建设AI Coding工作流程，搭建导购领域知识库，推动研发范式转型","requirements":"1.本科及以上学历，计算机相关专业；\n2.熟练掌握Java开发技术栈，对分布式架构组件有实践经验，熟悉设计模式、高可用性与容错保障等知识体系;\n3.拥有业务架构设计经验，对系统分层、DDD、领域分析建模、平台化等方面有丰富的实战经验者优先；\n4.有主流互联网电商业务系统搭建经验，具备复杂业务系统的分析与设计经验；\n5.具有良好的逻辑思维能力、沟通协作能力，对事情认真负责，自我驱动，具备突出的分析问题和解决问题的能力.\n6.熟悉AI辅助开发工具（如GitHub Copilot/Cursor），有AI Coding实践经验.\n7.了解大模型在高性能高稳定性领域自动分析自动预警应用优先.","description":"部门介绍\n美团核心本地商业下业务研发平台，基于公司“零售+科技”的战略导向，通过从底层架构到应用系统、从软件到硬件、从传统算法到GenAI的全方位技术研究，以及开发、运维、安全等全流程能力建设，致力于推动美团核心本地商业下需求侧与供给侧的数字化和智能化升级，助力业务实现高质量增长，优化用户使用体验，提升商户经营水平，促进行业生态伙伴关系的持续健康发展。团队秉持务实、自驱、开放以及追求卓越的工程师文化，一方面通过系统和技术体系的持续迭代升级，帮助业务高质量增长；另一方面，密切关注前沿技术趋势变化，积极创新技术能力，为业务未来发展创造新的可能性。期待优秀的你加入我们，在夯实专业、深耕平台的基础上与业务携手同行，一起用技术 “帮大家吃得更好，生活更好”。\n\n岗位职责\n1.负责境外用户端导购核心系统的研发工作，包括餐饮外卖商城首页、Grocery商城首页以及商城底层平台化能力建设，致力于帮助业务提升用户产品体验，实现快速用户增长;\n2.参与全球多业务下用户端核心系统的架构规划、性能优化、稳定性、安全性等工作;\n3.保证高流量系统的性能和稳定性；\n4.参与技术决策，制定研发规范，完成技术选型，流程设计和技术风险评估等相关工作;\n5.建设AI Coding工作流程，搭建导购领域知识库，推动研发范式转型\n\n岗位基本要求\n1.本科及以上学历，计算机相关专业；\n2.熟练掌握Java开发技术栈，对分布式架构组件有实践经验，熟悉设计模式、高可用性与容错保障等知识体系;\n3.拥有业务架构设计经验，对系统分层、DDD、领域分析建模、平台化等方面有丰富的实战经验者优先；\n4.有主流互联网电商业务系统搭建经验，具备复杂业务系统的分析与设计经验；\n5.具有良好的逻辑思维能力、沟通协作能力，对事情认真负责，自我驱动，具备突出的分析问题和解决问题的能力.\n6.熟悉AI辅助开发工具（如GitHub Copilot/Cursor），有AI Coding实践经验.\n7.了解大模型在高性能高稳定性领域自动分析自动预警应用优先.\n\n具备以下条件优先\n商城、导购、AI Coding、AI Agent、高并发、高性能、高稳定性经验\n\n岗位亮点\n能全面参与境外用户端业务从0到1的建设过程，承载多国差异化导购策略的架构挑战，可了解业务的全貌及系统架构演进。\n如果你对世界充满好奇心，在这里，你会接触到不同的国家、语言和文化，开拓国际视野，探索异域市场。\n如果你富有冒险精神，在这里，一个个陌生的国家等待你的开发，一个个全新的关卡等待你的挑战。\n如果你渴望快速成长，在这里，你可以经历新业务从0到1的过程，不断解锁新技能，持续获得成就感。\n我们的目标是星辰大海，期待有想法、敢于冒险、渴望快速成长的你加入！让我们一同见证美团境外业务的征程！","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4611954212","sourceKey":"meituan_social","company":"美团","title":"全国策联（华东）","city":"杭州市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4611954212&jobShareType=1","duty":"1. 负责全国策联大区门店选址开发工作，制定并执行区域拓展策略。  \n2. 统筹策联客户与区域门店营运标准落地，推动门店业绩提升与运营效率优化。   \n3. 分析市场趋势与竞争格局，输出区域发展建议与可行性报告。  \n4. 建立并维护与地方政府、商业地产等关键合作伙伴的关系。","requirements":"1. 大学本科及以上学历，市场营销、工商管理、房地产等相关专业优先。  \n2. 具备5年以上门店拓展、选址开发或连锁营运管理经验。  \n3. 熟悉全国重点城市商业布局，具备较强的市场洞察与数据分析能力。  \n4. 具备优秀的沟通协调能力与项目管理能力，能独立推动跨区域项目。  \n5. 能适应高频出差，具备较强的团队协同能力与结果导向意识。","description":"部门介绍\n快乐猴是美团自营社区超市，依托自有供应链和门店管理体系，聚焦家庭用户的三餐所需，为消费者提供高质价比的食杂商品。快乐猴以数字化能力与科学品控为基础，不断满足消费者对“省”和“便利”的需求。\n\n岗位职责\n1. 负责全国策联大区门店选址开发工作，制定并执行区域拓展策略。  \n2. 统筹策联客户与区域门店营运标准落地，推动门店业绩提升与运营效率优化。   \n3. 分析市场趋势与竞争格局，输出区域发展建议与可行性报告。  \n4. 建立并维护与地方政府、商业地产等关键合作伙伴的关系。\n\n岗位基本要求\n1. 大学本科及以上学历，市场营销、工商管理、房地产等相关专业优先。  \n2. 具备5年以上门店拓展、选址开发或连锁营运管理经验。  \n3. 熟悉全国重点城市商业布局，具备较强的市场洞察与数据分析能力。  \n4. 具备优秀的沟通协调能力与项目管理能力，能独立推动跨区域项目。  \n5. 能适应高频出差，具备较强的团队协同能力与结果导向意识。\n\n岗位亮点\n1. 参与全国战略布局，直接影响品牌区域发展节奏。  \n2. 与总部及大区团队紧密协作，拥有广阔的职业发展空间。  \n3. 公司提供完善的培训体系与清晰的晋升通道。    \n4. 具备竞争力的薪酬福利与绩效激励机制。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4490491134","sourceKey":"meituan_social","company":"美团","title":"销量预测专家","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4490491134&jobShareType=1","duty":"1. 负责城市、多品类长短周期的销量预测工作，综合历史销售数据、运营策略、区域特色及市场竞争态势，输出精准预测结果，为订货及库存计划提供核心数据支持。  \n2. 持续监控并分析预测准确率，借助AI手段自动识别偏差根因，推动整改措施落地，通过模型迭代和AI驱动的自动化闭环机制提升预测精准度，并对核心预测指标负责。  \n3. 构建和完善覆盖城市、仓等多维度的预测监控与数据分析体系，独立运用AI工具进行业务运营结果的深度归因分析，沉淀有效策略，推进预测流程或工具的产品化与自动化。  \n4. 深度融入运营模式，理解商品运营策略、促销规划及库存管理逻辑，通过AI赋能的精准预测协同采购、供应链及运营团队，优化库存水平，保障商品供给，降低滞销风险，提升周转效率。","requirements":"1. 大学本科及以上学历，5年及以上大型零售企业（商超、便利店、品牌连锁等）供应链计划或需求预测相关经验，熟悉线下零售业务运作流程和关键指标者优先。  \n2. 具备扎实的数据统计和分析能力，熟练使用SQL、Python等工具进行数据提取、清洗和分析，熟悉常用预测模型及AI工具，有自动化预测体系搭建经验者加分。  \n3. 具备严谨的逻辑分析和系统性思维能力，对线下零售业务有高度敏感度，能洞察内外部因素对销量的影响，并将业务洞察转化为AI模型输入。  \n4. 具备出色的跨部门沟通协调能力，能主动协同采购、运营、供应链等团队推动预测落地，有AI工具推广和赋能团队的意愿与能力。","description":"部门介绍\n美团闪购是美团旗下的即时零售平台，依托即时配送能力，连接本地零售供给，满足消费者30分钟万物到家的即时需求。美团闪购涵盖超市便利、食材、水果、鲜花绿植、休闲零食、酒水饮料、数码家电、美妆个护、母婴玩具、日用百货、服饰鞋帽、宠物等诸多品类，业务覆盖全国近3,000个县市区旗，每日百万级在岗骑手，以高效的配送、丰富的品类和广泛的覆盖，为美团数亿用户带来便捷的生活体验，积极助力实体零售线上化转型，提升本地商业活力。\n\n岗位职责\n1. 负责城市、多品类长短周期的销量预测工作，综合历史销售数据、运营策略、区域特色及市场竞争态势，输出精准预测结果，为订货及库存计划提供核心数据支持。  \n2. 持续监控并分析预测准确率，借助AI手段自动识别偏差根因，推动整改措施落地，通过模型迭代和AI驱动的自动化闭环机制提升预测精准度，并对核心预测指标负责。  \n3. 构建和完善覆盖城市、仓等多维度的预测监控与数据分析体系，独立运用AI工具进行业务运营结果的深度归因分析，沉淀有效策略，推进预测流程或工具的产品化与自动化。  \n4. 深度融入运营模式，理解商品运营策略、促销规划及库存管理逻辑，通过AI赋能的精准预测协同采购、供应链及运营团队，优化库存水平，保障商品供给，降低滞销风险，提升周转效率。\n\n岗位基本要求\n1. 大学本科及以上学历，5年及以上大型零售企业（商超、便利店、品牌连锁等）供应链计划或需求预测相关经验，熟悉线下零售业务运作流程和关键指标者优先。  \n2. 具备扎实的数据统计和分析能力，熟练使用SQL、Python等工具进行数据提取、清洗和分析，熟悉常用预测模型及AI工具，有自动化预测体系搭建经验者加分。  \n3. 具备严谨的逻辑分析和系统性思维能力，对线下零售业务有高度敏感度，能洞察内外部因素对销量的影响，并将业务洞察转化为AI模型输入。  \n4. 具备出色的跨部门沟通协调能力，能主动协同采购、运营、供应链等团队推动预测落地，有AI工具推广和赋能团队的意愿与能力。\n\n岗位亮点\n1. 深入核心业务，全面掌握新零售背景下的运作逻辑与挑战，直接参与AI预测体系的从0到1搭建。  \n2. 在真实复杂业务场景中，以AI工具为杠杆，锤炼兼具广度和深度的供应链计划与预测能力。  \n3. 与多元背景的专业团队协作，共同推动零售行业的AI化、智能化升级，站在行业变革前沿。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4644037383","sourceKey":"meituan_social","company":"美团","title":"杭州调度主管","city":"杭州市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4644037383&jobShareType=1","duty":"1、负责及时跟进部门运营数据及配送异常情况，针对客诉及时响应\n2、负责司机人员的日常管理；\n3、建立和完善车辆管理制度；\n4、确保发货及时率，降低漏扫占比；\n5、及时与上游环节沟通当日业务量及异常事项；\n6、负责运力及车源的开发，确保车辆运力池充足，满足订单及促销的需求；","requirements":"1、3年以上物流行业经验；\n2、从事过物流行业调度相关工作，对本城市交通非常熟悉；\n3、熟悉TMS系统的构成和使用逻辑，熟练使用计算机及办公软件；\n4、具备较强的沟通能力和现场管理能力，有较强的执行力，热爱团队；\n5、有较强的责任心和原则性；\n6、大专及以上学历。","description":"部门介绍\n快驴进货是美团旗下的餐饮供应链平台，帮助餐饮商户以更低成本、更高效率来获取安全可靠的食材供应，让餐饮采购更简单。快驴进货同步发展“自营+平台”的业务模式，在采购环节一方面向上游供应商直采大宗商品，另一方面引入各地批发商，助力平台伙伴共同发展；在销售环节既有自建团队进行市场、客户拓展，又帮助各地批发商拓展业务；同时自建仓储管理系统、配送网络与团队，为客户提供优质履约服务。\n截至2022年，快驴进货布局了全国41个城市，为百万家商户提供“全、省、稳、好”的餐饮供应链服务。我们拥有3000+品牌食材、超5万SKU商品、超28万商品资质，并提供源头严审核、食品安全严把关、24小时无忧售后的全面保障，实现手机下单、送货上门的高效采购模式，帮百万商家节省了采购时间与成本，助力平台伙伴共同发展，在万亿市场共享机遇。\n在这里，你将收获完善的员工发展机制及学习体系，与各界专家一起深度参与餐饮供应链业务的发展。欢迎优秀的你加入美团快驴进货，与我们一起成长，一起更好！\n\n岗位职责\n1、负责及时跟进部门运营数据及配送异常情况，针对客诉及时响应\n2、负责司机人员的日常管理；\n3、建立和完善车辆管理制度；\n4、确保发货及时率，降低漏扫占比；\n5、及时与上游环节沟通当日业务量及异常事项；\n6、负责运力及车源的开发，确保车辆运力池充足，满足订单及促销的需求；\n\n岗位基本要求\n1、3年以上物流行业经验；\n2、从事过物流行业调度相关工作，对本城市交通非常熟悉；\n3、熟悉TMS系统的构成和使用逻辑，熟练使用计算机及办公软件；\n4、具备较强的沟通能力和现场管理能力，有较强的执行力，热爱团队；\n5、有较强的责任心和原则性；\n6、大专及以上学历。\n\n具备以下条件优先\n拥有同城配送，生鲜配送等物流经验者优先\n\n岗位亮点\n1、丰富的物流运营经验，能够在环境下有效管理物流配送团队。\n2、拥有大型团队管理经验，能够带领和指导60人规模的团队，实现团队目标。\n3、在杭州市这个物流中心城市工作，有机会接触和合作众多大型供应商和客户，拓展人脉和业务机会。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3186218207","sourceKey":"meituan_social","company":"美团","title":"国际化HR产品经理","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3186218207&jobShareType=1","duty":"1. 负责海外核心人事及招聘等领域内相关系统规划、设计、交付和运营工作。\n2. 深入了解研究海外人力资源业务需求，并能清晰的将需求转化为可行性产品方案，根据不同国家业务诉求构建差异化服务产品兼容能力。\n3. 参与设计和整合核心人事及招聘等业务流程，建立统一服务标准与操作规范，对系统架构设计不断调整优化。\n4. 研究市场同类产品，结合用户需求，合理规划产品迭代路径。\n5. 能够使用英语进行工作交流，确保能与海外团队进行有效沟通。","requirements":"1.本科及以上学历，5年以上的HR软件设计或咨询经验，有互联网ToB产品应用设计经验或国际SaaS企业软件产品设计经验优先。\n2.具有较强的用户需求敏感度、深度挖掘需求价值和完整的业务链路。基于闭环场景给出完善解决方案。\n3.具备优秀的项目管理、协调能力，沟通协调能力较强，自驱能力强。\n4.具备流利的英语听说读写能力，能够无障碍地与海外团队进行工作交流。\n5.具有较强学习能力，能够承受较高工作压力。","description":"部门介绍\n美团HR的使命是“建设有生命力的组织，为客户和社会创造价值。” 我们认为HR的工作不是以自身“专业”为中心，而是要建设有助于员工发挥创造力的环境，支持他们更好地为外部客户和社会创造价值，也实现组织自身的进化和传承。在这个过程中，我们的每位HR同学都是“业务的战略合作伙伴、组织能力的建设者、美团精神的布道者、员工的成长伙伴”。我们要设计面向长期支撑组织有效运转的机制，我们要求真务实地帮业务解决发展中的问题和阵痛，我们要支持每一位员工历经磨炼收获成长。我们要影响和驱动让世界更美好的变化发生。如果这也是你追求的，欢迎加入美团HR，与我们一路同行！\n\n岗位职责\n1. 负责海外核心人事及招聘等领域内相关系统规划、设计、交付和运营工作。\n2. 深入了解研究海外人力资源业务需求，并能清晰的将需求转化为可行性产品方案，根据不同国家业务诉求构建差异化服务产品兼容能力。\n3. 参与设计和整合核心人事及招聘等业务流程，建立统一服务标准与操作规范，对系统架构设计不断调整优化。\n4. 研究市场同类产品，结合用户需求，合理规划产品迭代路径。\n5. 能够使用英语进行工作交流，确保能与海外团队进行有效沟通。\n\n岗位基本要求\n1.本科及以上学历，5年以上的HR软件设计或咨询经验，有互联网ToB产品应用设计经验或国际SaaS企业软件产品设计经验优先。\n2.具有较强的用户需求敏感度、深度挖掘需求价值和完整的业务链路。基于闭环场景给出完善解决方案。\n3.具备优秀的项目管理、协调能力，沟通协调能力较强，自驱能力强。\n4.具备流利的英语听说读写能力，能够无障碍地与海外团队进行工作交流。\n5.具有较强学习能力，能够承受较高工作压力。\n\n具备以下条件优先\n具备国际化HR系统建设的经验优先，具备海外工作及学习经历优先。\n\n岗位亮点\n1.迅速上升的业务态势，带来充足的发展机会和能力施展空间，可以在国际化产品领域发挥专业优势。\n2.团队氛围融洽，积极向上，一群人可以走得更远。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4209847628","sourceKey":"meituan_social","company":"美团","title":"快驴财务-商品财务BP","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4209847628&jobShareType=1","duty":"1. 预算制定：参与各品类年度规划工作，结合业务战略为品类制定相应的预算，同时支持业务将预算目标拆解到具体的实施路径并追踪达成。\n2. 业绩追踪：整体负责品类线的经营分析，通过日常对业务指标的追踪分析，发现和提示风险和机会点，站在经营的视角通过财务管理驱动业务盈利性增长。\n3. 策略评估：通过对品类的深入分析，结合业务模式发掘品类经营的关键驱动因素，持续迭代品类分析框架和评估体系；为业务策略提供论证测算支持，辅助业务制定中短期策略和落地计划。\n4. 业务支持：包括支持业务新场景落地，协同财税法提供财务解决方案；熟悉掌握各系统看板的数据口径和计算逻辑，支持业务进行数据分析；了解行业动态，提供对标分析支持等等。\n5.AI智能化推动：主动探索AI工具在业绩追踪、品类分析、预算制定等场景中的应用，推动财务分析工作提质增效。","requirements":"1.财务基本功扎实，具备基于大量数据处理和加工报表的能力。熟悉财务分析框架，能够输出业务经营分析报告和财务洞察。有良好跨团队沟通能力，能够与业务良好配合，紧密协作。\n2.具备AI工具应用意识，能熟练借助AI辅助工具（如大模型、智能BI等）提升数据分析和报告产出效率，有AI+财务决策实践经验者优先。","description":"部门介绍\n财务平台负责公司整体和各业务层面的财务管理工作，通过建设专业、全面、复合的财务管理能力和与业务经营的紧密结合来支持公司健康发展。目前财务平台拥有财务会计、财务报告、资金管理、税务管理、财务共享、财务系统、规划分析、财务BP和内控内审等主要工作方向。我们的目标是建设业界一流的财务管理能力和经营支持体系，为公司战略的正确落地、投入效率的持续提升、业务价值的不断增长保驾护航。欢迎加入财务平台，携手一起向未来！\n\n岗位职责\n1. 预算制定：参与各品类年度规划工作，结合业务战略为品类制定相应的预算，同时支持业务将预算目标拆解到具体的实施路径并追踪达成。\n2. 业绩追踪：整体负责品类线的经营分析，通过日常对业务指标的追踪分析，发现和提示风险和机会点，站在经营的视角通过财务管理驱动业务盈利性增长。\n3. 策略评估：通过对品类的深入分析，结合业务模式发掘品类经营的关键驱动因素，持续迭代品类分析框架和评估体系；为业务策略提供论证测算支持，辅助业务制定中短期策略和落地计划。\n4. 业务支持：包括支持业务新场景落地，协同财税法提供财务解决方案；熟悉掌握各系统看板的数据口径和计算逻辑，支持业务进行数据分析；了解行业动态，提供对标分析支持等等。\n5.AI智能化推动：主动探索AI工具在业绩追踪、品类分析、预算制定等场景中的应用，推动财务分析工作提质增效。\n\n岗位基本要求\n1.财务基本功扎实，具备基于大量数据处理和加工报表的能力。熟悉财务分析框架，能够输出业务经营分析报告和财务洞察。有良好跨团队沟通能力，能够与业务良好配合，紧密协作。\n2.具备AI工具应用意识，能熟练借助AI辅助工具（如大模型、智能BI等）提升数据分析和报告产出效率，有AI+财务决策实践经验者优先。\n\n具备以下条件优先\n有零售企业或互联网新零售背景优先。\n\n岗位亮点\n平台和业务发展稳定，个人发展空间大，业财联动紧密，可以沉淀方法论和行业经验。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4327284038","sourceKey":"meituan_social","company":"美团","title":"电话商务拓展专员","city":"石家庄市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4327284038&jobShareType=1","duty":"1.负责电话销售业务的开拓和推广，完成销售目标。\n2.针对潜在客户进行电话拜访、沟通，了解客户需求并进行产品推介。\n3.负责与客户建立良好的业务关系，维护客户满意度。\n4.跟进销售进展，协助解决客户问题和投诉，并提供售后服务。\n5.协助上级完成团队销售业绩的达成。\n6.及时汇报工作进展和市场动态，提供有关销售和竞争对手的信息。","requirements":"1.大学本科及以上学历。\n2.具备1年以上电话销售或业务开发经验，熟悉销售流程和销售技巧。\n3.具备良好的沟通能力和说服能力，能够与不同背景的客户进行有效的沟通。\n4.具备良好的团队合作精神，能够积极配合团队完成销售目标。\n5.具备较强的学习能力和适应能力，能够快速掌握产品知识和市场信息。\n6.具备良好的适应能力，能够应对工作中的挑战和压力。","description":"部门介绍\n美团到餐事业部拥有美团历史悠久的餐饮团购业务，聚焦美团“零售+科技”战略，为数以万计的餐饮商户提供一站式营销服务，为广大消费者提供优质的消费体验。我们帮助餐饮商户沉淀口碑、获取用户、增加复购等，持续提升商户数字化经营水平，同时秉承着“帮大家吃得更好，生活更好”的使命，面向消费者提供丰富的产品和服务，帮助消费者更好地作出消费决策。\n我们有高效成熟的管理体系，还将为你提供全面的人才培养机制和广阔的成长空间。让我们一起创造更大的价值，帮助消费者吃得更好，商户经营得更好！\n\n岗位职责\n1.负责电话销售业务的开拓和推广，完成销售目标。\n2.针对潜在客户进行电话拜访、沟通，了解客户需求并进行产品推介。\n3.负责与客户建立良好的业务关系，维护客户满意度。\n4.跟进销售进展，协助解决客户问题和投诉，并提供售后服务。\n5.协助上级完成团队销售业绩的达成。\n6.及时汇报工作进展和市场动态，提供有关销售和竞争对手的信息。\n\n岗位基本要求\n1.大学本科及以上学历。\n2.具备1年以上电话销售或业务开发经验，熟悉销售流程和销售技巧。\n3.具备良好的沟通能力和说服能力，能够与不同背景的客户进行有效的沟通。\n4.具备良好的团队合作精神，能够积极配合团队完成销售目标。\n5.具备较强的学习能力和适应能力，能够快速掌握产品知识和市场信息。\n6.具备良好的适应能力，能够应对工作中的挑战和压力。\n\n岗位亮点\n1.提供丰富的电话销售经验，有机会与不同类型的客户进行沟通和合作。\n2.能够通过销售业绩的提升获得相应的晋升机会。\n3.工作地点位于石家庄市，为您提供便利的工作环境和生活条件。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4659661353","sourceKey":"meituan_social","company":"美团","title":"具身基础模型算法专家","city":"北京市/深圳市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4659661353&jobShareType=1","duty":"1.设计并优化具身智能/无人机端到端的基础模型架构，探索面向物理世界感知、理解与决策的多模态统一模型；\n\n2.研究具身智能的 Scaling Law，提升模型在复杂操作/无人机业务上的 zero-shot 泛化与跨场景迁移能力；\n\n3.探索高效利用多样化、低成本数据源（Ego/Exo数据、互联网视频、真实采集数据）的训练方法，提升数据利用效率；\n\n4.探索面向下一代的无人机端到端架构，建设适用于端到端模型的数据闭环链路\n\n5.负责将AI工具与方法应用于算法研发全流程，提升开发效率与解决方案的智能化水平；","requirements":"1. 有VLA/VLM/LLM模型训练的经验，熟悉主流模型架构的原理与训练流程；\n\n2. 熟练使用 PyTorch/DeepSpeed等训练框架，具备扎实的工程能力； \n\n3. 具备以下至少一项技术背景：强化学习（GRPO/RECAP）；生成式模型（Diffusion Policy/Video Action Model）；  \n\n4. 持续跟踪具身智能、多模态大模型等前沿方向，推动算法创新与工程落地；\n\n5. 熟练运用AI辅助工具（如代码生成、数据分析、模型调优等）进行算法开发与优化；","description":"部门介绍\n为了更好地提升城市即时配送的效率与体验，2017年，美团启动了无人机配送服务的探索，通过科技创新推动履约工具变革，加快建设空地协同的本地即时配送网络。\n在过去的六年里，美团无人机完成了飞行器、自动化机场及智能调度系统的研发工作，实现了研发设计、生产制造、运营运维全链条布局，达成了城市复杂场景物流无人机高频次、高密度、多天时、多天侯运行。\n2023年7月，美团无人机在上海发布了自主研发的第四代无人机，跟此前机型相比，新机型升级了环境适应能力，可在“零下20度至50度”的中雨、中雪、6级风、弱光等环境中稳定飞行，能够适应97%以上国内城市的自然环境要求。\n截至2024年12月，美团无人机已在深圳、北京、上海、广州、南京、迪拜等城市开通53条航线，并累计完成订单超40万单。即时零售配送服务覆盖了办公、社区、景区、市政公园、校园、医疗、图书馆等多种场景。在医疗场景中，美团无人机可围绕医疗血液、检验样本、院前急救物资、特殊药品等医疗物资配送需求建设端到端的全天时急送网络。\n\n岗位职责\n1.设计并优化具身智能/无人机端到端的基础模型架构，探索面向物理世界感知、理解与决策的多模态统一模型；\n\n2.研究具身智能的 Scaling Law，提升模型在复杂操作/无人机业务上的 zero-shot 泛化与跨场景迁移能力；\n\n3.探索高效利用多样化、低成本数据源（Ego/Exo数据、互联网视频、真实采集数据）的训练方法，提升数据利用效率；\n\n4.探索面向下一代的无人机端到端架构，建设适用于端到端模型的数据闭环链路\n\n5.负责将AI工具与方法应用于算法研发全流程，提升开发效率与解决方案的智能化水平；\n\n岗位基本要求\n1. 有VLA/VLM/LLM模型训练的经验，熟悉主流模型架构的原理与训练流程；\n\n2. 熟练使用 PyTorch/DeepSpeed等训练框架，具备扎实的工程能力； \n\n3. 具备以下至少一项技术背景：强化学习（GRPO/RECAP）；生成式模型（Diffusion Policy/Video Action Model）；  \n\n4. 持续跟踪具身智能、多模态大模型等前沿方向，推动算法创新与工程落地；\n\n5. 熟练运用AI辅助工具（如代码生成、数据分析、模型调优等）进行算法开发与优化；\n\n具备以下条件优先\n1. 具备统一多模态/端到端模型训练经验； \n\n2. 具备机器人后训练与真机部署经验； \n\n3. 具备大规模分布式训练管线搭建或优化经验； \n\n4. 在CVPR/RSS/TPAMI等顶级会议发表相关论文，或在权威竞赛中获奖\n\n岗位亮点\n1.团队有丰富的算法/软硬件集成经验，丰富的训练资源和落地场景，无惧挑战，从0到1打造了低空物流配送系统。\n\n2.团队聚焦多模态感知与机器人研究，鼓励探索VLA、世界模型等前沿技术， 在计算机视觉知名刊物上有多篇论文发表。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4663097506","sourceKey":"meituan_social","company":"美团","title":"客服质培负责人","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4663097506&jobShareType=1","duty":"随着AI技术的发展，客服质检和培训场景是AI深度渗透和应用的场景，构建AI驱动的服务品质提升的闭环有巨大想象空间，该岗位作为客服质培负责人，将带领团队，协同各方推动质培业务流程和组织能力重构，拿到基于AI重塑客服质培的业务结果。\n\n1.基于AI重构培训管理和质量管理的工作流，构建“岗前培训 → 统一评价标准 → 质量发现 → 归因分析 → 千人千面培训/推动体验改善 → 效果验证”的服务水位评价和服务品质提升的闭环链路。\n\n2.思考和推动质培Agent的设计、应用落地，将“服务品质闭环”从理念落地为可执行的业务流程和AI能力，构建新的人机协作模式。\n\n3.颠覆质培传统模式，推动大模型全量质检能力落地，将质检从人工抽检模式向全量AI质检演进；推动培训从“统一授课”向“千人千面人机对练”模式演进；\n\n4.在整体视角与各业务差异之间找到平衡，确保统一框架下标准、策略和方案的灵活适配。\n\n5.在AI转型背景下重新定义团队能力模型，推动组织从执行型向策略型转变。","requirements":"1.本科及以上学历，人力资源管理、心理学、教育学、管理科学等相关专业优先。\n\n2.8年以上质量管理或培训管理相关经验，其中至少3年担任团队管理角色（管理10人以上团队），有跨中心/跨部门统筹管理经验。\n\n3.在质检或培训领域至少有一项深度专精，熟悉该领域的体系设计、运营全链路及数据分析方法，有成功建设或优化体系的实战经验。\n\n4.对AI/大模型在质检和培训场景的应用有深度认知，能结合业务场景设计AI落地方案，理解Agent闭环的设计逻辑。\n\n5.具备跨部门协同推进能力和团队管理能力，能够协调业务、运营、产品、技术等多方资源推动方案落地，在复杂组织中推动变革。\n\n6.以客户为中心，协同合作取得共赢，追求卓越。","description":"部门介绍\n核心本地商业（Core Local Commerce）是美团“零售+科技”战略的重要载体，涵盖了到店餐饮、服务零售、酒店旅行、外卖、履约配送、闪购、医药健康等多个业务，覆盖了超过200个消费场景，致力于通过“随时随地”的商品和服务，满足消费者的多样性需求，帮大家吃得更好，生活更好。核心本地商业扎根本地消费，围绕消费者的“吃、住、行、游、购、娱”进行深度创新，引领发展了即时零售、团购等多种消费业态，并在全国范围内广泛投资发展本地供给、履约平台等设施，助力创造产业、带动就业。基于多年的持续投入，核心本地商业打造了连接全国超过一千万中小微企业的服务体系，以及全球最大的即时配送网络。由核心本地商业所推行的30分钟“万物到家”体系，已覆盖全国2800多个城镇，为数亿用户提供优质的商品与服务。发展过程中，核心本地商业有效助力商超、连锁、本地小店等各类实体经济主体扩大交易规模、降低交易成本。截至目前，核心本地商业日均创造订单量数千万笔，助力千万商户实现了高质量发展。未来，核心本地商业将继续践行美团“零售+科技”战略，通过更大的投资，更多的技术创新，支持、培育消费新业态，为促进消费、服务民生、带动就业作出力所能及的贡献。欢迎优秀的你加入核心本地商业，我们携手助力市场繁荣，为用户创造更好的消费体验。\n\n岗位职责\n随着AI技术的发展，客服质检和培训场景是AI深度渗透和应用的场景，构建AI驱动的服务品质提升的闭环有巨大想象空间，该岗位作为客服质培负责人，将带领团队，协同各方推动质培业务流程和组织能力重构，拿到基于AI重塑客服质培的业务结果。\n\n1.基于AI重构培训管理和质量管理的工作流，构建“岗前培训 → 统一评价标准 → 质量发现 → 归因分析 → 千人千面培训/推动体验改善 → 效果验证”的服务水位评价和服务品质提升的闭环链路。\n\n2.思考和推动质培Agent的设计、应用落地，将“服务品质闭环”从理念落地为可执行的业务流程和AI能力，构建新的人机协作模式。\n\n3.颠覆质培传统模式，推动大模型全量质检能力落地，将质检从人工抽检模式向全量AI质检演进；推动培训从“统一授课”向“千人千面人机对练”模式演进；\n\n4.在整体视角与各业务差异之间找到平衡，确保统一框架下标准、策略和方案的灵活适配。\n\n5.在AI转型背景下重新定义团队能力模型，推动组织从执行型向策略型转变。\n\n岗位基本要求\n1.本科及以上学历，人力资源管理、心理学、教育学、管理科学等相关专业优先。\n\n2.8年以上质量管理或培训管理相关经验，其中至少3年担任团队管理角色（管理10人以上团队），有跨中心/跨部门统筹管理经验。\n\n3.在质检或培训领域至少有一项深度专精，熟悉该领域的体系设计、运营全链路及数据分析方法，有成功建设或优化体系的实战经验。\n\n4.对AI/大模型在质检和培训场景的应用有深度认知，能结合业务场景设计AI落地方案，理解Agent闭环的设计逻辑。\n\n5.具备跨部门协同推进能力和团队管理能力，能够协调业务、运营、产品、技术等多方资源推动方案落地，在复杂组织中推动变革。\n\n6.以客户为中心，协同合作取得共赢，追求卓越。\n\n具备以下条件优先\n1.有AI Agent或大模型在质检/培训场景的实际落地经验，了解Agent工作流设计和闭环逻辑。\n\n2.有客服/销售/外包/共享服务中心等大规模运营组织的质量管理或培训管理经验。\n\n3.有从0到1搭建或重构质检/培训体系的完整经历。\n\n4.有组织变革或团队转型推动经验。\n\n岗位亮点\n1. 站在AI重塑客服行业的前沿 — 推动智能质检和千人千面培训从概念走向规模化落地，重新定义质培模式\n\n2.站在组织转型变革的浪尖 — 率先推动“人机协作”的新一代质培组织能力建设，将质培从人力密集型变成AI驱动型\n\n3.战略权重高、成长空间大 — 资源管理部2026核心转型岗位，跨中心和所有业务线的全局视角","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4656522339","sourceKey":"meituan_social","company":"美团","title":"CatPaw 产品运营","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4656522339&jobShareType=1","duty":"负责 CatPaw 企业端产品的运营工作，结合客户需求和业务目标，制定并执行产品运营策略。\n\n深入了解企业客户的业务场景，协同销售、产品和研发团队，推动客户完成产品接入、上线及持续使用。\n\n建立客户 onboarding、培训、使用指导和问题反馈机制，提升客户活跃度、产品使用深度与续约率。\n\n跟踪客户使用数据及关键运营指标，识别使用障碍和增长机会，提出产品及运营优化方案。\n\n收集、整理并分析客户反馈，沉淀典型业务场景和共性需求，推动产品功能持续迭代。\n\n策划并制作产品手册、操作指南、培训材料、行业案例及销售支持内容。\n\n负责标杆客户案例的挖掘与包装，沉淀可复制的行业解决方案和客户成功经验。\n\n协同市场和销售团队开展产品推广、客户活动及重点项目运营，支持商机转化和业务增长。","requirements":"本科及以上学历，具备 2 年以上 To B 产品运营、客户成功、用户运营或相关工作经验。\n\n能够理解企业客户的业务流程和实际需求，具备较强的需求分析及问题解决能力。\n\n具备良好的项目推进能力，能够协调产品、研发、销售等多个团队推动项目落地。\n\n具备数据意识，能够通过客户行为和运营数据发现问题，并提出可执行的优化方案。\n\n具备优秀的沟通表达和内容输出能力，能够独立完成客户培训、产品文档及案例材料。\n\n结果导向，责任心强，能够适应快速变化的产品和业务环境。\n\n有 SaaS、AI 产品、企业服务或智能化工具运营经验者优先。\n\n有从 0 到 1 搭建 To B 产品运营或客户成功体系经验者优先。","description":"部门介绍\n基础研发平台是美团的核心技术平台，立足于“零售+科技”的战略定位，通过打造人工智能、大数据、云计算、安全等核心技术能力，以及研发效能平台、企业应用平台等公共服务，为业务提供稳定安全、扩展易用、技术领先的平台技术和产品服务。\n在这里，我们会参与到最前沿的技术研发和探索；能够接触超规模集群、海量数据，挑战高复杂业务场景，有机会与业界一流的工程师一起并肩前行。\n在这里，我们有超强的技术氛围，持续向社区贡献业界实践，加速行业技术发展；我们有完善的互联网学习生态圈，重视底层逻辑和方法论，助力职业生涯的非线性成长。\n真诚地邀请你，和我们一起驱动技术发展，创造行业价值。\n\n岗位职责\n负责 CatPaw 企业端产品的运营工作，结合客户需求和业务目标，制定并执行产品运营策略。\n\n深入了解企业客户的业务场景，协同销售、产品和研发团队，推动客户完成产品接入、上线及持续使用。\n\n建立客户 onboarding、培训、使用指导和问题反馈机制，提升客户活跃度、产品使用深度与续约率。\n\n跟踪客户使用数据及关键运营指标，识别使用障碍和增长机会，提出产品及运营优化方案。\n\n收集、整理并分析客户反馈，沉淀典型业务场景和共性需求，推动产品功能持续迭代。\n\n策划并制作产品手册、操作指南、培训材料、行业案例及销售支持内容。\n\n负责标杆客户案例的挖掘与包装，沉淀可复制的行业解决方案和客户成功经验。\n\n协同市场和销售团队开展产品推广、客户活动及重点项目运营，支持商机转化和业务增长。\n\n岗位基本要求\n本科及以上学历，具备 2 年以上 To B 产品运营、客户成功、用户运营或相关工作经验。\n\n能够理解企业客户的业务流程和实际需求，具备较强的需求分析及问题解决能力。\n\n具备良好的项目推进能力，能够协调产品、研发、销售等多个团队推动项目落地。\n\n具备数据意识，能够通过客户行为和运营数据发现问题，并提出可执行的优化方案。\n\n具备优秀的沟通表达和内容输出能力，能够独立完成客户培训、产品文档及案例材料。\n\n结果导向，责任心强，能够适应快速变化的产品和业务环境。\n\n有 SaaS、AI 产品、企业服务或智能化工具运营经验者优先。\n\n有从 0 到 1 搭建 To B 产品运营或客户成功体系经验者优先。\n\n岗位亮点\n参与核心产品成长：深度参与 CatPaw 产品从市场验证到规模化发展的关键阶段，拥有较大的发挥空间。\n\n深入 AI 与企业服务场景：接触前沿 AI 产品及真实企业需求，积累 AI 商业化和 To B 产品运营经验。\n\n直接影响产品方向：客户反馈和运营洞察能够直接进入产品决策与迭代过程。\n\n业务价值清晰：工作成果可以通过客户活跃度、使用深度、续约率和业务增长等指标得到直接体现。\n\n跨团队成长机会：与产品、研发、销售及市场团队紧密协作，快速建立对产品和商业化全链路的理解。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4659759888","sourceKey":"meituan_social","company":"美团","title":"到餐全国大客户--正餐门店组BD","city":"上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4659759888&jobShareType=1","duty":"负责推进 品牌餐饮连锁品牌 在城市/区域层面与美团在品牌营销、促销、交易运营增长等领域的深度商务合作；\n1.门店巡检与经营诊断：负责对接品牌客户旗下门店的定期巡检工作，核查门店经营状态、线上信息准确性、评价评分等，及时发现并推动解决门店异常问题；\n2.店推物料铺设与维护：负责店内推广物料（桌贴、立牌、海报、二维码等）的到店铺设、更换及日常维护，确保物料在位率和展示规范达标，配合营销活动节点完成物料集中更新；\n3.供给维护与拉回：跟进门店供给状态，针对下架、断货、过期等供给异常推动及时恢复上架；协助完成新品上架、套餐更新、价格调整等货盘维护，识别并激活低活跃门店；\n4.履约追补与保障：监控门店核销率、退款率等履约指标，对未核销订单、高退款门店进行定向追补；配合平台大促及品牌活动做好履约保障和问题响应；\n5.竞争情报收集与信息回传：收集门店端的铺设动态、活动力度等信息，为品牌策略提供一线竞争情报；及时反馈门店侧诉求与建议，维护门店基础数据的准确性；\n6.协同支持前线KA BD：承接品牌BD下达的门店侧执行任务，确保品牌策略在门店端有效落地；配合品牌重点项目（新品推广、区域攻坚、竞争防守等）的现场执行与支持。","requirements":"1.本科及以上学历，1年以上本地生活/餐饮/零售行业BD或地推相关工作经验；\n2.具备较强的执行力，能适应高频次外勤走访工作节奏；\n3.沟通表达能力良好，能够与门店店长/店员建立有效沟通；\n4.工作细致有条理，具备基本的数据记录和问题反馈意识；\n5.熟悉本地生活平台（美团/大众点评等）者优先；\n6.有连锁品牌门店服务经验者优先。","description":"部门介绍\n美团到餐事业部拥有美团历史悠久的餐饮团购业务，聚焦美团“零售+科技”战略，为数以万计的餐饮商户提供一站式营销服务，为广大消费者提供优质的消费体验。我们帮助餐饮商户沉淀口碑、获取用户、增加复购等，持续提升商户数字化经营水平，同时秉承着“帮大家吃得更好，生活更好”的使命，面向消费者提供丰富的产品和服务，帮助消费者更好地作出消费决策。\n我们有高效成熟的管理体系，还将为你提供全面的人才培养机制和广阔的成长空间。让我们一起创造更大的价值，帮助消费者吃得更好，商户经营得更好！\n\n岗位职责\n负责推进 品牌餐饮连锁品牌 在城市/区域层面与美团在品牌营销、促销、交易运营增长等领域的深度商务合作；\n1.门店巡检与经营诊断：负责对接品牌客户旗下门店的定期巡检工作，核查门店经营状态、线上信息准确性、评价评分等，及时发现并推动解决门店异常问题；\n2.店推物料铺设与维护：负责店内推广物料（桌贴、立牌、海报、二维码等）的到店铺设、更换及日常维护，确保物料在位率和展示规范达标，配合营销活动节点完成物料集中更新；\n3.供给维护与拉回：跟进门店供给状态，针对下架、断货、过期等供给异常推动及时恢复上架；协助完成新品上架、套餐更新、价格调整等货盘维护，识别并激活低活跃门店；\n4.履约追补与保障：监控门店核销率、退款率等履约指标，对未核销订单、高退款门店进行定向追补；配合平台大促及品牌活动做好履约保障和问题响应；\n5.竞争情报收集与信息回传：收集门店端的铺设动态、活动力度等信息，为品牌策略提供一线竞争情报；及时反馈门店侧诉求与建议，维护门店基础数据的准确性；\n6.协同支持前线KA BD：承接品牌BD下达的门店侧执行任务，确保品牌策略在门店端有效落地；配合品牌重点项目（新品推广、区域攻坚、竞争防守等）的现场执行与支持。\n\n岗位基本要求\n1.本科及以上学历，1年以上本地生活/餐饮/零售行业BD或地推相关工作经验；\n2.具备较强的执行力，能适应高频次外勤走访工作节奏；\n3.沟通表达能力良好，能够与门店店长/店员建立有效沟通；\n4.工作细致有条理，具备基本的数据记录和问题反馈意识；\n5.熟悉本地生活平台（美团/大众点评等）者优先；\n6.有连锁品牌门店服务经验者优先。\n\n岗位亮点\n1.具备丰富的地面产品销售经验，能够应对各种销售挑战。\n2.工作城市上海市，具备良好的发展前景和市场潜力。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4615516775","sourceKey":"meituan_social","company":"美团","title":"点评打卡项目运营负责人","city":"上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4615516775&jobShareType=1","duty":"1.负责大众点评打卡的整体运营工作，深入理解用户的打卡动机和行为路径，利用多种运营方式提升打卡用户数和高质量打卡内容数；\n2.定义大众点评打卡内容产出范式，引导商户和用户产出符合平台调性的打卡内容，培养用户记录生活的同时助力商户经营；\n3.策划和落地各类有趣有效的打卡活动，优化体验，联动城市运营，用户增长等团队推动打卡动机的泛化增长，通过提频贡献点评DAU的健康增长；\n4.持续跟踪核心指标表现，善用数据分析工具和AI辅助决策，洞察用户需求，驱动产品和运营策略迭代；\n5.持续关注行业趋势及优秀案例，探索记录类、社区类及生活服务类产品的创新运营玩法，关注AI+本地生活的前沿应用。","requirements":"1.本科及以上学历，4年以上互联网产品运营、活动运营或用户运营经验；\n2.具备较强的用户洞察能力和创造力，能从用户行为和需求出发设计出匹配用户兴趣、转化效果好的运营方案；\n3.有完整活动策划和落地经验，能够带领团队完成方案设计、资源协调到复盘优化的全流程工作；\n4.具备优秀的项目管理和跨团队协作能力，能够推动复杂项目高效落地；\n5.具备AI工具使用意识和实践经验（如ChatGPT/Claude/Copilot等），能主动将AI能力融入日常工作流；\n6.对打卡产品有较强兴趣和理解者优先；有AI+内容运营、AI+增长探索经验者优先。","description":"部门介绍\n大众点评作为国内重要的本地生活消费决策参考平台，多年来深耕本地生活消费领域，深受广大用户的信任和喜爱。我们的业务覆盖了吃喝玩乐游购娱等生活场景，通过极具辨识度和公信力的”星级“和”评价“产品，为数亿用户提供了全面、可信的消费决策依据。为更好满足用户探索城市的需求，大众点评在原有星级和评价的基础上，以信息流产品形式，助力用户发现更多好去处。大量优秀年轻同学的加入，为我们的团队注入了澎湃活力。我们相信，真实的生活是不可替代的，真实的感受是值得记录的，真实的美好是要被看到的。希望优秀的你能和我们一起，帮助广大用户在大众点评上发现更多好去处，找到属于自己的人间烟火气，共创美好生活。\n\n岗位职责\n1.负责大众点评打卡的整体运营工作，深入理解用户的打卡动机和行为路径，利用多种运营方式提升打卡用户数和高质量打卡内容数；\n2.定义大众点评打卡内容产出范式，引导商户和用户产出符合平台调性的打卡内容，培养用户记录生活的同时助力商户经营；\n3.策划和落地各类有趣有效的打卡活动，优化体验，联动城市运营，用户增长等团队推动打卡动机的泛化增长，通过提频贡献点评DAU的健康增长；\n4.持续跟踪核心指标表现，善用数据分析工具和AI辅助决策，洞察用户需求，驱动产品和运营策略迭代；\n5.持续关注行业趋势及优秀案例，探索记录类、社区类及生活服务类产品的创新运营玩法，关注AI+本地生活的前沿应用。\n\n岗位基本要求\n1.本科及以上学历，4年以上互联网产品运营、活动运营或用户运营经验；\n2.具备较强的用户洞察能力和创造力，能从用户行为和需求出发设计出匹配用户兴趣、转化效果好的运营方案；\n3.有完整活动策划和落地经验，能够带领团队完成方案设计、资源协调到复盘优化的全流程工作；\n4.具备优秀的项目管理和跨团队协作能力，能够推动复杂项目高效落地；\n5.具备AI工具使用意识和实践经验（如ChatGPT/Claude/Copilot等），能主动将AI能力融入日常工作流；\n6.对打卡产品有较强兴趣和理解者优先；有AI+内容运营、AI+增长探索经验者优先。\n\n具备以下条件优先\n1.有内容型产品、生活记录/社区/本地生活等相关产品运营经验；\n2.有活动运营或增长运营经验，具备高速增长和大规模增长项目成功经验优先；\n3.在内容社区有记录习惯，拥有一定粉丝量和自媒体经验。\n\n岗位亮点\n1.打卡项目是点评事业部当下最重要的项目之一，期望成为大众点评焕新增长的第二曲线；\n2.有机会跳出打卡有礼的传统增长路径，寻找和定义更多用户打卡动机，具备多样的创新空间；\n3.联动点评内大部分团队，能快速熟悉点评用户/商户的同时获取到大量资源支持；\n4.团队积极拥抱AI，不局限于职能体系，鼓励用AI工具提效和创新，有丰富的AI落地场景和实践机会。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4649791967","sourceKey":"meituan_social","company":"美团","title":"小象超市-区域训练运营","city":"北京市/杭州市/上海市/广州市/深圳市/武汉市/成都市/西安市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4649791967&jobShareType=1","duty":"1.负责所辖大区的训练计划制定与执行，包括新人入职训练、岗位进阶训练、管理转身训练等全项目的落地推进；\n2.负责大区训练数据的日常追踪与通晒，包括学习完成率、考试通过率、认证覆盖率、训练员配比等核心指标；\n3.定期巡站识别问题站点训练情况：新人带训质量、训练员配比、认证进度、SOC执行偏差，对训练落后站点进行专项辅导和资源投入，现场纠偏，推动整改；\n4.定期向大区/总部汇报区域训练进度，推动后进站点整改，承接总部训练项目（如新SOP宣贯、新系统上线训练），确保在区域内的按时按质落地；\n5.收集一线训练痛点和需求，反向推动总部训练产品和机制的优化。","requirements":"1.经验要求： 3年以上连锁零售/餐饮/即时电商行业的训练、培训、营运督导相关经验，有前置仓/便利店/快餐行业背景优先；\n2.专业能力： 熟悉SOC鉴定、训练四步骤、标准化教学包开发等训练方法论，了解训练系统能力；\n3.业务敏感度： 能快速理解业务场景，把标准语言转化为一线可执行的训练动作；\n4.数据能力： 能基于训练数据发现问题、制定改善方案，熟练使用数据看板与数据处理工具；\n5.沟通影响力：多层管理者对话，推动训练责任落地。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1.负责所辖大区的训练计划制定与执行，包括新人入职训练、岗位进阶训练、管理转身训练等全项目的落地推进；\n2.负责大区训练数据的日常追踪与通晒，包括学习完成率、考试通过率、认证覆盖率、训练员配比等核心指标；\n3.定期巡站识别问题站点训练情况：新人带训质量、训练员配比、认证进度、SOC执行偏差，对训练落后站点进行专项辅导和资源投入，现场纠偏，推动整改；\n4.定期向大区/总部汇报区域训练进度，推动后进站点整改，承接总部训练项目（如新SOP宣贯、新系统上线训练），确保在区域内的按时按质落地；\n5.收集一线训练痛点和需求，反向推动总部训练产品和机制的优化。\n\n岗位基本要求\n1.经验要求： 3年以上连锁零售/餐饮/即时电商行业的训练、培训、营运督导相关经验，有前置仓/便利店/快餐行业背景优先；\n2.专业能力： 熟悉SOC鉴定、训练四步骤、标准化教学包开发等训练方法论，了解训练系统能力；\n3.业务敏感度： 能快速理解业务场景，把标准语言转化为一线可执行的训练动作；\n4.数据能力： 能基于训练数据发现问题、制定改善方案，熟练使用数据看板与数据处理工具；\n5.沟通影响力：多层管理者对话，推动训练责任落地。\n\n岗位亮点\n1.参与建设期，不是维护期——从1到10的体系搭建机会；\n2.业务在高速扩张，训练是核心支撑部门。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4597076394","sourceKey":"meituan_social","company":"美团","title":"小象超市-配送渠道经理（宁波）","city":"宁波市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4597076394&jobShareType=1","duty":"岗位职责:\n1.制定区域配送管理的方案，监督现场执行情况，检核小象超市站点配送的日常管理及流程标准化； \n2.推动本区域业务运营落地工作，监控日常运营、服务质量、指标数据； \n3.负责区域的履约问题收集、反馈和解决工作，运营运作异常事件的跟进处理、总结分析、监督改进； \n4.负责区域内督导、骑手的培训工作，提高员工的综合素质和业务能力； \n5.负责区域内站点的服务质量，分析配送客诉，采取有效措施把控客诉，提供专业、高效、高质量的配送服务，提升顾客满意度。","requirements":"1.本科及以上学历，物流管理或供应链管理专业或3年以上配送运营相关工作经验； \n2.具有良好的沟通协调技巧和团队合作意识，跨部门协调能力，能与其他部门或者外部单位良好的沟通，踏实认真，有责任感； \n3.对数据变化敏感，有优秀的数据分析能力和学习能力，熟练使用各类办公软件； \n4.具备一定的文档处理能力，熟练操作常用办公软件； \n5.具备较强执行力，能适应高强度的工作和阶段性出差； \n6.具备较强的市场开拓性，有项目管理能力，思路清晰，管理协调能力佳。 \n具备以下优先： 有即时配送相关从业经验优先。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n岗位职责:\n1.制定区域配送管理的方案，监督现场执行情况，检核小象超市站点配送的日常管理及流程标准化； \n2.推动本区域业务运营落地工作，监控日常运营、服务质量、指标数据； \n3.负责区域的履约问题收集、反馈和解决工作，运营运作异常事件的跟进处理、总结分析、监督改进； \n4.负责区域内督导、骑手的培训工作，提高员工的综合素质和业务能力； \n5.负责区域内站点的服务质量，分析配送客诉，采取有效措施把控客诉，提供专业、高效、高质量的配送服务，提升顾客满意度。\n\n岗位基本要求\n1.本科及以上学历，物流管理或供应链管理专业或3年以上配送运营相关工作经验； \n2.具有良好的沟通协调技巧和团队合作意识，跨部门协调能力，能与其他部门或者外部单位良好的沟通，踏实认真，有责任感； \n3.对数据变化敏感，有优秀的数据分析能力和学习能力，熟练使用各类办公软件； \n4.具备一定的文档处理能力，熟练操作常用办公软件； \n5.具备较强执行力，能适应高强度的工作和阶段性出差； \n6.具备较强的市场开拓性，有项目管理能力，思路清晰，管理协调能力佳。 \n具备以下优先： 有即时配送相关从业经验优先。\n\n具备以下条件优先\n有即时配送以及代理商管理经验优先\n\n岗位亮点\n1、基于生鲜配送新型业态，完善的内部培训以及晋升机制，未来发展空间大； \n2、配送能力是社区生鲜零售行业的核心竞争力，工作重要性高、成长快。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4601150627","sourceKey":"meituan_social","company":"美团","title":"供应链品控","city":"天津市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4601150627&jobShareType=1","duty":"1.负责制定和执行生鲜品控相关的品质管理方案和流程。\n2.通过品质检测和评估，确保生鲜产品的质量符合公司要求和客户期望。\n3.负责监控生鲜产品的供应链，包括供应商选择、采购流程和物流配送等，以确保产品的新鲜度和安全性。\n4.进行供应商的评估和审核，确保供应商符合公司的品质标准和合规要求。\n5.协调与内部团队和供应商之间的沟通，解决品质问题和改善措施。\n6.持续改进品质管理体系，提高生鲜产品的品质，降低质量风险。","requirements":"1.大学专科以上学历，相关专业背景优先考虑。\n2.至少3年以上生鲜品控或相关领域的工作经验，熟悉生鲜产品的质量标准和检测方法。\n3.具备较强的沟通能力和团队合作精神，能够有效协调内部和外部资源。\n4.具备良好的分析和问题解决能力，能够快速识别和解决品质问题。\n5.具备较强的责任心，能够在快节奏的工作环境下保持高效率和准确性。\n6.熟练使用办公软件和品质管理工具。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1.负责制定和执行生鲜品控相关的品质管理方案和流程。\n2.通过品质检测和评估，确保生鲜产品的质量符合公司要求和客户期望。\n3.负责监控生鲜产品的供应链，包括供应商选择、采购流程和物流配送等，以确保产品的新鲜度和安全性。\n4.进行供应商的评估和审核，确保供应商符合公司的品质标准和合规要求。\n5.协调与内部团队和供应商之间的沟通，解决品质问题和改善措施。\n6.持续改进品质管理体系，提高生鲜产品的品质，降低质量风险。\n\n岗位基本要求\n1.大学专科以上学历，相关专业背景优先考虑。\n2.至少3年以上生鲜品控或相关领域的工作经验，熟悉生鲜产品的质量标准和检测方法。\n3.具备较强的沟通能力和团队合作精神，能够有效协调内部和外部资源。\n4.具备良好的分析和问题解决能力，能够快速识别和解决品质问题。\n5.具备较强的责任心，能够在快节奏的工作环境下保持高效率和准确性。\n6.熟练使用办公软件和品质管理工具。\n\n岗位亮点\n1.作为初级生鲜品控，可以接触到全流程的品质管理工作，拥有较大的发展空间和成长机会。\n2.可以与各个部门和供应商进行合作，了解和学习不同环节的品质管理经验。\n3.可以通过不断改进和优化品质管理流程，提高生鲜产品的品质和客户满意度。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3060106098","sourceKey":"meituan_social","company":"美团","title":"Keeta财务运营方案岗","city":"北京市/利雅得","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3060106098&jobShareType=1","duty":"1、业务支持：负责对接Keeta业务需求，结合会计准则，结算规则，合规要求等，识别和判断业务活动对财务的影响，出具相应的财务方案，为业务部门的发展及商业决策提供积极的财务支持；\n2、提升财务信息化能力：结合对业务场景及业财系统的深入理解，与各方产研配合推进财务信息化建设，包括业务场景的线上计费结算、线上化传账及业财数据校验、财务系统优化升级等；\n3、业财流程优化：通过专项梳理推进财务运营流程、信息化进程等优化，发现并解决各类财务问题，提高财务结果的效率和准确性，能识别日常工作中的流程问题，如流程断点、冗余，并通过优化流程和工具，同时积极探索并应用AI工具（大模型辅助方案撰写、自动化对账、异常检测等）提升财务运营效能。\n4、其他：与财务其他团队积极协调，完成其他指定任务。","requirements":"1.本科及其以上学历，会计、经济、管理类等相关专业，5年及以上财会相关工作经验，有结核算相关经验以及财务系统对接经验。\n2. 具备较强的沟通能力、协调能力，能和业务线对接，具备优秀的逻辑思维和分析能力；\n3.工作认真细心、责任心强、具有良好的团队协作精神和服务意识，有好奇心；\n4.能够以英文作为日常工作沟通语言。\n5.能够接受去海外出差。\n6.熟悉新鲜事物，能够使用AI相关工具为工作提效。","description":"部门介绍\n财务平台负责公司整体和各业务层面的财务管理工作，通过建设专业、全面、复合的财务管理能力和与业务经营的紧密结合来支持公司健康发展。目前财务平台拥有财务会计、财务报告、资金管理、税务管理、财务共享、财务系统、规划分析、财务BP和内控内审等主要工作方向。我们的目标是建设业界一流的财务管理能力和经营支持体系，为公司战略的正确落地、投入效率的持续提升、业务价值的不断增长保驾护航。欢迎加入财务平台，携手一起向未来！\n\n岗位职责\n1、业务支持：负责对接Keeta业务需求，结合会计准则，结算规则，合规要求等，识别和判断业务活动对财务的影响，出具相应的财务方案，为业务部门的发展及商业决策提供积极的财务支持；\n2、提升财务信息化能力：结合对业务场景及业财系统的深入理解，与各方产研配合推进财务信息化建设，包括业务场景的线上计费结算、线上化传账及业财数据校验、财务系统优化升级等；\n3、业财流程优化：通过专项梳理推进财务运营流程、信息化进程等优化，发现并解决各类财务问题，提高财务结果的效率和准确性，能识别日常工作中的流程问题，如流程断点、冗余，并通过优化流程和工具，同时积极探索并应用AI工具（大模型辅助方案撰写、自动化对账、异常检测等）提升财务运营效能。\n4、其他：与财务其他团队积极协调，完成其他指定任务。\n\n岗位基本要求\n1.本科及其以上学历，会计、经济、管理类等相关专业，5年及以上财会相关工作经验，有结核算相关经验以及财务系统对接经验。\n2. 具备较强的沟通能力、协调能力，能和业务线对接，具备优秀的逻辑思维和分析能力；\n3.工作认真细心、责任心强、具有良好的团队协作精神和服务意识，有好奇心；\n4.能够以英文作为日常工作沟通语言。\n5.能够接受去海外出差。\n6.熟悉新鲜事物，能够使用AI相关工具为工作提效。\n\n具备以下条件优先\n有互联网大公司平台经验者优先，具备财务专业基础扎实、有流程、系统优化的经验、沟通协调能力强、英语好能力者、熟悉AI工具优先\n\n岗位亮点\n见证境外业务发展，深度参与业务日常运营，并参与业财系统建设（包含AI实践），全面提升财务专业能力","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4648580488","sourceKey":"meituan_social","company":"美团","title":"资金风险管理专家","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4648580488&jobShareType=1","duty":"主要职责：\n1.负责公司资金风险的识别、评估、跟踪与管理，建立健全资金风险管理体系； \n2.基于现有管理体系，向需求方输出风险管理建议，不断完善管理的标准和流程； \n3.提高团队人效，推动已固化管理动作的流程制度建设，探索重复性工作场景的AI解决方案。\n\n专业能力要求：\n1.熟悉信用风险（交易对手信用和额度评估、信用资产过程管理、信用风险处置等）、市场风险（汇率、利率、国别风险）的量化评估方法、跨境资金合规要求（外汇管制、反洗钱、制裁筛查等），资金交易风险（权限管理、审批设置、实物保管等），资金风险中一种以上； \n2.具备较强的学习能力，能快速上手新工作，独立完成风险评估与风险管理建议输出；\n3.对资金业务中的潜在风险具备高度敏感性，有\"风险前置\"思维； \n4.逻辑清晰、沟通能力强。","requirements":"1.专业和学历：本科及以上学历，金融、经济、风险管理、会计、数学/统计等相关专业； \n2.工作经验：3年以上资金风险管理或相关领域工作经验。","description":"部门介绍\n财务平台负责公司整体和各业务层面的财务管理工作，通过建设专业、全面、复合的财务管理能力和与业务经营的紧密结合来支持公司健康发展。目前财务平台拥有财务会计、财务报告、资金管理、税务管理、财务共享、财务系统、规划分析、财务BP和内控内审等主要工作方向。我们的目标是建设业界一流的财务管理能力和经营支持体系，为公司战略的正确落地、投入效率的持续提升、业务价值的不断增长保驾护航。欢迎加入财务平台，携手一起向未来！\n\n岗位职责\n主要职责：\n1.负责公司资金风险的识别、评估、跟踪与管理，建立健全资金风险管理体系； \n2.基于现有管理体系，向需求方输出风险管理建议，不断完善管理的标准和流程； \n3.提高团队人效，推动已固化管理动作的流程制度建设，探索重复性工作场景的AI解决方案。\n\n专业能力要求：\n1.熟悉信用风险（交易对手信用和额度评估、信用资产过程管理、信用风险处置等）、市场风险（汇率、利率、国别风险）的量化评估方法、跨境资金合规要求（外汇管制、反洗钱、制裁筛查等），资金交易风险（权限管理、审批设置、实物保管等），资金风险中一种以上； \n2.具备较强的学习能力，能快速上手新工作，独立完成风险评估与风险管理建议输出；\n3.对资金业务中的潜在风险具备高度敏感性，有\"风险前置\"思维； \n4.逻辑清晰、沟通能力强。\n\n岗位基本要求\n1.专业和学历：本科及以上学历，金融、经济、风险管理、会计、数学/统计等相关专业； \n2.工作经验：3年以上资金风险管理或相关领域工作经验。\n\n具备以下条件优先\n1.行业背景：互联网/平台型企业、消费零售、科技行业、制造业等大型企业经验； \n2.证书资质：具有CFA、FRM、CPA等专业资格； \n3.国际化视野：有海外业务或跨境资金管理经验；\n4.创新能力：有AI工具应用能力和成功实践。\n\n岗位亮点\n全球资金管理平台视野，对境内外资金风险做全面管理，在业务高速发展中持续输出资金专业价值。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4570160124","sourceKey":"meituan_social","company":"美团","title":"零售SaaS高级数据产品经理","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4570160124&jobShareType=1","duty":"1.负责牵牛花平台核心数据资产的全生命周期管理，推动数据资产的标准化、可信化治理，建立数据质量监控体系，确保数据口径统一、血缘清晰、权限可控，为上层应用建立完备的底层知识体系。\n2.深度理解零售商、供应商的经营场景和数据分析意图，负责商家端数据看板的产品规划、设计迭代及效果验收，持续提升数据报表的经营适配性、全面性和易用性，结合 AI Agent、大模型等新技术探索数据服务的智能化交付路径，降低数据使用门槛，提升商家经营效率和决策质量。\n3.面向 AI 应用建设原子化、标准化的数据服务，包括数据治理规范、取数 Skill 定义与落地、核心数据接口 CLI 化、数据治理 DSL 等，确保 AI 取数的准确性、效率与安全性，支持 NL2SQL、数据 Agent 等智能数据产品的工程化落地。\n4.负责数据产品项目的全生命周期管理，包括需求分析、方案设计、项目管理推进、效果验收等，有效整合研发、算法、业务、运营等多方资源，推动复杂数据项目高质量落地。","requirements":"1.本科及以上学历，3 年以上数据产品或相关产品工作经验；优秀的沟通协调能力和学习适应能力，能在数据治理、AI 建设、业务需求等多条线并行推进中保持清晰的优先级判断和高效的执行节奏。\n2.业务理解与数据敏感度，对零售行业有深入理解，具备较强的数据敏感度和逻辑分析能力，能够通过数据驱动业务决策，熟练使用 SQL 进行数据分析，有 SaaS 数据产品或即时零售数据产品经验者优先。\n3.数据治理专业能力，了解数据治理基本方法论（数据标准、数据质量、数据安全、元数据管理、血缘分析），有数据资产建设、数据平台产品或数据中台经验者优先；熟悉数据资产从 0 到 1 的搭建过程。\n4.AI 与数据产品结合能力，对 AI 技术发展保持持续关注，能够将 LLM、Agent 等新技术与数据产品场景有机结合，有 NL2SQL、数据 Agent、智能取数等 AI 数据产品落地经验者优先。\n5.产品设计与项目管理，具备良好的产品抽象能力和用户体验意识，能够独立完成产品原型设计、项目推进和效果验证；具备强跨团队协同推进能力，能在多方利益诉求中找到最优解，推动复杂项目按时高质量交付。","description":"部门介绍\n美团闪购是美团旗下的即时零售平台，依托即时配送能力，连接本地零售供给，满足消费者30分钟万物到家的即时需求。美团闪购涵盖超市便利、食材、水果、鲜花绿植、休闲零食、酒水饮料、数码家电、美妆个护、母婴玩具、日用百货、服饰鞋帽、宠物等诸多品类，业务覆盖全国近3,000个县市区旗，每日百万级在岗骑手，以高效的配送、丰富的品类和广泛的覆盖，为美团数亿用户带来便捷的生活体验，积极助力实体零售线上化转型，提升本地商业活力。\n\n岗位职责\n1.负责牵牛花平台核心数据资产的全生命周期管理，推动数据资产的标准化、可信化治理，建立数据质量监控体系，确保数据口径统一、血缘清晰、权限可控，为上层应用建立完备的底层知识体系。\n2.深度理解零售商、供应商的经营场景和数据分析意图，负责商家端数据看板的产品规划、设计迭代及效果验收，持续提升数据报表的经营适配性、全面性和易用性，结合 AI Agent、大模型等新技术探索数据服务的智能化交付路径，降低数据使用门槛，提升商家经营效率和决策质量。\n3.面向 AI 应用建设原子化、标准化的数据服务，包括数据治理规范、取数 Skill 定义与落地、核心数据接口 CLI 化、数据治理 DSL 等，确保 AI 取数的准确性、效率与安全性，支持 NL2SQL、数据 Agent 等智能数据产品的工程化落地。\n4.负责数据产品项目的全生命周期管理，包括需求分析、方案设计、项目管理推进、效果验收等，有效整合研发、算法、业务、运营等多方资源，推动复杂数据项目高质量落地。\n\n岗位基本要求\n1.本科及以上学历，3 年以上数据产品或相关产品工作经验；优秀的沟通协调能力和学习适应能力，能在数据治理、AI 建设、业务需求等多条线并行推进中保持清晰的优先级判断和高效的执行节奏。\n2.业务理解与数据敏感度，对零售行业有深入理解，具备较强的数据敏感度和逻辑分析能力，能够通过数据驱动业务决策，熟练使用 SQL 进行数据分析，有 SaaS 数据产品或即时零售数据产品经验者优先。\n3.数据治理专业能力，了解数据治理基本方法论（数据标准、数据质量、数据安全、元数据管理、血缘分析），有数据资产建设、数据平台产品或数据中台经验者优先；熟悉数据资产从 0 到 1 的搭建过程。\n4.AI 与数据产品结合能力，对 AI 技术发展保持持续关注，能够将 LLM、Agent 等新技术与数据产品场景有机结合，有 NL2SQL、数据 Agent、智能取数等 AI 数据产品落地经验者优先。\n5.产品设计与项目管理，具备良好的产品抽象能力和用户体验意识，能够独立完成产品原型设计、项目推进和效果验证；具备强跨团队协同推进能力，能在多方利益诉求中找到最优解，推动复杂项目按时高质量交付。\n\n具备以下条件优先\n1.有 SaaS 数据产品（商家经营看板、数据资产平台等）落地经验者优先 \n2.有 AI 数据产品（如 NL2SQL、数据 Agent、智能取数）落地经验者优先\n3.有数据治理平台建设或数据资产管理经验者优先\n4.有智能数据商业化项目经历者优先\n5.有跨多团队大型项目协同推进经验者优先\n\n岗位亮点\n1.基于公司\"零售+科技\"战略，有机会全身心参与到新零售的多种业态，构建行业认知；同时深度参与 AI 数据化转型，在真实业务场景中探索 AI Agent、智能分析等前沿方向的落地路径。\n2.紧贴业务发展，基于先进的即时零售SaaS产品平台，用数据帮助商家切实解决经营问题；在数据治理体系建设上有充分的发挥空间，能够从0到1建立数据资产标准，推动数据可信、可用、可管。\n3.美团牵牛花的业务市场份额靠前，业务足够复杂、足够完整、新业务足够多，新加入的小伙伴有足够的机会真正接近商业的本质，思考很核心的问题，实现能力跃迁和梦想；团队高度重视 AI 与数据的协同建设，鼓励用 AI 提效、用数据治理夯实底座、用协同推进打通业务壁垒。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4658401805","sourceKey":"meituan_social","company":"美团","title":"酒店民宿商业化高级产品运营","city":"北京市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4658401805&jobShareType=1","duty":"1、负责酒店民宿商业化收入，深入了解酒店行业商业模式，制定并执行收入增长策略，确保收入达成，并实现收入的持续增长。\n\n2、负责制定各项为收入目标负责的指标，确保指标达成，并及时调整策略以应对市场的变化。\n\n3、负责协同相关方共识目标及做功策略，共同达成收入目标。","requirements":"1、5年以上商业化产品经验，对各种变现模式熟悉，且实践过主流的商业化变现模式。\n\n2、熟悉流量运营，可自主制定流量运营策略，提升商业产品的流量变现效率。\n\n3、熟悉商家运营，可自主制定商家运营策略，提升商业产品在线商家数。\n\n4、熟悉酒店行业，对酒店商家经营有深入的了解，能对商家的营销诉求做出清晰的分层分类。\n\n5、数据敏感度高，具备较强的数据分析能力，能通过数据及时判断商业化收入的风险及机会。\n\n6、成长意愿强烈，具备非常强的自驱力和沟通协作能力，能快速学习和跨团队高效合作。","description":"部门介绍\n美团酒店旅行业务涵盖酒店、民宿、机票、火车票、旅游度假、景点门票等各类住行游品类，通过与产业上下游的深度合作，为用户提供美好的旅游旅行体验。我们积极打造AI友好型组织，使用AI等新技术提升旅游服务的供需匹配效率，更好满足用户个性化、多样化的出游需求。我们持续深耕产业链，用数字化服务助力实体商家高质量经营，探索自有品牌等供给新模式，打造健康的商家生态，保障用户服务体验。为满足用户日益增长的跨境旅行需求，我们将聚焦亚太区域，打造高品质的住宿、交通、游玩等服务矩阵。\n这里有多元的业务布局、持续的成长空间，无论是向往的远方还是眼前的工作，一路都是风景相伴。加入我们，共同为用户创造旅游旅行中的高光时刻！\n\n岗位职责\n1、负责酒店民宿商业化收入，深入了解酒店行业商业模式，制定并执行收入增长策略，确保收入达成，并实现收入的持续增长。\n\n2、负责制定各项为收入目标负责的指标，确保指标达成，并及时调整策略以应对市场的变化。\n\n3、负责协同相关方共识目标及做功策略，共同达成收入目标。\n\n岗位基本要求\n1、5年以上商业化产品经验，对各种变现模式熟悉，且实践过主流的商业化变现模式。\n\n2、熟悉流量运营，可自主制定流量运营策略，提升商业产品的流量变现效率。\n\n3、熟悉商家运营，可自主制定商家运营策略，提升商业产品在线商家数。\n\n4、熟悉酒店行业，对酒店商家经营有深入的了解，能对商家的营销诉求做出清晰的分层分类。\n\n5、数据敏感度高，具备较强的数据分析能力，能通过数据及时判断商业化收入的风险及机会。\n\n6、成长意愿强烈，具备非常强的自驱力和沟通协作能力，能快速学习和跨团队高效合作。\n\n具备以下条件优先\n1、理解广告系统背后的逻辑，了解主流平台商业模式，有成功实践案例优先。\n\n岗位亮点\n1、所负责的业务是本地生活行业的核心之一，能够近距离接触到酒店行业前沿的营销策略，可以让你对O2O行业有更全面、更深入的了解，成为酒店领域的业务专家。\n\n2、能培养从流量到供给的全视角商业设计。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4646066049","sourceKey":"meituan_social","company":"美团","title":"无人车智能后端研发工程师","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4646066049&jobShareType=1","duty":"- 负责自动驾驶建图与发布系统的后端架构设计与核心开发，主导数据服务功能的设计、性能调优与高可用保障。\n- 负责自动驾驶数据处理流水线的架构设计与优化，基于分布式实现大规模空间数据的高效处理与调度，持续优化计算资源利用率。\n- 深度参与团队技术规划与选型，沉淀通用组件与最佳实践，推动工程效能与团队技术能力持续提升。","requirements":"- 计算机、软件工程等相关专业本科及以上学历，3 年以上后端开发经验。\n- 扎实的后端编程基础与工程素养，具备复杂业务系统的设计与落地能力。\n- 熟悉分布式原理，有大规模数据处理或流水线系统的实际开发经验。\n- 良好的沟通能力和跨团队协作能力，具备独立分析复杂问题并推动解决的能力。","description":"部门介绍\n无人车业务部成立于2016年，旨在用无人驾驶技术提升物流配送的效率和体验。美团无人车以自研L4级自动驾驶软硬件技术为核心，与美团即时零售业务结合，形成满足公开道路、社区、工业园区等室外全场景下的无人配送整体解决方案。自2020年起，无人车已在北京、深圳等多地进入常态化试运营阶段，在城市复杂场景下提供针对餐饮外卖、生鲜食杂等货物的即时配送服务。2025年，美团无人车又踏上了同城货运的新探索，并在2026年持续扩大运营范围和车队数量，为更多城市带来智能配送服务。\n欢迎加入美团无人车团队，与我们一起用科技推动即时零售再升级！\n\n岗位职责\n- 负责自动驾驶建图与发布系统的后端架构设计与核心开发，主导数据服务功能的设计、性能调优与高可用保障。\n- 负责自动驾驶数据处理流水线的架构设计与优化，基于分布式实现大规模空间数据的高效处理与调度，持续优化计算资源利用率。\n- 深度参与团队技术规划与选型，沉淀通用组件与最佳实践，推动工程效能与团队技术能力持续提升。\n\n岗位基本要求\n- 计算机、软件工程等相关专业本科及以上学历，3 年以上后端开发经验。\n- 扎实的后端编程基础与工程素养，具备复杂业务系统的设计与落地能力。\n- 熟悉分布式原理，有大规模数据处理或流水线系统的实际开发经验。\n- 良好的沟通能力和跨团队协作能力，具备独立分析复杂问题并推动解决的能力。\n\n具备以下条件优先\n- 具有自动驾驶相关业务经验者优先。\n- 有大规模数据质量治理、数据可观测性相关实践经验者优先。\n- 善于借助 AI 工具提升个人与团队研发效率，有实际提效案例者优先。\n\n岗位亮点\n- 系统全面地参与无人车业务全流程，并能够深入了解L4自动驾驶各模块的应用。\n- 面对超大规模的空间数据/传感器数据的工程挑战，积累大规模分布式系统与高并发架构的实战经验。\n- 团队技术氛围浓厚，鼓励技术创新与工程卓越，提供优秀的个人成长空间和环境。\n- 技术成果直接服务于无人车的安全稳定运行，工作产出有明确的业务价值闭环。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4659461155","sourceKey":"meituan_social","company":"美团","title":"自动驾驶系统开发工程师","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4659461155&jobShareType=1","duty":"1. 负责自动驾驶小货车云控系统的整体架构设计与核心模块开发。\n2. 构建云端遥控指令链路，覆盖转向、制动、油门、灯光、鸣笛等底层车辆控制指令的可靠下发与执行反馈闭环。\n3. 开发远程控制终端，集成多路视频流（前视/后视/环视）、车辆状态信息、操控外设（方向盘/踏板/手柄）等多模态人机交互能力。\n4. 支持单操作员多车（1:N） 遥控调度模式，实现高效的人工介入与车队管理。\n5. 开发遥控系统端到端延迟监控与质量评估体系，建立延迟基线与告警机制。\n6. 针对高丢包、高时延、带宽受限、信号抖动等复杂网络场景，设计通信自适应策略。\n7. 开发多链路聚合与动态切换机制（4G/5G/WiFi等），实现网络链路的实时质量评估与无缝切换，保障遥控指令连续性。\n8. 研究并实现时延补偿算法（如 Smith Predictor、卡尔曼预测等），在高延迟场景（200ms+）下维持遥控操作的安全性与可控性。\n9. 开发视频流自适应编码传输策略，基于 WebRTC / SRT / QUIC 等协议，在带宽受限条件下优先保障关键感知信息传输质量（分辨率/帧率动态调节）。\n10. 构建弱网分级响应机制，根据实时网络质量（RTT、丢包率、可用带宽）动态切换遥控模式。\n设计并实现多源控制指令仲裁框架，处理云端遥控指令与车端自动驾驶决策之间的冲突。","requirements":"1. 大学本科及以上学历，计算机、软件工程或相关专业。  \n2. 3年以上软件开发经验，具备分布式系统或云平台开发背景。  \n3. 熟练掌握C++/Python/Go中至少一种语言，熟悉微服务架构与容器化技术。  \n4. 有自动驾驶、车联网或大规模实时系统开发经验者优先。","description":"部门介绍\n无人车业务部成立于2016年，旨在用无人驾驶技术提升物流配送的效率和体验。美团无人车以自研L4级自动驾驶软硬件技术为核心，与美团即时零售业务结合，形成满足公开道路、社区、工业园区等室外全场景下的无人配送整体解决方案。自2020年起，无人车已在北京、深圳等多地进入常态化试运营阶段，在城市复杂场景下提供针对餐饮外卖、生鲜食杂等货物的即时配送服务。2025年，美团无人车又踏上了同城货运的新探索，并在2026年持续扩大运营范围和车队数量，为更多城市带来智能配送服务。\n欢迎加入美团无人车团队，与我们一起用科技推动即时零售再升级！\n\n岗位职责\n1. 负责自动驾驶小货车云控系统的整体架构设计与核心模块开发。\n2. 构建云端遥控指令链路，覆盖转向、制动、油门、灯光、鸣笛等底层车辆控制指令的可靠下发与执行反馈闭环。\n3. 开发远程控制终端，集成多路视频流（前视/后视/环视）、车辆状态信息、操控外设（方向盘/踏板/手柄）等多模态人机交互能力。\n4. 支持单操作员多车（1:N） 遥控调度模式，实现高效的人工介入与车队管理。\n5. 开发遥控系统端到端延迟监控与质量评估体系，建立延迟基线与告警机制。\n6. 针对高丢包、高时延、带宽受限、信号抖动等复杂网络场景，设计通信自适应策略。\n7. 开发多链路聚合与动态切换机制（4G/5G/WiFi等），实现网络链路的实时质量评估与无缝切换，保障遥控指令连续性。\n8. 研究并实现时延补偿算法（如 Smith Predictor、卡尔曼预测等），在高延迟场景（200ms+）下维持遥控操作的安全性与可控性。\n9. 开发视频流自适应编码传输策略，基于 WebRTC / SRT / QUIC 等协议，在带宽受限条件下优先保障关键感知信息传输质量（分辨率/帧率动态调节）。\n10. 构建弱网分级响应机制，根据实时网络质量（RTT、丢包率、可用带宽）动态切换遥控模式。\n设计并实现多源控制指令仲裁框架，处理云端遥控指令与车端自动驾驶决策之间的冲突。\n\n岗位基本要求\n1. 大学本科及以上学历，计算机、软件工程或相关专业。  \n2. 3年以上软件开发经验，具备分布式系统或云平台开发背景。  \n3. 熟练掌握C++/Python/Go中至少一种语言，熟悉微服务架构与容器化技术。  \n4. 有自动驾驶、车联网或大规模实时系统开发经验者优先。\n\n岗位亮点\n1. 参与前沿自动驾驶技术落地，推动智能交通发展。  \n2. 技术挑战性强，成长空间大，与团队共同协作成长。  \n3. 工作地点位于北京，提供具有竞争力的薪酬与福利体系。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4483049818","sourceKey":"meituan_social","company":"美团","title":"政企渠道大客户专家","city":"杭州市/宁波市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4483049818&jobShareType=1","duty":"1、负责所在区域政府事务拓展和维护；\n2、负责所在区域合作商拓展和维护；\n3、推动美团共享电单车投放运营；\n4、优化美团共享电单车运营环境；\n5、提高美团共享电单车市场占有率。","requirements":"1、本科5年以上政府业务工作经验；\n2、在政府业务上有较好且持续的产出；\n3、熟悉政府组织架构，熟悉政府决策程序。","description":"部门介绍\n美团骑行事业部在全国各个城市开展美团单车、电单车业务，提供绿色、便捷的共享出行服务，是美团出行板块重要的组成部分。我们力求为城市可持续发展提供低碳智能的解决方案，通过技术创新和硬件升级，不断优化全流程骑行体验，为低碳出行提供更好的服务。其中，美团单车旨在为城市居民提供通勤接驳服务，满足用户短途接驳出行需求；美团电单车则满足用户中短途多场景低碳出行需求。\n我们有开放的工作氛围，也有充满韧劲和创造力，心系低碳出行的伙伴。加入我们，一起为用户创造更好的出行体验。\n\n岗位职责\n1、负责所在区域政府事务拓展和维护；\n2、负责所在区域合作商拓展和维护；\n3、推动美团共享电单车投放运营；\n4、优化美团共享电单车运营环境；\n5、提高美团共享电单车市场占有率。\n\n岗位基本要求\n1、本科5年以上政府业务工作经验；\n2、在政府业务上有较好且持续的产出；\n3、熟悉政府组织架构，熟悉政府决策程序。\n\n具备以下条件优先\n1、具有良好的高线G端资源；\n2、具有良好的高线合作商资源；\n3、成功主导过G端大项目。\n\n岗位亮点\n1、更系统化的成长机会；\n2、大平台积累更多的资源；3、具有更大的上升空间。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4634247048","sourceKey":"meituan_social","company":"美团","title":"品牌营销设计专家","city":"上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4634247048&jobShareType=1","duty":"1. 负责品牌营销策略的制定与执行，提升品牌市场影响力和用户认知度。  \n2. 策划并落地线上线下整合营销活动，推动品牌声量与销售转化双增长。  \n3. 管理品牌视觉体系与内容输出，确保品牌形象的一致性与专业性。  \n4. 协同产品、运营及外部合作伙伴，推动跨部门项目高效落地。","requirements":"1. 大学本科及以上学历，市场营销、广告、设计等相关专业优先。  \n2. 5年以上品牌营销或相关领域工作经验，具备完整项目操盘经验。  \n3. 熟悉数字营销、社交媒体传播及内容创意策略，熟练掌握AI设计工具，具备数据驱动思维。  \n4. 优秀的沟通协调能力与项目管理能力，能独立推进复杂项目。","description":"部门介绍\n大众点评作为国内重要的本地生活消费决策参考平台，多年来深耕本地生活消费领域，深受广大用户的信任和喜爱。我们的业务覆盖了吃喝玩乐游购娱等生活场景，通过极具辨识度和公信力的”星级“和”评价“产品，为数亿用户提供了全面、可信的消费决策依据。为更好满足用户探索城市的需求，大众点评在原有星级和评价的基础上，以信息流产品形式，助力用户发现更多好去处。大量优秀年轻同学的加入，为我们的团队注入了澎湃活力。我们相信，真实的生活是不可替代的，真实的感受是值得记录的，真实的美好是要被看到的。希望优秀的你能和我们一起，帮助广大用户在大众点评上发现更多好去处，找到属于自己的人间烟火气，共创美好生活。\n\n岗位职责\n1. 负责品牌营销策略的制定与执行，提升品牌市场影响力和用户认知度。  \n2. 策划并落地线上线下整合营销活动，推动品牌声量与销售转化双增长。  \n3. 管理品牌视觉体系与内容输出，确保品牌形象的一致性与专业性。  \n4. 协同产品、运营及外部合作伙伴，推动跨部门项目高效落地。\n\n岗位基本要求\n1. 大学本科及以上学历，市场营销、广告、设计等相关专业优先。  \n2. 5年以上品牌营销或相关领域工作经验，具备完整项目操盘经验。  \n3. 熟悉数字营销、社交媒体传播及内容创意策略，熟练掌握AI设计工具，具备数据驱动思维。  \n4. 优秀的沟通协调能力与项目管理能力，能独立推进复杂项目。\n\n岗位亮点\n1. 加入快速发展的创新团队，拥有广阔的职业成长空间。  \n2. 深度参与品牌战略建设，发挥个人创意与专业影响力。  \n3. 提供具有竞争力的薪酬福利与灵活的工作环境。  \n4. 位于上海核心区域，交通便利，办公环境优越。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4656309187","sourceKey":"meituan_social","company":"美团","title":"闪购-歪马-前置仓区域主管（深圳）","city":"深圳市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4656309187&jobShareType=1","duty":"1.管辖10-13个酒水前置仓的业务开拓和日常管理；\n2.团队搭建，完成前置仓团队搭建，人员选用育励汰；\n3.具备一定的销售管理能力，有进行目标拆解和过程管理能力，承担区域增长目标，完成地推获客，留存等增长指标；\n4.对前置仓的商品进行管理，并不断提高前置仓操作规范性；\n5.保障前置仓的日常营运，确保配送时效，前置仓内商品准确，保障用户体验；\n6.有较好的数据意识，能通过数据发现前置仓运行中的问题；\n7.有较好的成本意识，能合理管控仓内日常消耗品、地推赠品等耗材的管理。","requirements":"1.本科学历，有1-3年的前置仓履约或直销管理经验，熟悉零售业务，对前置仓管理、商品管理等有一定经验；\n2.熟悉即时配业务特性，关注用户体验；\n3.有较好的团队管理、人员培养的经验和方法沉淀；\n4.价值观正，能够横向协同多部门，达成公司业务指标；\n5.有较好的数据敏感度，能够透过数据发现问题。","description":"部门介绍\n美团闪购是美团旗下的即时零售平台，依托即时配送能力，连接本地零售供给，满足消费者30分钟万物到家的即时需求。美团闪购涵盖超市便利、食材、水果、鲜花绿植、休闲零食、酒水饮料、数码家电、美妆个护、母婴玩具、日用百货、服饰鞋帽、宠物等诸多品类，业务覆盖全国近3,000个县市区旗，每日百万级在岗骑手，以高效的配送、丰富的品类和广泛的覆盖，为美团数亿用户带来便捷的生活体验，积极助力实体零售线上化转型，提升本地商业活力。\n\n岗位职责\n1.管辖10-13个酒水前置仓的业务开拓和日常管理；\n2.团队搭建，完成前置仓团队搭建，人员选用育励汰；\n3.具备一定的销售管理能力，有进行目标拆解和过程管理能力，承担区域增长目标，完成地推获客，留存等增长指标；\n4.对前置仓的商品进行管理，并不断提高前置仓操作规范性；\n5.保障前置仓的日常营运，确保配送时效，前置仓内商品准确，保障用户体验；\n6.有较好的数据意识，能通过数据发现前置仓运行中的问题；\n7.有较好的成本意识，能合理管控仓内日常消耗品、地推赠品等耗材的管理。\n\n岗位基本要求\n1.本科学历，有1-3年的前置仓履约或直销管理经验，熟悉零售业务，对前置仓管理、商品管理等有一定经验；\n2.熟悉即时配业务特性，关注用户体验；\n3.有较好的团队管理、人员培养的经验和方法沉淀；\n4.价值观正，能够横向协同多部门，达成公司业务指标；\n5.有较好的数据敏感度，能够透过数据发现问题。\n\n具备以下条件优先\n熟悉零售业务，有销售管理、前置仓管理、商品管理经验优先\n\n岗位亮点\n1.歪马业务是闪购事业部下新成立的，由前线业务+运营/采购+产品全闭环的组织\n2.歪马业务聚焦于酒类万亿市场，通过中心仓+前置仓、平台自营模式，为用户提供15分钟送达的买酒业务\n3.业务当前正处于0-1的快速迭代时期，可以从0-1参与新业务的产品建设\n4.全方位深入业务，在全闭环的组织里感受不同职能彼此的输入/输出，同时可以参与业务模式的定义\n5.足够宽的业务范围，深入参与自营零售业务的经营","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3358221550","sourceKey":"meituan_social","company":"美团","title":"品牌卫星店-解决方案专家（AI方向）","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3358221550&jobShareType=1","duty":"1、负责连锁客户的新市场机会洞察，深入理解大模型的原理、相关技术栈及工具，挖掘市场机会（如潜力品类、场景创新、区域空白市场等）；\n2、紧跟技术发展前沿，具备AI能力应用落地的实战经验和创新能力，具备敏锐的市场洞察力，能深入理解目标客户及行业的业务场景与痛点，挖掘Agent应用需求，打造具有行业影响力解决方案。\n3、协同销售团队参与客户业务拓展，对商机进行初步判断与价值评估，能够从商家开店，经营、增长趋势中找到关键痛点，设计AI应用解决方案，推动商机和业绩达成。\n4、确保为客户设计的解决方案具备可落地性，兼顾效果与成本，与交付团队紧密合作，达成方案落地，并及时提供有效的咨询服务与技术支持。","requirements":"1、本科及以上学历，计算机科学、人工智能、软件工程、数学、物理等相关专业优先。\n2、2年以上大模型或AI产品的客户解决方案或售前相关工作经验。熟悉主流大模型技术原理，对算力、基础设施等关联技术领域有所了解；有算法、算法工程或系统架构能力背景者优先。\n3、具有良好的逻辑思维能力和问题解决能力，能够从复杂的数据和业务场景中提炼关键信息，提出有效的解决方案。\n4、具备良好的沟通能力、路演能力及客情关系管理能力。","description":"部门介绍\n美团外卖秉承“帮大家吃得更好，生活更好”的使命，始终聚焦于消费者用餐需求。我们通过科技连接消费者和商家，依托庞大的骑手团队，以“线上+线下”的业务模式，为消费者提供品质化、精细化、多样化的餐饮外卖服务。\n外卖事业部是为用户与商家提供全链路交易服务的业务组织，围绕餐饮外卖搭建了包含外卖业务与创新孵化业务在内的多个部门。\n我们的目标是帮助商家开源增收、提高经营效率，促进餐饮行业数字化，以及为更多用户提供更便捷更有品质的外卖服务。加入我们，一起为上亿用户提供更好的用餐体验，帮助大家吃得更好，生活更好！\n\n岗位职责\n1、负责连锁客户的新市场机会洞察，深入理解大模型的原理、相关技术栈及工具，挖掘市场机会（如潜力品类、场景创新、区域空白市场等）；\n2、紧跟技术发展前沿，具备AI能力应用落地的实战经验和创新能力，具备敏锐的市场洞察力，能深入理解目标客户及行业的业务场景与痛点，挖掘Agent应用需求，打造具有行业影响力解决方案。\n3、协同销售团队参与客户业务拓展，对商机进行初步判断与价值评估，能够从商家开店，经营、增长趋势中找到关键痛点，设计AI应用解决方案，推动商机和业绩达成。\n4、确保为客户设计的解决方案具备可落地性，兼顾效果与成本，与交付团队紧密合作，达成方案落地，并及时提供有效的咨询服务与技术支持。\n\n岗位基本要求\n1、本科及以上学历，计算机科学、人工智能、软件工程、数学、物理等相关专业优先。\n2、2年以上大模型或AI产品的客户解决方案或售前相关工作经验。熟悉主流大模型技术原理，对算力、基础设施等关联技术领域有所了解；有算法、算法工程或系统架构能力背景者优先。\n3、具有良好的逻辑思维能力和问题解决能力，能够从复杂的数据和业务场景中提炼关键信息，提出有效的解决方案。\n4、具备良好的沟通能力、路演能力及客情关系管理能力。\n\n岗位亮点\n1、提供深入学习AI的新业务机会，可积累大体量AI解决方案经验；\n2、能够深入商家，平台，用户三重视角，提升综合能力和底层系统的构建能力","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:1520168069","sourceKey":"meituan_social","company":"美团","title":"乐生活北部战区-产品销售","city":"北京市/天津市/石家庄市/太原市/呼和浩特市/沈阳市/大连市/长春市/哈尔滨市/洛阳市/兰州市/乌鲁木齐市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=1520168069&jobShareType=1","duty":"1．通过销售拜访，了解商户的业务现状与实际需求并结合消费者的消费动向，制定个性化营销方案，与商户谈判并达成合作；\n2．执行公司的销售策略及政策，达成业绩目标；\n3．与公司各部门配合，及时处理用户的反馈、投诉和建议，提高用户满意度；\n4．归档和更新所有目标商户拜访、协议、服务条款等有关的文件和数据，确保信息在数据库中得到正确的维护。\n5、 借助AI销售辅助工具分析商户经营现状和消费者消费动向，制定数据驱动的个性化营销方案，通过数字化系统追踪拜访进程，提升商户合作达成效率。","requirements":"1．大专及以上学历，有销售工作经验优先。可接受优秀应届毕业生。\n2．有很强的学习能力和适应能力，适应互联网行业的快速发展；\n3．具备较强的人际沟通及逻辑思维能力，思维敏捷，能够准确把握产品优势和客户心理，高效整合内外部资源促成销售业绩；\n4．富有激情和创新理念，追求个人职业发展和公司利益的双赢；\n5．热爱销售，善于挑战，积极乐观，有强烈的成功欲望和企图心；\n6．为人正直，诚实可靠，以公司利益为重。","description":"部门介绍\n美团服务零售事业部下设乐生活业务部、易生活业务部、进场零售业务部以及中小城市发展部四大业务部门，旨在通过提供丰富、可靠、实惠的服务与商品满足用户各类生活需求。我们所处的服务零售行业是一个具有万亿规模的市场，覆盖足疗洗浴、酒吧KTV、运动健身、美发美甲、教育培训、亲子游乐、家政洗涤维修、摄影写真等数十个服务消费细分领域，同时延伸至超市便利、美妆个护、3C数码、服饰珠宝、运动户外、商场购物中心等实体零售到店消费场景，连接数十万品牌商户与线下门店。作为商家和行业的小帮手，我们持续深入服务零售与实体零售产业链，用AI等技术推动行业变革，帮助商家提升经营效率、实现高效的线上化经营与到店转化，优化消费者服务体验，提供安心、放心的履约保障。这里有着多元的业务布局，有着富有挑战和影响力的工作内容，为你提供丰富的视野、持续的成长和发展机会，引领你发现更多可能。期待和你在“随时随地，美好生活”的愿景指引下，共建美好的生活服务体验、健康的商家生态与高质量的经营结果。\n\n岗位职责\n1．通过销售拜访，了解商户的业务现状与实际需求并结合消费者的消费动向，制定个性化营销方案，与商户谈判并达成合作；\n2．执行公司的销售策略及政策，达成业绩目标；\n3．与公司各部门配合，及时处理用户的反馈、投诉和建议，提高用户满意度；\n4．归档和更新所有目标商户拜访、协议、服务条款等有关的文件和数据，确保信息在数据库中得到正确的维护。\n5、 借助AI销售辅助工具分析商户经营现状和消费者消费动向，制定数据驱动的个性化营销方案，通过数字化系统追踪拜访进程，提升商户合作达成效率。\n\n岗位基本要求\n1．大专及以上学历，有销售工作经验优先。可接受优秀应届毕业生。\n2．有很强的学习能力和适应能力，适应互联网行业的快速发展；\n3．具备较强的人际沟通及逻辑思维能力，思维敏捷，能够准确把握产品优势和客户心理，高效整合内外部资源促成销售业绩；\n4．富有激情和创新理念，追求个人职业发展和公司利益的双赢；\n5．热爱销售，善于挑战，积极乐观，有强烈的成功欲望和企图心；\n6．为人正直，诚实可靠，以公司利益为重。\n\n岗位亮点\n有机会学习并掌握互联网本地生活的工作方式，呼和浩特、洛阳、兰州有CKA销售岗位","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4241122072","sourceKey":"meituan_social","company":"美团","title":"快乐猴-3R采购高阶岗","city":"北京市/杭州市/广州市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4241122072&jobShareType=1","duty":"岗位职责:\n1.负责3R品类区域采购和销售的目标规划、路径拆解、关键业务指标的达成和团队的管理；\n2.制定对应品类的商品规划、招商计划、商家进场谈判，确保公司得到更好的采购条件，制定合作条款，管理供应商入场后行为，与商家建立良好的沟通和管理机制。\n3.管理竞争对手调查和消费者调查，把握市场动态，及时调整商品成本、商品结构、新品上架等经营策略，确保品类竞争处于优势。\n4.负责品类KA品牌商家管理及产业带溯源开发与孵化；\n5.开发相关品类品质保障核心商品，提升整体平台的差异化能力；","requirements":"1.5年以上大型商超或者电商平台品类采购经验，对库存管理、损耗控制等有实操经验，有团队的管理和操盘经验；\n2.具有较强的分析判断、前瞻思维、承压能力和团队合作意识，有采购团队管理经验；\n3.具备电商的采销和运营经验，熟悉生鲜电商的营销方法；\n4.具备线下生鲜零售和线上生鲜的知识和经营，具备生鲜零售业的创新能力，具有优秀的组织协调能力，决策能力高、较高的商业敏锐度，全局观强；\n5.具备项目统筹能力，能够协调和推进公司各支持部门完成项目落地及后续效率优化；\n6.具备团队管理经验与能力\n6. 自驱力强，具有较好的学习能力，愿意主动思考AI如何进一步优化工作流程；\n7.掌握基本的AI工具，使用工具提升工作流程效率。","description":"部门介绍\n快乐猴是美团自营社区超市，依托自有供应链和门店管理体系，聚焦家庭用户的三餐所需，为消费者提供高质价比的食杂商品。快乐猴以数字化能力与科学品控为基础，不断满足消费者对“省”和“便利”的需求。\n\n岗位职责\n岗位职责:\n1.负责3R品类区域采购和销售的目标规划、路径拆解、关键业务指标的达成和团队的管理；\n2.制定对应品类的商品规划、招商计划、商家进场谈判，确保公司得到更好的采购条件，制定合作条款，管理供应商入场后行为，与商家建立良好的沟通和管理机制。\n3.管理竞争对手调查和消费者调查，把握市场动态，及时调整商品成本、商品结构、新品上架等经营策略，确保品类竞争处于优势。\n4.负责品类KA品牌商家管理及产业带溯源开发与孵化；\n5.开发相关品类品质保障核心商品，提升整体平台的差异化能力；\n\n岗位基本要求\n1.5年以上大型商超或者电商平台品类采购经验，对库存管理、损耗控制等有实操经验，有团队的管理和操盘经验；\n2.具有较强的分析判断、前瞻思维、承压能力和团队合作意识，有采购团队管理经验；\n3.具备电商的采销和运营经验，熟悉生鲜电商的营销方法；\n4.具备线下生鲜零售和线上生鲜的知识和经营，具备生鲜零售业的创新能力，具有优秀的组织协调能力，决策能力高、较高的商业敏锐度，全局观强；\n5.具备项目统筹能力，能够协调和推进公司各支持部门完成项目落地及后续效率优化；\n6.具备团队管理经验与能力\n6. 自驱力强，具有较好的学习能力，愿意主动思考AI如何进一步优化工作流程；\n7.掌握基本的AI工具，使用工具提升工作流程效率。\n\n岗位亮点\n发展空间大，扁平化管理，\n团队氛围好，横向交叉工作和学习的机会非常多","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4654644911","sourceKey":"meituan_social","company":"美团","title":"小象长沙常温仓生产主管-正编","city":"长沙市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4654644911&jobShareType=1","duty":"1. 负责小象常温仓日常生产运营管理工作，确保仓储作业高效、安全、有序进行。  \n2. 制定并优化仓库生产流程，提升作业效率，控制运营成本。  \n3. 管理并指导一线操作团队，完成入库、存储、拣选、打包、出库等全流程作业。  \n4. 监控库存准确率与订单履约时效，及时处理异常情况并推动改进措施。  \n5. 落实安全生产制度，组织培训与检查，保障人员与货物安全。","requirements":"1. 大学专科及以上学历，物流、供应链、仓储管理等相关专业优先。  \n2. 具备3年以上仓储或物流行业生产管理经验，有电商或生鲜仓储背景者优先。  \n3. 熟悉WMS系统操作及仓储作业流程，具备较强的数据分析与问题解决能力。  \n4. 具备良好的沟通协调能力和团队管理能力，能承受一定工作压力。  \n5. 工作认真负责，执行力强，具备较强的责任心。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1. 负责小象常温仓日常生产运营管理工作，确保仓储作业高效、安全、有序进行。  \n2. 制定并优化仓库生产流程，提升作业效率，控制运营成本。  \n3. 管理并指导一线操作团队，完成入库、存储、拣选、打包、出库等全流程作业。  \n4. 监控库存准确率与订单履约时效，及时处理异常情况并推动改进措施。  \n5. 落实安全生产制度，组织培训与检查，保障人员与货物安全。\n\n岗位基本要求\n1. 大学专科及以上学历，物流、供应链、仓储管理等相关专业优先。  \n2. 具备3年以上仓储或物流行业生产管理经验，有电商或生鲜仓储背景者优先。  \n3. 熟悉WMS系统操作及仓储作业流程，具备较强的数据分析与问题解决能力。  \n4. 具备良好的沟通协调能力和团队管理能力，能承受一定工作压力。  \n5. 工作认真负责，执行力强，具备较强的责任心。\n\n具备以下条件优先\n需具备现场管理工作经验，有过带领生产团队经验\n\n岗位亮点\n1. 加入快速发展的新零售平台，拥有广阔的职业发展空间。  \n2. 提供完善的培训体系和晋升通道，助力个人成长。  \n3. 工作地点位于长沙，团队氛围积极，管理扁平高效。  \n4. 享受具有竞争力的薪酬福利及五险一金、带薪年假等法定福利。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4646252634","sourceKey":"meituan_social","company":"美团","title":"小象超市资产管理中台策略岗","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4646252634&jobShareType=1","duty":"1.负责线上店运营各项资产管理管控工作，梳理全链条中损耗产生的异常点并推动改善，负责资产运营策略输出，建设标准化资产管理体系，支撑一线业务稳定高效运营。\n2.负责资产类指标数据监控，识别问题、诊断根因并提出有效治理举措，制定可行计划并追踪落地，达成业务目标。\n3.负责搭建资产管理系统工具，合理规划业务需求并量化价值，推动产品能力建设，实现资产管理降本增效。\n4.协调内外部跨部门资源，推动资产策略运营项目的进展和落地，拿到业务结果。","requirements":"1.本科及以上学历，具备3-5年以上互联网工作背景优先；\n2.有良好的沟通能力和团队协作意识，善于发现并追踪解决问题；\n3.具备良好的逻辑思维能力，对待工作认真负责，具备主人翁意识；\n4.善于用量化指标表达结果，有与终端用户、产品等多方密切配合经验者优先；\n5.有策略优化能力、会推动运营、写作基本功扎实、数据分析能力强(会SQL)。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1.负责线上店运营各项资产管理管控工作，梳理全链条中损耗产生的异常点并推动改善，负责资产运营策略输出，建设标准化资产管理体系，支撑一线业务稳定高效运营。\n2.负责资产类指标数据监控，识别问题、诊断根因并提出有效治理举措，制定可行计划并追踪落地，达成业务目标。\n3.负责搭建资产管理系统工具，合理规划业务需求并量化价值，推动产品能力建设，实现资产管理降本增效。\n4.协调内外部跨部门资源，推动资产策略运营项目的进展和落地，拿到业务结果。\n\n岗位基本要求\n1.本科及以上学历，具备3-5年以上互联网工作背景优先；\n2.有良好的沟通能力和团队协作意识，善于发现并追踪解决问题；\n3.具备良好的逻辑思维能力，对待工作认真负责，具备主人翁意识；\n4.善于用量化指标表达结果，有与终端用户、产品等多方密切配合经验者优先；\n5.有策略优化能力、会推动运营、写作基本功扎实、数据分析能力强(会SQL)。\n\n具备以下条件优先\n优秀的数据分析能力，有较强的沟通协调能力及项目管理能力。\n\n岗位亮点\n成熟互联网业务运营团队，可学习扎实的运营策略管理机制。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4657476970","sourceKey":"meituan_social","company":"美团","title":"IT物资供应链策略","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4657476970&jobShareType=1","duty":"1、IT资产供应链策略与优化\n - 负责 IT 资产端到端供应链体系建设，覆盖需求预测、采购、库存、仓储物流、资产流转及逆向处置等环节，提升供应保障能力和运营效率。\n - 制定成本优化及库存策略，平衡供应、成本与风险，提升资产投入产出效率。\n - 推动供应链数字化建设，结合数据分析、自动化及 AI 等技术提升管理效率和决策能力。\n2、IT资产生命周期管理\n - 建立并优化 IT 资产全生命周期管理体系，推动采购、使用、运维、回收、报废等环节标准化、规范化和合规化。\n - 基于资产数据分析识别优化机会，提升资产利用率和管理精细化水平。\n3、供应生态与风险治理\n - 建立供应生态管理体系，持续优化供应模式、服务能力和合作机制，提升供应链韧性和业务支撑能力。\n - 识别供应链关键风险，建立风险预警、应急保障及持续改进机制，保障业务连续性。\n4、AI驱动的智能化建设\n - 探索与推动 AI 在 IT 资产与供应链场景中的应用，覆盖需求预测、库存优化、资产盘点、异常识别及流程自动化等方向，提升管理效率和决策质量。\n - 结合业务需求建设知识库、智能体（Agent）及自动化能力，推动资产管理和供应链运营智能化升级。","requirements":"1、5年以上 IT 资产管理或供应链管理相关经验，具备跨区域或跨国企业工作经验者优先。熟悉 IT 硬件、软件许可及云服务采购流程，具备端到端供应链管理及 IT 资产全生命周期管理经验。\n2、具备较强的数据分析和业务洞察能力，能够从业务和组织视角识别真实问题，围绕成本、效率、风险等维度制定策略并推动落地；具备供应商管理经验，能够搭建评估体系并持续优化合作模式。\n3、具备复杂问题解决和创新能力，能够突破现状、推动业务改进；善于借助 AI 等新技术提升问题分析、方案设计和流程优化效率，理解生成式 AI 应用场景及边界，具备数据安全和合规意识。\n4、具备优秀的跨部门协同和项目推动能力，能够整合全球团队、业务部门及供应商资源，建立深度合作关系并赢得信任，推动复杂项目落地。\n5、具备战略思维、结果导向和组织建设意识，能够明确方向、推动执行，并持续培养团队能力；坚持正直、利他的原则，在复杂场景下做出正确判断。\n6、英语流利，能够与全球团队及供应商进行高效沟通。","description":"部门介绍\n基础研发平台是美团的核心技术平台，立足于“零售+科技”的战略定位，通过打造人工智能、大数据、云计算、安全等核心技术能力，以及研发效能平台、企业应用平台等公共服务，为业务提供稳定安全、扩展易用、技术领先的平台技术和产品服务。\n在这里，我们会参与到最前沿的技术研发和探索；能够接触超规模集群、海量数据，挑战高复杂业务场景，有机会与业界一流的工程师一起并肩前行。\n在这里，我们有超强的技术氛围，持续向社区贡献业界实践，加速行业技术发展；我们有完善的互联网学习生态圈，重视底层逻辑和方法论，助力职业生涯的非线性成长。\n真诚地邀请你，和我们一起驱动技术发展，创造行业价值。\n\n岗位职责\n1、IT资产供应链策略与优化\n - 负责 IT 资产端到端供应链体系建设，覆盖需求预测、采购、库存、仓储物流、资产流转及逆向处置等环节，提升供应保障能力和运营效率。\n - 制定成本优化及库存策略，平衡供应、成本与风险，提升资产投入产出效率。\n - 推动供应链数字化建设，结合数据分析、自动化及 AI 等技术提升管理效率和决策能力。\n2、IT资产生命周期管理\n - 建立并优化 IT 资产全生命周期管理体系，推动采购、使用、运维、回收、报废等环节标准化、规范化和合规化。\n - 基于资产数据分析识别优化机会，提升资产利用率和管理精细化水平。\n3、供应生态与风险治理\n - 建立供应生态管理体系，持续优化供应模式、服务能力和合作机制，提升供应链韧性和业务支撑能力。\n - 识别供应链关键风险，建立风险预警、应急保障及持续改进机制，保障业务连续性。\n4、AI驱动的智能化建设\n - 探索与推动 AI 在 IT 资产与供应链场景中的应用，覆盖需求预测、库存优化、资产盘点、异常识别及流程自动化等方向，提升管理效率和决策质量。\n - 结合业务需求建设知识库、智能体（Agent）及自动化能力，推动资产管理和供应链运营智能化升级。\n\n岗位基本要求\n1、5年以上 IT 资产管理或供应链管理相关经验，具备跨区域或跨国企业工作经验者优先。熟悉 IT 硬件、软件许可及云服务采购流程，具备端到端供应链管理及 IT 资产全生命周期管理经验。\n2、具备较强的数据分析和业务洞察能力，能够从业务和组织视角识别真实问题，围绕成本、效率、风险等维度制定策略并推动落地；具备供应商管理经验，能够搭建评估体系并持续优化合作模式。\n3、具备复杂问题解决和创新能力，能够突破现状、推动业务改进；善于借助 AI 等新技术提升问题分析、方案设计和流程优化效率，理解生成式 AI 应用场景及边界，具备数据安全和合规意识。\n4、具备优秀的跨部门协同和项目推动能力，能够整合全球团队、业务部门及供应商资源，建立深度合作关系并赢得信任，推动复杂项目落地。\n5、具备战略思维、结果导向和组织建设意识，能够明确方向、推动执行，并持续培养团队能力；坚持正直、利他的原则，在复杂场景下做出正确判断。\n6、英语流利，能够与全球团队及供应商进行高效沟通。\n\n具备以下条件优先\n1、具备 CSCP、PMP、ITIL 等相关专业认证者优先。 \n2、具备大型跨国企业或 IT 服务行业经验，熟悉全球化运营环境及相关合规要求者优先。 \n3、具备 AI 在 IT 资产管理或供应链场景中的实践经验者优先，包括知识库、智能体（Agent）、自动化流程、AI Coding 等应用实践，并能够结合业务场景说明实际价值和效率提升。\n\n岗位亮点\n1、战略影响力：参与 IT 资产管理与供应链体系建设，推动资产管理模式、供应链策略及数字化能力升级，提升组织运营效率和业务支撑能力。 \n2、全球化视野与资源整合：协同全球业务、供应商及合作伙伴，参与跨区域供应链管理实践，积累全球化 IT 资产运营和资源整合经验。 \n3、创新驱动与能力成长：鼓励探索数字化、自动化及 AI 等新技术在 IT 资产与供应链场景中的应用，推动管理模式创新和效率提升。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4626566661","sourceKey":"meituan_social","company":"美团","title":"闪购-歪马-贵阳运营督导（物流方向）","city":"贵阳市/兰州市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4626566661&jobShareType=1","duty":"1.负责区域内仓配合作商日常全流程运营的监督管理，运营异常诊断及解决，保障中心仓运营符合流程标准、高效稳定。\n2.负责管控区域内仓配成本、运营指标、安全合规等事项，协助完成月度经营结果分析，持续通过赋能管理合作商实现质量提升、效率优化与成本降低。\n3.负责区域内开搬扩相关协同工作。\n4.负责区域内合作商运营赋能、考核、巡检、运营提升等工作，并完善管理策略和方式方法，不断提升管理水平，形成闭环管理。\n5.推动物流能力建设与业务发展需要相匹配；辅助大区负责人制定合理的经运营决策。\n6.贯彻执行总部及大区策略，配合落地新业务，保持动态协同，并在落地过程中不断反馈及支持迭代策略。","requirements":"1.本科学历，有专业仓储现场运营管理经历，有运输配送运营、大型商超仓、电商仓管理经验或背景者优先。\n2.物流运营经验5年及以上。\n3.沟通能力强，具备协同多方解决复杂问题的能力，过往有过类似案例。\n4.逻辑能力强，能够快速发现问题、找到原因，并能够快速形成解决方案落地改善。\n5.学习能力强，能够快速接受、学习新业务知识。\n6.有耐心、热情，有以客户为中心的意识。\n7.具备一定的数据分析能力，能够熟练运用数据处理软件，掌握常用公式及基本的透视统计操作。\n8.熟悉物流成本结构，具备成本优化意识，并具备相关专业技能和管理手段。\n9.能接受工作地点轮换，能接受经常性出差。","description":"部门介绍\n美团闪购是美团旗下的即时零售平台，依托即时配送能力，连接本地零售供给，满足消费者30分钟万物到家的即时需求。美团闪购涵盖超市便利、食材、水果、鲜花绿植、休闲零食、酒水饮料、数码家电、美妆个护、母婴玩具、日用百货、服饰鞋帽、宠物等诸多品类，业务覆盖全国近3,000个县市区旗，每日百万级在岗骑手，以高效的配送、丰富的品类和广泛的覆盖，为美团数亿用户带来便捷的生活体验，积极助力实体零售线上化转型，提升本地商业活力。\n\n岗位职责\n1.负责区域内仓配合作商日常全流程运营的监督管理，运营异常诊断及解决，保障中心仓运营符合流程标准、高效稳定。\n2.负责管控区域内仓配成本、运营指标、安全合规等事项，协助完成月度经营结果分析，持续通过赋能管理合作商实现质量提升、效率优化与成本降低。\n3.负责区域内开搬扩相关协同工作。\n4.负责区域内合作商运营赋能、考核、巡检、运营提升等工作，并完善管理策略和方式方法，不断提升管理水平，形成闭环管理。\n5.推动物流能力建设与业务发展需要相匹配；辅助大区负责人制定合理的经运营决策。\n6.贯彻执行总部及大区策略，配合落地新业务，保持动态协同，并在落地过程中不断反馈及支持迭代策略。\n\n岗位基本要求\n1.本科学历，有专业仓储现场运营管理经历，有运输配送运营、大型商超仓、电商仓管理经验或背景者优先。\n2.物流运营经验5年及以上。\n3.沟通能力强，具备协同多方解决复杂问题的能力，过往有过类似案例。\n4.逻辑能力强，能够快速发现问题、找到原因，并能够快速形成解决方案落地改善。\n5.学习能力强，能够快速接受、学习新业务知识。\n6.有耐心、热情，有以客户为中心的意识。\n7.具备一定的数据分析能力，能够熟练运用数据处理软件，掌握常用公式及基本的透视统计操作。\n8.熟悉物流成本结构，具备成本优化意识，并具备相关专业技能和管理手段。\n9.能接受工作地点轮换，能接受经常性出差。\n\n具备以下条件优先\n有酒水仓储配送经验优先；有合作商管理经验优先；有AI经验优先。\n\n岗位亮点\n快速发展的即时零售平台，业务处于蓬勃发展期，个人成长快，发展空间大。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4617840252","sourceKey":"meituan_social","company":"美团","title":"充电宝CKA销售（福州）","city":"福州市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4617840252&jobShareType=1","duty":"1. 连锁品牌开发：负责城市内10-50家门店连锁品牌的从0到1开发；识别品牌总部KP制定整体方案，一次谈判覆盖全品牌门店，而非逐店攻坚。\n2. 客户关系深耕：维护签约连锁品牌的核心客情，定期触达关键决策人；通过数据监测识别门店运营异常，推动解决并挖掘二次开发价值，实现客户生命周期价值最大化。\n3. 资源整合与跨部门协同：主动联动前后线及跨部门资源，为客户提供整体全局解决方案；将内外部资源转化为稳定的新客户获取渠道。\n4. 数据分析与谈判落地：结合客户历史数据与信息，制定个性化报价方案；运用顾问式销售挖掘客户真实痛点，平衡双方利益，推动合同签约落地。\n5. 市场洞察与复盘迭代：持续收集区域行业动态和市场布局，定期复盘客户跟进节奏，从成功/失败案例中提炼可复用方法论。","requirements":"【基础要求】\n1. 大专及以上学历，3年及以上B端地面销售经验\n2. 有完整的大客户从0到1开发案例（能说清楚：怎么找到KP、卡在哪、怎么突破、最终结果）\n3. 有CKA/KA等连锁、大客户销售经验者优先\n\n【能力要求】\n1. 连锁攻坚力：有全局思维能找总部关键KP、做标杆案例、批量复制覆盖，而非逐店谈判\n2. 谈判与逼单：能分析客户需求、提供优质解决方案并守住收益底线，不是过于消耗资源\n3. 作业习惯：有固定拜访节奏和客户分层逻辑，知道每天该去哪、为什么去\n4. 资源整合力：能主动搭建内外部资源，借力跨部门、合作商推进项目\n\n【底层特质】\n1. 内部归因：遇到客户拒绝，先反思自己的判断和方案，而非归因市场与挑战\n2. 韧性：能跟进长周期客户不轻易放弃，把每一次拒绝当作调整策略的起点\n3. 自驱力：主动复盘、主动约陪访、主动找方法，不等着被推着走","description":"部门介绍\n美团充电宝是服务零售中的共享租赁业务，承接美团使命，致力让大家充电更简单。美团充电宝业务以应急充电功能为服务核心，覆盖吃喝玩乐生活全场景。目前，已在全国超过2000多个城市的餐饮、娱乐、机场、地铁、火车站、医院、学校、景区等公共区域及场所提供充电服务，铺设机柜超过百万，有KA、直营、渠道合作商多种业务模式，随时随地保障和满足消费者的充电需求。我们的业务资产数量多、场景多元化，追求精益管理。我们的团队大咖云集，崇尚自主驱动，求真务实。我们正处在快速发展期，规模持续增长，目标是市场规模和利润水平双第一。我们的管理者关注团队每个成员的成长，为每个人提供适合自身发展的机会。广阔天地、大有作为，美团充电宝期待你的加入！\n\n岗位职责\n1. 连锁品牌开发：负责城市内10-50家门店连锁品牌的从0到1开发；识别品牌总部KP制定整体方案，一次谈判覆盖全品牌门店，而非逐店攻坚。\n2. 客户关系深耕：维护签约连锁品牌的核心客情，定期触达关键决策人；通过数据监测识别门店运营异常，推动解决并挖掘二次开发价值，实现客户生命周期价值最大化。\n3. 资源整合与跨部门协同：主动联动前后线及跨部门资源，为客户提供整体全局解决方案；将内外部资源转化为稳定的新客户获取渠道。\n4. 数据分析与谈判落地：结合客户历史数据与信息，制定个性化报价方案；运用顾问式销售挖掘客户真实痛点，平衡双方利益，推动合同签约落地。\n5. 市场洞察与复盘迭代：持续收集区域行业动态和市场布局，定期复盘客户跟进节奏，从成功/失败案例中提炼可复用方法论。\n\n岗位基本要求\n【基础要求】\n1. 大专及以上学历，3年及以上B端地面销售经验\n2. 有完整的大客户从0到1开发案例（能说清楚：怎么找到KP、卡在哪、怎么突破、最终结果）\n3. 有CKA/KA等连锁、大客户销售经验者优先\n\n【能力要求】\n1. 连锁攻坚力：有全局思维能找总部关键KP、做标杆案例、批量复制覆盖，而非逐店谈判\n2. 谈判与逼单：能分析客户需求、提供优质解决方案并守住收益底线，不是过于消耗资源\n3. 作业习惯：有固定拜访节奏和客户分层逻辑，知道每天该去哪、为什么去\n4. 资源整合力：能主动搭建内外部资源，借力跨部门、合作商推进项目\n\n【底层特质】\n1. 内部归因：遇到客户拒绝，先反思自己的判断和方案，而非归因市场与挑战\n2. 韧性：能跟进长周期客户不轻易放弃，把每一次拒绝当作调整策略的起点\n3. 自驱力：主动复盘、主动约陪访、主动找方法，不等着被推着走\n\n具备以下条件优先\n互联网本地生活经验、3年及以上大客户销售经验\n\n岗位亮点\n🔋 美团充电宝CKA团队，专注城市及区域连锁品牌与头部客户开发，不是扫街是品牌覆盖\n🚀 平台资源加持：背靠美团本地生活生态，用流量赋能、品牌背书帮你打开客户大门\n📈 成长天花板高：从单城连锁到全国品牌，从商务专员到城市经理，成长路径清晰\n💰 高激励机制：业绩与收入直接挂钩，高业绩高提成\n🏆 有方法论的团队：不靠感觉靠打法，有连锁攻坚SOP、客户分层体系、城市经理陪访支持\n\n如果你热爱销售、享受攻坚大客户的成就感，我们希望和你一起：\n用「乘法思维」做业绩——打通一个品牌，覆盖几十家门店\n在美团生态里借力——平台流量、跨部门资源都是你的谈判筹码\n在有方法论的团队里成长——从优秀同事身上学到可复用的打法\n走一条清晰的晋升路径——业绩说话，成长看得见\n\n我们期待你是这样的人：\n有过硬的大客户开发经历，遇到拒绝会先反思自己的方案而不是抱怨市场，习惯主动复盘和自我驱动——如果这说的是你，欢迎投递。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4617791678","sourceKey":"meituan_social","company":"美团","title":"充电宝CKA销售（金华）","city":"金华市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4617791678&jobShareType=1","duty":"1. 连锁品牌开发：负责城市内10-50家门店连锁品牌的从0到1开发；识别品牌总部KP制定整体方案，一次谈判覆盖全品牌门店，而非逐店攻坚。\n2. 客户关系深耕：维护签约连锁品牌的核心客情，定期触达关键决策人；通过数据监测识别门店运营异常，推动解决并挖掘二次开发价值，实现客户生命周期价值最大化。\n3. 资源整合与跨部门协同：主动联动前后线及跨部门资源，为客户提供整体全局解决方案；将内外部资源转化为稳定的新客户获取渠道。\n4. 数据分析与谈判落地：结合客户历史数据与信息，制定个性化报价方案；运用顾问式销售挖掘客户真实痛点，平衡双方利益，推动合同签约落地。\n5. 市场洞察与复盘迭代：持续收集区域行业动态和市场布局，定期复盘客户跟进节奏，从成功/失败案例中提炼可复用方法论。","requirements":"【基础要求】\n1. 大专及以上学历，3年及以上B端地面销售经验\n2. 有完整的大客户从0到1开发案例（能说清楚：怎么找到KP、卡在哪、怎么突破、最终结果）\n3. 有CKA/KA等连锁、大客户销售经验者优先\n\n【能力要求】\n1. 连锁攻坚力：有全局思维能找总部关键KP、做标杆案例、批量复制覆盖，而非逐店谈判\n2. 谈判与逼单：能分析客户需求、提供优质解决方案并守住收益底线，不是过于消耗资源\n3. 作业习惯：有固定拜访节奏和客户分层逻辑，知道每天该去哪、为什么去\n4. 资源整合力：能主动搭建内外部资源，借力跨部门、合作商推进项目\n\n【底层特质】\n1. 内部归因：遇到客户拒绝，先反思自己的判断和方案，而非归因市场与挑战\n2. 韧性：能跟进长周期客户不轻易放弃，把每一次拒绝当作调整策略的起点\n3. 自驱力：主动复盘、主动约陪访、主动找方法，不等着被推着走","description":"部门介绍\n美团充电宝是服务零售中的共享租赁业务，承接美团使命，致力让大家充电更简单。美团充电宝业务以应急充电功能为服务核心，覆盖吃喝玩乐生活全场景。目前，已在全国超过2000多个城市的餐饮、娱乐、机场、地铁、火车站、医院、学校、景区等公共区域及场所提供充电服务，铺设机柜超过百万，有KA、直营、渠道合作商多种业务模式，随时随地保障和满足消费者的充电需求。我们的业务资产数量多、场景多元化，追求精益管理。我们的团队大咖云集，崇尚自主驱动，求真务实。我们正处在快速发展期，规模持续增长，目标是市场规模和利润水平双第一。我们的管理者关注团队每个成员的成长，为每个人提供适合自身发展的机会。广阔天地、大有作为，美团充电宝期待你的加入！\n\n岗位职责\n1. 连锁品牌开发：负责城市内10-50家门店连锁品牌的从0到1开发；识别品牌总部KP制定整体方案，一次谈判覆盖全品牌门店，而非逐店攻坚。\n2. 客户关系深耕：维护签约连锁品牌的核心客情，定期触达关键决策人；通过数据监测识别门店运营异常，推动解决并挖掘二次开发价值，实现客户生命周期价值最大化。\n3. 资源整合与跨部门协同：主动联动前后线及跨部门资源，为客户提供整体全局解决方案；将内外部资源转化为稳定的新客户获取渠道。\n4. 数据分析与谈判落地：结合客户历史数据与信息，制定个性化报价方案；运用顾问式销售挖掘客户真实痛点，平衡双方利益，推动合同签约落地。\n5. 市场洞察与复盘迭代：持续收集区域行业动态和市场布局，定期复盘客户跟进节奏，从成功/失败案例中提炼可复用方法论。\n\n岗位基本要求\n【基础要求】\n1. 大专及以上学历，3年及以上B端地面销售经验\n2. 有完整的大客户从0到1开发案例（能说清楚：怎么找到KP、卡在哪、怎么突破、最终结果）\n3. 有CKA/KA等连锁、大客户销售经验者优先\n\n【能力要求】\n1. 连锁攻坚力：有全局思维能找总部关键KP、做标杆案例、批量复制覆盖，而非逐店谈判\n2. 谈判与逼单：能分析客户需求、提供优质解决方案并守住收益底线，不是过于消耗资源\n3. 作业习惯：有固定拜访节奏和客户分层逻辑，知道每天该去哪、为什么去\n4. 资源整合力：能主动搭建内外部资源，借力跨部门、合作商推进项目\n\n【底层特质】\n1. 内部归因：遇到客户拒绝，先反思自己的判断和方案，而非归因市场与挑战\n2. 韧性：能跟进长周期客户不轻易放弃，把每一次拒绝当作调整策略的起点\n3. 自驱力：主动复盘、主动约陪访、主动找方法，不等着被推着走\n\n具备以下条件优先\n互联网本地生活经验、3年及以上大客户销售经验\n\n岗位亮点\n🔋 美团充电宝CKA团队，专注城市及区域连锁品牌与头部客户开发，不是扫街是品牌覆盖\n🚀 平台资源加持：背靠美团本地生活生态，用流量赋能、品牌背书帮你打开客户大门\n📈 成长天花板高：从单城连锁到全国品牌，从商务专员到城市经理，成长路径清晰\n💰 高激励机制：业绩与收入直接挂钩，高业绩高提成\n🏆 有方法论的团队：不靠感觉靠打法，有连锁攻坚SOP、客户分层体系、城市经理陪访支持\n\n如果你热爱销售、享受攻坚大客户的成就感，我们希望和你一起：\n用「乘法思维」做业绩——打通一个品牌，覆盖几十家门店\n在美团生态里借力——平台流量、跨部门资源都是你的谈判筹码\n在有方法论的团队里成长——从优秀同事身上学到可复用的打法\n走一条清晰的晋升路径——业绩说话，成长看得见\n\n我们期待你是这样的人：\n有过硬的大客户开发经历，遇到拒绝会先反思自己的方案而不是抱怨市场，习惯主动复盘和自我驱动——如果这说的是你，欢迎投递。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4617789577","sourceKey":"meituan_social","company":"美团","title":"充电宝CKA销售（宁波）","city":"宁波市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4617789577&jobShareType=1","duty":"1. 连锁品牌开发：负责城市内10-50家门店连锁品牌的从0到1开发；识别品牌总部KP制定整体方案，一次谈判覆盖全品牌门店，而非逐店攻坚。\n2. 客户关系深耕：维护签约连锁品牌的核心客情，定期触达关键决策人；通过数据监测识别门店运营异常，推动解决并挖掘二次开发价值，实现客户生命周期价值最大化。\n3. 资源整合与跨部门协同：主动联动前后线及跨部门资源，为客户提供整体全局解决方案；将内外部资源转化为稳定的新客户获取渠道。\n4. 数据分析与谈判落地：结合客户历史数据与信息，制定个性化报价方案；运用顾问式销售挖掘客户真实痛点，平衡双方利益，推动合同签约落地。\n5. 市场洞察与复盘迭代：持续收集区域行业动态和市场布局，定期复盘客户跟进节奏，从成功/失败案例中提炼可复用方法论。","requirements":"【基础要求】\n1. 大专及以上学历，3年及以上B端地面销售经验\n2. 有完整的大客户从0到1开发案例（能说清楚：怎么找到KP、卡在哪、怎么突破、最终结果）\n3. 有CKA/KA等连锁、大客户销售经验者优先\n\n【能力要求】\n1. 连锁攻坚力：有全局思维能找总部关键KP、做标杆案例、批量复制覆盖，而非逐店谈判\n2. 谈判与逼单：能分析客户需求、提供优质解决方案并守住收益底线，不是过于消耗资源\n3. 作业习惯：有固定拜访节奏和客户分层逻辑，知道每天该去哪、为什么去\n4. 资源整合力：能主动搭建内外部资源，借力跨部门、合作商推进项目\n\n【底层特质】\n1. 内部归因：遇到客户拒绝，先反思自己的判断和方案，而非归因市场与挑战\n2. 韧性：能跟进长周期客户不轻易放弃，把每一次拒绝当作调整策略的起点\n3. 自驱力：主动复盘、主动约陪访、主动找方法，不等着被推着走","description":"部门介绍\n美团充电宝是服务零售中的共享租赁业务，承接美团使命，致力让大家充电更简单。美团充电宝业务以应急充电功能为服务核心，覆盖吃喝玩乐生活全场景。目前，已在全国超过2000多个城市的餐饮、娱乐、机场、地铁、火车站、医院、学校、景区等公共区域及场所提供充电服务，铺设机柜超过百万，有KA、直营、渠道合作商多种业务模式，随时随地保障和满足消费者的充电需求。我们的业务资产数量多、场景多元化，追求精益管理。我们的团队大咖云集，崇尚自主驱动，求真务实。我们正处在快速发展期，规模持续增长，目标是市场规模和利润水平双第一。我们的管理者关注团队每个成员的成长，为每个人提供适合自身发展的机会。广阔天地、大有作为，美团充电宝期待你的加入！\n\n岗位职责\n1. 连锁品牌开发：负责城市内10-50家门店连锁品牌的从0到1开发；识别品牌总部KP制定整体方案，一次谈判覆盖全品牌门店，而非逐店攻坚。\n2. 客户关系深耕：维护签约连锁品牌的核心客情，定期触达关键决策人；通过数据监测识别门店运营异常，推动解决并挖掘二次开发价值，实现客户生命周期价值最大化。\n3. 资源整合与跨部门协同：主动联动前后线及跨部门资源，为客户提供整体全局解决方案；将内外部资源转化为稳定的新客户获取渠道。\n4. 数据分析与谈判落地：结合客户历史数据与信息，制定个性化报价方案；运用顾问式销售挖掘客户真实痛点，平衡双方利益，推动合同签约落地。\n5. 市场洞察与复盘迭代：持续收集区域行业动态和市场布局，定期复盘客户跟进节奏，从成功/失败案例中提炼可复用方法论。\n\n岗位基本要求\n【基础要求】\n1. 大专及以上学历，3年及以上B端地面销售经验\n2. 有完整的大客户从0到1开发案例（能说清楚：怎么找到KP、卡在哪、怎么突破、最终结果）\n3. 有CKA/KA等连锁、大客户销售经验者优先\n\n【能力要求】\n1. 连锁攻坚力：有全局思维能找总部关键KP、做标杆案例、批量复制覆盖，而非逐店谈判\n2. 谈判与逼单：能分析客户需求、提供优质解决方案并守住收益底线，不是过于消耗资源\n3. 作业习惯：有固定拜访节奏和客户分层逻辑，知道每天该去哪、为什么去\n4. 资源整合力：能主动搭建内外部资源，借力跨部门、合作商推进项目\n\n【底层特质】\n1. 内部归因：遇到客户拒绝，先反思自己的判断和方案，而非归因市场与挑战\n2. 韧性：能跟进长周期客户不轻易放弃，把每一次拒绝当作调整策略的起点\n3. 自驱力：主动复盘、主动约陪访、主动找方法，不等着被推着走\n\n具备以下条件优先\n互联网本地生活经验、3年及以上大客户销售经验\n\n岗位亮点\n🔋 美团充电宝CKA团队，专注城市及区域连锁品牌与头部客户开发，不是扫街是品牌覆盖\n🚀 平台资源加持：背靠美团本地生活生态，用流量赋能、品牌背书帮你打开客户大门\n📈 成长天花板高：从单城连锁到全国品牌，从商务专员到城市经理，成长路径清晰\n💰 高激励机制：业绩与收入直接挂钩，高业绩高提成\n🏆 有方法论的团队：不靠感觉靠打法，有连锁攻坚SOP、客户分层体系、城市经理陪访支持\n\n如果你热爱销售、享受攻坚大客户的成就感，我们希望和你一起：\n用「乘法思维」做业绩——打通一个品牌，覆盖几十家门店\n在美团生态里借力——平台流量、跨部门资源都是你的谈判筹码\n在有方法论的团队里成长——从优秀同事身上学到可复用的打法\n走一条清晰的晋升路径——业绩说话，成长看得见\n\n我们期待你是这样的人：\n有过硬的大客户开发经历，遇到拒绝会先反思自己的方案而不是抱怨市场，习惯主动复盘和自我驱动——如果这说的是你，欢迎投递。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4091566014","sourceKey":"meituan_social","company":"美团","title":"美团骑行-政企大客户专家（云南）","city":"昆明市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4091566014&jobShareType=1","duty":"1.负责开拓政企大客户市场，推动美团骑行在云南地区的业务发展。\n2.建立和维护与政企大客户的合作关系，达成业务合作目标。\n3.负责制定并执行销售策略，实现销售目标，并持续优化销售流程和方法。\n4.跟进客户需求，提供优质的产品和服务解决方案，提高客户满意度。\n5.跟进市场动态和竞争对手情况，及时调整销售策略，保持市场优势地位。\n6.组织并参与重要客户的谈判和合同签署，确保合作项目的顺利推进。","requirements":"1、大学本科及以上学历;\n2、5年以上政企销售及大客户拓展经验，具备一定资源积累，有头部资源者优先；\n3、适应互联网行业的快速发展，具备出色完成任务的能力；\n4、具备较强的人际沟通能力、逻辑思维能力，很强的联结力；\n5、为人正直，诚实可靠，以公司利益为重；\n6、热爱销售，善于挑战，积极乐观，有强烈的成功欲望。","description":"部门介绍\n美团骑行事业部在全国各个城市开展美团单车、电单车业务，提供绿色、便捷的共享出行服务，是美团出行板块重要的组成部分。我们力求为城市可持续发展提供低碳智能的解决方案，通过技术创新和硬件升级，不断优化全流程骑行体验，为低碳出行提供更好的服务。其中，美团单车旨在为城市居民提供通勤接驳服务，满足用户短途接驳出行需求；美团电单车则满足用户中短途多场景低碳出行需求。\n我们有开放的工作氛围，也有充满韧劲和创造力，心系低碳出行的伙伴。加入我们，一起为用户创造更好的出行体验。\n\n岗位职责\n1.负责开拓政企大客户市场，推动美团骑行在云南地区的业务发展。\n2.建立和维护与政企大客户的合作关系，达成业务合作目标。\n3.负责制定并执行销售策略，实现销售目标，并持续优化销售流程和方法。\n4.跟进客户需求，提供优质的产品和服务解决方案，提高客户满意度。\n5.跟进市场动态和竞争对手情况，及时调整销售策略，保持市场优势地位。\n6.组织并参与重要客户的谈判和合同签署，确保合作项目的顺利推进。\n\n岗位基本要求\n1、大学本科及以上学历;\n2、5年以上政企销售及大客户拓展经验，具备一定资源积累，有头部资源者优先；\n3、适应互联网行业的快速发展，具备出色完成任务的能力；\n4、具备较强的人际沟通能力、逻辑思维能力，很强的联结力；\n5、为人正直，诚实可靠，以公司利益为重；\n6、热爱销售，善于挑战，积极乐观，有强烈的成功欲望。\n\n具备以下条件优先\nTo G工作经验、大客户销售经验、有渠道商合作管理经验，对共享出行行业有一定了解和热爱\n\n岗位亮点\n公司提供具有竞争力的薪酬福利待遇，并为员工提供广阔的职业发展空间和晋升机会。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4653451475","sourceKey":"meituan_social","company":"美团","title":"酒店民宿AI产品经理（销售效能方向）","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4653451475&jobShareType=1","duty":"建设美团酒店销售端AI生产力体系，围绕销售端商业模型，推动客户洞察、机会判断、策略建立分发、触达跟进和复盘从“人力与经验驱动”向“AI驱动”转变。\n\n深入销售一线，洞察需求背后的业务目标和本质问题；从“如何更高效地发现并转化商业机会”出发，重新设计销售流程与人机分工，而非简单优化现有工具。\n\n与销售、销售运营、算法、研发和数据团队协作，建设能够理解客户、判断机会、制定策略、调用工具、跟进执行并持续学习的销售Agent，从销售助手演进为销售执行者和决策参与者，带来实际业务收入。\n\n建设AI目标评测体系，覆盖评测集、离线评测、人工校准、线上实验和业务归因，衡量判断准确性、任务完成度、AI自主率、人工介入成本及收入利润增量，驱动产品持续迭代。","requirements":"本科及以上学历，3年及以上产品经验，有AI产品、SalesTech、CRM、商业化或复杂To B产品经验，具备独立负责重要方向并完成0到1落地的能力。\n\n对前沿AI技术高度敏感，理解大模型与Agent的能力边界，能快速验证新技术并转化为产品机会。同时给予良好的数据分析和评测能力，能够通过实验和业务结果验证AI产品价值。\n\n具备优秀的需求洞察和本质思考能力，能够区分销售提出的方案与真实业务问题，愿意深入一线理解销售过程。具备较强的商业理解和系统抽象能力，能够将复杂销售问题沉淀为可复用、可规模化的产品能力。\n\n自驱、结果导向，具备较强的跨团队推动能力，能够在高不确定性环境中推动项目持续落地。","description":"部门介绍\n美团酒店旅行业务涵盖酒店、民宿、机票、火车票、旅游度假、景点门票等各类住行游品类，通过与产业上下游的深度合作，为用户提供美好的旅游旅行体验。我们积极打造AI友好型组织，使用AI等新技术提升旅游服务的供需匹配效率，更好满足用户个性化、多样化的出游需求。我们持续深耕产业链，用数字化服务助力实体商家高质量经营，探索自有品牌等供给新模式，打造健康的商家生态，保障用户服务体验。为满足用户日益增长的跨境旅行需求，我们将聚焦亚太区域，打造高品质的住宿、交通、游玩等服务矩阵。\n这里有多元的业务布局、持续的成长空间，无论是向往的远方还是眼前的工作，一路都是风景相伴。加入我们，共同为用户创造旅游旅行中的高光时刻！\n\n岗位职责\n建设美团酒店销售端AI生产力体系，围绕销售端商业模型，推动客户洞察、机会判断、策略建立分发、触达跟进和复盘从“人力与经验驱动”向“AI驱动”转变。\n\n深入销售一线，洞察需求背后的业务目标和本质问题；从“如何更高效地发现并转化商业机会”出发，重新设计销售流程与人机分工，而非简单优化现有工具。\n\n与销售、销售运营、算法、研发和数据团队协作，建设能够理解客户、判断机会、制定策略、调用工具、跟进执行并持续学习的销售Agent，从销售助手演进为销售执行者和决策参与者，带来实际业务收入。\n\n建设AI目标评测体系，覆盖评测集、离线评测、人工校准、线上实验和业务归因，衡量判断准确性、任务完成度、AI自主率、人工介入成本及收入利润增量，驱动产品持续迭代。\n\n岗位基本要求\n本科及以上学历，3年及以上产品经验，有AI产品、SalesTech、CRM、商业化或复杂To B产品经验，具备独立负责重要方向并完成0到1落地的能力。\n\n对前沿AI技术高度敏感，理解大模型与Agent的能力边界，能快速验证新技术并转化为产品机会。同时给予良好的数据分析和评测能力，能够通过实验和业务结果验证AI产品价值。\n\n具备优秀的需求洞察和本质思考能力，能够区分销售提出的方案与真实业务问题，愿意深入一线理解销售过程。具备较强的商业理解和系统抽象能力，能够将复杂销售问题沉淀为可复用、可规模化的产品能力。\n\n自驱、结果导向，具备较强的跨团队推动能力，能够在高不确定性环境中推动项目持续落地。\n\n具备以下条件优先\n擅长突破边界，有推动销售流程重构、人机协作或组织提效的实践经验。\n熟悉酒店民宿行业，有酒店平台产品工作经验。\n\n岗位亮点\n空间大，重实践。基于业内销售体系为样本，进行AI生产力变革的突破。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4650957473","sourceKey":"meituan_social","company":"美团","title":"供应链计划产品专家","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4650957473&jobShareType=1","duty":"1、需求管理和产品协同：负责供应计划业务逻辑和产品逻辑迭代，承接相关的项目需求并协同各方进行进行需求梳理、可行性分析、上线验收及落地运营等；\n2、建立监测指标体系，及时发现并联动物流解决问题，提出改进方案和措施；\n3、协同城市计划和品类计划对全盘计划进行统筹，制定和运营库存指标；\n4、产品和流程优化：承接需求预测、库存策略、库存仿真、订货系统等计划相关产品/数据/应用需求，并承接需求梳理->上线->运营的相关工作；通过流程优化、专题项目、系统构建等方式提高链路的协同效率；\n5、上下游拉通，拉通算法、产品、计划运营、业务等各方共识，类项目管理的方式推进需求落地和产品功能上线。","requirements":"1、供应链计划产品实施经验，熟悉需求计划、库存计划、供应计划、S&OP流程并具备实际运营经验，掌握端到端的供应链管理方法；\n2、能够明确对应模块关键业务的诉求，进行需求编写、流程设计、独立完成BRD并能将需求准确的传递后后端产品和研发部门；\n3、较好的项目管理能力和风险管理能力，保障实施交付落地；能基于计划执行推动相关方完成相关动作的落地。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1、需求管理和产品协同：负责供应计划业务逻辑和产品逻辑迭代，承接相关的项目需求并协同各方进行进行需求梳理、可行性分析、上线验收及落地运营等；\n2、建立监测指标体系，及时发现并联动物流解决问题，提出改进方案和措施；\n3、协同城市计划和品类计划对全盘计划进行统筹，制定和运营库存指标；\n4、产品和流程优化：承接需求预测、库存策略、库存仿真、订货系统等计划相关产品/数据/应用需求，并承接需求梳理->上线->运营的相关工作；通过流程优化、专题项目、系统构建等方式提高链路的协同效率；\n5、上下游拉通，拉通算法、产品、计划运营、业务等各方共识，类项目管理的方式推进需求落地和产品功能上线。\n\n岗位基本要求\n1、供应链计划产品实施经验，熟悉需求计划、库存计划、供应计划、S&OP流程并具备实际运营经验，掌握端到端的供应链管理方法；\n2、能够明确对应模块关键业务的诉求，进行需求编写、流程设计、独立完成BRD并能将需求准确的传递后后端产品和研发部门；\n3、较好的项目管理能力和风险管理能力，保障实施交付落地；能基于计划执行推动相关方完成相关动作的落地。\n\n岗位亮点\n具有挑战性的业务场景，利于专业沉淀；有机会完成0-1的新能力建设。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4644459362","sourceKey":"meituan_social","company":"美团","title":"小象超市-供应计划专家（华南PC）","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4644459362&jobShareType=1","duty":"1、负责供应链品类计划：基于用户需求预测，输出品类备货计划，并通过持续提升计划准确度及备货弹性，保障商品稳定供给，提升用户体验；\n2、负责供应链产品优化：根据不同品类的独特发展需求及特点，建立全链路供应链优化及解决方案，沉淀策略并推进产品化，提升供应链计划自动化进程；\n3、负责供应链运营提效：通过管控输入及输出指标，监控库存现货率、周转、库龄，及时提出滞销、断货预警，识别风险点及机会点，提升现有供给链路效率。","requirements":"1、具备创业精神，积极主动，有较强的自驱力和韧性；\n2、熟练掌握各类办公软件，具有较强的逻辑思考能力、数据分析能力、复杂问题的拆解能力；\n3、具备较强责任心、沟通、协同、推动影响力；\n4、2年以上供应计划工作经验。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1、负责供应链品类计划：基于用户需求预测，输出品类备货计划，并通过持续提升计划准确度及备货弹性，保障商品稳定供给，提升用户体验；\n2、负责供应链产品优化：根据不同品类的独特发展需求及特点，建立全链路供应链优化及解决方案，沉淀策略并推进产品化，提升供应链计划自动化进程；\n3、负责供应链运营提效：通过管控输入及输出指标，监控库存现货率、周转、库龄，及时提出滞销、断货预警，识别风险点及机会点，提升现有供给链路效率。\n\n岗位基本要求\n1、具备创业精神，积极主动，有较强的自驱力和韧性；\n2、熟练掌握各类办公软件，具有较强的逻辑思考能力、数据分析能力、复杂问题的拆解能力；\n3、具备较强责任心、沟通、协同、推动影响力；\n4、2年以上供应计划工作经验。\n\n具备以下条件优先\n1、具备较强数据统计以及分析能力，熟练使用SQL；\n2、参与过同类型业务，具备多门店库存管理经验优先；\n3、供应链管理、物流管理专业优先；\n4、乐观向上正能量者优先。\n\n岗位亮点\n1、供应链能力建设价值高：供给侧需要有无限接近和满足消费者的能力，对于需求计划，库存计划，补货管理专业能力建设；以及通过供应链条的整体优化最大化供给的弹性。这种能力区别于现在的远场电商/线下电商已有的供应链能力，也会成为未来即时零售的核心竞争力。\n2、小象供应链场景的复杂度能帮助在供应链专业上的深度拓展：供应链链路上的节点多，品类复杂，异常场景多等，都对供应链规划/计划/执行能力上有更高的要求，是很好的专业深度挑战。\n3、构建更宽广的职业发展图景：有机会全身心地参与新零售业态，在急速发展的业务当中，从0到1地建立对业务和产业的认知，能和电商、O2O、物流、零售、人工智能等多元化背景的团队一起，综合学习，共同进步。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4648283686","sourceKey":"meituan_social","company":"美团","title":"小象超市-杭州运输主管","city":"杭州市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4648283686&jobShareType=1","duty":"1. 负责杭州区域小象超市的运输配送日常运营，确保配送时效与服务质量。  \n2. 协调运输资源，优化配送路线，降低运输成本并提升效率。  \n3. 监控运输数据，分析异常情况并制定改进措施。  \n4. 与仓储、采购及门店团队紧密协作，保障供应链顺畅运作。  \n5. 处理运输过程中的突发问题，及时响应并解决客户投诉。","requirements":"1. 大学专科及以上学历，物流、运输或相关专业优先。  \n2. 3年以上物流运输或配送管理经验，熟悉城市配送流程。  \n3. 熟练使用办公软件及运输管理系统，具备数据分析能力。  \n4. 具备良好的沟通协调能力，能高效处理多方协作问题。  \n5. 责任心强，能适应快节奏工作环境，接受弹性工作安排。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1. 负责杭州区域小象超市的运输配送日常运营，确保配送时效与服务质量。  \n2. 协调运输资源，优化配送路线，降低运输成本并提升效率。  \n3. 监控运输数据，分析异常情况并制定改进措施。  \n4. 与仓储、采购及门店团队紧密协作，保障供应链顺畅运作。  \n5. 处理运输过程中的突发问题，及时响应并解决客户投诉。\n\n岗位基本要求\n1. 大学专科及以上学历，物流、运输或相关专业优先。  \n2. 3年以上物流运输或配送管理经验，熟悉城市配送流程。  \n3. 熟练使用办公软件及运输管理系统，具备数据分析能力。  \n4. 具备良好的沟通协调能力，能高效处理多方协作问题。  \n5. 责任心强，能适应快节奏工作环境，接受弹性工作安排。\n\n具备以下条件优先\n1、有同行业城配经验优先，如(YX,DD,PP)；\n2、具备路由规划能力和团队管理能力，能直面司机管理；\n3、有数据分析经验者优先；\n\n岗位亮点\n1. 加入快速发展的生鲜零售行业，参与核心物流环节。  \n2. 提供完善的培训体系，助力个人职业成长。  \n3. 扁平化管理，工作氛围开放，注重员工反馈。  \n4. 有机会参与区域物流网络优化及创新项目。  \n5. 提供具有竞争力的薪酬及绩效奖励机制。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4629474238","sourceKey":"meituan_social","company":"美团","title":"AI组织转型专家","city":"深圳市/北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4629474238&jobShareType=1","duty":"1.基于公司发展战略和组织能力长期建设需求，深入研究、推演AI对组织生产关系的影响，推动相关人才策略的形成和落地；\n2.支持公司级序列、职级、人才发展等基础管理体系的日常运营及迭代需求，协同业务推进项目落地实施；\n3.通过数据分析、内部访谈、外部对标等手段，持续识别和发现组织能力和人才发展上需要被关注的问题/机会，并能够促进相关问题的讨论，撬动改变发生；\n4.结合公司关注的重点话题，开展前瞻性研究工作。","requirements":"1.对组织人才管理和AI产品充满好奇心、责任感和热情，愿意投身其中作为长期事业；\n2.心态开放、持续学习，能及时关注和掌握理论前沿、市场发展动态、业务需求和痛点；\n3.专业精深，但不局限于已有的资源和方法，深潜把握细节，对交付成果有较高的质量要求；\n4.极度关注客户，深入理解各个管理场景中的实际痛点和问题，具备较好捕捉问题的能力和判断力。","description":"部门介绍\n美团HR的使命是“建设有生命力的组织，为客户和社会创造价值。” 我们认为HR的工作不是以自身“专业”为中心，而是要建设有助于员工发挥创造力的环境，支持他们更好地为外部客户和社会创造价值，也实现组织自身的进化和传承。在这个过程中，我们的每位HR同学都是“业务的战略合作伙伴、组织能力的建设者、美团精神的布道者、员工的成长伙伴”。我们要设计面向长期支撑组织有效运转的机制，我们要求真务实地帮业务解决发展中的问题和阵痛，我们要支持每一位员工历经磨炼收获成长。我们要影响和驱动让世界更美好的变化发生。如果这也是你追求的，欢迎加入美团HR，与我们一路同行！\n\n岗位职责\n1.基于公司发展战略和组织能力长期建设需求，深入研究、推演AI对组织生产关系的影响，推动相关人才策略的形成和落地；\n2.支持公司级序列、职级、人才发展等基础管理体系的日常运营及迭代需求，协同业务推进项目落地实施；\n3.通过数据分析、内部访谈、外部对标等手段，持续识别和发现组织能力和人才发展上需要被关注的问题/机会，并能够促进相关问题的讨论，撬动改变发生；\n4.结合公司关注的重点话题，开展前瞻性研究工作。\n\n岗位基本要求\n1.对组织人才管理和AI产品充满好奇心、责任感和热情，愿意投身其中作为长期事业；\n2.心态开放、持续学习，能及时关注和掌握理论前沿、市场发展动态、业务需求和痛点；\n3.专业精深，但不局限于已有的资源和方法，深潜把握细节，对交付成果有较高的质量要求；\n4.极度关注客户，深入理解各个管理场景中的实际痛点和问题，具备较好捕捉问题的能力和判断力。\n\n岗位亮点\n1.总部专业团队，有全局视野，视角宽广。\n2.团队专业，文化务实，敢于并愿意提供培养人的责任/机会。\n3.工作内容不局限于传统管理领域，面向业务协同、国际化、AI等有跨多领域的挑战性项目机会。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4655690684","sourceKey":"meituan_social","company":"美团","title":"AI产品解决方案","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4655690684&jobShareType=1","duty":"1. 深入理解餐饮业务以及餐饮SaaS系统业务流程，为AI方向对应的业务结果负责；\n2. 深入理解大模型的原理、相关技术栈及工具，挖掘餐饮客户业务场景AI诉求，主导需求识别并推动产品化落地；\n3. 负责AI产品解决方案在餐饮商家的验证和价值评估，打造具有行业影响力解决方案\n4. 持续学习并打造行业标杆，持续沉淀商家AI领域最佳实践。","requirements":"1.本科及以上学历，5年以上工作经验，2年以上SaaS行业工作经验或餐饮甲方经验\n2.2年以上大模型或AI产品实践经验\n3. 对AI有热情，相信AI在业务场景中的价值\n4. 出色的跨部门协作和沟通能力，具备较好的商家沟通能力和较强的项目管理能力。","description":"部门介绍\n美团餐饮系统为餐饮企业提供一站式IT解决方案，帮助餐饮商户实现从供应链管理、生产管理、前厅管理到外卖的数字化经营。美团餐饮系统不仅打通了餐厅和平台，更帮助餐厅连接客人，让商户更了解顾客需求，在帮助商户做商业决策的同时给顾客带来更好的消费体验。\n我们持续建设和提升产研、销售、服务的核心能力，通过全新升级的美团餐饮系统一体化软硬件产品，助力餐饮商户进行线上化经营，帮助商户在推广新店、提升效率、降低成本、会员营销、流量扶持、智慧选址、供应链管理等方面强化经营能力。团队汇集了餐饮和SaaS领域的优秀人才，秉持着“以客户为中心”的初心和“长期有耐心”的耕耘精神，求真、敬畏、敢于自我否定、善于快速学习。期待同样愿意长期致力于餐饮产业数字化、智能化的你加入我们的团队，共同进步共同成长！\n\n岗位职责\n1. 深入理解餐饮业务以及餐饮SaaS系统业务流程，为AI方向对应的业务结果负责；\n2. 深入理解大模型的原理、相关技术栈及工具，挖掘餐饮客户业务场景AI诉求，主导需求识别并推动产品化落地；\n3. 负责AI产品解决方案在餐饮商家的验证和价值评估，打造具有行业影响力解决方案\n4. 持续学习并打造行业标杆，持续沉淀商家AI领域最佳实践。\n\n岗位基本要求\n1.本科及以上学历，5年以上工作经验，2年以上SaaS行业工作经验或餐饮甲方经验\n2.2年以上大模型或AI产品实践经验\n3. 对AI有热情，相信AI在业务场景中的价值\n4. 出色的跨部门协作和沟通能力，具备较好的商家沟通能力和较强的项目管理能力。\n\n具备以下条件优先\n具备技术动手能力，能自己动手利用AI独立搭建前后端完整对外系统\n\n岗位亮点\n1、餐饮SaaS业务作为美团的战略级业务，直接通过AI推动餐饮行业信息化和数字化，创造足够大的行业价值与社会价值；\n2、负责的方向可影响大体量商户和消费者，实践土壤好，市场价值高；\n3、公司和团队优质的氛围、福利和方法论学习土壤，有效助力职场生涯迭代成长；","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4381199673","sourceKey":"meituan_social","company":"美团","title":"LongCat - 基座agent评测分析算法研究员（生产力方向）","city":"北京市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4381199673&jobShareType=1","duty":"负责围绕AI大模型算法的认知分析的研究工作，具体工作内容包括但不限于：\n1. 深入理解大规模语言模型的模型结构、训练过程以及评测方式，根据模型的训练过程以及评测结果，对大语言模型存在的问题进行研究。\n2. 深度参与通用生产力在claude code/OpenClaw等场景下的基座模型能力优化迭代，设计具有长路径、多步骤交互特征的评测任务集，实现从“单次问答”到“闭环任务”的评测转型。\n3. 探索长周期下Agent在复杂任务的能力边界，涵盖工具调用、决策规划和记忆管理等方向，对前沿评测范式如基于沙盒环境的动态评测和多agent协同效率等进行深入研究.","requirements":"1. 硕士及以上学历，计算机、数学或相关专业。熟悉Java/Python/C++等编程语言，良好的编码习惯和一定的工程能力 ；\n2. 具有机器学习或深度学习算法的基础知识，熟练掌握自然语言处理、多模态或大模型相关算法和模型；\n3. 具备工匠精神，对每一行代码负责，对业务方负责。有良好的沟通合作意识和较强的问题解决能力。","description":"部门介绍\n基础研发平台是美团的核心技术平台，立足于“零售+科技”的战略定位，通过打造人工智能、大数据、云计算、安全等核心技术能力，以及研发效能平台、企业应用平台等公共服务，为业务提供稳定安全、扩展易用、技术领先的平台技术和产品服务。\n在这里，我们会参与到最前沿的技术研发和探索；能够接触超规模集群、海量数据，挑战高复杂业务场景，有机会与业界一流的工程师一起并肩前行。\n在这里，我们有超强的技术氛围，持续向社区贡献业界实践，加速行业技术发展；我们有完善的互联网学习生态圈，重视底层逻辑和方法论，助力职业生涯的非线性成长。\n真诚地邀请你，和我们一起驱动技术发展，创造行业价值。\n\n岗位职责\n负责围绕AI大模型算法的认知分析的研究工作，具体工作内容包括但不限于：\n1. 深入理解大规模语言模型的模型结构、训练过程以及评测方式，根据模型的训练过程以及评测结果，对大语言模型存在的问题进行研究。\n2. 深度参与通用生产力在claude code/OpenClaw等场景下的基座模型能力优化迭代，设计具有长路径、多步骤交互特征的评测任务集，实现从“单次问答”到“闭环任务”的评测转型。\n3. 探索长周期下Agent在复杂任务的能力边界，涵盖工具调用、决策规划和记忆管理等方向，对前沿评测范式如基于沙盒环境的动态评测和多agent协同效率等进行深入研究.\n\n岗位基本要求\n1. 硕士及以上学历，计算机、数学或相关专业。熟悉Java/Python/C++等编程语言，良好的编码习惯和一定的工程能力 ；\n2. 具有机器学习或深度学习算法的基础知识，熟练掌握自然语言处理、多模态或大模型相关算法和模型；\n3. 具备工匠精神，对每一行代码负责，对业务方负责。有良好的沟通合作意识和较强的问题解决能力。\n\n具备以下条件优先\n1. 紧跟人工智能行业进展，接触到前沿技术和行业趋势，磨练出对人工智能的独到见解；\n2. 参与AI下半场，从评测分析到模型改进，了解从理论到工程实践的全面技能；\n3. 与一流的人工智能团队合作，快速成长，同时有机会参与公司的创新项目，跨足不同领域，拓宽人工智能技术的应用范围。\n\n岗位亮点\n1. 在计算机领域顶会(如ACL、EMNLP、NeurIPS、AAAI等）上以一作发表过论文者优先；\n2. 具备从事相关行业人工智能开发、算法研究等相关工作经验者优先；\n3. 对ClaudeCode和OpenClaw等agent框架有深入了解或丰富使用经验者优先；","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4521454594","sourceKey":"meituan_social","company":"美团","title":"智能体算法工程师（商业智能方向）","city":"北京市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4521454594&jobShareType=1","duty":"1. 面向美团以及生态相关方真实商业经营场景（经营分析、营销投放、销售拓展、商业变现等），构建可用自主智能体，操盘营销预算、服务广大商户、支持数万员工。\n2. 参与商业经营新范式构建与定义，同时追踪大模型与智能体前沿技术，探索其在上述场景的创新应用，以技术驱动业务增长。\n3. 负责应用场景下Skill体系构建， 探索Skill的表示、组织、调度与自进化机制，提升系统复用与泛化能力\n4. 负责应用场景下智能体框架能力建设，重点研究架构优化、推理成本控制、上下文治理、长期记忆与执行效率提升\n5. 负责模型全链路训练与调优，涵盖数据构建、Prompt工程、监督微调、强化学习及效果评测，提升智能体复杂任务处理能力","requirements":"1. 计算机、人工智能或相关专业本科及以上学历。  \n2. 具备2年以上大模型或智能体相关算法开发经验，熟悉主流大模型架构与应用方法。  \n3. 熟练掌握Python，具备扎实的算法与数据结构基础，有PyTorch或TensorFlow实战经验。  \n4. 具备良好的逻辑思维与沟通能力，能够独立完成技术方案设计并推动落地。","description":"部门介绍\n基础研发平台是美团的核心技术平台，立足于“零售+科技”的战略定位，通过打造人工智能、大数据、云计算、安全等核心技术能力，以及研发效能平台、企业应用平台等公共服务，为业务提供稳定安全、扩展易用、技术领先的平台技术和产品服务。\n在这里，我们会参与到最前沿的技术研发和探索；能够接触超规模集群、海量数据，挑战高复杂业务场景，有机会与业界一流的工程师一起并肩前行。\n在这里，我们有超强的技术氛围，持续向社区贡献业界实践，加速行业技术发展；我们有完善的互联网学习生态圈，重视底层逻辑和方法论，助力职业生涯的非线性成长。\n真诚地邀请你，和我们一起驱动技术发展，创造行业价值。\n\n岗位职责\n1. 面向美团以及生态相关方真实商业经营场景（经营分析、营销投放、销售拓展、商业变现等），构建可用自主智能体，操盘营销预算、服务广大商户、支持数万员工。\n2. 参与商业经营新范式构建与定义，同时追踪大模型与智能体前沿技术，探索其在上述场景的创新应用，以技术驱动业务增长。\n3. 负责应用场景下Skill体系构建， 探索Skill的表示、组织、调度与自进化机制，提升系统复用与泛化能力\n4. 负责应用场景下智能体框架能力建设，重点研究架构优化、推理成本控制、上下文治理、长期记忆与执行效率提升\n5. 负责模型全链路训练与调优，涵盖数据构建、Prompt工程、监督微调、强化学习及效果评测，提升智能体复杂任务处理能力\n\n岗位基本要求\n1. 计算机、人工智能或相关专业本科及以上学历。  \n2. 具备2年以上大模型或智能体相关算法开发经验，熟悉主流大模型架构与应用方法。  \n3. 熟练掌握Python，具备扎实的算法与数据结构基础，有PyTorch或TensorFlow实战经验。  \n4. 具备良好的逻辑思维与沟通能力，能够独立完成技术方案设计并推动落地。\n\n具备以下条件优先\n1. 在AIBD、营销系统、智能客服、企业办公等场景的Agent实践应用经验。\n2. 能够结合业务需求进行技术选型和方案设计，对业务和用户有主动思考。\n3. 具备良好的项目管理能力、沟通协调能力和解决问题的能力。\n\n岗位亮点\n1. AI-Native的工作范式：不仅是需求承接方，更有独立负责真实业务机会，扁平化管理、决策高效直达，打破组织壁垒、高信息密度透传。\n2. 成长空间与影响力：技术深度与业务广度兼具——既能深耕前沿算法，也能看到技术如何一步步变成产品、改变真实物理世界；\n3. 团队创新和技术氛围浓厚，扁平开放，鼓励技术分享与创新探索，给予充足创新场景的试错空间。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:2769840045","sourceKey":"meituan_social","company":"美团","title":"Keeta技术-调度算法工程师","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=2769840045&jobShareType=1","duty":"1. 负责 Keeta 即时配送调度算法的建模与迭代优化，综合运用运筹优化、强化学习等方法，在多供需场景下提升骑手-订单匹配效率，持续优化用户体验与履约成本；\n2. 深入研究调度策略、供需平衡、履约模式等核心方向，通过路径规划与时间预估算法，支撑多国业务的规模化落地；\n3. 与产品、运营团队紧密协作，将业务问题转化为算法方案，推动算法成果在生产环境中稳定上线并持续产生业务价值；\n4. 积极探索 AI 编程工具（如 Copilot）与大模型辅助分析在算法研发中的应用，持续提升个人与团队的研发效率。","requirements":"1. 硕士及以上学历，3年以上算法研发经验；\n2. 在运筹优化、机器学习、深度学习、强化学习中至少一个方向有扎实理论基础与项目落地经验，熟悉 Python/C++ 及相关框架；\n3. 具备较强的问题分析与拆解能力，能独立推进算法方案从设计到上线全流程。\n4. 有海外工作/生活经验，英语可作为工作语言；\n5. 熟悉 Gurobi/OR-Tools 等运筹求解器，或有即时配送/物流调度领域经验；\n6. 有使用 AI 辅助工具（如 Copilot、ChatGPT）提升算法研发效率的实践经验。","description":"部门介绍\n美团核心本地商业下业务研发平台，基于公司“零售+科技”的战略导向，通过从底层架构到应用系统、从软件到硬件、从传统算法到GenAI的全方位技术研究，以及开发、运维、安全等全流程能力建设，致力于推动美团核心本地商业下需求侧与供给侧的数字化和智能化升级，助力业务实现高质量增长，优化用户使用体验，提升商户经营水平，促进行业生态伙伴关系的持续健康发展。团队秉持务实、自驱、开放以及追求卓越的工程师文化，一方面通过系统和技术体系的持续迭代升级，帮助业务高质量增长；另一方面，密切关注前沿技术趋势变化，积极创新技术能力，为业务未来发展创造新的可能性。期待优秀的你加入我们，在夯实专业、深耕平台的基础上与业务携手同行，一起用技术 “帮大家吃得更好，生活更好”。\n\n岗位职责\n1. 负责 Keeta 即时配送调度算法的建模与迭代优化，综合运用运筹优化、强化学习等方法，在多供需场景下提升骑手-订单匹配效率，持续优化用户体验与履约成本；\n2. 深入研究调度策略、供需平衡、履约模式等核心方向，通过路径规划与时间预估算法，支撑多国业务的规模化落地；\n3. 与产品、运营团队紧密协作，将业务问题转化为算法方案，推动算法成果在生产环境中稳定上线并持续产生业务价值；\n4. 积极探索 AI 编程工具（如 Copilot）与大模型辅助分析在算法研发中的应用，持续提升个人与团队的研发效率。\n\n岗位基本要求\n1. 硕士及以上学历，3年以上算法研发经验；\n2. 在运筹优化、机器学习、深度学习、强化学习中至少一个方向有扎实理论基础与项目落地经验，熟悉 Python/C++ 及相关框架；\n3. 具备较强的问题分析与拆解能力，能独立推进算法方案从设计到上线全流程。\n4. 有海外工作/生活经验，英语可作为工作语言；\n5. 熟悉 Gurobi/OR-Tools 等运筹求解器，或有即时配送/物流调度领域经验；\n6. 有使用 AI 辅助工具（如 Copilot、ChatGPT）提升算法研发效率的实践经验。\n\n具备以下条件优先\n1. 有海外工作经验/生活经验，英语流利，可作为工作语言者优先；\n2. 从0到1主R过算法项目。\n\n岗位亮点\n1. 技术规模前沿：参与全球头部即时配送平台的调度系统建设，日均处理百万级订单实时调度决策，技术挑战在业界首屈一指；\n2. 业务影响直接：算法迭代直接影响骑手效率与用户体验核心指标，每一次优化都能在数据上清晰可见；\n3. 国际化成长：深度参与 Keeta 多国市场拓展，接触不同国家的供需特征与文化差异，快速积累国际化视野；\n4. 团队氛围：团队汇聚运筹优化与机器学习背景的技术专家，鼓励技术创新，支持顶会论文发表。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4642118969","sourceKey":"meituan_social","company":"美团","title":"美团食杂零售AI算法工程师-视觉方向","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4642118969&jobShareType=1","duty":"负责美团食杂零售视觉/多模态相关核心算法研发与优化，深入理解业务需求，与产品经理及硬件团队协作，将AI视觉能力高效落地到实际生产环境中，工作场景聚焦于品控、门店运营、门店客流、仓储物流运营、作业规范性检测等场景。\n\n负责仓储客流场景内垂域多模态大模型研发，包括在垂域内进行继续预训练、指令遵循后训练等工作，提升多模态大模型在域内的可用性+泛化性。\n\n负责面向门店场景的防损/客流场景的目标检测、多目标跟踪、语义分割、时空动作检测等相关算法研发，提升门店的业务运营效率、降低业务损耗\n\n持续关注行业前沿技术动态，探索将新兴AI/IoT技术、多模态大模型技术引入到现有系统中以提升整体竞争力。","requirements":"硕士及以上学历，计算机科学、人工智能或相关专业背景，有扎实的数学基础，对机器学习理论有深刻理解；\n\n熟练掌握主流深度学习框架\n\n熟悉主流多模态大模型的训练、推理与相关的代码框架\n\n在计算机视觉领域具有丰富经验，如目标检测、图像分割、关键点识别、姿态估计等；\n\n具备良好的代码开发能力，熟悉Python/C/C++/Java等编程语言；\n\n具备良好的沟通与团队合作能力，乐于学习与分享；\n\n动手能力强，责任心强，具备良好的自我驱动能力和良好的编程习惯。","description":"部门介绍\n美团的使命是“帮大家吃得更好，生活更好”，公司聚焦“零售 + 科技”战略，和广大商户与各类合作伙伴一起，努力为消费者提供品质生活，推动商品零售和服务零售在需求侧和供给侧的数字化转型。\n2018年9月20日，美团正式在港交所挂牌上市。美团将始终坚持以客户为中心，不断加大在科技研发方面的投入，更好承担社会责任，更多创造社会价值，与广大合作伙伴一起发展共赢。\n\n岗位职责\n负责美团食杂零售视觉/多模态相关核心算法研发与优化，深入理解业务需求，与产品经理及硬件团队协作，将AI视觉能力高效落地到实际生产环境中，工作场景聚焦于品控、门店运营、门店客流、仓储物流运营、作业规范性检测等场景。\n\n负责仓储客流场景内垂域多模态大模型研发，包括在垂域内进行继续预训练、指令遵循后训练等工作，提升多模态大模型在域内的可用性+泛化性。\n\n负责面向门店场景的防损/客流场景的目标检测、多目标跟踪、语义分割、时空动作检测等相关算法研发，提升门店的业务运营效率、降低业务损耗\n\n持续关注行业前沿技术动态，探索将新兴AI/IoT技术、多模态大模型技术引入到现有系统中以提升整体竞争力。\n\n岗位基本要求\n硕士及以上学历，计算机科学、人工智能或相关专业背景，有扎实的数学基础，对机器学习理论有深刻理解；\n\n熟练掌握主流深度学习框架\n\n熟悉主流多模态大模型的训练、推理与相关的代码框架\n\n在计算机视觉领域具有丰富经验，如目标检测、图像分割、关键点识别、姿态估计等；\n\n具备良好的代码开发能力，熟悉Python/C/C++/Java等编程语言；\n\n具备良好的沟通与团队合作能力，乐于学习与分享；\n\n动手能力强，责任心强，具备良好的自我驱动能力和良好的编程习惯。\n\n具备以下条件优先\n拥有物流、大仓/门店管理或供应链相关行业经验，在工业级场景下成功部署过AI视觉方案者优先考虑；\n\n对视频分析任务感兴趣，并在行为识别、人群密度估计或异常动作监测方面有所研究；\n\n有相关国际顶级会议论文（CVPR, ICCV, NeurIPS等）者优先\n\n岗位亮点\n提供海量真实数据支持，优质的业务方向，有挑战的技术问题，有较大的成长空间\n\n\n有参加国际优质学术会议等学习交流机会","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4615101576","sourceKey":"meituan_social","company":"美团","title":"AI产品经理","city":"北京市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4615101576&jobShareType=1","duty":"岗位定位\n我们在寻找 AI Builder —— 不是传统产品经理的转型，而是原生于 AI 时代的产品构建者。你将从 0 到 1 定义和落地 AI 驱动的产品能力，用 AI 重新定义内容营销、广告投放、用户增长等核心场景\n\n岗位职责\n1. AI 产品从 0 到 1 构建：独立完成 AI 产品/功能的定义、设计、落地和迭代（AIGC 内容生产、AI 工作流自动化、智能投放等）\n2. 技术深度参与：深度理解大模型能力边界（LLM、多模态、Agent），将技术可能性转化为产品方案\n3. 业务闭环：打通\"需求洞察 → 产品设计 → 技术实现 → 效果验证\"全链路\n4. 跨团队协同：与算法、工程、运营、业务方紧密配合\n5. 前沿探索：持续跟踪 AI 前沿，主动发现新的产品化机会","requirements":"必须具备\n1. 强烈的 Builder 心态：喜欢动手做东西，不只是写 PRD\n2. 优秀的结构化思维和快速学习能力\n3. 本科及以上学历\n\n加分项\n1. AI 应用公司工作经验（AI Native 产品、AI SaaS、AIGC 工具等）\n2. 计算机/AI 相关硕士或博士\n3. 有独立开发或开源项目经历\n4. 熟悉 Prompt Engineering、Agent 框架、RAG 等技术实践\n5. 有内容营销/广告投放/用户增长业务认知\n5. 对 AI/LLM/Agent 有深度理解和实操经验（不限产品角色——研发、研究员、创业者均可）","description":"部门介绍\n美团平台为用户的基础产品体验负责，还承担了美团的用户增长、市场和品牌营销以及多条业务线的产品设计职责，建立了融合文字、图片、视频和直播等不同形式的內容生态系统，同时整合地图服务部、客户服务和体验部、企业业务部、网约车业务部等部门，致力于用科技提升美团数亿消费者、近千万商家、骑手、司机和团长的服务体验。美团平台拥有高并发、多业务的复杂场景，为技术深度优化提供了最佳实践可能。这里有简单、讲逻辑、有爱的团队，更是一块理想的实战场地，舞台广阔，欢迎你来尽情施展。\n\n岗位职责\n岗位定位\n我们在寻找 AI Builder —— 不是传统产品经理的转型，而是原生于 AI 时代的产品构建者。你将从 0 到 1 定义和落地 AI 驱动的产品能力，用 AI 重新定义内容营销、广告投放、用户增长等核心场景\n\n岗位职责\n1. AI 产品从 0 到 1 构建：独立完成 AI 产品/功能的定义、设计、落地和迭代（AIGC 内容生产、AI 工作流自动化、智能投放等）\n2. 技术深度参与：深度理解大模型能力边界（LLM、多模态、Agent），将技术可能性转化为产品方案\n3. 业务闭环：打通\"需求洞察 → 产品设计 → 技术实现 → 效果验证\"全链路\n4. 跨团队协同：与算法、工程、运营、业务方紧密配合\n5. 前沿探索：持续跟踪 AI 前沿，主动发现新的产品化机会\n\n岗位基本要求\n必须具备\n1. 强烈的 Builder 心态：喜欢动手做东西，不只是写 PRD\n2. 优秀的结构化思维和快速学习能力\n3. 本科及以上学历\n\n加分项\n1. AI 应用公司工作经验（AI Native 产品、AI SaaS、AIGC 工具等）\n2. 计算机/AI 相关硕士或博士\n3. 有独立开发或开源项目经历\n4. 熟悉 Prompt Engineering、Agent 框架、RAG 等技术实践\n5. 有内容营销/广告投放/用户增长业务认知\n5. 对 AI/LLM/Agent 有深度理解和实操经验（不限产品角色——研发、研究员、创业者均可）\n\n岗位亮点\n我们不看重\n1. 传统互联网产品经理的年限和 title\n2. 是否做过美团相关业务\n3. 是否有大厂背景\n\n我们提供\n1. 破格空间：高潜候选人职级薪资不设限\n2. 前沿场景：美团海量真实业务 × AI 技术的交叉地带\n3. 成长速度：小团队，快迭代\n4. 技术资源：内部大模型能力、算力支持、工程团队配合","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4314095069","sourceKey":"meituan_social","company":"美团","title":"AI应用与效能提升","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4314095069&jobShareType=1","duty":"1、前线效率提升：系统梳理前线日常运营中的效率瓶颈，设计并推动优化方案落地；围绕销售流程、管理动作、信息传递等环节，建立标准化操作规范和高效协作机制。\n2、AI工具探索与应用：持续跟踪AI在销售、运营、管理场景的前沿应用，结合前线实际需求，推动AI工具在团队内的落地使用，提升人效水平和工作质量。\n3、项目落地与效果验证：对各提效项目进行全周期管理，追踪落地进展与效果，以数据为依据评估项目价值，持续迭代优化。","requirements":"1、大学本科及以上学历，3年以上相关工作经验，有流程优化背景优先；\n2、对销售运营、前线管理有一定理解，能将业务诉求转化为系统性的赋能方案；\n3、具备较强的项目推动力，能协调多方资源，推动复杂项目落地；\n4、对AI工具和新技术有较强的学习意愿和探索兴趣；\n5、表达清晰，擅长内容产出（课件、方案、操作手册等）；接受一定频率的全国范围出差。","description":"部门介绍\n美团核心本地商业-下沉市场发展部于2015年成立，通过招募优质的合作商伙伴并对其业务经营能力、组织能力等赋能，以期为下沉城市提供一站式的本地生活服务。\n下沉市场发展部的业务场景涵盖了外卖餐饮、团购、拼好饭、闪购、医药等多元化的生活服务领域，同时搭建了一套稳定、高效的即时配送网络，为更多本地用户提供品质化、多样化、便捷高效的生活服务体验，为当地商户提供数字化发展机遇、提升数字化水平，为社会创造更多的就地就业机会。\n截至2024年6月，下沉市场发展部已开拓全国4000+县区市，帮助百万商户实现本地生活服务数字化，日订单量突破千万，为数十万名骑手提供就业岗位，让本地生活服务逐渐成长为地方新基建，实现美团“帮助大家吃得更好，生活更好”的使命！\n\n岗位职责\n1、前线效率提升：系统梳理前线日常运营中的效率瓶颈，设计并推动优化方案落地；围绕销售流程、管理动作、信息传递等环节，建立标准化操作规范和高效协作机制。\n2、AI工具探索与应用：持续跟踪AI在销售、运营、管理场景的前沿应用，结合前线实际需求，推动AI工具在团队内的落地使用，提升人效水平和工作质量。\n3、项目落地与效果验证：对各提效项目进行全周期管理，追踪落地进展与效果，以数据为依据评估项目价值，持续迭代优化。\n\n岗位基本要求\n1、大学本科及以上学历，3年以上相关工作经验，有流程优化背景优先；\n2、对销售运营、前线管理有一定理解，能将业务诉求转化为系统性的赋能方案；\n3、具备较强的项目推动力，能协调多方资源，推动复杂项目落地；\n4、对AI工具和新技术有较强的学习意愿和探索兴趣；\n5、表达清晰，擅长内容产出（课件、方案、操作手册等）；接受一定频率的全国范围出差。\n\n岗位亮点\n1、深入参与公司核心业务运营。  \n2、参与前沿AI技术在业务中的创新实践，推动企业智能化升级。  \n3、提供广阔的发展平台与清晰的职业成长路径。\n4、团队氛围开放，鼓励创新与主动担当。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4316277906","sourceKey":"meituan_social","company":"美团","title":"效能优化组负责人","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4316277906&jobShareType=1","duty":"1、整体工作规划与统筹：制定效能优化组的年度/季度工作目标与行动计划，统筹合作商赋能、效率提升&AI、盈亏改善三个方向的工作推进，确保各方向协同作战、整体目标达成。\n2、合作商赋能体系建设：统筹合作商能力提升体系设计，联动前线合作商管理政策优化，推动合作商组织能力系统性建设；建立标准化赋能模型，推动优秀实践的规模化复制。\n3、效率提升与AI落地：主导前线运营效率诊断与改善项目，推动标准化流程落地；系统性探索AI在销售运营管理场景的应用，牵头AI工具引入与推广，大幅提升前线人效水平。\n4、盈亏改善与经营健康管理：统筹各业务线资源与盈亏的匹配平衡工作，建立盈亏预警与改善机制，推动合作商经营风险整体水平下降，守住可持续经营底线。\n5、前后线协同与跨部门推动：作为效能优化组对外的主要接口，协调前线大区团队、策略运营组、分析管理组等多方资源，推动重大改善项目高效落地；对内建立良好的团队运作机制。","requirements":"1、大学本科及以上学历，5年以上相关工作经验，其中3年以上团队管理经验；\n2、具备较强的业务运营或合作商管理背景，熟悉本地生活或O2O平台的商业模式与合作商经营逻辑；\n3、有系统性项目推动和变革管理能力，能在组织复杂、利益多元的环境中有效推动改善落地；\n4、对AI和新兴技术有较强认知，能将技术能力转化为实际业务价值；\n5、具备财务或资源管理视角，能理解盈亏逻辑，在赋能和管控之间找到合理平衡；\n6、优秀的跨部门协调与高管沟通能力，能承接重大项目并驱动结果；接受一定频率的全国范围出差。","description":"部门介绍\n美团核心本地商业-下沉市场发展部于2015年成立，通过招募优质的合作商伙伴并对其业务经营能力、组织能力等赋能，以期为下沉城市提供一站式的本地生活服务。\n下沉市场发展部的业务场景涵盖了外卖餐饮、团购、拼好饭、闪购、医药等多元化的生活服务领域，同时搭建了一套稳定、高效的即时配送网络，为更多本地用户提供品质化、多样化、便捷高效的生活服务体验，为当地商户提供数字化发展机遇、提升数字化水平，为社会创造更多的就地就业机会。\n截至2024年6月，下沉市场发展部已开拓全国4000+县区市，帮助百万商户实现本地生活服务数字化，日订单量突破千万，为数十万名骑手提供就业岗位，让本地生活服务逐渐成长为地方新基建，实现美团“帮助大家吃得更好，生活更好”的使命！\n\n岗位职责\n1、整体工作规划与统筹：制定效能优化组的年度/季度工作目标与行动计划，统筹合作商赋能、效率提升&AI、盈亏改善三个方向的工作推进，确保各方向协同作战、整体目标达成。\n2、合作商赋能体系建设：统筹合作商能力提升体系设计，联动前线合作商管理政策优化，推动合作商组织能力系统性建设；建立标准化赋能模型，推动优秀实践的规模化复制。\n3、效率提升与AI落地：主导前线运营效率诊断与改善项目，推动标准化流程落地；系统性探索AI在销售运营管理场景的应用，牵头AI工具引入与推广，大幅提升前线人效水平。\n4、盈亏改善与经营健康管理：统筹各业务线资源与盈亏的匹配平衡工作，建立盈亏预警与改善机制，推动合作商经营风险整体水平下降，守住可持续经营底线。\n5、前后线协同与跨部门推动：作为效能优化组对外的主要接口，协调前线大区团队、策略运营组、分析管理组等多方资源，推动重大改善项目高效落地；对内建立良好的团队运作机制。\n\n岗位基本要求\n1、大学本科及以上学历，5年以上相关工作经验，其中3年以上团队管理经验；\n2、具备较强的业务运营或合作商管理背景，熟悉本地生活或O2O平台的商业模式与合作商经营逻辑；\n3、有系统性项目推动和变革管理能力，能在组织复杂、利益多元的环境中有效推动改善落地；\n4、对AI和新兴技术有较强认知，能将技术能力转化为实际业务价值；\n5、具备财务或资源管理视角，能理解盈亏逻辑，在赋能和管控之间找到合理平衡；\n6、优秀的跨部门协调与高管沟通能力，能承接重大项目并驱动结果；接受一定频率的全国范围出差。\n\n岗位亮点\n完善的晋升&考核机制，业务视野宽阔，良好的公司文化以及团队氛围，成长空间大。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4310838598","sourceKey":"meituan_social","company":"美团","title":"合作商赋能提效","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4310838598&jobShareType=1","duty":"1、合作商能力赋能：基于前线合作商的现状与短板，设计并推动合作商培训体系、经营辅导方案和能力提升项目，协助合作商建立标准化的经营管理能力，推动合作商组织竞争力持续提升。\n2、合作商新能力建设：探索并推动合作商在数字化管理、精细化运营等方面的新能力建设，梳理最佳实践，萃取可复制的赋能模型，推动全国范围内的能力复制与规模化推广。\n3、项目落地与效果验证：对各赋能项目进行全周期管理，追踪落地进展与效果，以数据为依据评估项目价值，持续迭代优化。","requirements":"1、大学本科及以上学历，3年以上相关工作经验，有培训体系设计、业务赋能背景优先；\n2、对销售运营、前线管理、合作商管理有一定理解，能将业务诉求转化为系统性的赋能方案；\n3、具备较强的项目推动力，能协调多方资源，推动复杂项目落地；\n4、对AI工具和新技术有较强的学习意愿和探索兴趣；\n5、表达清晰，擅长内容产出（课件、方案、操作手册等）；接受一定频率的全国范围出差。","description":"部门介绍\n美团核心本地商业-下沉市场发展部于2015年成立，通过招募优质的合作商伙伴并对其业务经营能力、组织能力等赋能，以期为下沉城市提供一站式的本地生活服务。\n下沉市场发展部的业务场景涵盖了外卖餐饮、团购、拼好饭、闪购、医药等多元化的生活服务领域，同时搭建了一套稳定、高效的即时配送网络，为更多本地用户提供品质化、多样化、便捷高效的生活服务体验，为当地商户提供数字化发展机遇、提升数字化水平，为社会创造更多的就地就业机会。\n截至2024年6月，下沉市场发展部已开拓全国4000+县区市，帮助百万商户实现本地生活服务数字化，日订单量突破千万，为数十万名骑手提供就业岗位，让本地生活服务逐渐成长为地方新基建，实现美团“帮助大家吃得更好，生活更好”的使命！\n\n岗位职责\n1、合作商能力赋能：基于前线合作商的现状与短板，设计并推动合作商培训体系、经营辅导方案和能力提升项目，协助合作商建立标准化的经营管理能力，推动合作商组织竞争力持续提升。\n2、合作商新能力建设：探索并推动合作商在数字化管理、精细化运营等方面的新能力建设，梳理最佳实践，萃取可复制的赋能模型，推动全国范围内的能力复制与规模化推广。\n3、项目落地与效果验证：对各赋能项目进行全周期管理，追踪落地进展与效果，以数据为依据评估项目价值，持续迭代优化。\n\n岗位基本要求\n1、大学本科及以上学历，3年以上相关工作经验，有培训体系设计、业务赋能背景优先；\n2、对销售运营、前线管理、合作商管理有一定理解，能将业务诉求转化为系统性的赋能方案；\n3、具备较强的项目推动力，能协调多方资源，推动复杂项目落地；\n4、对AI工具和新技术有较强的学习意愿和探索兴趣；\n5、表达清晰，擅长内容产出（课件、方案、操作手册等）；接受一定频率的全国范围出差。\n\n岗位亮点\n1、深度参与公司核心业务运营。  \n2、提供完善的培训体系与职业发展通道。  \n3、团队氛围开放，鼓励创新与主动思考。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4151966151","sourceKey":"meituan_social","company":"美团","title":"医药健康-快递电商-健康品供应链专家","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4151966151&jobShareType=1","duty":"1. 从事美团买药自营健康品业务的采购工作，对所负责业务范围内的新品引入、库存周转、断货率、滞销率、现金流等业绩指标负责；\n2. 对上游供应链现状进行梳理和诊断，识别判断最优采购路径，不断优化采购成本，提升低成本结构竞争力；\n3. 引入优质供应商，与负责的供应商不断深入合作，做好供应商资源管理，为公司争取更多的供应链资源；\n4. 借助AI工具进行监测行业政策（如医疗器械注册法规、保健品备案要求）、市场动态，输出策略建议，抢占市场先机。结合市场和行业信息，与行业伙伴共同建立健康有序的合作关系。","requirements":"1. 专业背景\n本科及以上学历，熟悉保健品、医疗器械行业（如产品资质、渠道特征、供应链流程），有3年以上品类采购、招商经验，具备成熟商家资源库；\n2. 核心能力\n沟通谈判能力：擅长从0到1挖掘供应商，具备强谈判技巧及资源整合能力；\n数据分析：能通过数据、供应链特征等制定精准策略；\n行业敏感度：对爆品趋势（如功能性保健品、家用医疗器械）有敏锐洞察，能快速锁定潜力供应商；\n3. 软性素质\n目标导向，适应出差及跨部门协作；\n具备优秀沟通能力，能高效协调平台、供应商及品牌等多方需求；\n积极乐观，充满正能量，认同美团价值观并努力践行。","description":"部门介绍\n美团医药健康事业部是美团核心本地商业板块下专注健康领域的业务部门，涵盖美团买药、美团医美和美团医疗三大业务。自创立以来，美团医药健康致力于为用户提供全健康周期产品及服务，满足人民群众多层次多元化医疗健康需求，现已覆盖购药到家、居家检测、问诊挂号、医保支付、求医寻院、医疗美容等核心场景。此外，美团医药健康还为商户提供数字化转型创新解决方案，打造贯穿上游的联动机制，长期参与共建更透明、更可持续的医药健康产业生态圈，目前业务已覆盖25万家药店，收录27万家医疗机构。未来，美团医药康将协同更多行业伙伴，帮助大家变得更健康、更美丽、更养生。\n\n岗位职责\n1. 从事美团买药自营健康品业务的采购工作，对所负责业务范围内的新品引入、库存周转、断货率、滞销率、现金流等业绩指标负责；\n2. 对上游供应链现状进行梳理和诊断，识别判断最优采购路径，不断优化采购成本，提升低成本结构竞争力；\n3. 引入优质供应商，与负责的供应商不断深入合作，做好供应商资源管理，为公司争取更多的供应链资源；\n4. 借助AI工具进行监测行业政策（如医疗器械注册法规、保健品备案要求）、市场动态，输出策略建议，抢占市场先机。结合市场和行业信息，与行业伙伴共同建立健康有序的合作关系。\n\n岗位基本要求\n1. 专业背景\n本科及以上学历，熟悉保健品、医疗器械行业（如产品资质、渠道特征、供应链流程），有3年以上品类采购、招商经验，具备成熟商家资源库；\n2. 核心能力\n沟通谈判能力：擅长从0到1挖掘供应商，具备强谈判技巧及资源整合能力；\n数据分析：能通过数据、供应链特征等制定精准策略；\n行业敏感度：对爆品趋势（如功能性保健品、家用医疗器械）有敏锐洞察，能快速锁定潜力供应商；\n3. 软性素质\n目标导向，适应出差及跨部门协作；\n具备优秀沟通能力，能高效协调平台、供应商及品牌等多方需求；\n积极乐观，充满正能量，认同美团价值观并努力践行。\n\n具备以下条件优先\n1. 拥有医药行业经验者优先；\n2. 拥有大型互联网工作经验者优先。\n\n岗位亮点\n1. 公司福利优厚：六险一金、年终奖、定期团建、带薪年假、定期体检、节日福利、补充医疗保险；\n2. 业务发展广阔前景，是公司重点突破业务；\n3. 主导平台核心品类布局，直接参与行业生态构建；\n4. 参与建设美团B2C电商快速发展阶段，并从中收获宝贵的经验。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4414488484","sourceKey":"meituan_social","company":"美团","title":"下沉市场-餐饮广告产品及客户运营","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4414488484&jobShareType=1","duty":"1、广告收入达成与大客招商\n深度盘点下沉市场流量资源与供需匹配关系，持续挖掘增收机会点；负责外卖和到餐大客户的属地化广告招商，拓展客户生态，驱动广告收入目标达成。\n2、广告产品体系建设与整合营销\n基于下沉市场用户画像与商户特征，设计并落地适配下沉场景的差异化广告产品体系；为客户提供\"投放前-中-后\"一体化整合营销解决方案，涵盖广告策略制定、创意策划、资源组合及效果保障。\n3、销售策略制定与大客运营\n制定广告产品销售策略与商户分层运营体系，精准匹配不同层级商户需求；负责大客户全生命周期管理，建立深度信任关系，提升客户长期价值与续费率，建立可复制的标准化运营SOP。\n4、AI提效赋能\n探索并落地AI工具在广告运营与销售全环节的应用，包括投放策略优化、数据分析提效、广告方案智能产出等，沉淀可复制的AI+广告赋能打法与案例，推动人效提升与运营模式创新。","requirements":"1、本科及以上，3年以上互联网广告产品运营/大客销售/整合营销经验，本地生活广告背景优先。\n2、优秀的商务谈判与客户管理能力，熟悉零售行业商业模式及广告营销痛点，能制定销售策略并推动落地。\n3、精通广告核心指标（CPM/CPC/ROI）优化，具备较强数据分析能力，能以数据驱动策略优化。\n4、有AI工具实战经验，能将AI应用于方案撰写、数据处理、客户分析等场景，对AI+营销趋势敏感。\n5、具备全流程项目管理与跨团队协同推动力，能在高竞争环境下稳定交付结果。","description":"部门介绍\n美团核心本地商业-下沉市场发展部于2015年成立，通过招募优质的合作商伙伴并对其业务经营能力、组织能力等赋能，以期为下沉城市提供一站式的本地生活服务。\n下沉市场发展部的业务场景涵盖了外卖餐饮、团购、拼好饭、闪购、医药等多元化的生活服务领域，同时搭建了一套稳定、高效的即时配送网络，为更多本地用户提供品质化、多样化、便捷高效的生活服务体验，为当地商户提供数字化发展机遇、提升数字化水平，为社会创造更多的就地就业机会。\n截至2024年6月，下沉市场发展部已开拓全国4000+县区市，帮助百万商户实现本地生活服务数字化，日订单量突破千万，为数十万名骑手提供就业岗位，让本地生活服务逐渐成长为地方新基建，实现美团“帮助大家吃得更好，生活更好”的使命！\n\n岗位职责\n1、广告收入达成与大客招商\n深度盘点下沉市场流量资源与供需匹配关系，持续挖掘增收机会点；负责外卖和到餐大客户的属地化广告招商，拓展客户生态，驱动广告收入目标达成。\n2、广告产品体系建设与整合营销\n基于下沉市场用户画像与商户特征，设计并落地适配下沉场景的差异化广告产品体系；为客户提供\"投放前-中-后\"一体化整合营销解决方案，涵盖广告策略制定、创意策划、资源组合及效果保障。\n3、销售策略制定与大客运营\n制定广告产品销售策略与商户分层运营体系，精准匹配不同层级商户需求；负责大客户全生命周期管理，建立深度信任关系，提升客户长期价值与续费率，建立可复制的标准化运营SOP。\n4、AI提效赋能\n探索并落地AI工具在广告运营与销售全环节的应用，包括投放策略优化、数据分析提效、广告方案智能产出等，沉淀可复制的AI+广告赋能打法与案例，推动人效提升与运营模式创新。\n\n岗位基本要求\n1、本科及以上，3年以上互联网广告产品运营/大客销售/整合营销经验，本地生活广告背景优先。\n2、优秀的商务谈判与客户管理能力，熟悉零售行业商业模式及广告营销痛点，能制定销售策略并推动落地。\n3、精通广告核心指标（CPM/CPC/ROI）优化，具备较强数据分析能力，能以数据驱动策略优化。\n4、有AI工具实战经验，能将AI应用于方案撰写、数据处理、客户分析等场景，对AI+营销趋势敏感。\n5、具备全流程项目管理与跨团队协同推动力，能在高竞争环境下稳定交付结果。\n\n具备以下条件优先\n1、有AI工具深度应用落地案例，能够主导推动团队AI提效实践。\n2、有本地生活（到店/外卖）或餐饮行业广告运营经验，熟悉相关业务逻辑与商业化路径。\n3、有下沉市场或县域市场相关业务经验，深度了解下沉用户与商户特征。\n\n岗位亮点\n1. 广阔市场：下沉市场潜力大，发展机会多，能充分施展才能。\n2. 多元挑战：涵盖多方面工作，全面提升综合运营能力。\n3. 创新影响：有机会尝试新策略，对业务发展影响大。\n4. 团队协作：与多团队合作，共享资源，助力职业发展。\n5. 业绩回报：业务增长带来丰厚奖励和晋升机会。\n6. 前沿经验：了解行业动态，积累前沿经验，提升竞争力。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3667346136","sourceKey":"meituan_social","company":"美团","title":"下沉市场-广告渠道销售运营","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3667346136&jobShareType=1","duty":"1、渠道策略与规划：落实下沉广告渠道运营策略，包括广告合作商与广告商引入、协同、汰换，提升广告渠道运营效率。\n2、渠道管理与运营：负责广告渠道日常运营（合作商/广告商管理、考核、激励），制定一线广告人员管理机制，提升广告渠道稳定性、执行力与团队效能。\n3、广告产品与策略：提供适配下沉商户的广告产品投放及销售策略，提升广告渗透率与广告收入。\n4、数据驱动与 AI 赋能：挖掘广告收入增长机会，通过数据分析与 AI 工具赋能广告策略推演、投放效果评估、合作商广告效能诊断及复盘输出，沉淀可复用打法，持续优化广告投放策略与人效。\n5、内外部协同：与内外部部门对齐目标，建立高效合作关系，实现广告业务协同增效。","requirements":"1、本科及以上学历，3年以上本地生活广告渠道运营、广告销售或相关经验优先。\n2、熟悉广告产品体系，具备广告产品策略、广告销售策略制定能力。\n3、数据分析与 AI 应用能力突出，能通过数据驱动优化广告渠道运营策略与投放效果，具备 AI+广告工具实战经验，对 AI+广告趋势敏感。\n4、沟通能力强，执行力强，团队协作精神佳。\n5、学习能力和创新意识强，能快速适应行业变化。","description":"部门介绍\n美团核心本地商业-下沉市场发展部于2015年成立，通过招募优质的合作商伙伴并对其业务经营能力、组织能力等赋能，以期为下沉城市提供一站式的本地生活服务。\n下沉市场发展部的业务场景涵盖了外卖餐饮、团购、拼好饭、闪购、医药等多元化的生活服务领域，同时搭建了一套稳定、高效的即时配送网络，为更多本地用户提供品质化、多样化、便捷高效的生活服务体验，为当地商户提供数字化发展机遇、提升数字化水平，为社会创造更多的就地就业机会。\n截至2024年6月，下沉市场发展部已开拓全国4000+县区市，帮助百万商户实现本地生活服务数字化，日订单量突破千万，为数十万名骑手提供就业岗位，让本地生活服务逐渐成长为地方新基建，实现美团“帮助大家吃得更好，生活更好”的使命！\n\n岗位职责\n1、渠道策略与规划：落实下沉广告渠道运营策略，包括广告合作商与广告商引入、协同、汰换，提升广告渠道运营效率。\n2、渠道管理与运营：负责广告渠道日常运营（合作商/广告商管理、考核、激励），制定一线广告人员管理机制，提升广告渠道稳定性、执行力与团队效能。\n3、广告产品与策略：提供适配下沉商户的广告产品投放及销售策略，提升广告渗透率与广告收入。\n4、数据驱动与 AI 赋能：挖掘广告收入增长机会，通过数据分析与 AI 工具赋能广告策略推演、投放效果评估、合作商广告效能诊断及复盘输出，沉淀可复用打法，持续优化广告投放策略与人效。\n5、内外部协同：与内外部部门对齐目标，建立高效合作关系，实现广告业务协同增效。\n\n岗位基本要求\n1、本科及以上学历，3年以上本地生活广告渠道运营、广告销售或相关经验优先。\n2、熟悉广告产品体系，具备广告产品策略、广告销售策略制定能力。\n3、数据分析与 AI 应用能力突出，能通过数据驱动优化广告渠道运营策略与投放效果，具备 AI+广告工具实战经验，对 AI+广告趋势敏感。\n4、沟通能力强，执行力强，团队协作精神佳。\n5、学习能力和创新意识强，能快速适应行业变化。\n\n具备以下条件优先\n1、有 AI 工具赋能广告渠道/销售运营实际使用经验优先。\n2、熟悉 AI 数据分析或智能广告投放工具者优先。\n\n岗位亮点\n1、 本科及以上学历，3年以上本地生活广告、渠道运营、广告销售或相关经验优先。\n2、 熟悉广告产品体系，具备广告产品策略、销售策略制定能力。\n3、 数据分析与 AI 应用能力突出，能通过数据驱动优化渠道运营策略，具备 AI 工具实战经验，对 AI+广告趋势敏感。\n4、 沟通能力强，执行力强，团队协作精神佳。\n5、 学习能力和创新意识强，能快速适应行业变化。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4506930963","sourceKey":"meituan_social","company":"美团","title":"下沉市场-渠道经理（粤海区域）","city":"广州市/海口市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4506930963&jobShareType=1","duty":"1.负责区域内目标合作商的挖掘和洽谈合作工作，并带领合作商完成外卖的业务目标；\n2.协助合作商组建和管理团队，辅导和监督合作商做好团队的管理工作；\n3.给合作商团队成员有效的培训和辅导；\n4.总结梳理合作商团队工作中的关键动作，使之流程标准化并落地执行；\n5.从外卖业务数据和配送数据中发现问题，持续优化合作商的业务和管理；\n6.从合作商的角度出发思考问题，保证合作商与美团外卖在资源互补、目标一致的方向健康发展；\n7.对合作商团队进行公平公正且有效的工作考核，对不符合考核标准的合作商进行坚决清退。","requirements":"1.有强大的自驱力，渴望成功；\n2.出色的人际沟通能力、团队协作精神与团队建设能力；\n3.能接受区域内工作日长期出差；\n4.精力充沛，能够在压力下出色完成任务；\n5.学习能力出色，对AI工具有较为娴熟的掌握；\n6.为人力行正道，强烈认同以客户为中心、团队合作、拥抱变化、诚信、勤俭、敬业、学习成长的美团价值观。","description":"部门介绍\n美团核心本地商业-下沉市场发展部于2015年成立，通过招募优质的合作商伙伴并对其业务经营能力、组织能力等赋能，以期为下沉城市提供一站式的本地生活服务。\n下沉市场发展部的业务场景涵盖了外卖餐饮、团购、拼好饭、闪购、医药等多元化的生活服务领域，同时搭建了一套稳定、高效的即时配送网络，为更多本地用户提供品质化、多样化、便捷高效的生活服务体验，为当地商户提供数字化发展机遇、提升数字化水平，为社会创造更多的就地就业机会。\n截至2024年6月，下沉市场发展部已开拓全国4000+县区市，帮助百万商户实现本地生活服务数字化，日订单量突破千万，为数十万名骑手提供就业岗位，让本地生活服务逐渐成长为地方新基建，实现美团“帮助大家吃得更好，生活更好”的使命！\n\n岗位职责\n1.负责区域内目标合作商的挖掘和洽谈合作工作，并带领合作商完成外卖的业务目标；\n2.协助合作商组建和管理团队，辅导和监督合作商做好团队的管理工作；\n3.给合作商团队成员有效的培训和辅导；\n4.总结梳理合作商团队工作中的关键动作，使之流程标准化并落地执行；\n5.从外卖业务数据和配送数据中发现问题，持续优化合作商的业务和管理；\n6.从合作商的角度出发思考问题，保证合作商与美团外卖在资源互补、目标一致的方向健康发展；\n7.对合作商团队进行公平公正且有效的工作考核，对不符合考核标准的合作商进行坚决清退。\n\n岗位基本要求\n1.有强大的自驱力，渴望成功；\n2.出色的人际沟通能力、团队协作精神与团队建设能力；\n3.能接受区域内工作日长期出差；\n4.精力充沛，能够在压力下出色完成任务；\n5.学习能力出色，对AI工具有较为娴熟的掌握；\n6.为人力行正道，强烈认同以客户为中心、团队合作、拥抱变化、诚信、勤俭、敬业、学习成长的美团价值观。\n\n岗位亮点\n1. 覆盖广东海南两省，发展空间广阔，成长路径清晰。  \n2. 公司提供完善的培训体系和资源支持，助力个人能力提升。  \n3. 团队氛围积极开放，鼓励创新与协作。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3946498294","sourceKey":"meituan_social","company":"美团","title":"医药健康-快递电商-药品商品运营","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3946498294&jobShareType=1","duty":"承担快递电商慢病药品的商品运营工作，包括商品规划、价格策略、供给协同、人群运营、商业化等模块，为慢病药品的规模增长、利润贡献及低价心智建设负责。\n1.商品规划：结合行业特征和业务特征，洞察用户需求，对商品进行分层分类，基于不同业务场景，制定有效选品、推品策略，联动供给团队进行持续补充；定期评估商品销售表现，制定并执行商品汰换计划，优化商品结构。\n2.商品增长：基于不同病种下用户购买决策因子差异，制定有竞争力的价格策略，管理商品的补贴、流量等资源。包括分层定价、补贴效率提升、搜索排序优化、营销活动推品等，沉淀商品运营方法论。\n3.组织协同：协同招运/采购、营销、产品等部门，连接B端、P端和C端，借助AI工具推动用户购买链路优化及提效。","requirements":"1. 本科或以上学历，工作履历和经验能力匹配度突出者可适度放宽；\n2. 3年及以上快消行业电商平台运营经验，具有药品电商工作经验者优先；\n3. 对数据敏感度高，具备精细化商品分析经验，且学习能力、独立思考能力强；\n4. 乐于沟通，语言表达和感染说服能力突出，可应对复杂情形的商业谈判、组织协调；\n5. 积极乐观，充满正能量，认同美团价值观并努力践行。","description":"部门介绍\n美团医药健康事业部是美团核心本地商业板块下专注健康领域的业务部门，涵盖美团买药、美团医美和美团医疗三大业务。自创立以来，美团医药健康致力于为用户提供全健康周期产品及服务，满足人民群众多层次多元化医疗健康需求，现已覆盖购药到家、居家检测、问诊挂号、医保支付、求医寻院、医疗美容等核心场景。此外，美团医药健康还为商户提供数字化转型创新解决方案，打造贯穿上游的联动机制，长期参与共建更透明、更可持续的医药健康产业生态圈，目前业务已覆盖25万家药店，收录27万家医疗机构。未来，美团医药康将协同更多行业伙伴，帮助大家变得更健康、更美丽、更养生。\n\n岗位职责\n承担快递电商慢病药品的商品运营工作，包括商品规划、价格策略、供给协同、人群运营、商业化等模块，为慢病药品的规模增长、利润贡献及低价心智建设负责。\n1.商品规划：结合行业特征和业务特征，洞察用户需求，对商品进行分层分类，基于不同业务场景，制定有效选品、推品策略，联动供给团队进行持续补充；定期评估商品销售表现，制定并执行商品汰换计划，优化商品结构。\n2.商品增长：基于不同病种下用户购买决策因子差异，制定有竞争力的价格策略，管理商品的补贴、流量等资源。包括分层定价、补贴效率提升、搜索排序优化、营销活动推品等，沉淀商品运营方法论。\n3.组织协同：协同招运/采购、营销、产品等部门，连接B端、P端和C端，借助AI工具推动用户购买链路优化及提效。\n\n岗位基本要求\n1. 本科或以上学历，工作履历和经验能力匹配度突出者可适度放宽；\n2. 3年及以上快消行业电商平台运营经验，具有药品电商工作经验者优先；\n3. 对数据敏感度高，具备精细化商品分析经验，且学习能力、独立思考能力强；\n4. 乐于沟通，语言表达和感染说服能力突出，可应对复杂情形的商业谈判、组织协调；\n5. 积极乐观，充满正能量，认同美团价值观并努力践行。\n\n岗位亮点\n1.公司福利优厚，六险一金、年终奖、定期团建、带薪年假、定期体检、节日福利、补充医疗保险；\n2.快递电商核心岗位，参与建设美团医药健康业务的快速发展阶段，并从中收获宝贵的经验。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4580434257","sourceKey":"meituan_social","company":"美团","title":"闪购-IT赋能业务-产品运营","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4580434257&jobShareType=1","duty":"1. 业务增长与商业化：负责SaaS 新产品的门店覆盖率及业务收入目标达成，设计商家与平台双视角的盈利模型，制定商业化收费策略并推动落地。\n2. 市场洞察与策略制定：持续扫描 AI/SaaS 市场动态及竞争信息，深入一线挖掘商家经营痛点与未满足需求，识别新增长点，输出产品方案与业务策略。\n3. 项目迭代推进：制定项目迭代计划，联动产品、研发团队推动项目如期交付，统筹 AI 能力引入与系统建设两条路径，确保产品持续演进。\n4. 推广与运营：联动销售及地推团队产出推广计划，下沉一线商户收集使用反馈，驱动\"推广—反馈—迭代\"闭环运转，持续打磨产品以达成业务目标。","requirements":"1. 3年以上运营或产品经验，具备本地生活、零售、电商、SaaS 等行业背景优先。\n2. 参与过\"0→1\"项目经历，具备从立项、MVP验证到规模化推广的完整实操经验；有商业化或盈利模型设计经验者加分。\n3. 优秀的沟通与需求转化能力，能与不同体量的商户（从夫妻店到大连锁）深入沟通，将模糊需求提炼为可落地的产品方案。\n4. 具备在高不确定性环境中保持定力的能力，善于在资源有限、方向模糊时围绕目标拆解问题并持续输出解决方案。\n5. 具备 AI 工具的实际动手能力，有使用 AI 生成前端页面、接口打通、开发 Skill/Agent 等经验，能将 AI 能力快速应用于业务提效场景。","description":"部门介绍\n美团闪购是美团旗下的即时零售平台，依托即时配送能力，连接本地零售供给，满足消费者30分钟万物到家的即时需求。美团闪购涵盖超市便利、食材、水果、鲜花绿植、休闲零食、酒水饮料、数码家电、美妆个护、母婴玩具、日用百货、服饰鞋帽、宠物等诸多品类，业务覆盖全国近3,000个县市区旗，每日百万级在岗骑手，以高效的配送、丰富的品类和广泛的覆盖，为美团数亿用户带来便捷的生活体验，积极助力实体零售线上化转型，提升本地商业活力。\n\n岗位职责\n1. 业务增长与商业化：负责SaaS 新产品的门店覆盖率及业务收入目标达成，设计商家与平台双视角的盈利模型，制定商业化收费策略并推动落地。\n2. 市场洞察与策略制定：持续扫描 AI/SaaS 市场动态及竞争信息，深入一线挖掘商家经营痛点与未满足需求，识别新增长点，输出产品方案与业务策略。\n3. 项目迭代推进：制定项目迭代计划，联动产品、研发团队推动项目如期交付，统筹 AI 能力引入与系统建设两条路径，确保产品持续演进。\n4. 推广与运营：联动销售及地推团队产出推广计划，下沉一线商户收集使用反馈，驱动\"推广—反馈—迭代\"闭环运转，持续打磨产品以达成业务目标。\n\n岗位基本要求\n1. 3年以上运营或产品经验，具备本地生活、零售、电商、SaaS 等行业背景优先。\n2. 参与过\"0→1\"项目经历，具备从立项、MVP验证到规模化推广的完整实操经验；有商业化或盈利模型设计经验者加分。\n3. 优秀的沟通与需求转化能力，能与不同体量的商户（从夫妻店到大连锁）深入沟通，将模糊需求提炼为可落地的产品方案。\n4. 具备在高不确定性环境中保持定力的能力，善于在资源有限、方向模糊时围绕目标拆解问题并持续输出解决方案。\n5. 具备 AI 工具的实际动手能力，有使用 AI 生成前端页面、接口打通、开发 Skill/Agent 等经验，能将 AI 能力快速应用于业务提效场景。\n\n岗位亮点\n1. SaaS 行业正拥抱 AI 驱动的深度变革，能够快速积累 AI 商业化实战经验，深入理解效能与成本的平衡，建立AI 落地的判断力。\n2. 新业务，可完整参与产品定义、商业策略制定、市场推广全链路的完整锻炼。\n3. 与闪购多条业务线和三方软件公司等多方直接协作，深入了解即时零售行业逻辑与商家生态，积累跨品类的认知与资源。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4655004680","sourceKey":"meituan_social","company":"美团","title":"Keeta - Product Operations Strategy BP 产运战略BP（阿联酋）","city":"迪拜","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4655004680&jobShareType=1","duty":"1. Act as the country product business partner role in the product team, deeply involved in the entire process of product requirement management, launch introduction, benefits review, and feedback improvement. Provide product solution services to business teams in different countries to support business success.\n2. Proactively identify potential opportunities and issues for the business teams through market research, user research, metric construction, and user feedback mechanism development. Drive closed-loop improvements between the product and business teams to enhance user experience.\n3. Facilitate effective cross-national (and cross-time zone) communication and collaboration, establish and maintain long-term trusted relationships, and develop appropriate collaboration mechanisms.\n4. Actively explore the use of AI tools (such as data analysis, interview summary analysis, market information aggregation, etc.) to enhance insight efficiency and form structured product requirement inputs. \n\n1. 作为境外业务产品团队国家BP角色，深度参与产品需求管理、上线导入、收益复盘、反馈改善等全过程，面向不同国家业务团队提供产品解决方案服务，助力业务成功；\n2. 通过市场调研、用户调研、指标体系搭建、用户反馈机制建设等方式、主动积极发现所面向的业务团队潜在的机会和问题、推动产品和业务团队闭环改善，提升用户体验；\n3. 有效的跨国（跨时区）的沟通合作，建立和保持长期的可信任关系，建立匹配的协作机制和流程；\n4.积极探索利用AI工具（如数据分析、访谈纪要分析、市场信息聚合等）提升洞察效率，形成结构化的产品需求输入。","requirements":"1. Experience in project management, product management, product operations, or business operations in an internet company or large multinational corporation, with deep knowledge and insight in the professional field.\n2. Strong communication skills in cross-functional teams and cross-cultural environments, with excellent English proficiency.\n3. Willingness to base Middle East region and accept international travel at certain frequencies.\n4. Accept base long-term work arrangement in the Middle East and frequent cross-border business trips to the Middle East.\n\n1. 具备互联网公司或大型跨国企业项目管理、产品经理、产品运营或者业务运营经验，在专业领域具有深度认知和洞察；\n2. 具备较强的跨职能团队/跨文化背景的沟通能力，具备出色的英语听说读写能力，英语可作为工作语言；\n3.了解大模型工作原理，深度应用过AI Agent能力，借助AI工具进行过数据分析、文档撰写、运营配置等工作；\n4. 接受base中东地区长期工作安排及一定频次的中东地区跨国出差。","description":"部门介绍\nKeeta是全球领先外卖平台美团旗下的独立品牌，肩负着“帮大家吃得更好，生活更好”的使命。依托美团深耕中国市场15年的技术与运营积淀，我们正引领全球餐饮与商品即时配送服务的创新与发展。\n\n自2023年成立以来，Keeta始终扎根社区并创造价值。我们为用户提供可靠的外卖体验，以智慧技术助餐厅提升经营效率，在为骑手拓宽收入来源的同时，也充分提供安全保障措施。基于这份多方共赢、共同成长的理念，我们的业务已从中国香港稳步拓展至中东及巴西，并持续向世界迈进。\n\n岗位职责\n1. Act as the country product business partner role in the product team, deeply involved in the entire process of product requirement management, launch introduction, benefits review, and feedback improvement. Provide product solution services to business teams in different countries to support business success.\n2. Proactively identify potential opportunities and issues for the business teams through market research, user research, metric construction, and user feedback mechanism development. Drive closed-loop improvements between the product and business teams to enhance user experience.\n3. Facilitate effective cross-national (and cross-time zone) communication and collaboration, establish and maintain long-term trusted relationships, and develop appropriate collaboration mechanisms.\n4. Actively explore the use of AI tools (such as data analysis, interview summary analysis, market information aggregation, etc.) to enhance insight efficiency and form structured product requirement inputs. \n\n1. 作为境外业务产品团队国家BP角色，深度参与产品需求管理、上线导入、收益复盘、反馈改善等全过程，面向不同国家业务团队提供产品解决方案服务，助力业务成功；\n2. 通过市场调研、用户调研、指标体系搭建、用户反馈机制建设等方式、主动积极发现所面向的业务团队潜在的机会和问题、推动产品和业务团队闭环改善，提升用户体验；\n3. 有效的跨国（跨时区）的沟通合作，建立和保持长期的可信任关系，建立匹配的协作机制和流程；\n4.积极探索利用AI工具（如数据分析、访谈纪要分析、市场信息聚合等）提升洞察效率，形成结构化的产品需求输入。\n\n岗位基本要求\n1. Experience in project management, product management, product operations, or business operations in an internet company or large multinational corporation, with deep knowledge and insight in the professional field.\n2. Strong communication skills in cross-functional teams and cross-cultural environments, with excellent English proficiency.\n3. Willingness to base Middle East region and accept international travel at certain frequencies.\n4. Accept base long-term work arrangement in the Middle East and frequent cross-border business trips to the Middle East.\n\n1. 具备互联网公司或大型跨国企业项目管理、产品经理、产品运营或者业务运营经验，在专业领域具有深度认知和洞察；\n2. 具备较强的跨职能团队/跨文化背景的沟通能力，具备出色的英语听说读写能力，英语可作为工作语言；\n3.了解大模型工作原理，深度应用过AI Agent能力，借助AI工具进行过数据分析、文档撰写、运营配置等工作；\n4. 接受base中东地区长期工作安排及一定频次的中东地区跨国出差。\n\n具备以下条件优先\n1. Experience in product or operations role in food delivery, e-commerce, mobility services, or international internet companies.\n2. Experience living and working in the Middle East.\n3. Proficiency in Arabic or other minority languages.\n\n1. 有外卖/电商/出行业务或国际化互联网公司的产品岗或产运岗经验者优先。\n2. 有中东地区生活工作经验者优先。\n3. 有阿语小语种背景者优先。\n\n岗位亮点\n1. Responsible for product operations and project management of overseas business, collaborating with all local business teams and engaging with regional business leaders. Broad business perspective and high market development potential, offering opportunities for rapid growth in emerging markets.\n2. Provides excellent training and learning opportunities, enabling continuous improvement in project and product management skills and professional development in the fast-growing international expansion business.\n3. The team is equipped with a robust AI tooling ecosystem that empowers members to integrate AI capabilities into daily product discovery and the continuous optimization of R&D collaboration workflows, relentlessly advancing best practices in human-AI collaboration.\n\n1. 承担境外业务的产品运营和项目管理工作，跨职能合作本地所有横向业务团队、对话区域业务负责人，业务视野广、市场发展潜力高，有机会在增量市场实现快速成长；\n2. 提供良好的培训和学习机会，能够在快速发展的国际化出海业务中不断提升自己的项目管理能力和职业素养。\n3. 团队配备完善的AI工具体系，鼓励成员将AI能力融入日常产品洞察和产研协作流程优化，持续探索人机协作最佳实践。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4642597681","sourceKey":"meituan_social","company":"美团","title":"大米地采专家","city":"上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4642597681&jobShareType=1","duty":"1、研究行业、商户需求及商品特性，制定品类策略和发展方向，完成公司的采购计划和目标；\n2、负责大米类区域供应商的开发与评审，整合供应商资源及供货渠道，满足区域城市的业务发展需求；\n3、不断优化和完善商品结构，满足不同餐饮业态客户的需求，提升品类的综合经营能力；\n4、建立供应体系包括但不限于：合同谈判、供应商管理及考核、成本管控、采购计划编制等各类流程；\n5、区域品类采购业务管理，保持与城市的良好沟通协作，改善城市端供应链，持续提升城市销售和毛利水平。","requirements":"1、本科及以上学历，有品类采购管理经验；\n2、熟悉采购工作流程，对价格谈判、订单管理、账务处理、供应商开发等具有丰富的经验；\n3、思路清晰，开展工作有计划性，有良好的执行力；\n4、诚信可靠，积极主动，具备良好的表达能力和沟通能力；\n5、有较强的数据分析能力，熟练掌握计算机操作","description":"部门介绍\n快驴进货是美团旗下的餐饮供应链平台，帮助餐饮商户以更低成本、更高效率来获取安全可靠的食材供应，让餐饮采购更简单。快驴进货同步发展“自营+平台”的业务模式，在采购环节一方面向上游供应商直采大宗商品，另一方面引入各地批发商，助力平台伙伴共同发展；在销售环节既有自建团队进行市场、客户拓展，又帮助各地批发商拓展业务；同时自建仓储管理系统、配送网络与团队，为客户提供优质履约服务。\n截至2022年，快驴进货布局了全国41个城市，为百万家商户提供“全、省、稳、好”的餐饮供应链服务。我们拥有3000+品牌食材、超5万SKU商品、超28万商品资质，并提供源头严审核、食品安全严把关、24小时无忧售后的全面保障，实现手机下单、送货上门的高效采购模式，帮百万商家节省了采购时间与成本，助力平台伙伴共同发展，在万亿市场共享机遇。\n在这里，你将收获完善的员工发展机制及学习体系，与各界专家一起深度参与餐饮供应链业务的发展。欢迎优秀的你加入美团快驴进货，与我们一起成长，一起更好！\n\n岗位职责\n1、研究行业、商户需求及商品特性，制定品类策略和发展方向，完成公司的采购计划和目标；\n2、负责大米类区域供应商的开发与评审，整合供应商资源及供货渠道，满足区域城市的业务发展需求；\n3、不断优化和完善商品结构，满足不同餐饮业态客户的需求，提升品类的综合经营能力；\n4、建立供应体系包括但不限于：合同谈判、供应商管理及考核、成本管控、采购计划编制等各类流程；\n5、区域品类采购业务管理，保持与城市的良好沟通协作，改善城市端供应链，持续提升城市销售和毛利水平。\n\n岗位基本要求\n1、本科及以上学历，有品类采购管理经验；\n2、熟悉采购工作流程，对价格谈判、订单管理、账务处理、供应商开发等具有丰富的经验；\n3、思路清晰，开展工作有计划性，有良好的执行力；\n4、诚信可靠，积极主动，具备良好的表达能力和沟通能力；\n5、有较强的数据分析能力，熟练掌握计算机操作\n\n岗位亮点\n成长空间大 学习机会多，可以学习大米品类管理的各种技能\n具备以下优先:\n对大米行业有一定的工作经验，对全国大米产业布局、物流链路等有一定的了解\n有一定大米产地工厂资源\n具备以上条件者优先考虑","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4604078086","sourceKey":"meituan_social","company":"美团","title":"松鼠便利华南区广州中心仓拣配主管","city":"广州市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4604078086&jobShareType=1","duty":"1.负责每日生产排产、车辆排线、仓配生产过程管理，确保及时、准确完成订单履约。\n\n2.现场管理协调，针对现场生产问题、差异问题进行快速处理解决；监控每日司机到仓情况，跟进配送时效和满载情况，配送异常的及时处置。\n\n3.负责所属人员的排班和休假管理。\n\n4.负责全仓安全生产工作，对安全管理目标负责。\n\n5.所属区域的盘点、5s、安全生产、设备物资管理。\n\n6.日常生产差异日清管理。\n\n下设分拣组、集货组、调度组。","requirements":"1.大学专科以上学历，物流管理或相关专业优先。2.具有至少3年以上仓储、配送管理经验。3.具备良好的团队管理能力和沟通能力，能有效协调团队工作。4.熟悉仓储和配送管理流程，熟练操作仓库管理软件。5.具备较强的责任心和执行力，能够承受一定的工作压力","description":"部门介绍\n美团闪购是美团旗下的即时零售平台，依托即时配送能力，连接本地零售供给，满足消费者30分钟万物到家的即时需求。美团闪购涵盖超市便利、食材、水果、鲜花绿植、休闲零食、酒水饮料、数码家电、美妆个护、母婴玩具、日用百货、服饰鞋帽、宠物等诸多品类，业务覆盖全国近3,000个县市区旗，每日百万级在岗骑手，以高效的配送、丰富的品类和广泛的覆盖，为美团数亿用户带来便捷的生活体验，积极助力实体零售线上化转型，提升本地商业活力。\n\n岗位职责\n1.负责每日生产排产、车辆排线、仓配生产过程管理，确保及时、准确完成订单履约。\n\n2.现场管理协调，针对现场生产问题、差异问题进行快速处理解决；监控每日司机到仓情况，跟进配送时效和满载情况，配送异常的及时处置。\n\n3.负责所属人员的排班和休假管理。\n\n4.负责全仓安全生产工作，对安全管理目标负责。\n\n5.所属区域的盘点、5s、安全生产、设备物资管理。\n\n6.日常生产差异日清管理。\n\n下设分拣组、集货组、调度组。\n\n岗位基本要求\n1.大学专科以上学历，物流管理或相关专业优先。2.具有至少3年以上仓储、配送管理经验。3.具备良好的团队管理能力和沟通能力，能有效协调团队工作。4.熟悉仓储和配送管理流程，熟练操作仓库管理软件。5.具备较强的责任心和执行力，能够承受一定的工作压力\n\n具备以下条件优先\n中心仓工作经验优先（仅负责过前置仓的不合适）；\n京东、零售品牌方、便利店连锁、商超背景优先。\n过往做过仓储主管、仓储经理优先\n\n岗位亮点\n1.提供良好的晋升空间和发展机会；\n2.有机会接触到先进物流仓配管理理念；","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4319023858","sourceKey":"meituan_social","company":"美团","title":"快驴CKA-城市经理","city":"成都市/深圳市/广州市/北京市/厦门市/宁波市/杭州市/重庆市/天津市/长沙市/南京市/苏州市/合肥市/东莞市/佛山市/上海市/福州市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4319023858&jobShareType=1","duty":"1.负责制定和执行地面产品销售业务发展计划，实现销售目标和业绩指标。\n2.负责招募、培训、激励和管理城市销售团队，确保团队整体业绩达标。\n3.负责市场调研和竞争情报的收集，及时调整销售策略和推广方案。\n4.负责与客户建立良好的关系，开拓新客户并维护现有客户，提升客户满意度。\n5.负责协调内部各部门资源，解决销售过程中的问题和难题，确保项目顺利进行。","requirements":"1.大学专科及以上学历，市场营销、管理等相关专业优先。\n2.五年以上业务开发或地面产品销售经验，有团队管理经验者优先。\n3.具备较强的市场洞察力、沟通能力和团队协作能力。\n4.熟悉销售流程和市场营销策略，有成功案例更佳。\n5.具备较强的解决问题能力，能够应对复杂的销售环境。","description":"部门介绍\n快驴进货是美团旗下的餐饮供应链平台，帮助餐饮商户以更低成本、更高效率来获取安全可靠的食材供应，让餐饮采购更简单。快驴进货同步发展“自营+平台”的业务模式，在采购环节一方面向上游供应商直采大宗商品，另一方面引入各地批发商，助力平台伙伴共同发展；在销售环节既有自建团队进行市场、客户拓展，又帮助各地批发商拓展业务；同时自建仓储管理系统、配送网络与团队，为客户提供优质履约服务。\n截至2022年，快驴进货布局了全国41个城市，为百万家商户提供“全、省、稳、好”的餐饮供应链服务。我们拥有3000+品牌食材、超5万SKU商品、超28万商品资质，并提供源头严审核、食品安全严把关、24小时无忧售后的全面保障，实现手机下单、送货上门的高效采购模式，帮百万商家节省了采购时间与成本，助力平台伙伴共同发展，在万亿市场共享机遇。\n在这里，你将收获完善的员工发展机制及学习体系，与各界专家一起深度参与餐饮供应链业务的发展。欢迎优秀的你加入美团快驴进货，与我们一起成长，一起更好！\n\n岗位职责\n1.负责制定和执行地面产品销售业务发展计划，实现销售目标和业绩指标。\n2.负责招募、培训、激励和管理城市销售团队，确保团队整体业绩达标。\n3.负责市场调研和竞争情报的收集，及时调整销售策略和推广方案。\n4.负责与客户建立良好的关系，开拓新客户并维护现有客户，提升客户满意度。\n5.负责协调内部各部门资源，解决销售过程中的问题和难题，确保项目顺利进行。\n\n岗位基本要求\n1.大学专科及以上学历，市场营销、管理等相关专业优先。\n2.五年以上业务开发或地面产品销售经验，有团队管理经验者优先。\n3.具备较强的市场洞察力、沟通能力和团队协作能力。\n4.熟悉销售流程和市场营销策略，有成功案例更佳。\n5.具备较强的解决问题能力，能够应对复杂的销售环境。\n\n岗位亮点\n1.高级职级，有机会在多个一线城市进行业务拓展和管理。\n2.带领庞大团队，挑战性大，发展空间广阔。\n3.薪酬福利优厚，公司提供完善的培训和晋升机制，有机会快速成长和晋升。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4570948506","sourceKey":"meituan_social","company":"美团","title":"Keeta技术-营销前端/全栈开发工程师","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4570948506&jobShareType=1","duty":"1.负责Keeta优惠券配置端和用户端功能的设计、开发和维护，保障系统稳定性和高性能。  \n2.与产品、设计、后端团队协作，将业务需求转化为高质量的技术实现。  \n3.优化前后端工程架构和用户体验，提升开发效率和页面性能。  \n4.参与技术方案评审，推动代码质量和系统可维护性提升。","requirements":"1.3年以上前端或全栈开发经验。\n2.熟练掌握前端基础技能，深入理解CSS、JavaScript等理论知识。\n3.熟练掌握React、Vue、AngularJS等主流前端框架。  \n4.熟悉Node.js或至少一门后端语言（如Java、Python），具备全栈开发基础知识。  \n5.有AI辅助开发经验。\n6.具备良好的业务理解能力、沟通能力和团队协作精神。","description":"部门介绍\n美团核心本地商业下业务研发平台，基于公司“零售+科技”的战略导向，通过从底层架构到应用系统、从软件到硬件、从传统算法到GenAI的全方位技术研究，以及开发、运维、安全等全流程能力建设，致力于推动美团核心本地商业下需求侧与供给侧的数字化和智能化升级，助力业务实现高质量增长，优化用户使用体验，提升商户经营水平，促进行业生态伙伴关系的持续健康发展。团队秉持务实、自驱、开放以及追求卓越的工程师文化，一方面通过系统和技术体系的持续迭代升级，帮助业务高质量增长；另一方面，密切关注前沿技术趋势变化，积极创新技术能力，为业务未来发展创造新的可能性。期待优秀的你加入我们，在夯实专业、深耕平台的基础上与业务携手同行，一起用技术 “帮大家吃得更好，生活更好”。\n\n岗位职责\n1.负责Keeta优惠券配置端和用户端功能的设计、开发和维护，保障系统稳定性和高性能。  \n2.与产品、设计、后端团队协作，将业务需求转化为高质量的技术实现。  \n3.优化前后端工程架构和用户体验，提升开发效率和页面性能。  \n4.参与技术方案评审，推动代码质量和系统可维护性提升。\n\n岗位基本要求\n1.3年以上前端或全栈开发经验。\n2.熟练掌握前端基础技能，深入理解CSS、JavaScript等理论知识。\n3.熟练掌握React、Vue、AngularJS等主流前端框架。  \n4.熟悉Node.js或至少一门后端语言（如Java、Python），具备全栈开发基础知识。  \n5.有AI辅助开发经验。\n6.具备良好的业务理解能力、沟通能力和团队协作精神。\n\n具备以下条件优先\n1.有AI SDLC实践经验。\n2.有全栈开发经验。\n\n岗位亮点\n1.参与境外Keeta业务早期建设，可了解业务全貌及系统架构演进。\n2.参与核心营销系统建设，直接影响业务增长。  \n3.参与AI Coding在大型复杂业务系统中的应用。\n4.无边界的技术探索空间，前沿AI技术可快速实验和推广。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4635144995","sourceKey":"meituan_social","company":"美团","title":"小象超市-配送渠道经理（天津）","city":"天津市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4635144995&jobShareType=1","duty":"1.制定区域配送管理的方案，监督现场执行情况，检查美团小象超市站点配送的日常管理，流程上的监督、纠正；\n2.推动本区域业务运营落地工作，监控日常运营、服务质量、指标数据；\n3.负责区域的履约问题收集、反馈和解决工作，运营运作异常事件的跟进处理、总结分析、监督改进；\n4.负责区域内督导、骑手的培训工作，提高员工的综合素质和业务能力；\n5.负责区域内站点的服务质量，分析配送客诉，采取有效措施把控客诉，提供专业、高效、高质量的配送服务，提升顾客满意度。","requirements":"1.本科及以上学历，物流管理或供应链管理专业或3年以上配送运营相关工作经验；\n2.具有良好的沟通协调技巧和团队合作意识，跨部门协调能力，能与其他部门或者外部单位良好的沟通，踏实认真，有责任感；\n3.对数据变化敏感，有优秀的数据分析能力和学习能力，熟练使用各类办公软件；\n4.具备一定的文档处理能力，熟练操作常用办公软件；\n5.具备较强执行力，能适应高强度的工作和阶段性出差；\n6.具备较强的市场开拓性，有项目管理能力，思路清晰，管理协调能力佳。\n7.掌握基本的AI工具，使用工具提升工作流程效率。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1.制定区域配送管理的方案，监督现场执行情况，检查美团小象超市站点配送的日常管理，流程上的监督、纠正；\n2.推动本区域业务运营落地工作，监控日常运营、服务质量、指标数据；\n3.负责区域的履约问题收集、反馈和解决工作，运营运作异常事件的跟进处理、总结分析、监督改进；\n4.负责区域内督导、骑手的培训工作，提高员工的综合素质和业务能力；\n5.负责区域内站点的服务质量，分析配送客诉，采取有效措施把控客诉，提供专业、高效、高质量的配送服务，提升顾客满意度。\n\n岗位基本要求\n1.本科及以上学历，物流管理或供应链管理专业或3年以上配送运营相关工作经验；\n2.具有良好的沟通协调技巧和团队合作意识，跨部门协调能力，能与其他部门或者外部单位良好的沟通，踏实认真，有责任感；\n3.对数据变化敏感，有优秀的数据分析能力和学习能力，熟练使用各类办公软件；\n4.具备一定的文档处理能力，熟练操作常用办公软件；\n5.具备较强执行力，能适应高强度的工作和阶段性出差；\n6.具备较强的市场开拓性，有项目管理能力，思路清晰，管理协调能力佳。\n7.掌握基本的AI工具，使用工具提升工作流程效率。\n\n具备以下条件优先\n具备外卖配送渠道管理、生鲜配送行业经验的候选人优先考虑\n\n岗位亮点\n晋升空间大，发展机会多，团队内部氛围好；有机会参与配送内部的关键项目，或得更多学习成长的机会","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4621579125","sourceKey":"meituan_social","company":"美团","title":"小象线上店店长-重庆","city":"重庆市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4621579125&jobShareType=1","duty":"1.负责线上店的商品管理，对于商品的有效期管理、品质管理、损耗管理负责，负责门店的水产养殖和销售的整体管理；\n2.负责线上店的进销存管理，负责线上店内门店的收货、上架、库存、库位的管理工作，优化店内的动线和库位，对于商品的周转和资产、设备的安全准确负责；\n3.负责线上店订单的履约，保证在更快的时间保质保量履约客户的订单，不断追求降本提效，致力于为客户提供更好的服务，不断精益求精；配合总部各项营销策略的实施，负责线上各品类商品的日常的促销活动实施；\n4.负责线上店现场的人员管理，包括招聘、培训和效率管理，负责数据管理和异常事件处理，维护周边社区关系；进行日常经营管理工作，包含对各项运营指标进行监控和分析，确保销售达成；\n5.负责新开门店开业前期筹备相关工作。","requirements":"1.五年以上连锁门店/单体大店经营管理经验，熟悉新零售优先；\n2.对生鲜商品有一定的认知，熟悉门店促销管理、损耗控制管理、品类管理等；\n3.良好的沟通能力及跨部门团队合作精神，学习能力佳，责任心强，愿意接受挑战，以结果为导向；\n4.善于劳务人员的管理工作，熟悉与零售相关的法律法规；\n5.熟练操作办公软件及智能手机，热爱互联网行业。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1.负责线上店的商品管理，对于商品的有效期管理、品质管理、损耗管理负责，负责门店的水产养殖和销售的整体管理；\n2.负责线上店的进销存管理，负责线上店内门店的收货、上架、库存、库位的管理工作，优化店内的动线和库位，对于商品的周转和资产、设备的安全准确负责；\n3.负责线上店订单的履约，保证在更快的时间保质保量履约客户的订单，不断追求降本提效，致力于为客户提供更好的服务，不断精益求精；配合总部各项营销策略的实施，负责线上各品类商品的日常的促销活动实施；\n4.负责线上店现场的人员管理，包括招聘、培训和效率管理，负责数据管理和异常事件处理，维护周边社区关系；进行日常经营管理工作，包含对各项运营指标进行监控和分析，确保销售达成；\n5.负责新开门店开业前期筹备相关工作。\n\n岗位基本要求\n1.五年以上连锁门店/单体大店经营管理经验，熟悉新零售优先；\n2.对生鲜商品有一定的认知，熟悉门店促销管理、损耗控制管理、品类管理等；\n3.良好的沟通能力及跨部门团队合作精神，学习能力佳，责任心强，愿意接受挑战，以结果为导向；\n4.善于劳务人员的管理工作，熟悉与零售相关的法律法规；\n5.熟练操作办公软件及智能手机，热爱互联网行业。\n\n具备以下条件优先\n有零售、物流行业系统性工作经验，有团队管理经验。\n\n岗位亮点\n即时零售线上店头部企业营运核心岗位，与互联网大咖及零售业专家共同发展。川渝地区开新城新站，业务发展快，个人机会多。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4546885378","sourceKey":"meituan_social","company":"美团","title":"小象超市-线下店经营分析-武汉","city":"武汉市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4546885378&jobShareType=1","duty":"1.数据体系建设：负责构建与优化华中大区的数据指标体系与报表平台，夯实数据基建，确保数据的准确、及时与可视化，为经营管理提供坚实基础；\n2.业务监控与预警：建立常态化业务监控体系，对核心经营指标进行实时与动态追踪，敏锐识别业务偏差与潜在风险，并实现前置的风险预警；\n3.深度专题分析：针对销售、客流、毛利、库存等关键业务模块进行深度诊断定位，通过多维分析挖掘问题根因，并形成有数据支撑的解决方案与行动建议；\n4.绩效管理与复盘：负责或协同完成大区及门店的绩效考核数据梳理与复盘分析，客观评估经营成果，为绩效改进和策略调整提供依据；\n5.决策支持与赋能：紧密对接业务团队，为区域战略规划、运营优化、营销活动等提供专项数据分析支持，输出专业分析报告，赋能业务科学决策；\n6.分析工具与模型应用：探索并引入先进的数据分析工具与方法，构建业务分析模型，不断提升团队的数据化运营水平；\n7.掌握基本的AI工具，使用工具提升工作流程效率。","requirements":"1.数学、统计学、计算机、经济学等相关专业优先；\n2.具备3年以上数据分析或经营分析相关工作经验，有零售/新零售行业背景者优先；\n3.精通表格处理，能熟练运用函数、透视表等进行高效数据处理；\n4.熟悉SQL，具备编写查询语句以获取和整合数据的能力；\n5.具备出色的逻辑思维能力和结构化表达能力，能够将复杂问题清晰化；\n6.拥有优秀的报告撰写能力，能独立完成逻辑严谨、结论明确、建议可行的经营分析报告。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1.数据体系建设：负责构建与优化华中大区的数据指标体系与报表平台，夯实数据基建，确保数据的准确、及时与可视化，为经营管理提供坚实基础；\n2.业务监控与预警：建立常态化业务监控体系，对核心经营指标进行实时与动态追踪，敏锐识别业务偏差与潜在风险，并实现前置的风险预警；\n3.深度专题分析：针对销售、客流、毛利、库存等关键业务模块进行深度诊断定位，通过多维分析挖掘问题根因，并形成有数据支撑的解决方案与行动建议；\n4.绩效管理与复盘：负责或协同完成大区及门店的绩效考核数据梳理与复盘分析，客观评估经营成果，为绩效改进和策略调整提供依据；\n5.决策支持与赋能：紧密对接业务团队，为区域战略规划、运营优化、营销活动等提供专项数据分析支持，输出专业分析报告，赋能业务科学决策；\n6.分析工具与模型应用：探索并引入先进的数据分析工具与方法，构建业务分析模型，不断提升团队的数据化运营水平；\n7.掌握基本的AI工具，使用工具提升工作流程效率。\n\n岗位基本要求\n1.数学、统计学、计算机、经济学等相关专业优先；\n2.具备3年以上数据分析或经营分析相关工作经验，有零售/新零售行业背景者优先；\n3.精通表格处理，能熟练运用函数、透视表等进行高效数据处理；\n4.熟悉SQL，具备编写查询语句以获取和整合数据的能力；\n5.具备出色的逻辑思维能力和结构化表达能力，能够将复杂问题清晰化；\n6.拥有优秀的报告撰写能力，能独立完成逻辑严谨、结论明确、建议可行的经营分析报告。\n\n具备以下条件优先\n了解Python 用于数据处理与分析者为佳。\n\n岗位亮点\n“业务大脑”，赋能管理层决策，岗位价值高，未来晋升空间大。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4454016473","sourceKey":"meituan_social","company":"美团","title":"小象超市-线下店门店培训运营-北京","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4454016473&jobShareType=1","duty":"1.培训体系规划：基于大区业务战略与人才梯队现状，进行培训需求分析，负责构建并持续迭代区域分层、分条线的全流程培训体系与年度规划。\n2.学习内容开发：主导关键课程（如服务标准、运营流程、销售技巧、管理能力等）的课件设计与内容制作，开发标准化教材、案例库及数字化学习材料。\n3.培训项目落地：负责组织并实施各类培训项目，包括新员工入职集训、在岗技能提升、储备干部培养及管理层发展项目，确保培训高效落地。\n4.讲师团队管理与赋能：负责区域内部讲师团队的选拔、培养、认证与激励，通过定期教研与技能培训，提升讲师团队的专业交付能力。\n5.培训效果检验：建立科学的培训效果评估体系，通过考核、调研、行为观察及业务数据比对等方式，检验培训转化效果，并持续优化培训策略。\n6.学习运营与数字化：负责学习平台与资源的日常运营管理，探索并应用多样化的学习技术与形式，提升培训的覆盖度、便捷性与员工学习体验。\n7.掌握基本的AI工具，使用工具提升工作流程效率。","requirements":"1.人力资源管理、教育学、心理学等相关专业优先。\n2.拥有3年以上培训相关工作经验，具备零售行业培训背景者佳。\n3.具备独立完成培训需求分析、项目规划、课件开发与授课交付的全流程实操经验。\n4.具备良好的数据处理能力，能使用常用函数和相关数据工具分析培训效果与人才数据。\n5.拥有优秀的报告撰写与呈现能力，能清晰展示培训项目价值与人才发展成果。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1.培训体系规划：基于大区业务战略与人才梯队现状，进行培训需求分析，负责构建并持续迭代区域分层、分条线的全流程培训体系与年度规划。\n2.学习内容开发：主导关键课程（如服务标准、运营流程、销售技巧、管理能力等）的课件设计与内容制作，开发标准化教材、案例库及数字化学习材料。\n3.培训项目落地：负责组织并实施各类培训项目，包括新员工入职集训、在岗技能提升、储备干部培养及管理层发展项目，确保培训高效落地。\n4.讲师团队管理与赋能：负责区域内部讲师团队的选拔、培养、认证与激励，通过定期教研与技能培训，提升讲师团队的专业交付能力。\n5.培训效果检验：建立科学的培训效果评估体系，通过考核、调研、行为观察及业务数据比对等方式，检验培训转化效果，并持续优化培训策略。\n6.学习运营与数字化：负责学习平台与资源的日常运营管理，探索并应用多样化的学习技术与形式，提升培训的覆盖度、便捷性与员工学习体验。\n7.掌握基本的AI工具，使用工具提升工作流程效率。\n\n岗位基本要求\n1.人力资源管理、教育学、心理学等相关专业优先。\n2.拥有3年以上培训相关工作经验，具备零售行业培训背景者佳。\n3.具备独立完成培训需求分析、项目规划、课件开发与授课交付的全流程实操经验。\n4.具备良好的数据处理能力，能使用常用函数和相关数据工具分析培训效果与人才数据。\n5.拥有优秀的报告撰写与呈现能力，能清晰展示培训项目价值与人才发展成果。\n\n岗位亮点\n区域人才发展的“总教练”与“赋能引擎”，岗位价值高，未来发展空间大。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4646665606","sourceKey":"meituan_social","company":"美团","title":"小象超市-线下店后场副店","city":"扬州市/蚌埠市/武汉市/重庆市/成都市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4646665606&jobShareType=1","duty":"1.主持门店后场部门日常工作，根据公司的经营状况与要求，制定部门工作计划，执行和落实仓库相关规章制度；\n2.按照标准SOP指导部门团队完成收货、理货、上架等各项作业流程，并根据业务变化，及时调整人员岗位及作业流程；\n3.负责门店后场仓储现场标准化管理，优化站点内部布局，落实仓内运营标准，确保标准化流程运营；\n4.部门人员管理，做好员工的岗位技能培训，并做好每月的员工排班及KPI考核等工作；\n5.现场6S管理、安全消防、安全作业，避免工伤事故和商品损坏事故的发生；\n6.掌握基本的AI工具，使用工具提升工作流程效率。","requirements":"1.物流、运输、仓储等相关专业优先；\n2.3年以上仓储管理经验，有门店后场或前置仓管理经验优先；\n3.熟悉仓储管理标准sop作业流程（清点、收货、上架、库存管理、盘点、波次运行、拣货），熟悉ERP及仓储管理系统。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1.主持门店后场部门日常工作，根据公司的经营状况与要求，制定部门工作计划，执行和落实仓库相关规章制度；\n2.按照标准SOP指导部门团队完成收货、理货、上架等各项作业流程，并根据业务变化，及时调整人员岗位及作业流程；\n3.负责门店后场仓储现场标准化管理，优化站点内部布局，落实仓内运营标准，确保标准化流程运营；\n4.部门人员管理，做好员工的岗位技能培训，并做好每月的员工排班及KPI考核等工作；\n5.现场6S管理、安全消防、安全作业，避免工伤事故和商品损坏事故的发生；\n6.掌握基本的AI工具，使用工具提升工作流程效率。\n\n岗位基本要求\n1.物流、运输、仓储等相关专业优先；\n2.3年以上仓储管理经验，有门店后场或前置仓管理经验优先；\n3.熟悉仓储管理标准sop作业流程（清点、收货、上架、库存管理、盘点、波次运行、拣货），熟悉ERP及仓储管理系统。\n\n具备以下条件优先\n沃尔玛、盒马、七鲜后场管理经验优先；前置仓管理经验优先\n\n岗位亮点\n1.提供广阔的晋升空间和发展机会，公司注重人才的培养和成长；\n2.薪资福利丰厚，员工福利完善，工作氛围轻松愉快；\n3.有机会参与公司决策和战略制定，对个人职业发展具有重要意义。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4646616856","sourceKey":"meituan_social","company":"美团","title":"小象超市-线下店前场副店","city":"扬州市/蚌埠市/武汉市/重庆市/成都市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4646616856&jobShareType=1","duty":"1.负责线下门店前场的日常管理工作，包括但不限于人员效率、商品陈列、销售目标达成等；\n2.确保门店的运营效率和服务质量，提升顾客满意度和忠诚度；\n3.组织并参与门店个品类促销活动，制定有效的营销策略，提升门店销售额；\n4.负责团队的招聘、培训和绩效考核，确保团队稳定和高效运作；\n5.协调与总部各部门的沟通与协作，推动门店业绩的持续提升。","requirements":"1.门店店长/督导/门店运营等相关经验；\n2.具备至少5年以上门店管理经验，有成功带领团队实现销售目标的经验；\n3.具备优秀的沟通协调能力、团队管理能力和解决问题能力；\n4.具备良好的商业敏感度和市场洞察力，能够快速响应市场变化；\n5.掌握基本的AI工具，使用工具提升工作流程效率。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1.负责线下门店前场的日常管理工作，包括但不限于人员效率、商品陈列、销售目标达成等；\n2.确保门店的运营效率和服务质量，提升顾客满意度和忠诚度；\n3.组织并参与门店个品类促销活动，制定有效的营销策略，提升门店销售额；\n4.负责团队的招聘、培训和绩效考核，确保团队稳定和高效运作；\n5.协调与总部各部门的沟通与协作，推动门店业绩的持续提升。\n\n岗位基本要求\n1.门店店长/督导/门店运营等相关经验；\n2.具备至少5年以上门店管理经验，有成功带领团队实现销售目标的经验；\n3.具备优秀的沟通协调能力、团队管理能力和解决问题能力；\n4.具备良好的商业敏感度和市场洞察力，能够快速响应市场变化；\n5.掌握基本的AI工具，使用工具提升工作流程效率。\n\n具备以下条件优先\n沃尔玛、盒马、七鲜前场管理经验优先\n\n岗位亮点\n1.提供广阔的晋升空间和发展机会，公司注重人才的培养和成长；\n2.薪资福利丰厚，员工福利完善，工作氛围轻松愉快；\n3.有机会参与公司决策和战略制定，对个人职业发展具有重要意义。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4624734848","sourceKey":"meituan_social","company":"美团","title":"医药健康-快递电商-物流组负责人","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4624734848&jobShareType=1","duty":"快递电商业务部物流运营负责人，通过物流规划、策略制定、经营管理、团队领导，为仓配效率、成本、履约体验目标结果负责。\n1、负责仓储配送规划与拓展，在对业务发展预判的基础上，快速响应业务对仓储配送能力的需求，完成新仓从选址、模式设计、仓内搭建、到运行管理的全流程建设落地；\n2、制定全国仓储运营年度/月度规划及运营策略，制定完善的运营指标体系并进行过程管理，建立标准化运营流程及精益改善体系，保障仓储运营效率及成本调优，不断提高用户体验；\n3、搭建物流服务商合作与管理体系，包括供应商引入、用工策略制定、人员效率提升、考核管理等，提高仓储服务人效及水平；\n4、负责物流管理信息系统的落地及推广实施，仓储管理系统（WMS）、履约调度系统（OFC）改造及升级，不断提高系统产品体验，通过AI优化调度，提升用户体验、降低成本。","requirements":"1、正规本科及以上学历，6年以上电商物流仓储规划及团队管理实战经验；\n2、具备从顶层设计到一线现场执行的全链路把控能力，拥有出色的跨部门沟通协作与资源整合能力；\n3、具备宏观行业视野，对物流行业发展趋势有深度理解与洞察；\n4、精通物流规划方法论，在网络规划、系统流程设计、库内布局规划等一个或多个领域具备深度项目管理经验；\n5、对AI技术有热情，主动探索并推动AI工具在工作中落地应用，提升工作效率与业务成果。","description":"部门介绍\n美团医药健康事业部是美团核心本地商业板块下专注健康领域的业务部门，涵盖美团买药、美团医美和美团医疗三大业务。自创立以来，美团医药健康致力于为用户提供全健康周期产品及服务，满足人民群众多层次多元化医疗健康需求，现已覆盖购药到家、居家检测、问诊挂号、医保支付、求医寻院、医疗美容等核心场景。此外，美团医药健康还为商户提供数字化转型创新解决方案，打造贯穿上游的联动机制，长期参与共建更透明、更可持续的医药健康产业生态圈，目前业务已覆盖25万家药店，收录27万家医疗机构。未来，美团医药康将协同更多行业伙伴，帮助大家变得更健康、更美丽、更养生。\n\n岗位职责\n快递电商业务部物流运营负责人，通过物流规划、策略制定、经营管理、团队领导，为仓配效率、成本、履约体验目标结果负责。\n1、负责仓储配送规划与拓展，在对业务发展预判的基础上，快速响应业务对仓储配送能力的需求，完成新仓从选址、模式设计、仓内搭建、到运行管理的全流程建设落地；\n2、制定全国仓储运营年度/月度规划及运营策略，制定完善的运营指标体系并进行过程管理，建立标准化运营流程及精益改善体系，保障仓储运营效率及成本调优，不断提高用户体验；\n3、搭建物流服务商合作与管理体系，包括供应商引入、用工策略制定、人员效率提升、考核管理等，提高仓储服务人效及水平；\n4、负责物流管理信息系统的落地及推广实施，仓储管理系统（WMS）、履约调度系统（OFC）改造及升级，不断提高系统产品体验，通过AI优化调度，提升用户体验、降低成本。\n\n岗位基本要求\n1、正规本科及以上学历，6年以上电商物流仓储规划及团队管理实战经验；\n2、具备从顶层设计到一线现场执行的全链路把控能力，拥有出色的跨部门沟通协作与资源整合能力；\n3、具备宏观行业视野，对物流行业发展趋势有深度理解与洞察；\n4、精通物流规划方法论，在网络规划、系统流程设计、库内布局规划等一个或多个领域具备深度项目管理经验；\n5、对AI技术有热情，主动探索并推动AI工具在工作中落地应用，提升工作效率与业务成果。\n\n岗位亮点\n业务高速增长，物流拓展及优化空间大，带团队，团队现有成员能力整体上较为突出。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4654047003","sourceKey":"meituan_social","company":"美团","title":"自动驾驶交付测试工程师","city":"北京市/深圳市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4654047003&jobShareType=1","duty":"1）测试策略制定：结合城市路网特点，安排车辆路测计划和方案，输出测试交付排期和所需资源，并迭代接管SOP，为测试效率和质量负责；\n2）问题分析定位：分析自动驾驶在道路测试中的行为表现，通过数据下钻定位系统缺陷根因，输出可落地的改进策略，推动Case分析、分层聚类和跟进闭环；\n3）流程建设和效能提升：根据过往测试交付中的问题点，建立横向协调各方的工具化和标准化的测试交付方案，输出可复制的交付能力；\n4）AI开发：结合测试交付的完整流程，借助AI开发提效工具；\n5）与产品、研发、算法等团队紧密协作，保障测试流程高效推进。","requirements":"1）计算机科学、电子工程、自动化、车辆工程等相关专业本科及以上学历；\n2）具备超强owner意识，能完整承接项目需求，具备较强的问题解决与横向协调推进能力；\n3）逻辑清晰，深入理解自动驾驶系统架构（感知、规划、控制等模块），能定位自动驾驶能力问题并输出测试策略，同时能主动思考并持续迭代测试策略和能力认知；","description":"部门介绍\n无人车业务部成立于2016年，旨在用无人驾驶技术提升物流配送的效率和体验。美团无人车以自研L4级自动驾驶软硬件技术为核心，与美团即时零售业务结合，形成满足公开道路、社区、工业园区等室外全场景下的无人配送整体解决方案。自2020年起，无人车已在北京、深圳等多地进入常态化试运营阶段，在城市复杂场景下提供针对餐饮外卖、生鲜食杂等货物的即时配送服务。2025年，美团无人车又踏上了同城货运的新探索，并在2026年持续扩大运营范围和车队数量，为更多城市带来智能配送服务。\n欢迎加入美团无人车团队，与我们一起用科技推动即时零售再升级！\n\n岗位职责\n1）测试策略制定：结合城市路网特点，安排车辆路测计划和方案，输出测试交付排期和所需资源，并迭代接管SOP，为测试效率和质量负责；\n2）问题分析定位：分析自动驾驶在道路测试中的行为表现，通过数据下钻定位系统缺陷根因，输出可落地的改进策略，推动Case分析、分层聚类和跟进闭环；\n3）流程建设和效能提升：根据过往测试交付中的问题点，建立横向协调各方的工具化和标准化的测试交付方案，输出可复制的交付能力；\n4）AI开发：结合测试交付的完整流程，借助AI开发提效工具；\n5）与产品、研发、算法等团队紧密协作，保障测试流程高效推进。\n\n岗位基本要求\n1）计算机科学、电子工程、自动化、车辆工程等相关专业本科及以上学历；\n2）具备超强owner意识，能完整承接项目需求，具备较强的问题解决与横向协调推进能力；\n3）逻辑清晰，深入理解自动驾驶系统架构（感知、规划、控制等模块），能定位自动驾驶能力问题并输出测试策略，同时能主动思考并持续迭代测试策略和能力认知；\n\n具备以下条件优先\n1）有自动驾驶系统开发或测试经验\n2）有车辆动力学、传感器融合、自动驾驶算法各模块等知识\n3）有扩量扩城交付经验（城市差异化运营背景）\n\n岗位亮点\n1）行业前沿：自动驾驶+AI最前沿科技探索，深入参与科技硬件对生活服务的改变\n2）高壁垒：自动驾驶行业岗位壁垒高，有利于提升个人职业价值\n3）技术深度：深入理解L4级自动驾驶系统架构，接触完整的感知-规划-控制技术栈\n4）成长空间：自动驾驶头部团队，发展空间巨大，有无人车规模化增长机会","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3788551786","sourceKey":"meituan_social","company":"美团","title":"小象超市-商品财务BP（策略分析方向）","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3788551786&jobShareType=1","duty":"1. 财务分析：参与产品和项目的整体评估，包括商业定价、健康度评估，并建立规范的通用模型；按期出具多维度的经营分析数据及业务运营情况、行业同类产品分析报告，结合业务特点制定关键业务指标及分析体系，与业务建立双向反馈机制；\n\n2. 财务支持：深入了解业务，与业务伙伴密切合作，建立合理有效的分析体系，给予有效建议并推进解决方案，深度支持业务决策和过程管理；\n\n3. 财务管理：对业务方案进行风险评估，建立定期的业务和财务数据跟踪体系，对重点业务和项目进行随时跟进，定期反馈。","requirements":"1、5年及以上数据分析、经营分析、策略分析等相关工作经验；\n\n2、掌握各项数据工具（SQL等），具备高阶经营分析/数据分析能力，善于从数据背后抽丝剥茧、层层下探，识别业务信号；\n\n3、具备较强的商业洞察力，逻辑性强，能够框架性拆解并分析问题、推动问题解决；\n\n4、自驱力强、优秀的沟通表达能力和文档书写能力，具有主人翁意识和团队协作精神，在快速的业务变化中迅速适应和成长。\n5、对 AI 技术在财务和业务分析领域的应用有主动探索意识，能结合 AI 工具创新分析方法，推动财务支持数智化转型。","description":"部门介绍\n财务平台负责公司整体和各业务层面的财务管理工作，通过建设专业、全面、复合的财务管理能力和与业务经营的紧密结合来支持公司健康发展。目前财务平台拥有财务会计、财务报告、资金管理、税务管理、财务共享、财务系统、规划分析、财务BP和内控内审等主要工作方向。我们的目标是建设业界一流的财务管理能力和经营支持体系，为公司战略的正确落地、投入效率的持续提升、业务价值的不断增长保驾护航。欢迎加入财务平台，携手一起向未来！\n\n岗位职责\n1. 财务分析：参与产品和项目的整体评估，包括商业定价、健康度评估，并建立规范的通用模型；按期出具多维度的经营分析数据及业务运营情况、行业同类产品分析报告，结合业务特点制定关键业务指标及分析体系，与业务建立双向反馈机制；\n\n2. 财务支持：深入了解业务，与业务伙伴密切合作，建立合理有效的分析体系，给予有效建议并推进解决方案，深度支持业务决策和过程管理；\n\n3. 财务管理：对业务方案进行风险评估，建立定期的业务和财务数据跟踪体系，对重点业务和项目进行随时跟进，定期反馈。\n\n岗位基本要求\n1、5年及以上数据分析、经营分析、策略分析等相关工作经验；\n\n2、掌握各项数据工具（SQL等），具备高阶经营分析/数据分析能力，善于从数据背后抽丝剥茧、层层下探，识别业务信号；\n\n3、具备较强的商业洞察力，逻辑性强，能够框架性拆解并分析问题、推动问题解决；\n\n4、自驱力强、优秀的沟通表达能力和文档书写能力，具有主人翁意识和团队协作精神，在快速的业务变化中迅速适应和成长。\n5、对 AI 技术在财务和业务分析领域的应用有主动探索意识，能结合 AI 工具创新分析方法，推动财务支持数智化转型。\n\n具备以下条件优先\n具备经营分析、商业分析、数据分析工作经验优先。\n\n岗位亮点\n1、业务核心岗位，团队氛围好，可与多部门合作，职业发展空间广阔。\n\n2、业务增长速度快，个人成长机会多，发挥空间大。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4653559723","sourceKey":"meituan_social","company":"美团","title":"生鲜供应链品控主管","city":"济南市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4653559723&jobShareType=1","duty":"1.负责小象超市生鲜供应链环节商品及供应商质量管理，从源头到餐桌，预防和优化商品质量问题，提升用户满意度；\n2.负责商品验收，存储，包装，配送过程中的质量检测和标准落地，减少各环节的商品质量问题发生；\n3.负责跟踪解决出现的商品（特别是生鲜产品）质量问题，避免商品质量问题重复出现，影响用户体验；\n4.负责与采购/客服/品质标准组等相关横向部门配合，解决商品品质异常及潜在食品安全风险。","requirements":"1.大专以上学历，2年以上零售质量管理经验、或供应链质量管理经验、或门店商品质量运营管理\n2.具备跨部门的高效沟通及协作能力，能快速推进项目落地；\n3.诚信、正直、责任心及上进心强。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1.负责小象超市生鲜供应链环节商品及供应商质量管理，从源头到餐桌，预防和优化商品质量问题，提升用户满意度；\n2.负责商品验收，存储，包装，配送过程中的质量检测和标准落地，减少各环节的商品质量问题发生；\n3.负责跟踪解决出现的商品（特别是生鲜产品）质量问题，避免商品质量问题重复出现，影响用户体验；\n4.负责与采购/客服/品质标准组等相关横向部门配合，解决商品品质异常及潜在食品安全风险。\n\n岗位基本要求\n1.大专以上学历，2年以上零售质量管理经验、或供应链质量管理经验、或门店商品质量运营管理\n2.具备跨部门的高效沟通及协作能力，能快速推进项目落地；\n3.诚信、正直、责任心及上进心强。\n\n岗位亮点\n加入快速发展的即时零售平台，参与生鲜品控核心环节\n\n可在多个一二线城市拓展城市品控管理经验","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4650191230","sourceKey":"meituan_social","company":"美团","title":"小象超市-蛋类采购专家","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4650191230&jobShareType=1","duty":"1、负责蛋类的商品规划、采购管理、供应链管理、城市经营等，为经营结果负责；\n2、负责采购的供应商资源开发及管理，通过供应商谈判获得地采&销售渠道的供应链优化，效能提升；\n3、通过资源整合、品牌谈判、供应链优化等行为综合提升达到利润及效能的提升；\n4、把握市场动态，及时调整资源配置、确保采购的竞争处于优势。具备行业信息收集及行业经验获取能力。","requirements":"1、专科以上学历，有5年以上蛋类采销和营运经验；\n2、对采购业务流程及体系有清晰的认识，对零售行业有很强的预判能力和突破能力；\n3、擅长源头供应商寻找和开发经验，并且有效管理供应商；\n4、买手型采购专家，具有较强的分析判断、前瞻思维、承压能力和团队合作意识，有采购管理经验；\n5、具备项目统筹能力，能够协调和推进公司各支持部门完成项目落地及后续效率优化；\n6、掌握基本的AI工具，使用工具提升工作流程效率。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1、负责蛋类的商品规划、采购管理、供应链管理、城市经营等，为经营结果负责；\n2、负责采购的供应商资源开发及管理，通过供应商谈判获得地采&销售渠道的供应链优化，效能提升；\n3、通过资源整合、品牌谈判、供应链优化等行为综合提升达到利润及效能的提升；\n4、把握市场动态，及时调整资源配置、确保采购的竞争处于优势。具备行业信息收集及行业经验获取能力。\n\n岗位基本要求\n1、专科以上学历，有5年以上蛋类采销和营运经验；\n2、对采购业务流程及体系有清晰的认识，对零售行业有很强的预判能力和突破能力；\n3、擅长源头供应商寻找和开发经验，并且有效管理供应商；\n4、买手型采购专家，具有较强的分析判断、前瞻思维、承压能力和团队合作意识，有采购管理经验；\n5、具备项目统筹能力，能够协调和推进公司各支持部门完成项目落地及后续效率优化；\n6、掌握基本的AI工具，使用工具提升工作流程效率。\n\n具备以下条件优先\n具备养殖专业能力，深度洞察消费需求，有落地操盘经营优先。\n\n岗位亮点\n具有多类创新业务场景的实践机会，在品类规划、供应链优化等方面具有操盘空间和品类发展空间大，个人成长速度快。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4641915941","sourceKey":"meituan_social","company":"美团","title":"餐饮系统-高级客户成功（北京）","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4641915941&jobShareType=1","duty":"1、餐饮行业资深专家，根据客户管理现状及业务痛点分析，挖掘根因，给出运营指导建议，制定并落地解决方案，提升产品健康度的同时协助连锁品牌拿到业务结果\n2、通过向客户提供餐饮行业解决方案，让客户更好的使用我们的SaaS软件，提升客户健康度，从而提升客户生命周期。并在客户经营发展过程中，有效识别市场动态，对产品PMF提供建议和反馈，从而发掘交叉销售的机会\n3、维护餐饮连锁总部，提升客户健康度，对所辖区域连锁品牌的活跃留存负责，减少并管理流失","requirements":"1、学历本科以上，计算机、软件工程、信息管理，网络工程等相关专业，有至少3年以上餐饮SaaS行业工作经验；有2年以上销售、运营或客户成功经验\n2、5年以上相关工作经验，热爱互联网行业，拥有餐饮软件行业经验者优先；\n3、具有良好的沟通能力，学习能力强，擅长主动汲取信息和知识，头脑灵活，积极主动，具有团队合作精神；\n4、正直可靠。品行端正，积极阳光的你，我们都爱；\n5、热爱生活。个性开朗，富有激情，喜好餐饮行业、吃货，我们会有共同话题的。\n6、有耐心、有韧性，喜欢与人沟通类工作；愿意从事客户维护工作，具备一定要性；\n我们提供互联网业内卓越的平台+有竞争力的薪资+通讯交通补贴+当地五险一金+所有法定节假日（带薪年、产、陪产、病等假期）+晋升机会+定期团建活动……","description":"部门介绍\n美团餐饮系统为餐饮企业提供一站式IT解决方案，帮助餐饮商户实现从供应链管理、生产管理、前厅管理到外卖的数字化经营。美团餐饮系统不仅打通了餐厅和平台，更帮助餐厅连接客人，让商户更了解顾客需求，在帮助商户做商业决策的同时给顾客带来更好的消费体验。\n我们持续建设和提升产研、销售、服务的核心能力，通过全新升级的美团餐饮系统一体化软硬件产品，助力餐饮商户进行线上化经营，帮助商户在推广新店、提升效率、降低成本、会员营销、流量扶持、智慧选址、供应链管理等方面强化经营能力。团队汇集了餐饮和SaaS领域的优秀人才，秉持着“以客户为中心”的初心和“长期有耐心”的耕耘精神，求真、敬畏、敢于自我否定、善于快速学习。期待同样愿意长期致力于餐饮产业数字化、智能化的你加入我们的团队，共同进步共同成长！\n\n岗位职责\n1、餐饮行业资深专家，根据客户管理现状及业务痛点分析，挖掘根因，给出运营指导建议，制定并落地解决方案，提升产品健康度的同时协助连锁品牌拿到业务结果\n2、通过向客户提供餐饮行业解决方案，让客户更好的使用我们的SaaS软件，提升客户健康度，从而提升客户生命周期。并在客户经营发展过程中，有效识别市场动态，对产品PMF提供建议和反馈，从而发掘交叉销售的机会\n3、维护餐饮连锁总部，提升客户健康度，对所辖区域连锁品牌的活跃留存负责，减少并管理流失\n\n岗位基本要求\n1、学历本科以上，计算机、软件工程、信息管理，网络工程等相关专业，有至少3年以上餐饮SaaS行业工作经验；有2年以上销售、运营或客户成功经验\n2、5年以上相关工作经验，热爱互联网行业，拥有餐饮软件行业经验者优先；\n3、具有良好的沟通能力，学习能力强，擅长主动汲取信息和知识，头脑灵活，积极主动，具有团队合作精神；\n4、正直可靠。品行端正，积极阳光的你，我们都爱；\n5、热爱生活。个性开朗，富有激情，喜好餐饮行业、吃货，我们会有共同话题的。\n6、有耐心、有韧性，喜欢与人沟通类工作；愿意从事客户维护工作，具备一定要性；\n我们提供互联网业内卓越的平台+有竞争力的薪资+通讯交通补贴+当地五险一金+所有法定节假日（带薪年、产、陪产、病等假期）+晋升机会+定期团建活动……\n\n具备以下条件优先\n客户成功经理，销售经验，项目管理经验\n\n岗位亮点\n大客户经营管理\n团队成长\n横向联通\n美团生态链接","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4321475963","sourceKey":"meituan_social","company":"美团","title":"AI Agent 开发工程师","city":"北京市/成都市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4321475963&jobShareType=1","duty":"1. 负责CatPaw SDK/CLI能力建设，设计并实现Skill/Plugin体系，持续提升开发者体验。  \n2. 基于OpenClaw构建CatClaw集群，负责多智能体运行时、路由调度、会话管理及记忆系统的设计与开发。  \n3. 主导AI编排层开发，包括多模型调度、Prompt工程、Function Calling及上下文管理机制。  \n4. 推动IM/社交/办公等多端渠道的场景接入，支持浏览器自动化能力集成。  \n5. 构建安全隔离体系，实现多租户权限控制与数据沙箱机制，保障系统安全性与稳定性。","requirements":"1. 大学本科及以上学历，3年以上开发经验，精通TypeScript/Node.js或Python。  \n2. 重度AI Coding用户，熟练使用CatPaw/NoCode/Cursor/CC等AI编程工具进行日常开发。  \n3. 深入理解LLM应用开发，掌握Prompt设计、Tool Use、RAG等核心技术。  \n4. 具备平台或框架级系统设计能力，能独立完成复杂模块架构与实现。  \n5. 具备自驱力，善于与AI协作，主动探索技术边界并推动落地。","description":"部门介绍\n基础研发平台是美团的核心技术平台，立足于“零售+科技”的战略定位，通过打造人工智能、大数据、云计算、安全等核心技术能力，以及研发效能平台、企业应用平台等公共服务，为业务提供稳定安全、扩展易用、技术领先的平台技术和产品服务。\n在这里，我们会参与到最前沿的技术研发和探索；能够接触超规模集群、海量数据，挑战高复杂业务场景，有机会与业界一流的工程师一起并肩前行。\n在这里，我们有超强的技术氛围，持续向社区贡献业界实践，加速行业技术发展；我们有完善的互联网学习生态圈，重视底层逻辑和方法论，助力职业生涯的非线性成长。\n真诚地邀请你，和我们一起驱动技术发展，创造行业价值。\n\n岗位职责\n1. 负责CatPaw SDK/CLI能力建设，设计并实现Skill/Plugin体系，持续提升开发者体验。  \n2. 基于OpenClaw构建CatClaw集群，负责多智能体运行时、路由调度、会话管理及记忆系统的设计与开发。  \n3. 主导AI编排层开发，包括多模型调度、Prompt工程、Function Calling及上下文管理机制。  \n4. 推动IM/社交/办公等多端渠道的场景接入，支持浏览器自动化能力集成。  \n5. 构建安全隔离体系，实现多租户权限控制与数据沙箱机制，保障系统安全性与稳定性。\n\n岗位基本要求\n1. 大学本科及以上学历，3年以上开发经验，精通TypeScript/Node.js或Python。  \n2. 重度AI Coding用户，熟练使用CatPaw/NoCode/Cursor/CC等AI编程工具进行日常开发。  \n3. 深入理解LLM应用开发，掌握Prompt设计、Tool Use、RAG等核心技术。  \n4. 具备平台或框架级系统设计能力，能独立完成复杂模块架构与实现。  \n5. 具备自驱力，善于与AI协作，主动探索技术边界并推动落地。\n\n具备以下条件优先\n1. 有Agent平台/IDE/CLI工具链开发经验。  \n2. 熟悉浏览器自动化技术（如Playwright/CDP）。  \n3. 搭建过AI助理并投入日常使用。\n\n岗位亮点\n1. 参与构建下一代AI Agent开发框架与运行平台，技术影响力广泛。  \n2. 深度使用AI工具进行开发，鼓励高效人机协作。  \n3. 与前沿AI技术团队共同探索多智能体系统、浏览器自动化等创新方向。  \n4. 扁平化工作环境，支持技术自主决策与快速迭代。  \n5. 工作地点位于成都市，享受优质科技人才生态与生活环境。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4648813171","sourceKey":"meituan_social","company":"美团","title":"B端高阶AI产品经理","city":"上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4648813171&jobShareType=1","duty":"1. 深入研究零售商家端连锁业务场景，通过FDE等方式挖掘商户经营痛点，转化为可落地的AI通用解决方案并推动商业化售卖； \n2. 负责商家大模型应用的整体产品规划与能力建设，推动AI技术在连锁商户中的深度应用；\n3. 主导连锁版AI产品能力建设，覆盖图片生成、数据分析、批量操作等业务场景，提升商户经营效率；  \n4. 与业务团队、技术团队紧密协作，定义产品目标与实施路径，确保产品功能的高效交付与持续优化；  \n5. 关注行业趋势与技术前沿，探索大模型技术在零售领域的创新应用，推动产品迭代与升级。","requirements":"1. 本科及以上学历，计算机、数据科学、信息管理、经济学等相关专业优先；  \n2. 具备5年以上互联网产品经理经验，熟悉B端产品设计，有本地生活服务、电商或零售行业经验者优先；  \n3. 对AI技术及大模型应用有深刻理解，熟悉提示工程（PE）及相关技术落地场景；  \n4. 具备优秀的逻辑思维能力、问题抽象能力及数据分析能力，能够快速定位问题并提出解决方案；  \n5. 出色的沟通协调能力，能够跨部门高效协作，推动产品落地；  \n6. 自我驱动力强，具备较强的责任心与韧性；  \n7. 有AI产品商业化经验者加分，熟悉零售商户经营模式及痛点者优先。","description":"部门介绍\n美团服务零售事业部下设乐生活业务部、易生活业务部、进场零售业务部以及中小城市发展部四大业务部门，旨在通过提供丰富、可靠、实惠的服务与商品满足用户各类生活需求。我们所处的服务零售行业是一个具有万亿规模的市场，覆盖足疗洗浴、酒吧KTV、运动健身、美发美甲、教育培训、亲子游乐、家政洗涤维修、摄影写真等数十个服务消费细分领域，同时延伸至超市便利、美妆个护、3C数码、服饰珠宝、运动户外、商场购物中心等实体零售到店消费场景，连接数十万品牌商户与线下门店。作为商家和行业的小帮手，我们持续深入服务零售与实体零售产业链，用AI等技术推动行业变革，帮助商家提升经营效率、实现高效的线上化经营与到店转化，优化消费者服务体验，提供安心、放心的履约保障。这里有着多元的业务布局，有着富有挑战和影响力的工作内容，为你提供丰富的视野、持续的成长和发展机会，引领你发现更多可能。期待和你在“随时随地，美好生活”的愿景指引下，共建美好的生活服务体验、健康的商家生态与高质量的经营结果。\n\n岗位职责\n1. 深入研究零售商家端连锁业务场景，通过FDE等方式挖掘商户经营痛点，转化为可落地的AI通用解决方案并推动商业化售卖； \n2. 负责商家大模型应用的整体产品规划与能力建设，推动AI技术在连锁商户中的深度应用；\n3. 主导连锁版AI产品能力建设，覆盖图片生成、数据分析、批量操作等业务场景，提升商户经营效率；  \n4. 与业务团队、技术团队紧密协作，定义产品目标与实施路径，确保产品功能的高效交付与持续优化；  \n5. 关注行业趋势与技术前沿，探索大模型技术在零售领域的创新应用，推动产品迭代与升级。\n\n岗位基本要求\n1. 本科及以上学历，计算机、数据科学、信息管理、经济学等相关专业优先；  \n2. 具备5年以上互联网产品经理经验，熟悉B端产品设计，有本地生活服务、电商或零售行业经验者优先；  \n3. 对AI技术及大模型应用有深刻理解，熟悉提示工程（PE）及相关技术落地场景；  \n4. 具备优秀的逻辑思维能力、问题抽象能力及数据分析能力，能够快速定位问题并提出解决方案；  \n5. 出色的沟通协调能力，能够跨部门高效协作，推动产品落地；  \n6. 自我驱动力强，具备较强的责任心与韧性；  \n7. 有AI产品商业化经验者加分，熟悉零售商户经营模式及痛点者优先。\n\n岗位亮点\n1. 深入服务零售200余行业，了解本地生活行业的多样化需求与痛点；  \n2. 负责AI产品的全链路设计与落地实施，兼具技术创新与业务实践，成长空间大；  \n3. 有机会参与大模型技术在零售商户端的前沿应用，积累丰富的实战经验；  \n4. 高度参与产品商业化过程，助力AI技术在零售领域的规模化推广，成就感强；  \n5. 与优秀团队共事，接触行业一线技术和资源，持续提升专业能力与视野。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4652501371","sourceKey":"meituan_social","company":"美团","title":"供应链生鲜品控专家-长沙","city":"长沙市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4652501371&jobShareType=1","duty":"1. 负责小象超市生鲜供应链环节商品及供应商质量管理，从源头到餐桌，预防和优化商品质量问题，提升用户满意度；\n2. 全链路保障商品品质，负责商品验收、存储、包装、配送过程中的质量检测和标准落地，预防和减少各环节的商品质量问题发生；\n3. 负责跟踪解决出现的商品（特别是生鲜产品）质量问题，避免商品质量问题重复出现，影响用户体验；\n4. 负责与采购/客服/品控标准组等相关横向部门配合，解决商品品质异常及潜在食品安全风险。","requirements":"1.大专及以上学历，3年及以上商超零售/供应链/门店商品质量运营管理经验；\n2.具备较强的跨部门协同与推动能力，能高效拉通资源、快速推进项目落地；\n3.诚信正直，责任心强，具备良好的职业操守与进取意识。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1. 负责小象超市生鲜供应链环节商品及供应商质量管理，从源头到餐桌，预防和优化商品质量问题，提升用户满意度；\n2. 全链路保障商品品质，负责商品验收、存储、包装、配送过程中的质量检测和标准落地，预防和减少各环节的商品质量问题发生；\n3. 负责跟踪解决出现的商品（特别是生鲜产品）质量问题，避免商品质量问题重复出现，影响用户体验；\n4. 负责与采购/客服/品控标准组等相关横向部门配合，解决商品品质异常及潜在食品安全风险。\n\n岗位基本要求\n1.大专及以上学历，3年及以上商超零售/供应链/门店商品质量运营管理经验；\n2.具备较强的跨部门协同与推动能力，能高效拉通资源、快速推进项目落地；\n3.诚信正直，责任心强，具备良好的职业操守与进取意识。\n\n具备以下条件优先\n1. 热爱互联网和新零售行业，具有极强的快速学习能力，进取心和要性强；\n2. 有较强的质量管理方法论且可以快速结合业务特点落地能力；\n3. 擅长数据分析，自驱力、逻辑思维能力、落地执行能力强；\n4. 有生鲜水果、PC加工质量管理经验优先。\n\n岗位亮点\n本岗位直接参与美团小象超市业务的商品品质管理，你的工作将影响生鲜行业的食安与品质标准，同时伴随业务快速增长，带来较大的成长与晋升机会。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4550275307","sourceKey":"meituan_social","company":"美团","title":"智能硬件产品运营","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4550275307&jobShareType=1","duty":"1. 搭建并维护产品 VOC（Voice of Customer）体系，运用 AI 大模型对海量用户反馈进行智能分类、情感分析和趋势洞察，结合客服工单、社媒舆情、售后维修、一线销售等多渠道数据，自动化输出问题诊断报告和优化建议。\n2. 设计并执行用户调研，包括问卷设计、客户访谈、实地调研等，覆盖新品定义、上市验证、迭代优化等不同阶段。运用 AI 辅助工具提升调研效率，如 AI 辅助问卷生成、访谈纪要自动整理、用户画像智能分析，持续挖掘真实用户需求和使用痛点。\n3. 负责硬件产品营销内容产出，包括卖点提炼、宣传图文、短视频、销售材料等。探索 AI 辅助内容生成、创意迭代和效果测试，提升内容生产效率和传播转化率。\n4. 跟踪行业信息和动态，包括政策、市场趋势、用户评价等。利用 AI 工具实现信息自动抓取、用户评价批量分析和市场趋势智能洞察，定期沉淀分析结论，为产品规划提供决策依据。\n5. 维护并完善硬件产品对外知识库（产品介绍、核心卖点、FAQ、使用说明、销售话术、培训材料等），探索AI辅助优化产品侧日常运营流程。","requirements":"1. 本科及以上学历，市场营销、工商管理、工业设计、电子信息等相关专业优先。\n2. 3 年以上产品运营、用户运营或相关岗位经验，有消费电子、智能硬件行业背景者优先。\n3. 具备较强的用户洞察能力，能够从访谈、调研、数据分析和一线反馈中发现真实问题。\n4. 具备良好的数据分析能力和逻辑思考能力，熟练使用数据分析工具，具备数据驱动的决策习惯。熟练使用 AI 大模型（如 ChatGPT、Kimi、豆包等）及相关 AI 工具，能够将大模型融入 VOC 分析、内容生成等日常工作流，有实际 AI 提效经验。\n5. 具备较强的沟通能力、文字表达能力和内容生产能力，能够独立产出产品文案、调研报告、运营复盘和营销宣传内容。","description":"部门介绍\n美团的使命是“帮大家吃得更好，生活更好”，公司聚焦“零售 + 科技”战略，和广大商户与各类合作伙伴一起，努力为消费者提供品质生活，推动商品零售和服务零售在需求侧和供给侧的数字化转型。\n2018年9月20日，美团正式在港交所挂牌上市。美团将始终坚持以客户为中心，不断加大在科技研发方面的投入，更好承担社会责任，更多创造社会价值，与广大合作伙伴一起发展共赢。\n\n岗位职责\n1. 搭建并维护产品 VOC（Voice of Customer）体系，运用 AI 大模型对海量用户反馈进行智能分类、情感分析和趋势洞察，结合客服工单、社媒舆情、售后维修、一线销售等多渠道数据，自动化输出问题诊断报告和优化建议。\n2. 设计并执行用户调研，包括问卷设计、客户访谈、实地调研等，覆盖新品定义、上市验证、迭代优化等不同阶段。运用 AI 辅助工具提升调研效率，如 AI 辅助问卷生成、访谈纪要自动整理、用户画像智能分析，持续挖掘真实用户需求和使用痛点。\n3. 负责硬件产品营销内容产出，包括卖点提炼、宣传图文、短视频、销售材料等。探索 AI 辅助内容生成、创意迭代和效果测试，提升内容生产效率和传播转化率。\n4. 跟踪行业信息和动态，包括政策、市场趋势、用户评价等。利用 AI 工具实现信息自动抓取、用户评价批量分析和市场趋势智能洞察，定期沉淀分析结论，为产品规划提供决策依据。\n5. 维护并完善硬件产品对外知识库（产品介绍、核心卖点、FAQ、使用说明、销售话术、培训材料等），探索AI辅助优化产品侧日常运营流程。\n\n岗位基本要求\n1. 本科及以上学历，市场营销、工商管理、工业设计、电子信息等相关专业优先。\n2. 3 年以上产品运营、用户运营或相关岗位经验，有消费电子、智能硬件行业背景者优先。\n3. 具备较强的用户洞察能力，能够从访谈、调研、数据分析和一线反馈中发现真实问题。\n4. 具备良好的数据分析能力和逻辑思考能力，熟练使用数据分析工具，具备数据驱动的决策习惯。熟练使用 AI 大模型（如 ChatGPT、Kimi、豆包等）及相关 AI 工具，能够将大模型融入 VOC 分析、内容生成等日常工作流，有实际 AI 提效经验。\n5. 具备较强的沟通能力、文字表达能力和内容生产能力，能够独立产出产品文案、调研报告、运营复盘和营销宣传内容。\n\n具备以下条件优先\n1. 有完整参与或主导一款硬件产品从用户研究、产品定义、上市推广到运营复盘的经验。\n2. 有客户访谈、NPS 分析、满意度调研、用户旅程地图、服务蓝图、需求分析等相关经验。\n3. 有 AI 大模型（ChatGPT/Kimi/豆包/Claude）在 VOC 智能分析、用户访谈纪要整理、需求分析、内容生成等场景的实战经验，能独立设计 AI 工作流并落地提效。\n\n岗位亮点\nAI + 硬件运营的前沿实践：在美团\"AI at Work\"的文化下，你将系统性地把 AI 大模型融入硬件产品运营的每个环节——从 VOC 智能分析到 AI 辅助用户调研、营销内容生成等。这不是\"会用 Chatbot\"，而是真正用 AI 改变工作方式的实践场。同时，你将参与产品从立项、上市到迭代退出的全生命周期运营，积累硬件产品运营的完整方法论，为走向产品方向打下扎实基础。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4607539149","sourceKey":"meituan_social","company":"美团","title":"美团骑行-资管片区经理-南宁","city":"南宁市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4607539149&jobShareType=1","duty":"岗位职责:\n1.负责所辖区域运营资源供给保障及仓库管理，支撑管辖区域经营目标的达成；\n2.执行落地相关管理要求及流程标准；\n3.对资产/作业/现场等的各场景下的安全管理工作进行体系化建设，防范和处理风险；\n4.管理和培养团队，持续提升团队现场管理能力和作业效率。","requirements":"岗位要求:\n1.本科及以上学历，具有3年以上团队管理经验，有相关物流仓储工作经验优先；\n2.具有较强的人际交往能力和应变能力；\n3.熟悉基本电脑办公软件，有良好的数据分析和提炼能力，有AI应用和落地项目可加分；\n4.具有强烈的责任感，学习能力强，吃苦耐劳，认可公司绿色出行与共享理念。","description":"部门介绍\n美团骑行事业部在全国各个城市开展美团单车、电单车业务，提供绿色、便捷的共享出行服务，是美团出行板块重要的组成部分。我们力求为城市可持续发展提供低碳智能的解决方案，通过技术创新和硬件升级，不断优化全流程骑行体验，为低碳出行提供更好的服务。其中，美团单车旨在为城市居民提供通勤接驳服务，满足用户短途接驳出行需求；美团电单车则满足用户中短途多场景低碳出行需求。\n我们有开放的工作氛围，也有充满韧劲和创造力，心系低碳出行的伙伴。加入我们，一起为用户创造更好的出行体验。\n\n岗位职责\n岗位职责:\n1.负责所辖区域运营资源供给保障及仓库管理，支撑管辖区域经营目标的达成；\n2.执行落地相关管理要求及流程标准；\n3.对资产/作业/现场等的各场景下的安全管理工作进行体系化建设，防范和处理风险；\n4.管理和培养团队，持续提升团队现场管理能力和作业效率。\n\n岗位基本要求\n岗位要求:\n1.本科及以上学历，具有3年以上团队管理经验，有相关物流仓储工作经验优先；\n2.具有较强的人际交往能力和应变能力；\n3.熟悉基本电脑办公软件，有良好的数据分析和提炼能力，有AI应用和落地项目可加分；\n4.具有强烈的责任感，学习能力强，吃苦耐劳，认可公司绿色出行与共享理念。\n\n岗位亮点\n作为业务内超大体量城市，可锻炼高模糊度和高复杂度。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4230089276","sourceKey":"meituan_social","company":"美团","title":"企业级Agent解决方案产品经理","city":"北京市/上海市/成都市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4230089276&jobShareType=1","duty":"1. 负责企业级Agent解决方案的产品规划、需求分析与功能设计，推动产品从0到1的落地及持续迭代。  \n2. 深入理解企业客户在智能化、自动化场景中的痛点，结合AI技术趋势，输出具备市场竞争力的产品方案。  \n3. 协同研发、算法、运营等多团队，制定产品 roadmap，确保项目按时高质量交付。  \n4. 跟踪产品上线后的数据表现与用户反馈，持续优化产品体验与商业价值。","requirements":"1. 大学本科及以上学历，计算机、信息管理或相关专业优先。  \n2. 5年以上产品经理经验，有企业级SaaS、AI产品、知识库、向量数据库以及Agent相关产品背景者优先。  \n3. 具备优秀的逻辑思维、沟通表达与跨团队协作能力，能推动复杂项目落地。  \n4. 熟悉企业级产品生命周期管理，具备较强的数据分析与用户洞察能力。","description":"部门介绍\n美团餐饮系统为餐饮企业提供一站式IT解决方案，帮助餐饮商户实现从供应链管理、生产管理、前厅管理到外卖的数字化经营。美团餐饮系统不仅打通了餐厅和平台，更帮助餐厅连接客人，让商户更了解顾客需求，在帮助商户做商业决策的同时给顾客带来更好的消费体验。\n我们持续建设和提升产研、销售、服务的核心能力，通过全新升级的美团餐饮系统一体化软硬件产品，助力餐饮商户进行线上化经营，帮助商户在推广新店、提升效率、降低成本、会员营销、流量扶持、智慧选址、供应链管理等方面强化经营能力。团队汇集了餐饮和SaaS领域的优秀人才，秉持着“以客户为中心”的初心和“长期有耐心”的耕耘精神，求真、敬畏、敢于自我否定、善于快速学习。期待同样愿意长期致力于餐饮产业数字化、智能化的你加入我们的团队，共同进步共同成长！\n\n岗位职责\n1. 负责企业级Agent解决方案的产品规划、需求分析与功能设计，推动产品从0到1的落地及持续迭代。  \n2. 深入理解企业客户在智能化、自动化场景中的痛点，结合AI技术趋势，输出具备市场竞争力的产品方案。  \n3. 协同研发、算法、运营等多团队，制定产品 roadmap，确保项目按时高质量交付。  \n4. 跟踪产品上线后的数据表现与用户反馈，持续优化产品体验与商业价值。\n\n岗位基本要求\n1. 大学本科及以上学历，计算机、信息管理或相关专业优先。  \n2. 5年以上产品经理经验，有企业级SaaS、AI产品、知识库、向量数据库以及Agent相关产品背景者优先。  \n3. 具备优秀的逻辑思维、沟通表达与跨团队协作能力，能推动复杂项目落地。  \n4. 熟悉企业级产品生命周期管理，具备较强的数据分析与用户洞察能力。\n\n具备以下条件优先\n有企业级agent项目落地、有向量数据库或知识库基础建设经验优先\n\n岗位亮点\n1. 参与前沿AI Agent技术在企业场景中的创新应用，推动行业智能化升级。  \n2. 与优秀技术团队深度合作，快速提升AI产品化与商业化能力。  \n3. 工作地点灵活，支持北京、上海、成都多地办公，提供广阔的职业发展空间。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4423717903","sourceKey":"meituan_social","company":"美团","title":"CodeAgent AI工程师","city":"北京市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4423717903&jobShareType=1","duty":"- 负责 Code Agent 一个或多个核心模块（规划推理 / 执行沙盒 / 评测数据 / 数据合成）的设计与实现，对成功率、稳定性、吞吐这几个核心指标负责\n- 把真实研发场景里的难题拆开，给出能落地、能迭代的方案，一直跟到上线\n- 和算法、工程、产品团队一起，把方案从原型做到规模化上线，对线上交付质量负责\n- （高职级）定技术方向和架构选型，做关键技术决策，带团队啃下核心技术难题\n\n两条工作主线\n- 建一套统一访问体系的沙盒 PaaS 平台，给各类 env 提供环境管理、资源调度、env scale 能力，支撑复杂环境 agent 的评测、训练、数据合成；提升沙盒调度和路由支持规模量级：沙盒并行规模做到 1000 万，创建吞吐 100 万 RPM，网关转发吞吐做到 1000 万 RPM\n- 建统一的 agentic 数据合成框架和镜像合成系统，给 CodeAgent 方向的蒸馏数据生产、RL 训练、模型评测提供稳定可靠的工程基座\n\n另外，也接受在下面单一方向深耕：\n算法方向：做任务分解和工具调用框架，搞大仓库检索、长上下文压缩与记忆，用 SFT/RL（含执行反馈奖励）把任务成功率提上去\n工程方向：建代码执行沙盒（隔离、编排、并发调度），啃构建加速和依赖缓存，做运行时可观测性和失败诊断回放\n评测方向：建贴近真实的评测集和 benchmark，做端到端质检和效果度量，搭\"采集—清洗—标注—反哺训练\"的数据闭环","requirements":"- 本科及以上学历，计算机相关专业\n- 工程 / 算法基础扎实，至少一门主力语言用得熟（Python / Go / Java / TypeScript 等）\n- 做过从 0 到 1 交付复杂系统或模型的完整项目，能独立扛下一个模块的设计和落地\n- 对 Code Agent / LLM 应用有真实理解，能快速跟进并复现前沿工作","description":"部门介绍\n基础研发平台是美团的核心技术平台，立足于“零售+科技”的战略定位，通过打造人工智能、大数据、云计算、安全等核心技术能力，以及研发效能平台、企业应用平台等公共服务，为业务提供稳定安全、扩展易用、技术领先的平台技术和产品服务。\n在这里，我们会参与到最前沿的技术研发和探索；能够接触超规模集群、海量数据，挑战高复杂业务场景，有机会与业界一流的工程师一起并肩前行。\n在这里，我们有超强的技术氛围，持续向社区贡献业界实践，加速行业技术发展；我们有完善的互联网学习生态圈，重视底层逻辑和方法论，助力职业生涯的非线性成长。\n真诚地邀请你，和我们一起驱动技术发展，创造行业价值。\n\n岗位职责\n- 负责 Code Agent 一个或多个核心模块（规划推理 / 执行沙盒 / 评测数据 / 数据合成）的设计与实现，对成功率、稳定性、吞吐这几个核心指标负责\n- 把真实研发场景里的难题拆开，给出能落地、能迭代的方案，一直跟到上线\n- 和算法、工程、产品团队一起，把方案从原型做到规模化上线，对线上交付质量负责\n- （高职级）定技术方向和架构选型，做关键技术决策，带团队啃下核心技术难题\n\n两条工作主线\n- 建一套统一访问体系的沙盒 PaaS 平台，给各类 env 提供环境管理、资源调度、env scale 能力，支撑复杂环境 agent 的评测、训练、数据合成；提升沙盒调度和路由支持规模量级：沙盒并行规模做到 1000 万，创建吞吐 100 万 RPM，网关转发吞吐做到 1000 万 RPM\n- 建统一的 agentic 数据合成框架和镜像合成系统，给 CodeAgent 方向的蒸馏数据生产、RL 训练、模型评测提供稳定可靠的工程基座\n\n另外，也接受在下面单一方向深耕：\n算法方向：做任务分解和工具调用框架，搞大仓库检索、长上下文压缩与记忆，用 SFT/RL（含执行反馈奖励）把任务成功率提上去\n工程方向：建代码执行沙盒（隔离、编排、并发调度），啃构建加速和依赖缓存，做运行时可观测性和失败诊断回放\n评测方向：建贴近真实的评测集和 benchmark，做端到端质检和效果度量，搭\"采集—清洗—标注—反哺训练\"的数据闭环\n\n岗位基本要求\n- 本科及以上学历，计算机相关专业\n- 工程 / 算法基础扎实，至少一门主力语言用得熟（Python / Go / Java / TypeScript 等）\n- 做过从 0 到 1 交付复杂系统或模型的完整项目，能独立扛下一个模块的设计和落地\n- 对 Code Agent / LLM 应用有真实理解，能快速跟进并复现前沿工作\n\n具备以下条件优先\n- 算法：做过 LLM 微调 / RLHF·RLAIF / Agent 框架 / 检索增强 / 长上下文，有 tool-use 或 planning 的实战经验\n- 工程：熟悉容器沙盒隔离、分布式调度、主流构建系统（Gradle/Maven/Bazel 等）、网络proxy与缓存、高并发治理\n- 评测：做过 benchmark 设计、评测 harness、数据标注清洗流水线、指标体系\n- 做过 SWE-bench 类任务、AI 编程产品或开发者工具的落地\n- 有活跃的开源贡献、有影响力的技术项目或论文\n\n岗位亮点\n- 算法、工程、评测三条线不设墙，想钻深一条也行，想做复合型也行\n- 加入美团自研模型团队，建设的沙盒系统深度融入自研模型强化训练、数据合成、agent评测等核心流程，更有开源项目贡献和顶会论文发布机会，打造业界个人影响力。\n- 深入剖析和探索探索大模型的能力边界，追踪业界进展，站在大模型业界的最前沿。\n- 团队保障充足的计算资源，第一时间接触使用业界的模型，并推动美团自研大模型研究进展。\n- 沙盒系统建设挑战大（如何用统一接口承载多种不同隔离级别的执行环境；如何让海量环境镜像做到加载快、启动快、复用高；如何在高并发下实现高密度、低成本、强隔离；如何让 Agent 执行过程具备轨迹可追踪、任务可恢复、结果可复现的能力）","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4549855633","sourceKey":"meituan_social","company":"美团","title":"酒店连锁客户战略合作岗","city":"上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4549855633&jobShareType=1","duty":"1. 负责国际国内头部酒店连锁客户的商务拓展与维护，制定并执行大客户销战略合作策略。  \n2. 深度挖掘客户需求，推动定制化解决方案的落地，提升客户满意度与合作粘性。  \n3. 能够结合AI应用高效整理酒店连锁客户知识库、经营分析、市场洞察、生成解决方案。\n4. 定期分析市场趋势与竞争对手动态，输出行业洞察报告，优化商务策略。  \n5. 具备良好的项目管理能力，协调内部资源确保项目高效推进与合同顺利签署。\n5. 完成公司下达的业绩指标，持续扩大市场份额与收入规模。","requirements":"1. 大学本科及以上学历，市场营销、商务管理或相关专业优先。  \n2. 具备8年以上大客户销售或商务拓展经验，有酒店连锁、OTA等合作背景者优先。  \n3. 出色的沟通谈判能力与跨文化商务交流能力，英语流利。  \n4. 具备较强的数据分析能力与商业敏感度，能够灵活应用AI工具高效工作。\n5. 工作城市为上海市，能适应高频次出差与高强度工作压力。","description":"部门介绍\n美团酒店旅行业务涵盖酒店、民宿、机票、火车票、旅游度假、景点门票等各类住行游品类，通过与产业上下游的深度合作，为用户提供美好的旅游旅行体验。我们积极打造AI友好型组织，使用AI等新技术提升旅游服务的供需匹配效率，更好满足用户个性化、多样化的出游需求。我们持续深耕产业链，用数字化服务助力实体商家高质量经营，探索自有品牌等供给新模式，打造健康的商家生态，保障用户服务体验。为满足用户日益增长的跨境旅行需求，我们将聚焦亚太区域，打造高品质的住宿、交通、游玩等服务矩阵。\n这里有多元的业务布局、持续的成长空间，无论是向往的远方还是眼前的工作，一路都是风景相伴。加入我们，共同为用户创造旅游旅行中的高光时刻！\n\n岗位职责\n1. 负责国际国内头部酒店连锁客户的商务拓展与维护，制定并执行大客户销战略合作策略。  \n2. 深度挖掘客户需求，推动定制化解决方案的落地，提升客户满意度与合作粘性。  \n3. 能够结合AI应用高效整理酒店连锁客户知识库、经营分析、市场洞察、生成解决方案。\n4. 定期分析市场趋势与竞争对手动态，输出行业洞察报告，优化商务策略。  \n5. 具备良好的项目管理能力，协调内部资源确保项目高效推进与合同顺利签署。\n5. 完成公司下达的业绩指标，持续扩大市场份额与收入规模。\n\n岗位基本要求\n1. 大学本科及以上学历，市场营销、商务管理或相关专业优先。  \n2. 具备8年以上大客户销售或商务拓展经验，有酒店连锁、OTA等合作背景者优先。  \n3. 出色的沟通谈判能力与跨文化商务交流能力，英语流利。  \n4. 具备较强的数据分析能力与商业敏感度，能够灵活应用AI工具高效工作。\n5. 工作城市为上海市，能适应高频次出差与高强度工作压力。\n\n具备以下条件优先\n英语好、AI应用程度熟练、对酒店行业有较好经验\n\n岗位亮点\n1. 直接对接国内外知名酒店连锁品牌，积累高端客户资源与行业影响力。  \n2. 提供具有市场竞争力的薪酬体系与完善的职业发展通道。  \n3. 扁平化管理模式，鼓励创新与跨部门协作。  \n4. 定期参与国际行业峰会与培训，提升专业视野与综合能力。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4618067709","sourceKey":"meituan_social","company":"美团","title":"商业化运营","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4618067709&jobShareType=1","duty":"1、渠道策略运营：根据业务目标拆解充电宝智惠屏运营计划,推动月度/季度铺设任务达成；\n2、合作商管理：对接并维护充电宝合作商、品牌方等合作渠道，推动合作商完成门店落实与设备激活，确保点位铺设进度达标;\n3、跨部门协同推动：与广告、硬件交付、系统研发等团队保持密切协作,确保点位铺设与广告招商、系统能力建设的节奏匹配。","requirements":"1、沟通与谈判能力：具备优秀的商务谈判技巧和跨部门协调能力，擅长利益点设计与政策包装，能高效推动合作商及内部团队协同作业。\n2、结果导向：目标感强，具备独立完成从沟通到落地全流程的能力。\n3、适应力：能接受高频次的线下走访与出差，具备在复杂场景下解决实际问题的能力。","description":"部门介绍\n美团充电宝是服务零售中的共享租赁业务，承接美团使命，致力让大家充电更简单。美团充电宝业务以应急充电功能为服务核心，覆盖吃喝玩乐生活全场景。目前，已在全国超过2000多个城市的餐饮、娱乐、机场、地铁、火车站、医院、学校、景区等公共区域及场所提供充电服务，铺设机柜超过百万，有KA、直营、渠道合作商多种业务模式，随时随地保障和满足消费者的充电需求。我们的业务资产数量多、场景多元化，追求精益管理。我们的团队大咖云集，崇尚自主驱动，求真务实。我们正处在快速发展期，规模持续增长，目标是市场规模和利润水平双第一。我们的管理者关注团队每个成员的成长，为每个人提供适合自身发展的机会。广阔天地、大有作为，美团充电宝期待你的加入！\n\n岗位职责\n1、渠道策略运营：根据业务目标拆解充电宝智惠屏运营计划,推动月度/季度铺设任务达成；\n2、合作商管理：对接并维护充电宝合作商、品牌方等合作渠道，推动合作商完成门店落实与设备激活，确保点位铺设进度达标;\n3、跨部门协同推动：与广告、硬件交付、系统研发等团队保持密切协作,确保点位铺设与广告招商、系统能力建设的节奏匹配。\n\n岗位基本要求\n1、沟通与谈判能力：具备优秀的商务谈判技巧和跨部门协调能力，擅长利益点设计与政策包装，能高效推动合作商及内部团队协同作业。\n2、结果导向：目标感强，具备独立完成从沟通到落地全流程的能力。\n3、适应力：能接受高频次的线下走访与出差，具备在复杂场景下解决实际问题的能力。\n\n具备以下条件优先\n有大客户运营或渠道管理经验优先\n\n岗位亮点\n1、亲历创新业务的规模化扩张过程，积累稀缺的商业化运营经验。\n2、清晰的成长路径，项目正处于加速期。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4566998937","sourceKey":"meituan_social","company":"美团","title":"Agent工程师（商业智能）","city":"北京市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4566998937&jobShareType=1","duty":"1.面向美团以及生态相关方真实商业经营场景（经营分析、营销投放、销售拓展、商业变现等），构建可用自主智能体，操盘营销预算、服务广大商户、支持数万员工。\n2.参与商业经营新范式构建与定义，同时追踪大模型与智能体前沿技术，探索其在上述场景的创新应用，以技术驱动业务增长。\n3.负责应用场景下智能体框架核心能力建设，重点包括 Agent Loop 编排、上下文工程、长期记忆系统、多 Agent 协同、工具调用协议、推理成本控制与执行可靠性，安全机制。\n4.负责 Agent 评测体系与数据闭环建设，覆盖执行成功率、幻觉率、Token 消耗、上下文漂移等核心指标，驱动系统持续优化。","requirements":"1.计算机、人工智能或相关专业本科及以上学历。\n2. 具备大模型或智能体相关工程开发经验，理解 LLM 底层工作机制与 Agent 系统核心组件\n3.对主流开源 Agent 框架有源码阅读与使用经验，能从架构层面分析其设计取舍。以下为典型参考（需至少深入过 2-3 个）：\n典型框架：Claude Code / Agent SDK、OpenAI Agents SDK / Codex、CrewAI、LangGraph、OpenClaw、Hermes、Dify / Mastra / Nanobot 等\n关注机制：Agentic Loop、上下文工程与压缩策略、多 Agent 协作与委托、记忆系统（短期/长期）、闭环自进化能力、Observability / Tracing、Human-in-the-loop 审批机制、Skill 体系与工具编排、状态持久化与断点续跑、Sandbox 安全执行 等\n4. 具备良好的逻辑思维与沟通能力，能够独立完成技术方案设计并推动落地。","description":"部门介绍\n基础研发平台是美团的核心技术平台，立足于“零售+科技”的战略定位，通过打造人工智能、大数据、云计算、安全等核心技术能力，以及研发效能平台、企业应用平台等公共服务，为业务提供稳定安全、扩展易用、技术领先的平台技术和产品服务。\n在这里，我们会参与到最前沿的技术研发和探索；能够接触超规模集群、海量数据，挑战高复杂业务场景，有机会与业界一流的工程师一起并肩前行。\n在这里，我们有超强的技术氛围，持续向社区贡献业界实践，加速行业技术发展；我们有完善的互联网学习生态圈，重视底层逻辑和方法论，助力职业生涯的非线性成长。\n真诚地邀请你，和我们一起驱动技术发展，创造行业价值。\n\n岗位职责\n1.面向美团以及生态相关方真实商业经营场景（经营分析、营销投放、销售拓展、商业变现等），构建可用自主智能体，操盘营销预算、服务广大商户、支持数万员工。\n2.参与商业经营新范式构建与定义，同时追踪大模型与智能体前沿技术，探索其在上述场景的创新应用，以技术驱动业务增长。\n3.负责应用场景下智能体框架核心能力建设，重点包括 Agent Loop 编排、上下文工程、长期记忆系统、多 Agent 协同、工具调用协议、推理成本控制与执行可靠性，安全机制。\n4.负责 Agent 评测体系与数据闭环建设，覆盖执行成功率、幻觉率、Token 消耗、上下文漂移等核心指标，驱动系统持续优化。\n\n岗位基本要求\n1.计算机、人工智能或相关专业本科及以上学历。\n2. 具备大模型或智能体相关工程开发经验，理解 LLM 底层工作机制与 Agent 系统核心组件\n3.对主流开源 Agent 框架有源码阅读与使用经验，能从架构层面分析其设计取舍。以下为典型参考（需至少深入过 2-3 个）：\n典型框架：Claude Code / Agent SDK、OpenAI Agents SDK / Codex、CrewAI、LangGraph、OpenClaw、Hermes、Dify / Mastra / Nanobot 等\n关注机制：Agentic Loop、上下文工程与压缩策略、多 Agent 协作与委托、记忆系统（短期/长期）、闭环自进化能力、Observability / Tracing、Human-in-the-loop 审批机制、Skill 体系与工具编排、状态持久化与断点续跑、Sandbox 安全执行 等\n4. 具备良好的逻辑思维与沟通能力，能够独立完成技术方案设计并推动落地。\n\n具备以下条件优先\n1.在 AIBD、营销系统、智能客服、企业办公等场景的 Agent 实践应用经验。\n2.有 Agent 框架的二次开发或深度定制经验（如记忆系统设计、Agent Loop 改造、Multi-Agent 编排、Tool 协议扩展等）。\n3.深度使用 Claude Code、OpenClaw 等 AI Agent 产品，是 Agent 的高强度用户，对模型行为有品味有判断力。\n4.有 Agent Eval 平台、轨迹回放、可观测性工具的开发经验，熟悉 Loop Engineering、Harness Engineering 系统调优，具备工程与模型联合优化能力。\n5.能够结合业务需求进行技术选型和方案设计，对业务和用户有主动思考，具备良好的项目管理能力、沟通协调能力和解决问题的能力。\n\n岗位亮点\n1. AI-Native 的工作范式：不仅是需求承接方，更有独立负责真实业务机会，扁平化管理、决策高效直达，打破组织壁垒、高信息密度透传。\n2. 成长空间与影响力：技术深度与业务广度兼具——既能深耕前沿 Agent 架构，也能看到技术如何一步步变成产品、改变真实物理世界。\n3. 团队创新和技术氛围浓厚，扁平开放，鼓励技术分享与创新探索，给予充足创新场景的试错空间。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4136761943","sourceKey":"meituan_social","company":"美团","title":"大模型和智能体应用算法(AIBD方向)","city":"北京市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4136761943&jobShareType=1","duty":"美团基础研发平台，作为公司的核心技术平台，致力于“零售+科技”的战略发展。我们专注于智能体构建、大模型推理、多模态训练等核心技术，并通过FRIDAY模型工厂与应用工厂，为业务提供稳定、安全、易扩展与技术先进的平台技术和技术能力。我们聚焦于大模型和智能体的前沿算法研究和应用落地，致力于将先进的人工智能技术转化为实际的业务价值。 我们真诚邀请你加入我们，共同推动技术发展，创造行业价值。\n     \n1.负责大模型与智能体应用优化及落地，迭代面向商家与销售的 OpenClaw 智能体系统，聚焦 AIBD 领域技术创新。\n2.协同产品与工程团队，驱动算法方案在真实场景中的规模化部署。\n3.追踪大模型与智能体前沿技术，探索并实践业务场景下的创新应用","requirements":"1. 计算机、人工智能或相关专业本科及以上学历。  \n2. 具备2年以上大模型或智能体相关算法开发经验，熟悉主流大模型架构与应用方法。  \n3. 熟练掌握Python，具备扎实的算法与数据结构基础，有PyTorch或TensorFlow实战经验。  \n4. 具备良好的逻辑思维与沟通能力，能够独立完成技术方案设计并推动落地。","description":"部门介绍\n基础研发平台是美团的核心技术平台，立足于“零售+科技”的战略定位，通过打造人工智能、大数据、云计算、安全等核心技术能力，以及研发效能平台、企业应用平台等公共服务，为业务提供稳定安全、扩展易用、技术领先的平台技术和产品服务。\n在这里，我们会参与到最前沿的技术研发和探索；能够接触超规模集群、海量数据，挑战高复杂业务场景，有机会与业界一流的工程师一起并肩前行。\n在这里，我们有超强的技术氛围，持续向社区贡献业界实践，加速行业技术发展；我们有完善的互联网学习生态圈，重视底层逻辑和方法论，助力职业生涯的非线性成长。\n真诚地邀请你，和我们一起驱动技术发展，创造行业价值。\n\n岗位职责\n美团基础研发平台，作为公司的核心技术平台，致力于“零售+科技”的战略发展。我们专注于智能体构建、大模型推理、多模态训练等核心技术，并通过FRIDAY模型工厂与应用工厂，为业务提供稳定、安全、易扩展与技术先进的平台技术和技术能力。我们聚焦于大模型和智能体的前沿算法研究和应用落地，致力于将先进的人工智能技术转化为实际的业务价值。 我们真诚邀请你加入我们，共同推动技术发展，创造行业价值。\n     \n1.负责大模型与智能体应用优化及落地，迭代面向商家与销售的 OpenClaw 智能体系统，聚焦 AIBD 领域技术创新。\n2.协同产品与工程团队，驱动算法方案在真实场景中的规模化部署。\n3.追踪大模型与智能体前沿技术，探索并实践业务场景下的创新应用\n\n岗位基本要求\n1. 计算机、人工智能或相关专业本科及以上学历。  \n2. 具备2年以上大模型或智能体相关算法开发经验，熟悉主流大模型架构与应用方法。  \n3. 熟练掌握Python，具备扎实的算法与数据结构基础，有PyTorch或TensorFlow实战经验。  \n4. 具备良好的逻辑思维与沟通能力，能够独立完成技术方案设计并推动落地。\n\n具备以下条件优先\n1. 具备大模型在AIBD、智能客服、企业办公、商家和个人助理等场景的应用经验。\n2. 能够结合业务需求进行技术选型和方案设计，对业务和用户有主动思考。\n3. 具备良好的项目管理能力、沟通协调能力和解决问题的能力。\n\n岗位亮点\n1. 参与前沿AI技术在实际业务中的深度应用，推动技术价值转化。\n2. 与高水平技术团队共同成长，业务技术挑战性强。\n3. 团队技术氛围浓厚，鼓励技术创新与知识分享。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4419477550","sourceKey":"meituan_social","company":"美团","title":"充电宝大客户经理-餐饮场景","city":"上海市/成都市/北京市/郑州市/广州市/深圳市/厦门市/杭州市/武汉市/西安市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4419477550&jobShareType=1","duty":"1. 负责充电宝业务在餐饮场景下的市场拓展与大客户开发，制定并执行销售策略，完成业绩目标。  \n2. 深度挖掘餐饮连锁品牌需求，建立并维护长期合作关系，推动项目落地与续约。  \n3. 协调内部资源，包括产品、运营、技术等团队，确保客户需求高效响应与解决方案顺利实施。  \n4. 分析餐饮行业趋势与行业动态，输出市场洞察报告，优化业务模式与客户服务体系。","requirements":"1. 大学本科及以上学历，5年以上大客户销售或业务开发经验，有本地生活服务、共享充电宝或餐饮行业背景优先。  \n2. 具备优秀的商务谈判能力与客户关系管理能力，能独立开拓并管理高价值客户。  \n3. 熟悉餐饮行业生态，具备较强的市场敏感度与数据分析能力。  \n4. 工作城市为上海市、成都市、北京市、郑州市、广州市、深圳市、厦门市，能适应高频次出差。","description":"部门介绍\n美团充电宝是服务零售中的共享租赁业务，承接美团使命，致力让大家充电更简单。美团充电宝业务以应急充电功能为服务核心，覆盖吃喝玩乐生活全场景。目前，已在全国超过2000多个城市的餐饮、娱乐、机场、地铁、火车站、医院、学校、景区等公共区域及场所提供充电服务，铺设机柜超过百万，有KA、直营、渠道合作商多种业务模式，随时随地保障和满足消费者的充电需求。我们的业务资产数量多、场景多元化，追求精益管理。我们的团队大咖云集，崇尚自主驱动，求真务实。我们正处在快速发展期，规模持续增长，目标是市场规模和利润水平双第一。我们的管理者关注团队每个成员的成长，为每个人提供适合自身发展的机会。广阔天地、大有作为，美团充电宝期待你的加入！\n\n岗位职责\n1. 负责充电宝业务在餐饮场景下的市场拓展与大客户开发，制定并执行销售策略，完成业绩目标。  \n2. 深度挖掘餐饮连锁品牌需求，建立并维护长期合作关系，推动项目落地与续约。  \n3. 协调内部资源，包括产品、运营、技术等团队，确保客户需求高效响应与解决方案顺利实施。  \n4. 分析餐饮行业趋势与行业动态，输出市场洞察报告，优化业务模式与客户服务体系。\n\n岗位基本要求\n1. 大学本科及以上学历，5年以上大客户销售或业务开发经验，有本地生活服务、共享充电宝或餐饮行业背景优先。  \n2. 具备优秀的商务谈判能力与客户关系管理能力，能独立开拓并管理高价值客户。  \n3. 熟悉餐饮行业生态，具备较强的市场敏感度与数据分析能力。  \n4. 工作城市为上海市、成都市、北京市、郑州市、广州市、深圳市、厦门市，能适应高频次出差。\n\n具备以下条件优先\n1.具备熟练商务英语表达和书写能力者。\n2.具备AI思维在过往工作有成熟场景应用。\n\n岗位亮点\n1. 大而稳定的平台发展，参与核心业务拓展，成长空间广阔。  \n2. 直面头部餐饮品牌与连锁客户，积累高价值行业资源与人脉。  \n3. 扁平化管理，结果导向，具备竞争力的薪酬激励与晋升机制。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4131316359","sourceKey":"meituan_social","company":"美团","title":"零售物流方案","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4131316359&jobShareType=1","duty":"1、方案对接与出具：负责间采全品类（工程类、设备类、租赁类、消耗品类等）业务需求对接，对新采购模式、新合同结构进行财务影响评估，结合会计准则，结算规则，合规要求等，识别和判断业务活动对财务的关键影响，出具相应的财务解决方案（结算&核算）；\n2、财务风险管理：围绕资产负债表完整性、期间费用准确性、资金安全三个维度，建立间采财务风险识别与分层框架，完善风险监控体系，定期开展财务风险排查，输出风险敞口分析，推动业务侧配合整改，降低资损及财务合规风险；\n3、流程优化：参与采购流程设计，从财务视角提出流程和系统功能建议，推动风险前置，并与各方配合推进规划落地；\n4、其他：与采购、运营、法务、IT等职能横向协作，推动核算规则、付款流程、系统功能三位一体落地。","requirements":"1.本科及其以上学历，会计、经济、管理类等相关专业，5年及以上财会相关工作经验，其中至少3年聚焦于间接采购（间采）场景；\n2.熟练掌握常用办公软件的使用；\n3.扎实的会计准则基础，熟悉企业会计准则下固定资产、工程物资、租赁（第21号）、费用确认等相关科目处理规则，可以对复杂场景出具适当的会计判断；\n4.熟练的系统流程规划能力，可以对复杂场景出具适当的系统/流程建设方案；\n5.较强的分析能力、清晰的思维逻辑和创新意识，能够基于数据发现问题和解决问题；\n6.具备较强的沟通能力、协调能力，能主导项目开展，具备优秀的逻辑思维和分析能力。","description":"部门介绍\n财务平台负责公司整体和各业务层面的财务管理工作，通过建设专业、全面、复合的财务管理能力和与业务经营的紧密结合来支持公司健康发展。目前财务平台拥有财务会计、财务报告、资金管理、税务管理、财务共享、财务系统、规划分析、财务BP和内控内审等主要工作方向。我们的目标是建设业界一流的财务管理能力和经营支持体系，为公司战略的正确落地、投入效率的持续提升、业务价值的不断增长保驾护航。欢迎加入财务平台，携手一起向未来！\n\n岗位职责\n1、方案对接与出具：负责间采全品类（工程类、设备类、租赁类、消耗品类等）业务需求对接，对新采购模式、新合同结构进行财务影响评估，结合会计准则，结算规则，合规要求等，识别和判断业务活动对财务的关键影响，出具相应的财务解决方案（结算&核算）；\n2、财务风险管理：围绕资产负债表完整性、期间费用准确性、资金安全三个维度，建立间采财务风险识别与分层框架，完善风险监控体系，定期开展财务风险排查，输出风险敞口分析，推动业务侧配合整改，降低资损及财务合规风险；\n3、流程优化：参与采购流程设计，从财务视角提出流程和系统功能建议，推动风险前置，并与各方配合推进规划落地；\n4、其他：与采购、运营、法务、IT等职能横向协作，推动核算规则、付款流程、系统功能三位一体落地。\n\n岗位基本要求\n1.本科及其以上学历，会计、经济、管理类等相关专业，5年及以上财会相关工作经验，其中至少3年聚焦于间接采购（间采）场景；\n2.熟练掌握常用办公软件的使用；\n3.扎实的会计准则基础，熟悉企业会计准则下固定资产、工程物资、租赁（第21号）、费用确认等相关科目处理规则，可以对复杂场景出具适当的会计判断；\n4.熟练的系统流程规划能力，可以对复杂场景出具适当的系统/流程建设方案；\n5.较强的分析能力、清晰的思维逻辑和创新意识，能够基于数据发现问题和解决问题；\n6.具备较强的沟通能力、协调能力，能主导项目开展，具备优秀的逻辑思维和分析能力。\n\n具备以下条件优先\n具有互联网行业背景优先；有零售线下店、仓储物流等行业财务管理经验优先；CPA持证或具备四大会计师事务经验优先；有财务系统搭建、财务流程优化经验者优先。\n\n岗位亮点\n1、学习成长机会大：我们拥有众多的业态，在这里，你可以学习到不同复杂业态下的财务解决方案，带给你前所未有的成长速度；\n2、与行业内优秀的人共舞：我们拥有众多国内外知名企业的优秀人士，和优秀的人共事，让自己变得更加优秀；\n3、简单高效的团队氛围：我们注重结果导向，每个人都凭业绩说话，我们尊重专业，努力构造业界的财务标杆，同时，我们更加重视财务在业务中的价值体现。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4621251622","sourceKey":"meituan_social","company":"美团","title":"深圳-CKA商务专员","city":"深圳市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4621251622&jobShareType=1","duty":"1.深刻、全面的理解客户需求，协同相关部门制定服务方案，帮助客户更好进行服务规划、完成服务目标、提升服务满意度，从而提升美团公司品牌影响力；\n2.深入理解客户流程、决策的决策链和关键人；\n3.理解行业规律及市场空间，总结销售方法论；\n4.开拓中型大型客户、维护客户关系、建立长期的合作关系，对销售结果负责。","requirements":"1.三年以上客户销售经验，有食材客户销售经验者优先考虑；\n2.较强的沟通能力和同理心，能够和客户深入交流、赢得客户信任、获取客户需求、进行专业宣讲和方案引导；\n3.能够跟进客户需求制定销售策略；\n4.自我驱动、有创新意识、有激情、结果导向，具备良好的团队合作精神，以客户为中心，能组织、协调周边资源达成组织、项目的目标；\n5.较强的学习能力、适应性强、组织协调能力强。","description":"部门介绍\n快驴进货是美团旗下的餐饮供应链平台，帮助餐饮商户以更低成本、更高效率来获取安全可靠的食材供应，让餐饮采购更简单。快驴进货同步发展“自营+平台”的业务模式，在采购环节一方面向上游供应商直采大宗商品，另一方面引入各地批发商，助力平台伙伴共同发展；在销售环节既有自建团队进行市场、客户拓展，又帮助各地批发商拓展业务；同时自建仓储管理系统、配送网络与团队，为客户提供优质履约服务。\n截至2022年，快驴进货布局了全国41个城市，为百万家商户提供“全、省、稳、好”的餐饮供应链服务。我们拥有3000+品牌食材、超5万SKU商品、超28万商品资质，并提供源头严审核、食品安全严把关、24小时无忧售后的全面保障，实现手机下单、送货上门的高效采购模式，帮百万商家节省了采购时间与成本，助力平台伙伴共同发展，在万亿市场共享机遇。\n在这里，你将收获完善的员工发展机制及学习体系，与各界专家一起深度参与餐饮供应链业务的发展。欢迎优秀的你加入美团快驴进货，与我们一起成长，一起更好！\n\n岗位职责\n1.深刻、全面的理解客户需求，协同相关部门制定服务方案，帮助客户更好进行服务规划、完成服务目标、提升服务满意度，从而提升美团公司品牌影响力；\n2.深入理解客户流程、决策的决策链和关键人；\n3.理解行业规律及市场空间，总结销售方法论；\n4.开拓中型大型客户、维护客户关系、建立长期的合作关系，对销售结果负责。\n\n岗位基本要求\n1.三年以上客户销售经验，有食材客户销售经验者优先考虑；\n2.较强的沟通能力和同理心，能够和客户深入交流、赢得客户信任、获取客户需求、进行专业宣讲和方案引导；\n3.能够跟进客户需求制定销售策略；\n4.自我驱动、有创新意识、有激情、结果导向，具备良好的团队合作精神，以客户为中心，能组织、协调周边资源达成组织、项目的目标；\n5.较强的学习能力、适应性强、组织协调能力强。\n\n岗位亮点\n1.能够较快的建立销售技能及视野；\n2.加入快速成长的学习型团队，快速提升综合能力。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4636864729","sourceKey":"meituan_social","company":"美团","title":"长沙城市负责人","city":"长沙市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4636864729&jobShareType=1","duty":"1. 负责长沙地区商品与供应链的整体规划、运营及团队管理，确保供应链高效运转。  \n2. 制定并执行本地化采购策略，优化供应商结构，控制采购成本，保障商品质量与供应稳定性。  \n3. 带领3人团队完成日常采购、库存管理、物流配送及供应商关系维护等工作。  \n4. 监控市场动态与行业趋势，及时调整商品结构，提升区域竞争力与运营效率。  \n5. 协同总部及其他城市团队，推动跨区域协作与标准化流程落地。","requirements":"1. 大学专科及以上学历，具备5年以上商品与供应链管理或采购相关工作经验。  \n2. 熟悉快消品、零售或电商行业供应链运作模式，有城市级管理经验者优先。  \n3. 具备优秀的团队管理能力、沟通协调能力及数据分析能力。  \n4. 具备较强的统筹能力与执行力，能适应快节奏工作环境。  \n5. 工作地点在长沙市，能接受必要的出差安排。","description":"部门介绍\n快驴进货是美团旗下的餐饮供应链平台，帮助餐饮商户以更低成本、更高效率来获取安全可靠的食材供应，让餐饮采购更简单。快驴进货同步发展“自营+平台”的业务模式，在采购环节一方面向上游供应商直采大宗商品，另一方面引入各地批发商，助力平台伙伴共同发展；在销售环节既有自建团队进行市场、客户拓展，又帮助各地批发商拓展业务；同时自建仓储管理系统、配送网络与团队，为客户提供优质履约服务。\n截至2022年，快驴进货布局了全国41个城市，为百万家商户提供“全、省、稳、好”的餐饮供应链服务。我们拥有3000+品牌食材、超5万SKU商品、超28万商品资质，并提供源头严审核、食品安全严把关、24小时无忧售后的全面保障，实现手机下单、送货上门的高效采购模式，帮百万商家节省了采购时间与成本，助力平台伙伴共同发展，在万亿市场共享机遇。\n在这里，你将收获完善的员工发展机制及学习体系，与各界专家一起深度参与餐饮供应链业务的发展。欢迎优秀的你加入美团快驴进货，与我们一起成长，一起更好！\n\n岗位职责\n1. 负责长沙地区商品与供应链的整体规划、运营及团队管理，确保供应链高效运转。  \n2. 制定并执行本地化采购策略，优化供应商结构，控制采购成本，保障商品质量与供应稳定性。  \n3. 带领3人团队完成日常采购、库存管理、物流配送及供应商关系维护等工作。  \n4. 监控市场动态与行业趋势，及时调整商品结构，提升区域竞争力与运营效率。  \n5. 协同总部及其他城市团队，推动跨区域协作与标准化流程落地。\n\n岗位基本要求\n1. 大学专科及以上学历，具备5年以上商品与供应链管理或采购相关工作经验。  \n2. 熟悉快消品、零售或电商行业供应链运作模式，有城市级管理经验者优先。  \n3. 具备优秀的团队管理能力、沟通协调能力及数据分析能力。  \n4. 具备较强的统筹能力与执行力，能适应快节奏工作环境。  \n5. 工作地点在长沙市，能接受必要的出差安排。\n\n岗位亮点\n1. 担任城市负责人，拥有较高的决策权与成长空间。  \n2. 团队规模适中，管理聚焦，利于快速展现个人能力。  \n3. 公司提供完善的培训体系与职业发展通道。  \n4. 工作地点位于长沙核心区域，交通便利，办公环境优良。  \n5. 参与公司战略落地，积累跨区域、多项目协同经验。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4487152855","sourceKey":"meituan_social","company":"美团","title":"美团骑行-渠道经理-海南","city":"海口市/三亚市/儋州市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4487152855&jobShareType=1","duty":"1、对所辖城市群的电单车渠道合作商管理工作负责，承担经营过程和结果指标的任务达成；\n2、充分了解用户、市场等行业信息，制定有针对性的城市打法，并能够指导渠道运营落地，拿到结果；\n3、保持对政府的良好合作关系，进行必要的陪访，配合政策要求及时响应；\n4、与渠道合作商负责人建立良好客情，帮其分析车辆点位、调度规律，制定合理运营计划，以及给出收益管理和人员管理建议，不断推动合作伙伴投入资源达成运营任务并更加盈利；对商的选、育、励、汰负责；\n5、落地执行公司对商政策的上传下达，以及商的赋能工作。","requirements":"1、具备3年以上渠道开发、渠道管理经验，有共享出行、物流管理、快消行业经验者优先；\n2、学习能力强，对渠道管理模式有比较深刻的认知，能够激发合作商积极性，对管理合作商有一定方法论沉淀；\n3、商务沟通能力强，逻辑能力强，有良好的文字功底；\n4、热爱工作，接受挑战，有团队协作精神和较强的服务意识；价值观正，诚实，责任心强；\n5、大学本科以上学历，可接受出差；","description":"部门介绍\n美团骑行事业部在全国各个城市开展美团单车、电单车业务，提供绿色、便捷的共享出行服务，是美团出行板块重要的组成部分。我们力求为城市可持续发展提供低碳智能的解决方案，通过技术创新和硬件升级，不断优化全流程骑行体验，为低碳出行提供更好的服务。其中，美团单车旨在为城市居民提供通勤接驳服务，满足用户短途接驳出行需求；美团电单车则满足用户中短途多场景低碳出行需求。\n我们有开放的工作氛围，也有充满韧劲和创造力，心系低碳出行的伙伴。加入我们，一起为用户创造更好的出行体验。\n\n岗位职责\n1、对所辖城市群的电单车渠道合作商管理工作负责，承担经营过程和结果指标的任务达成；\n2、充分了解用户、市场等行业信息，制定有针对性的城市打法，并能够指导渠道运营落地，拿到结果；\n3、保持对政府的良好合作关系，进行必要的陪访，配合政策要求及时响应；\n4、与渠道合作商负责人建立良好客情，帮其分析车辆点位、调度规律，制定合理运营计划，以及给出收益管理和人员管理建议，不断推动合作伙伴投入资源达成运营任务并更加盈利；对商的选、育、励、汰负责；\n5、落地执行公司对商政策的上传下达，以及商的赋能工作。\n\n岗位基本要求\n1、具备3年以上渠道开发、渠道管理经验，有共享出行、物流管理、快消行业经验者优先；\n2、学习能力强，对渠道管理模式有比较深刻的认知，能够激发合作商积极性，对管理合作商有一定方法论沉淀；\n3、商务沟通能力强，逻辑能力强，有良好的文字功底；\n4、热爱工作，接受挑战，有团队协作精神和较强的服务意识；价值观正，诚实，责任心强；\n5、大学本科以上学历，可接受出差；\n\n岗位亮点\n良好的团队氛围，成长空间大，舒适的工作环境。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4644167398","sourceKey":"meituan_social","company":"美团","title":"小象超市-重庆水产品控主管","city":"重庆市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4644167398&jobShareType=1","duty":"1. 梳理水产养殖的各流程环节，建立标准操作流程和技术手册，梳理形成操作技术规范赋能到服务站团队进行使用，持续降低损耗率和死亡率；\n2. 跟踪活鲜养殖领域的核心技术，包括水产收货、养殖、制冷、供氧、过滤、海水配置、宰杀、配送等，并通过专业赋能公司；\n3. 通过日常巡店，不断完善操作流程和技术手册，定期对服务站培训输出，提升服务站团队运营能力；\n4. 具备兽残检测能力优先考虑，如：孔雀石绿、呋喃系列、氯霉素、磺胺类等。","requirements":"1.大专以上学历，熟悉水产供应链路，有水产管理经验或水产养殖相关工作经验；\n2.责任心强，有推动问题解决的魄力和担当；\n3.具备较好的跨部门沟通表达及协作能力，能有效沟通并达成一致，并推行落地；\n4.能主动跟进闭环管理数据分析异动，据指标并执行落地。有较强的质量管理方法论且可以快速结合业务特点落地能力；\n5.坚持正直诚信原则底线。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1. 梳理水产养殖的各流程环节，建立标准操作流程和技术手册，梳理形成操作技术规范赋能到服务站团队进行使用，持续降低损耗率和死亡率；\n2. 跟踪活鲜养殖领域的核心技术，包括水产收货、养殖、制冷、供氧、过滤、海水配置、宰杀、配送等，并通过专业赋能公司；\n3. 通过日常巡店，不断完善操作流程和技术手册，定期对服务站培训输出，提升服务站团队运营能力；\n4. 具备兽残检测能力优先考虑，如：孔雀石绿、呋喃系列、氯霉素、磺胺类等。\n\n岗位基本要求\n1.大专以上学历，熟悉水产供应链路，有水产管理经验或水产养殖相关工作经验；\n2.责任心强，有推动问题解决的魄力和担当；\n3.具备较好的跨部门沟通表达及协作能力，能有效沟通并达成一致，并推行落地；\n4.能主动跟进闭环管理数据分析异动，据指标并执行落地。有较强的质量管理方法论且可以快速结合业务特点落地能力；\n5.坚持正直诚信原则底线。\n\n具备以下条件优先\n有熟知活鲜水产行业，全球渔业生产分布，工业化活鲜养殖技术等。具有较强的快速学习能力以及解决问题能力。\n\n岗位亮点\n1. 加入快速发展的美团小象平台，参与核心品控环节。\n2. 接触多元生鲜品类，积累行业深度经验。\n3. 扁平化管理，直接对接业务核心团队。\n4. 提供系统化品控培训及职业发展支持。\n5. 候选人的才华将直接对行业产生影响。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:2920686242","sourceKey":"meituan_social","company":"美团","title":"充电宝渠道-渠道经理-湖北","city":"武汉市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=2920686242&jobShareType=1","duty":"1.负责充电宝渠道在下沉战区的拓展与管理，制定并执行渠道发展计划，完成销售目标。\n2.开发新的渠道合作伙伴，建立并维护与渠道合作伙伴的良好合作关系。\n3.监控渠道销售绩效，分析销售数据并提出改进措施，提升销售额和市场占有率。\n4.跟进渠道合作伙伴的运营情况，协助解决渠道合作伙伴的问题和困难。\n5.参与制定渠道价格政策和销售促销方案，确保渠道销售的可持续增长。\n6.跟踪市场动态和竞争对手，及时调整渠道策略，保持竞争优势。","requirements":"1.本科及以上学历，市场营销、商务管理等相关专业优先考虑。\n2.拥有相关行业渠道管理或销售经验，熟悉渠道市场运作规则和流程。\n3.具备良好的沟通、协调和团队合作能力，能够有效与内外部各方进行沟通和合作。\n4.具备较强的拓展能力和市场洞察力，能够迅速发现并把握市场机会。\n5.具备较强的数据分析和解决问题的能力，能够根据市场情况提出有效的销售策略和方案。\n6.具备良好的适应能力，能够适应快节奏的工作环境。","description":"部门介绍\n美团充电宝是服务零售中的共享租赁业务，承接美团使命，致力让大家充电更简单。美团充电宝业务以应急充电功能为服务核心，覆盖吃喝玩乐生活全场景。目前，已在全国超过2000多个城市的餐饮、娱乐、机场、地铁、火车站、医院、学校、景区等公共区域及场所提供充电服务，铺设机柜超过百万，有KA、直营、渠道合作商多种业务模式，随时随地保障和满足消费者的充电需求。我们的业务资产数量多、场景多元化，追求精益管理。我们的团队大咖云集，崇尚自主驱动，求真务实。我们正处在快速发展期，规模持续增长，目标是市场规模和利润水平双第一。我们的管理者关注团队每个成员的成长，为每个人提供适合自身发展的机会。广阔天地、大有作为，美团充电宝期待你的加入！\n\n岗位职责\n1.负责充电宝渠道在下沉战区的拓展与管理，制定并执行渠道发展计划，完成销售目标。\n2.开发新的渠道合作伙伴，建立并维护与渠道合作伙伴的良好合作关系。\n3.监控渠道销售绩效，分析销售数据并提出改进措施，提升销售额和市场占有率。\n4.跟进渠道合作伙伴的运营情况，协助解决渠道合作伙伴的问题和困难。\n5.参与制定渠道价格政策和销售促销方案，确保渠道销售的可持续增长。\n6.跟踪市场动态和竞争对手，及时调整渠道策略，保持竞争优势。\n\n岗位基本要求\n1.本科及以上学历，市场营销、商务管理等相关专业优先考虑。\n2.拥有相关行业渠道管理或销售经验，熟悉渠道市场运作规则和流程。\n3.具备良好的沟通、协调和团队合作能力，能够有效与内外部各方进行沟通和合作。\n4.具备较强的拓展能力和市场洞察力，能够迅速发现并把握市场机会。\n5.具备较强的数据分析和解决问题的能力，能够根据市场情况提出有效的销售策略和方案。\n6.具备良好的适应能力，能够适应快节奏的工作环境。\n\n具备以下条件优先\n1、充电宝渠道管理经验者优先。\n2、渠道管理工作经验优先。\n\n岗位亮点\n1.有机会在充电宝渠道下沉战区进行业务拓展和管理，挖掘市场潜力。\n2.可以参与制定并执行渠道发展计划，负责整个下沉战区的渠道销售工作。\n3.可以与各级渠道合作伙伴建立和维护良好的合作关系，提升渠道销售绩效。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4649794285","sourceKey":"meituan_social","company":"美团","title":"美团快驴-CKA城市质量主管","city":"宁波市/深圳市/杭州市/石家庄市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4649794285&jobShareType=1","duty":"1.主要负责蔬菜水果品类的到货验收，严格把控入库质量；\n2.蔬菜加工环节品质巡检，指导加工标准，成品检验等；\n3.对高投品高投客户进行专项治理，协调采、仓、配参与优化；\n4.全链路监控客诉问题，并跟进改善；\n5.物流执行标准稽核，例外问题推动改善；\n6.客诉分析与定位，其他主管交付的品质管理工作。","requirements":"1.大专及以上学历，食品、农学、医药等相关专业；\n2.具有2年以上生鲜质量管理经验，熟悉蔬菜产地、质量特性等；\n3.较强的质量意识，责任心强，原则性强；\n4.吃苦耐劳，能适应长期晚班。","description":"部门介绍\n快驴进货是美团旗下的餐饮供应链平台，帮助餐饮商户以更低成本、更高效率来获取安全可靠的食材供应，让餐饮采购更简单。快驴进货同步发展“自营+平台”的业务模式，在采购环节一方面向上游供应商直采大宗商品，另一方面引入各地批发商，助力平台伙伴共同发展；在销售环节既有自建团队进行市场、客户拓展，又帮助各地批发商拓展业务；同时自建仓储管理系统、配送网络与团队，为客户提供优质履约服务。\n截至2022年，快驴进货布局了全国41个城市，为百万家商户提供“全、省、稳、好”的餐饮供应链服务。我们拥有3000+品牌食材、超5万SKU商品、超28万商品资质，并提供源头严审核、食品安全严把关、24小时无忧售后的全面保障，实现手机下单、送货上门的高效采购模式，帮百万商家节省了采购时间与成本，助力平台伙伴共同发展，在万亿市场共享机遇。\n在这里，你将收获完善的员工发展机制及学习体系，与各界专家一起深度参与餐饮供应链业务的发展。欢迎优秀的你加入美团快驴进货，与我们一起成长，一起更好！\n\n岗位职责\n1.主要负责蔬菜水果品类的到货验收，严格把控入库质量；\n2.蔬菜加工环节品质巡检，指导加工标准，成品检验等；\n3.对高投品高投客户进行专项治理，协调采、仓、配参与优化；\n4.全链路监控客诉问题，并跟进改善；\n5.物流执行标准稽核，例外问题推动改善；\n6.客诉分析与定位，其他主管交付的品质管理工作。\n\n岗位基本要求\n1.大专及以上学历，食品、农学、医药等相关专业；\n2.具有2年以上生鲜质量管理经验，熟悉蔬菜产地、质量特性等；\n3.较强的质量意识，责任心强，原则性强；\n4.吃苦耐劳，能适应长期晚班。\n\n具备以下条件优先\n有蔬菜质量管理经验或生鲜产地管理经验优先\n\n岗位亮点\n生鲜B2B电商领域，面对餐饮大客户，构建生鲜品质管理的标准化和信息化","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4648940132","sourceKey":"meituan_social","company":"美团","title":"Hong Kong Traditional Chinese Language Specialist","city":"香港特别行政区","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4648940132&jobShareType=1","duty":"Ensure the linguistic and cultural quality of Traditional Chinese content by reviewing AI or vendor translations, conducting linguistic QA, providing actionable feedback, and performing translation or editing tasks when needed.\n\nOwn and continuously optimize language assets, including terminology databases, style guides, translation memories, and linguistic guidelines, to maintain consistency and improve localization efficiency.\n\nEstablish and maintain localization quality standards for product content, including defining language benchmarks, researching market-specific terminology, and ensuring alignment with Hong Kong user expectations and communication preferences.\n\nChampion a natural and engaging user experience by analyzing user feedback, identifying language-related pain points, and collaborating with product teams & stakeholders to improve in-app language quality.\n\nCollaborate with localization project managers, external translation partners, and product teams to manage localization workflows, resolve linguistic issues, and continuously improve content delivery quality and efficiency.\n\nStay updated on Hong Kong language trends, consumer behaviors, and digital product language practices to ensure Keeta’s content remains relevant and competitive.","requirements":"Native-level Cantonese speaker with extensive experience living and working in Hong Kong, with deep understanding of local language usage, cultural nuances, and user expectations.\n\nProfessional proficiency in Traditional Chinese writing, editing, and localization, with the ability to create natural, user-friendly product content for the Hong Kong market.\n\nFluent business-level English and Mandarin communication skills, with the ability to collaborate effectively with global teams.\n\nBachelor’s degree or above in Linguistics, Translation, Localization, Communications, or related fields preferred.\n\n3+ years of professional experience in Simplified Chinese/English-to-Traditional Chinese translation, localization, linguistic QA, or related language roles.\n\nProven experience with Simplified Chinese to Traditional Chinese localization, particularly for Hong Kong market adaptation, is required.\n\nStrong attention to detail, excellent language judgment, and the ability to balance linguistic accuracy with product and business objectives.\n\nStrong collaboration and stakeholder management skills, with the ability to build effective working relationships across teams and with external partners.","description":"部门介绍\nKeeta是全球领先外卖平台美团旗下的独立品牌，肩负着“帮大家吃得更好，生活更好”的使命。依托美团深耕中国市场15年的技术与运营积淀，我们正引领全球餐饮与商品即时配送服务的创新与发展。\n\n自2023年成立以来，Keeta始终扎根社区并创造价值。我们为用户提供可靠的外卖体验，以智慧技术助餐厅提升经营效率，在为骑手拓宽收入来源的同时，也充分提供安全保障措施。基于这份多方共赢、共同成长的理念，我们的业务已从中国香港稳步拓展至中东及巴西，并持续向世界迈进。\n\n岗位职责\nEnsure the linguistic and cultural quality of Traditional Chinese content by reviewing AI or vendor translations, conducting linguistic QA, providing actionable feedback, and performing translation or editing tasks when needed.\n\nOwn and continuously optimize language assets, including terminology databases, style guides, translation memories, and linguistic guidelines, to maintain consistency and improve localization efficiency.\n\nEstablish and maintain localization quality standards for product content, including defining language benchmarks, researching market-specific terminology, and ensuring alignment with Hong Kong user expectations and communication preferences.\n\nChampion a natural and engaging user experience by analyzing user feedback, identifying language-related pain points, and collaborating with product teams & stakeholders to improve in-app language quality.\n\nCollaborate with localization project managers, external translation partners, and product teams to manage localization workflows, resolve linguistic issues, and continuously improve content delivery quality and efficiency.\n\nStay updated on Hong Kong language trends, consumer behaviors, and digital product language practices to ensure Keeta’s content remains relevant and competitive.\n\n岗位基本要求\nNative-level Cantonese speaker with extensive experience living and working in Hong Kong, with deep understanding of local language usage, cultural nuances, and user expectations.\n\nProfessional proficiency in Traditional Chinese writing, editing, and localization, with the ability to create natural, user-friendly product content for the Hong Kong market.\n\nFluent business-level English and Mandarin communication skills, with the ability to collaborate effectively with global teams.\n\nBachelor’s degree or above in Linguistics, Translation, Localization, Communications, or related fields preferred.\n\n3+ years of professional experience in Simplified Chinese/English-to-Traditional Chinese translation, localization, linguistic QA, or related language roles.\n\nProven experience with Simplified Chinese to Traditional Chinese localization, particularly for Hong Kong market adaptation, is required.\n\nStrong attention to detail, excellent language judgment, and the ability to balance linguistic accuracy with product and business objectives.\n\nStrong collaboration and stakeholder management skills, with the ability to build effective working relationships across teams and with external partners.\n\n具备以下条件优先\nHong Kong native or candidates with extensive Hong Kong market experience are strongly preferred.\n\nAbility to communicate professionally in Mandarin (Simplified Chinese) and English.\n\nHands-on experience with CAT tools and Translation Management Systems (TMS).\n\nExperience localizing consumer internet products, mobile applications, e-commerce platforms, or other technology products.\n\nExperience working with professional localization vendors or language service providers in the technology industry.\n\nFamiliarity with product localization workflows, UX writing principles, and internationalization practices.\n\n岗位亮点\nPlay a key role in shaping Keeta’s Hong Kong localization strategy from the ground up, directly influencing how millions of users experience our product.\n\nGain hands-on experience in building scalable localization processes and language standards for a fast-growing global technology company.\n\nWork with talented, international teams in a dynamic and collaborative environment.","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4618100981","sourceKey":"meituan_social","company":"美团","title":"风控大模型算法专家","city":"上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4618100981&jobShareType=1","duty":"1.负责支持美团金融支付风控大模型算法研发，深刻理解风险控制和风险经营的业务场景，借助大模型技术推动风控核心场景AI 能力从 0 到 1 落地及持续迭代，负责从数据构建、提示词工程、模型SFT/RL到线上部署的全链路工程实现； \n2.深度挖掘海量生态数据、金融数据及外部数据，研究大模型与传统机器学习、深度学习模型融合落地方案，针对业务目标设计到端决策框架；\n3.负责不同业务线、不同场景下的模型体系的搭建，分层、立体地支持相应场景的业务指标达成；\n4.推动建立模型全生命周期SOP和相应工具平台建设，提升模型维护、管理和迭代的效率。","requirements":"1.具备生产环境大模型落地经验；熟悉大模型结构、训练与推理原理；掌握 RAG / Agent 框架（LangChain / LangGraph / AutoGen）工程化应用；有 SFT / RLHF / DPO 微调经验；熟悉 Prompt Engineering；能独立完成数据处理 → 模型训练 → 评估 → 部署完整链路；有将大模型与风控场景结合的实际项目经验优先；相关顶会论文（NeurIPS / KDD / WWW / AAAI / ACL 等）优先。\n2.3年以上风控算法/机器学习 / 深度学习/大模型相关方向工作经验，硕士及以上学历（计算机 / AI / 统计 / 金融工程相关专业），有金融风控场景经验优先。\n3.扎实的机器学习与深度学习基础（PyTorch / TensorFlow）；熟练掌握树模型、序列模型、图模型等机器学习算法，具备大模型agent框架构建、微调及强化学习经验；具备良好的工程能力（Python / SQL / Spark）；较强的数据分析与实验设计能力；对风控指标体系有深刻理解。\n4.强自驱力、良好的跨职能沟通协作能力、持续学习意愿、严谨细致的安全意识。","description":"部门介绍\n美团金融服务平台成立于2016年，以“场景+金融”模式，携手合作伙伴构建开放生态，为美团平台用户和商户提供底层账户、支付通道、信贷、保险和理财等金融解决方案。我们致力于以科技为核心，助力金融机构打通金融普惠“最后一公里”。我们期待与大家共同完成每一件平凡而卓越的事情，一起为用户提供优质的产品体验，守护用户的资金安全，让生活变得更美好。\n\n岗位职责\n1.负责支持美团金融支付风控大模型算法研发，深刻理解风险控制和风险经营的业务场景，借助大模型技术推动风控核心场景AI 能力从 0 到 1 落地及持续迭代，负责从数据构建、提示词工程、模型SFT/RL到线上部署的全链路工程实现； \n2.深度挖掘海量生态数据、金融数据及外部数据，研究大模型与传统机器学习、深度学习模型融合落地方案，针对业务目标设计到端决策框架；\n3.负责不同业务线、不同场景下的模型体系的搭建，分层、立体地支持相应场景的业务指标达成；\n4.推动建立模型全生命周期SOP和相应工具平台建设，提升模型维护、管理和迭代的效率。\n\n岗位基本要求\n1.具备生产环境大模型落地经验；熟悉大模型结构、训练与推理原理；掌握 RAG / Agent 框架（LangChain / LangGraph / AutoGen）工程化应用；有 SFT / RLHF / DPO 微调经验；熟悉 Prompt Engineering；能独立完成数据处理 → 模型训练 → 评估 → 部署完整链路；有将大模型与风控场景结合的实际项目经验优先；相关顶会论文（NeurIPS / KDD / WWW / AAAI / ACL 等）优先。\n2.3年以上风控算法/机器学习 / 深度学习/大模型相关方向工作经验，硕士及以上学历（计算机 / AI / 统计 / 金融工程相关专业），有金融风控场景经验优先。\n3.扎实的机器学习与深度学习基础（PyTorch / TensorFlow）；熟练掌握树模型、序列模型、图模型等机器学习算法，具备大模型agent框架构建、微调及强化学习经验；具备良好的工程能力（Python / SQL / Spark）；较强的数据分析与实验设计能力；对风控指标体系有深刻理解。\n4.强自驱力、良好的跨职能沟通协作能力、持续学习意愿、严谨细致的安全意识。\n\n具备以下条件优先\n1.具备大模型在风控领域垂类应用经验优先，包含客户画像、准入/额价决策场景的智能体搭建、后训练、蒸馏推理加速。\n\n岗位亮点\n1.主导支付风控场景 AI 从 0 到 1 落地，在高对抗、快变化、大数据量的金融支付场景中深度应用 LLM + 机器学习前沿技术栈，稀缺性强、技术壁垒高。\n2.服务数亿美团用户，美团平台多维交易行为数据资产丰富；个人贡献与风险、规模等核心业务 ROI 直接挂钩，成就感强。\n3.充足 GPU 算力与海量金融数据；专业标注与合规资源；团队来自国内外名校及头部大厂，技术氛围浓厚；扁平管理，晋升通道清晰，鼓励技术创新与分享。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:2651522727","sourceKey":"meituan_social","company":"美团","title":"机器学习平台研发工程师","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=2651522727&jobShareType=1","duty":"1.建设特征/样本工程，设计包括从特征打印到特征服务的完整实时+离线特征/样本生产流程，设计大规模分布式特征存储系统，支撑百亿级数据实时处理，提升特征/样本的生产效率、质量和访问性能，进而提升算法迭代效率和效果；\n2.对算法开发过程进行抽象，将常用的机器学习、深度学习过程沉淀为组件，建设算法开发pipeline，设计代码与可视化组件相结合的编程范式，提供便捷稳固的一站式环境托管，提升算法迭代效率；\n3.建设训练任务的托管能力，设计异构、多地域、多系统资源池、多租户分组的实验编排调度系统，建立模型实验效果评估体系，支撑几十个业务线、千级模型同时进行训练，保障模型及时产出，提升资源利用率，帮助业务优化模型效果；\n4.探索云原生下的模型服务部署架构，设计高可用、多角色的模型服务框架，制定流量分发、模型/服务治理策略，支撑万亿级推理调用量，提升模型部署成功率、推理请求成功率和性能；","requirements":"1.计算机基础知识良好，熟悉Java/Python/C++之一，对机器学习感兴趣；\n2.对后台开发技术栈有深刻理解，有较强抽象能力，有大型系统开发经历；\n2.具有主流深度学习引擎和大数据计算引擎（包括但不限于TensorFlow/PyTorch、Spark/Flink、Hudi/Iceberg等）的实际应用经验和原理了解，有引擎优化或平台化的经历；\n4.有较强的技术好奇心和自驱力，了解行业最佳实践。","description":"部门介绍\n基础研发平台是美团的核心技术平台，立足于“零售+科技”的战略定位，通过打造人工智能、大数据、云计算、安全等核心技术能力，以及研发效能平台、企业应用平台等公共服务，为业务提供稳定安全、扩展易用、技术领先的平台技术和产品服务。\n在这里，我们会参与到最前沿的技术研发和探索；能够接触超规模集群、海量数据，挑战高复杂业务场景，有机会与业界一流的工程师一起并肩前行。\n在这里，我们有超强的技术氛围，持续向社区贡献业界实践，加速行业技术发展；我们有完善的互联网学习生态圈，重视底层逻辑和方法论，助力职业生涯的非线性成长。\n真诚地邀请你，和我们一起驱动技术发展，创造行业价值。\n\n岗位职责\n1.建设特征/样本工程，设计包括从特征打印到特征服务的完整实时+离线特征/样本生产流程，设计大规模分布式特征存储系统，支撑百亿级数据实时处理，提升特征/样本的生产效率、质量和访问性能，进而提升算法迭代效率和效果；\n2.对算法开发过程进行抽象，将常用的机器学习、深度学习过程沉淀为组件，建设算法开发pipeline，设计代码与可视化组件相结合的编程范式，提供便捷稳固的一站式环境托管，提升算法迭代效率；\n3.建设训练任务的托管能力，设计异构、多地域、多系统资源池、多租户分组的实验编排调度系统，建立模型实验效果评估体系，支撑几十个业务线、千级模型同时进行训练，保障模型及时产出，提升资源利用率，帮助业务优化模型效果；\n4.探索云原生下的模型服务部署架构，设计高可用、多角色的模型服务框架，制定流量分发、模型/服务治理策略，支撑万亿级推理调用量，提升模型部署成功率、推理请求成功率和性能；\n\n岗位基本要求\n1.计算机基础知识良好，熟悉Java/Python/C++之一，对机器学习感兴趣；\n2.对后台开发技术栈有深刻理解，有较强抽象能力，有大型系统开发经历；\n2.具有主流深度学习引擎和大数据计算引擎（包括但不限于TensorFlow/PyTorch、Spark/Flink、Hudi/Iceberg等）的实际应用经验和原理了解，有引擎优化或平台化的经历；\n4.有较强的技术好奇心和自驱力，了解行业最佳实践。\n\n具备以下条件优先\n1.参与过大型开源项目，尤其是在深度学习引擎或大数据引擎方面贡献过社区代码；\n2.完整参与过企业级算法工程建设，有搜广推后端工程或特征/样本流建设经验，有平台化经历；\n3.具有存储系统读写优化相关工作经验；\n4.有GPU编程经验，参与过模型训练和推理服务，有深度学习任务性能/异常分析经验；\n4.能以结果和价值为导向，利用科学的方法进行指标收集、统计、分析，从而进行成果的衡量。\n\n岗位亮点\n1.能参与特征、样本、算法开发、训练、推理全流程的算法工程实践；\n2.万亿级请求量线上服务的高可用挑战；\n3.参与大模型算法工程建设；\n4.从平台视角，观察体验丰富的业务场景，覆盖美团外卖、酒旅、配送、优选等多领域业务，从数据规模、集群体量、算法和业务复杂度多个维度提供了技术挑战和锻炼发展的机会。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4605451483","sourceKey":"meituan_social","company":"美团","title":"加工主管","city":"武汉市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4605451483&jobShareType=1","duty":"1、负责排产、排班、出勤计划执行，加工进度管控、每日订单目标交付达成；\n2、负责加工过程中人员组台、品类拆分、原料进度追踪、异常协调等业务；\n3、负责加工品质保障、加工数据准确性管理、上下游入库准确性管理；\n4、负责设备高效使用，员工积极性策略推动与执行；\n5、负责加工区域6S、生产安全、消防安全、食品安全等管理；\n6、负责促成部门各指标达成（品质、原料成本、人力成本、员工留存等）\n7、负责班次团队组织架构搭建、招聘计划、人员培养汰换，每日生产会议。","requirements":"1.具备物流或仓储相关领域的大学专科及以上学历。\n2.至少3年以上物流或仓储管理经验，有生鲜加工、净菜管理经验者优先考虑。\n3.熟悉生鲜产品的质量标准和加工工艺，具备相关品控知识。\n4.具备较好的团队管理能力，能够激励团队成员，提高工作效率。\n5.具备良好的沟通协调能力，能够与不同部门和供应商进行有效的合作。\n6.具备一定的问题解决能力和应变能力，能够灵活应对工作中的各种挑战。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1、负责排产、排班、出勤计划执行，加工进度管控、每日订单目标交付达成；\n2、负责加工过程中人员组台、品类拆分、原料进度追踪、异常协调等业务；\n3、负责加工品质保障、加工数据准确性管理、上下游入库准确性管理；\n4、负责设备高效使用，员工积极性策略推动与执行；\n5、负责加工区域6S、生产安全、消防安全、食品安全等管理；\n6、负责促成部门各指标达成（品质、原料成本、人力成本、员工留存等）\n7、负责班次团队组织架构搭建、招聘计划、人员培养汰换，每日生产会议。\n\n岗位基本要求\n1.具备物流或仓储相关领域的大学专科及以上学历。\n2.至少3年以上物流或仓储管理经验，有生鲜加工、净菜管理经验者优先考虑。\n3.熟悉生鲜产品的质量标准和加工工艺，具备相关品控知识。\n4.具备较好的团队管理能力，能够激励团队成员，提高工作效率。\n5.具备良好的沟通协调能力，能够与不同部门和供应商进行有效的合作。\n6.具备一定的问题解决能力和应变能力，能够灵活应对工作中的各种挑战。\n\n具备以下条件优先\n有生鲜、食品、净菜加工经验优先\n\n岗位亮点\n1、具备100人以上的团队管理经验；\n2、具备数据分析能力，熟练使用办公软件；\n3、具备良华的沟通能力，能与上下游沟通协作；","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4641891765","sourceKey":"meituan_social","company":"美团","title":"拼好饭内控合规专家","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4641891765&jobShareType=1","duty":"1. 负责从0-1搭建起内控合规体系，并灵活借助AI制定并优化相关制度与流程；\n2. 组织开展内控自评、合规检查及风险评估，识别潜在风险并提出改进建议；\n3. 监督业务部门落实内控合规要求，推动问题整改与闭环管理 ；\n4. 配合外部审计与内控检查，提供相关内控合规支持材料；\n5. 定期开展内控合规培训，提升全员合规意识与风险防控能力。","requirements":"1. 大学本科及以上学历，财务、审计、法律或相关专业背景。\n2. 具备5年以上内控、合规或内部审计工作经验，有大型企业或上市公司经历者优先，对AI应用有一定认知及实践经验优先。\n3. 熟悉企业内部控制规范、合规管理要求及相关法律法规。\n4. 具备良好的沟通协调能力、逻辑分析能力和文字表达能力。\n5. 工作严谨细致，具备较强的责任心和学习能力。","description":"部门介绍\n美团外卖秉承“帮大家吃得更好，生活更好”的使命，始终聚焦于消费者用餐需求。我们通过科技连接消费者和商家，依托庞大的骑手团队，以“线上+线下”的业务模式，为消费者提供品质化、精细化、多样化的餐饮外卖服务。\n外卖事业部是为用户与商家提供全链路交易服务的业务组织，围绕餐饮外卖搭建了包含外卖业务与创新孵化业务在内的多个部门。\n我们的目标是帮助商家开源增收、提高经营效率，促进餐饮行业数字化，以及为更多用户提供更便捷更有品质的外卖服务。加入我们，一起为上亿用户提供更好的用餐体验，帮助大家吃得更好，生活更好！\n\n岗位职责\n1. 负责从0-1搭建起内控合规体系，并灵活借助AI制定并优化相关制度与流程；\n2. 组织开展内控自评、合规检查及风险评估，识别潜在风险并提出改进建议；\n3. 监督业务部门落实内控合规要求，推动问题整改与闭环管理 ；\n4. 配合外部审计与内控检查，提供相关内控合规支持材料；\n5. 定期开展内控合规培训，提升全员合规意识与风险防控能力。\n\n岗位基本要求\n1. 大学本科及以上学历，财务、审计、法律或相关专业背景。\n2. 具备5年以上内控、合规或内部审计工作经验，有大型企业或上市公司经历者优先，对AI应用有一定认知及实践经验优先。\n3. 熟悉企业内部控制规范、合规管理要求及相关法律法规。\n4. 具备良好的沟通协调能力、逻辑分析能力和文字表达能力。\n5. 工作严谨细致，具备较强的责任心和学习能力。\n\n岗位亮点\n1. 平台稳定，发展空间广阔，可深度参与公司风控体系建设。\n2. 团队专业，协作氛围良好，提供系统化培训与成长机会。\n3. 工作地点位于北京市核心区域，交通便利，办公环境优越。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4643320053","sourceKey":"meituan_social","company":"美团","title":"拼好饭-运营支持/门店督导","city":"深圳市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4643320053&jobShareType=1","duty":"1. 门店经营督导\n对所负责城市门店的经营指标（日均单量、单均毛利、UE达标率）负责，确保门店按SOP标准执行运营动作\n定期巡店（含线上巡检），输出巡检报告，推动问题整改闭环\n协助门店解决日常经营问题（曝光不足、转化率低、客诉异常等）\n2. 合作商管理\n对接合作商日常运营需求，推动合作商资源分配到位\n执行门店资源奖惩机制，确保合作商履约达标\n关注合作商门店服务质量（差评率、门店评分、复购率等）\n3. 标准化落地\n推动门店执行总部下发的运营SOP（出餐标准、食品安全、服务流程）\n配合门店培训落地，确保新员工掌握岗位技能\n执行门店稽核与供应链品控标准\n4. 数据驱动\n每日跟进门店经营数据，异常门店及时预警并输出整改方案\n定期输出城市门店经营分析报告，为策略调整提供依据\n5. 新店跟进\n新店开业前参与筹备验收，开业后跟进爬坡期经营表现\n新店2个月内重点保障单量爬坡与UE转正","requirements":"1. 经验：2年以上餐饮/外卖行业门店运营或督导经验，有连锁餐饮或外卖运营背景优先\n2. 能力：具备数据敏感度，能看懂经营数据并输出分析结论；具备较强的执行力和沟通能力，能推动合作商落地执行\n3. 态度：能适应高频巡店（含线上巡检），接受驻城工作制，有责任心\n4. 加分项：有外卖平台运营经验；熟悉北京/深圳/东莞本地餐饮市场","description":"部门介绍\n美团外卖秉承“帮大家吃得更好，生活更好”的使命，始终聚焦于消费者用餐需求。我们通过科技连接消费者和商家，依托庞大的骑手团队，以“线上+线下”的业务模式，为消费者提供品质化、精细化、多样化的餐饮外卖服务。\n外卖事业部是为用户与商家提供全链路交易服务的业务组织，围绕餐饮外卖搭建了包含外卖业务与创新孵化业务在内的多个部门。\n我们的目标是帮助商家开源增收、提高经营效率，促进餐饮行业数字化，以及为更多用户提供更便捷更有品质的外卖服务。加入我们，一起为上亿用户提供更好的用餐体验，帮助大家吃得更好，生活更好！\n\n岗位职责\n1. 门店经营督导\n对所负责城市门店的经营指标（日均单量、单均毛利、UE达标率）负责，确保门店按SOP标准执行运营动作\n定期巡店（含线上巡检），输出巡检报告，推动问题整改闭环\n协助门店解决日常经营问题（曝光不足、转化率低、客诉异常等）\n2. 合作商管理\n对接合作商日常运营需求，推动合作商资源分配到位\n执行门店资源奖惩机制，确保合作商履约达标\n关注合作商门店服务质量（差评率、门店评分、复购率等）\n3. 标准化落地\n推动门店执行总部下发的运营SOP（出餐标准、食品安全、服务流程）\n配合门店培训落地，确保新员工掌握岗位技能\n执行门店稽核与供应链品控标准\n4. 数据驱动\n每日跟进门店经营数据，异常门店及时预警并输出整改方案\n定期输出城市门店经营分析报告，为策略调整提供依据\n5. 新店跟进\n新店开业前参与筹备验收，开业后跟进爬坡期经营表现\n新店2个月内重点保障单量爬坡与UE转正\n\n岗位基本要求\n1. 经验：2年以上餐饮/外卖行业门店运营或督导经验，有连锁餐饮或外卖运营背景优先\n2. 能力：具备数据敏感度，能看懂经营数据并输出分析结论；具备较强的执行力和沟通能力，能推动合作商落地执行\n3. 态度：能适应高频巡店（含线上巡检），接受驻城工作制，有责任心\n4. 加分项：有外卖平台运营经验；熟悉北京/深圳/东莞本地餐饮市场\n\n具备以下条件优先\n有C2M/拼好饭等渠道运营经验\n\n岗位亮点\n参与品牌从0到1的爬坡过程：新店前2个月是经营定盘的关键窗口，直接决定门店生死线，你的每一步决策都影响最终产出\nUE与单量双维度闭环：不只看单量，更关注经营质量，从曝光→进店→下单全链路拉通，确保单量爬坡的同时UE转正\n多城多店并行运营：覆盖多城市门店矩阵，节奏快、场景丰富，运营经验可快速复制、横向迁移\n成长空间大：业务处于扩张期，跑通模型后规模可复制，个人影响力随业务增长同步放大","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4646018675","sourceKey":"meituan_social","company":"美团","title":"风险投诉客服经理","city":"武汉市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4646018675&jobShareType=1","duty":"1、管理团队，并在团队运营中发现并不断完善相关流程/机制，保障团队稳定、高效运转；\n2、持续培养提升员工的服务意识、风险&危机意识、跨部门协同能力、良好的沟通谈判能力、发现并解决问题的能力等；\n3、做到坚持以客户为中心，快速解决客户问题（避免风险），提升客户满意度；\n4、能发现流程及产品不足，有效解决，并做到持续改善；探索AI工具在客服场景的应用，推动智能客服、智能质检等AI能力落地，提升团队运营效率；\n5、建立完整人才培养体系，发掘并培养团队人才，推动组长个人能力和团队能力提升；\n6、承接项目，明确目标和里程碑，保证项目有序推进和达成；\n7、不断学习和探索，学习、借鉴、并超越业内同岗位运营方式。关注AI在客户服务领域的新应用，具备将AI能力转化为业务结果的意识和能力。","requirements":"1、5年以上互联网呼叫中心工作经验，有超过100人团队管理经验；\n2、具备客服团队管理运营，风险研判经验，能够快速的适应业务变化并调整打法拿到结果，能主动依据团队现状做策略规划，有逻辑有侧重落地执行；\n3、拥有与管理团队、业务团队对话的能力，思路敏捷；\n4、适应扁平化的管理和沟通，拥抱变化；\n5、在团队精细化运营外，能聚焦业务，关注体验，持续优化；\n6、具备项目承接和推动能力，保证项目如期完成。\n7、对AI技术保持好奇心和学习热情，能快速适应AI驱动的工作模式，有推动AI落地或人机协同团队的管理经验者优先。","description":"部门介绍\n美团平台为用户的基础产品体验负责，还承担了美团的用户增长、市场和品牌营销以及多条业务线的产品设计职责，建立了融合文字、图片、视频和直播等不同形式的內容生态系统，同时整合地图服务部、客户服务和体验部、企业业务部、网约车业务部等部门，致力于用科技提升美团数亿消费者、近千万商家、骑手、司机和团长的服务体验。美团平台拥有高并发、多业务的复杂场景，为技术深度优化提供了最佳实践可能。这里有简单、讲逻辑、有爱的团队，更是一块理想的实战场地，舞台广阔，欢迎你来尽情施展。\n\n岗位职责\n1、管理团队，并在团队运营中发现并不断完善相关流程/机制，保障团队稳定、高效运转；\n2、持续培养提升员工的服务意识、风险&危机意识、跨部门协同能力、良好的沟通谈判能力、发现并解决问题的能力等；\n3、做到坚持以客户为中心，快速解决客户问题（避免风险），提升客户满意度；\n4、能发现流程及产品不足，有效解决，并做到持续改善；探索AI工具在客服场景的应用，推动智能客服、智能质检等AI能力落地，提升团队运营效率；\n5、建立完整人才培养体系，发掘并培养团队人才，推动组长个人能力和团队能力提升；\n6、承接项目，明确目标和里程碑，保证项目有序推进和达成；\n7、不断学习和探索，学习、借鉴、并超越业内同岗位运营方式。关注AI在客户服务领域的新应用，具备将AI能力转化为业务结果的意识和能力。\n\n岗位基本要求\n1、5年以上互联网呼叫中心工作经验，有超过100人团队管理经验；\n2、具备客服团队管理运营，风险研判经验，能够快速的适应业务变化并调整打法拿到结果，能主动依据团队现状做策略规划，有逻辑有侧重落地执行；\n3、拥有与管理团队、业务团队对话的能力，思路敏捷；\n4、适应扁平化的管理和沟通，拥抱变化；\n5、在团队精细化运营外，能聚焦业务，关注体验，持续优化；\n6、具备项目承接和推动能力，保证项目如期完成。\n7、对AI技术保持好奇心和学习热情，能快速适应AI驱动的工作模式，有推动AI落地或人机协同团队的管理经验者优先。\n\n具备以下条件优先\n团队管理经验，服务运营，高风险处理，风险研判等经验优先。\n\n岗位亮点\n1、发展方向多元：从消费者和商家服务体验出发，深入到业务中通过产品能力解决问题。\n2、有挑战成长快：复杂业务中学习和实践美团丰富方法论，建立自己思维框架。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4566481225","sourceKey":"meituan_social","company":"美团","title":"AI电销运营策略岗","city":"上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4566481225&jobShareType=1","duty":"1. 结合AI重塑电销运营全流程，主导AI电销用户分层策略、智能触达节奏、话术设计等核心环节，建立可复制的AI电销运营方法论。\n2. 与产研/算法团队协同推进AI能力迭代，把业务Know-how转化为算法锚点、意图识别优化、对话策略调整等具体需求，推动产研快速迭代。\n3. 自驱力强，通过数据驱动构建AI电销核心指标体系，建立周期性复盘机制和持续迭代AI运营策略。","requirements":"1. 大学本科及以上学历，4年及以上用户运营或产品运营相关经验。  \n2. 熟悉电销业务流程，具备跨团队协作能力与较强的策略落地执行力。具备AI项目实践经验，能够将业务需求拆解为Prompt工程、意图分类、对话策略等具体方案；了解大模型基本原理；能使用AI工具辅助业务分析与流程优化。\n3. 具备较强的数据分析能力，独立思考能力。","description":"部门介绍\n美团金融服务平台成立于2016年，以“场景+金融”模式，携手合作伙伴构建开放生态，为美团平台用户和商户提供底层账户、支付通道、信贷、保险和理财等金融解决方案。我们致力于以科技为核心，助力金融机构打通金融普惠“最后一公里”。我们期待与大家共同完成每一件平凡而卓越的事情，一起为用户提供优质的产品体验，守护用户的资金安全，让生活变得更美好。\n\n岗位职责\n1. 结合AI重塑电销运营全流程，主导AI电销用户分层策略、智能触达节奏、话术设计等核心环节，建立可复制的AI电销运营方法论。\n2. 与产研/算法团队协同推进AI能力迭代，把业务Know-how转化为算法锚点、意图识别优化、对话策略调整等具体需求，推动产研快速迭代。\n3. 自驱力强，通过数据驱动构建AI电销核心指标体系，建立周期性复盘机制和持续迭代AI运营策略。\n\n岗位基本要求\n1. 大学本科及以上学历，4年及以上用户运营或产品运营相关经验。  \n2. 熟悉电销业务流程，具备跨团队协作能力与较强的策略落地执行力。具备AI项目实践经验，能够将业务需求拆解为Prompt工程、意图分类、对话策略等具体方案；了解大模型基本原理；能使用AI工具辅助业务分析与流程优化。\n3. 具备较强的数据分析能力，独立思考能力。\n\n具备以下条件优先\n具备信贷行业AI营销相关经营者优先\n\n岗位亮点\n1. 接触多Agent协同、智能决策、人机融合等前沿AI技术栈，站在AI重构传统业务模式最前沿。\n2. 电销业务正处于从\"人工为主\"向\"AI驱动\"范式切换期，增长空间较大。\n3. 参与大模型在电销场景的深度落地，主导千万级用户规模AI电销系统的运营与迭代；提供充足算力、数据、标注及预算支持发展空间和个人能力成长。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4520878795","sourceKey":"meituan_social","company":"美团","title":"眼科KA大客户主管","city":"上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4520878795&jobShareType=1","duty":"1. 负责眼科行业大客户的开发与维护，制定并执行客户运营策略，达成销售目标。  \n2. 深入了解客户需求，协调内部资源推动定制化解决方案落地。  \n3. 带领团队完成团队销售任务，制定团队目标、培训计划及绩效考核机制。  \n4. 定期分析市场/行业动态与竞争态势，优化客户结构与业务布局。","requirements":"1. 大学本科及以上学历，市场营销、工商管理或相关专业。  \n2. 具备5年以上大客户销售或业务开发经验，有本地生活 / O2O / 广告投放产品销售经验。\n3. 熟悉大客户管理流程，具备较强的商务谈判与项目推进能力，有连锁品牌或大客户销售经验，熟悉总部决策 + 门店执行双线跟进节奏。  \n4. 具备团队管理经验，能够有效激励团队并推动目标达成。\n\n加分项：\n1.有眼科及行业资源或有相关从业背景\n2.熟悉商业化产品体系体系","description":"部门介绍\n美团医药健康事业部是美团核心本地商业板块下专注健康领域的业务部门，涵盖美团买药、美团医美和美团医疗三大业务。自创立以来，美团医药健康致力于为用户提供全健康周期产品及服务，满足人民群众多层次多元化医疗健康需求，现已覆盖购药到家、居家检测、问诊挂号、医保支付、求医寻院、医疗美容等核心场景。此外，美团医药健康还为商户提供数字化转型创新解决方案，打造贯穿上游的联动机制，长期参与共建更透明、更可持续的医药健康产业生态圈，目前业务已覆盖25万家药店，收录27万家医疗机构。未来，美团医药康将协同更多行业伙伴，帮助大家变得更健康、更美丽、更养生。\n\n岗位职责\n1. 负责眼科行业大客户的开发与维护，制定并执行客户运营策略，达成销售目标。  \n2. 深入了解客户需求，协调内部资源推动定制化解决方案落地。  \n3. 带领团队完成团队销售任务，制定团队目标、培训计划及绩效考核机制。  \n4. 定期分析市场/行业动态与竞争态势，优化客户结构与业务布局。\n\n岗位基本要求\n1. 大学本科及以上学历，市场营销、工商管理或相关专业。  \n2. 具备5年以上大客户销售或业务开发经验，有本地生活 / O2O / 广告投放产品销售经验。\n3. 熟悉大客户管理流程，具备较强的商务谈判与项目推进能力，有连锁品牌或大客户销售经验，熟悉总部决策 + 门店执行双线跟进节奏。  \n4. 具备团队管理经验，能够有效激励团队并推动目标达成。\n\n加分项：\n1.有眼科及行业资源或有相关从业背景\n2.熟悉商业化产品体系体系\n\n具备以下条件优先\n打仗型管理者：自己能上，带团队也能打\n懂行业：能聊品类策略，团队能力能自闭环\n坚韧：冲刺季扛得住，遇到大客户流失能快速稳住局面\n有标准：对下属有要求，能给出具体改进建议，不只是\"加油\"\n\n岗位亮点\n1. 覆盖全国核心城市，拥有广阔的市场发展空间与资源支持。  \n2. 行业头部企业平台，提供完善的培训体系与职业发展通道。  \n3. 富有竞争力的薪酬结构，包含绩效奖金与长期激励计划。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4626636244","sourceKey":"meituan_social","company":"美团","title":"调度策略运营","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4626636244&jobShareType=1","duty":"1.负责制定和执行两轮车辆运营策略，以提高O端运营效率和盈利能力，达成目标。\n2.分析市场需求和竞争情况，制定相应的车辆调度和运营计划，确保车辆供应和需求的平衡。\n3.负责监控车辆运营数据，进行数据分析和挖掘，发现问题并提出改进措施，以优化运营效果。\n4.推动车辆运营相关联的标准化建设，完善流程管理，风控防范等。","requirements":"1.大学本科学历，专业不限，具备良好的业务运营和管理能力。\n2.拥有至少3年B端供需策略运营相关工作经验，熟悉供需运营流程和管理方法。\n3.灵活运用SQL等数据工具，具备良好的数据分析能力和解决问题的能力，能够准确分析运营数据并提出有效的改进方案。\n4.具备较强的责任心，能够在较挑战环境下保持良好的工作状态。","description":"部门介绍\n美团骑行事业部在全国各个城市开展美团单车、电单车业务，提供绿色、便捷的共享出行服务，是美团出行板块重要的组成部分。我们力求为城市可持续发展提供低碳智能的解决方案，通过技术创新和硬件升级，不断优化全流程骑行体验，为低碳出行提供更好的服务。其中，美团单车旨在为城市居民提供通勤接驳服务，满足用户短途接驳出行需求；美团电单车则满足用户中短途多场景低碳出行需求。\n我们有开放的工作氛围，也有充满韧劲和创造力，心系低碳出行的伙伴。加入我们，一起为用户创造更好的出行体验。\n\n岗位职责\n1.负责制定和执行两轮车辆运营策略，以提高O端运营效率和盈利能力，达成目标。\n2.分析市场需求和竞争情况，制定相应的车辆调度和运营计划，确保车辆供应和需求的平衡。\n3.负责监控车辆运营数据，进行数据分析和挖掘，发现问题并提出改进措施，以优化运营效果。\n4.推动车辆运营相关联的标准化建设，完善流程管理，风控防范等。\n\n岗位基本要求\n1.大学本科学历，专业不限，具备良好的业务运营和管理能力。\n2.拥有至少3年B端供需策略运营相关工作经验，熟悉供需运营流程和管理方法。\n3.灵活运用SQL等数据工具，具备良好的数据分析能力和解决问题的能力，能够准确分析运营数据并提出有效的改进方案。\n4.具备较强的责任心，能够在较挑战环境下保持良好的工作状态。\n\n岗位亮点\n1.作为O端运营策略专家，有机会参与和引领车辆运营策略的制定和实施，对公司整体业务发展具有重要影响力。\n2.可以接触到丰富的车辆运营数据，并通过数据分析和挖掘提出改进方案，为公司的运营效果和盈利能力提供重要支持。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3515288929","sourceKey":"meituan_social","company":"美团","title":"酒店直连产品专家","city":"北京市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3515288929&jobShareType=1","duty":"1、负责设计酒店直连接入通道能力（开放平台、KA对接），实现供给的高效和高质量接入，可以做到行业先进；\n2、负责设计直连与其他多个业务系统（尤其是商家端、商品库、CRS）的高效对接联动；可以承担部门内直连攻坚项目主R；\n3、通过数据分析和用户调研跟踪产品上线效果，发现、分析并解决问题，持续改善产品和创新；\n4、能利用AI工具实现工作提效。","requirements":"1、3年及以上的直连产品建设经验，熟悉上游酒店、PMS厂商、Switch厂商；\n2、有owner意识，可以通过产品牵引运营及业务团队，驱动业务发展；\n3、沟通和表达能力强，良好的目标感和自驱力，高度责任感；\n4、思路清晰、逻辑严谨、具备主动分析问题能力；\n5、能熟练使用AI工具辅助产品设计和效果分析。","description":"部门介绍\n美团酒店旅行业务涵盖酒店、民宿、机票、火车票、旅游度假、景点门票等各类住行游品类，通过与产业上下游的深度合作，为用户提供美好的旅游旅行体验。我们积极打造AI友好型组织，使用AI等新技术提升旅游服务的供需匹配效率，更好满足用户个性化、多样化的出游需求。我们持续深耕产业链，用数字化服务助力实体商家高质量经营，探索自有品牌等供给新模式，打造健康的商家生态，保障用户服务体验。为满足用户日益增长的跨境旅行需求，我们将聚焦亚太区域，打造高品质的住宿、交通、游玩等服务矩阵。\n这里有多元的业务布局、持续的成长空间，无论是向往的远方还是眼前的工作，一路都是风景相伴。加入我们，共同为用户创造旅游旅行中的高光时刻！\n\n岗位职责\n1、负责设计酒店直连接入通道能力（开放平台、KA对接），实现供给的高效和高质量接入，可以做到行业先进；\n2、负责设计直连与其他多个业务系统（尤其是商家端、商品库、CRS）的高效对接联动；可以承担部门内直连攻坚项目主R；\n3、通过数据分析和用户调研跟踪产品上线效果，发现、分析并解决问题，持续改善产品和创新；\n4、能利用AI工具实现工作提效。\n\n岗位基本要求\n1、3年及以上的直连产品建设经验，熟悉上游酒店、PMS厂商、Switch厂商；\n2、有owner意识，可以通过产品牵引运营及业务团队，驱动业务发展；\n3、沟通和表达能力强，良好的目标感和自驱力，高度责任感；\n4、思路清晰、逻辑严谨、具备主动分析问题能力；\n5、能熟练使用AI工具辅助产品设计和效果分析。\n\n具备以下条件优先\n有OTA、酒店行业、直连相关产品或研发背景优先\n\n岗位亮点\n1.业务规模大、复杂度高，岗位职能兼具体系建设和业务实践，对供给产品方向来说有极大的挑战和成长机会；\n2.可构建广而深的业务领域知识体系，有机会在多个细分领域探索、积累、实践；\n3.团队氛围开放、友好；成熟有效的业务、产品方法论体系，完善的培养机制，重视同学成长发展，欢迎志同道合同学加入！","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4629855284","sourceKey":"meituan_social","company":"美团","title":"小象超市-北京供应链品控","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4629855284&jobShareType=1","duty":"1. 负责小象超市生鲜的供应链环节的商品质量管理，预防和优化商品质量问题，提升用户满意度；\n2. 负责商品收货，存储，包装，配送过程中的质量检测和标准落地，减少各环节的商品质量问题发生；\n3. 负责跟踪解决出现的商品（特别是生鲜产品）质量问题，避免商品质量问题重复出现，影响用户体验。","requirements":"1. 专科以上学历，2年以上商超零售质量管理经验或供应链质量管理经验；\n2. 具备跨部门沟通表达及协作能力，能快速推进项目落地；\n3. 具备责任心，自驱性强；\n4. 具备正直诚信的价值观，有较强的原则性。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1. 负责小象超市生鲜的供应链环节的商品质量管理，预防和优化商品质量问题，提升用户满意度；\n2. 负责商品收货，存储，包装，配送过程中的质量检测和标准落地，减少各环节的商品质量问题发生；\n3. 负责跟踪解决出现的商品（特别是生鲜产品）质量问题，避免商品质量问题重复出现，影响用户体验。\n\n岗位基本要求\n1. 专科以上学历，2年以上商超零售质量管理经验或供应链质量管理经验；\n2. 具备跨部门沟通表达及协作能力，能快速推进项目落地；\n3. 具备责任心，自驱性强；\n4. 具备正直诚信的价值观，有较强的原则性。\n\n具备以下条件优先\n1. 热爱互联网和新零售行业，具有极强的快速学习能力；\n2. 有质量管理方法论且可以快速结合业务特点落地能力。\n\n岗位亮点\n1.了解生鲜商品全链条品质管理过程，与各团队一起提升客户品质体验；\n2.制定互联网生鲜板块的相关行业标准。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4449505759","sourceKey":"meituan_social","company":"美团","title":"保险平台-AI理赔策略经理","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4449505759&jobShareType=1","duty":"1、制定与迭代优化理赔模式和核赔规则：负责理赔策略设计，覆盖人伤医疗费扣减、伤残减损逻辑、车物成本管控、估损模型优化等；将核赔规则结构化为AI可自动执行的决策逻辑，推动从\"人逐案审\"到\"AI按规则判、人维护规则\"的模式转变\n\n2、保司运营与管理：负责合作保司的日常运营管理，包括保司理赔作业质量监控、核心指标追踪与对齐、保司端理赔动作异常的预警与介入；推动保司侧理赔流程标准化，确保向日葵与保司形成互补分工、协同高效的作业格局；探索用AI对保司作业质量进行实时监测与异常预警，替代传统滞后的人工抽检和周报盘点。\n\n3、设计风控策略并推动落地：构建倒签单识别、异常就医模式检测、关联异常预警等风控能力；推动风控从\"事后抽检\"转向\"AI实时识别\"——让每case进来瞬间就完成风险扫描，而非依赖人工回溯发现问题。\n\n4、理赔体验策略：负责理赔满意度提升与投诉率治理，设计理赔时效优化、估损偏差收敛、主动沟通触达等体验策略；关注用户全旅程中的体验断点，从报案、审核、赔付到结案每个环节找到改善空间；利用AI实现理赔进度智能推送、用户诉求预判与主动干预，让\"用户追着问进度\"变成\"系统主动告知结果\"，同时通过AI质检实现服务标准化，减少个体差异带来的体验波动。\n\n5、驱动成本与体验的平衡：通过策略手段推动减损产出提升、赔付成本优化，同时守住满意度和投诉率底线；借助AI能力实现理赔时效缩短与服务标准化，在降本的同时用效率换体验，而非单纯压缩赔付\n\n6、结合AI应用，协同理赔中台的规划与落地，挖掘 AI 在保险理赔全链路的应用价值——涵盖自动化理赔审核（通过 OCR、智能审核、风控反诈等Agent技术缩短理赔周期、提高理赔质量）；推动 AI 理赔应用能力的平台化沉淀与跨业务复用，驱动理赔效能提升和成本压降。","requirements":"1、AI认知与应用意识：不强制要求会写代码，但需要理解AI能力的边界——能判断\"这个环节适合AI做还是人做\"，能把理赔底层业务规则描述得足够清晰让技术侧实现AI自动执行；有AI/大模型项目参与经验者优先，有创新意识、敢想的优先。\n\n2、理赔/风控策略实战经验：5年及以上保险理赔相关工作经验，实际参与过作业模式设计、核赔规则制定、风控策略设计或赔付成本管控，除执行层面外，需要对理赔管理熟知。\n\n3、成本-体验-效率三角思维：理赔策略的核心难题是三者之间的平衡取舍。需要理解\"降获赔率可能带来投诉\"、\"提速可能放过风险\"这类真实业务矛盾，并能设计兼顾多目标的策略方案，而非只会单维度优化。\n\n4、多方协同推动力：理赔涉及保司、产研、运营、业务等多方，需要能在复杂利益格局中推动事情落地。\n\n5、规则结构化与AI协作能力：能把复杂业务场景抽象为清晰的规则逻辑——什么条件下赔、赔多少、走什么通道。这是和AI协作的基础：定义的规则越清晰，AI执行得越准。需要理解AI能做什么、适合做什么、边界在哪里。\n\n6、多线程工作能力：理赔策略涉及多条业务线（骑手险、生意保、健康险等）、多个相关方（作业团队、保司、业务方等）、多维指标同时推进，需要能在高并发会议和快速变化的业务节奏中保持输出质量","description":"部门介绍\n美团金融服务平台成立于2016年，以“场景+金融”模式，携手合作伙伴构建开放生态，为美团平台用户和商户提供底层账户、支付通道、信贷、保险和理财等金融解决方案。我们致力于以科技为核心，助力金融机构打通金融普惠“最后一公里”。我们期待与大家共同完成每一件平凡而卓越的事情，一起为用户提供优质的产品体验，守护用户的资金安全，让生活变得更美好。\n\n岗位职责\n1、制定与迭代优化理赔模式和核赔规则：负责理赔策略设计，覆盖人伤医疗费扣减、伤残减损逻辑、车物成本管控、估损模型优化等；将核赔规则结构化为AI可自动执行的决策逻辑，推动从\"人逐案审\"到\"AI按规则判、人维护规则\"的模式转变\n\n2、保司运营与管理：负责合作保司的日常运营管理，包括保司理赔作业质量监控、核心指标追踪与对齐、保司端理赔动作异常的预警与介入；推动保司侧理赔流程标准化，确保向日葵与保司形成互补分工、协同高效的作业格局；探索用AI对保司作业质量进行实时监测与异常预警，替代传统滞后的人工抽检和周报盘点。\n\n3、设计风控策略并推动落地：构建倒签单识别、异常就医模式检测、关联异常预警等风控能力；推动风控从\"事后抽检\"转向\"AI实时识别\"——让每case进来瞬间就完成风险扫描，而非依赖人工回溯发现问题。\n\n4、理赔体验策略：负责理赔满意度提升与投诉率治理，设计理赔时效优化、估损偏差收敛、主动沟通触达等体验策略；关注用户全旅程中的体验断点，从报案、审核、赔付到结案每个环节找到改善空间；利用AI实现理赔进度智能推送、用户诉求预判与主动干预，让\"用户追着问进度\"变成\"系统主动告知结果\"，同时通过AI质检实现服务标准化，减少个体差异带来的体验波动。\n\n5、驱动成本与体验的平衡：通过策略手段推动减损产出提升、赔付成本优化，同时守住满意度和投诉率底线；借助AI能力实现理赔时效缩短与服务标准化，在降本的同时用效率换体验，而非单纯压缩赔付\n\n6、结合AI应用，协同理赔中台的规划与落地，挖掘 AI 在保险理赔全链路的应用价值——涵盖自动化理赔审核（通过 OCR、智能审核、风控反诈等Agent技术缩短理赔周期、提高理赔质量）；推动 AI 理赔应用能力的平台化沉淀与跨业务复用，驱动理赔效能提升和成本压降。\n\n岗位基本要求\n1、AI认知与应用意识：不强制要求会写代码，但需要理解AI能力的边界——能判断\"这个环节适合AI做还是人做\"，能把理赔底层业务规则描述得足够清晰让技术侧实现AI自动执行；有AI/大模型项目参与经验者优先，有创新意识、敢想的优先。\n\n2、理赔/风控策略实战经验：5年及以上保险理赔相关工作经验，实际参与过作业模式设计、核赔规则制定、风控策略设计或赔付成本管控，除执行层面外，需要对理赔管理熟知。\n\n3、成本-体验-效率三角思维：理赔策略的核心难题是三者之间的平衡取舍。需要理解\"降获赔率可能带来投诉\"、\"提速可能放过风险\"这类真实业务矛盾，并能设计兼顾多目标的策略方案，而非只会单维度优化。\n\n4、多方协同推动力：理赔涉及保司、产研、运营、业务等多方，需要能在复杂利益格局中推动事情落地。\n\n5、规则结构化与AI协作能力：能把复杂业务场景抽象为清晰的规则逻辑——什么条件下赔、赔多少、走什么通道。这是和AI协作的基础：定义的规则越清晰，AI执行得越准。需要理解AI能做什么、适合做什么、边界在哪里。\n\n6、多线程工作能力：理赔策略涉及多条业务线（骑手险、生意保、健康险等）、多个相关方（作业团队、保司、业务方等）、多维指标同时推进，需要能在高并发会议和快速变化的业务节奏中保持输出质量\n\n具备以下条件优先\n1、有AI/大模型项目参与经验、有创新意识、敢想的优先\n\n2、有头部财险保司总部一年以上工作经验者优先\n\n岗位亮点\n1、AI理赔已进入规模化落地阶段——理赔AI项目已实际上线倒签单识别，年底前还有5个Agent陆续落地。加入的不是一个\"未来要做AI\"的团队，而是一个AI已经在跑、正在快速迭代的团队。策略岗在其中的角色是定义AI执行的规则——写的每条规则，直接决定线上AI的决策质量。\n\n2、真正在定义\"AI怎么做理赔\"——不是旁观AI浪潮，而是直接参与规则定义。写的规则决定了AI的决策质量，工作产出在线上实时跑着。\n\n3、业务结果可见、可量化——综合项目收益过亿级别，每条策略优化都有明确的成本/体验/效率产出，不是做完就放抽屉的方案。\n\n4、高频场景锤炼能力——骑手险日均理赔量大、险种覆盖全（车物+人伤+伤残+死亡），业务复杂度高但反馈周期短。一条策略上线几天就能看到效果数据，试错成本可控、成长速度快，远超低频险种。\n\n5、多线业务视野，不是螺丝钉——同时覆盖向日葵理赔、人保/太保等保司合作理赔，能接触到不同作业模式和合作方管理逻辑。从成本、体验、效率三个维度理解理赔全貌，而非只做单一模块。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4508499303","sourceKey":"meituan_social","company":"美团","title":"Keemart-仓储经理","city":"利雅得","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4508499303&jobShareType=1","duty":"1. 负责沙特地区物流运营的规划与管理，确保日常运营高效、成本卓越。  \n2. 持续优化仓储、运输及配送环节，提升运营效率并控制成本。  \n3. 制定并执行物流运营标准操作流程，推动团队标准化作业。  \n4. 监控关键绩效指标，定期分析运营数据并提出改进方案。  \n5. 协调内外部的资源，提升客户满意度。","requirements":"1. 大学本科及以上学历，物流、供应链或相关专业优先。  \n2. 具备5年以上物流运营相关工作经验，有中东地区经验者优先。  \n3. 具备优秀的沟通协调能力，英语流利者优先。","description":"部门介绍\n美团的使命是“帮大家吃得更好，生活更好”，公司聚焦“零售 + 科技”战略，和广大商户与各类合作伙伴一起，努力为消费者提供品质生活，推动商品零售和服务零售在需求侧和供给侧的数字化转型。\n2018年9月20日，美团正式在港交所挂牌上市。美团将始终坚持以客户为中心，不断加大在科技研发方面的投入，更好承担社会责任，更多创造社会价值，与广大合作伙伴一起发展共赢。\n\n岗位职责\n1. 负责沙特地区物流运营的规划与管理，确保日常运营高效、成本卓越。  \n2. 持续优化仓储、运输及配送环节，提升运营效率并控制成本。  \n3. 制定并执行物流运营标准操作流程，推动团队标准化作业。  \n4. 监控关键绩效指标，定期分析运营数据并提出改进方案。  \n5. 协调内外部的资源，提升客户满意度。\n\n岗位基本要求\n1. 大学本科及以上学历，物流、供应链或相关专业优先。  \n2. 具备5年以上物流运营相关工作经验，有中东地区经验者优先。  \n3. 具备优秀的沟通协调能力，英语流利者优先。\n\n岗位亮点\nKeemart海外业务快速发展，持续深耕零售行业。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4556081738","sourceKey":"meituan_social","company":"美团","title":"流量策略运营经理","city":"上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4556081738&jobShareType=1","duty":"负责大众点评App的Push的运营工作，为触达效率和消息质量负责。\n1、挖掘并定义触达场域内的用户需求，引入优质内容供给，协同产研团队探索消息供给的系统化能力建设；\n2、主导Push的热点运营、活动运营和场景运营能力建设，提升Push场景的DAU渗透和业务流量分发效率；\n3、熟悉Push的厂商合作生态，对付费权益有基本了解，有成本意识和操盘能力；\n4、制定运营分发标准、质量评测标准和运营管理审核制度，提升触达规模和触达质量。","requirements":"1、3年及以上触达类产品的运营经验，良好的用户sense、数据分析能力；\n2、有合作共赢的心态，具备良好的沟通能力，擅长跨团队的沟通协调工作；\n3、有韧性、有责任心、细致认真。","description":"部门介绍\n大众点评作为国内重要的本地生活消费决策参考平台，多年来深耕本地生活消费领域，深受广大用户的信任和喜爱。我们的业务覆盖了吃喝玩乐游购娱等生活场景，通过极具辨识度和公信力的”星级“和”评价“产品，为数亿用户提供了全面、可信的消费决策依据。为更好满足用户探索城市的需求，大众点评在原有星级和评价的基础上，以信息流产品形式，助力用户发现更多好去处。大量优秀年轻同学的加入，为我们的团队注入了澎湃活力。我们相信，真实的生活是不可替代的，真实的感受是值得记录的，真实的美好是要被看到的。希望优秀的你能和我们一起，帮助广大用户在大众点评上发现更多好去处，找到属于自己的人间烟火气，共创美好生活。\n\n岗位职责\n负责大众点评App的Push的运营工作，为触达效率和消息质量负责。\n1、挖掘并定义触达场域内的用户需求，引入优质内容供给，协同产研团队探索消息供给的系统化能力建设；\n2、主导Push的热点运营、活动运营和场景运营能力建设，提升Push场景的DAU渗透和业务流量分发效率；\n3、熟悉Push的厂商合作生态，对付费权益有基本了解，有成本意识和操盘能力；\n4、制定运营分发标准、质量评测标准和运营管理审核制度，提升触达规模和触达质量。\n\n岗位基本要求\n1、3年及以上触达类产品的运营经验，良好的用户sense、数据分析能力；\n2、有合作共赢的心态，具备良好的沟通能力，擅长跨团队的沟通协调工作；\n3、有韧性、有责任心、细致认真。\n\n具备以下条件优先\n有应用AI工具实际提升运营效率的经验优先。\n\n岗位亮点\n1、业务复杂度高，成长性好；\n2、团队氛围良好，学习型、目标导向型团队。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3035198133","sourceKey":"meituan_social","company":"美团","title":"充电宝渠道-渠道经理-河南","city":"郑州市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3035198133&jobShareType=1","duty":"1.负责充电宝渠道在下沉战区的业务开发和渠道管理工作，制定并实施相关销售策略和计划。\n2.负责团队建设和管理，包括招聘、培训、绩效评估等，确保团队成员的工作效率和业绩达到预期目标。\n3.策划并组织营销活动，提升充电宝产品在下沉战区市场的知名度和销售量。\n4.负责与渠道合作伙伴的沟通和合作，建立并维护良好的合作关系，提升充电宝产品在渠道中的销售渗透率。\n5.监控市场竞争情况，收集、整理并分析市场数据，及时调整销售策略，提供有效的市场反馈和建议。","requirements":"1.大学专科及以上学历，具备相关专业背景。\n2.至少3年以上充电宝渠道管理或业务开发经验，熟悉下沉战区市场特点和渠道管理的工作流程。\n3.具备良好的沟通能力和团队管理能力，能够有效协调团队成员的工作并推动团队业绩的提升。\n4.具备较强的市场分析和判断能力，对市场趋势和竞争对手的情况有准确的把握和分析能力。\n5.具备较强的执行力，能够在多条线工作中保持良好的工作状态和积极的工作态度。","description":"部门介绍\n美团充电宝是服务零售中的共享租赁业务，承接美团使命，致力让大家充电更简单。美团充电宝业务以应急充电功能为服务核心，覆盖吃喝玩乐生活全场景。目前，已在全国超过2000多个城市的餐饮、娱乐、机场、地铁、火车站、医院、学校、景区等公共区域及场所提供充电服务，铺设机柜超过百万，有KA、直营、渠道合作商多种业务模式，随时随地保障和满足消费者的充电需求。我们的业务资产数量多、场景多元化，追求精益管理。我们的团队大咖云集，崇尚自主驱动，求真务实。我们正处在快速发展期，规模持续增长，目标是市场规模和利润水平双第一。我们的管理者关注团队每个成员的成长，为每个人提供适合自身发展的机会。广阔天地、大有作为，美团充电宝期待你的加入！\n\n岗位职责\n1.负责充电宝渠道在下沉战区的业务开发和渠道管理工作，制定并实施相关销售策略和计划。\n2.负责团队建设和管理，包括招聘、培训、绩效评估等，确保团队成员的工作效率和业绩达到预期目标。\n3.策划并组织营销活动，提升充电宝产品在下沉战区市场的知名度和销售量。\n4.负责与渠道合作伙伴的沟通和合作，建立并维护良好的合作关系，提升充电宝产品在渠道中的销售渗透率。\n5.监控市场竞争情况，收集、整理并分析市场数据，及时调整销售策略，提供有效的市场反馈和建议。\n\n岗位基本要求\n1.大学专科及以上学历，具备相关专业背景。\n2.至少3年以上充电宝渠道管理或业务开发经验，熟悉下沉战区市场特点和渠道管理的工作流程。\n3.具备良好的沟通能力和团队管理能力，能够有效协调团队成员的工作并推动团队业绩的提升。\n4.具备较强的市场分析和判断能力，对市场趋势和竞争对手的情况有准确的把握和分析能力。\n5.具备较强的执行力，能够在多条线工作中保持良好的工作状态和积极的工作态度。\n\n具备以下条件优先\n1、充电宝渠道管理经验者优先。\n2、渠道管理工作经验优先。\n\n岗位亮点\n1.有机会参与充电宝在下沉战区市场的战略规划和渠道拓展工作，为公司的业务发展做出重要贡献。\n2.可以带领一个团队，通过团队的协作和努力，共同实现销售目标并提升团队业绩。\n3.能够与渠道合作伙伴进行深入合作，扩大充电宝产品在下沉战区市场的影响力和市场份额。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4426395637","sourceKey":"meituan_social","company":"美团","title":"四川区域酒店业务经理","city":"成都市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4426395637&jobShareType=1","duty":"1.商家运营。通过电话沟通、出差上门，对合作中商家进行全面诊断分析，找到商家目前存在的问题，给到商家合适的经营方案；\n2.客户拓展。邀约未和美团合作的酒店入驻上线；\n3.通过和酒店商户洽谈拿回更有优势的产品，提升酒店整体美团间夜量；\n4.协助商家处理售后问题，例如财务、各类活动、价格调整、到期续签等日常运营事务。","requirements":"1.具备较强的谈判能力、自我管理能力、沟通理解能力，愿意接受挑战；\n\n2.具备线上沟通销售运营能力，线下面销运营能力。","description":"部门介绍\n美团酒店旅行业务涵盖酒店、民宿、机票、火车票、旅游度假、景点门票等各类住行游品类，通过与产业上下游的深度合作，为用户提供美好的旅游旅行体验。我们积极打造AI友好型组织，使用AI等新技术提升旅游服务的供需匹配效率，更好满足用户个性化、多样化的出游需求。我们持续深耕产业链，用数字化服务助力实体商家高质量经营，探索自有品牌等供给新模式，打造健康的商家生态，保障用户服务体验。为满足用户日益增长的跨境旅行需求，我们将聚焦亚太区域，打造高品质的住宿、交通、游玩等服务矩阵。\n这里有多元的业务布局、持续的成长空间，无论是向往的远方还是眼前的工作，一路都是风景相伴。加入我们，共同为用户创造旅游旅行中的高光时刻！\n\n岗位职责\n1.商家运营。通过电话沟通、出差上门，对合作中商家进行全面诊断分析，找到商家目前存在的问题，给到商家合适的经营方案；\n2.客户拓展。邀约未和美团合作的酒店入驻上线；\n3.通过和酒店商户洽谈拿回更有优势的产品，提升酒店整体美团间夜量；\n4.协助商家处理售后问题，例如财务、各类活动、价格调整、到期续签等日常运营事务。\n\n岗位基本要求\n1.具备较强的谈判能力、自我管理能力、沟通理解能力，愿意接受挑战；\n\n2.具备线上沟通销售运营能力，线下面销运营能力。\n\n岗位亮点\n1.有机会参与并推动公司业务的快速发展，为平台的用户提供更好的服务和体验。\n2.可以通过与各类商户合作，拓展自己的商务拓展能力和人脉资源。\n3.在运营过程中，能够学习和应用市场分析和数据分析的技能，提升自己的运营策略和决策能力。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4019648255","sourceKey":"meituan_social","company":"美团","title":"四川区域酒店业务经理","city":"成都市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4019648255&jobShareType=1","duty":"1.商家运营。通过电话沟通、出差上门，对合作中商家进行全面诊断分析，找到商家目前存在的问题，给到商家合适的经营方案；\n2.客户拓展。邀约未和美团合作的酒店入驻上线；\n3.通过和酒店商户洽谈拿回更有优势的产品，提升酒店整体美团间夜量；\n4.协助商家处理售后问题，例如财务、各类活动、价格调整、到期续签等日常运营事务。","requirements":"岗位基本需求\n1.具备较强的谈判能力、自我管理能力、沟通理解能力，愿意接受挑战；\n2.具备线上沟通销售运营能力，线下面销运营能力；\n3.具备强责任心、耐心， 能适应出差，敢拼敢冲。\n4. 有酒店行业经验优先。","description":"部门介绍\n美团酒店旅行业务涵盖酒店、民宿、机票、火车票、旅游度假、景点门票等各类住行游品类，通过与产业上下游的深度合作，为用户提供美好的旅游旅行体验。我们积极打造AI友好型组织，使用AI等新技术提升旅游服务的供需匹配效率，更好满足用户个性化、多样化的出游需求。我们持续深耕产业链，用数字化服务助力实体商家高质量经营，探索自有品牌等供给新模式，打造健康的商家生态，保障用户服务体验。为满足用户日益增长的跨境旅行需求，我们将聚焦亚太区域，打造高品质的住宿、交通、游玩等服务矩阵。\n这里有多元的业务布局、持续的成长空间，无论是向往的远方还是眼前的工作，一路都是风景相伴。加入我们，共同为用户创造旅游旅行中的高光时刻！\n\n岗位职责\n1.商家运营。通过电话沟通、出差上门，对合作中商家进行全面诊断分析，找到商家目前存在的问题，给到商家合适的经营方案；\n2.客户拓展。邀约未和美团合作的酒店入驻上线；\n3.通过和酒店商户洽谈拿回更有优势的产品，提升酒店整体美团间夜量；\n4.协助商家处理售后问题，例如财务、各类活动、价格调整、到期续签等日常运营事务。\n\n岗位基本要求\n岗位基本需求\n1.具备较强的谈判能力、自我管理能力、沟通理解能力，愿意接受挑战；\n2.具备线上沟通销售运营能力，线下面销运营能力；\n3.具备强责任心、耐心， 能适应出差，敢拼敢冲。\n4. 有酒店行业经验优先。\n\n岗位亮点\n1. 团队氛围年轻活跃，注重个人成长。  \n2.可以通过与各类商户合作，拓展自己的商务拓展能力和人脉资源；\n3.在运营过程中，能够学习和应用市场分析和数据分析的技能，提升自己的运营策略和决策能力。\n4.完善的培训体系和晋升通道。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:2682118682","sourceKey":"meituan_social","company":"美团","title":"分销-销售BD（北京广州深圳）","city":"北京市/深圳市/广州市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=2682118682&jobShareType=1","duty":"1、负责美团平台在当地市场酒店第三方渠道的对接和运营；\n2、通过市场数据、行业案例和调研走访梳理出业务开展形态与结果间的逻辑关系；\n3、结合平台战略、战区策略以及现状制定发展目标和落地阶段策略；执行平台、战区战略或策略意图，主动对标策略落地实施步骤，及时反馈市场动向、产品问题、用户需求并向战区提供策略制定的参考意见、依据和建议；\n4、围绕目标和落地策略盘点整合内外部资源；\n5、在业务推进过程中聚焦业务痛点和市场增长点，向上推动系统和资源建设，向下梳理优化流程和业务战术；\n6、赋能商家，通过复盘、分享、业务培训渠道运营能力，积累沉淀下来一套可复制的业务流程规范。","requirements":"1、具有良好沟通和协调能力，特别是在与渠道代理商的商务谈判方面，可以完成新签商家并且拿回酒店资源上线；\n2、擅长挖掘市场信息与主动探索陌生市场资源，对业务整体协调及把控能力强；\n3、具有行业敏锐性和学习能力，能对业务实时动态及时把握，过往从事过多种行业且均拿到不错结果。\n4、具有良好的数据分析能力、项目复盘能力、逻辑思考能力。","description":"部门介绍\n美团酒店旅行业务涵盖酒店、民宿、机票、火车票、旅游度假、景点门票等各类住行游品类，通过与产业上下游的深度合作，为用户提供美好的旅游旅行体验。我们积极打造AI友好型组织，使用AI等新技术提升旅游服务的供需匹配效率，更好满足用户个性化、多样化的出游需求。我们持续深耕产业链，用数字化服务助力实体商家高质量经营，探索自有品牌等供给新模式，打造健康的商家生态，保障用户服务体验。为满足用户日益增长的跨境旅行需求，我们将聚焦亚太区域，打造高品质的住宿、交通、游玩等服务矩阵。\n这里有多元的业务布局、持续的成长空间，无论是向往的远方还是眼前的工作，一路都是风景相伴。加入我们，共同为用户创造旅游旅行中的高光时刻！\n\n岗位职责\n1、负责美团平台在当地市场酒店第三方渠道的对接和运营；\n2、通过市场数据、行业案例和调研走访梳理出业务开展形态与结果间的逻辑关系；\n3、结合平台战略、战区策略以及现状制定发展目标和落地阶段策略；执行平台、战区战略或策略意图，主动对标策略落地实施步骤，及时反馈市场动向、产品问题、用户需求并向战区提供策略制定的参考意见、依据和建议；\n4、围绕目标和落地策略盘点整合内外部资源；\n5、在业务推进过程中聚焦业务痛点和市场增长点，向上推动系统和资源建设，向下梳理优化流程和业务战术；\n6、赋能商家，通过复盘、分享、业务培训渠道运营能力，积累沉淀下来一套可复制的业务流程规范。\n\n岗位基本要求\n1、具有良好沟通和协调能力，特别是在与渠道代理商的商务谈判方面，可以完成新签商家并且拿回酒店资源上线；\n2、擅长挖掘市场信息与主动探索陌生市场资源，对业务整体协调及把控能力强；\n3、具有行业敏锐性和学习能力，能对业务实时动态及时把握，过往从事过多种行业且均拿到不错结果。\n4、具有良好的数据分析能力、项目复盘能力、逻辑思考能力。\n\n具备以下条件优先\n酒店销售总监及以上\n代理商行业从业者\nota销售运营人员\n以上优先。\n\n岗位亮点\n深入了解酒店渠道供应链行业采购，从采购到销售一体的闭环体系，帮助伙伴在垂直业务上更深入的闭环，并通过sop的梳理系统化的形成作战方法论。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4633968809","sourceKey":"meituan_social","company":"美团","title":"小象超市工程经理-北京","city":"北京市/天津市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4633968809&jobShareType=1","duty":"1. 制度与体系：结合业务模式拟定工程管理制度并严格落实，建立符合小象超市业态特点的项目管理标准化流程，保障项目安全高效推进；\n2. 全面管控：对工程项目的进度、质量、成本、安全进行全面把控，持续优化项目管理模式，做好指导、监督与考核，确保批量开店目标达成；\n3. 多方协同：组织设计、施工、供应商等多方会审，主导重要物料及工程验收备案；实时监督总包/分包履约状况，敏锐捕捉工程问题并迅速给出整改方案；\n4. 选址与交接：实地勘察场地，协同拓展部明确技术条件，助力完成选址、签约与场地交接，对门店的工程可行性提供专业判断；\n5. 结算与审计：严谨审查竣工图纸与结算资料，推动审计结算进程，配合完成结算闭环，有效控制工程超支风险；\n6. 报批报建：牵头负责施工及消防报批报建工作，获取开工许可等审批文件，熟练应对各地政策差异；\n7. 供应商管理：以设计标准为指引管理供应商体系，驱动培训考核，持续提升施工执行能力和材料品控水平；\n8. 数字化工程管控：推动工程管理数字化落地——运用BIM/数字孪生进行施工前预演和图纸审查；\n9. 借助AI辅助工具（如AI图纸合规检查、AI工期/成本预警）提升工程决策效率；\n10. 借助智能工单系统实现多项目并行的进度追踪和问题闭环；配合门店智能化改造，完成IoT设备（冷链监控、能耗管理、智能安防）调试与验收交付。","requirements":"1. 5年以上连锁商超或餐饮工程管理实践经验；\n2. 工程、土木、机电专业出身优先熟悉商超/餐饮工程各类标准、规范、技术方案及常用设备（制冷/强弱电/消防等）\n3. 精通工程管理、招投标、成本管控流程，具备独立管理多项目并行能力拥有施工报建、消防报审全流程实操经验具备良好的跨部门沟通协调能力，能有效推动多方资源协同\n4. 具备BIM基础操作能力，或使用过工程数字化工具\n5. 有使用AI工具辅助工程工作的经验（如AI图纸审查、AI工程文档生成、AI成本测算等工具）","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1. 制度与体系：结合业务模式拟定工程管理制度并严格落实，建立符合小象超市业态特点的项目管理标准化流程，保障项目安全高效推进；\n2. 全面管控：对工程项目的进度、质量、成本、安全进行全面把控，持续优化项目管理模式，做好指导、监督与考核，确保批量开店目标达成；\n3. 多方协同：组织设计、施工、供应商等多方会审，主导重要物料及工程验收备案；实时监督总包/分包履约状况，敏锐捕捉工程问题并迅速给出整改方案；\n4. 选址与交接：实地勘察场地，协同拓展部明确技术条件，助力完成选址、签约与场地交接，对门店的工程可行性提供专业判断；\n5. 结算与审计：严谨审查竣工图纸与结算资料，推动审计结算进程，配合完成结算闭环，有效控制工程超支风险；\n6. 报批报建：牵头负责施工及消防报批报建工作，获取开工许可等审批文件，熟练应对各地政策差异；\n7. 供应商管理：以设计标准为指引管理供应商体系，驱动培训考核，持续提升施工执行能力和材料品控水平；\n8. 数字化工程管控：推动工程管理数字化落地——运用BIM/数字孪生进行施工前预演和图纸审查；\n9. 借助AI辅助工具（如AI图纸合规检查、AI工期/成本预警）提升工程决策效率；\n10. 借助智能工单系统实现多项目并行的进度追踪和问题闭环；配合门店智能化改造，完成IoT设备（冷链监控、能耗管理、智能安防）调试与验收交付。\n\n岗位基本要求\n1. 5年以上连锁商超或餐饮工程管理实践经验；\n2. 工程、土木、机电专业出身优先熟悉商超/餐饮工程各类标准、规范、技术方案及常用设备（制冷/强弱电/消防等）\n3. 精通工程管理、招投标、成本管控流程，具备独立管理多项目并行能力拥有施工报建、消防报审全流程实操经验具备良好的跨部门沟通协调能力，能有效推动多方资源协同\n4. 具备BIM基础操作能力，或使用过工程数字化工具\n5. 有使用AI工具辅助工程工作的经验（如AI图纸审查、AI工程文档生成、AI成本测算等工具）\n\n岗位亮点\n有机会全身心地参与新零售业态，和团队一起更快速、更有效的完成工程筹建，提升个人能力； 能和电商、物流、零售、人工智能等多元化背景的团队技术大牛一起，综合学习，共同进步；工程团队的图纸审查、进度预警、成本分析都在探索AI辅助，你将有机会成为\"AI+工程管理\"这个新方向的先行者","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4635755350","sourceKey":"meituan_social","company":"美团","title":"美团企业版-KA客户成功经理","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4635755350&jobShareType=1","duty":"1.负责工作餐/商务宴请/差旅等方向的客户运营及服务管理，对老客户的留存、稳定运营、交叉销售、转介绍以及新客的持续放量负责；\n2.与客户建立信任关系，收集和解决客户KP对产品和服务的反馈，准确识别客户需求和痛点，对产品和服务流程提出优化建议； \n3.负责协调内部资源，解决客户问题和投诉；\n4.对客户的满意度负责，不断地总结、提炼并向客户传递优质实践；\n5.能对客户需求进行二次开发，提升客户的内部使用率和GMV，进而提升业务营收。","requirements":"1.大学本科及以上学历，市场营销、商务管理等相关专业优先考虑；\n2.至少1年以上大客户业务开发或客户成功经验，熟悉大客户管理流程和销售策略；\n3.具备良好的沟通能力和谈判技巧，能够与各级别客户进行有效的沟通和合作；\n4.具备较强的市场分析能力和业务拓展能力，能够准确把握市场趋势和客户需求；\n5.具备团队合作精神，能够独立完成工作任务，有较强的问题解决能力；","description":"部门介绍\n美团平台为用户的基础产品体验负责，还承担了美团的用户增长、市场和品牌营销以及多条业务线的产品设计职责，建立了融合文字、图片、视频和直播等不同形式的內容生态系统，同时整合地图服务部、客户服务和体验部、企业业务部、网约车业务部等部门，致力于用科技提升美团数亿消费者、近千万商家、骑手、司机和团长的服务体验。美团平台拥有高并发、多业务的复杂场景，为技术深度优化提供了最佳实践可能。这里有简单、讲逻辑、有爱的团队，更是一块理想的实战场地，舞台广阔，欢迎你来尽情施展。\n\n岗位职责\n1.负责工作餐/商务宴请/差旅等方向的客户运营及服务管理，对老客户的留存、稳定运营、交叉销售、转介绍以及新客的持续放量负责；\n2.与客户建立信任关系，收集和解决客户KP对产品和服务的反馈，准确识别客户需求和痛点，对产品和服务流程提出优化建议； \n3.负责协调内部资源，解决客户问题和投诉；\n4.对客户的满意度负责，不断地总结、提炼并向客户传递优质实践；\n5.能对客户需求进行二次开发，提升客户的内部使用率和GMV，进而提升业务营收。\n\n岗位基本要求\n1.大学本科及以上学历，市场营销、商务管理等相关专业优先考虑；\n2.至少1年以上大客户业务开发或客户成功经验，熟悉大客户管理流程和销售策略；\n3.具备良好的沟通能力和谈判技巧，能够与各级别客户进行有效的沟通和合作；\n4.具备较强的市场分析能力和业务拓展能力，能够准确把握市场趋势和客户需求；\n5.具备团队合作精神，能够独立完成工作任务，有较强的问题解决能力；\n\n具备以下条件优先\n1.有互联网SaaS、企业服务等方向的客户经理从业经验者优先； \n2.看好To B（To 企业） 的大方向，期待投身其中建功立业； \n3.有商旅行业运营和项目管理工作经验优先\n4.拥抱AI，懂得如何使用AI工具提效\n\n岗位亮点\n美团企业版主要面向企业，为其提供“企业消费管理”一站式服务解决方案，覆盖企业差旅、企业用餐、企业招待宴请、企业用车等多种场景。此岗位能接触美团多种业务场景，工作半径大、视野广、挑战足；团队人际简单，求真务实的工作氛围。\n1.【新业务】美团内部孵化的、专门面向企业市场的To B业务。为“企业因公消费管理”提供一站式SaaS服务，涵盖企业商旅、用餐、用车、报销费控等多个领域（这些领域已经在服务美团自身）\n2.【空间大】公务消费有数万亿的大盘，有足够的想象力；该业务会涉及外卖、到店餐饮、酒店、机票、火车、打车等业务类型，能给大家提供足够的学习成长空间； \n3.【有希望】To B的大势刚刚开始，依托于美团过去10年的积累，依托于对美团自身服务的积累，很有机会把业务做大做成； \n4.【氛围好】务实求真，创业氛围；人际简单，组织扁平。这是一个巨大的机会，也需要长期的耐心；To B星辰大海，征程期待有你。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4643609316","sourceKey":"meituan_social","company":"美团","title":"产品运营-合作中心平台及商家运营","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4643609316&jobShareType=1","duty":"1.负责外卖业务外部服务商、品牌商的引入和维护，结合业务信息、行业信息、竞争信息制定合作策略，提升业务渗透率与商户覆盖数。\n2.负责外卖业务三方对接的全流程（包括不限于入驻、权限审批、系统运维、经营管理等）设计，结合系统能力升级、数据分析洞察持续优化对接过程，提升外部客户的对接效率及体验。\n3.负责三方合作风险的预防及处置工作，与信安、风控、业务等部门共同设计风险评价体系、识别策略、协作机制，建立监控预警及响应机制。\n4.探索服务市场和联合售卖能力，提升三方伙伴活跃度及与外卖业务的合作深度。建设并运营服务者社区，通过标杆案例、生态伙伴评选、官方认证、积分激励等玩法，搭建沟通桥梁，提高活跃频次，深化合作关系。","requirements":"1.3年以上中后台系统产品运营工作经验，负责过中大型复杂系统全链路产品运营，有合作管理、生态运营经验优先。\n2.优秀的沟通协调及资源管理能力，有一定的商业思维及谈判技巧，能够洞察双边合作的机会空间。聚焦核心目标，带领多角色、多职能高效合作。\n3.具备突出的风险意识，有安全风险治理、合规运营、风险策略经验者优先。\n4.具备需求分析洞察能力及逻辑思维能力，能通过多种数据分析方法和工具（如SQL、Python）提供数据驱动的产品规划及策略。","description":"部门介绍\n美团平台为用户的基础产品体验负责，还承担了美团的用户增长、市场和品牌营销以及多条业务线的产品设计职责，建立了融合文字、图片、视频和直播等不同形式的內容生态系统，同时整合地图服务部、客户服务和体验部、企业业务部、网约车业务部等部门，致力于用科技提升美团数亿消费者、近千万商家、骑手、司机和团长的服务体验。美团平台拥有高并发、多业务的复杂场景，为技术深度优化提供了最佳实践可能。这里有简单、讲逻辑、有爱的团队，更是一块理想的实战场地，舞台广阔，欢迎你来尽情施展。\n\n岗位职责\n1.负责外卖业务外部服务商、品牌商的引入和维护，结合业务信息、行业信息、竞争信息制定合作策略，提升业务渗透率与商户覆盖数。\n2.负责外卖业务三方对接的全流程（包括不限于入驻、权限审批、系统运维、经营管理等）设计，结合系统能力升级、数据分析洞察持续优化对接过程，提升外部客户的对接效率及体验。\n3.负责三方合作风险的预防及处置工作，与信安、风控、业务等部门共同设计风险评价体系、识别策略、协作机制，建立监控预警及响应机制。\n4.探索服务市场和联合售卖能力，提升三方伙伴活跃度及与外卖业务的合作深度。建设并运营服务者社区，通过标杆案例、生态伙伴评选、官方认证、积分激励等玩法，搭建沟通桥梁，提高活跃频次，深化合作关系。\n\n岗位基本要求\n1.3年以上中后台系统产品运营工作经验，负责过中大型复杂系统全链路产品运营，有合作管理、生态运营经验优先。\n2.优秀的沟通协调及资源管理能力，有一定的商业思维及谈判技巧，能够洞察双边合作的机会空间。聚焦核心目标，带领多角色、多职能高效合作。\n3.具备突出的风险意识，有安全风险治理、合规运营、风险策略经验者优先。\n4.具备需求分析洞察能力及逻辑思维能力，能通过多种数据分析方法和工具（如SQL、Python）提供数据驱动的产品规划及策略。\n\n岗位亮点\n1.负责本地生活领域场景最丰富的技术开放平台运营。管理众多外部合作伙伴，深度服务了外卖、闪购、到店餐饮、服务零售等核心业务场景，直接影响业务供给质量和丰富度。\n2.结合美团核心业务场景与前沿技术能力直接赋能海量服务商与品牌商，了解头部行业动态，积累前沿经验，参与众多0-1建设的能力建设与运营，组织大型培训与展会，个人能力和职业发展双丰收。\n3.锻炼长链路工作环境下的跨团队协作能力，在美团生态价值深化与商业化的关键扩张期，拥有极大的空间去实践建设商家生态构想，亲手推动生态体系繁荣增长。\n4.学习美团体系下优秀管理者的方法论、思维模式，畅享内部各类音视频分享与培训，在高活力、创业型团队中快速成长。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4645838243","sourceKey":"meituan_social","company":"美团","title":"服务流程运营","city":"上海市/北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4645838243&jobShareType=1","duty":"1、负责统筹服务全流程和链路的设计与运营，持续改善客户/商户服务的工作流程、执行规范等基础制度，并能落地实施。\n2、持续提升客户服务解决能力，关注客户体验，建立有效的运营机制，赋能客服团队并提升其解决问题的能力。\n3、通过对行业/业务分析&调研、客户声音的洞察&分析等举措，发现痛点问题，与协同团队密切合作，推动问题从源头解决。\n4、负责与业务建立良好的协同关系，带领团队通过深入走访业务一线等方式熟悉业务运营的各个环节，识别有效问题，主动为业务团队提出改善建议并推动需求项目执行。\n5、引入AI工具辅助服务流程优化。","requirements":"1、本科及以上学历，3年以上客户服务行业经验。\n2、具备大中型复杂项目管理能力和较强的业务推动能力，有一定的目标导向，自驱力强。\n3、逻辑性强，具备较强的数据分析能力，能清楚的判断客户痛点，具备发现问题及主动改善能力，解析影响客户体验的具体因素，结构化输出合理化解决方案，并推动方案执行达成结果。\n4、能够协同或整合内外部资源 ，有团队合作精神，工作严谨踏实，责任心强。\n5、能够熟练运用AI工具和人机协作，具备岗位要求的AI能力。","description":"部门介绍\n美团平台为用户的基础产品体验负责，还承担了美团的用户增长、市场和品牌营销以及多条业务线的产品设计职责，建立了融合文字、图片、视频和直播等不同形式的內容生态系统，同时整合地图服务部、客户服务和体验部、企业业务部、网约车业务部等部门，致力于用科技提升美团数亿消费者、近千万商家、骑手、司机和团长的服务体验。美团平台拥有高并发、多业务的复杂场景，为技术深度优化提供了最佳实践可能。这里有简单、讲逻辑、有爱的团队，更是一块理想的实战场地，舞台广阔，欢迎你来尽情施展。\n\n岗位职责\n1、负责统筹服务全流程和链路的设计与运营，持续改善客户/商户服务的工作流程、执行规范等基础制度，并能落地实施。\n2、持续提升客户服务解决能力，关注客户体验，建立有效的运营机制，赋能客服团队并提升其解决问题的能力。\n3、通过对行业/业务分析&调研、客户声音的洞察&分析等举措，发现痛点问题，与协同团队密切合作，推动问题从源头解决。\n4、负责与业务建立良好的协同关系，带领团队通过深入走访业务一线等方式熟悉业务运营的各个环节，识别有效问题，主动为业务团队提出改善建议并推动需求项目执行。\n5、引入AI工具辅助服务流程优化。\n\n岗位基本要求\n1、本科及以上学历，3年以上客户服务行业经验。\n2、具备大中型复杂项目管理能力和较强的业务推动能力，有一定的目标导向，自驱力强。\n3、逻辑性强，具备较强的数据分析能力，能清楚的判断客户痛点，具备发现问题及主动改善能力，解析影响客户体验的具体因素，结构化输出合理化解决方案，并推动方案执行达成结果。\n4、能够协同或整合内外部资源 ，有团队合作精神，工作严谨踏实，责任心强。\n5、能够熟练运用AI工具和人机协作，具备岗位要求的AI能力。\n\n具备以下条件优先\n智能客服运营、大模型项目经验\n\n岗位亮点\n1、热门核心行业以及重点岗位，能够全面接触以及深入了解行业动态、服务策略等，有助于眼界开阔。\n2、有机会参与或统筹复杂业务场景中跨部门重大项目管理工作。\n3、专业可靠的工作搭子，团队关系融洽，工作学习氛围好，重视每个成员的个人发展。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4641139436","sourceKey":"meituan_social","company":"美团","title":"Training Specialist","city":"开罗","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4641139436&jobShareType=1","duty":"1. BPO Vendor Training Governance & Accountability (Primary)\n\nDedicated training POC for assigned BPO vendors, owning the full vendor training relationship end-to-end\nLead WBRs, calibration sessions, performance reviews, and escalation calls with structured documentation\nHold vendors accountable for training SLAs — trainer readiness, attendance, content adoption, nesting compliance, certification timelines\nValidate vendor-reported training data against internal metrics\n\n2. Vendor Performance Management & Intervention\n\nTrack vendor KPIs and proactively flag underperformance\nConduct root cause analysis\nDesign and enforce corrective action plans with measurable targets\nDrive vendor readiness for product/service launches\n\n3. Nesting & Onboarding Oversight\n\nOwn the Nesting Scorecard framework — scoring, evidence collection, graduation decisions\nOversee vendor new hire onboarding and validate curriculum coverage\nReview and approve vendor training plans per batch\n\n4. Training Delivery & Content Development\n\nDesign and deliver training as business needs arise — refreshers, launches, SOPs, workshops\nStep in directly when vendor-led delivery falls short\nMaintain SOPs, training decks, guides, and knowledge base articles\n\n5. Training Initiatives & Continuous Improvement\n\nDrive cross-vendor initiatives — assessment frameworks, accreditation, best-practice sharing\nImprove delivery methods, tools, and engagement models\nContribute to regional projects and strategic initiatives\n\n6. Reporting, Data & Stakeholder Communication\n\nMaintain the Master Tracker with accurate training records\nPrepare weekly/monthly reports with data-backed insights\nCollaborate cross-functionally with Ops, Quality, and BPI teams","requirements":"5+ years in training/L&D/vendor management in BPO/contact center\nTrack record managing vendor training across multiple sites/regions\nStrong grasp of industry metrics\nRCA and data-driven intervention experience\nContent development and facilitation skills\nExcellent stakeholder management\nFluent English and Arabic\nWillingness to travel within GCC","description":"部门介绍\nKeeta是全球领先外卖平台美团旗下的独立品牌，肩负着“帮大家吃得更好，生活更好”的使命。依托美团深耕中国市场15年的技术与运营积淀，我们正引领全球餐饮与商品即时配送服务的创新与发展。\n\n自2023年成立以来，Keeta始终扎根社区并创造价值。我们为用户提供可靠的外卖体验，以智慧技术助餐厅提升经营效率，在为骑手拓宽收入来源的同时，也充分提供安全保障措施。基于这份多方共赢、共同成长的理念，我们的业务已从中国香港稳步拓展至中东及巴西，并持续向世界迈进。\n\n岗位职责\n1. BPO Vendor Training Governance & Accountability (Primary)\n\nDedicated training POC for assigned BPO vendors, owning the full vendor training relationship end-to-end\nLead WBRs, calibration sessions, performance reviews, and escalation calls with structured documentation\nHold vendors accountable for training SLAs — trainer readiness, attendance, content adoption, nesting compliance, certification timelines\nValidate vendor-reported training data against internal metrics\n\n2. Vendor Performance Management & Intervention\n\nTrack vendor KPIs and proactively flag underperformance\nConduct root cause analysis\nDesign and enforce corrective action plans with measurable targets\nDrive vendor readiness for product/service launches\n\n3. Nesting & Onboarding Oversight\n\nOwn the Nesting Scorecard framework — scoring, evidence collection, graduation decisions\nOversee vendor new hire onboarding and validate curriculum coverage\nReview and approve vendor training plans per batch\n\n4. Training Delivery & Content Development\n\nDesign and deliver training as business needs arise — refreshers, launches, SOPs, workshops\nStep in directly when vendor-led delivery falls short\nMaintain SOPs, training decks, guides, and knowledge base articles\n\n5. Training Initiatives & Continuous Improvement\n\nDrive cross-vendor initiatives — assessment frameworks, accreditation, best-practice sharing\nImprove delivery methods, tools, and engagement models\nContribute to regional projects and strategic initiatives\n\n6. Reporting, Data & Stakeholder Communication\n\nMaintain the Master Tracker with accurate training records\nPrepare weekly/monthly reports with data-backed insights\nCollaborate cross-functionally with Ops, Quality, and BPI teams\n\n岗位基本要求\n5+ years in training/L&D/vendor management in BPO/contact center\nTrack record managing vendor training across multiple sites/regions\nStrong grasp of industry metrics\nRCA and data-driven intervention experience\nContent development and facilitation skills\nExcellent stakeholder management\nFluent English and Arabic\nWillingness to travel within GCC\n\n具备以下条件优先\nFood delivery / e-commerce / on-demand platform experience\nBPO vendor governance experience (SLAs, accountability)\nMulti-country training operations management\nLMS / e-learning authoring tool experience\nBuilt training programs/scorecards from scratch in scaling environments\nWFM concepts and capacity planning integration\nBI/analytics proficiency\nStrong professional writing skills\n\n岗位亮点\nWhat Sets You Apart:\nFood delivery / e-commerce / on-demand industry background\nNesting programs, certification frameworks, scorecard governance experience\nSix Sigma / Lean / CI methodology familiarity\nMulti-country/multi-market training management\nFramework builder, not just framework inheritor\nData-comfortable — dashboards, trackers, numbers to action\nSelf-starter who drives execution without waiting for direction\nThrives in fast-paced, high-growth, still-building environments","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3977379361","sourceKey":"meituan_social","company":"美团","title":"无人机-运管中心主任调度","city":"上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3977379361&jobShareType=1","duty":"1.运行区域安全负责人，负责区域内飞行任务分配以及紧急状态下的工单分配；\n2.运行机组成员管理，制定排班计划，保障工作有序开展；\n3.落实运行相关制度流程执行，带领机组依据《美团无人机运行手册》执飞；\n4.监控负责区域内无人机运行系统整体状态，遭遇异常时调度机组成员妥善处置；\n5.辅助运管中心负责人收集运行过程中的问题，产出解决方案，促进流程优化改进；\n6.机组能力提升，确保所辖飞行人员的实操技能、理论水平、异常处置能力符合岗位要求；\n7.运营工作流程优化提效，不断提升远程机组安全保障能力；\n8.完成临时性任务的统筹、规划、实施等工作；\n9.运行过程中异常问题的上报以及产生安全事件的后续处理。","requirements":"1. 本科及以上学历；\n2. 运行管理相关专业，例如机场运行服务与管理、轨道交通运营管理、航空物流管理、航空飞行、航空管理、智慧交通、交通工程、无人驾驶系统工程等相关专业；\n3. 工作领域：交通运输、地铁运营控制中心、物流调度、公安系统指挥中心等领域拥有多年运行或管理经验，涉及到在实时情况下对资源、任务或事件进行优化和分配及相应的问题分析能力；\n4. 担任过团队领导职位，或具备协调管理小组成员的能力和经验；\n5. 使用过监控系统实时监测交通、运输工具或设备的运行状态，及时发现异常情况并采取措施，有应急响应程序处置相关经验；\n6. 熟练使用电脑操作、监控系统、通信设备、数据分析工具、文档处理等技术工具，以便支持运行调度工作；\n7. 在安全操作前提下对新技术持开放学习态度，对AI在智能调度、告警、建议等方面的能力边界有基础认知。","description":"部门介绍\n为了更好地提升城市即时配送的效率与体验，2017年，美团启动了无人机配送服务的探索，通过科技创新推动履约工具变革，加快建设空地协同的本地即时配送网络。\n在过去的六年里，美团无人机完成了飞行器、自动化机场及智能调度系统的研发工作，实现了研发设计、生产制造、运营运维全链条布局，达成了城市复杂场景物流无人机高频次、高密度、多天时、多天侯运行。\n2023年7月，美团无人机在上海发布了自主研发的第四代无人机，跟此前机型相比，新机型升级了环境适应能力，可在“零下20度至50度”的中雨、中雪、6级风、弱光等环境中稳定飞行，能够适应97%以上国内城市的自然环境要求。\n截至2024年12月，美团无人机已在深圳、北京、上海、广州、南京、迪拜等城市开通53条航线，并累计完成订单超40万单。即时零售配送服务覆盖了办公、社区、景区、市政公园、校园、医疗、图书馆等多种场景。在医疗场景中，美团无人机可围绕医疗血液、检验样本、院前急救物资、特殊药品等医疗物资配送需求建设端到端的全天时急送网络。\n\n岗位职责\n1.运行区域安全负责人，负责区域内飞行任务分配以及紧急状态下的工单分配；\n2.运行机组成员管理，制定排班计划，保障工作有序开展；\n3.落实运行相关制度流程执行，带领机组依据《美团无人机运行手册》执飞；\n4.监控负责区域内无人机运行系统整体状态，遭遇异常时调度机组成员妥善处置；\n5.辅助运管中心负责人收集运行过程中的问题，产出解决方案，促进流程优化改进；\n6.机组能力提升，确保所辖飞行人员的实操技能、理论水平、异常处置能力符合岗位要求；\n7.运营工作流程优化提效，不断提升远程机组安全保障能力；\n8.完成临时性任务的统筹、规划、实施等工作；\n9.运行过程中异常问题的上报以及产生安全事件的后续处理。\n\n岗位基本要求\n1. 本科及以上学历；\n2. 运行管理相关专业，例如机场运行服务与管理、轨道交通运营管理、航空物流管理、航空飞行、航空管理、智慧交通、交通工程、无人驾驶系统工程等相关专业；\n3. 工作领域：交通运输、地铁运营控制中心、物流调度、公安系统指挥中心等领域拥有多年运行或管理经验，涉及到在实时情况下对资源、任务或事件进行优化和分配及相应的问题分析能力；\n4. 担任过团队领导职位，或具备协调管理小组成员的能力和经验；\n5. 使用过监控系统实时监测交通、运输工具或设备的运行状态，及时发现异常情况并采取措施，有应急响应程序处置相关经验；\n6. 熟练使用电脑操作、监控系统、通信设备、数据分析工具、文档处理等技术工具，以便支持运行调度工作；\n7. 在安全操作前提下对新技术持开放学习态度，对AI在智能调度、告警、建议等方面的能力边界有基础认知。\n\n具备以下条件优先\n1. 航空运行、轨道交通运行调度等领域从业经历；\n2. 取得过运行岗位专业资格认证，例如飞行调度员认证、轨道交通运营管理师专业认证等；\n3. 持有有效期内的民航局颁发的Ⅲ、IV类《民用无人机超视距驾驶员执照》；\n4.  有使用AI辅助飞行调度或运行监控系统的实际操作经验。\n\n岗位亮点\n1. 公司提供全方位培训和发展晋升机会，帮助提升业务所需技能，从而更好的履行岗位职责；\n2. 无人机运行调度及管理岗位将在未来继续增长，与传统行业相比前景更加广阔，为有志于从事这一领域的人才提供了广阔的发展晋升机会。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4376948247","sourceKey":"meituan_social","company":"美团","title":"小象超市-资深数据分析师","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4376948247&jobShareType=1","duty":"1.负责品质管理领域的数据分析工作，以支持品质管理决策。包括不限于指标体系建立，异常预警数据监控，品质异动归因诊断，改善落地动作的数据化识别，管理方法论的数据化沉淀。 \n2.负责品质管理团队绩效目标制定管理工作。\n3.跟进产品和供应链环节的数据，监控产品质量和品质管理绩效，并及时发现和解决潜在的质量问题。 \n4.协调跨部门团队，包括研发、生产、供应链等，建立和优化数据分析模型，共同推动品质提升。\n5.持续研究使用AI进行数据分析提效，帮助整个团队提升数据分析效率","requirements":"1.大学本科及以上学历，专业不限，统计、数学、计算机相关等专业优先，具备较强的数据分析和运营能力。 \n2.至少3年及以上数据分析/商业分析/策略运营/数据运营或相关领域工作经验，熟悉品质数据的收集、整理、分析和报告流程，零售行业商分经验优先。 \n3.具备较强的数据分析和解决问题的能力，精通SQL，熟练运用至少一种数据分析工具（如R、Python等）和常见统计分析方法，能够快速发现问题并提出解决方案。 \n4.具备良好的团队合作和沟通能力，能够有效协调多个部门的合作，推动品质数据运营工作的顺利进行。 \n5.工作责任心强，有较强的自我驱动能力。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1.负责品质管理领域的数据分析工作，以支持品质管理决策。包括不限于指标体系建立，异常预警数据监控，品质异动归因诊断，改善落地动作的数据化识别，管理方法论的数据化沉淀。 \n2.负责品质管理团队绩效目标制定管理工作。\n3.跟进产品和供应链环节的数据，监控产品质量和品质管理绩效，并及时发现和解决潜在的质量问题。 \n4.协调跨部门团队，包括研发、生产、供应链等，建立和优化数据分析模型，共同推动品质提升。\n5.持续研究使用AI进行数据分析提效，帮助整个团队提升数据分析效率\n\n岗位基本要求\n1.大学本科及以上学历，专业不限，统计、数学、计算机相关等专业优先，具备较强的数据分析和运营能力。 \n2.至少3年及以上数据分析/商业分析/策略运营/数据运营或相关领域工作经验，熟悉品质数据的收集、整理、分析和报告流程，零售行业商分经验优先。 \n3.具备较强的数据分析和解决问题的能力，精通SQL，熟练运用至少一种数据分析工具（如R、Python等）和常见统计分析方法，能够快速发现问题并提出解决方案。 \n4.具备良好的团队合作和沟通能力，能够有效协调多个部门的合作，推动品质数据运营工作的顺利进行。 \n5.工作责任心强，有较强的自我驱动能力。\n\n岗位亮点\n1、互联网大厂，晋升通道通畅，培训体系完整； \n2、食安与品质管理部为一级部门，发展空间大； \n3、小组工作氛围好，open，主管来自相关行业且商分背景，内部有完整的职业上升培养体系。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4641512434","sourceKey":"meituan_social","company":"美团","title":"快驴链路运营稽核","city":"广州市/深圳市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4641512434&jobShareType=1","duty":"适应长期出差，按稽核巡检要求，对链路履约环节进行楷核项巡检，记录异常问题。\n保障稽核巡检真实性和准确性，按要求提供稽核例外证明，熟悉掌握稽核巡检标准\n与物流、品控相关负责人及时联动，推动物流侧纠偏整改，定期复盘，监控例外改善\n对非日常巡检项但存在重大品质影响，及时升级反馈总部，如仓硬件及管理水平等\n通过日常及专项稻核等形式,发现履约链路中品质影响的机会点，推动迭代流程标准。","requirements":"需要长期异地现场出差巡检。周度轮休。\n工作地点：全国各快驴仓内现场飞检稽核，现场一线办公。\n熟悉物流和仓储管理知识：熟悉大宗餐饮B2B物流和仓储管理的基本原理和流程，包括库存管理、货物存储、装卸和运输\n安全管理知识：掌握仓库安全管理知识，包括消防安全、物品安全和人员安全等\n品质保障知识：掌握商品品质相关知识，包括商品存储，分拣打包，运输等链路品质保障等\n关注细节、态度审慎、注意保密","description":"部门介绍\n快驴进货是美团旗下的餐饮供应链平台，帮助餐饮商户以更低成本、更高效率来获取安全可靠的食材供应，让餐饮采购更简单。快驴进货同步发展“自营+平台”的业务模式，在采购环节一方面向上游供应商直采大宗商品，另一方面引入各地批发商，助力平台伙伴共同发展；在销售环节既有自建团队进行市场、客户拓展，又帮助各地批发商拓展业务；同时自建仓储管理系统、配送网络与团队，为客户提供优质履约服务。\n截至2022年，快驴进货布局了全国41个城市，为百万家商户提供“全、省、稳、好”的餐饮供应链服务。我们拥有3000+品牌食材、超5万SKU商品、超28万商品资质，并提供源头严审核、食品安全严把关、24小时无忧售后的全面保障，实现手机下单、送货上门的高效采购模式，帮百万商家节省了采购时间与成本，助力平台伙伴共同发展，在万亿市场共享机遇。\n在这里，你将收获完善的员工发展机制及学习体系，与各界专家一起深度参与餐饮供应链业务的发展。欢迎优秀的你加入美团快驴进货，与我们一起成长，一起更好！\n\n岗位职责\n适应长期出差，按稽核巡检要求，对链路履约环节进行楷核项巡检，记录异常问题。\n保障稽核巡检真实性和准确性，按要求提供稽核例外证明，熟悉掌握稽核巡检标准\n与物流、品控相关负责人及时联动，推动物流侧纠偏整改，定期复盘，监控例外改善\n对非日常巡检项但存在重大品质影响，及时升级反馈总部，如仓硬件及管理水平等\n通过日常及专项稻核等形式,发现履约链路中品质影响的机会点，推动迭代流程标准。\n\n岗位基本要求\n需要长期异地现场出差巡检。周度轮休。\n工作地点：全国各快驴仓内现场飞检稽核，现场一线办公。\n熟悉物流和仓储管理知识：熟悉大宗餐饮B2B物流和仓储管理的基本原理和流程，包括库存管理、货物存储、装卸和运输\n安全管理知识：掌握仓库安全管理知识，包括消防安全、物品安全和人员安全等\n品质保障知识：掌握商品品质相关知识，包括商品存储，分拣打包，运输等链路品质保障等\n关注细节、态度审慎、注意保密\n\n具备以下条件优先\n在京东、优选、美菜等做大宗餐饮配送物流运营优先。\n\n岗位亮点\n岗位亮点:\n从稽核视角出发 可以全链路了解快驴业务链条，学习餐饮物流全流程作业，锻炼跨部门沟通能力驱动物流执行持续改进，使客户体验越来越好。\n具备以下优先:\n具备数据分析能力、物流运营稽核工作优先。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4612990160","sourceKey":"meituan_social","company":"美团","title":"营销场商业分析负责人","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4612990160&jobShareType=1","duty":"1. 负责营销场域的目标和资源管理，搭建核心指标监控体系，支持业务决策。  \n2. 带领团队深入分析用户行为、供给分层、营销活动效果及营销渠道表现，评估渠道效率。  \n3. 协同产品、运营、用户团队，识别场域增长机会，推动场域专项策略落地。  \n4. 管理并指导团队，提升团队专业能力与交付效率。  \n5. 探索并使用AI分析方法和工具，优化分析流程，提升团队整体产出质量。","requirements":"1.5年及以上商业分析/业务策略/战略规划相关经验，有互联网公司商分/策略/战略岗经验优先，有本地生活、餐饮、零售类业务背景优先；\n2.优秀的业务理解力和洞察力，敢想敢干，挖掘问题或机会，推动业务迭代，引领场域商业洞察与模式设计；\n3.具备良好的跨团队沟通协同能力，擅长统筹和推动关键事项从分析到落地的闭环；\n4.对AI行业有热情、有理解，能够结合业务场景设计AI解决方案。","description":"部门介绍\n美团到餐事业部拥有美团历史悠久的餐饮团购业务，聚焦美团“零售+科技”战略，为数以万计的餐饮商户提供一站式营销服务，为广大消费者提供优质的消费体验。我们帮助餐饮商户沉淀口碑、获取用户、增加复购等，持续提升商户数字化经营水平，同时秉承着“帮大家吃得更好，生活更好”的使命，面向消费者提供丰富的产品和服务，帮助消费者更好地作出消费决策。\n我们有高效成熟的管理体系，还将为你提供全面的人才培养机制和广阔的成长空间。让我们一起创造更大的价值，帮助消费者吃得更好，商户经营得更好！\n\n岗位职责\n1. 负责营销场域的目标和资源管理，搭建核心指标监控体系，支持业务决策。  \n2. 带领团队深入分析用户行为、供给分层、营销活动效果及营销渠道表现，评估渠道效率。  \n3. 协同产品、运营、用户团队，识别场域增长机会，推动场域专项策略落地。  \n4. 管理并指导团队，提升团队专业能力与交付效率。  \n5. 探索并使用AI分析方法和工具，优化分析流程，提升团队整体产出质量。\n\n岗位基本要求\n1.5年及以上商业分析/业务策略/战略规划相关经验，有互联网公司商分/策略/战略岗经验优先，有本地生活、餐饮、零售类业务背景优先；\n2.优秀的业务理解力和洞察力，敢想敢干，挖掘问题或机会，推动业务迭代，引领场域商业洞察与模式设计；\n3.具备良好的跨团队沟通协同能力，擅长统筹和推动关键事项从分析到落地的闭环；\n4.对AI行业有热情、有理解，能够结合业务场景设计AI解决方案。\n\n岗位亮点\n高增长核心业务核心岗位；高成长性；良好团队氛围","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4643863428","sourceKey":"meituan_social","company":"美团","title":"小象超市-北京供应链品控","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4643863428&jobShareType=1","duty":"1. 负责小象超市生鲜的供应链环节的商品质量管理，预防和优化商品质量问题，提升用户满意度；\n2. 负责商品收货，存储，包装，配送过程中的质量检测和标准落地，减少各环节的商品质量问题发生；\n3. 负责跟踪解决出现的商品（特别是生鲜产品）质量问题，避免商品质量问题重复出现，影响用户体验。","requirements":"1. 专科以上学历，2年以上商超零售质量管理经验或供应链质量管理经验；\n2. 具备跨部门沟通表达及协作能力，能快速推进项目落地；\n3. 具备责任心，自驱性强；\n4. 具备正直诚信的价值观，有较强的原则性。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1. 负责小象超市生鲜的供应链环节的商品质量管理，预防和优化商品质量问题，提升用户满意度；\n2. 负责商品收货，存储，包装，配送过程中的质量检测和标准落地，减少各环节的商品质量问题发生；\n3. 负责跟踪解决出现的商品（特别是生鲜产品）质量问题，避免商品质量问题重复出现，影响用户体验。\n\n岗位基本要求\n1. 专科以上学历，2年以上商超零售质量管理经验或供应链质量管理经验；\n2. 具备跨部门沟通表达及协作能力，能快速推进项目落地；\n3. 具备责任心，自驱性强；\n4. 具备正直诚信的价值观，有较强的原则性。\n\n具备以下条件优先\n1. 热爱互联网和新零售行业，具有极强的快速学习能力；\n2. 有质量管理方法论且可以快速结合业务特点落地能力。\n\n岗位亮点\n1.了解生鲜商品全链条品质管理过程，与各团队一起提升客户品质体验；\n2.制定互联网生鲜板块的相关行业标准。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4638520781","sourceKey":"meituan_social","company":"美团","title":"小象超市-食品安全管理","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4638520781&jobShareType=1","duty":"1.利用AI提升食品安全日常管理效能，作为食品安全中台，为一线品控、采购、商家提供能力支持。\n2.跟进食品安全客诉的识别、治理、管控，确保改善闭环。推进食安客诉治理数字化、自动化和AI化。\n3.负责快检实验室、快检外包、三方送检，持续迭代食品安全检测策略，确保生鲜品满足小象食品安全标准。\n4.推进系统产品能力建设，抽检系统线上化迭代，实现抽检过程的数字化和自动化；\n5.食品安全全链路解决方案制定。","requirements":"1.大学本科及以上学历，食品安全、分析检测、食用农产品质量安全相关专业。\n2.至少1年以上食品安全相关工作经验，具备丰富的质量管理经验和技能。熟悉质量管理体系和相关标准。\n3.适应互联网工作节奏，有清晰职业规划和成长意愿，自驱力强，能够主动推进工作。\n4.具备良好的团队合作能力和沟通能力，能够与不同部门进行有效地合作和沟通。\n5.具备较强的问题分析能力和解决能力，能够快速识别并解决问题。\n6.掌握基本的AI工具，愿意使用AI工具提升工作效率、优化工作流程。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1.利用AI提升食品安全日常管理效能，作为食品安全中台，为一线品控、采购、商家提供能力支持。\n2.跟进食品安全客诉的识别、治理、管控，确保改善闭环。推进食安客诉治理数字化、自动化和AI化。\n3.负责快检实验室、快检外包、三方送检，持续迭代食品安全检测策略，确保生鲜品满足小象食品安全标准。\n4.推进系统产品能力建设，抽检系统线上化迭代，实现抽检过程的数字化和自动化；\n5.食品安全全链路解决方案制定。\n\n岗位基本要求\n1.大学本科及以上学历，食品安全、分析检测、食用农产品质量安全相关专业。\n2.至少1年以上食品安全相关工作经验，具备丰富的质量管理经验和技能。熟悉质量管理体系和相关标准。\n3.适应互联网工作节奏，有清晰职业规划和成长意愿，自驱力强，能够主动推进工作。\n4.具备良好的团队合作能力和沟通能力，能够与不同部门进行有效地合作和沟通。\n5.具备较强的问题分析能力和解决能力，能够快速识别并解决问题。\n6.掌握基本的AI工具，愿意使用AI工具提升工作效率、优化工作流程。\n\n具备以下条件优先\n具有互联网经历、政府市监部门抽检、三方食品检测实验室管理、的食品安全相关经验者优先。\n具备AI创新能力、数仓数据经验、SQL数据分析经验等能力者优先。\n\n岗位亮点\n1.专业发展：推动业务食品安全管理体系的建设、运行和改进，拓展专业领域和实践经验。\n2.创新机会：推动食品安全管理AI智能化。\n3.总部平台：北京总部平台的全局视角能力提升，方向可根据个人能力确定。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4641765618","sourceKey":"meituan_social","company":"美团","title":"小象超市-食品安全体系专家","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4641765618&jobShareType=1","duty":"1.负责设计、规划及实施业务的食品安全管理体系，确保其符合国家法规和行业标准。\n2.调研食安趋势，结合业务现状，输出从源头至终端的全链路食安管理策略，持续优化食安体系，并提升其有效性和可操作性。\n3.开展食品安全风险监测，识别潜在的安全隐患；进行食品安全风险评估，量化风险的严重性和发生概率；制定和实施风险治理措施，降低食品安全风险。\n4.开展公司食品安全文化建设，提升链路上各相关方的食安意识，确保工作目标、意识理念一致。","requirements":"1.大学本科及以上学历，食品安全相关专业，至少10年以上食安管理相关工作经验。\n2.熟悉食安管理体系和相关标准，如ISO22000、BRCGS、IFS等。\n3.具备良好的团队合作能力和沟通能力，能够与不同部门进行有效地合作和沟通。\n4.具备较强的问题分析能力和解决能力，责任心和自驱力强，能够主动推进工作。\n5.掌握基本的AI工具，使用工具提升工作流程效率。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1.负责设计、规划及实施业务的食品安全管理体系，确保其符合国家法规和行业标准。\n2.调研食安趋势，结合业务现状，输出从源头至终端的全链路食安管理策略，持续优化食安体系，并提升其有效性和可操作性。\n3.开展食品安全风险监测，识别潜在的安全隐患；进行食品安全风险评估，量化风险的严重性和发生概率；制定和实施风险治理措施，降低食品安全风险。\n4.开展公司食品安全文化建设，提升链路上各相关方的食安意识，确保工作目标、意识理念一致。\n\n岗位基本要求\n1.大学本科及以上学历，食品安全相关专业，至少10年以上食安管理相关工作经验。\n2.熟悉食安管理体系和相关标准，如ISO22000、BRCGS、IFS等。\n3.具备良好的团队合作能力和沟通能力，能够与不同部门进行有效地合作和沟通。\n4.具备较强的问题分析能力和解决能力，责任心和自驱力强，能够主动推进工作。\n5.掌握基本的AI工具，使用工具提升工作流程效率。\n\n具备以下条件优先\n具有新零售、电商的中台食品安全体系搭建经验，或大型零售企业总部食品安全管理经验者优先。\n\n岗位亮点\n1.专业发展：推动业务食品安全管理体系的建设、运行和改进，拓展专业领域和实践经验。\n2.创新机会：推动食品安全管理的数字化和智能化。\n3.协同管理：与多部门合作，全链路视角提升整体食品安全管理水平，确保消费者的健康和安全。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4642467289","sourceKey":"meituan_social","company":"美团","title":"小象超市-门店食品安全管理专家","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4642467289&jobShareType=1","duty":"1.负责规划小象业务线上及线下门店食品安全管理体系，确保其符合国家法规和行业标准。\n2.制定及完善门店从图纸设计与审核、工程食安验收、商户入驻、人员培训、加工制作管理、清洁消毒、效期管理、食安巡检稽核、食安客诉处理等全链路的食安标准和流程；\n3.调研门店食安管理风险场景，结合现有业务，输出线上与线下门店的食安管理策略，持续完善食安风险治理，并提升其有效性和可操作性。\n4.推进门店食安系统的线上化迭代，实现数字化和自动化；有效分析和跟踪门店商品及过程管理的食品安全数据，及时发现和处理食品安全问题。\n5.通过抽检、飞审等手段开展食品安全风险监测，进行食品安全风险评估，量化风险的严重性和发生概率，制定和实施风险分级治理措施，降低门店食品安全风险。","requirements":"1.大学本科及以上学历，食品安全相关专业，至少10年以上食安管理相关工作经验。\n2.熟悉食安管理体系和相关标准，如ISO22000、BRCGS、IFS等。\n3.具备良好的团队合作能力和沟通能力，能够与不同部门进行有效地合作和沟通。\n4.具备较强的问题分析能力和解决能力，责任心和自驱力强，能够主动推进工作。\n5.掌握基本的AI工具，使用工具提升工作流程效率。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1.负责规划小象业务线上及线下门店食品安全管理体系，确保其符合国家法规和行业标准。\n2.制定及完善门店从图纸设计与审核、工程食安验收、商户入驻、人员培训、加工制作管理、清洁消毒、效期管理、食安巡检稽核、食安客诉处理等全链路的食安标准和流程；\n3.调研门店食安管理风险场景，结合现有业务，输出线上与线下门店的食安管理策略，持续完善食安风险治理，并提升其有效性和可操作性。\n4.推进门店食安系统的线上化迭代，实现数字化和自动化；有效分析和跟踪门店商品及过程管理的食品安全数据，及时发现和处理食品安全问题。\n5.通过抽检、飞审等手段开展食品安全风险监测，进行食品安全风险评估，量化风险的严重性和发生概率，制定和实施风险分级治理措施，降低门店食品安全风险。\n\n岗位基本要求\n1.大学本科及以上学历，食品安全相关专业，至少10年以上食安管理相关工作经验。\n2.熟悉食安管理体系和相关标准，如ISO22000、BRCGS、IFS等。\n3.具备良好的团队合作能力和沟通能力，能够与不同部门进行有效地合作和沟通。\n4.具备较强的问题分析能力和解决能力，责任心和自驱力强，能够主动推进工作。\n5.掌握基本的AI工具，使用工具提升工作流程效率。\n\n具备以下条件优先\n具有新零售、电商平台或大型零售企业总部门店食品安全管理经验者优先。\n\n岗位亮点\n1.专业发展：推动业务全渠道门店食品安全管理体系的建设、运行和改进，拓展专业领域和实践经验。\n2.创新机会：推动门店食品安全管理的数字化和智能化。\n3.协同管理：与多部门合作，全链路视角提升整体食品安全管理水平，确保消费者的健康和安全。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3529970506","sourceKey":"meituan_social","company":"美团","title":"门店拓展财务BP","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3529970506&jobShareType=1","duty":"1、门店拓展选址部门的财务BP\n2、美团自营超市门店选址项目全链路UE测算\n3、超市门店业态下的商铺租金调研","requirements":"1、过往有门店选址财务相关经验，在连锁线下超市或者门店相关的经验。\n2、学习并好奇，善于沟通调研，有行业调研或市场调研相关经验。\n3、对 AI 技术在财务和业务分析领域的应用有主动探索意识，能结合 AI 工具创新分析方法，推动财务数智化转型。","description":"部门介绍\n财务平台负责公司整体和各业务层面的财务管理工作，通过建设专业、全面、复合的财务管理能力和与业务经营的紧密结合来支持公司健康发展。目前财务平台拥有财务会计、财务报告、资金管理、税务管理、财务共享、财务系统、规划分析、财务BP和内控内审等主要工作方向。我们的目标是建设业界一流的财务管理能力和经营支持体系，为公司战略的正确落地、投入效率的持续提升、业务价值的不断增长保驾护航。欢迎加入财务平台，携手一起向未来！\n\n岗位职责\n1、门店拓展选址部门的财务BP\n2、美团自营超市门店选址项目全链路UE测算\n3、超市门店业态下的商铺租金调研\n\n岗位基本要求\n1、过往有门店选址财务相关经验，在连锁线下超市或者门店相关的经验。\n2、学习并好奇，善于沟通调研，有行业调研或市场调研相关经验。\n3、对 AI 技术在财务和业务分析领域的应用有主动探索意识，能结合 AI 工具创新分析方法，推动财务数智化转型。\n\n岗位亮点\n业务初期飞速发展阶段，简单直接灵活的团队氛围，能够快速成长并获得发展的机会","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3958847494","sourceKey":"meituan_social","company":"美团","title":"AI组织转型专家","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3958847494&jobShareType=1","duty":"1.战略研究：基于公司发展战略和组织能力长期建设需求，深入研究AI对组织生产关系和人才策略的影响，识别组织能力和人才发展上需要被关注的问题与机会，推动相关问题的讨论与改变发生。\n2.方案设计：结合不同业务的差异化性质、发展阶段和管理需求，综合数据分析、内部访谈、外部对标等手段，持续识别和发现组织能力和人才发展上需要被关注的问题/机会，并能够促进相关问题的讨论，撬动改变发生；\n3.前瞻探索：围绕AI与组织的前沿话题，设计探索性的产品、工具与机制（如HRAI产品），推动从概念验证到实际落地的全链路工作。\n4.制度与项目推进：参与公司组织与人才发展领域的政策制度迭代及年度重点项目（如组织与人才盘点、职级评审、HC预算规划等），运用访谈调研、数据分析和外部对标为决策提供依据。","requirements":"1.愿力：对AI如何改变组织运作有清晰的构想和独立思考，不满足于\"AI是工具\"的浅层理解，愿意追问\"AI在改变什么底层逻辑\"。如果你写过关于AI与组织/工作/人的思考笔记或博客，欢迎附在简历里。\n2.创造力：在更高层次的创造性突破上，AI目前仍有限——它擅长整合已有信息，但提出新方向、定义新问题、设计新路径，依然是人的主场。我们看中的不只是\"会用AI\"，而是能看见AI还看不到的东西。\n3.判断力：在高度复杂、充满不确定性的环境中，依然能做出高质量决策。具体来说，能判断\"这件事AI能不能做、该不该做\"，能识别前沿的变化和真正的机会，也能主动迎接挑战，与不同利益相关方共同推进问题解决。\n4.同理心：极度关注客户，善于理解不同业务、管理者和员工的实际体验与需求，具备敏锐的问题捕捉能力。能站在对方视角看问题，而不是站在自己的专业视角提方案。\n5.跨领域思维：具备跨学科视野或跨领域好奇心，能同时用技术和管理的语言理解问题。专业不限，重要的是你用什么方法思考，而不是你学过什么专业。","description":"部门介绍\n美团HR的使命是“建设有生命力的组织，为客户和社会创造价值。” 我们认为HR的工作不是以自身“专业”为中心，而是要建设有助于员工发挥创造力的环境，支持他们更好地为外部客户和社会创造价值，也实现组织自身的进化和传承。在这个过程中，我们的每位HR同学都是“业务的战略合作伙伴、组织能力的建设者、美团精神的布道者、员工的成长伙伴”。我们要设计面向长期支撑组织有效运转的机制，我们要求真务实地帮业务解决发展中的问题和阵痛，我们要支持每一位员工历经磨炼收获成长。我们要影响和驱动让世界更美好的变化发生。如果这也是你追求的，欢迎加入美团HR，与我们一路同行！\n\n岗位职责\n1.战略研究：基于公司发展战略和组织能力长期建设需求，深入研究AI对组织生产关系和人才策略的影响，识别组织能力和人才发展上需要被关注的问题与机会，推动相关问题的讨论与改变发生。\n2.方案设计：结合不同业务的差异化性质、发展阶段和管理需求，综合数据分析、内部访谈、外部对标等手段，持续识别和发现组织能力和人才发展上需要被关注的问题/机会，并能够促进相关问题的讨论，撬动改变发生；\n3.前瞻探索：围绕AI与组织的前沿话题，设计探索性的产品、工具与机制（如HRAI产品），推动从概念验证到实际落地的全链路工作。\n4.制度与项目推进：参与公司组织与人才发展领域的政策制度迭代及年度重点项目（如组织与人才盘点、职级评审、HC预算规划等），运用访谈调研、数据分析和外部对标为决策提供依据。\n\n岗位基本要求\n1.愿力：对AI如何改变组织运作有清晰的构想和独立思考，不满足于\"AI是工具\"的浅层理解，愿意追问\"AI在改变什么底层逻辑\"。如果你写过关于AI与组织/工作/人的思考笔记或博客，欢迎附在简历里。\n2.创造力：在更高层次的创造性突破上，AI目前仍有限——它擅长整合已有信息，但提出新方向、定义新问题、设计新路径，依然是人的主场。我们看中的不只是\"会用AI\"，而是能看见AI还看不到的东西。\n3.判断力：在高度复杂、充满不确定性的环境中，依然能做出高质量决策。具体来说，能判断\"这件事AI能不能做、该不该做\"，能识别前沿的变化和真正的机会，也能主动迎接挑战，与不同利益相关方共同推进问题解决。\n4.同理心：极度关注客户，善于理解不同业务、管理者和员工的实际体验与需求，具备敏锐的问题捕捉能力。能站在对方视角看问题，而不是站在自己的专业视角提方案。\n5.跨领域思维：具备跨学科视野或跨领域好奇心，能同时用技术和管理的语言理解问题。专业不限，重要的是你用什么方法思考，而不是你学过什么专业。\n\n具备以下条件优先\n1.兼具甲乙方的经验，乙方的同学需要在甲方有过成功落地的实践；\n2.具备同理心，面对不同对象时能够将专业的内容有效沟通并影响；\n3.精益运营，能够做好项目管理；\n4.勇于挑战，具备一定的韧性。\n\n岗位亮点\n1.直接参与AI时代的组织变革：不是旁观者，而是参与者——你的研究成果可能直接影响公司级人才政策和组织决策，这是传统OD岗位很难给到的参与深度。\n2.成长曲线陡峭：总部专业团队，直接接触公司级战略项目，与资深管理者对话，快速建立全局视野和组织洞察力。\n3.前沿探索空间：不局限于传统管理领域，有机会做AI+组织的前瞻性研究，甚至独立设计并推动产品化工具的落地。\n4.团队文化务实：团队专业且开放，愿意提供培养人的责任和机会，主管+Mentor+Buddy全程帮助成长，成长路径清晰。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4495321748","sourceKey":"meituan_social","company":"美团","title":"KSA-履约副站-Last Mile Supervisor","city":"利雅得/吉达/达曼","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4495321748&jobShareType=1","duty":"1. Responsible for the daily management of the dark store delivery module, developing regional delivery management plans and supervising on-site execution.\n2. Facilitate the implementation of business operations in the region, monitor daily operations, service quality, and performance metrics.\n3. Collect, provide feedback on, and resolve fulfillment issues in the region, follow up on operational anomalies, and conduct experience analysis for continuous improvement.\n4. Oversee the training of supervisors/riders in the region to enhance employees' overall quality and business capabilities.\n5. Ensure service quality at sites within the region, analyze delivery customer complaints, implement effective measures to control complaints, and provide professional, efficient, and high-quality delivery services to enhance customer satisfaction.","requirements":"1. Education and Experience: Bachelor's degree or higher in Logistics Management or Supply Chain Management, or at least 3 years of relevant experience in delivery operations.\n2. Skills: Strong communication and coordination skills, capable of effective cross-team collaboration and communication with other departments or external entities, diligent, responsible.\n3. Technical Proficiency: Proficient in using various MS software, with strong data processing and analysis skills, as well as document organization and summarization abilities.\n4. Personal Traits: Strong execution capabilities and able to withstand a certain level of work pressure.\n5. Market and Project Skills: Strong market development skills, clear thinking, and excellent project management abilities.\n6. Location: Based in Riyadh, with proficient English communication skills.","description":"部门介绍\n美团的使命是“帮大家吃得更好，生活更好”，公司聚焦“零售 + 科技”战略，和广大商户与各类合作伙伴一起，努力为消费者提供品质生活，推动商品零售和服务零售在需求侧和供给侧的数字化转型。\n2018年9月20日，美团正式在港交所挂牌上市。美团将始终坚持以客户为中心，不断加大在科技研发方面的投入，更好承担社会责任，更多创造社会价值，与广大合作伙伴一起发展共赢。\n\n岗位职责\n1. Responsible for the daily management of the dark store delivery module, developing regional delivery management plans and supervising on-site execution.\n2. Facilitate the implementation of business operations in the region, monitor daily operations, service quality, and performance metrics.\n3. Collect, provide feedback on, and resolve fulfillment issues in the region, follow up on operational anomalies, and conduct experience analysis for continuous improvement.\n4. Oversee the training of supervisors/riders in the region to enhance employees' overall quality and business capabilities.\n5. Ensure service quality at sites within the region, analyze delivery customer complaints, implement effective measures to control complaints, and provide professional, efficient, and high-quality delivery services to enhance customer satisfaction.\n\n岗位基本要求\n1. Education and Experience: Bachelor's degree or higher in Logistics Management or Supply Chain Management, or at least 3 years of relevant experience in delivery operations.\n2. Skills: Strong communication and coordination skills, capable of effective cross-team collaboration and communication with other departments or external entities, diligent, responsible.\n3. Technical Proficiency: Proficient in using various MS software, with strong data processing and analysis skills, as well as document organization and summarization abilities.\n4. Personal Traits: Strong execution capabilities and able to withstand a certain level of work pressure.\n5. Market and Project Skills: Strong market development skills, clear thinking, and excellent project management abilities.\n6. Location: Based in Riyadh, with proficient English communication skills.\n\n岗位亮点\n1.Opportunity to contribute to the establishment and development of the logistics delivery team, making a significant impact on the company's logistics operations.\n2.Exposure to diverse logistics delivery resources and processes, gaining insights into the latest industry trends and enhancing professional skills.\n3.Ability to improve customer satisfaction and enhance the company's market competitiveness through optimization and improvement of the logistics delivery process.","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4640532964","sourceKey":"meituan_social","company":"美团","title":"连锁酒店大客户经理KA-南京、徐州","city":"南京市/徐州市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4640532964&jobShareType=1","duty":"1、负责酒店在平台的日常运营和管理工作，包括指标达成、营销活动、线上推广、针对指导等，协助客服解决商家客诉及异常问题处理；\n2、通过上门拜访、电话运营维护商家，全面提高商家线上运营意识和能力，给子商家可行的优化提升方案；\n3、维护好作伙伴的长期合作关系，深入了解商家特点，落地公司策略\n4 做好市场和行业动态信息收集和反馈","requirements":"1、 本科及以上学历；\n2、可以接受短期出养，工作形式：电销+面销;\n3、具备较强的销售沟通技巧、运营思维、市场敏税度、喜欢酒旅行业；\n4、有较强时间规划 韧性能力以及执行力。具有良好的团队合作精神；\n5、较强的学习能力和自我成长意愿,明确的职业生涯规划。\n6、具备OTA行业、酒店运营经验以及酒店管理专业优先；\n7、熱练使用办公软件。","description":"部门介绍\n美团酒店旅行业务涵盖酒店、民宿、机票、火车票、旅游度假、景点门票等各类住行游品类，通过与产业上下游的深度合作，为用户提供美好的旅游旅行体验。我们积极打造AI友好型组织，使用AI等新技术提升旅游服务的供需匹配效率，更好满足用户个性化、多样化的出游需求。我们持续深耕产业链，用数字化服务助力实体商家高质量经营，探索自有品牌等供给新模式，打造健康的商家生态，保障用户服务体验。为满足用户日益增长的跨境旅行需求，我们将聚焦亚太区域，打造高品质的住宿、交通、游玩等服务矩阵。\n这里有多元的业务布局、持续的成长空间，无论是向往的远方还是眼前的工作，一路都是风景相伴。加入我们，共同为用户创造旅游旅行中的高光时刻！\n\n岗位职责\n1、负责酒店在平台的日常运营和管理工作，包括指标达成、营销活动、线上推广、针对指导等，协助客服解决商家客诉及异常问题处理；\n2、通过上门拜访、电话运营维护商家，全面提高商家线上运营意识和能力，给子商家可行的优化提升方案；\n3、维护好作伙伴的长期合作关系，深入了解商家特点，落地公司策略\n4 做好市场和行业动态信息收集和反馈\n\n岗位基本要求\n1、 本科及以上学历；\n2、可以接受短期出养，工作形式：电销+面销;\n3、具备较强的销售沟通技巧、运营思维、市场敏税度、喜欢酒旅行业；\n4、有较强时间规划 韧性能力以及执行力。具有良好的团队合作精神；\n5、较强的学习能力和自我成长意愿,明确的职业生涯规划。\n6、具备OTA行业、酒店运营经验以及酒店管理专业优先；\n7、熱练使用办公软件。\n\n具备以下条件优先\n连锁酒店运营管理经验\n本地生活销售经验\n\n岗位亮点\n面对不同客户，增强销售能力和解决问题的能力，并可以对酒店行业有更全面、更深入的了解；\n有机会与公司共同成长，个人综合能力将随业务发展及需求变化不断提升。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4531181147","sourceKey":"meituan_social","company":"美团","title":"到餐会员运营负责人","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4531181147&jobShareType=1","duty":"构建高价值用户与核心商家的双边信任关系，以到餐权益使用用户数为北极星指标，打造到餐会员体系。 承担两件事：C端提升高价值用户忠诚度；B端提供高价值客流的精准触达与长效经营。\n\n主要职责：\n构建到餐会员权益体系（尤其是到餐业态相关的服务履约类的权益）\n站在用户、商户双视角，设计与匹配会员策略、包括联合会员打法\n优化用户会员权益使用链路，放大用户价值感知，提升粘性","requirements":"1. 大学本科及以上学历，5年以上用户运营或会员运营相关经验。  \n2. 具备完整的会员体系搭建与运营经验，熟悉用户生命周期管理。  \n3. 具备较强的数据分析能力，能通过数据驱动运营决策。  \n4. 有团队管理经验，具备优秀的沟通协调与项目管理能力。  \n5. 对本地生活或餐饮行业有深入理解者优先。","description":"部门介绍\n美团平台为用户的基础产品体验负责，还承担了美团的用户增长、市场和品牌营销以及多条业务线的产品设计职责，建立了融合文字、图片、视频和直播等不同形式的內容生态系统，同时整合地图服务部、客户服务和体验部、企业业务部、网约车业务部等部门，致力于用科技提升美团数亿消费者、近千万商家、骑手、司机和团长的服务体验。美团平台拥有高并发、多业务的复杂场景，为技术深度优化提供了最佳实践可能。这里有简单、讲逻辑、有爱的团队，更是一块理想的实战场地，舞台广阔，欢迎你来尽情施展。\n\n岗位职责\n构建高价值用户与核心商家的双边信任关系，以到餐权益使用用户数为北极星指标，打造到餐会员体系。 承担两件事：C端提升高价值用户忠诚度；B端提供高价值客流的精准触达与长效经营。\n\n主要职责：\n构建到餐会员权益体系（尤其是到餐业态相关的服务履约类的权益）\n站在用户、商户双视角，设计与匹配会员策略、包括联合会员打法\n优化用户会员权益使用链路，放大用户价值感知，提升粘性\n\n岗位基本要求\n1. 大学本科及以上学历，5年以上用户运营或会员运营相关经验。  \n2. 具备完整的会员体系搭建与运营经验，熟悉用户生命周期管理。  \n3. 具备较强的数据分析能力，能通过数据驱动运营决策。  \n4. 有团队管理经验，具备优秀的沟通协调与项目管理能力。  \n5. 对本地生活或餐饮行业有深入理解者优先。\n\n具备以下条件优先\n对本地生活或餐饮行业有深入理解者优先。\n\n岗位亮点\n1. 参与核心业务模块，直接影响亿级用户的产品体验。  \n2. 拥有独立负责到店餐饮会员体系的机会，且深耕产业链生态。  \n3. 团队氛围开放，鼓励创新与数据驱动的工作方式。  \n4. 公司提供完善的职业发展通道与学习资源支持。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4231176534","sourceKey":"meituan_social","company":"美团","title":"无人车业务部-车身和外饰件采购","city":"上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4231176534&jobShareType=1","duty":"1. 负责车身及外饰件的采购策略制定与执行，确保供应链稳定和成本优化。  \n2. 与研发、质量、生产等部门协作，推动新项目零部件的选型、定点及供应商开发。  \n3. 管理供应商绩效，定期评估并推动持续改进，保障交付、质量与成本目标达成。  \n4. 分析市场行情与成本结构，主导商务谈判，降低采购总成本。  \n5. 建立并维护供应商资源库，优化供应链结构，提升抗风险能力。","requirements":"1. 大学本科及以上学历，机械、材料、汽车工程或相关专业优先。  \n2. 5年以上汽车行业采购经验，具备车身或外饰件采购背景。  \n3. 熟悉汽车零部件开发流程及供应商管理体系，具备较强的成本分析能力。  \n4. 具备良好的沟通协调能力和商务谈判技巧，推动业务能力强。","description":"部门介绍\n无人车业务部成立于2016年，旨在用无人驾驶技术提升物流配送的效率和体验。美团无人车以自研L4级自动驾驶软硬件技术为核心，与美团即时零售业务结合，形成满足公开道路、社区、工业园区等室外全场景下的无人配送整体解决方案。自2020年起，无人车已在北京、深圳等多地进入常态化试运营阶段，在城市复杂场景下提供针对餐饮外卖、生鲜食杂等货物的即时配送服务。2025年，美团无人车又踏上了同城货运的新探索，并在2026年持续扩大运营范围和车队数量，为更多城市带来智能配送服务。\n欢迎加入美团无人车团队，与我们一起用科技推动即时零售再升级！\n\n岗位职责\n1. 负责车身及外饰件的采购策略制定与执行，确保供应链稳定和成本优化。  \n2. 与研发、质量、生产等部门协作，推动新项目零部件的选型、定点及供应商开发。  \n3. 管理供应商绩效，定期评估并推动持续改进，保障交付、质量与成本目标达成。  \n4. 分析市场行情与成本结构，主导商务谈判，降低采购总成本。  \n5. 建立并维护供应商资源库，优化供应链结构，提升抗风险能力。\n\n岗位基本要求\n1. 大学本科及以上学历，机械、材料、汽车工程或相关专业优先。  \n2. 5年以上汽车行业采购经验，具备车身或外饰件采购背景。  \n3. 熟悉汽车零部件开发流程及供应商管理体系，具备较强的成本分析能力。  \n4. 具备良好的沟通协调能力和商务谈判技巧，推动业务能力强。\n\n岗位亮点\n1. 加入快速发展的汽车制造企业，参与核心零部件供应链管理。  \n2. 提供具有市场竞争力的薪酬与完善的职业发展通道。  \n3. 扁平化管理模式，团队协作氛围佳，决策高效。  \n4. 工作地点位于上海，交通便利，配套齐全。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4535089598","sourceKey":"meituan_social","company":"美团","title":"鲜肉招商采购","city":"上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4535089598&jobShareType=1","duty":"1.负责区域鲜肉品类的招商采购工作，制定并落实相关策略和计划；\n2.有当地鲜禽、牛羊、水产核心宰场及批市有较好的供给资源，通过批市引入优质商资源，通过成本优化提升销售；\n3.通过商品及品类的结构梳理、品类操盘来提升鲜肉规模；\n4.有较好的供应商管理能力,能长期保障稳定的品质及供给；","requirements":"1.大学专科及以上学历，具备相关领域的知识和经验。\n2.至少5年以上商品与供应链管理、招商采购相关工作经验，有成功案例者优先。\n3.具备较强的沟通能力和执行能力，对市场变化有敏锐的洞察力。\n4.具备良好的解决问题的能力，能够有效应对各种挑战。\n5.具备良好的职业素质，诚信正直；\n6.工作地点为福州市或厦门市，能适应一定频率的出差。","description":"部门介绍\n快驴进货是美团旗下的餐饮供应链平台，帮助餐饮商户以更低成本、更高效率来获取安全可靠的食材供应，让餐饮采购更简单。快驴进货同步发展“自营+平台”的业务模式，在采购环节一方面向上游供应商直采大宗商品，另一方面引入各地批发商，助力平台伙伴共同发展；在销售环节既有自建团队进行市场、客户拓展，又帮助各地批发商拓展业务；同时自建仓储管理系统、配送网络与团队，为客户提供优质履约服务。\n截至2022年，快驴进货布局了全国41个城市，为百万家商户提供“全、省、稳、好”的餐饮供应链服务。我们拥有3000+品牌食材、超5万SKU商品、超28万商品资质，并提供源头严审核、食品安全严把关、24小时无忧售后的全面保障，实现手机下单、送货上门的高效采购模式，帮百万商家节省了采购时间与成本，助力平台伙伴共同发展，在万亿市场共享机遇。\n在这里，你将收获完善的员工发展机制及学习体系，与各界专家一起深度参与餐饮供应链业务的发展。欢迎优秀的你加入美团快驴进货，与我们一起成长，一起更好！\n\n岗位职责\n1.负责区域鲜肉品类的招商采购工作，制定并落实相关策略和计划；\n2.有当地鲜禽、牛羊、水产核心宰场及批市有较好的供给资源，通过批市引入优质商资源，通过成本优化提升销售；\n3.通过商品及品类的结构梳理、品类操盘来提升鲜肉规模；\n4.有较好的供应商管理能力,能长期保障稳定的品质及供给；\n\n岗位基本要求\n1.大学专科及以上学历，具备相关领域的知识和经验。\n2.至少5年以上商品与供应链管理、招商采购相关工作经验，有成功案例者优先。\n3.具备较强的沟通能力和执行能力，对市场变化有敏锐的洞察力。\n4.具备良好的解决问题的能力，能够有效应对各种挑战。\n5.具备良好的职业素质，诚信正直；\n6.工作地点为福州市或厦门市，能适应一定频率的出差。\n\n岗位亮点\n1.参与大区品类策略制定和执行，与供应商、团队紧密合作，实现共赢发展。\n2.提供广阔的发展空间和职业晋升机会。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3248041854","sourceKey":"meituan_social","company":"美团","title":"渠道经理","city":"广州市/深圳市/武汉市/长沙市/东莞市/佛山市/桂林市/海口市/南宁市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3248041854&jobShareType=1","duty":"1.负责区域内合作商的挖掘和洽谈合作，制定招商规划，并在规定时间周期内完成招商目标；\n2.基于招商政策，客观评估合作商能力，进行信息提报，跟进招商进展；\n3.负责区域内合作商选、用、育、励、汰，培养更多优质合作商；\n4.协助合作商完成招管培汰、盈亏改善等环节，并就各环节问题，及时反馈给总部协同部门；\n5.负责管辖区内市场及行业信息收集反馈。","requirements":"1.专科及以上学历，3年以上渠道商管理经验；\n2.良好的商务谈判能力，沟通协调能力，能够制定招商规划，对招商结果负责；\n3.具备良好的渠道维护意识，在合作商选、育、用、励、汰环节，有基础的方法和技巧；\n4.积极乐观，敢于挑战，为人正直，诚实可靠。\n具备以下者优先\n1.具备O2O相关行业从业经验，有收银业务经历优先；\n2.能够接受异地出差者优先。","description":"部门介绍\n美团餐饮系统为餐饮企业提供一站式IT解决方案，帮助餐饮商户实现从供应链管理、生产管理、前厅管理到外卖的数字化经营。美团餐饮系统不仅打通了餐厅和平台，更帮助餐厅连接客人，让商户更了解顾客需求，在帮助商户做商业决策的同时给顾客带来更好的消费体验。\n我们持续建设和提升产研、销售、服务的核心能力，通过全新升级的美团餐饮系统一体化软硬件产品，助力餐饮商户进行线上化经营，帮助商户在推广新店、提升效率、降低成本、会员营销、流量扶持、智慧选址、供应链管理等方面强化经营能力。团队汇集了餐饮和SaaS领域的优秀人才，秉持着“以客户为中心”的初心和“长期有耐心”的耕耘精神，求真、敬畏、敢于自我否定、善于快速学习。期待同样愿意长期致力于餐饮产业数字化、智能化的你加入我们的团队，共同进步共同成长！\n\n岗位职责\n1.负责区域内合作商的挖掘和洽谈合作，制定招商规划，并在规定时间周期内完成招商目标；\n2.基于招商政策，客观评估合作商能力，进行信息提报，跟进招商进展；\n3.负责区域内合作商选、用、育、励、汰，培养更多优质合作商；\n4.协助合作商完成招管培汰、盈亏改善等环节，并就各环节问题，及时反馈给总部协同部门；\n5.负责管辖区内市场及行业信息收集反馈。\n\n岗位基本要求\n1.专科及以上学历，3年以上渠道商管理经验；\n2.良好的商务谈判能力，沟通协调能力，能够制定招商规划，对招商结果负责；\n3.具备良好的渠道维护意识，在合作商选、育、用、励、汰环节，有基础的方法和技巧；\n4.积极乐观，敢于挑战，为人正直，诚实可靠。\n具备以下者优先\n1.具备O2O相关行业从业经验，有收银业务经历优先；\n2.能够接受异地出差者优先。\n\n岗位亮点\n1.有机会全身心地参与美团餐饮系统发展机会中，和团队一起探索未来；\n2.我们有开放、直接的工作氛围，以逻辑和事实说话，而不是岗位级别和层级。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4337248740","sourceKey":"meituan_social","company":"美团","title":"商业分析TL","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4337248740&jobShareType=1","duty":"1.基于对医药健康领域的理解和洞察，支持业务规划思考和发展设计，能在关键战略和策略迭代提供专业意见，协助产出短期目标和中长期规划；\n2.逐步完善业务的经营分析体系，包括不断梳理输入/输出指标，完成目标拆解和经营分析（数据监控、结果复盘、专题分析等），提升业务经营管理水平；\n3.在重要专项中，联动多方资源，设定目标，澄清问题，推动共识落地，以业务价值创造为导向开展工作;\n4.运用大模型对用户数据进行智能归因，自动生成分析报告初稿并标注异常指标，将商家分析周期从天级缩短至小时级。","requirements":"1.统计学、数学、经济学、计算机等相关专业，5年以上数据分析工作经验，零售/医药行业优先考虑；\n2.精通相关数据提取工具，熟练操作常用办公软件，善于应用常用数据统计及分析方法；\n3.好奇求知，成长型思维，解决问题的心态，能抓住问题本质，高效解决问题；\n4.能使用大模型辅助用户数据分析，具备自然语言生成SQL、自动化报表解读的实操经验者优先。","description":"部门介绍\n美团医药健康事业部是美团核心本地商业板块下专注健康领域的业务部门，涵盖美团买药、美团医美和美团医疗三大业务。自创立以来，美团医药健康致力于为用户提供全健康周期产品及服务，满足人民群众多层次多元化医疗健康需求，现已覆盖购药到家、居家检测、问诊挂号、医保支付、求医寻院、医疗美容等核心场景。此外，美团医药健康还为商户提供数字化转型创新解决方案，打造贯穿上游的联动机制，长期参与共建更透明、更可持续的医药健康产业生态圈，目前业务已覆盖25万家药店，收录27万家医疗机构。未来，美团医药康将协同更多行业伙伴，帮助大家变得更健康、更美丽、更养生。\n\n岗位职责\n1.基于对医药健康领域的理解和洞察，支持业务规划思考和发展设计，能在关键战略和策略迭代提供专业意见，协助产出短期目标和中长期规划；\n2.逐步完善业务的经营分析体系，包括不断梳理输入/输出指标，完成目标拆解和经营分析（数据监控、结果复盘、专题分析等），提升业务经营管理水平；\n3.在重要专项中，联动多方资源，设定目标，澄清问题，推动共识落地，以业务价值创造为导向开展工作;\n4.运用大模型对用户数据进行智能归因，自动生成分析报告初稿并标注异常指标，将商家分析周期从天级缩短至小时级。\n\n岗位基本要求\n1.统计学、数学、经济学、计算机等相关专业，5年以上数据分析工作经验，零售/医药行业优先考虑；\n2.精通相关数据提取工具，熟练操作常用办公软件，善于应用常用数据统计及分析方法；\n3.好奇求知，成长型思维，解决问题的心态，能抓住问题本质，高效解决问题；\n4.能使用大模型辅助用户数据分析，具备自然语言生成SQL、自动化报表解读的实操经验者优先。\n\n具备以下条件优先\n1.自我驱动、逻辑清晰，具备良好的沟通和协作能力；\n2.有一定的团队管理经验者优先。\n\n岗位亮点\n1.医药零售从业机会，万亿级医疗增量市场，行业前景好；\n2.在快速发展的新业务中，对个人有巨大的成长空间；\n3.我们有开放直接的工作氛围，努力以业务视角思考自身工作。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3329975530","sourceKey":"meituan_social","company":"美团","title":"搜推营销-Keeta搜推算法架构师","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3329975530&jobShareType=1","duty":"1、负责keeta零售业务搜索算法，和产品、运营深度协作，提升多语言搜索用户体验、支持业务目标达成；\n2、跟进业界大语言模型、排序机制、强化学习等方向前沿技术，探索在Keeta搜推业务场景落地；\n3、团队算法人才的招聘和培养。","requirements":"1、5年以上工作经验，有相关大厂在搜索、推荐算法领域的深度工作经验，对业界搜推算法各方向的业务、技术、路径等均有较好理解；\n2、优秀的分析及解决问题的能力，业务理解力强，善于通过技术前置帮助业务，形成策略驱动型合作模式；\n3、有良好的沟通能力，工作积极主动、责任心强，极度关注客户。","description":"部门介绍\n美团核心本地商业下业务研发平台，基于公司“零售+科技”的战略导向，通过从底层架构到应用系统、从软件到硬件、从传统算法到GenAI的全方位技术研究，以及开发、运维、安全等全流程能力建设，致力于推动美团核心本地商业下需求侧与供给侧的数字化和智能化升级，助力业务实现高质量增长，优化用户使用体验，提升商户经营水平，促进行业生态伙伴关系的持续健康发展。团队秉持务实、自驱、开放以及追求卓越的工程师文化，一方面通过系统和技术体系的持续迭代升级，帮助业务高质量增长；另一方面，密切关注前沿技术趋势变化，积极创新技术能力，为业务未来发展创造新的可能性。期待优秀的你加入我们，在夯实专业、深耕平台的基础上与业务携手同行，一起用技术 “帮大家吃得更好，生活更好”。\n\n岗位职责\n1、负责keeta零售业务搜索算法，和产品、运营深度协作，提升多语言搜索用户体验、支持业务目标达成；\n2、跟进业界大语言模型、排序机制、强化学习等方向前沿技术，探索在Keeta搜推业务场景落地；\n3、团队算法人才的招聘和培养。\n\n岗位基本要求\n1、5年以上工作经验，有相关大厂在搜索、推荐算法领域的深度工作经验，对业界搜推算法各方向的业务、技术、路径等均有较好理解；\n2、优秀的分析及解决问题的能力，业务理解力强，善于通过技术前置帮助业务，形成策略驱动型合作模式；\n3、有良好的沟通能力，工作积极主动、责任心强，极度关注客户。\n\n具备以下条件优先\n1、国际化业务算法方向经验；\n2、熟练应用英语作为工作语言；\n3、对搜推领域均了解。\n\n岗位亮点\n1、Keeta业务发展速度快，个人成长和发展空间大；\n2、面临多国家、多时区、多语言的复杂场景挑战，收获国际化视野和技术成就。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4254495491","sourceKey":"meituan_social","company":"美团","title":"导航定位算法工程师","city":"北京市/深圳市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4254495491&jobShareType=1","duty":"1.负责无人机卫星导航、组合导航核心功能模块的开发、测试及上机等；\n2.负责导航系统在GNSS遮挡、干扰和电离层活跃等场景下的性能优化；\n3.支持相关项目开展其它定位技术相关工作。\n4.负责将AI工具与方法应用于算法研发全流程，提升开发效率与解决方案的智能化水平；","requirements":"1.具有良好的数学基础，对于线性代数、优化理论、概率论、矩阵计算、数值分析等有深刻理解；\n2.具有良好的计算机原理基础知识和较强C/C++代码工程化能力和经验；\n3.熟练掌握多传感器融合理论基础，有惯导、AHRS、GNSS等算法的开发应用经验，并有应用多种传感器融合的经验；\n4.具有解决导航定位算法落地中问题的能力，提升全天候全天时情况下的导航定位系统精度和可靠性；\n5.具有较强自我驱动能力、团队协作开发能力经验和算法创新能力；\n6.熟练运用AI辅助工具（如代码生成、数据分析、模型调优等）进行算法开发与优化；\n7.具备利用AI技术解决复杂工程问题的能力，并能评估其在实际场景中的有效性与局限性。","description":"部门介绍\n为了更好地提升城市即时配送的效率与体验，2017年，美团启动了无人机配送服务的探索，通过科技创新推动履约工具变革，加快建设空地协同的本地即时配送网络。\n在过去的六年里，美团无人机完成了飞行器、自动化机场及智能调度系统的研发工作，实现了研发设计、生产制造、运营运维全链条布局，达成了城市复杂场景物流无人机高频次、高密度、多天时、多天侯运行。\n2023年7月，美团无人机在上海发布了自主研发的第四代无人机，跟此前机型相比，新机型升级了环境适应能力，可在“零下20度至50度”的中雨、中雪、6级风、弱光等环境中稳定飞行，能够适应97%以上国内城市的自然环境要求。\n截至2024年12月，美团无人机已在深圳、北京、上海、广州、南京、迪拜等城市开通53条航线，并累计完成订单超40万单。即时零售配送服务覆盖了办公、社区、景区、市政公园、校园、医疗、图书馆等多种场景。在医疗场景中，美团无人机可围绕医疗血液、检验样本、院前急救物资、特殊药品等医疗物资配送需求建设端到端的全天时急送网络。\n\n岗位职责\n1.负责无人机卫星导航、组合导航核心功能模块的开发、测试及上机等；\n2.负责导航系统在GNSS遮挡、干扰和电离层活跃等场景下的性能优化；\n3.支持相关项目开展其它定位技术相关工作。\n4.负责将AI工具与方法应用于算法研发全流程，提升开发效率与解决方案的智能化水平；\n\n岗位基本要求\n1.具有良好的数学基础，对于线性代数、优化理论、概率论、矩阵计算、数值分析等有深刻理解；\n2.具有良好的计算机原理基础知识和较强C/C++代码工程化能力和经验；\n3.熟练掌握多传感器融合理论基础，有惯导、AHRS、GNSS等算法的开发应用经验，并有应用多种传感器融合的经验；\n4.具有解决导航定位算法落地中问题的能力，提升全天候全天时情况下的导航定位系统精度和可靠性；\n5.具有较强自我驱动能力、团队协作开发能力经验和算法创新能力；\n6.熟练运用AI辅助工具（如代码生成、数据分析、模型调优等）进行算法开发与优化；\n7.具备利用AI技术解决复杂工程问题的能力，并能评估其在实际场景中的有效性与局限性。\n\n具备以下条件优先\n1.有AR/VR、机器人或无人机的导航定位项目实际开发经验或相关比赛经验者优先；\n2.具备多传感器融合和挑战场景的定位算法优化经验，或发表过前沿研究论文成果者优先。\n\n岗位亮点\n1.和具有世界一流技术团队合作的机会及经验分享，提供广阔的成长空间；\n2.多样的内部分享，完美的落地场景，解决实际业务中的问题；\n3.良好的技术氛围和多样的团队活动，使工作充满乐趣。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4627056546","sourceKey":"meituan_social","company":"美团","title":"猫眼服务流程运营","city":"北京市/上海市/武汉市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4627056546&jobShareType=1","duty":"1. 负责猫眼平台服务运营体系的搭建与优化，提升用户体验和服务效率。  \n2. 分析用户行为数据，识别服务痛点并对接业务推动产品、技术团队进行改进。  \n3. 制定并执行服务标准流程，确保服务质量和响应时效符合业务目标。  \n4. 协调内外部资源，处理重大客诉及突发事件，保障平台服务稳定性。  \n5. 探索并落地客服大模型在服务场景中的应用，提升自动化服务能力。","requirements":"1. 大学本科及以上学历，具备3年以上服务运营或相关业务运营经验。  \n2. 熟悉互联网平台服务流程，具备较强的数据分析能力和用户洞察力。  \n3. 具备良好的沟通协调能力和跨团队协作能力，能独立推动项目落地。  \n4. 了解AI及大模型技术，有客服智能化项目经验者优先。  \n5. 能适应一定强度的业务节奏。","description":"部门介绍\n美团平台为用户的基础产品体验负责，还承担了美团的用户增长、市场和品牌营销以及多条业务线的产品设计职责，建立了融合文字、图片、视频和直播等不同形式的內容生态系统，同时整合地图服务部、客户服务和体验部、企业业务部、网约车业务部等部门，致力于用科技提升美团数亿消费者、近千万商家、骑手、司机和团长的服务体验。美团平台拥有高并发、多业务的复杂场景，为技术深度优化提供了最佳实践可能。这里有简单、讲逻辑、有爱的团队，更是一块理想的实战场地，舞台广阔，欢迎你来尽情施展。\n\n岗位职责\n1. 负责猫眼平台服务运营体系的搭建与优化，提升用户体验和服务效率。  \n2. 分析用户行为数据，识别服务痛点并对接业务推动产品、技术团队进行改进。  \n3. 制定并执行服务标准流程，确保服务质量和响应时效符合业务目标。  \n4. 协调内外部资源，处理重大客诉及突发事件，保障平台服务稳定性。  \n5. 探索并落地客服大模型在服务场景中的应用，提升自动化服务能力。\n\n岗位基本要求\n1. 大学本科及以上学历，具备3年以上服务运营或相关业务运营经验。  \n2. 熟悉互联网平台服务流程，具备较强的数据分析能力和用户洞察力。  \n3. 具备良好的沟通协调能力和跨团队协作能力，能独立推动项目落地。  \n4. 了解AI及大模型技术，有客服智能化项目经验者优先。  \n5. 能适应一定强度的业务节奏。\n\n具备以下条件优先\n了解、熟悉电影及演出行业，有对应工作经验优先考虑\n\n岗位亮点\n1. 加入快速发展的大文娱平台，参与核心服务体系建设。  \n2. 与产品、技术、客服等多团队深度协作，提升综合运营能力。  \n3. 提供完善的职业发展路径和培训资源，助力个人成长。  \n4. 参与前沿AI技术在客服领域的应用实践，积累智能化运营经验。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4094428125","sourceKey":"meituan_social","company":"美团","title":"美团纠纷与治理服务流程管理","city":"上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4094428125&jobShareType=1","duty":"● 负责制定并持续改善用户/商户服务的工作流程、执行规范等基础制度，并能落地实施；\n● 持续提升服务解决能力，探索AI智能分单、智能辅助应答等能力建设，联动协同团队前置服务解决效率；\n● 通过日常的客户反馈、业务策略分析等手段发现痛点问题，建立有效的流程运营机制，提升服务团队解决问题的能力；\n● 深入业务线的各个环节，对棘手问题有序梳理，主为业务团队提供前瞻性的改善建议，并主导或协同推动优化方案落地。","requirements":"● 具备3年以上互联网行业服务运营经验，有本地生活行业的服务运营经验者优先；\n● 熟悉服务流程设计，具备流程优化、效果评估及迭代经验。了解智能服务运营方法、流程系统化落地方法，能推动流程有效执行和目标达成；\n了解AI在服务运营中的前沿应用（如GPT/Claude辅助SOP撰写、AI智能路由、智能质检），具备推动AI+服务流程创新的意识；\n● 能精准定位客户痛点，解析影响客户问题的具体因素，并提供合理化的解决方案；\n● 具备发现问题及主动改善能力，以及较强的业务推动能力，提出完整的优化方案，并推动方案执行达成结果；\n● 能够协同或整合内外部资源 ，有团队合作精神，工作严谨踏实，责任心强。","description":"部门介绍\n美团平台为用户的基础产品体验负责，还承担了美团的用户增长、市场和品牌营销以及多条业务线的产品设计职责，建立了融合文字、图片、视频和直播等不同形式的內容生态系统，同时整合地图服务部、客户服务和体验部、企业业务部、网约车业务部等部门，致力于用科技提升美团数亿消费者、近千万商家、骑手、司机和团长的服务体验。美团平台拥有高并发、多业务的复杂场景，为技术深度优化提供了最佳实践可能。这里有简单、讲逻辑、有爱的团队，更是一块理想的实战场地，舞台广阔，欢迎你来尽情施展。\n\n岗位职责\n● 负责制定并持续改善用户/商户服务的工作流程、执行规范等基础制度，并能落地实施；\n● 持续提升服务解决能力，探索AI智能分单、智能辅助应答等能力建设，联动协同团队前置服务解决效率；\n● 通过日常的客户反馈、业务策略分析等手段发现痛点问题，建立有效的流程运营机制，提升服务团队解决问题的能力；\n● 深入业务线的各个环节，对棘手问题有序梳理，主为业务团队提供前瞻性的改善建议，并主导或协同推动优化方案落地。\n\n岗位基本要求\n● 具备3年以上互联网行业服务运营经验，有本地生活行业的服务运营经验者优先；\n● 熟悉服务流程设计，具备流程优化、效果评估及迭代经验。了解智能服务运营方法、流程系统化落地方法，能推动流程有效执行和目标达成；\n了解AI在服务运营中的前沿应用（如GPT/Claude辅助SOP撰写、AI智能路由、智能质检），具备推动AI+服务流程创新的意识；\n● 能精准定位客户痛点，解析影响客户问题的具体因素，并提供合理化的解决方案；\n● 具备发现问题及主动改善能力，以及较强的业务推动能力，提出完整的优化方案，并推动方案执行达成结果；\n● 能够协同或整合内外部资源 ，有团队合作精神，工作严谨踏实，责任心强。\n\n具备以下条件优先\n● 具备治理申诉及纠纷判责服务运营相关经验；\n● 具有大模型在服务场景应用落地经验；\n● 3年以上项目管理经验。\n\n岗位亮点\n● 高度专业化的服务运营管理体系，有充分的资源实施运营策略；\n● 有机会主R复杂业务场景中跨部门重大项目管理工作。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3600378954","sourceKey":"meituan_social","company":"美团","title":"美团服务运营-本地生活","city":"北京市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3600378954&jobShareType=1","duty":"1.负责服务零售业务（如休闲娱乐、丽人、生活服务等行业）的服务全链路的日常运营，借助AI工具持续改善用户/商户服务的工作流程、执行规范等基础制度，并能落地实施；\n2.通过智能AI持续提升服务解决能力，关注客户体验，建立有效的运营机制，赋能客服团队并提升其解决问题的能力；\n3.通过客户声音的洞察、分析，发现痛点问题，与协同团队密切合作，推动问题从源头解决，通过智能质检系统替代人工抽样复核；\n4.主导服务改善项目，从立项、执行到闭环管理，推动跨部门协作，确保项目高效落地；\n5.通过大模型对客户反馈进行智能聚类分析，自动提炼服务链路中的高频痛点与改善机会，替代人工逐条分析，将VOC洞察周期从周级缩短至日级。","requirements":"1.具备3年以上互联网行业服务运营经验，有本地生活行业的服务运营经验者优先；\n2.熟悉服务流程设计，具备流程优化、效果评估及迭代经验。了解智能服务运营方法、流程系统化落地方法，能推动流程有效执行和目标达成。\n3. 具备项目管理经验，能从目标设定到执行落地实现闭环管理，具备较强的数据分析能力和解决问题能力。\n4.了解ChatGPT/Claude等AI工具在SOP撰写、流程优化方案设计中的应用，有AI辅助服务运营的实践经验优先。","description":"部门介绍\n美团平台为用户的基础产品体验负责，还承担了美团的用户增长、市场和品牌营销以及多条业务线的产品设计职责，建立了融合文字、图片、视频和直播等不同形式的內容生态系统，同时整合地图服务部、客户服务和体验部、企业业务部、网约车业务部等部门，致力于用科技提升美团数亿消费者、近千万商家、骑手、司机和团长的服务体验。美团平台拥有高并发、多业务的复杂场景，为技术深度优化提供了最佳实践可能。这里有简单、讲逻辑、有爱的团队，更是一块理想的实战场地，舞台广阔，欢迎你来尽情施展。\n\n岗位职责\n1.负责服务零售业务（如休闲娱乐、丽人、生活服务等行业）的服务全链路的日常运营，借助AI工具持续改善用户/商户服务的工作流程、执行规范等基础制度，并能落地实施；\n2.通过智能AI持续提升服务解决能力，关注客户体验，建立有效的运营机制，赋能客服团队并提升其解决问题的能力；\n3.通过客户声音的洞察、分析，发现痛点问题，与协同团队密切合作，推动问题从源头解决，通过智能质检系统替代人工抽样复核；\n4.主导服务改善项目，从立项、执行到闭环管理，推动跨部门协作，确保项目高效落地；\n5.通过大模型对客户反馈进行智能聚类分析，自动提炼服务链路中的高频痛点与改善机会，替代人工逐条分析，将VOC洞察周期从周级缩短至日级。\n\n岗位基本要求\n1.具备3年以上互联网行业服务运营经验，有本地生活行业的服务运营经验者优先；\n2.熟悉服务流程设计，具备流程优化、效果评估及迭代经验。了解智能服务运营方法、流程系统化落地方法，能推动流程有效执行和目标达成。\n3. 具备项目管理经验，能从目标设定到执行落地实现闭环管理，具备较强的数据分析能力和解决问题能力。\n4.了解ChatGPT/Claude等AI工具在SOP撰写、流程优化方案设计中的应用，有AI辅助服务运营的实践经验优先。\n\n具备以下条件优先\n有大模型等智能能力应用于运营工作成功经验的优先。\n\n岗位亮点\n1.拥抱AI，具备高度专业化的服务运营管理体系，有充分的资源实施运营策略；\n2.生活服务行业前景广阔，有丰富的职业发展机会；\n3.完善的五险一金、年度体检、带薪年假等福利；\n4.有机会参与智能客服系统建设，将传统服务运营升级为AI驱动的智能化运营模式。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4469038976","sourceKey":"meituan_social","company":"美团","title":"内部审计-合规审计专家","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4469038976&jobShareType=1","duty":"1、负责依据审计计划针对特定岗位开展专项审计（例如离任、任中审计）及管理评价工作，对特定岗位人员的个人及业务管理方面进行审计，重点评估特定岗位人员在个人合规方面是否存在违反公司规定行为，在业务管理方面是否存在重大管理漏洞、重大损失及舞弊风险等；\n2、负责主导或参与审计项目全周期事宜，包括审计调研立项、制定审计方案、执行审计程序、审计问题确认、审计结果汇报、撰写审计报告等；\n3、负责对审计发现进行深入分析，包括分析问题根因、问题影响，提出审计建议，并联合业务及相关部门推进问题整改/风险治理；\n4、负责在审计项目基础上沉淀审计规则，结合AI工具建立审计模型，推动审计场景的智能化与自动化落地；探索将AI应用于风险识别、异常检测等核心环节，持续提升审计效率和发现质量；\n5、负责对项目组遇到的问题进行协调和解决；\n6、完成上级主管安排的其他临时协助事项。","requirements":"1、本科以上学历，6年及以上内审、调查、合规等工作经验，有互联网行业从业经历者优先，有内审+调查经验者优先；\n2、有CIA、CPA、ACCA等资质证书者优先；\n3、可以完成审计项目全周期的程序执行；\n4、熟悉财务、审计相关标准，熟悉IIA国际内部审计实务标准，熟悉中国企业内部控制基本规范及相关指引；\n5、具备AI思维与工具应用能力，能将AI能力主动引入风险识别、数据分析、异常检测、报告撰写等审计场景；熟练使用至少一种AI工具（ChatGPT/Kimi/豆包/Claude等）辅助日常工作；有AI审计模型搭建、提示词工程或数据分析自动化相关实践经验者优先；\n6、良好的沟通协调和人际关系能力，良好的口头和书面表达能力。","description":"部门介绍\n财务平台负责公司整体和各业务层面的财务管理工作，通过建设专业、全面、复合的财务管理能力和与业务经营的紧密结合来支持公司健康发展。目前财务平台拥有财务会计、财务报告、资金管理、税务管理、财务共享、财务系统、规划分析、财务BP和内控内审等主要工作方向。我们的目标是建设业界一流的财务管理能力和经营支持体系，为公司战略的正确落地、投入效率的持续提升、业务价值的不断增长保驾护航。欢迎加入财务平台，携手一起向未来！\n\n岗位职责\n1、负责依据审计计划针对特定岗位开展专项审计（例如离任、任中审计）及管理评价工作，对特定岗位人员的个人及业务管理方面进行审计，重点评估特定岗位人员在个人合规方面是否存在违反公司规定行为，在业务管理方面是否存在重大管理漏洞、重大损失及舞弊风险等；\n2、负责主导或参与审计项目全周期事宜，包括审计调研立项、制定审计方案、执行审计程序、审计问题确认、审计结果汇报、撰写审计报告等；\n3、负责对审计发现进行深入分析，包括分析问题根因、问题影响，提出审计建议，并联合业务及相关部门推进问题整改/风险治理；\n4、负责在审计项目基础上沉淀审计规则，结合AI工具建立审计模型，推动审计场景的智能化与自动化落地；探索将AI应用于风险识别、异常检测等核心环节，持续提升审计效率和发现质量；\n5、负责对项目组遇到的问题进行协调和解决；\n6、完成上级主管安排的其他临时协助事项。\n\n岗位基本要求\n1、本科以上学历，6年及以上内审、调查、合规等工作经验，有互联网行业从业经历者优先，有内审+调查经验者优先；\n2、有CIA、CPA、ACCA等资质证书者优先；\n3、可以完成审计项目全周期的程序执行；\n4、熟悉财务、审计相关标准，熟悉IIA国际内部审计实务标准，熟悉中国企业内部控制基本规范及相关指引；\n5、具备AI思维与工具应用能力，能将AI能力主动引入风险识别、数据分析、异常检测、报告撰写等审计场景；熟练使用至少一种AI工具（ChatGPT/Kimi/豆包/Claude等）辅助日常工作；有AI审计模型搭建、提示词工程或数据分析自动化相关实践经验者优先；\n6、良好的沟通协调和人际关系能力，良好的口头和书面表达能力。\n\n岗位亮点\n广泛接触公司各项业务模式，深度解析业务及个人合规风险，有机会接触各级管理层，探讨业务风险及优化措施，提升审计视角和格局；同时在AI与审计深度融合的场景中积累人机协作的实战经验，探索审计智能化的前沿方法论。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4360716238","sourceKey":"meituan_social","company":"美团","title":"用户分析专家","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4360716238&jobShareType=1","duty":"1. 负责用户行为数据的收集、清洗与分析，构建用户画像与分层模型。  \n2. 深入挖掘用户需求与痛点，输出可落地的业务洞察与优化建议。  \n3. 设计并执行用户调研、A/B测试等研究方案，评估产品与运营策略效果。  \n4. 协同产品、运营、市场等团队，推动数据驱动的用户增长与体验提升。  \n5. 建立并维护用户分析指标体系，定期输出分析报告与趋势预警。","requirements":"1. 大学本科及以上学历，统计学、数学、计算机、心理学或相关专业优先。  \n2. 5年以上用户分析或商业分析相关工作经验，具备互联网行业背景。  \n3. 熟练使用数据分析工具，熟悉常用数据可视化平台。  \n4. 具备优秀的逻辑思维与沟通能力，能独立完成复杂分析项目。  \n5. 对用户体验敏感，具备较强的业务理解与跨团队协作能力。\n6.加分项：\n具备较好的自主学习能力，对AI新技术抱有浓厚兴趣，乐于探索AI可能性；\n熟练使用 AI 工具（如大模型对话、AI 搜索、智能分析平台等）辅助研究工作，在实际项目中有明确的效率提升实践。","description":"部门介绍\n美团的使命是“帮大家吃得更好，生活更好”，公司聚焦“零售 + 科技”战略，和广大商户与各类合作伙伴一起，努力为消费者提供品质生活，推动商品零售和服务零售在需求侧和供给侧的数字化转型。\n2018年9月20日，美团正式在港交所挂牌上市。美团将始终坚持以客户为中心，不断加大在科技研发方面的投入，更好承担社会责任，更多创造社会价值，与广大合作伙伴一起发展共赢。\n\n岗位职责\n1. 负责用户行为数据的收集、清洗与分析，构建用户画像与分层模型。  \n2. 深入挖掘用户需求与痛点，输出可落地的业务洞察与优化建议。  \n3. 设计并执行用户调研、A/B测试等研究方案，评估产品与运营策略效果。  \n4. 协同产品、运营、市场等团队，推动数据驱动的用户增长与体验提升。  \n5. 建立并维护用户分析指标体系，定期输出分析报告与趋势预警。\n\n岗位基本要求\n1. 大学本科及以上学历，统计学、数学、计算机、心理学或相关专业优先。  \n2. 5年以上用户分析或商业分析相关工作经验，具备互联网行业背景。  \n3. 熟练使用数据分析工具，熟悉常用数据可视化平台。  \n4. 具备优秀的逻辑思维与沟通能力，能独立完成复杂分析项目。  \n5. 对用户体验敏感，具备较强的业务理解与跨团队协作能力。\n6.加分项：\n具备较好的自主学习能力，对AI新技术抱有浓厚兴趣，乐于探索AI可能性；\n熟练使用 AI 工具（如大模型对话、AI 搜索、智能分析平台等）辅助研究工作，在实际项目中有明确的效率提升实践。\n\n岗位亮点\n1. 参与核心用户增长项目，直接影响产品战略与业务决策。  \n2. 与行业专业团队共事，获得快速成长与专业能力提升。  \n3. 开放包容的工作环境，鼓励创新与数据驱动的文化氛围。  \n4. 提供具有竞争力的薪酬福利与完善的职业发展通道。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4629298391","sourceKey":"meituan_social","company":"美团","title":"物流-仓储-仓储主管--生产主管","city":"苏州市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4629298391&jobShareType=1","duty":"1.负责冻品仓储业务运营，包括收、存、分、发的操作管理；自有及外包人员的培养及管理；\n2.负责冻品仓流程优化和模式创新；\n3.负责冻品仓仓储成本的控制优化。","requirements":"1.大专及以上学历；\n2.3年以上物流或电商行业仓储运营管理经验；\n3.具备仓储现场管理的团队经验；\n4.熟悉WMS系统逻辑和操作；\n5.较强的沟通协调能力。\n6.能适应长期晚班","description":"部门介绍\n快驴进货是美团旗下的餐饮供应链平台，帮助餐饮商户以更低成本、更高效率来获取安全可靠的食材供应，让餐饮采购更简单。快驴进货同步发展“自营+平台”的业务模式，在采购环节一方面向上游供应商直采大宗商品，另一方面引入各地批发商，助力平台伙伴共同发展；在销售环节既有自建团队进行市场、客户拓展，又帮助各地批发商拓展业务；同时自建仓储管理系统、配送网络与团队，为客户提供优质履约服务。\n截至2022年，快驴进货布局了全国41个城市，为百万家商户提供“全、省、稳、好”的餐饮供应链服务。我们拥有3000+品牌食材、超5万SKU商品、超28万商品资质，并提供源头严审核、食品安全严把关、24小时无忧售后的全面保障，实现手机下单、送货上门的高效采购模式，帮百万商家节省了采购时间与成本，助力平台伙伴共同发展，在万亿市场共享机遇。\n在这里，你将收获完善的员工发展机制及学习体系，与各界专家一起深度参与餐饮供应链业务的发展。欢迎优秀的你加入美团快驴进货，与我们一起成长，一起更好！\n\n岗位职责\n1.负责冻品仓储业务运营，包括收、存、分、发的操作管理；自有及外包人员的培养及管理；\n2.负责冻品仓流程优化和模式创新；\n3.负责冻品仓仓储成本的控制优化。\n\n岗位基本要求\n1.大专及以上学历；\n2.3年以上物流或电商行业仓储运营管理经验；\n3.具备仓储现场管理的团队经验；\n4.熟悉WMS系统逻辑和操作；\n5.较强的沟通协调能力。\n6.能适应长期晚班\n\n具备以下条件优先\n1、有生鲜行业物流仓储相关经验者；\n2、有较长时间冻品管理经验者；\n3、有做过RDC仓库管理，尤其是冻品RDC经验者；\n4、大型互联网电商仓储管理经验者优先；\n5、50人以上团队管理经验优先。\n\n岗位亮点\n1.在早期加入生鲜B2B电商领域，与来自电商、物流和商超的精英同仁一同努力，构建供给侧的数字化与智能化。\n2.该岗位负责工作位公司大力推进的模式创新，资源充足，受关关注程度高，未来发展空间大；","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4634561886","sourceKey":"meituan_social","company":"美团","title":"快驴-重庆沙坪坝仓调度主管","city":"重庆市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4634561886&jobShareType=1","duty":"1、负责司机团队人员的日常管理，包含招培管评全流程。\n2、结合业务动态安排司机排线、车辆的规划及布置。\n3、建立司机车辆引入合规和驾驶行为规范。\n4、司机作业SOP的推动和落地，实现作业标准化和客户体验的提升。\n5、及时与上下游环节沟通当日业务量及异常事项。\n6、组织交代的其他交付工作；","requirements":"1.大专以上学历。\n2.有2年以上直营车队管理经验；\n3.较好的沟通和协调能力，具备较强的现场管理能力；\n4.岗位需要较强吃苦能力。","description":"部门介绍\n快驴进货是美团旗下的餐饮供应链平台，帮助餐饮商户以更低成本、更高效率来获取安全可靠的食材供应，让餐饮采购更简单。快驴进货同步发展“自营+平台”的业务模式，在采购环节一方面向上游供应商直采大宗商品，另一方面引入各地批发商，助力平台伙伴共同发展；在销售环节既有自建团队进行市场、客户拓展，又帮助各地批发商拓展业务；同时自建仓储管理系统、配送网络与团队，为客户提供优质履约服务。\n截至2022年，快驴进货布局了全国41个城市，为百万家商户提供“全、省、稳、好”的餐饮供应链服务。我们拥有3000+品牌食材、超5万SKU商品、超28万商品资质，并提供源头严审核、食品安全严把关、24小时无忧售后的全面保障，实现手机下单、送货上门的高效采购模式，帮百万商家节省了采购时间与成本，助力平台伙伴共同发展，在万亿市场共享机遇。\n在这里，你将收获完善的员工发展机制及学习体系，与各界专家一起深度参与餐饮供应链业务的发展。欢迎优秀的你加入美团快驴进货，与我们一起成长，一起更好！\n\n岗位职责\n1、负责司机团队人员的日常管理，包含招培管评全流程。\n2、结合业务动态安排司机排线、车辆的规划及布置。\n3、建立司机车辆引入合规和驾驶行为规范。\n4、司机作业SOP的推动和落地，实现作业标准化和客户体验的提升。\n5、及时与上下游环节沟通当日业务量及异常事项。\n6、组织交代的其他交付工作；\n\n岗位基本要求\n1.大专以上学历。\n2.有2年以上直营车队管理经验；\n3.较好的沟通和协调能力，具备较强的现场管理能力；\n4.岗位需要较强吃苦能力。\n\n具备以下条件优先\n有7方以上面包车、金杯车、4.2米小型货车司机资源优先\n\n岗位亮点\n公司提供良好的晋升空间和培训机会，员工福利待遇优厚\n具备以下优先:\n有7方以上面包车、金杯车、4.2米小型货车司机资源优先；","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3573875170","sourceKey":"meituan_social","company":"美团","title":"精益与项目管理","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3573875170&jobShareType=1","duty":"1、分析报告出具及专项抽检：出具运营月报，通过月报分析和专项抽检等方式，识别风险及提出改进建议，并监控落地执行效果。\n2、风险监控及数据分析：建立并优化财务结算/核算监控指标体系，通过数据分析识别风险流程，输出分析报告，牵头拟定治理策略并跟踪落地效果。\n3、横向专项分析：通过行业对标、数据分析、调研访谈等方式进行专项分析，推动解决识别到的财务结算/核算流程中的痛点和问题，推进流程优化；\n4、智能运营能力建设：对接研发团队，推动AI等智能工具在结/核算流程中的应用，提升工作效率。\n5、与财务其他团队积极协调，完成其他指定任务。","requirements":"1、大学本科及以上学历，会计、财务管理、审计相关专业背景；\n2、5年以上财务工作经验，有结算工作经验强加分项。\n3、有财务结算流程建设或财务操作系统建设类项目经验，具备很好的沟通、表达及协同能力。\n4、具备风险管理和数据分析能力，熟悉财务结算/核算流程。\n5、鼓励有AI落地经验同学","description":"部门介绍\n财务平台负责公司整体和各业务层面的财务管理工作，通过建设专业、全面、复合的财务管理能力和与业务经营的紧密结合来支持公司健康发展。目前财务平台拥有财务会计、财务报告、资金管理、税务管理、财务共享、财务系统、规划分析、财务BP和内控内审等主要工作方向。我们的目标是建设业界一流的财务管理能力和经营支持体系，为公司战略的正确落地、投入效率的持续提升、业务价值的不断增长保驾护航。欢迎加入财务平台，携手一起向未来！\n\n岗位职责\n1、分析报告出具及专项抽检：出具运营月报，通过月报分析和专项抽检等方式，识别风险及提出改进建议，并监控落地执行效果。\n2、风险监控及数据分析：建立并优化财务结算/核算监控指标体系，通过数据分析识别风险流程，输出分析报告，牵头拟定治理策略并跟踪落地效果。\n3、横向专项分析：通过行业对标、数据分析、调研访谈等方式进行专项分析，推动解决识别到的财务结算/核算流程中的痛点和问题，推进流程优化；\n4、智能运营能力建设：对接研发团队，推动AI等智能工具在结/核算流程中的应用，提升工作效率。\n5、与财务其他团队积极协调，完成其他指定任务。\n\n岗位基本要求\n1、大学本科及以上学历，会计、财务管理、审计相关专业背景；\n2、5年以上财务工作经验，有结算工作经验强加分项。\n3、有财务结算流程建设或财务操作系统建设类项目经验，具备很好的沟通、表达及协同能力。\n4、具备风险管理和数据分析能力，熟悉财务结算/核算流程。\n5、鼓励有AI落地经验同学\n\n具备以下条件优先\n1、互联网行业/零售行业工作经历优先，四大内控咨询项目经历者优先；\n2、有结算流程线上化，供应链、物流履约财务相关流程线上化项目经验者优先；\n\n岗位亮点\n1、能从财务管理整体视角审视系统、流程、财务管控点等，从财务控制角度推动业财系统和流程建设，为企业创造价值的同时，对个人能力模型也有很强的增值效应。\n2、能接触到多个零售行业的业务模式，深入了解零售行业，亲历并见证风口行业的快速发展；\n3、行业复杂度高，对财务人的塑造和锻炼非常大，能对业务产生深刻价值创造；\n4、有丰富接触AI、探索解决方案的机会","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4564164243","sourceKey":"meituan_social","company":"美团","title":"食杂零售财务运营方案岗","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4564164243&jobShareType=1","duty":"1、结算运营管理：深入理解业务逻辑与结算系统规则，建立并持续优化结算流程体系，推动结算需求高效落地；负责日常合同审批、计费底稿审核、对账及结算管理、发票管理等核心运营工作，对结算准确性、及时性承担管理责任。\n2、核算运营管理：协同支持所负责业务场景的月度会计结账，确保入账及时性、准确性；能够识别核算差异并主动推动业财数据一致性治理。\n3、风险监控与数据分析：搭建并迭代运营风险监控机制与预警体系，通过数据分析主动识别财务风险，输出分析结论与治理建议，并跟踪落地效果，为管理层决策提供数据支撑。\n4、系统与流程优化：主动识别业财结算环节痛点与瓶颈，设计系统优化方案并推动与业务、产品、技术团队的高效协同落地，持续提升结核算自动化与线上化水平。\n5、专项管理与横向对标：主导专项梳理与行业/内部横向对标，输出财务信息化与运营流程优化方案，推动落地并量化效果；主动发现、解决结算运营中的复杂问题，提升财务管理质量与运营效率。\n6、跨团队协同：与财务内部各团队及业务侧保持高效协作，确保结算运营工作的顺畅运转。","requirements":"1、大学本科及以上学历，会计、经济、管理类等相关专业，3年以上财会相关工作经验，在结算领域有丰富的结算运营管理及系统流程建设经验；\n2、熟练掌握常用办公软件的使用；\n3、较强的分析能力、清晰的思维逻辑和创新意识，能够基于数据发现问题和解决问题；\n5、具有良好的沟通能力、团队精神、工作态度、学习能力，高度的自我驱动和结果导向。","description":"部门介绍\n财务平台负责公司整体和各业务层面的财务管理工作，通过建设专业、全面、复合的财务管理能力和与业务经营的紧密结合来支持公司健康发展。目前财务平台拥有财务会计、财务报告、资金管理、税务管理、财务共享、财务系统、规划分析、财务BP和内控内审等主要工作方向。我们的目标是建设业界一流的财务管理能力和经营支持体系，为公司战略的正确落地、投入效率的持续提升、业务价值的不断增长保驾护航。欢迎加入财务平台，携手一起向未来！\n\n岗位职责\n1、结算运营管理：深入理解业务逻辑与结算系统规则，建立并持续优化结算流程体系，推动结算需求高效落地；负责日常合同审批、计费底稿审核、对账及结算管理、发票管理等核心运营工作，对结算准确性、及时性承担管理责任。\n2、核算运营管理：协同支持所负责业务场景的月度会计结账，确保入账及时性、准确性；能够识别核算差异并主动推动业财数据一致性治理。\n3、风险监控与数据分析：搭建并迭代运营风险监控机制与预警体系，通过数据分析主动识别财务风险，输出分析结论与治理建议，并跟踪落地效果，为管理层决策提供数据支撑。\n4、系统与流程优化：主动识别业财结算环节痛点与瓶颈，设计系统优化方案并推动与业务、产品、技术团队的高效协同落地，持续提升结核算自动化与线上化水平。\n5、专项管理与横向对标：主导专项梳理与行业/内部横向对标，输出财务信息化与运营流程优化方案，推动落地并量化效果；主动发现、解决结算运营中的复杂问题，提升财务管理质量与运营效率。\n6、跨团队协同：与财务内部各团队及业务侧保持高效协作，确保结算运营工作的顺畅运转。\n\n岗位基本要求\n1、大学本科及以上学历，会计、经济、管理类等相关专业，3年以上财会相关工作经验，在结算领域有丰富的结算运营管理及系统流程建设经验；\n2、熟练掌握常用办公软件的使用；\n3、较强的分析能力、清晰的思维逻辑和创新意识，能够基于数据发现问题和解决问题；\n5、具有良好的沟通能力、团队精神、工作态度、学习能力，高度的自我驱动和结果导向。\n\n具备以下条件优先\n1、互联网行业/零售行业工作经验优先、有会计师事务所工作经验优先；\n2、有结算流程线上化，供应链、物流履约财务相关流程线上化项目经验者优先；\n3、有专业数据分析工具使用技能者优先；\n4、熟练掌握AI应用能力者优先。\n\n岗位亮点\n1、深入了解新零售行业业务，亲历并见证风口行业的快速发展；\n2、行业复杂度高，对财务人的塑造和锻炼非常大，能对业务产生深刻价值创造；\n3、跟一群聪颖又富有激情的小伙伴一起学习奋斗，见证不如建设！","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4571229152","sourceKey":"meituan_social","company":"美团","title":"零售财务运营-keemart财务方案","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4571229152&jobShareType=1","duty":"1.业务支持：负责对接业务需求，在充分理解业务场景的基础上，结合会计准则，结算规则，合规要求等，识别和判断业务活动对财务的影响，出具相应的综合财务解决方案（结算&核算），为业务部门的发展及商业决策提供积极的财务支持；\n2.提升财务信息化能力：结合对业务场景及业财系统的深入理解，与各方产研配合推进财务信息化建设，包括业务场景的线上计费结算、线上化传账及业财数据校验、财务系统优化升级等；\n3.业财流程优化：定期参与合作商/业务部门调研，针对核心痛点问题推进财务运营流程优化，发现并解决各类财务问题，提高财务结果的效率和准确性；\n4.其他：与财务其他团队积极协调，完成其他指定任务。","requirements":"1.本科及其以上学历，会计、经济、管理类等相关专业，5年及以上财会相关工作经验，有结核算相关经验以及财务系统对接经验；\n2.具备较强的业务理解力，沟通能力、协调能力，能和业务线对接，具备优秀的逻辑思维和分析能力；\n3.工作认真细心、责任心强、具有良好的团队协作精神和服务意识；\n4.能够以英文作为日常工作沟通语言；\n5.能够适应业务需求进行海外出差。","description":"部门介绍\n财务平台负责公司整体和各业务层面的财务管理工作，通过建设专业、全面、复合的财务管理能力和与业务经营的紧密结合来支持公司健康发展。目前财务平台拥有财务会计、财务报告、资金管理、税务管理、财务共享、财务系统、规划分析、财务BP和内控内审等主要工作方向。我们的目标是建设业界一流的财务管理能力和经营支持体系，为公司战略的正确落地、投入效率的持续提升、业务价值的不断增长保驾护航。欢迎加入财务平台，携手一起向未来！\n\n岗位职责\n1.业务支持：负责对接业务需求，在充分理解业务场景的基础上，结合会计准则，结算规则，合规要求等，识别和判断业务活动对财务的影响，出具相应的综合财务解决方案（结算&核算），为业务部门的发展及商业决策提供积极的财务支持；\n2.提升财务信息化能力：结合对业务场景及业财系统的深入理解，与各方产研配合推进财务信息化建设，包括业务场景的线上计费结算、线上化传账及业财数据校验、财务系统优化升级等；\n3.业财流程优化：定期参与合作商/业务部门调研，针对核心痛点问题推进财务运营流程优化，发现并解决各类财务问题，提高财务结果的效率和准确性；\n4.其他：与财务其他团队积极协调，完成其他指定任务。\n\n岗位基本要求\n1.本科及其以上学历，会计、经济、管理类等相关专业，5年及以上财会相关工作经验，有结核算相关经验以及财务系统对接经验；\n2.具备较强的业务理解力，沟通能力、协调能力，能和业务线对接，具备优秀的逻辑思维和分析能力；\n3.工作认真细心、责任心强、具有良好的团队协作精神和服务意识；\n4.能够以英文作为日常工作沟通语言；\n5.能够适应业务需求进行海外出差。\n\n具备以下条件优先\n有资产会计工作经验者优先\n\n岗位亮点\n见证境外业务发展壮大，深度参与业务日常运营，全面提升财务专业能力。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4616303738","sourceKey":"meituan_social","company":"美团","title":"北京中心仓运营支持","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4616303738&jobShareType=1","duty":"1.结算与费用管理：依据合同约定计费标准，独立核算应付费用，识别并标记异常差异项，在业财系统中准确创建结算申请单并完成审批跟进，主动发现、分析结算差异原因，推动多方协调核实与解决。 \n\n2. 物流成本分析与数据支持：定期整理汇总结算相关数据，制作物流成本分析报表，识别成本异常和优化空间，为成本控制及精细化运营提供数据支撑。 \n\n3. 闪购商家入驻与规则管理：负责闪购商家入驻规则的迭代优化，协同合规、GA等业务方及时更新审核规则，完成内外部政策透传与规则落地。 \n\n4. 中心仓运营支持：负责输出中心仓日报，支持仓配经理精细化运营；管理差异专员的认责和举证效率，驱动履约体验提升；定期收集门店和采销的投诉与反馈，协助优化流程、提升全链路体验；负责大区内相关岗位的绩效得分核算。\n\n 5. 仓内行政与后勤管理：负责中心仓物资设备验收、入账、盘点、报损及水电办公成本控制结算；负责人员排班休假管理、5S管理，以及外部联络接待（物业、回收商、设备维保、消防等）。","requirements":"1.大学专科以上学历，财务、物流或人力资源相关专业优先。\n2.具有至少3年以上财务、行政、人事管理经验。\n3.具备良好的团队管理能力和沟通能力，能有效协调团队工作。\n4.熟练操作办公软件，了解物流管理流程。\n5.具备较强的责任心和执行力，能够承受一定的工作压力。","description":"部门介绍\n美团闪购是美团旗下的即时零售平台，依托即时配送能力，连接本地零售供给，满足消费者30分钟万物到家的即时需求。美团闪购涵盖超市便利、食材、水果、鲜花绿植、休闲零食、酒水饮料、数码家电、美妆个护、母婴玩具、日用百货、服饰鞋帽、宠物等诸多品类，业务覆盖全国近3,000个县市区旗，每日百万级在岗骑手，以高效的配送、丰富的品类和广泛的覆盖，为美团数亿用户带来便捷的生活体验，积极助力实体零售线上化转型，提升本地商业活力。\n\n岗位职责\n1.结算与费用管理：依据合同约定计费标准，独立核算应付费用，识别并标记异常差异项，在业财系统中准确创建结算申请单并完成审批跟进，主动发现、分析结算差异原因，推动多方协调核实与解决。 \n\n2. 物流成本分析与数据支持：定期整理汇总结算相关数据，制作物流成本分析报表，识别成本异常和优化空间，为成本控制及精细化运营提供数据支撑。 \n\n3. 闪购商家入驻与规则管理：负责闪购商家入驻规则的迭代优化，协同合规、GA等业务方及时更新审核规则，完成内外部政策透传与规则落地。 \n\n4. 中心仓运营支持：负责输出中心仓日报，支持仓配经理精细化运营；管理差异专员的认责和举证效率，驱动履约体验提升；定期收集门店和采销的投诉与反馈，协助优化流程、提升全链路体验；负责大区内相关岗位的绩效得分核算。\n\n 5. 仓内行政与后勤管理：负责中心仓物资设备验收、入账、盘点、报损及水电办公成本控制结算；负责人员排班休假管理、5S管理，以及外部联络接待（物业、回收商、设备维保、消防等）。\n\n岗位基本要求\n1.大学专科以上学历，财务、物流或人力资源相关专业优先。\n2.具有至少3年以上财务、行政、人事管理经验。\n3.具备良好的团队管理能力和沟通能力，能有效协调团队工作。\n4.熟练操作办公软件，了解物流管理流程。\n5.具备较强的责任心和执行力，能够承受一定的工作压力。\n\n具备以下条件优先\n财务、零售电商物流经验优先。\n\n岗位亮点\n1. 加入高速发展的松鼠便利，参与区域核心仓储运营。  \n2. 扁平化管理，提供清晰的职业成长路径。  \n3. 团队氛围年轻活跃，注重员工能力提升。  \n4. 提供行业竞争力的薪资及绩效激励。  \n5. 弹性工作制，注重工作与生活平衡。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4590389280","sourceKey":"meituan_social","company":"美团","title":"歪马-闪购渠道运营","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4590389280&jobShareType=1","duty":"1、闪购渠道店铺运营：为歪马闪购门店（闪购渠道）的品类交易额负责：结合平台运营规则和商品特征，通过选品、定价、流量策略等，在效率和毛利约束下促进品类目标达成；识别平台品类增长机会和资源流向，沉淀商品分层及招商规则，提升交易规模、补贴效率，助力潜力新品爬坡。\n\n2、城市增长运营：歪马新开门店/新城爬坡，为门店及城市的订单量负责。通过优化已有爬坡工具效率、开发新的获客及订单爬坡手段，持续提升歪马新开门店/新开城市的爬坡速度和资源效率。\n\n3、促销节点的设计、组织与执行：承接平台及歪马品牌大促需求，完成歪马闪购渠道的大促方案设计、资源整合、策略落地、过程管理及复盘。\n\n4、理解和挖掘用户需求、增长机会：通过调研、跨团队交流等方式，深入业务场景；联动采销（商品）、商分、平台运营等团队挖掘增长机会。\n\n5、监测平台主要玩家的运营策略和发展趋势，及时调优运营策略。","requirements":"1、本科及以上学历，3年以上互联网用户运营or商家运营经验。\n\n2、对平台的流量分发、供给运营有深入理解，能解读规则、结合业务目标设计闪购渠道运营策略并落地。\n\n3、有促销与权益工具的精细化运营经验，数据驱动，能独立完成归因分析。\n\n4、有跨部门推进复杂项目的经验，具备一定谈判能力，能理解所在岗位与相关方的关系，撬动各方资源投入达成目标。\n\n5、结果导向，可以围绕目标拆解形成落地方案，能基于合理的分析方法对运营方案进行持续迭代并沉淀方法。","description":"部门介绍\n美团闪购是美团旗下的即时零售平台，依托即时配送能力，连接本地零售供给，满足消费者30分钟万物到家的即时需求。美团闪购涵盖超市便利、食材、水果、鲜花绿植、休闲零食、酒水饮料、数码家电、美妆个护、母婴玩具、日用百货、服饰鞋帽、宠物等诸多品类，业务覆盖全国近3,000个县市区旗，每日百万级在岗骑手，以高效的配送、丰富的品类和广泛的覆盖，为美团数亿用户带来便捷的生活体验，积极助力实体零售线上化转型，提升本地商业活力。\n\n岗位职责\n1、闪购渠道店铺运营：为歪马闪购门店（闪购渠道）的品类交易额负责：结合平台运营规则和商品特征，通过选品、定价、流量策略等，在效率和毛利约束下促进品类目标达成；识别平台品类增长机会和资源流向，沉淀商品分层及招商规则，提升交易规模、补贴效率，助力潜力新品爬坡。\n\n2、城市增长运营：歪马新开门店/新城爬坡，为门店及城市的订单量负责。通过优化已有爬坡工具效率、开发新的获客及订单爬坡手段，持续提升歪马新开门店/新开城市的爬坡速度和资源效率。\n\n3、促销节点的设计、组织与执行：承接平台及歪马品牌大促需求，完成歪马闪购渠道的大促方案设计、资源整合、策略落地、过程管理及复盘。\n\n4、理解和挖掘用户需求、增长机会：通过调研、跨团队交流等方式，深入业务场景；联动采销（商品）、商分、平台运营等团队挖掘增长机会。\n\n5、监测平台主要玩家的运营策略和发展趋势，及时调优运营策略。\n\n岗位基本要求\n1、本科及以上学历，3年以上互联网用户运营or商家运营经验。\n\n2、对平台的流量分发、供给运营有深入理解，能解读规则、结合业务目标设计闪购渠道运营策略并落地。\n\n3、有促销与权益工具的精细化运营经验，数据驱动，能独立完成归因分析。\n\n4、有跨部门推进复杂项目的经验，具备一定谈判能力，能理解所在岗位与相关方的关系，撬动各方资源投入达成目标。\n\n5、结果导向，可以围绕目标拆解形成落地方案，能基于合理的分析方法对运营方案进行持续迭代并沉淀方法。\n\n具备以下条件优先\n有AI深度使用、工具化经验者优先；对酒类行业与酒类用户感兴趣者优先；有自营/LBS业务经验的优先。\n\n岗位亮点\n1、参与核心业务从10-100的发展过程，深入自营零售业务经营，与多个部门及角色密切合作，说不定你后续也知道怎么开店；\n\n2、团队氛围开放，鼓励交流和分享，信息开放透明","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3536633526","sourceKey":"meituan_social","company":"美团","title":"充电宝大客户销售——商场方向","city":"广州市/深圳市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3536633526&jobShareType=1","duty":"1.负责推进重要城市头部商业项目与美团充电宝的合作，包括客户触达、提案制定、数据测算、合同签约、项目运维等；\n2.负责KA项目运营，定期输出项目经营数据分析，了解商业项目在充电宝板块的业务需求；\n3.负责公司内部跨部门协同沟通，协同销运、直营、产品、硬件等部门，为品牌方提供整体全案解决方案；\n4.保持良好的客户关系，做好KA客户管理和维护工作。","requirements":"1.本科及以上学历优先，三年及以上的销售经验，有KA销售经验者；\n2.较强的学习能力和适应能力，适应互联网行业的快速发展节奏，具备出色完成任务的能力；\n3.具备较强的公关能力及逻辑思维能力，思维敏捷，能够准确把握产品优势和客户心理，高效整合内外部资源促成商务合作；\n4.热爱销售，善于挑战，积极乐观，有强烈的成功欲望和企图心。","description":"部门介绍\n美团充电宝是服务零售中的共享租赁业务，承接美团使命，致力让大家充电更简单。美团充电宝业务以应急充电功能为服务核心，覆盖吃喝玩乐生活全场景。目前，已在全国超过2000多个城市的餐饮、娱乐、机场、地铁、火车站、医院、学校、景区等公共区域及场所提供充电服务，铺设机柜超过百万，有KA、直营、渠道合作商多种业务模式，随时随地保障和满足消费者的充电需求。我们的业务资产数量多、场景多元化，追求精益管理。我们的团队大咖云集，崇尚自主驱动，求真务实。我们正处在快速发展期，规模持续增长，目标是市场规模和利润水平双第一。我们的管理者关注团队每个成员的成长，为每个人提供适合自身发展的机会。广阔天地、大有作为，美团充电宝期待你的加入！\n\n岗位职责\n1.负责推进重要城市头部商业项目与美团充电宝的合作，包括客户触达、提案制定、数据测算、合同签约、项目运维等；\n2.负责KA项目运营，定期输出项目经营数据分析，了解商业项目在充电宝板块的业务需求；\n3.负责公司内部跨部门协同沟通，协同销运、直营、产品、硬件等部门，为品牌方提供整体全案解决方案；\n4.保持良好的客户关系，做好KA客户管理和维护工作。\n\n岗位基本要求\n1.本科及以上学历优先，三年及以上的销售经验，有KA销售经验者；\n2.较强的学习能力和适应能力，适应互联网行业的快速发展节奏，具备出色完成任务的能力；\n3.具备较强的公关能力及逻辑思维能力，思维敏捷，能够准确把握产品优势和客户心理，高效整合内外部资源促成商务合作；\n4.热爱销售，善于挑战，积极乐观，有强烈的成功欲望和企图心。\n\n具备以下条件优先\n1.对商业场景有一定认知度，有商业项目资源；\n2.有大客户成功经验，有良好销售业绩。\n\n岗位亮点\n1.大而稳定的平台发展，业务发展前景广阔；\n2.健全的培养体系，晋升通道完善；\n3.团队专业性强，产品竞争力强。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3992862389","sourceKey":"meituan_social","company":"美团","title":"美团骑行-政企大客户专家（浙江）","city":"杭州市/温州市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3992862389&jobShareType=1","duty":"1.做好战略发展规划，为出行业务在当地建立良好政商、行业环境；\n2.与行业主管部门建立良好的沟通、合作关系，深入理解当地政府等相关领域的政策法规，制定公司在当地政府关系工作的策略和计划，并操作执行；\n3.做好骑行业务的拓展，并为提升业务占比争取较好的发展环境；\n4.掌握出行领域行业信息、企业动态，推动与本地政企合作；\n5.响应出行业务在本地对主管部门的具体诉求，做好业务保障工作。","requirements":"1.本科及以上学历，5-10年以上工作经验；\n2.善于沟通和协调，有较强的项目管理能力、解决方案汇报能力和文字写作能力； \n3.熟悉政府部门体系组织架构和主要工作流程，了解政府管理方式方法，治理诉求；\n4.具有良好的团队合作精神和敬业精神，能适应出差；","description":"部门介绍\n美团骑行事业部在全国各个城市开展美团单车、电单车业务，提供绿色、便捷的共享出行服务，是美团出行板块重要的组成部分。我们力求为城市可持续发展提供低碳智能的解决方案，通过技术创新和硬件升级，不断优化全流程骑行体验，为低碳出行提供更好的服务。其中，美团单车旨在为城市居民提供通勤接驳服务，满足用户短途接驳出行需求；美团电单车则满足用户中短途多场景低碳出行需求。\n我们有开放的工作氛围，也有充满韧劲和创造力，心系低碳出行的伙伴。加入我们，一起为用户创造更好的出行体验。\n\n岗位职责\n1.做好战略发展规划，为出行业务在当地建立良好政商、行业环境；\n2.与行业主管部门建立良好的沟通、合作关系，深入理解当地政府等相关领域的政策法规，制定公司在当地政府关系工作的策略和计划，并操作执行；\n3.做好骑行业务的拓展，并为提升业务占比争取较好的发展环境；\n4.掌握出行领域行业信息、企业动态，推动与本地政企合作；\n5.响应出行业务在本地对主管部门的具体诉求，做好业务保障工作。\n\n岗位基本要求\n1.本科及以上学历，5-10年以上工作经验；\n2.善于沟通和协调，有较强的项目管理能力、解决方案汇报能力和文字写作能力； \n3.熟悉政府部门体系组织架构和主要工作流程，了解政府管理方式方法，治理诉求；\n4.具有良好的团队合作精神和敬业精神，能适应出差；\n\n具备以下条件优先\n熟悉交通出行、城市管理工作，长期在政府、信息化等领域工作者优先。\n\n岗位亮点\n发展空间巨大、上升空间大，团队小伙伴领导nice","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4263331409","sourceKey":"meituan_social","company":"美团","title":"无人车业务部-技术运营QA资深专家","city":"北京市/深圳市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4263331409&jobShareType=1","duty":"1）负责自动驾驶算法测试体系化建设，建设测试流程和测试手段；\n2）负责测试策略制定，能够分层做好问题拦截，保障交付质量；\n3）负责问题优先级和影响的判断，负责业务运营线上问题、跟进以及验证问题解决；\n4）协助整理行业对标工具/方法的基础调研，提出建设性的建议。","requirements":"1）计算机/统计学/大数据等相关专业； \n2）具备良好团队管理能力与经验；\n3）完整承接项目需求，具备较强的问题解决与推进能力；\n4）良好的学习能力、出色的沟通能力与团队协作意识。","description":"部门介绍\n无人车业务部成立于2016年，旨在用无人驾驶技术提升物流配送的效率和体验。美团无人车以自研L4级自动驾驶软硬件技术为核心，与美团即时零售业务结合，形成满足公开道路、社区、工业园区等室外全场景下的无人配送整体解决方案。自2020年起，无人车已在北京、深圳等多地进入常态化试运营阶段，在城市复杂场景下提供针对餐饮外卖、生鲜食杂等货物的即时配送服务。2025年，美团无人车又踏上了同城货运的新探索，并在2026年持续扩大运营范围和车队数量，为更多城市带来智能配送服务。\n欢迎加入美团无人车团队，与我们一起用科技推动即时零售再升级！\n\n岗位职责\n1）负责自动驾驶算法测试体系化建设，建设测试流程和测试手段；\n2）负责测试策略制定，能够分层做好问题拦截，保障交付质量；\n3）负责问题优先级和影响的判断，负责业务运营线上问题、跟进以及验证问题解决；\n4）协助整理行业对标工具/方法的基础调研，提出建设性的建议。\n\n岗位基本要求\n1）计算机/统计学/大数据等相关专业； \n2）具备良好团队管理能力与经验；\n3）完整承接项目需求，具备较强的问题解决与推进能力；\n4）良好的学习能力、出色的沟通能力与团队协作意识。\n\n具备以下条件优先\n1）参与过复杂项目的建设过程，涉及多种不同职能团队\n2）对算法/模型有一定了解，熟练使用Python、SQL\n3）参与过人工智能相关领域、如自动驾驶、视觉、语音、大模型等类似业务\n\n岗位亮点\n自动驾驶+AI最前沿科技的探索，深入参与科技硬件对生活服务的改变，建设比见证更值得期待。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4611451940","sourceKey":"meituan_social","company":"美团","title":"Engineering Manager-Kuwait&Qatar","city":"多哈/科威特城","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4611451940&jobShareType=1","duty":"1. Project Management: Overseeing store construction projects, managing project cost budgets and ensuring cost targets are met; developing project schedules, employing project management tools for real-time progress monitoring, and promptly resolving delays;\n2. Quality Management: Establishing quality control systems, supervising construction quality to ensure compliance with design standards, exercising comprehensive oversight over project progress, quality, cost and safety, and conducting guidance, supervision and assessment;\n3. Supplier Management: Oversee supplier operations including vetting new suppliers, organising routine training, conducting periodic assessments, and removing non-compliant suppliers.\n4. Construction Process Management: Convene multi-party reviews involving design, construction, and suppliers; lead acceptance and documentation of critical materials and works; monitor main contractors and subcontractors' performance in real time, promptly rectifying issues; swiftly identify construction problems and propose corrective measures to ensure project stability.\n5. Compliance Management: Lead construction and fire safety approval processes, securing essential permits including commencement authorisations;\n6. Settlement Management: Rigorous review of as-built drawings and settlement documentation; drive audit settlement procedures, monitor critical process milestones, and facilitate closed-loop settlement completion.","requirements":"1、 本科及以上学历，有对应前置仓工作经验者优先；\n2、5 年以上连锁商超或餐饮工程管理实践经验，熟悉商超、餐饮工程各类标准、规范、技术方案及常用设备。\n3、精通工程管理、招投标、成本管控流程，精准掌控工程质量要求，具备监督评估能力。\n4、拥有施工报建、消防报审全流程实操技能。\n5、具备良好的团队协作、组织协调与跨部门沟通能力。","description":"部门介绍\n美团的使命是“帮大家吃得更好，生活更好”，公司聚焦“零售 + 科技”战略，和广大商户与各类合作伙伴一起，努力为消费者提供品质生活，推动商品零售和服务零售在需求侧和供给侧的数字化转型。\n2018年9月20日，美团正式在港交所挂牌上市。美团将始终坚持以客户为中心，不断加大在科技研发方面的投入，更好承担社会责任，更多创造社会价值，与广大合作伙伴一起发展共赢。\n\n岗位职责\n1. Project Management: Overseeing store construction projects, managing project cost budgets and ensuring cost targets are met; developing project schedules, employing project management tools for real-time progress monitoring, and promptly resolving delays;\n2. Quality Management: Establishing quality control systems, supervising construction quality to ensure compliance with design standards, exercising comprehensive oversight over project progress, quality, cost and safety, and conducting guidance, supervision and assessment;\n3. Supplier Management: Oversee supplier operations including vetting new suppliers, organising routine training, conducting periodic assessments, and removing non-compliant suppliers.\n4. Construction Process Management: Convene multi-party reviews involving design, construction, and suppliers; lead acceptance and documentation of critical materials and works; monitor main contractors and subcontractors' performance in real time, promptly rectifying issues; swiftly identify construction problems and propose corrective measures to ensure project stability.\n5. Compliance Management: Lead construction and fire safety approval processes, securing essential permits including commencement authorisations;\n6. Settlement Management: Rigorous review of as-built drawings and settlement documentation; drive audit settlement procedures, monitor critical process milestones, and facilitate closed-loop settlement completion.\n\n岗位基本要求\n1、 本科及以上学历，有对应前置仓工作经验者优先；\n2、5 年以上连锁商超或餐饮工程管理实践经验，熟悉商超、餐饮工程各类标准、规范、技术方案及常用设备。\n3、精通工程管理、招投标、成本管控流程，精准掌控工程质量要求，具备监督评估能力。\n4、拥有施工报建、消防报审全流程实操技能。\n5、具备良好的团队协作、组织协调与跨部门沟通能力。\n\n岗位亮点\n创新型项目，成长空间广阔能够和做事、目标感、使命感强的优秀团队合作，一起拿结果","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3370225621","sourceKey":"meituan_social","company":"美团","title":"履约-众包站长","city":"上海市/杭州市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3370225621&jobShareType=1","duty":"1.对负责区域制定配送体验优化方案并有效地执行方案，同时对执行结果进行有效复盘；​2.重点围绕骑手的招聘，培训，提效，留存，淘汰等环节开展工作，保证负责区域的运力活力以及提升履约服务质量，提升用户体验；​3.处理由履约原因产生的相关商户问题，以及能够良好地协同其他部门进行问题解决；​4.对负责的骑手运营项目，能够做出短、中、长期的规划，制定高效的运营方案并达成业务结果。","requirements":"1.本科及以上学历，有物流、互联网、O2O等相关行业或运营经验者优先；​2.熟练运用互联网常见分析工具，掌握物流数据分析方法论；​3.业务灵敏度强，能从数据运营中发现问题，并提出解决路径；​4.有较强的自驱与学习能力，有长远职业发展的规划。","description":"部门介绍\n美团配送是以科技为内核的即时物流品牌，利用高效、稳定、广阔的配送网络和前沿科技能力为各行业客户提供涵盖商流物流一体化、流量赋能、行业定制化即时配送、末端配送、前置仓等服务在内的全方位同城物流综合解决方案。\n作为科技创新和智慧物流的实践者，美团配送在人工智能（AI）、5G应用、物联网（IoT）、云计算等多维度不断探索科创蓝海，让同城物流进入数智化时代。美团配送在IoT智能设备、外卖柜、换电网络、无人配送体系等硬件设施与服务上不断推陈出新，持续优化骑手、消费者、商家体验；自研同城物流系统，通过智能分析为用户提供更便捷的生活方式，为商家提供更高效的履约服务。\n加入我们，一起把世界送到消费者手中！\n\n岗位职责\n1.对负责区域制定配送体验优化方案并有效地执行方案，同时对执行结果进行有效复盘；​2.重点围绕骑手的招聘，培训，提效，留存，淘汰等环节开展工作，保证负责区域的运力活力以及提升履约服务质量，提升用户体验；​3.处理由履约原因产生的相关商户问题，以及能够良好地协同其他部门进行问题解决；​4.对负责的骑手运营项目，能够做出短、中、长期的规划，制定高效的运营方案并达成业务结果。\n\n岗位基本要求\n1.本科及以上学历，有物流、互联网、O2O等相关行业或运营经验者优先；​2.熟练运用互联网常见分析工具，掌握物流数据分析方法论；​3.业务灵敏度强，能从数据运营中发现问题，并提出解决路径；​4.有较强的自驱与学习能力，有长远职业发展的规划。\n\n具备以下条件优先\n1.具有2年及以上物流运营经验者优先；​2.具有运营项目管理经验者优先；​3.对物流行业有强烈兴趣，有韧性有规划\n\n岗位亮点\n1.能够参与并推动履约运营体系完善与搭建；​2.可参与到跨部门重点项目协调推进；​3.可与优秀物流运营者共同成长。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4416958745","sourceKey":"meituan_social","company":"美团","title":"美团无人车-渠道政策专家","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4416958745&jobShareType=1","duty":"1. 合作商全生命周期管理：主导无人车合作商的引入评估、日常运营与退出机制设计，构建覆盖全生命周期的管理策略体系，保障业务生态质量稳定可持续、风险可控。\n2. 风险运营体系建设 ：建立合作商风险识别标准、预警规则与处置流程，打造高效可扩展的风险运营机制；对一线团队开展风控赋能，持续优化评估与闭环管理。\n3. 管理工具产品化与自动化： 协同产品与数据团队，推动合作商管理策略的产品化、线上化落地，提升运营效率，降低人工依赖。探索AI工具在产品系统中的融合应用。\n4. 跨部门协作与策略落地： 协同商分、产品、研发等团队整合资源，推动运营策略高效落地；协调内外部资源解决合作商问题，达成业务目标。\n5. 市场与行业洞察： 持续跟踪行业动态与策略，结合市场洞察与业务现状识别增长机会，为业务决策提供支撑。","requirements":"基本条件 本科及以上学历，财务、统计、信息技术、经营管理等相关专业优先；3～5 年渠道/合作商运营或策略运营相关经验。\n\n1.具备渠道管理或互联网策略运营/合作商管理经验，有大型项目主导经验者优先；\n2.逻辑思维与策略拆解能力强，能独立完成从问题定义到方案落地的全链路推进；\n3.数据分析能力扎实，善于从数据中发现问题并提出可落地的改进建议；\n4.跨团队协作与沟通表达能力出色，能高效整合内外部资源推动目标达成；\n5.了解AI基础知识，有使用AI工具提效个人或团队工作的经验和想法。","description":"部门介绍\n无人车业务部成立于2016年，旨在用无人驾驶技术提升物流配送的效率和体验。美团无人车以自研L4级自动驾驶软硬件技术为核心，与美团即时零售业务结合，形成满足公开道路、社区、工业园区等室外全场景下的无人配送整体解决方案。自2020年起，无人车已在北京、深圳等多地进入常态化试运营阶段，在城市复杂场景下提供针对餐饮外卖、生鲜食杂等货物的即时配送服务。2025年，美团无人车又踏上了同城货运的新探索，并在2026年持续扩大运营范围和车队数量，为更多城市带来智能配送服务。\n欢迎加入美团无人车团队，与我们一起用科技推动即时零售再升级！\n\n岗位职责\n1. 合作商全生命周期管理：主导无人车合作商的引入评估、日常运营与退出机制设计，构建覆盖全生命周期的管理策略体系，保障业务生态质量稳定可持续、风险可控。\n2. 风险运营体系建设 ：建立合作商风险识别标准、预警规则与处置流程，打造高效可扩展的风险运营机制；对一线团队开展风控赋能，持续优化评估与闭环管理。\n3. 管理工具产品化与自动化： 协同产品与数据团队，推动合作商管理策略的产品化、线上化落地，提升运营效率，降低人工依赖。探索AI工具在产品系统中的融合应用。\n4. 跨部门协作与策略落地： 协同商分、产品、研发等团队整合资源，推动运营策略高效落地；协调内外部资源解决合作商问题，达成业务目标。\n5. 市场与行业洞察： 持续跟踪行业动态与策略，结合市场洞察与业务现状识别增长机会，为业务决策提供支撑。\n\n岗位基本要求\n基本条件 本科及以上学历，财务、统计、信息技术、经营管理等相关专业优先；3～5 年渠道/合作商运营或策略运营相关经验。\n\n1.具备渠道管理或互联网策略运营/合作商管理经验，有大型项目主导经验者优先；\n2.逻辑思维与策略拆解能力强，能独立完成从问题定义到方案落地的全链路推进；\n3.数据分析能力扎实，善于从数据中发现问题并提出可落地的改进建议；\n4.跨团队协作与沟通表达能力出色，能高效整合内外部资源推动目标达成；\n5.了解AI基础知识，有使用AI工具提效个人或团队工作的经验和想法。\n\n具备以下条件优先\n1.熟悉无人车、电单车、物流等平台型渠道管理模式，了解合作商体系、分润与绩效规则；\n2.有管理工具产品化/线上化推进经验；\n3.具备数据与 AI 工具应用能力，能识别合作商异常模式并驱动策略优化；\n\n岗位亮点\n业务快速扩展期，跟随业务见证操盘工作的孵化和壮大；\n\n平台影响大，未来覆盖全国城市，操盘工作直接影响数量众多合作商的行为模式；\n\n体系建设空间充分：渠道商体系仍处于快速建设阶段，有大量机会主导从零设计标准体系；\n\nAI-Native 工作氛围：美团 AI at Work 全面推进，CatPaw AI编程助手、NoCode零代码平台已渗透日常工作，支持你快速构建各类工具。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4631895397","sourceKey":"meituan_social","company":"美团","title":"美团拼好饭-区域品牌采购经理","city":"北京市/济南市/沈阳市/青岛市/石家庄市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4631895397&jobShareType=1","duty":"1.基于目标清单，完成连锁品牌的招商引入与合作签约，主动建联品牌方KP、传递合作价值、达成入驻合作，建立并维护品牌方高层（供应链/外卖负责人）的长期合作关系；\n2.推动品牌方完成拼好饭模式的经营落地，识别经营中的核心问题，解决品牌方经营中的核心卡点，持续提升商品的市场表现和用户满意度；\n3.主动联动内部团队，推动品牌方商品策略在区域的落地执行，参与品牌方经营数据的复盘，协同多方团队优化商品成本和经营效率。","requirements":"1.具备连锁品牌招商拓展或餐饮行业商务谈判经验，能独立对接品牌方决策层；\n2.具备一定的数据分析能力和项目管理能力，能够通过数据分析诊断经营问题，协调资源推动问题的改善与解决，将单点优化沉淀为可复用的组织能力；\n3.对餐饮行业或本地生活业务有基本理解，了解品牌方经营的核心需求；\n4.诚信正直，自我驱动力强，愿意接受挑战，对工作结果交付具有责任心；\n5.具备AI学习意愿，能主动探索AI在工作场景中的应用。","description":"部门介绍\n美团外卖秉承“帮大家吃得更好，生活更好”的使命，始终聚焦于消费者用餐需求。我们通过科技连接消费者和商家，依托庞大的骑手团队，以“线上+线下”的业务模式，为消费者提供品质化、精细化、多样化的餐饮外卖服务。\n外卖事业部是为用户与商家提供全链路交易服务的业务组织，围绕餐饮外卖搭建了包含外卖业务与创新孵化业务在内的多个部门。\n我们的目标是帮助商家开源增收、提高经营效率，促进餐饮行业数字化，以及为更多用户提供更便捷更有品质的外卖服务。加入我们，一起为上亿用户提供更好的用餐体验，帮助大家吃得更好，生活更好！\n\n岗位职责\n1.基于目标清单，完成连锁品牌的招商引入与合作签约，主动建联品牌方KP、传递合作价值、达成入驻合作，建立并维护品牌方高层（供应链/外卖负责人）的长期合作关系；\n2.推动品牌方完成拼好饭模式的经营落地，识别经营中的核心问题，解决品牌方经营中的核心卡点，持续提升商品的市场表现和用户满意度；\n3.主动联动内部团队，推动品牌方商品策略在区域的落地执行，参与品牌方经营数据的复盘，协同多方团队优化商品成本和经营效率。\n\n岗位基本要求\n1.具备连锁品牌招商拓展或餐饮行业商务谈判经验，能独立对接品牌方决策层；\n2.具备一定的数据分析能力和项目管理能力，能够通过数据分析诊断经营问题，协调资源推动问题的改善与解决，将单点优化沉淀为可复用的组织能力；\n3.对餐饮行业或本地生活业务有基本理解，了解品牌方经营的核心需求；\n4.诚信正直，自我驱动力强，愿意接受挑战，对工作结果交付具有责任心；\n5.具备AI学习意愿，能主动探索AI在工作场景中的应用。\n\n岗位亮点\n1.深度参与品牌方经营，从采购到运营全链路操盘；\n2.配备前沿AI工具与资源，在AI时代持续提升竞争力、加速职业成长。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4631856974","sourceKey":"meituan_social","company":"美团","title":"美团拼好饭-区域品牌采购经理","city":"北京市/沈阳市/天津市/济南市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4631856974&jobShareType=1","duty":"1.基于目标清单，完成连锁品牌的招商引入与合作签约，主动建联品牌方KP、传递合作价值、达成入驻合作，建立并维护品牌方高层（供应链/外卖负责人）的长期合作关系；\n2.推动品牌方完成拼好饭模式的经营落地，识别经营中的核心问题，解决品牌方经营中的核心卡点，持续提升商品的市场表现和用户满意度；\n3.主动联动内部团队，推动品牌方商品策略在区域的落地执行，参与品牌方经营数据的复盘，协同多方团队优化商品成本和经营效率。","requirements":"1.具备连锁品牌招商拓展或餐饮行业商务谈判经验，能独立对接品牌方决策层；\n2.具备一定的数据分析能力和项目管理能力，能够通过数据分析诊断经营问题，协调资源推动问题的改善与解决，将单点优化沉淀为可复用的组织能力；\n3.对餐饮行业或本地生活业务有基本理解，了解品牌方经营的核心需求；\n4.诚信正直，自我驱动力强，愿意接受挑战，对工作结果交付具有责任心；\n5.具备AI学习意愿，能主动探索AI在工作场景中的应用。","description":"部门介绍\n美团外卖秉承“帮大家吃得更好，生活更好”的使命，始终聚焦于消费者用餐需求。我们通过科技连接消费者和商家，依托庞大的骑手团队，以“线上+线下”的业务模式，为消费者提供品质化、精细化、多样化的餐饮外卖服务。\n外卖事业部是为用户与商家提供全链路交易服务的业务组织，围绕餐饮外卖搭建了包含外卖业务与创新孵化业务在内的多个部门。\n我们的目标是帮助商家开源增收、提高经营效率，促进餐饮行业数字化，以及为更多用户提供更便捷更有品质的外卖服务。加入我们，一起为上亿用户提供更好的用餐体验，帮助大家吃得更好，生活更好！\n\n岗位职责\n1.基于目标清单，完成连锁品牌的招商引入与合作签约，主动建联品牌方KP、传递合作价值、达成入驻合作，建立并维护品牌方高层（供应链/外卖负责人）的长期合作关系；\n2.推动品牌方完成拼好饭模式的经营落地，识别经营中的核心问题，解决品牌方经营中的核心卡点，持续提升商品的市场表现和用户满意度；\n3.主动联动内部团队，推动品牌方商品策略在区域的落地执行，参与品牌方经营数据的复盘，协同多方团队优化商品成本和经营效率。\n\n岗位基本要求\n1.具备连锁品牌招商拓展或餐饮行业商务谈判经验，能独立对接品牌方决策层；\n2.具备一定的数据分析能力和项目管理能力，能够通过数据分析诊断经营问题，协调资源推动问题的改善与解决，将单点优化沉淀为可复用的组织能力；\n3.对餐饮行业或本地生活业务有基本理解，了解品牌方经营的核心需求；\n4.诚信正直，自我驱动力强，愿意接受挑战，对工作结果交付具有责任心；\n5.具备AI学习意愿，能主动探索AI在工作场景中的应用。\n\n岗位亮点\n1.深度参与品牌方经营，从采购到运营全链路操盘；\n2.配备前沿AI工具与资源，在AI时代持续提升竞争力、加速职业成长。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4614804595","sourceKey":"meituan_social","company":"美团","title":"美团拼好饭-区域品牌采购专员","city":"上海市/杭州市/南京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4614804595&jobShareType=1","duty":"职级：L5、L6\n基于目标清单，完成连锁品牌的招商引入与合作签约，主动建联品牌方KP、传递合作价值、达成入驻合作，建立并维护品牌方高层（供应链/外卖负责人）的长期合作关系；\n\n推动品牌方完成拼好饭模式的经营落地，识别经营中的核心问题，解决品牌方经营中的核心卡点，持续提升商品的市场表现和用户满意度；\n\n主动联动内部团队，推动品牌方商品策略在区域的落地执行，参与品牌方经营数据的复盘，协同多方团队优化商品成本和经营效率。","requirements":"具备连锁品牌招商拓展或餐饮行业商务谈判经验，能独立对接品牌方决策层；\n\n具备一定的数据分析能力和项目管理能力，能够通过数据分析诊断经营问题，协调资源推动问题的改善与解决，将单点优化沉淀为可复用的组织能力；\n\n对餐饮行业或本地生活业务有基本理解，了解品牌方经营的核心需求；\n\n诚信正直，自我驱动力强，愿意接受挑战，对工作结果交付具有责任心；\n\n具备AI学习意愿，能主动探索AI在工作场景中的应用。","description":"部门介绍\n美团外卖秉承“帮大家吃得更好，生活更好”的使命，始终聚焦于消费者用餐需求。我们通过科技连接消费者和商家，依托庞大的骑手团队，以“线上+线下”的业务模式，为消费者提供品质化、精细化、多样化的餐饮外卖服务。\n外卖事业部是为用户与商家提供全链路交易服务的业务组织，围绕餐饮外卖搭建了包含外卖业务与创新孵化业务在内的多个部门。\n我们的目标是帮助商家开源增收、提高经营效率，促进餐饮行业数字化，以及为更多用户提供更便捷更有品质的外卖服务。加入我们，一起为上亿用户提供更好的用餐体验，帮助大家吃得更好，生活更好！\n\n岗位职责\n职级：L5、L6\n基于目标清单，完成连锁品牌的招商引入与合作签约，主动建联品牌方KP、传递合作价值、达成入驻合作，建立并维护品牌方高层（供应链/外卖负责人）的长期合作关系；\n\n推动品牌方完成拼好饭模式的经营落地，识别经营中的核心问题，解决品牌方经营中的核心卡点，持续提升商品的市场表现和用户满意度；\n\n主动联动内部团队，推动品牌方商品策略在区域的落地执行，参与品牌方经营数据的复盘，协同多方团队优化商品成本和经营效率。\n\n岗位基本要求\n具备连锁品牌招商拓展或餐饮行业商务谈判经验，能独立对接品牌方决策层；\n\n具备一定的数据分析能力和项目管理能力，能够通过数据分析诊断经营问题，协调资源推动问题的改善与解决，将单点优化沉淀为可复用的组织能力；\n\n对餐饮行业或本地生活业务有基本理解，了解品牌方经营的核心需求；\n\n诚信正直，自我驱动力强，愿意接受挑战，对工作结果交付具有责任心；\n\n具备AI学习意愿，能主动探索AI在工作场景中的应用。\n\n岗位亮点\n深度参与品牌方经营，从采购到运营全链路操盘；\n\n配备前沿AI工具与资源，在AI时代持续提升竞争力、加速职业成长。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4597378838","sourceKey":"meituan_social","company":"美团","title":"美团拼好饭-区域品牌采购经理","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4597378838&jobShareType=1","duty":"基于连锁品牌目标清单开展招商谈判，清晰传达“平台商品+长期经营”的合作方案，调动品牌方兴趣，愿意就拼好饭的新模式达成长期的合作；\n\n根据商品运营需求，制定连锁品牌商品采购策略，搭建拼好饭连锁团队，负责与连锁品牌进行采购谈判，确保商品供应稳定、价格具备足够性价比；\n\n参与拼好饭定制品的开发及品质管控，通过供应链管理和生产流程优化，降低生产成本，持续优化定制商品的成本与效率，确保品牌方的履约质量；持续提升商品的市场表现和用户满意度；\n\n基于连锁品牌在新模式下的运营数据组织专项复盘，识别经营中的核心问题；针对诊断出的核心问题，制定并推动改善计划，确保问题得到有效解决，提升品牌方在拼好饭的经营能力；\n\n对内主动联动内部团队，确保定制品开发流程的顺畅和高效，协调资源解决流程中的瓶颈问题；对外与品牌方的供应链KP、外卖KP等进行有效沟通，维护好客情并建立长期的合作。","requirements":"具备优秀的招商谈判和商品采购能力，搭建连锁团队和品牌方进行洽谈，推动品牌方参与到平台和品牌的生态共建，跑通品牌方和拼好饭长期合作的新模式；\n\n熟悉连锁品牌供应链完整的链路流程，基于商品开发的流程，联动中台建立商品开发SOP，实现从需求洞察到量产开发的标准化工具化，持续优化定制商品的成本与效率，帮助连锁商家提升ROI；\n\n能够与相关部门建立高效协同联动，针对合作中的痛点设计多方联动协同机制，推动跨团队的分工协作顺畅，及时响应和对接品牌方的问题；\n\n具备一定的数据分析能力和项目管理能力，能够通过数据分析诊断经营问题（如周度复盘会/经营分析等），能够协调资源推动问题的改善与解决，将单点优化沉淀为可复用的组织能力；\n\n具备快速学习能力，能够快速掌握新的工具和方法，提升工作效率，适应快速变化的市场环境。","description":"部门介绍\n美团外卖秉承“帮大家吃得更好，生活更好”的使命，始终聚焦于消费者用餐需求。我们通过科技连接消费者和商家，依托庞大的骑手团队，以“线上+线下”的业务模式，为消费者提供品质化、精细化、多样化的餐饮外卖服务。\n外卖事业部是为用户与商家提供全链路交易服务的业务组织，围绕餐饮外卖搭建了包含外卖业务与创新孵化业务在内的多个部门。\n我们的目标是帮助商家开源增收、提高经营效率，促进餐饮行业数字化，以及为更多用户提供更便捷更有品质的外卖服务。加入我们，一起为上亿用户提供更好的用餐体验，帮助大家吃得更好，生活更好！\n\n岗位职责\n基于连锁品牌目标清单开展招商谈判，清晰传达“平台商品+长期经营”的合作方案，调动品牌方兴趣，愿意就拼好饭的新模式达成长期的合作；\n\n根据商品运营需求，制定连锁品牌商品采购策略，搭建拼好饭连锁团队，负责与连锁品牌进行采购谈判，确保商品供应稳定、价格具备足够性价比；\n\n参与拼好饭定制品的开发及品质管控，通过供应链管理和生产流程优化，降低生产成本，持续优化定制商品的成本与效率，确保品牌方的履约质量；持续提升商品的市场表现和用户满意度；\n\n基于连锁品牌在新模式下的运营数据组织专项复盘，识别经营中的核心问题；针对诊断出的核心问题，制定并推动改善计划，确保问题得到有效解决，提升品牌方在拼好饭的经营能力；\n\n对内主动联动内部团队，确保定制品开发流程的顺畅和高效，协调资源解决流程中的瓶颈问题；对外与品牌方的供应链KP、外卖KP等进行有效沟通，维护好客情并建立长期的合作。\n\n岗位基本要求\n具备优秀的招商谈判和商品采购能力，搭建连锁团队和品牌方进行洽谈，推动品牌方参与到平台和品牌的生态共建，跑通品牌方和拼好饭长期合作的新模式；\n\n熟悉连锁品牌供应链完整的链路流程，基于商品开发的流程，联动中台建立商品开发SOP，实现从需求洞察到量产开发的标准化工具化，持续优化定制商品的成本与效率，帮助连锁商家提升ROI；\n\n能够与相关部门建立高效协同联动，针对合作中的痛点设计多方联动协同机制，推动跨团队的分工协作顺畅，及时响应和对接品牌方的问题；\n\n具备一定的数据分析能力和项目管理能力，能够通过数据分析诊断经营问题（如周度复盘会/经营分析等），能够协调资源推动问题的改善与解决，将单点优化沉淀为可复用的组织能力；\n\n具备快速学习能力，能够快速掌握新的工具和方法，提升工作效率，适应快速变化的市场环境。\n\n具备以下条件优先\n1、具备餐饮连锁品牌/管理经验的人优先。\n2、具备餐饮供应链经验的人优先。\n3、具备零售/商品思维的人优先。\n\n岗位亮点\n主导连锁品牌与拼好饭的生态共建\n\n供应链精益化运营与规模化商品落地","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4614434011","sourceKey":"meituan_social","company":"美团","title":"美团拼好饭-区域品牌采购经理","city":"郑州市/武汉市/长沙市/合肥市/厦门市/福州市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4614434011&jobShareType=1","duty":"将总部策略转化为区域可执行的落地方案，根据市场反馈动态调整，对区域连锁品牌拓展及经营目标的达成负责；\n\n主导关键品牌/关键项目的突破，必要时亲自下场操盘，从实践中提炼可复用的方法论，向更大范围输出经验；\n\n搭建团队能力培养体系，提升团队整体的作战能力；搭建团队内部的信息共享和协作机制，推动跨部门协同效率提升；","requirements":"具备连锁品牌拓展或商品采购的管理经验，有从0到1搭建团队或开拓市场的经历；\n\n具备目标拆解、过程管理、跨部门协同能力，能通过数据追踪团队进展并及时干预；\n\n能够运用 AI工具提升产出效率与质量，主动探索AI在本岗位的应用；\n\n诚信正直，自我驱动力强，愿意接受挑战，对工作结果交付具有责任心。","description":"部门介绍\n美团外卖秉承“帮大家吃得更好，生活更好”的使命，始终聚焦于消费者用餐需求。我们通过科技连接消费者和商家，依托庞大的骑手团队，以“线上+线下”的业务模式，为消费者提供品质化、精细化、多样化的餐饮外卖服务。\n外卖事业部是为用户与商家提供全链路交易服务的业务组织，围绕餐饮外卖搭建了包含外卖业务与创新孵化业务在内的多个部门。\n我们的目标是帮助商家开源增收、提高经营效率，促进餐饮行业数字化，以及为更多用户提供更便捷更有品质的外卖服务。加入我们，一起为上亿用户提供更好的用餐体验，帮助大家吃得更好，生活更好！\n\n岗位职责\n将总部策略转化为区域可执行的落地方案，根据市场反馈动态调整，对区域连锁品牌拓展及经营目标的达成负责；\n\n主导关键品牌/关键项目的突破，必要时亲自下场操盘，从实践中提炼可复用的方法论，向更大范围输出经验；\n\n搭建团队能力培养体系，提升团队整体的作战能力；搭建团队内部的信息共享和协作机制，推动跨部门协同效率提升；\n\n岗位基本要求\n具备连锁品牌拓展或商品采购的管理经验，有从0到1搭建团队或开拓市场的经历；\n\n具备目标拆解、过程管理、跨部门协同能力，能通过数据追踪团队进展并及时干预；\n\n能够运用 AI工具提升产出效率与质量，主动探索AI在本岗位的应用；\n\n诚信正直，自我驱动力强，愿意接受挑战，对工作结果交付具有责任心。\n\n岗位亮点\n深度参与品牌方经营，从采购到运营全链路操盘；\n\n配备前沿AI工具与资源，在AI时代持续提升竞争力、加速职业成长。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4618290248","sourceKey":"meituan_social","company":"美团","title":"民宿B端商家AI产品经理","city":"上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4618290248&jobShareType=1","duty":"1. 深入业务，并对客户真实需求加以甄别和专业判断，输出高质量的产品方案，并交付业务结果\n2. 深入使用商家端产品的全流程，准确识别商家痛点，运用AI分析工具挖掘商家行为洞察\n3. 研究全球范围内行业头部玩家的商家端产品能力，为商家使用体验负责，并推动AI在商家端产品中的落地应用（如智能商品管理、AI经营助手等）\n4. 持续迭代CRM及销售作业系统产品能力，提升平台运营效率","requirements":"1. 本科及以上学历，3年以上互联网产品经验，有商家端或B端产品经验者优先\n2. 对商家需求理解准确，能转化为清晰的产品策略\n3. 具备用户产品和工具产品的设计能力，学习意愿强\n4. 有较好的产品审美，有AI工具实际使用经验（如使用AI进行需求分析、方案设计、市场研究等），能输出高质量的产品方案\n5. 具备定量分析能力，能设计A/B实验并解读实验结果与业务逻辑\n6. 责任心强，能在多线并行工作中保持条理，结果导向","description":"部门介绍\n美团酒店旅行业务涵盖酒店、民宿、机票、火车票、旅游度假、景点门票等各类住行游品类，通过与产业上下游的深度合作，为用户提供美好的旅游旅行体验。我们积极打造AI友好型组织，使用AI等新技术提升旅游服务的供需匹配效率，更好满足用户个性化、多样化的出游需求。我们持续深耕产业链，用数字化服务助力实体商家高质量经营，探索自有品牌等供给新模式，打造健康的商家生态，保障用户服务体验。为满足用户日益增长的跨境旅行需求，我们将聚焦亚太区域，打造高品质的住宿、交通、游玩等服务矩阵。\n这里有多元的业务布局、持续的成长空间，无论是向往的远方还是眼前的工作，一路都是风景相伴。加入我们，共同为用户创造旅游旅行中的高光时刻！\n\n岗位职责\n1. 深入业务，并对客户真实需求加以甄别和专业判断，输出高质量的产品方案，并交付业务结果\n2. 深入使用商家端产品的全流程，准确识别商家痛点，运用AI分析工具挖掘商家行为洞察\n3. 研究全球范围内行业头部玩家的商家端产品能力，为商家使用体验负责，并推动AI在商家端产品中的落地应用（如智能商品管理、AI经营助手等）\n4. 持续迭代CRM及销售作业系统产品能力，提升平台运营效率\n\n岗位基本要求\n1. 本科及以上学历，3年以上互联网产品经验，有商家端或B端产品经验者优先\n2. 对商家需求理解准确，能转化为清晰的产品策略\n3. 具备用户产品和工具产品的设计能力，学习意愿强\n4. 有较好的产品审美，有AI工具实际使用经验（如使用AI进行需求分析、方案设计、市场研究等），能输出高质量的产品方案\n5. 具备定量分析能力，能设计A/B实验并解读实验结果与业务逻辑\n6. 责任心强，能在多线并行工作中保持条理，结果导向\n\n具备以下条件优先\n- AI coding是加分项\n\n岗位亮点\n1. 业务处于高速发展期，个人成长与业务增长强绑定\n2. AI-Native工作氛围，团队积极推动AI在商家端产品中的深度应用\n3. 从0到1参与AI+商家服务的智能化建设，在商家赋能前沿领域积累先发经验\n4. 团队氛围求真务实，决策扁平高效","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4635492372","sourceKey":"meituan_social","company":"美团","title":"销售中台","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4635492372&jobShareType=1","duty":"1、搭建业务数据监控机制，在周期的各个阶段负责整体进度把控，对业务结果负责；\n2、用户增长运营：围绕流量获取及转化，综合利用触达工具、营销活动及补贴资源分配等，扩展流量获取入口，提升流量转化效率，提升城市流量水平；同时持续优化城市用户结构，设计用户运营关键策略，提升城市中高价值用户规模，促进城市规模稳定健康增长。\n3、城市专项运营：主导城市运营能力沉淀对应专项，设计并推进策略落地，联动产研部门，建设相关运营工具，提升运营效率；\n4、项目管理：基于业务目标，持续探索可落地的创新项目，并具备项目沉淀能力，对项目节奏有掌控力，监督和推动各业务方向达成\n5、探索AI技术在业务运营场景中的应用，善于利用智能化工具提升运营效率和决策质量","requirements":"1、本科及以上学历，有互联网行业、快消或咨询公司从业背景，在项目管理或策略运营领域有3年以上实践经验；\n2、有强力的自驱意识，目标感强，对销售运营行业感兴趣；\n3、有良好的数据敏感度，通过数据洞察问题和解决问题，发掘业务增量机会；\n4、出色的沟通能力和体系化思维，善于资源整合；\n5、精通办公软件，擅长sql、python等工具优先\n6、具备较强的跨部门协调与项目推进能力，能在复杂内部环境中推动事项落地\n7、有快消/食材/生鲜/餐饮B端渠道从业背景者优先\n8、熟练使用AI工具（如ChatGPT、文心一言等）进行数据分析和运营策略优化，具备利用AI提升工作效率的意识","description":"部门介绍\n快驴进货是美团旗下的餐饮供应链平台，帮助餐饮商户以更低成本、更高效率来获取安全可靠的食材供应，让餐饮采购更简单。快驴进货同步发展“自营+平台”的业务模式，在采购环节一方面向上游供应商直采大宗商品，另一方面引入各地批发商，助力平台伙伴共同发展；在销售环节既有自建团队进行市场、客户拓展，又帮助各地批发商拓展业务；同时自建仓储管理系统、配送网络与团队，为客户提供优质履约服务。\n截至2022年，快驴进货布局了全国41个城市，为百万家商户提供“全、省、稳、好”的餐饮供应链服务。我们拥有3000+品牌食材、超5万SKU商品、超28万商品资质，并提供源头严审核、食品安全严把关、24小时无忧售后的全面保障，实现手机下单、送货上门的高效采购模式，帮百万商家节省了采购时间与成本，助力平台伙伴共同发展，在万亿市场共享机遇。\n在这里，你将收获完善的员工发展机制及学习体系，与各界专家一起深度参与餐饮供应链业务的发展。欢迎优秀的你加入美团快驴进货，与我们一起成长，一起更好！\n\n岗位职责\n1、搭建业务数据监控机制，在周期的各个阶段负责整体进度把控，对业务结果负责；\n2、用户增长运营：围绕流量获取及转化，综合利用触达工具、营销活动及补贴资源分配等，扩展流量获取入口，提升流量转化效率，提升城市流量水平；同时持续优化城市用户结构，设计用户运营关键策略，提升城市中高价值用户规模，促进城市规模稳定健康增长。\n3、城市专项运营：主导城市运营能力沉淀对应专项，设计并推进策略落地，联动产研部门，建设相关运营工具，提升运营效率；\n4、项目管理：基于业务目标，持续探索可落地的创新项目，并具备项目沉淀能力，对项目节奏有掌控力，监督和推动各业务方向达成\n5、探索AI技术在业务运营场景中的应用，善于利用智能化工具提升运营效率和决策质量\n\n岗位基本要求\n1、本科及以上学历，有互联网行业、快消或咨询公司从业背景，在项目管理或策略运营领域有3年以上实践经验；\n2、有强力的自驱意识，目标感强，对销售运营行业感兴趣；\n3、有良好的数据敏感度，通过数据洞察问题和解决问题，发掘业务增量机会；\n4、出色的沟通能力和体系化思维，善于资源整合；\n5、精通办公软件，擅长sql、python等工具优先\n6、具备较强的跨部门协调与项目推进能力，能在复杂内部环境中推动事项落地\n7、有快消/食材/生鲜/餐饮B端渠道从业背景者优先\n8、熟练使用AI工具（如ChatGPT、文心一言等）进行数据分析和运营策略优化，具备利用AI提升工作效率的意识\n\n岗位亮点\n1、独立负责项目，从计划到执行，有利于全局观视角建立，以及个人体系化能力的沉淀\n2、部门开放性强，团队氛围好，鼓励尝试创新、个人成长空间大。\n3、深度拥抱AI+业务融合，团队积极探索AIGC在运营场景的落地应用，技术赋能业务创新","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4625646671","sourceKey":"meituan_social","company":"美团","title":"美团企业版线下营销组-华北线下营销经理","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4625646671&jobShareType=1","duty":"伙伴拓展与运营：立足华北区域，负责华北区域生态伙伴的建联、拓展与维护，围绕费控厂商、软件厂商、酒店平台、行业协会等合作伙伴，建立并深化合作关系，推动伙伴产出 KAMQL 线索。\n\n客户拓展：基于华北区域市场特点，配合伙伴开展客户拓展工作，通过联办活动、行业人脉会等形式触达目标客户，推动线索转化。\n\n活动策划与执行：独立策划并执行伙伴联办活动（行业沙龙、论坛、展会赞助等），包括主题策划、嘉宾邀约、客户邀约、现场执行、线索回收等全链路闭环。\n\n数据跟踪与复盘：跟踪每场活动的过程指标（邀约数、到场数、KAMQL 产出数、SA 占比等），定期复盘产出效果，输出优化建议。","requirements":"1.具备2年以上2B传统软件公司、SaaS、云市场或互联网生态市场/销售经验，有 to-B 行业（费控、差旅、企业服务等）背景优先。\n\n2. 具备较强的商务沟通与谈判能力，能够独立建联合作伙伴并推动合作落地。\n    \n3.具备活动策划与执行能力，有从 0 到 1 策划行业活动的经验；具备基本的数据分析能力，能够用数据驱动运营决策；具备较强的自驱力与 owner 意识。\n\n4.为人正直，有责任心，积极主动，能承担高强度的工作，具备较强的目标驱动力。","description":"部门介绍\n美团平台为用户的基础产品体验负责，还承担了美团的用户增长、市场和品牌营销以及多条业务线的产品设计职责，建立了融合文字、图片、视频和直播等不同形式的內容生态系统，同时整合地图服务部、客户服务和体验部、企业业务部、网约车业务部等部门，致力于用科技提升美团数亿消费者、近千万商家、骑手、司机和团长的服务体验。美团平台拥有高并发、多业务的复杂场景，为技术深度优化提供了最佳实践可能。这里有简单、讲逻辑、有爱的团队，更是一块理想的实战场地，舞台广阔，欢迎你来尽情施展。\n\n岗位职责\n伙伴拓展与运营：立足华北区域，负责华北区域生态伙伴的建联、拓展与维护，围绕费控厂商、软件厂商、酒店平台、行业协会等合作伙伴，建立并深化合作关系，推动伙伴产出 KAMQL 线索。\n\n客户拓展：基于华北区域市场特点，配合伙伴开展客户拓展工作，通过联办活动、行业人脉会等形式触达目标客户，推动线索转化。\n\n活动策划与执行：独立策划并执行伙伴联办活动（行业沙龙、论坛、展会赞助等），包括主题策划、嘉宾邀约、客户邀约、现场执行、线索回收等全链路闭环。\n\n数据跟踪与复盘：跟踪每场活动的过程指标（邀约数、到场数、KAMQL 产出数、SA 占比等），定期复盘产出效果，输出优化建议。\n\n岗位基本要求\n1.具备2年以上2B传统软件公司、SaaS、云市场或互联网生态市场/销售经验，有 to-B 行业（费控、差旅、企业服务等）背景优先。\n\n2. 具备较强的商务沟通与谈判能力，能够独立建联合作伙伴并推动合作落地。\n    \n3.具备活动策划与执行能力，有从 0 到 1 策划行业活动的经验；具备基本的数据分析能力，能够用数据驱动运营决策；具备较强的自驱力与 owner 意识。\n\n4.为人正直，有责任心，积极主动，能承担高强度的工作，具备较强的目标驱动力。\n\n具备以下条件优先\n有渠道运营/伙伴管理经验；\n有企业差旅、费控、TMC 等行业资源；\n有活动策划执行经验（展会、沙龙、论坛等）。\n\n岗位亮点\n立足美团企业版营销及增长组，能够系统完整的参与互联网2B业务流程及市场全貌，更能全面系统的提升业务逻辑和市场认知。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4507957769","sourceKey":"meituan_social","company":"美团","title":"机器人-用工管理/商管理","city":"深圳市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4507957769&jobShareType=1","duty":"1. 外包人员全生命周期管理：覆盖需求规划、供应商导入评估、人员入离职流程管理及绩效考核体系搭建，确保外包团队人力供给持续稳定；\n2. 供应商开发与商务管理：对接劳务/BPO供应商，主导综合评估（资质、服务能力、成本结构、合规性）、商务谈判与合同签署，建立供应商分级管理与动态评价机制；\n3. 外包用工管理体系建设：制定考勤、薪酬结算、安全培训、数据保密等标准化管理制度，推动用工全流程数字化与规范化；\n4. 人力成本管控与合规风险防控：通过数据分析识别外包人天单价、人效比等成本优化机会，把控劳务合规红线（劳务派遣比例、社保合规、数据安全协议等），防范用工法律风险；\n5. 跨部门协同与资源调度：与数据采集项目组、法务、财务等多方协作，保障外包资源匹配项目需求节奏，对交付结果负责。","requirements":"1. 本科及以上学历，人力资源管理、工商管理、供应链管理等相关专业优先；\n2. 3年以上外包用工管理、劳务管理或供应商管理经验，有100人以上规模外包团队管理经验者优先；\n3. 熟悉劳务派遣/外包相关法律法规，具备风险识别与防控意识；\n4. 具备扎实的商务谈判能力与成本分析能力，能独立完成供应商开发与合同管理全流程；\n5. 跨部门沟通协调能力强，善于在多方诉求中找到平衡点并有效推动落地。","description":"部门介绍\n为了更好地提升城市即时配送的效率与体验，2017年，美团启动了无人机配送服务的探索，通过科技创新推动履约工具变革，加快建设空地协同的本地即时配送网络。\n在过去的六年里，美团无人机完成了飞行器、自动化机场及智能调度系统的研发工作，实现了研发设计、生产制造、运营运维全链条布局，达成了城市复杂场景物流无人机高频次、高密度、多天时、多天侯运行。\n2023年7月，美团无人机在上海发布了自主研发的第四代无人机，跟此前机型相比，新机型升级了环境适应能力，可在“零下20度至50度”的中雨、中雪、6级风、弱光等环境中稳定飞行，能够适应97%以上国内城市的自然环境要求。\n截至2024年12月，美团无人机已在深圳、北京、上海、广州、南京、迪拜等城市开通53条航线，并累计完成订单超40万单。即时零售配送服务覆盖了办公、社区、景区、市政公园、校园、医疗、图书馆等多种场景。在医疗场景中，美团无人机可围绕医疗血液、检验样本、院前急救物资、特殊药品等医疗物资配送需求建设端到端的全天时急送网络。\n\n岗位职责\n1. 外包人员全生命周期管理：覆盖需求规划、供应商导入评估、人员入离职流程管理及绩效考核体系搭建，确保外包团队人力供给持续稳定；\n2. 供应商开发与商务管理：对接劳务/BPO供应商，主导综合评估（资质、服务能力、成本结构、合规性）、商务谈判与合同签署，建立供应商分级管理与动态评价机制；\n3. 外包用工管理体系建设：制定考勤、薪酬结算、安全培训、数据保密等标准化管理制度，推动用工全流程数字化与规范化；\n4. 人力成本管控与合规风险防控：通过数据分析识别外包人天单价、人效比等成本优化机会，把控劳务合规红线（劳务派遣比例、社保合规、数据安全协议等），防范用工法律风险；\n5. 跨部门协同与资源调度：与数据采集项目组、法务、财务等多方协作，保障外包资源匹配项目需求节奏，对交付结果负责。\n\n岗位基本要求\n1. 本科及以上学历，人力资源管理、工商管理、供应链管理等相关专业优先；\n2. 3年以上外包用工管理、劳务管理或供应商管理经验，有100人以上规模外包团队管理经验者优先；\n3. 熟悉劳务派遣/外包相关法律法规，具备风险识别与防控意识；\n4. 具备扎实的商务谈判能力与成本分析能力，能独立完成供应商开发与合同管理全流程；\n5. 跨部门沟通协调能力强，善于在多方诉求中找到平衡点并有效推动落地。\n\n具备以下条件优先\n1. 有AI数据标注/数据采集行业外包管理经验者优先；\n2. 有BPO/众包平台运营管理经验者优先；\n3. 熟悉数字化人力管理工具（如WMS、SRM等系统）者优先；\n4. 有从0到1搭建大规模用工管理体系的经历。\n\n岗位亮点\n1. 前沿行业：深度参与具身智能数据采集运营体系建设，处于AI+机器人行业最前沿的实践一线；\n2. 体系从0到1：主导建设大规模外包用工管理体系，有充分的制度设计和流程优化空间；\n3. 平台资源：依托美团在本地生活领域的强大生态和组织能力，获得专业的管理工具和方法论支持；\n4. 业务影响力：外包人员规模和管理质量直接影响数据采集效率和AI模型训练效果，岗位产出与业务成果强挂钩。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4631694181","sourceKey":"meituan_social","company":"美团","title":"快乐猴-佛山片区经理","city":"佛山市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4631694181&jobShareType=1","duty":"1.负责区域内多家门店超市的日常运营管理工作，包括人员调配、库存管理、销售数据分析等。\n2.负责招聘、培训和管理团队成员，确保团队高效运作。\n3.负责制定并执行营销促销活动，提升线下超市的知名度和盈利能力。","requirements":"1.大学本科及以上学历.\n2.至少8年以上线下超市管理相关工作经验。\n3.具备较强的团队管理能力和沟通协调能力，能够有效领导团队实现业绩目标。\n4.具备良好的数据分析能力和解决问题能力，能够快速响应并解决运营中的问题。\n5.掌握基本的AI工具，使用工具提升工作流程效率。","description":"部门介绍\n快乐猴是美团自营社区超市，依托自有供应链和门店管理体系，聚焦家庭用户的三餐所需，为消费者提供高质价比的食杂商品。快乐猴以数字化能力与科学品控为基础，不断满足消费者对“省”和“便利”的需求。\n\n岗位职责\n1.负责区域内多家门店超市的日常运营管理工作，包括人员调配、库存管理、销售数据分析等。\n2.负责招聘、培训和管理团队成员，确保团队高效运作。\n3.负责制定并执行营销促销活动，提升线下超市的知名度和盈利能力。\n\n岗位基本要求\n1.大学本科及以上学历.\n2.至少8年以上线下超市管理相关工作经验。\n3.具备较强的团队管理能力和沟通协调能力，能够有效领导团队实现业绩目标。\n4.具备良好的数据分析能力和解决问题能力，能够快速响应并解决运营中的问题。\n5.掌握基本的AI工具，使用工具提升工作流程效率。\n\n岗位亮点\n1.可以在快节奏的线下零售行业中展现个人管理能力和团队领导能力。\n2.有机会参与线下超市的整体运营策略规划和执行，实现个人职业发展和成长。\n3.薪资福利优厚，发展空间大，公司提供良好的培训和晋升机会。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4631687320","sourceKey":"meituan_social","company":"美团","title":"快乐猴-东莞片区经理","city":"东莞市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4631687320&jobShareType=1","duty":"1.负责区域多家门店超市的日常运营管理工作，包括人员调配、库存管理、销售数据分析等。\n2.负责招聘、培训和管理团队成员，确保团队高效运作。\n3.负责制定并执行营销促销活动，提升线下超市的知名度和盈利能力。","requirements":"1.大学本科及以上学历.\n2.至少8年以上线下超市管理相关工作经验。\n3.具备较强的团队管理能力和沟通协调能力，能够有效领导团队实现业绩目标。\n4.具备良好的数据分析能力和解决问题能力，能够快速响应并解决运营中的问题。\n5.掌握基本的AI工具，使用工具提升工作流程效率。","description":"部门介绍\n快乐猴是美团自营社区超市，依托自有供应链和门店管理体系，聚焦家庭用户的三餐所需，为消费者提供高质价比的食杂商品。快乐猴以数字化能力与科学品控为基础，不断满足消费者对“省”和“便利”的需求。\n\n岗位职责\n1.负责区域多家门店超市的日常运营管理工作，包括人员调配、库存管理、销售数据分析等。\n2.负责招聘、培训和管理团队成员，确保团队高效运作。\n3.负责制定并执行营销促销活动，提升线下超市的知名度和盈利能力。\n\n岗位基本要求\n1.大学本科及以上学历.\n2.至少8年以上线下超市管理相关工作经验。\n3.具备较强的团队管理能力和沟通协调能力，能够有效领导团队实现业绩目标。\n4.具备良好的数据分析能力和解决问题能力，能够快速响应并解决运营中的问题。\n5.掌握基本的AI工具，使用工具提升工作流程效率。\n\n岗位亮点\n1.可以在快节奏的线下零售行业中展现个人管理能力和团队领导能力。\n2.有机会参与线下超市的整体运营策略规划和执行，实现个人职业发展和成长。\n3.薪资福利优厚，发展空间大，公司提供良好的培训和晋升机会。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4631609532","sourceKey":"meituan_social","company":"美团","title":"快乐猴-深圳片区经理","city":"深圳市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4631609532&jobShareType=1","duty":"1.负责区域多家门店超市的日常运营管理工作，包括人员调配、库存管理、销售数据分析等。\n2.负责招聘、培训和管理团队成员，确保团队高效运作。\n3.负责制定并执行营销促销活动，提升线下超市的知名度和盈利能力。","requirements":"1.大学本科及以上学历.\n2.至少8年以上线下超市管理相关工作经验。\n3.具备较强的团队管理能力和沟通协调能力，能够有效领导团队实现业绩目标。\n4.具备良好的数据分析能力和解决问题能力，能够快速响应并解决运营中的问题。\n5.掌握基本的AI工具，使用工具提升工作流程效率。","description":"部门介绍\n快乐猴是美团自营社区超市，依托自有供应链和门店管理体系，聚焦家庭用户的三餐所需，为消费者提供高质价比的食杂商品。快乐猴以数字化能力与科学品控为基础，不断满足消费者对“省”和“便利”的需求。\n\n岗位职责\n1.负责区域多家门店超市的日常运营管理工作，包括人员调配、库存管理、销售数据分析等。\n2.负责招聘、培训和管理团队成员，确保团队高效运作。\n3.负责制定并执行营销促销活动，提升线下超市的知名度和盈利能力。\n\n岗位基本要求\n1.大学本科及以上学历.\n2.至少8年以上线下超市管理相关工作经验。\n3.具备较强的团队管理能力和沟通协调能力，能够有效领导团队实现业绩目标。\n4.具备良好的数据分析能力和解决问题能力，能够快速响应并解决运营中的问题。\n5.掌握基本的AI工具，使用工具提升工作流程效率。\n\n岗位亮点\n1.可以在快节奏的线下零售行业中展现个人管理能力和团队领导能力。\n2.有机会参与线下超市的整体运营策略规划和执行，实现个人职业发展和成长。\n3.薪资福利优厚，发展空间大，公司提供良好的培训和晋升机会。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4406399745","sourceKey":"meituan_social","company":"美团","title":"品控运营-策略运营（专项&AI提效）","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4406399745&jobShareType=1","duty":"1、全链路提效做功点梳理与场景映射：深入调研品质管理业务线（涵盖商管理、原料验收、生产加工等），盘点现有中台专项、产品与通用AI工具能力。识别高价值AI落地点，将复杂的品控业务流程拆解为可被AI赋能的标准化模块，输出全链路提效做功点地图与解决方案。\n2、AI产品规划与业务场景落地：主导AI赋能品控业务的产品化设计，可自行闭环将业务需求转化为可交付的AI提效工具，应用到业务场景。\n3、效果评估与持续迭代运营：建立AI赋能品控业务的提效评估指标体系，定期输出复盘报告。沉淀可复用的AI应用资产，包括最佳实践案例库、场景操作SOP、AI使用指南等。面向业务内部开展AI工具培训，推动全员“可用、愿用、会用”，打造AI驱动的食安品控新生态。","requirements":"1、AI产品体验与实操能力：对大模型及生成式AI在企业级落地有浓厚兴趣与深刻理解，具备丰富的AI产品体验与工具实操经验。能够基于AI工具快速搭建轻量级业务原型，验证产品逻辑。\n2、业务导向与产品思维：具备极强的产品思维和用户视角，熟悉食品行业全链路（研发、生产、供应链、合规）者优先。能够从业务痛点、产品能力边界、成本收益等维度，精准判断AI工具的适配路径与落地可行性。\n3、技术理解与跨部门协作：具备扎实的AI与技术素养，了解AI模型、NLP、计算机视觉等基本概念，能与技术团队顺畅对话（不强制要求编程能力）。具备优秀的结构化表达与文档撰写能力，方案说明及培训课件，推动跨部门、跨团队协作落地。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1、全链路提效做功点梳理与场景映射：深入调研品质管理业务线（涵盖商管理、原料验收、生产加工等），盘点现有中台专项、产品与通用AI工具能力。识别高价值AI落地点，将复杂的品控业务流程拆解为可被AI赋能的标准化模块，输出全链路提效做功点地图与解决方案。\n2、AI产品规划与业务场景落地：主导AI赋能品控业务的产品化设计，可自行闭环将业务需求转化为可交付的AI提效工具，应用到业务场景。\n3、效果评估与持续迭代运营：建立AI赋能品控业务的提效评估指标体系，定期输出复盘报告。沉淀可复用的AI应用资产，包括最佳实践案例库、场景操作SOP、AI使用指南等。面向业务内部开展AI工具培训，推动全员“可用、愿用、会用”，打造AI驱动的食安品控新生态。\n\n岗位基本要求\n1、AI产品体验与实操能力：对大模型及生成式AI在企业级落地有浓厚兴趣与深刻理解，具备丰富的AI产品体验与工具实操经验。能够基于AI工具快速搭建轻量级业务原型，验证产品逻辑。\n2、业务导向与产品思维：具备极强的产品思维和用户视角，熟悉食品行业全链路（研发、生产、供应链、合规）者优先。能够从业务痛点、产品能力边界、成本收益等维度，精准判断AI工具的适配路径与落地可行性。\n3、技术理解与跨部门协作：具备扎实的AI与技术素养，了解AI模型、NLP、计算机视觉等基本概念，能与技术团队顺畅对话（不强制要求编程能力）。具备优秀的结构化表达与文档撰写能力，方案说明及培训课件，推动跨部门、跨团队协作落地。\n\n具备以下条件优先\n1、有零售行业AI应用落地、Nocode/skill等优化相关实战经历。\n2、有丰富的专项推动和零售行业经验优先。\n\n岗位亮点\n1. 参与公司核心战略项目，提供AI落地场景，帮助业务快速发展。  \n2. 提供完善的培训体系和职业发展通道。  \n3. 团队氛围开放，鼓励创新与自主决策。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4456104163","sourceKey":"meituan_social","company":"美团","title":"小象超市-线下店选址拓展经理（华北）","city":"北京市/石家庄市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4456104163&jobShareType=1","duty":"岗位职责\n1. 负责小象超市的线下大店的选址工作，对所管辖区域的新店选址做现场考察、商圈评估及市场调研工作；\n2. 根据本地市场的特点以及公司开店的要求制定战区规划与开店策略；\n3. 负责项目的商务谈判、合同谈判、基本工程条件的谈判以及风险预估；\n4. 对负责区域网点考察及评估，完成调研报告和选址报告，落实数据化选址的精准要求，并能通过财务测算选择更优项目；\n5. 负责与公司内部相关团队沟通协作，推进项目顺利落地。","requirements":"1.本科及以上学历；\n2.5年以上购物中心选址或商业招商工作经验；\n3.较强的沟通、谈判、协调能力，具备较好的谈判技巧及处理公共关系的能力；\n4.熟悉商业地产市场和本地市场特点，市场敏锐度高；\n5.有高度的敬业精神和责任心，有较强的沟通表达能力。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n岗位职责\n1. 负责小象超市的线下大店的选址工作，对所管辖区域的新店选址做现场考察、商圈评估及市场调研工作；\n2. 根据本地市场的特点以及公司开店的要求制定战区规划与开店策略；\n3. 负责项目的商务谈判、合同谈判、基本工程条件的谈判以及风险预估；\n4. 对负责区域网点考察及评估，完成调研报告和选址报告，落实数据化选址的精准要求，并能通过财务测算选择更优项目；\n5. 负责与公司内部相关团队沟通协作，推进项目顺利落地。\n\n岗位基本要求\n1.本科及以上学历；\n2.5年以上购物中心选址或商业招商工作经验；\n3.较强的沟通、谈判、协调能力，具备较好的谈判技巧及处理公共关系的能力；\n4.熟悉商业地产市场和本地市场特点，市场敏锐度高；\n5.有高度的敬业精神和责任心，有较强的沟通表达能力。\n\n岗位亮点\n小象超市实体线下店背靠即时达业务积累的供应商资源、仓配能力，搭建起近万SKU的优质好商品基盘;以此为基础，构建生鲜、加工食品等特色品类，并与时令结合带来场景化购物体验：体验感优于线下传统商超。此外，小象超市携海量线上用户走向线下，可形成“线上引流，线下体验”的闭环，双轮驱动业务增长。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4508061132","sourceKey":"meituan_social","company":"美团","title":"小象超市-线下店选址拓展经理（天津/山东/沈阳）","city":"天津市/青岛市/济南市/沈阳市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4508061132&jobShareType=1","duty":"1. 负责小象超市的线下大店的选址工作，对所管辖区域的新店选址做现场考察、商圈评估及市场调研工作；\n2. 根据本地市场的特点以及公司开店的要求制定战区规划与开店策略；\n3. 负责项目的商务谈判、合同谈判、基本工程条件的谈判以及风险预估；\n4. 对负责区域网点考察及评估，完成调研报告和选址报告，落实数据化选址的精准要求，并能通过财务测算选择更优项目；\n5. 负责与公司内部相关团队沟通协作，推进项目顺利落地","requirements":"1.本科及以上学历；\n2.5年以上购物中心选址或商业招商工作经验；\n3.较强的沟通、谈判、协调能力，具备较好的谈判技巧及处理公共关系的能力；\n4.熟悉商业地产市场和本地市场特点，市场敏锐度高；\n5.有高度的敬业精神和责任心，有较强的沟通表达能力","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1. 负责小象超市的线下大店的选址工作，对所管辖区域的新店选址做现场考察、商圈评估及市场调研工作；\n2. 根据本地市场的特点以及公司开店的要求制定战区规划与开店策略；\n3. 负责项目的商务谈判、合同谈判、基本工程条件的谈判以及风险预估；\n4. 对负责区域网点考察及评估，完成调研报告和选址报告，落实数据化选址的精准要求，并能通过财务测算选择更优项目；\n5. 负责与公司内部相关团队沟通协作，推进项目顺利落地\n\n岗位基本要求\n1.本科及以上学历；\n2.5年以上购物中心选址或商业招商工作经验；\n3.较强的沟通、谈判、协调能力，具备较好的谈判技巧及处理公共关系的能力；\n4.熟悉商业地产市场和本地市场特点，市场敏锐度高；\n5.有高度的敬业精神和责任心，有较强的沟通表达能力\n\n岗位亮点\n小象超市实体线下店背靠即时达业务积累的供应商资源、仓配能力，搭建起近万SKU的优质好商品基盘;以此为基础，构建生鲜、加工食品等特色品类，并与时令结合带来场景化购物体验：体验感优于线下传统商超。此外，小象超市携海量线上用户走向线下，可形成“线上引流，线下体验”的闭环，双轮驱动业务增长。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4512107583","sourceKey":"meituan_social","company":"美团","title":"无人机自动化设备-机械设计工程师","city":"深圳市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4512107583&jobShareType=1","duty":"设计与开发：\n\n1. 根据无人机机场自动化设备的功能需求，提出机电一体化系统解决方案，主导核心机构的技术攻坚；\n\n2. 根据自动化设备应用场景需求，制定机电执行机构的关键性能指标（输出扭矩/力、定位精度、可靠寿命、噪声等级等），并完成系统级方案设计；\n\n3. 主导机电系统整体设计及子模块分工，完成从原理样机到量产的全链路优化与生产验证；\n\n4.主动探索并运用各类AI工具优化日常工作流程，积极推动AI在业务场景中的落地实践，持续提升个人及团队的工作效率与产出质量。\n\n仿真与验证：\n\n1. 运用有限元分析、多体动力学或机电联合仿真等工具，对机电系统进行性能、热力学及寿命分析；\n\n2. 协同测试团队完成台架/整机测试，完成失效模式分析（FMEA）并驱动设计改进闭环。\n\n跨学科协作：\n\n1. 对接可靠性、工艺、制造等上下游团队，优化设计方案，保证设备的可靠性、可制造性、可维护性；\n\n2. 与电控、算法团队协作，推动机电系统与控制算法的联合调试与参数优化；\n\n3. 协调相关方解决项目开发过程中的技术问题（研发、制造、组装、测试）。\n\n技术研究：\n\n1. 持续跟踪机电系统前沿技术（新型电机、精密传动、轻量化材料等），推动技术选型迭代；\n\n2. 参与专利撰写，构建技术壁垒。\n\n文档管理：\n\n1. 负责BOM、设计图纸等相关生产、加工文件的输出，保证研发质量；\n\n2. 编制测试报告、问题分析报告及设计规范等技术文档，确保知识体系沉淀。","requirements":"教育背景&经验要求：\n\n1. 机械设计、自动化、机电一体化、机器人工程等相关专业，硕士及以上学历；\n\n2. 具备5年以上机电、动力系统、传动系统开发经验。\n\n知识与技能要求：\n\n1. 熟悉机械设计、材料力学、动力学或控制系统等相关知识，具有精密机械、动力系统、自动化设备的设计及量产经验；\n\n2. 具备机电系统设计经验，熟悉机电系统各组成部件（电机、减速器、传动机构等），能够根据具体需求设计、优化机电系统；\n\n3. 熟练掌握结构设计、机电系统设计及仿真工具，能够进行机电系统设计与分析；\n\n4. 了解机械加工工艺、常用材料选型，能够对关键模块进行组装测试验证；\n\n5. 具备 AI 工具实际应用能力，能将 AI 工具融入日常研发流程，包括但不限于：利用 AI 辅助技术文档编写、故障分析及知识沉淀；使用大语言模型进行设计方案评审、仿真参数调优及技术调研；具备基本的 Prompt Engineering 能力，能清晰阐述利用AI解决复杂问题的思路与方法，保持对AI前沿趋势的敏感度。\n\n软性素质：\n\n1. 强烈的创新意识、学习能力、问题解决及总结能力，工作主动性强；\n\n2. 具有良好的跨团队沟通能力及团队协作精神，能适应快节奏研发环境。","description":"部门介绍\n为了更好地提升城市即时配送的效率与体验，2017年，美团启动了无人机配送服务的探索，通过科技创新推动履约工具变革，加快建设空地协同的本地即时配送网络。\n在过去的六年里，美团无人机完成了飞行器、自动化机场及智能调度系统的研发工作，实现了研发设计、生产制造、运营运维全链条布局，达成了城市复杂场景物流无人机高频次、高密度、多天时、多天侯运行。\n2023年7月，美团无人机在上海发布了自主研发的第四代无人机，跟此前机型相比，新机型升级了环境适应能力，可在“零下20度至50度”的中雨、中雪、6级风、弱光等环境中稳定飞行，能够适应97%以上国内城市的自然环境要求。\n截至2024年12月，美团无人机已在深圳、北京、上海、广州、南京、迪拜等城市开通53条航线，并累计完成订单超40万单。即时零售配送服务覆盖了办公、社区、景区、市政公园、校园、医疗、图书馆等多种场景。在医疗场景中，美团无人机可围绕医疗血液、检验样本、院前急救物资、特殊药品等医疗物资配送需求建设端到端的全天时急送网络。\n\n岗位职责\n设计与开发：\n\n1. 根据无人机机场自动化设备的功能需求，提出机电一体化系统解决方案，主导核心机构的技术攻坚；\n\n2. 根据自动化设备应用场景需求，制定机电执行机构的关键性能指标（输出扭矩/力、定位精度、可靠寿命、噪声等级等），并完成系统级方案设计；\n\n3. 主导机电系统整体设计及子模块分工，完成从原理样机到量产的全链路优化与生产验证；\n\n4.主动探索并运用各类AI工具优化日常工作流程，积极推动AI在业务场景中的落地实践，持续提升个人及团队的工作效率与产出质量。\n\n仿真与验证：\n\n1. 运用有限元分析、多体动力学或机电联合仿真等工具，对机电系统进行性能、热力学及寿命分析；\n\n2. 协同测试团队完成台架/整机测试，完成失效模式分析（FMEA）并驱动设计改进闭环。\n\n跨学科协作：\n\n1. 对接可靠性、工艺、制造等上下游团队，优化设计方案，保证设备的可靠性、可制造性、可维护性；\n\n2. 与电控、算法团队协作，推动机电系统与控制算法的联合调试与参数优化；\n\n3. 协调相关方解决项目开发过程中的技术问题（研发、制造、组装、测试）。\n\n技术研究：\n\n1. 持续跟踪机电系统前沿技术（新型电机、精密传动、轻量化材料等），推动技术选型迭代；\n\n2. 参与专利撰写，构建技术壁垒。\n\n文档管理：\n\n1. 负责BOM、设计图纸等相关生产、加工文件的输出，保证研发质量；\n\n2. 编制测试报告、问题分析报告及设计规范等技术文档，确保知识体系沉淀。\n\n岗位基本要求\n教育背景&经验要求：\n\n1. 机械设计、自动化、机电一体化、机器人工程等相关专业，硕士及以上学历；\n\n2. 具备5年以上机电、动力系统、传动系统开发经验。\n\n知识与技能要求：\n\n1. 熟悉机械设计、材料力学、动力学或控制系统等相关知识，具有精密机械、动力系统、自动化设备的设计及量产经验；\n\n2. 具备机电系统设计经验，熟悉机电系统各组成部件（电机、减速器、传动机构等），能够根据具体需求设计、优化机电系统；\n\n3. 熟练掌握结构设计、机电系统设计及仿真工具，能够进行机电系统设计与分析；\n\n4. 了解机械加工工艺、常用材料选型，能够对关键模块进行组装测试验证；\n\n5. 具备 AI 工具实际应用能力，能将 AI 工具融入日常研发流程，包括但不限于：利用 AI 辅助技术文档编写、故障分析及知识沉淀；使用大语言模型进行设计方案评审、仿真参数调优及技术调研；具备基本的 Prompt Engineering 能力，能清晰阐述利用AI解决复杂问题的思路与方法，保持对AI前沿趋势的敏感度。\n\n软性素质：\n\n1. 强烈的创新意识、学习能力、问题解决及总结能力，工作主动性强；\n\n2. 具有良好的跨团队沟通能力及团队协作精神，能适应快节奏研发环境。\n\n具备以下条件优先\n1. 有足式、轮式或机械臂类机器人本体或关节设计、跨学科综合能力、机电集成的项目经历者优先；\n\n2. 有伺服电机选型、驱动器调试、闭环控制参数整定经验者优先；\n\n3. 有 AI 工具落地实践（如使用 LLM 辅助仿真、设计评审、文档生成）经验者优先。\n\n岗位亮点\n1. 你将与无人机和机器人领域的前沿技术专家，优秀的行业资源一起合作，快速成长和提升；\n\n2. 你将见证无人配送网络的建设过程，感受科技改变社会的历史使命和自豪；\n\n3. 团队氛围nice，鼓励创新和试错，广阔的个人施展空间。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4631373934","sourceKey":"meituan_social","company":"美团","title":"小象超市-选址拓展经理-线下店","city":"上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4631373934&jobShareType=1","duty":"1.负责小象超市的选址工作，对所管辖区域的新店选址做现场考察、商圈评估及市场调研工作；\n2.根据本地市场的特点以及公司开店的要求制定战区规划与开店策略；\n3.负责项目的商务谈判、合同谈判、基本工程条件的谈判以及风险预估；\n4.利用相关工具对预选址进行详细分析，做出逻辑清晰、条理分明的选址报告；\n5.负责与公司内部相关团队沟通协作；\n6.负责跟进项目签约、接场、开业的流程，具备处理门店开业前施工过程中遇到的各种问题的能力。","requirements":"1.大专以上学历；\n2.5年及以上零售拓展行业的相关工作经验，购物中心开店经验者优先；\n3.较强的专业能力，能够独立完成项目的评估、选址、谈判、签约及进场工作，具备制定战区图的能力；\n4.熟悉所负责区域的商业地产及房产市场，有一定的人脉资源；\n5.掌握与租赁合同相关的基本法律、法规问题，与房东洽谈时能够辨别和规避法律风险、保障公司权益；\n6.掌握基本的工程常识，做选址评估时能够辨别较为明显的工程隐患；\n7.较强的沟通、谈判、协调能力，具备一定的谈判技巧及处理公共关系的能力；\n8. 有较强的自我驱动力、学习能力，对新零售有一定了解。\n9.因业务需求，本岗位需要出差，具体由公司统一安排。\n10.掌握基本的AI工具，使用工具提升工作流程效率。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1.负责小象超市的选址工作，对所管辖区域的新店选址做现场考察、商圈评估及市场调研工作；\n2.根据本地市场的特点以及公司开店的要求制定战区规划与开店策略；\n3.负责项目的商务谈判、合同谈判、基本工程条件的谈判以及风险预估；\n4.利用相关工具对预选址进行详细分析，做出逻辑清晰、条理分明的选址报告；\n5.负责与公司内部相关团队沟通协作；\n6.负责跟进项目签约、接场、开业的流程，具备处理门店开业前施工过程中遇到的各种问题的能力。\n\n岗位基本要求\n1.大专以上学历；\n2.5年及以上零售拓展行业的相关工作经验，购物中心开店经验者优先；\n3.较强的专业能力，能够独立完成项目的评估、选址、谈判、签约及进场工作，具备制定战区图的能力；\n4.熟悉所负责区域的商业地产及房产市场，有一定的人脉资源；\n5.掌握与租赁合同相关的基本法律、法规问题，与房东洽谈时能够辨别和规避法律风险、保障公司权益；\n6.掌握基本的工程常识，做选址评估时能够辨别较为明显的工程隐患；\n7.较强的沟通、谈判、协调能力，具备一定的谈判技巧及处理公共关系的能力；\n8. 有较强的自我驱动力、学习能力，对新零售有一定了解。\n9.因业务需求，本岗位需要出差，具体由公司统一安排。\n10.掌握基本的AI工具，使用工具提升工作流程效率。\n\n岗位亮点\n1.线下购物中心门店拓展；\n2.能够和做事、目标感、使命感强的优秀团队合作，一起拿结果；","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4609127369","sourceKey":"meituan_social","company":"美团","title":"Partnership Management Manager","city":"科威特城","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4609127369&jobShareType=1","duty":"1. Develop and expand 3PL partners and rider capacity according to delivery demand in each city.\n\n2. Build and maintain strong long-term relationships with 3PL partners.\n\n3. Improve 3PL operational capability through training, communication, performance review, and continuous support.\n\n4. Develop and optimize 3PL fleet operation plans to improve rider availability, rider quality, rider efficiency, and service stability.\n\n5. Ensure 100% compliance of 3PL partners and riders with company policies, local regulations, safety standards, and operational requirements.\n\n6. Set clear performance metrics for partners, conduct audits, and organize regular business reviews.\n\n7. Monitor rider behavior and service quality through 3PL partners to ensure customer satisfaction and delivery experience.\n\n8. Work closely with the operations team to design and manage reward and penalty mechanisms for 3PL partners.\n\n9. Take ownership of partner performance in assigned regions, including rider recruitment, daily operations, management quality, and user experience goals.\n\n10. Cooperate with product, operations, finance, and legal teams to optimize 3PL onboarding, payment, compliance, and management processes.\n\n11. Manage the exit or replacement process for partners who fail to meet company requirements.\n\n12. Complete other partnership management tasks assigned by the manager.","requirements":"1. Bachelor’s degree or above.\n2. At least 3 years of experience in rider growth, 3PL management, logistics operations, partner management, delivery operations, or related fields.\n3. Strong knowledge of the local 3PL market, rider supply market, and delivery operations.\n4. Excellent communication and relationship management skills.\n5. Strong negotiation, problem-solving, and execution abilities.\n6. Data-driven mindset with the ability to track KPIs and improve partner performance.\n7. Ability to work under pressure and manage multiple partners and cities.\n8. Proficiency in English is required; Arabic is highly preferred.\n9. Experience in food delivery, quick commerce, e-commerce logistics, or last-mile delivery is preferred.","description":"部门介绍\n美团的使命是“帮大家吃得更好，生活更好”，公司聚焦“零售 + 科技”战略，和广大商户与各类合作伙伴一起，努力为消费者提供品质生活，推动商品零售和服务零售在需求侧和供给侧的数字化转型。\n2018年9月20日，美团正式在港交所挂牌上市。美团将始终坚持以客户为中心，不断加大在科技研发方面的投入，更好承担社会责任，更多创造社会价值，与广大合作伙伴一起发展共赢。\n\n岗位职责\n1. Develop and expand 3PL partners and rider capacity according to delivery demand in each city.\n\n2. Build and maintain strong long-term relationships with 3PL partners.\n\n3. Improve 3PL operational capability through training, communication, performance review, and continuous support.\n\n4. Develop and optimize 3PL fleet operation plans to improve rider availability, rider quality, rider efficiency, and service stability.\n\n5. Ensure 100% compliance of 3PL partners and riders with company policies, local regulations, safety standards, and operational requirements.\n\n6. Set clear performance metrics for partners, conduct audits, and organize regular business reviews.\n\n7. Monitor rider behavior and service quality through 3PL partners to ensure customer satisfaction and delivery experience.\n\n8. Work closely with the operations team to design and manage reward and penalty mechanisms for 3PL partners.\n\n9. Take ownership of partner performance in assigned regions, including rider recruitment, daily operations, management quality, and user experience goals.\n\n10. Cooperate with product, operations, finance, and legal teams to optimize 3PL onboarding, payment, compliance, and management processes.\n\n11. Manage the exit or replacement process for partners who fail to meet company requirements.\n\n12. Complete other partnership management tasks assigned by the manager.\n\n岗位基本要求\n1. Bachelor’s degree or above.\n2. At least 3 years of experience in rider growth, 3PL management, logistics operations, partner management, delivery operations, or related fields.\n3. Strong knowledge of the local 3PL market, rider supply market, and delivery operations.\n4. Excellent communication and relationship management skills.\n5. Strong negotiation, problem-solving, and execution abilities.\n6. Data-driven mindset with the ability to track KPIs and improve partner performance.\n7. Ability to work under pressure and manage multiple partners and cities.\n8. Proficiency in English is required; Arabic is highly preferred.\n9. Experience in food delivery, quick commerce, e-commerce logistics, or last-mile delivery is preferred.\n\n岗位亮点\nThe Partnership Management Manager is responsible for developing, expanding, and managing Keeta’s third-party logistics partners and rider supply network. This role ensures that 3PL partners can provide sufficient delivery capacity, maintain high service quality, comply with company standards, and support business growth across assigned cities.","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4427335861","sourceKey":"meituan_social","company":"美团","title":"海外智能资金管理","city":"北京市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4427335861&jobShareType=1","duty":"1、智能资金预测与头寸管理： 负责构建并优化海外市场的资金流预测模型，利用AI算法分析历史数据及宏观经济指标，实现资金头寸的实时精准预测与自动平衡。\n\n2、自动化资金调度与结算： 设计并执行完善的资金调拨策略和差错管理，利用自动化系统监控资金池状态，实现资金最优配置，保证资金安全的前提下降低资金沉淀成本。\n\n3、智能风控与合规监测： 建立基于AI的资金链路风控体系，实时监控异常交易与流动性风险，确保资金流转全链路的合规性与安全性。\n\n4、数据驱动的决策支持： 深度挖掘资金运营数据，通过智能化报表与分析工具，为海外信贷业务的增长策略、融资计划及成本优化提供前瞻性的数据洞察与决策建议。\n\n5、智能化系统迭代与优化： 协同技术团队推动资金管理系统的智能化升级，持续优化算法模型，提升资金运营的自动化水平与响应效率。","requirements":"1、5年以上资金管理工作经验，有信贷背景者优先。\n\n2、具备较强的逻辑思维和极强的个人落地实施能力和意愿。\n\n3、能够独立思考并解决问题，执行力和目标感强，具备良好的协调沟通能力，善于跨团队协作。\n\n4、有大型互联网公司海外业务经验者优先，熟悉南美市场金融政策、支付结算习惯及当地银行体系；具备英语沟通能力。\n\n5、具有创业精神，善于应对挑战与压力。\n\n6、 熟练掌握Python、SQL等数据分析工具，能够独立进行资金流数据清洗、特征工程及预测模型构建，具备将业务逻辑转化为算法逻辑的能力。","description":"部门介绍\n美团金融服务平台成立于2016年，以“场景+金融”模式，携手合作伙伴构建开放生态，为美团平台用户和商户提供底层账户、支付通道、信贷、保险和理财等金融解决方案。我们致力于以科技为核心，助力金融机构打通金融普惠“最后一公里”。我们期待与大家共同完成每一件平凡而卓越的事情，一起为用户提供优质的产品体验，守护用户的资金安全，让生活变得更美好。\n\n岗位职责\n1、智能资金预测与头寸管理： 负责构建并优化海外市场的资金流预测模型，利用AI算法分析历史数据及宏观经济指标，实现资金头寸的实时精准预测与自动平衡。\n\n2、自动化资金调度与结算： 设计并执行完善的资金调拨策略和差错管理，利用自动化系统监控资金池状态，实现资金最优配置，保证资金安全的前提下降低资金沉淀成本。\n\n3、智能风控与合规监测： 建立基于AI的资金链路风控体系，实时监控异常交易与流动性风险，确保资金流转全链路的合规性与安全性。\n\n4、数据驱动的决策支持： 深度挖掘资金运营数据，通过智能化报表与分析工具，为海外信贷业务的增长策略、融资计划及成本优化提供前瞻性的数据洞察与决策建议。\n\n5、智能化系统迭代与优化： 协同技术团队推动资金管理系统的智能化升级，持续优化算法模型，提升资金运营的自动化水平与响应效率。\n\n岗位基本要求\n1、5年以上资金管理工作经验，有信贷背景者优先。\n\n2、具备较强的逻辑思维和极强的个人落地实施能力和意愿。\n\n3、能够独立思考并解决问题，执行力和目标感强，具备良好的协调沟通能力，善于跨团队协作。\n\n4、有大型互联网公司海外业务经验者优先，熟悉南美市场金融政策、支付结算习惯及当地银行体系；具备英语沟通能力。\n\n5、具有创业精神，善于应对挑战与压力。\n\n6、 熟练掌握Python、SQL等数据分析工具，能够独立进行资金流数据清洗、特征工程及预测模型构建，具备将业务逻辑转化为算法逻辑的能力。\n\n岗位亮点\n1、参与行业头部金融平台海外业务发展，业务成长空间大。\n\n2、接触大模型在信贷场景从 0 到 1 的落地机会，站在 AI 金融科技前沿。\n\n3、团队氛围开放，鼓励创新与自主决策；平台资源丰富（数据、算力、标注等），支持 AI 探索与快速验证。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4586366950","sourceKey":"meituan_social","company":"美团","title":"美团闪购-AI业务运营-牵牛花Claw","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4586366950&jobShareType=1","duty":"1、负责美团闪购牵牛花Claw的业务策略，结合业务发展需求，制定并落地有竞争力的业务发展路径；\n2、挖掘真实场景下用户对AI的真实需求，主导全链路AI业务方案落地；\n3、联动产品、研发团队推进AI项目落地，负责需求识别、需求拆解、进度跟进并为产品使用效果负责；\n4、跟踪内外部AI趋势及创新工具，结合业务场景引入差异化方案，构建AI竞争优势。","requirements":"1、具有3年以上产品运营或业务运营工作经历，有深度AI工具使用习惯；\n2、对AI有热情，相信AI在业务场景中的价值；\n3、逻辑清晰，有一定的业务及技术理解力，能够快速了解和学习复杂系统产品的功能和逻辑；\n4、有独立牵引或深度参与AI项目者加分；\n5、有即时零售经验加分。","description":"部门介绍\n美团闪购是美团旗下的即时零售平台，依托即时配送能力，连接本地零售供给，满足消费者30分钟万物到家的即时需求。美团闪购涵盖超市便利、食材、水果、鲜花绿植、休闲零食、酒水饮料、数码家电、美妆个护、母婴玩具、日用百货、服饰鞋帽、宠物等诸多品类，业务覆盖全国近3,000个县市区旗，每日百万级在岗骑手，以高效的配送、丰富的品类和广泛的覆盖，为美团数亿用户带来便捷的生活体验，积极助力实体零售线上化转型，提升本地商业活力。\n\n岗位职责\n1、负责美团闪购牵牛花Claw的业务策略，结合业务发展需求，制定并落地有竞争力的业务发展路径；\n2、挖掘真实场景下用户对AI的真实需求，主导全链路AI业务方案落地；\n3、联动产品、研发团队推进AI项目落地，负责需求识别、需求拆解、进度跟进并为产品使用效果负责；\n4、跟踪内外部AI趋势及创新工具，结合业务场景引入差异化方案，构建AI竞争优势。\n\n岗位基本要求\n1、具有3年以上产品运营或业务运营工作经历，有深度AI工具使用习惯；\n2、对AI有热情，相信AI在业务场景中的价值；\n3、逻辑清晰，有一定的业务及技术理解力，能够快速了解和学习复杂系统产品的功能和逻辑；\n4、有独立牵引或深度参与AI项目者加分；\n5、有即时零售经验加分。\n\n岗位亮点\n1、我们是一个年轻有活力的团队，团队有明确的成长路径；\n2、合作方有自营业务、社会化众多头部商家，能全面且深入的理解即时零售行业，视野广阔，适合提升深度思考能力。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4599989499","sourceKey":"meituan_social","company":"美团","title":"大客户经理","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4599989499&jobShareType=1","duty":"1-拿结果：制定负责省份商务拓展策略和目标拆解并落地执行，确保团队方向与部门整体规划一致，对公司整体营收、利润、客户增长负最终责任\n\n2-大客户攻坚与客户关系：负责战略级大客户的谈判与签约，维护核心客户关系，增强客户满意度和忠诚度，推动续费与增购\n\n3-内部协调与支持：敏锐捕捉市场动态，快速定位潜在问题，联动跨部门资源推动解决方案\n\n4-行业洞察与市场分析：跟踪行业趋势、市场动态，及时调整销售打法，保持公司市场竞争力","requirements":"本科及以上学历，5年以上SaaS软件销售经验，需具备显著业绩成果\n\n熟悉零售行业O2O业务，有成熟客户资源、行业渠道、大客户案例者优先\n\n能力要求：具备极强的目标感、谈判能力、市场开拓能力，精通SaaS获客、成交、续费、增购全流程","description":"部门介绍\n美团闪购是美团旗下的即时零售平台，依托即时配送能力，连接本地零售供给，满足消费者30分钟万物到家的即时需求。美团闪购涵盖超市便利、食材、水果、鲜花绿植、休闲零食、酒水饮料、数码家电、美妆个护、母婴玩具、日用百货、服饰鞋帽、宠物等诸多品类，业务覆盖全国近3,000个县市区旗，每日百万级在岗骑手，以高效的配送、丰富的品类和广泛的覆盖，为美团数亿用户带来便捷的生活体验，积极助力实体零售线上化转型，提升本地商业活力。\n\n岗位职责\n1-拿结果：制定负责省份商务拓展策略和目标拆解并落地执行，确保团队方向与部门整体规划一致，对公司整体营收、利润、客户增长负最终责任\n\n2-大客户攻坚与客户关系：负责战略级大客户的谈判与签约，维护核心客户关系，增强客户满意度和忠诚度，推动续费与增购\n\n3-内部协调与支持：敏锐捕捉市场动态，快速定位潜在问题，联动跨部门资源推动解决方案\n\n4-行业洞察与市场分析：跟踪行业趋势、市场动态，及时调整销售打法，保持公司市场竞争力\n\n岗位基本要求\n本科及以上学历，5年以上SaaS软件销售经验，需具备显著业绩成果\n\n熟悉零售行业O2O业务，有成熟客户资源、行业渠道、大客户案例者优先\n\n能力要求：具备极强的目标感、谈判能力、市场开拓能力，精通SaaS获客、成交、续费、增购全流程\n\n具备以下条件优先\n有SAAS拓展相关经验优先\n\n岗位亮点\n即时零售是美团\"零售+科技\"新战略下的重点方向，闪购业务在高速增长阶段，个人发展空间大\n\n你有机会跟随美团牵牛花业务为即时零售赋能，支撑业务高速发展","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4613831123","sourceKey":"meituan_social","company":"美团","title":"火石-渠道经理（城市销代合伙人方向）","city":"北京市/杭州市/成都市/广州市/重庆市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4613831123&jobShareType=1","duty":"1、 渠道商体系建设（从0到1）\n负责所辖区域城市渠道商的招募、评估与签约，制定区域渠道策略，快速扩大市场覆盖。\n主导渠道商团队的组建赋能，帮助渠道商搭建销售队伍，实现团餐客户的规模化开发与拓展。\n2、渠道商运营与赋能\n对签约渠道商进行全生命周期管理：日常运营、业绩追踪、问题响应、培训赋能。\n协助渠道商做好客户维护与售后跟进，提升渠道商忠诚度与活跃度，打造长期稳定的合作关系。\n3、业绩目标达成\n制定并分解区域销售目标，追踪核心渠道数据（GMV增长、客户开发、客户留存等）。\n通过精细化运营手段推动渠道商业绩持续增长，确保区域目标达成。\n4、市场洞察与策略反馈\n持续跟踪区域竞争态势，掌握团餐客户需求变化。\n提炼市场洞察并反馈至商品、运营、物流团队，驱动业务策略优化。\n5、跨部门协同保障\n协同商品、物流、售后等部门，保障渠道商和相关部门联动效率，推动客户问题快速响应与解决。","requirements":"1、专科及以上学历，3年以上B端渠道销售/管理经验，有生鲜食材、餐饮供应链、团餐行业背景优先\n2、具备渠道开拓与招募能力，有从0到1搭建区域渠道体系的成功经验\n3、熟悉团餐/餐饮供应链市场生态，理解渠道商（代理商）业务模式\n4、资源整合具备较强的内外部资源整合与协调能力，能独立操盘区域业务\n5、热爱食材供应链行业，有创业心态，愿意与渠道商共同成长","description":"部门介绍\n快驴进货是美团旗下的餐饮供应链平台，帮助餐饮商户以更低成本、更高效率来获取安全可靠的食材供应，让餐饮采购更简单。快驴进货同步发展“自营+平台”的业务模式，在采购环节一方面向上游供应商直采大宗商品，另一方面引入各地批发商，助力平台伙伴共同发展；在销售环节既有自建团队进行市场、客户拓展，又帮助各地批发商拓展业务；同时自建仓储管理系统、配送网络与团队，为客户提供优质履约服务。\n截至2022年，快驴进货布局了全国41个城市，为百万家商户提供“全、省、稳、好”的餐饮供应链服务。我们拥有3000+品牌食材、超5万SKU商品、超28万商品资质，并提供源头严审核、食品安全严把关、24小时无忧售后的全面保障，实现手机下单、送货上门的高效采购模式，帮百万商家节省了采购时间与成本，助力平台伙伴共同发展，在万亿市场共享机遇。\n在这里，你将收获完善的员工发展机制及学习体系，与各界专家一起深度参与餐饮供应链业务的发展。欢迎优秀的你加入美团快驴进货，与我们一起成长，一起更好！\n\n岗位职责\n1、 渠道商体系建设（从0到1）\n负责所辖区域城市渠道商的招募、评估与签约，制定区域渠道策略，快速扩大市场覆盖。\n主导渠道商团队的组建赋能，帮助渠道商搭建销售队伍，实现团餐客户的规模化开发与拓展。\n2、渠道商运营与赋能\n对签约渠道商进行全生命周期管理：日常运营、业绩追踪、问题响应、培训赋能。\n协助渠道商做好客户维护与售后跟进，提升渠道商忠诚度与活跃度，打造长期稳定的合作关系。\n3、业绩目标达成\n制定并分解区域销售目标，追踪核心渠道数据（GMV增长、客户开发、客户留存等）。\n通过精细化运营手段推动渠道商业绩持续增长，确保区域目标达成。\n4、市场洞察与策略反馈\n持续跟踪区域竞争态势，掌握团餐客户需求变化。\n提炼市场洞察并反馈至商品、运营、物流团队，驱动业务策略优化。\n5、跨部门协同保障\n协同商品、物流、售后等部门，保障渠道商和相关部门联动效率，推动客户问题快速响应与解决。\n\n岗位基本要求\n1、专科及以上学历，3年以上B端渠道销售/管理经验，有生鲜食材、餐饮供应链、团餐行业背景优先\n2、具备渠道开拓与招募能力，有从0到1搭建区域渠道体系的成功经验\n3、熟悉团餐/餐饮供应链市场生态，理解渠道商（代理商）业务模式\n4、资源整合具备较强的内外部资源整合与协调能力，能独立操盘区域业务\n5、热爱食材供应链行业，有创业心态，愿意与渠道商共同成长\n\n岗位亮点\n深度参与从0到1：快驴渠道正处于快速扩张阶段，将直接操盘城市渠道商体系建设，不是执行者，而是区域市场的开拓者。\n业务空间大：招募→赋能→运营→业绩，渠道全链路闭环，操盘感强。\n资源支持足：美团官方品牌、海量商品货源、餐饮客户资源共享、行业专家上门指导，背后是整个美团生态。\n业务红利期：B2B餐饮供应链是美团战略级业务，渠道红利窗口期，先入者占先机。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4620937479","sourceKey":"meituan_social","company":"美团","title":"营销产品经理（券方向）","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4620937479&jobShareType=1","duty":"1、参与制定核心本地商业营销系统的发展规划和计划，整合各业务营销能力，参与统一券平台的补贴结构、招商、制券、发券、用券、券资产、风险管控、交易和算价引擎等核心模块的建设，可负责其中一个或多个方向\n\n2、协同各业务营销和用户增长部门，梳理业务用券场景和需求，优化上下游联动机制并为营销效果负责，完成对应能力与方案建设，深入共建达成业务结果\n\n3、持续进行市场调研、竞争分析和对标，深度理解业务需求，保障营销系统的先进性和竞争优势，确保系统高效、稳定、灵活，结合AI技术发展，探索券平台工具能力和服务创新，为业务创造增量价值","requirements":"1、大学本科及以上学历，有5年以上互联网平台产品工作经验，有营销中台、优惠券系统、招商系统、营销投放系统工作经验优先\n\n2、能动性强，具备良好的沟通协调能力，有合作精神，目标导向，能够制定Roadmap并推动落地，能够持续学习并学以致用\n\n3、营销系统的规划与建设，需要有更体系化的思维，需要对平台生态、用户增长、业务经营有全面认知与思考，需要对复利与长效机制负责","description":"部门介绍\n美团平台为用户的基础产品体验负责，还承担了美团的用户增长、市场和品牌营销以及多条业务线的产品设计职责，建立了融合文字、图片、视频和直播等不同形式的內容生态系统，同时整合地图服务部、客户服务和体验部、企业业务部、网约车业务部等部门，致力于用科技提升美团数亿消费者、近千万商家、骑手、司机和团长的服务体验。美团平台拥有高并发、多业务的复杂场景，为技术深度优化提供了最佳实践可能。这里有简单、讲逻辑、有爱的团队，更是一块理想的实战场地，舞台广阔，欢迎你来尽情施展。\n\n岗位职责\n1、参与制定核心本地商业营销系统的发展规划和计划，整合各业务营销能力，参与统一券平台的补贴结构、招商、制券、发券、用券、券资产、风险管控、交易和算价引擎等核心模块的建设，可负责其中一个或多个方向\n\n2、协同各业务营销和用户增长部门，梳理业务用券场景和需求，优化上下游联动机制并为营销效果负责，完成对应能力与方案建设，深入共建达成业务结果\n\n3、持续进行市场调研、竞争分析和对标，深度理解业务需求，保障营销系统的先进性和竞争优势，确保系统高效、稳定、灵活，结合AI技术发展，探索券平台工具能力和服务创新，为业务创造增量价值\n\n岗位基本要求\n1、大学本科及以上学历，有5年以上互联网平台产品工作经验，有营销中台、优惠券系统、招商系统、营销投放系统工作经验优先\n\n2、能动性强，具备良好的沟通协调能力，有合作精神，目标导向，能够制定Roadmap并推动落地，能够持续学习并学以致用\n\n3、营销系统的规划与建设，需要有更体系化的思维，需要对平台生态、用户增长、业务经营有全面认知与思考，需要对复利与长效机制负责\n\n岗位亮点\n1、有机会从零到一打造企业级营销平台，服务上亿用户。\n\n2、营销系统复杂度高，链路长、场景多，能力和经验可以得到全面提升。\n\n3、深度参与公司级项目和策略制定，有机会对行业产生重大影响。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4614072811","sourceKey":"meituan_social","company":"美团","title":"沙特-配送运营","city":"利雅得","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4614072811&jobShareType=1","duty":"1. 负责利雅得地区配送网络的日常运营管理，优化配送路径与时效，提升整体运营效率。  \n2. 制定并执行配送运营策略，确保订单准时交付率、客户满意度等关键指标达成。  \n3. 管理配送团队，包括人员排班、绩效评估、培训与激励，提升团队执行力与服务质量。  \n4. 协同仓储、调度、客服等部门，推动跨部门协作，解决配送过程中的异常问题。  \n5. 分析运营数据，识别瓶颈并提出改进方案，持续优化成本结构与运营流程。","requirements":"1. 大学本科及以上学历，物流、供应链、交通运输等相关专业优先。  \n2. 具备5年以上物流或配送运营相关工作经验，有中东地区工作经验者优先。  \n3. 熟悉城市配送网络设计与运营管理，具备较强的数据分析与问题解决能力。  \n4. 具备良好的团队管理与沟通协调能力，能够带领团队达成业务目标。  \n5. 熟练使用办公软件及物流管理系统，英语或阿拉伯语能力者优先。","description":"部门介绍\n美团的使命是“帮大家吃得更好，生活更好”，公司聚焦“零售 + 科技”战略，和广大商户与各类合作伙伴一起，努力为消费者提供品质生活，推动商品零售和服务零售在需求侧和供给侧的数字化转型。\n2018年9月20日，美团正式在港交所挂牌上市。美团将始终坚持以客户为中心，不断加大在科技研发方面的投入，更好承担社会责任，更多创造社会价值，与广大合作伙伴一起发展共赢。\n\n岗位职责\n1. 负责利雅得地区配送网络的日常运营管理，优化配送路径与时效，提升整体运营效率。  \n2. 制定并执行配送运营策略，确保订单准时交付率、客户满意度等关键指标达成。  \n3. 管理配送团队，包括人员排班、绩效评估、培训与激励，提升团队执行力与服务质量。  \n4. 协同仓储、调度、客服等部门，推动跨部门协作，解决配送过程中的异常问题。  \n5. 分析运营数据，识别瓶颈并提出改进方案，持续优化成本结构与运营流程。\n\n岗位基本要求\n1. 大学本科及以上学历，物流、供应链、交通运输等相关专业优先。  \n2. 具备5年以上物流或配送运营相关工作经验，有中东地区工作经验者优先。  \n3. 熟悉城市配送网络设计与运营管理，具备较强的数据分析与问题解决能力。  \n4. 具备良好的团队管理与沟通协调能力，能够带领团队达成业务目标。  \n5. 熟练使用办公软件及物流管理系统，英语或阿拉伯语能力者优先。\n\n岗位亮点\n1. 加入快速发展的物流平台，参与区域核心业务运营，具备广阔的职业发展空间。  \n2. 提供具有市场竞争力的薪酬福利与完善的培训体系。  \n3. 工作地点位于利雅得核心区域，交通便利，办公环境现代化。  \n4. 团队氛围开放包容，鼓励创新与持续改进。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:2518736406","sourceKey":"meituan_social","company":"美团","title":"电销四区-电销广告商务拓展专员","city":"石家庄市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=2518736406&jobShareType=1","duty":"1、负责美团全国城市餐饮商户广告产品的线上入驻，促成商户与平台的持续合作；\n2、通过主动电话外呼，与合作商户负责人建立客情，洞察经营需求，并提供专业的线上营销解决方案；\n3、接听商户电话，及时响应商户诉求，为商户提供良好的使用体验。","requirements":"1、专科及以上学历；\n2、能够熟练使用办公软件；\n3、有很强的学习能力和适应能力，能够快速迭代，拥抱变化；\n4、积极主动、富有激情、具有良好的适应能力和沟通能力。","description":"部门介绍\n商业增值部是服务于美团核心本地商业客户的增值服务平台，覆盖餐饮、即时零售、医药、休闲娱乐、丽人医美、生活服务、酒旅度假等业务领域。我们致力于构建健康的本地商业生态，通过为平台客户和消费者提供符合其需求的多元、便捷、高效的商业产品和服务，帮助生态伙伴提高效率、优化经营、实现持续健康发展，推动本地商业数字化营销的发展，促进商业生态繁荣。作为本地商业的头部平台，我们为产品、运营、商务、技术、商业分析等领域人才提供广阔的发展空间。诚邀你加入美团商业增值团队，共筑本地商业的健康繁荣生态！\n\n岗位职责\n1、负责美团全国城市餐饮商户广告产品的线上入驻，促成商户与平台的持续合作；\n2、通过主动电话外呼，与合作商户负责人建立客情，洞察经营需求，并提供专业的线上营销解决方案；\n3、接听商户电话，及时响应商户诉求，为商户提供良好的使用体验。\n\n岗位基本要求\n1、专科及以上学历；\n2、能够熟练使用办公软件；\n3、有很强的学习能力和适应能力，能够快速迭代，拥抱变化；\n4、积极主动、富有激情、具有良好的适应能力和沟通能力。\n\n岗位亮点\n1、入职即开展带薪培训；\n2、入职即购买六险一金，并享受带薪年假；\n3、完善的晋升发展机制；\n4、每年一次免费健康体检；\n5、丰富的员工活动和每月团建活动；\n6、双休+法定节假日。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4605662011","sourceKey":"meituan_social","company":"美团","title":"【Kuwait】License Manager","city":"科威特城","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4605662011&jobShareType=1","duty":"1. License & Permit Management: Lead end-to-end store license applications in Kuwait, including municipal, commercial, food safety, fire safety, and signage permits. Ensure all stores maintain valid documentation.\n2. Government Relations: Build relationships with Kuwait authorities (Municipality, MOCI, Fire Force, PAFN). Track regulatory changes and assess impact on operations.\n3. Compliance Tracking: Maintain a compliance system to monitor license status and expiry.\n4. New Store Support: Coordinate with engineering and operations to secure all permits before store launch; Manage the critical path to avoid opening delays.\n5. Risk & Inspection Management: Handle government inspections and violation notices. Implement corrective actions to minimize penalties and disruptions.","requirements":"1. Bachelor's degree or above; quick commerce or retail chain experience preferred.\n2. 3+ years in license/permit management in Kuwait, familiar with local municipal, commercial, and food safety regulations.\n3. Proven track record in obtaining commercial licenses, food permits, and fire safety approvals in Kuwait.\n4. Strong relationships with relevant Kuwait government authorities preferred.\n5. Bilingual in Arabic and English; Chinese is a plus.","description":"部门介绍\n美团的使命是“帮大家吃得更好，生活更好”，公司聚焦“零售 + 科技”战略，和广大商户与各类合作伙伴一起，努力为消费者提供品质生活，推动商品零售和服务零售在需求侧和供给侧的数字化转型。\n2018年9月20日，美团正式在港交所挂牌上市。美团将始终坚持以客户为中心，不断加大在科技研发方面的投入，更好承担社会责任，更多创造社会价值，与广大合作伙伴一起发展共赢。\n\n岗位职责\n1. License & Permit Management: Lead end-to-end store license applications in Kuwait, including municipal, commercial, food safety, fire safety, and signage permits. Ensure all stores maintain valid documentation.\n2. Government Relations: Build relationships with Kuwait authorities (Municipality, MOCI, Fire Force, PAFN). Track regulatory changes and assess impact on operations.\n3. Compliance Tracking: Maintain a compliance system to monitor license status and expiry.\n4. New Store Support: Coordinate with engineering and operations to secure all permits before store launch; Manage the critical path to avoid opening delays.\n5. Risk & Inspection Management: Handle government inspections and violation notices. Implement corrective actions to minimize penalties and disruptions.\n\n岗位基本要求\n1. Bachelor's degree or above; quick commerce or retail chain experience preferred.\n2. 3+ years in license/permit management in Kuwait, familiar with local municipal, commercial, and food safety regulations.\n3. Proven track record in obtaining commercial licenses, food permits, and fire safety approvals in Kuwait.\n4. Strong relationships with relevant Kuwait government authorities preferred.\n5. Bilingual in Arabic and English; Chinese is a plus.\n\n岗位亮点\nInnovative retail project, growing rapidly; join a team full of energy and focused on results, with broad career development opportunities.","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4631567557","sourceKey":"meituan_social","company":"美团","title":"营销增长算法专家","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4631567557&jobShareType=1","duty":"1. 负责美团骑行用户运营核心业务，包括算法驱动的用户增长预测、营销补贴、套餐卡券推荐排序等。  \n2. 设计和优化用户智能营销算法，提升多种营销场景的补贴效率，驱动用户规模与业务收入的双重增长。  \n3. 与用户运营、产品团队紧密合作，从复杂业务逻辑中抽象问题并进行建模优化，推动全链路解决方案的落地。  \n4. 结合GenAI、因果推断等前沿理论和业界实践，解决骑行营销场景中的“选、估、售”难题。","requirements":"1. 硕士研究生及以上学历，计算机、数学、统计学等相关专业。  \n2. 4年以上算法策略相关工作经验，熟悉推荐/广告出价、深度学习序列建模或因果推断等方向。  \n3. 熟悉用户智能营销算法体系，对套餐卡推荐排序、补贴算法、动态定价等有深入理解。  \n4. 具备良好的数据敏感度和业务理解能力，能独立推动项目闭环。","description":"部门介绍\n美团的使命是“帮大家吃得更好，生活更好”，公司聚焦“零售 + 科技”战略，和广大商户与各类合作伙伴一起，努力为消费者提供品质生活，推动商品零售和服务零售在需求侧和供给侧的数字化转型。\n2018年9月20日，美团正式在港交所挂牌上市。美团将始终坚持以客户为中心，不断加大在科技研发方面的投入，更好承担社会责任，更多创造社会价值，与广大合作伙伴一起发展共赢。\n\n岗位职责\n1. 负责美团骑行用户运营核心业务，包括算法驱动的用户增长预测、营销补贴、套餐卡券推荐排序等。  \n2. 设计和优化用户智能营销算法，提升多种营销场景的补贴效率，驱动用户规模与业务收入的双重增长。  \n3. 与用户运营、产品团队紧密合作，从复杂业务逻辑中抽象问题并进行建模优化，推动全链路解决方案的落地。  \n4. 结合GenAI、因果推断等前沿理论和业界实践，解决骑行营销场景中的“选、估、售”难题。\n\n岗位基本要求\n1. 硕士研究生及以上学历，计算机、数学、统计学等相关专业。  \n2. 4年以上算法策略相关工作经验，熟悉推荐/广告出价、深度学习序列建模或因果推断等方向。  \n3. 熟悉用户智能营销算法体系，对套餐卡推荐排序、补贴算法、动态定价等有深入理解。  \n4. 具备良好的数据敏感度和业务理解能力，能独立推动项目闭环。\n\n具备以下条件优先\n（1）在强化学习、可解释性推荐、运筹优化、BML等领域有经验者优先； \n（2）关注前沿算法迭代并有自己总结思考、善于复盘者优先。 \n（3）近三年在机器学习、数据挖掘顶级会议/期刊产出过论文者优先。\n\n岗位亮点\n1. 业务规模大：亿级真实用户，覆盖用户理解、推卡排序、营销转化、增长留存的全过程算法触点场景。  \n2. 战略级定位：参与公司S级项目，目标空间大，协同资源丰富，个人业务与技术成长路径清晰。  \n3. 技术前沿：探索并推动大模型在策略生成、用户洞察等场景的应用落地，提升研发效率。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4551964979","sourceKey":"meituan_social","company":"美团","title":"战略研究专家","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4551964979&jobShareType=1","duty":"1、跟踪行业发展动态：围绕食杂零售行业搭建调研跟踪体系，获得可靠信息输入并进行细化甄别，持续拓宽市场竞争信息与社零大盘的信息获取渠道，提高数据的及时性、丰富度与可信度。\n2、战略性课题研究：基于持续的竞争跟踪，开展战略性课题研究，就零售行业的通用规律、国内外零售业的发展轨迹、行业竞争格局趋势、公司竞争优劣势、核心竞争力构建路径等战略性要素给出深刻洞察、给予管理层和业务有价值的决策建议。\n3、零售行业研究：对于零售各细分市场的观察与解读，捕捉对产业发展趋势具有实质性影响的认知。帮助管理层及时了解市场动向。","requirements":"1、对商业和业务逻辑敏感，具备良好的结构化思维与严密的逻辑推理能力，能从发现商业价值并深度思考，最终通过数据归纳总结与沟通呈现\n2、具备快速学习能力，目标导向，具备良好的跨团队沟通协同和项目落地推行能力\n3.加分项：\n具备较好的自主学习能力，对AI新技术抱有浓厚兴趣，乐于探索AI可能性；\n熟练使用 AI 工具（如大模型对话、AI 搜索、智能分析平台等）辅助研究工作，在实际项目中有明确的效率提升实践。","description":"部门介绍\n美团的使命是“帮大家吃得更好，生活更好”，公司聚焦“零售 + 科技”战略，和广大商户与各类合作伙伴一起，努力为消费者提供品质生活，推动商品零售和服务零售在需求侧和供给侧的数字化转型。\n2018年9月20日，美团正式在港交所挂牌上市。美团将始终坚持以客户为中心，不断加大在科技研发方面的投入，更好承担社会责任，更多创造社会价值，与广大合作伙伴一起发展共赢。\n\n岗位职责\n1、跟踪行业发展动态：围绕食杂零售行业搭建调研跟踪体系，获得可靠信息输入并进行细化甄别，持续拓宽市场竞争信息与社零大盘的信息获取渠道，提高数据的及时性、丰富度与可信度。\n2、战略性课题研究：基于持续的竞争跟踪，开展战略性课题研究，就零售行业的通用规律、国内外零售业的发展轨迹、行业竞争格局趋势、公司竞争优劣势、核心竞争力构建路径等战略性要素给出深刻洞察、给予管理层和业务有价值的决策建议。\n3、零售行业研究：对于零售各细分市场的观察与解读，捕捉对产业发展趋势具有实质性影响的认知。帮助管理层及时了解市场动向。\n\n岗位基本要求\n1、对商业和业务逻辑敏感，具备良好的结构化思维与严密的逻辑推理能力，能从发现商业价值并深度思考，最终通过数据归纳总结与沟通呈现\n2、具备快速学习能力，目标导向，具备良好的跨团队沟通协同和项目落地推行能力\n3.加分项：\n具备较好的自主学习能力，对AI新技术抱有浓厚兴趣，乐于探索AI可能性；\n熟练使用 AI 工具（如大模型对话、AI 搜索、智能分析平台等）辅助研究工作，在实际项目中有明确的效率提升实践。\n\n具备以下条件优先\n消费及零售经验、扎实的行业研究功底\n\n岗位亮点\n1、完善的岗位培养及有吸引力的上升路径\n2、非常具有前景的增长型行业\n3、具备包容性与创新性的大平台支撑","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4630881436","sourceKey":"meituan_social","company":"美团","title":"生鲜供应链品控（果蔬）","city":"济南市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4630881436&jobShareType=1","duty":"1.负责小象超市生鲜供应链环节商品及供应商质量管理，从源头到餐桌，预防和优化商品质量问题，提升用户满意度；\n2.负责商品验收，存储，包装，配送过程中的质量检测和标准落地，减少各环节的商品质量问题发生；\n3.负责跟踪解决出现的商品（特别是生鲜产品）质量问题，避免商品质量问题重复出现，影响用户体验；\n4.负责与采购/客服/品质标准组等相关横向部门配合，解决商品品质异常及潜在食品安全风险。","requirements":"1.大专以上学历，2年以上零售质量管理经验、或供应链质量管理经验、或门店商品质量运营管理\n2.具备跨部门的高效沟通及协作能力，能快速推进项目落地；\n3.诚信、正直、责任心及上进心强。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1.负责小象超市生鲜供应链环节商品及供应商质量管理，从源头到餐桌，预防和优化商品质量问题，提升用户满意度；\n2.负责商品验收，存储，包装，配送过程中的质量检测和标准落地，减少各环节的商品质量问题发生；\n3.负责跟踪解决出现的商品（特别是生鲜产品）质量问题，避免商品质量问题重复出现，影响用户体验；\n4.负责与采购/客服/品质标准组等相关横向部门配合，解决商品品质异常及潜在食品安全风险。\n\n岗位基本要求\n1.大专以上学历，2年以上零售质量管理经验、或供应链质量管理经验、或门店商品质量运营管理\n2.具备跨部门的高效沟通及协作能力，能快速推进项目落地；\n3.诚信、正直、责任心及上进心强。\n\n岗位亮点\n加入快速发展的即时零售平台，参与生鲜品控核心环节\n\n可在多个一二线城市拓展城市品控管理经验","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:2035103427","sourceKey":"meituan_social","company":"美团","title":"中小发西北大区-产品销售","city":"酒泉市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=2035103427&jobShareType=1","duty":"1．通过销售拜访，了解商户的业务现状与实际需求并结合消费者的消费动向，制定个性化营销方案，与商户谈判并达成合作；\n2．执行公司的销售策略及政策，达成业绩目标；\n3．与公司各部门配合，及时处理用户的反馈、投诉和建议，提高用户满意度；\n4．归档和更新所有目标商户拜访、协议、服务条款等有关的文件和数据，确保信息在数据库中得到正确的维护。","requirements":"1．大专及以上学历，有销售工作经验优先。可接受优秀应届毕业生；\n2．有很强的学习能力和适应能力，适应互联网行业的快速发展；\n3．具备较强的人际沟通及逻辑思维能力，思维敏捷，能够准确把握产品优势和客户心理，高效整合内外部资源促成销售业绩；\n4．富有激情和创新理念，追求个人职业发展和公司利益的双赢；\n5．热爱销售，善于挑战，积极乐观，有强烈的成功欲望和企图心；\n6．为人正直，诚实可靠，以公司利益为重。","description":"部门介绍\n美团服务零售事业部下设乐生活业务部、易生活业务部、进场零售业务部以及中小城市发展部四大业务部门，旨在通过提供丰富、可靠、实惠的服务与商品满足用户各类生活需求。我们所处的服务零售行业是一个具有万亿规模的市场，覆盖足疗洗浴、酒吧KTV、运动健身、美发美甲、教育培训、亲子游乐、家政洗涤维修、摄影写真等数十个服务消费细分领域，同时延伸至超市便利、美妆个护、3C数码、服饰珠宝、运动户外、商场购物中心等实体零售到店消费场景，连接数十万品牌商户与线下门店。作为商家和行业的小帮手，我们持续深入服务零售与实体零售产业链，用AI等技术推动行业变革，帮助商家提升经营效率、实现高效的线上化经营与到店转化，优化消费者服务体验，提供安心、放心的履约保障。这里有着多元的业务布局，有着富有挑战和影响力的工作内容，为你提供丰富的视野、持续的成长和发展机会，引领你发现更多可能。期待和你在“随时随地，美好生活”的愿景指引下，共建美好的生活服务体验、健康的商家生态与高质量的经营结果。\n\n岗位职责\n1．通过销售拜访，了解商户的业务现状与实际需求并结合消费者的消费动向，制定个性化营销方案，与商户谈判并达成合作；\n2．执行公司的销售策略及政策，达成业绩目标；\n3．与公司各部门配合，及时处理用户的反馈、投诉和建议，提高用户满意度；\n4．归档和更新所有目标商户拜访、协议、服务条款等有关的文件和数据，确保信息在数据库中得到正确的维护。\n\n岗位基本要求\n1．大专及以上学历，有销售工作经验优先。可接受优秀应届毕业生；\n2．有很强的学习能力和适应能力，适应互联网行业的快速发展；\n3．具备较强的人际沟通及逻辑思维能力，思维敏捷，能够准确把握产品优势和客户心理，高效整合内外部资源促成销售业绩；\n4．富有激情和创新理念，追求个人职业发展和公司利益的双赢；\n5．热爱销售，善于挑战，积极乐观，有强烈的成功欲望和企图心；\n6．为人正直，诚实可靠，以公司利益为重。\n\n岗位亮点\n1.能够与下沉市场生活服务行业中小商户深度沟通，运用专业帮他们经营更好； 2.年轻团队、富有活力，入职即有师傅带教，将获得运营、销售、沟通等技能的专人辅导 3.发展空间大，向上可晋升至管理岗。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4473665927","sourceKey":"meituan_social","company":"美团","title":"具身整机工艺/新产品导入NPI工程师","city":"深圳市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4473665927&jobShareType=1","duty":"1. 主导具身新产品从 EVT → DVT → PVT → MP 各阶段的组装工艺开发及新产品导入的工作；\n2. 对整机结构方案进行可制造性（DFM）和评估，输出问题点清单与改善建议；\n3. 搭建及优化整机组装工位，包括设备选型、夹治具需求、工位布局、自动化引入评估等；\n4. 主导试产过程中的工艺异常问题分析和解决，保证问题不重犯；\n5. 建立新产品工艺文件（SOP/关键工序清单/辅料清单等），完成工艺标准向后端生产制造/维护团队的交接；\n6. 主动探索并运用各类AI工具优化日常工作流程，积极推动AI在业务场景中的落地实践，持续提升个人及团队的工作效率与产出质量。","requirements":"1. 本科及以上学历，机械、力学、材料或相关专业；\n2. 3年及以上消费电子整机工艺/新产品导入经验，有头戴式运动相机、VR、AR、具身智能、摄像头等感知模组相关产品经验者优先；\n3. 对常见的精密压合、螺丝锁附、点胶工艺、背胶粘接等工艺有深刻的理解；\n4. 具备先产品从立项到量产的全生命周期开发经验，熟悉新产品导入流程；\n5. 具备主动学习与探索AI新工具、新方法的意识，能持续将AI能力融入实际工作场景并独立落地；\n6. 对AI工具有实际使用经验，能清晰阐述利用AI解决复杂问题的思路与方法，保持对AI前沿趋势的敏感度。","description":"部门介绍\n为了更好地提升城市即时配送的效率与体验，2017年，美团启动了无人机配送服务的探索，通过科技创新推动履约工具变革，加快建设空地协同的本地即时配送网络。\n在过去的六年里，美团无人机完成了飞行器、自动化机场及智能调度系统的研发工作，实现了研发设计、生产制造、运营运维全链条布局，达成了城市复杂场景物流无人机高频次、高密度、多天时、多天侯运行。\n2023年7月，美团无人机在上海发布了自主研发的第四代无人机，跟此前机型相比，新机型升级了环境适应能力，可在“零下20度至50度”的中雨、中雪、6级风、弱光等环境中稳定飞行，能够适应97%以上国内城市的自然环境要求。\n截至2024年12月，美团无人机已在深圳、北京、上海、广州、南京、迪拜等城市开通53条航线，并累计完成订单超40万单。即时零售配送服务覆盖了办公、社区、景区、市政公园、校园、医疗、图书馆等多种场景。在医疗场景中，美团无人机可围绕医疗血液、检验样本、院前急救物资、特殊药品等医疗物资配送需求建设端到端的全天时急送网络。\n\n岗位职责\n1. 主导具身新产品从 EVT → DVT → PVT → MP 各阶段的组装工艺开发及新产品导入的工作；\n2. 对整机结构方案进行可制造性（DFM）和评估，输出问题点清单与改善建议；\n3. 搭建及优化整机组装工位，包括设备选型、夹治具需求、工位布局、自动化引入评估等；\n4. 主导试产过程中的工艺异常问题分析和解决，保证问题不重犯；\n5. 建立新产品工艺文件（SOP/关键工序清单/辅料清单等），完成工艺标准向后端生产制造/维护团队的交接；\n6. 主动探索并运用各类AI工具优化日常工作流程，积极推动AI在业务场景中的落地实践，持续提升个人及团队的工作效率与产出质量。\n\n岗位基本要求\n1. 本科及以上学历，机械、力学、材料或相关专业；\n2. 3年及以上消费电子整机工艺/新产品导入经验，有头戴式运动相机、VR、AR、具身智能、摄像头等感知模组相关产品经验者优先；\n3. 对常见的精密压合、螺丝锁附、点胶工艺、背胶粘接等工艺有深刻的理解；\n4. 具备先产品从立项到量产的全生命周期开发经验，熟悉新产品导入流程；\n5. 具备主动学习与探索AI新工具、新方法的意识，能持续将AI能力融入实际工作场景并独立落地；\n6. 对AI工具有实际使用经验，能清晰阐述利用AI解决复杂问题的思路与方法，保持对AI前沿趋势的敏感度。\n\n岗位亮点\n1. 具身智能、机器人等前沿领域\n2. 大数据/AI等前沿领域","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4608003073","sourceKey":"meituan_social","company":"美团","title":"深圳供应链品控主管","city":"深圳市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4608003073&jobShareType=1","duty":"1. 负责小象超市生鲜的供应链环节的商品及供应商质量标准建设和完善，从源头到餐桌，预防和优化商品质量问题，提升用户满意度；\n2. 负责质量监督团队的招募、培训和人员绩效管理，快速搭建质量管理监控体系，输出质量改善建议，推动质量改善；\n3. 负责商品收货、存储、包装、配送过程中的质量检测和标准落地，减少各环节的商品质量问题发生；\n4. 负责跟踪解决出现的商品（特别是生鲜产品）质量问题，避免商品质量问题重复出现及影响用户体验；\n5. 负责和法务、GR、品质标准组同时配合，解决突发的食品安全问题，降低食品安全风险；\n6.需要出差产地进行前置生鲜商品品质识别、验收。","requirements":"1. 本科以上学历，2年以上商超零售质量管理经验或供应链质量管理经验；\n2. 具备很强的跨部门沟通表达及协作能力，能快速推进项目落地；\n3. 有极强的责任心，自驱性强；\n4. 具备正直诚信的价值观，有较强的原则性。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1. 负责小象超市生鲜的供应链环节的商品及供应商质量标准建设和完善，从源头到餐桌，预防和优化商品质量问题，提升用户满意度；\n2. 负责质量监督团队的招募、培训和人员绩效管理，快速搭建质量管理监控体系，输出质量改善建议，推动质量改善；\n3. 负责商品收货、存储、包装、配送过程中的质量检测和标准落地，减少各环节的商品质量问题发生；\n4. 负责跟踪解决出现的商品（特别是生鲜产品）质量问题，避免商品质量问题重复出现及影响用户体验；\n5. 负责和法务、GR、品质标准组同时配合，解决突发的食品安全问题，降低食品安全风险；\n6.需要出差产地进行前置生鲜商品品质识别、验收。\n\n岗位基本要求\n1. 本科以上学历，2年以上商超零售质量管理经验或供应链质量管理经验；\n2. 具备很强的跨部门沟通表达及协作能力，能快速推进项目落地；\n3. 有极强的责任心，自驱性强；\n4. 具备正直诚信的价值观，有较强的原则性。\n\n具备以下条件优先\n1.热爱互联网和新零售行业，具有极强的快速学习能力；\n2.有较强的质量管理方法论且可以快速结合业务特点落地能力。\n\n岗位亮点\n1.了解生鲜商品全链条品质管理过程，与各团队一起提升客户品质体验；\n2.制定互联网生鲜板块的相关行业标准。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4377993940","sourceKey":"meituan_social","company":"美团","title":"快驴财务-销售财务BP","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4377993940&jobShareType=1","duty":"1. 深入了解餐饮供应链to B销售业务，与业务伙伴密切合作，建立合理有效的分析体系，参与所支持业务的决策过程，包括但不限于销售收入、销售效率、客户增长、营销补贴等，并建立规范的财务模型；\n2. 按期出具多维度的财务分析报告，分析和挖掘相关业务表现，结合业务特点制定关键业务指标及分析体系，给予有效建议并推进解决方案，深度支持业务决策和过程管理；\n3. 准确编制对应业务的财务预测及年度预算，执行预算实际分析，并协助业务进行预算管理，监督业务在预算范围内完成目标；\n4. 推进流程优化，提升管理效率，降低流程风险。\n5.AI驱动效率提升：积极引入AI工具参与管理报表编制、数据分析框架建设及可视化工具搭建，推动财务数字化与智能化升级。","requirements":"1. 3年以上销售财务分析经验，5年以上财务分析经验； \n2. 具有高度责任责任感和较强的团队合作意识； \n3. 较好的学习能力和数据能力、清晰的思维逻辑和创新意识； \n4. 良好的组织、协调、项目推动和沟通能力。\n5.具备AI工具应用意识，能借助AI辅助工具（如大模型、智能数据处理工具等）提升营销数据分析和报告产出效率。","description":"部门介绍\n财务平台负责公司整体和各业务层面的财务管理工作，通过建设专业、全面、复合的财务管理能力和与业务经营的紧密结合来支持公司健康发展。目前财务平台拥有财务会计、财务报告、资金管理、税务管理、财务共享、财务系统、规划分析、财务BP和内控内审等主要工作方向。我们的目标是建设业界一流的财务管理能力和经营支持体系，为公司战略的正确落地、投入效率的持续提升、业务价值的不断增长保驾护航。欢迎加入财务平台，携手一起向未来！\n\n岗位职责\n1. 深入了解餐饮供应链to B销售业务，与业务伙伴密切合作，建立合理有效的分析体系，参与所支持业务的决策过程，包括但不限于销售收入、销售效率、客户增长、营销补贴等，并建立规范的财务模型；\n2. 按期出具多维度的财务分析报告，分析和挖掘相关业务表现，结合业务特点制定关键业务指标及分析体系，给予有效建议并推进解决方案，深度支持业务决策和过程管理；\n3. 准确编制对应业务的财务预测及年度预算，执行预算实际分析，并协助业务进行预算管理，监督业务在预算范围内完成目标；\n4. 推进流程优化，提升管理效率，降低流程风险。\n5.AI驱动效率提升：积极引入AI工具参与管理报表编制、数据分析框架建设及可视化工具搭建，推动财务数字化与智能化升级。\n\n岗位基本要求\n1. 3年以上销售财务分析经验，5年以上财务分析经验； \n2. 具有高度责任责任感和较强的团队合作意识； \n3. 较好的学习能力和数据能力、清晰的思维逻辑和创新意识； \n4. 良好的组织、协调、项目推动和沟通能力。\n5.具备AI工具应用意识，能借助AI辅助工具（如大模型、智能数据处理工具等）提升营销数据分析和报告产出效率。\n\n岗位亮点\n1. 市场潜力空间巨大，业务高速发展期间，财务可发挥空间大；\n2. 业务团队财务意识强，高度认可财务对于业务的支持价值，配合度高。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4626426410","sourceKey":"meituan_social","company":"美团","title":"美团评价策略运营","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4626426410&jobShareType=1","duty":"1. 深入洞察美团本地生活不同业务的用户看评场景，通过对用户看评诉求分析及本地生活各行业的决策特征理解，制定行业的有用性标准与标签体系，提升评价内容的真实性、丰富度及对用户的决策参考价值。\n\n2. 通过用户行为分析及体感洞察，精准定位用户在选店决策路径中的痛点，针对评价排序、双端（美团/点评）供给差异等场景进行分析下探，抽象业务规则，推动算法模型迭代，并验证策略上线后的增量价值。\n\n3. 结合AI/大模型能力探索评价智能化方向，推动AI辅助内容理解、智能总结、效果归因等链路的产品化落地，评估AI应用对运营效率与用户体验的实际提升效果。  \n\n4. 作为业务与算法、产品、运营等多团队之间的桥梁，在模糊的业务场景中高效推动策略落地，建立策略实验与效果评估的标准化闭环，通过持续迭代验证策略有效性。","requirements":"1. 3年以上内容平台、搜索、推荐或评价体系的策略运营/产品经理经验，熟悉流量分发、排序权重调优及内容相关性、真实性等核心策略逻辑，有评价/内容生态相关经验者优先。\n\n2. 兼具良好的数据分析和用户洞察能力，对指标含义、用户价值、行业价值有足够的思考和理解，能从千万级用户行为数据中抽象出产品策略，能够敏锐洞察用户价值与行业差异，并将其转化为可量化的策略指标。\n\n3. 对AI在内容理解、智能交互等场景的应用有实践或深度思考，能够快速理解AI技术边界并找到与业务场景的结合点。\n\n4. 具备较强的跨团队沟通协作能力和项目推动力，对本地生活行业有基本认知，能从用户视角判断策略价值，在用户体验、商户价值与平台生态之间找到平衡点。","description":"部门介绍\n美团平台为用户的基础产品体验负责，还承担了美团的用户增长、市场和品牌营销以及多条业务线的产品设计职责，建立了融合文字、图片、视频和直播等不同形式的內容生态系统，同时整合地图服务部、客户服务和体验部、企业业务部、网约车业务部等部门，致力于用科技提升美团数亿消费者、近千万商家、骑手、司机和团长的服务体验。美团平台拥有高并发、多业务的复杂场景，为技术深度优化提供了最佳实践可能。这里有简单、讲逻辑、有爱的团队，更是一块理想的实战场地，舞台广阔，欢迎你来尽情施展。\n\n岗位职责\n1. 深入洞察美团本地生活不同业务的用户看评场景，通过对用户看评诉求分析及本地生活各行业的决策特征理解，制定行业的有用性标准与标签体系，提升评价内容的真实性、丰富度及对用户的决策参考价值。\n\n2. 通过用户行为分析及体感洞察，精准定位用户在选店决策路径中的痛点，针对评价排序、双端（美团/点评）供给差异等场景进行分析下探，抽象业务规则，推动算法模型迭代，并验证策略上线后的增量价值。\n\n3. 结合AI/大模型能力探索评价智能化方向，推动AI辅助内容理解、智能总结、效果归因等链路的产品化落地，评估AI应用对运营效率与用户体验的实际提升效果。  \n\n4. 作为业务与算法、产品、运营等多团队之间的桥梁，在模糊的业务场景中高效推动策略落地，建立策略实验与效果评估的标准化闭环，通过持续迭代验证策略有效性。\n\n岗位基本要求\n1. 3年以上内容平台、搜索、推荐或评价体系的策略运营/产品经理经验，熟悉流量分发、排序权重调优及内容相关性、真实性等核心策略逻辑，有评价/内容生态相关经验者优先。\n\n2. 兼具良好的数据分析和用户洞察能力，对指标含义、用户价值、行业价值有足够的思考和理解，能从千万级用户行为数据中抽象出产品策略，能够敏锐洞察用户价值与行业差异，并将其转化为可量化的策略指标。\n\n3. 对AI在内容理解、智能交互等场景的应用有实践或深度思考，能够快速理解AI技术边界并找到与业务场景的结合点。\n\n4. 具备较强的跨团队沟通协作能力和项目推动力，对本地生活行业有基本认知，能从用户视角判断策略价值，在用户体验、商户价值与平台生态之间找到平衡点。\n\n具备以下条件优先\n1. 有评价/评论领域 或 大型本地生活平台 相关经验\n\n2. 主导或深度参与过 AI 赋能产品的全链路尝试\n\n岗位亮点\n1. 这是一个深度参与评价业务核心策略的岗位，你将直接负责评价体系的策略设计与效果优化，驱动用户评价行为和内容生态的健康发展。\n\n2. 评价是用户消费决策中最关键的信任资产之一，你将有机会重新定义“什么是高质量评价”，通过精细化策略运营，提升评价内容的质量和可信度，让优质评价更好地服务用户决策。\n\n3. 岗位横跨用户、商户、审核治理、算法分发等多个关键环节，能够完整锻炼平台型产品的系统设计和跨团队推动能力。\n\n4. 这是一个非常适合结合 AI 提效的场景，内容理解、智能总结、效果归因等链路都有大量 AI 工具赋能运营效率的创新空间。 \n\n5. 你将面对真实的大规模用户场景，产出的策略能力可以被上亿用户使用，并直接影响用户体验、交易效率和平台生态健康度。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4564887702","sourceKey":"meituan_social","company":"美团","title":"东南进向分拨中心负责人","city":"杭州市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4564887702&jobShareType=1","duty":"1.负责分拨中心的日常运营管理工作，包括收货、分拣、出库、转运管理等，确保分拨中心运作顺畅。\n2.负责制定并执行分拨中心的作业流程和标准操作规范，提高工作效率和准确性。\n3.负责团队的日常管理和指导，培训新员工，提升团队整体素质。\n4.负责分拨中心设备的维护和保养，确保设备正常运转。\n5.协调内部各部门，保障分拨运营的顺利进行。","requirements":"1、三年物流公司分拨管理经验，有同行业生鲜物流分拨中心管理工作经验优先。\n2、较强的现场管理能力，对人机料法环的作业管理有较好的沉淀，能够推动团队达成团队目标，不断追求卓越。\n3、年轻有潜力。","description":"部门介绍\n快驴进货是美团旗下的餐饮供应链平台，帮助餐饮商户以更低成本、更高效率来获取安全可靠的食材供应，让餐饮采购更简单。快驴进货同步发展“自营+平台”的业务模式，在采购环节一方面向上游供应商直采大宗商品，另一方面引入各地批发商，助力平台伙伴共同发展；在销售环节既有自建团队进行市场、客户拓展，又帮助各地批发商拓展业务；同时自建仓储管理系统、配送网络与团队，为客户提供优质履约服务。\n截至2022年，快驴进货布局了全国41个城市，为百万家商户提供“全、省、稳、好”的餐饮供应链服务。我们拥有3000+品牌食材、超5万SKU商品、超28万商品资质，并提供源头严审核、食品安全严把关、24小时无忧售后的全面保障，实现手机下单、送货上门的高效采购模式，帮百万商家节省了采购时间与成本，助力平台伙伴共同发展，在万亿市场共享机遇。\n在这里，你将收获完善的员工发展机制及学习体系，与各界专家一起深度参与餐饮供应链业务的发展。欢迎优秀的你加入美团快驴进货，与我们一起成长，一起更好！\n\n岗位职责\n1.负责分拨中心的日常运营管理工作，包括收货、分拣、出库、转运管理等，确保分拨中心运作顺畅。\n2.负责制定并执行分拨中心的作业流程和标准操作规范，提高工作效率和准确性。\n3.负责团队的日常管理和指导，培训新员工，提升团队整体素质。\n4.负责分拨中心设备的维护和保养，确保设备正常运转。\n5.协调内部各部门，保障分拨运营的顺利进行。\n\n岗位基本要求\n1、三年物流公司分拨管理经验，有同行业生鲜物流分拨中心管理工作经验优先。\n2、较强的现场管理能力，对人机料法环的作业管理有较好的沉淀，能够推动团队达成团队目标，不断追求卓越。\n3、年轻有潜力。\n\n具备以下条件优先\n愿意接受大区内部调动和安排\n\n岗位亮点\n1.夯实对仓储成本的深入管控，带领团队迎接效率与成本的综合考验；\n2.在早期加入生鲜B2B电商领域，与来自电商、物流和商超的精英同仁一同努力，构建供给侧的数字化与智能化。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4588591377","sourceKey":"meituan_social","company":"美团","title":"设备物资主管-上海","city":"上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4588591377&jobShareType=1","duty":"日常管理包括片区内负责仓库输送线维保维养包括生产陪产和日常养护，物资申请配置、验收入库、物资存储、物资日常养护、物资维修、物资报废、消耗品日常管理、物资盘点、库存分析与预警以及能耗管理。\n1.生产陪产涉及生产前设备巡查、生产中及时处理设备异常、生产结束后解决无法在生产过程中处理的异常，确保生产运营顺利进行。\n2.日常养护包括制定维养频率、管理设备配件、建立管理台账、处理配件申请与报废工作，确保配件数量合理充足，并在设备质保期内与厂家沟通，确保技术标准统一。\n3.物资申请配置需进行需求分析、遵循配置标准、规范执行申请流程并管理台账。\n4.验收入库涉及到货信息核验、质量检验、系统数据录入及异常问题处理。\n5.物资存储要求设置功能分区并进行精细化运营。\n6.物资日常养护包括制定养护计划、环境监测与调节、物资检查与维护及养护记录与分析。\n7.物资维修需进行故障诊断与评估、协调维修资源、检验维修质量及管理维修台账。\n8.物资报废按照标准检查并申请。\n9.消耗品日常管理包括物资盘点、差异分析处理及提交盘点报告。\n10.水电能耗管理涉及相关操作。","requirements":"1.大专学历、机电一体化、电气类相关专业、持电工证；\n2.两年以上相关设备维护与保养相关经验，能独立分析设备故障原因并排除，具有物流、快递行业（（皮带机、爬坡机、转弯机等)等分拣设备维保工作经验；\n3.有较强的安全意识，具有较强的责任心、吃苦耐劳、品行端正、无不良嗜好，能接受长期晚班。\n4.掌握基本的AI工具，使用工具提升工作流程效率","description":"部门介绍\n快驴进货是美团旗下的餐饮供应链平台，帮助餐饮商户以更低成本、更高效率来获取安全可靠的食材供应，让餐饮采购更简单。快驴进货同步发展“自营+平台”的业务模式，在采购环节一方面向上游供应商直采大宗商品，另一方面引入各地批发商，助力平台伙伴共同发展；在销售环节既有自建团队进行市场、客户拓展，又帮助各地批发商拓展业务；同时自建仓储管理系统、配送网络与团队，为客户提供优质履约服务。\n截至2022年，快驴进货布局了全国41个城市，为百万家商户提供“全、省、稳、好”的餐饮供应链服务。我们拥有3000+品牌食材、超5万SKU商品、超28万商品资质，并提供源头严审核、食品安全严把关、24小时无忧售后的全面保障，实现手机下单、送货上门的高效采购模式，帮百万商家节省了采购时间与成本，助力平台伙伴共同发展，在万亿市场共享机遇。\n在这里，你将收获完善的员工发展机制及学习体系，与各界专家一起深度参与餐饮供应链业务的发展。欢迎优秀的你加入美团快驴进货，与我们一起成长，一起更好！\n\n岗位职责\n日常管理包括片区内负责仓库输送线维保维养包括生产陪产和日常养护，物资申请配置、验收入库、物资存储、物资日常养护、物资维修、物资报废、消耗品日常管理、物资盘点、库存分析与预警以及能耗管理。\n1.生产陪产涉及生产前设备巡查、生产中及时处理设备异常、生产结束后解决无法在生产过程中处理的异常，确保生产运营顺利进行。\n2.日常养护包括制定维养频率、管理设备配件、建立管理台账、处理配件申请与报废工作，确保配件数量合理充足，并在设备质保期内与厂家沟通，确保技术标准统一。\n3.物资申请配置需进行需求分析、遵循配置标准、规范执行申请流程并管理台账。\n4.验收入库涉及到货信息核验、质量检验、系统数据录入及异常问题处理。\n5.物资存储要求设置功能分区并进行精细化运营。\n6.物资日常养护包括制定养护计划、环境监测与调节、物资检查与维护及养护记录与分析。\n7.物资维修需进行故障诊断与评估、协调维修资源、检验维修质量及管理维修台账。\n8.物资报废按照标准检查并申请。\n9.消耗品日常管理包括物资盘点、差异分析处理及提交盘点报告。\n10.水电能耗管理涉及相关操作。\n\n岗位基本要求\n1.大专学历、机电一体化、电气类相关专业、持电工证；\n2.两年以上相关设备维护与保养相关经验，能独立分析设备故障原因并排除，具有物流、快递行业（（皮带机、爬坡机、转弯机等)等分拣设备维保工作经验；\n3.有较强的安全意识，具有较强的责任心、吃苦耐劳、品行端正、无不良嗜好，能接受长期晚班。\n4.掌握基本的AI工具，使用工具提升工作流程效率\n\n具备以下条件优先\n有仓库输送线维保维养包括生产陪产和日常养护知识及电工证优先考虑\n\n岗位亮点\n快速发展的互联网业务，发展空间大，良好的团队氛围，挑战和成长机会多","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3548786059","sourceKey":"meituan_social","company":"美团","title":"快驴小B华南大区-BDM","city":"广州市/深圳市/东莞市/佛山市/中山市/珠海市/江门市/惠州市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3548786059&jobShareType=1","duty":"1. 目标管理：合理的规划及分解目标，并带领团队完成业绩指标\n2. 负责所属区域BD人员的招募、选拔、留用、培养、关怀、考核工作，通过团队拿到结果；\n3. 过程管理：销售日常数据分析及监控，夯实销售过程\n4. 培训管理：不定期开展团队销售技巧培训、产品知识及情景演练，快速提升销售水平\n5. 团队建设：营造积极向上的竞争环境，适度开展团建，保持团队稳定性","requirements":"1. 一年以上销售管理经验；\n2. 热爱销售，对互联网公司兴趣强烈；\n3. 注重长远职业发展，有强烈的晋升欲望；\n4. 学习能力强且勤奋努力，吃苦耐劳，执行力强，有较强的进取心;\n5. 精力充沛，具备在压力下出色完成任务的能力。","description":"部门介绍\n快驴进货是美团旗下的餐饮供应链平台，帮助餐饮商户以更低成本、更高效率来获取安全可靠的食材供应，让餐饮采购更简单。快驴进货同步发展“自营+平台”的业务模式，在采购环节一方面向上游供应商直采大宗商品，另一方面引入各地批发商，助力平台伙伴共同发展；在销售环节既有自建团队进行市场、客户拓展，又帮助各地批发商拓展业务；同时自建仓储管理系统、配送网络与团队，为客户提供优质履约服务。\n截至2022年，快驴进货布局了全国41个城市，为百万家商户提供“全、省、稳、好”的餐饮供应链服务。我们拥有3000+品牌食材、超5万SKU商品、超28万商品资质，并提供源头严审核、食品安全严把关、24小时无忧售后的全面保障，实现手机下单、送货上门的高效采购模式，帮百万商家节省了采购时间与成本，助力平台伙伴共同发展，在万亿市场共享机遇。\n在这里，你将收获完善的员工发展机制及学习体系，与各界专家一起深度参与餐饮供应链业务的发展。欢迎优秀的你加入美团快驴进货，与我们一起成长，一起更好！\n\n岗位职责\n1. 目标管理：合理的规划及分解目标，并带领团队完成业绩指标\n2. 负责所属区域BD人员的招募、选拔、留用、培养、关怀、考核工作，通过团队拿到结果；\n3. 过程管理：销售日常数据分析及监控，夯实销售过程\n4. 培训管理：不定期开展团队销售技巧培训、产品知识及情景演练，快速提升销售水平\n5. 团队建设：营造积极向上的竞争环境，适度开展团建，保持团队稳定性\n\n岗位基本要求\n1. 一年以上销售管理经验；\n2. 热爱销售，对互联网公司兴趣强烈；\n3. 注重长远职业发展，有强烈的晋升欲望；\n4. 学习能力强且勤奋努力，吃苦耐劳，执行力强，有较强的进取心;\n5. 精力充沛，具备在压力下出色完成任务的能力。\n\n岗位亮点\n业务发展空间大，行业场景好，成长快，工作氛围好","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4630338149","sourceKey":"meituan_social","company":"美团","title":"小象超市-水果基地品质管理","city":"北京市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4630338149&jobShareType=1","duty":"岗位职责:\n1.负责生鲜产地初级农产品的采收、暂存、装车、运输等工作的全程品控管理；\n2.对生鲜种殖基地的采收涉及产品的标准要求进行培训和采后全过程技术输出、监督指导；\n3.有计划及重点地监控生鲜基地种殖产品的食品安全工作，确保采收产品的安全性；\n4.协调合作方确保产品符合采收标准和采收数量、质量等要求，及时完成订单产品发货；\n5.对产地基地源头发现的品质波动，及时与部门内各团队沟通协调，确保上下游标准统一；\n6.及时准确地向上级汇报基地采购产品的相关信息，积极配合领导安排的相关工作。","requirements":"1、可适应全国高频出差；\n2、大专及以上学历，农学、园艺或食品相关专业；\n3、3年及以上生鲜互联网或零售行业品质管理或传统食品加工制造业的品质管理或蔬果方面种植或采销专家；\n4、具备较强的执行力、逻辑分析、业务理解以及沟通能力；\n5、良好的学习能力、团队合作能力。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n岗位职责:\n1.负责生鲜产地初级农产品的采收、暂存、装车、运输等工作的全程品控管理；\n2.对生鲜种殖基地的采收涉及产品的标准要求进行培训和采后全过程技术输出、监督指导；\n3.有计划及重点地监控生鲜基地种殖产品的食品安全工作，确保采收产品的安全性；\n4.协调合作方确保产品符合采收标准和采收数量、质量等要求，及时完成订单产品发货；\n5.对产地基地源头发现的品质波动，及时与部门内各团队沟通协调，确保上下游标准统一；\n6.及时准确地向上级汇报基地采购产品的相关信息，积极配合领导安排的相关工作。\n\n岗位基本要求\n1、可适应全国高频出差；\n2、大专及以上学历，农学、园艺或食品相关专业；\n3、3年及以上生鲜互联网或零售行业品质管理或传统食品加工制造业的品质管理或蔬果方面种植或采销专家；\n4、具备较强的执行力、逻辑分析、业务理解以及沟通能力；\n5、良好的学习能力、团队合作能力。\n\n具备以下条件优先\n独立运营品类，管理供应商经验\n\n岗位亮点\n团队好；成长空间大；全面了解新零售业务的品质管理，深入产地了解商品特性；","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4618209623","sourceKey":"meituan_social","company":"美团","title":"AI基础设施研发","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4618209623&jobShareType=1","duty":"负责 AI 基础设施平台的核心研发，构建高并发、低延迟的 API 网关与业务服务，为开发者提供稳定可靠的 AI 能力接入服务。\n\n设计和实现多供应商资源调度系统，包括加权负载均衡、粘性会话、熔断降级等核心策略，保障服务高可用。\n\n负责精细化计量计费体系的研发，涵盖预扣费/结算/释放三阶段生命周期管理、多渠道支付对接、企业账期对账等，确保资金强一致。\n\n构建系统可观测与安全合规能力，包括全链路调用日志、实时指标采集、内容安全护栏等。\n\n参与系统架构演进，包括管理面与数据面分离部署、独立扩缩容策略、多实例分布式协调等。","requirements":"本科及以上学历，计算机相关专业，3 年以上 Java/Go 后端开发经验。\n\n熟悉 PostgreSQL / MySQL 等关系型数据库，具备良好的数据库设计与 SQL 调优能力。\n\n熟悉 Redis，有基于 Redis 实现分布式限流、分布式锁、缓存策略的实战经验。\n\n具备高并发系统设计能力，了解网关层架构，有 API 鉴权、限流、路由、熔断等实践经验。\n\n有 AI / LLM 相关平台或 API 网关研发经验，了解 OpenAI / Anthropic 等主流大模型 API 协议。\n\n有较强的业务理解能力和系统设计思维。","description":"部门介绍\n基础研发平台是美团的核心技术平台，立足于“零售+科技”的战略定位，通过打造人工智能、大数据、云计算、安全等核心技术能力，以及研发效能平台、企业应用平台等公共服务，为业务提供稳定安全、扩展易用、技术领先的平台技术和产品服务。\n在这里，我们会参与到最前沿的技术研发和探索；能够接触超规模集群、海量数据，挑战高复杂业务场景，有机会与业界一流的工程师一起并肩前行。\n在这里，我们有超强的技术氛围，持续向社区贡献业界实践，加速行业技术发展；我们有完善的互联网学习生态圈，重视底层逻辑和方法论，助力职业生涯的非线性成长。\n真诚地邀请你，和我们一起驱动技术发展，创造行业价值。\n\n岗位职责\n负责 AI 基础设施平台的核心研发，构建高并发、低延迟的 API 网关与业务服务，为开发者提供稳定可靠的 AI 能力接入服务。\n\n设计和实现多供应商资源调度系统，包括加权负载均衡、粘性会话、熔断降级等核心策略，保障服务高可用。\n\n负责精细化计量计费体系的研发，涵盖预扣费/结算/释放三阶段生命周期管理、多渠道支付对接、企业账期对账等，确保资金强一致。\n\n构建系统可观测与安全合规能力，包括全链路调用日志、实时指标采集、内容安全护栏等。\n\n参与系统架构演进，包括管理面与数据面分离部署、独立扩缩容策略、多实例分布式协调等。\n\n岗位基本要求\n本科及以上学历，计算机相关专业，3 年以上 Java/Go 后端开发经验。\n\n熟悉 PostgreSQL / MySQL 等关系型数据库，具备良好的数据库设计与 SQL 调优能力。\n\n熟悉 Redis，有基于 Redis 实现分布式限流、分布式锁、缓存策略的实战经验。\n\n具备高并发系统设计能力，了解网关层架构，有 API 鉴权、限流、路由、熔断等实践经验。\n\n有 AI / LLM 相关平台或 API 网关研发经验，了解 OpenAI / Anthropic 等主流大模型 API 协议。\n\n有较强的业务理解能力和系统设计思维。\n\n岗位亮点\n我们正在构建新一代 AI 基础设施平台，服务全球开发者和企业客户。你将作为核心开发获得从 0 到 1 构建企业级平台的完整经历。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4158155579","sourceKey":"meituan_social","company":"美团","title":"数据挖掘工程师","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4158155579&jobShareType=1","duty":"岗位职责：\n\n1.使用各类数据挖掘技术及机器学习算法以及大模型等前沿技术，基于海量多模态行为数据，构建完整的用户画像与兴趣建模体系，精准刻画用户行为。\n\n2.结合对业务理解，深入挖掘数据价值，将业务问题转化为可建模的算法问题并推动在业务场景下应用，拿到业务结果。\n\n3.深入思考产品业务价值，参与制定及落实团队在技术、业务等多维度发展方向。\n\n4.深入理解食杂零售餐饮供应链业务逻辑和运营模式，与业务、产品、工程、数据等团队紧密协同，完成从业务问题到算法问题的抽象与定义，设计指标体系，进行算法技术选型和方案设计实现，推动落地应用。","requirements":"1.拥有计算机、电子、通信、数学、统计学或相关专业的本科及以上学历，具备3年及以上工作经验。\n\n2.扎实的代码能力和数据结构基础，熟悉常见的机器学习算法，在大规模深度学习、数据挖掘、因果推断等算法能力有实际研发经验。\n\n3.熟练使用大数据工具，熟悉主流深度学习框架。\n\n4.对零售、电商及供应链领域有热情，持续关注行业发展趋势，能主动思考业务模式与技术结合的创新点，具备良好的业务洞察力和数据分析能力。\n\n5.具备出色的问题分析和解决能力，具有团队合作意识，对具有挑战性的问题充满激情。","description":"部门介绍\n美团的使命是“帮大家吃得更好，生活更好”，公司聚焦“零售 + 科技”战略，和广大商户与各类合作伙伴一起，努力为消费者提供品质生活，推动商品零售和服务零售在需求侧和供给侧的数字化转型。\n2018年9月20日，美团正式在港交所挂牌上市。美团将始终坚持以客户为中心，不断加大在科技研发方面的投入，更好承担社会责任，更多创造社会价值，与广大合作伙伴一起发展共赢。\n\n岗位职责\n岗位职责：\n\n1.使用各类数据挖掘技术及机器学习算法以及大模型等前沿技术，基于海量多模态行为数据，构建完整的用户画像与兴趣建模体系，精准刻画用户行为。\n\n2.结合对业务理解，深入挖掘数据价值，将业务问题转化为可建模的算法问题并推动在业务场景下应用，拿到业务结果。\n\n3.深入思考产品业务价值，参与制定及落实团队在技术、业务等多维度发展方向。\n\n4.深入理解食杂零售餐饮供应链业务逻辑和运营模式，与业务、产品、工程、数据等团队紧密协同，完成从业务问题到算法问题的抽象与定义，设计指标体系，进行算法技术选型和方案设计实现，推动落地应用。\n\n岗位基本要求\n1.拥有计算机、电子、通信、数学、统计学或相关专业的本科及以上学历，具备3年及以上工作经验。\n\n2.扎实的代码能力和数据结构基础，熟悉常见的机器学习算法，在大规模深度学习、数据挖掘、因果推断等算法能力有实际研发经验。\n\n3.熟练使用大数据工具，熟悉主流深度学习框架。\n\n4.对零售、电商及供应链领域有热情，持续关注行业发展趋势，能主动思考业务模式与技术结合的创新点，具备良好的业务洞察力和数据分析能力。\n\n5.具备出色的问题分析和解决能力，具有团队合作意识，对具有挑战性的问题充满激情。\n\n具备以下条件优先\n1.有食杂零售、生鲜冻品等数据挖掘算法工作经验，有较强的数据分析和数据工程能力；\n\n2.在国际顶会(如ACL,EMNLP,NACCL,NeurPS等)发表过论文，知名比赛中有优异表现者优先。\n\n岗位亮点\n1、美团坚持“零售+科技”的长期战略定位，零售业务高速发展，目前正处于智能化升级的关键时期，为算法创新和价值落地提供了广阔空间。\n\n2、团队氛围简单、纯粹、务实，有激情，团队成员来自海内外一流高校，鼓励技术交流和创新探索，学习成长机会丰富。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4450789883","sourceKey":"meituan_social","company":"美团","title":"AI应用Builder","city":"上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4450789883&jobShareType=1","duty":"我们在寻找的不是一个执行者，而是一个Builder——能够用AI工具将想法快速变成现实的人。你将：\n1、独立构建 AI 驱动的业务工具与产品原型：结合服务零售业务场景，利用 AI Coding、Agent 、Prompt 、Workflow工程等能力，快速将业务需求转化为可运行的解决方案，缩短从想法到落地的路径；\n2、深度参与 AI 应用探索与落地：在商家运营、用户增长、内容生产、数据分析等方向，主动发现 AI 的应用机会，设计并验证新的业务模式与效率工具；\n3、跨角色协作，打破边界：与多角色团队紧密配合，用 AI 能力弥合角色之间的协作断层，成为团队中能\"连接一切\"的人；\n4、持续学习与输出：紧跟 AI 前沿动态，将模型能力、工具链快速转化为业务价值，并在团队内部沉淀方法论与最佳实践。","requirements":"1、对 AI 技术有真实的热情与动手实践经验，熟悉主流 AI 工具，有独立搭建 Agent、Bot 或自动化工作流的经历；\n2、具备较强的产品感与业务理解力，能够从用户和商家视角出发，定义真实问题，并用 AI 工具快速构建解决方案；\n3、有较强的自驱力与学习能力，能够在模糊环境中独立推进，不依赖完整的需求文档和既定流程；\n4、具备Vibe coding或者AI Coding能力，能够借助 AI 辅助编程完成原型开发或数据处理任务；\n5、良好的沟通与协作能力，善于将复杂的技术方案转化为清晰的业务语言。","description":"部门介绍\n美团服务零售事业部下设乐生活业务部、易生活业务部、进场零售业务部以及中小城市发展部四大业务部门，旨在通过提供丰富、可靠、实惠的服务与商品满足用户各类生活需求。我们所处的服务零售行业是一个具有万亿规模的市场，覆盖足疗洗浴、酒吧KTV、运动健身、美发美甲、教育培训、亲子游乐、家政洗涤维修、摄影写真等数十个服务消费细分领域，同时延伸至超市便利、美妆个护、3C数码、服饰珠宝、运动户外、商场购物中心等实体零售到店消费场景，连接数十万品牌商户与线下门店。作为商家和行业的小帮手，我们持续深入服务零售与实体零售产业链，用AI等技术推动行业变革，帮助商家提升经营效率、实现高效的线上化经营与到店转化，优化消费者服务体验，提供安心、放心的履约保障。这里有着多元的业务布局，有着富有挑战和影响力的工作内容，为你提供丰富的视野、持续的成长和发展机会，引领你发现更多可能。期待和你在“随时随地，美好生活”的愿景指引下，共建美好的生活服务体验、健康的商家生态与高质量的经营结果。\n\n岗位职责\n我们在寻找的不是一个执行者，而是一个Builder——能够用AI工具将想法快速变成现实的人。你将：\n1、独立构建 AI 驱动的业务工具与产品原型：结合服务零售业务场景，利用 AI Coding、Agent 、Prompt 、Workflow工程等能力，快速将业务需求转化为可运行的解决方案，缩短从想法到落地的路径；\n2、深度参与 AI 应用探索与落地：在商家运营、用户增长、内容生产、数据分析等方向，主动发现 AI 的应用机会，设计并验证新的业务模式与效率工具；\n3、跨角色协作，打破边界：与多角色团队紧密配合，用 AI 能力弥合角色之间的协作断层，成为团队中能\"连接一切\"的人；\n4、持续学习与输出：紧跟 AI 前沿动态，将模型能力、工具链快速转化为业务价值，并在团队内部沉淀方法论与最佳实践。\n\n岗位基本要求\n1、对 AI 技术有真实的热情与动手实践经验，熟悉主流 AI 工具，有独立搭建 Agent、Bot 或自动化工作流的经历；\n2、具备较强的产品感与业务理解力，能够从用户和商家视角出发，定义真实问题，并用 AI 工具快速构建解决方案；\n3、有较强的自驱力与学习能力，能够在模糊环境中独立推进，不依赖完整的需求文档和既定流程；\n4、具备Vibe coding或者AI Coding能力，能够借助 AI 辅助编程完成原型开发或数据处理任务；\n5、良好的沟通与协作能力，善于将复杂的技术方案转化为清晰的业务语言。\n\n具备以下条件优先\n1、有在互联网公司 0→1 构建产品或工具的实际经验；\n2、有 Prompt Engineering、RAG、多模态应用等方向的深度实践；\n3、有本地生活、服务零售、电商等行业背景，理解商家与用户的核心诉求；\n4、有个人项目、开源贡献或公开的 AI 应用作品，能够展示你的 Build能力。\n\n岗位亮点\n1、站在 AI 应用的最前沿：你将在一个真实的万亿级业务场景中，探索 AI 改变服务零售行业的无限可能，而不是在沙盒里做实验；\n2、极高的自由度与成长空间：我们鼓励你用 AI 重新定义自己的工作方式，打破岗位边界，成为真正意义上的超级个体；\n3、直接影响业务结果：你的每一个构建，都有机会直接触达数百万商家与用户，产生真实可见的业务价值。","jdComplete":true,"sourceStatus":"000"}];
